# =============================
# Durable journal helpers
# =============================
def _ensure_parent_dir(path_str: str):
    try:
        Path(path_str).expanduser().resolve().parent.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass


def _journal_should_persist(event: str, action: str = "") -> bool:
    if not JOURNAL_ENABLED:
        return False
    event_u = str(event or "").upper()
    action_s = str(action or "").lower()
    if event_u in {"ENTRY", "EXIT", "RECONCILE", "SYSTEM"}:
        return True
    if JOURNAL_PERSIST_SCANS and event_u == "SCAN":
        return True
    if event_u == "SCAN" and action_s in {"candidate_selected", "candidate_ignored_after_selection"}:
        return True
    return action_s in {"error", "rejected"}


def _journal_append(record: dict):
    if not JOURNAL_ENABLED:
        return
    try:
        _ensure_parent_dir(JOURNAL_PATH)
        with open(JOURNAL_PATH, "a", encoding="utf-8") as f:
            f.write(json.dumps(record, separators=(",", ":"), default=str) + "\n")
    except Exception as e:
        logger.warning("JOURNAL_APPEND_FAILED err=%s", e)


def _read_journal(limit: int = 100, event: str = "", symbol: str = "") -> list[dict]:
    path = Path(JOURNAL_PATH)
    if (not JOURNAL_ENABLED) or (not path.exists()):
        return []
    lim = max(1, min(int(limit or 100), 5000))
    event = str(event or "").upper().strip()
    symbol = str(symbol or "").upper().strip()
    rows: list[dict] = []
    try:
        with path.open("r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    row = json.loads(line)
                except Exception:
                    continue
                if event and str(row.get("event", "")).upper() != event:
                    continue
                if symbol and str(row.get("symbol", "")).upper() != symbol:
                    continue
                rows.append(row)
        return rows[-lim:]
    except Exception as e:
        logger.warning("JOURNAL_READ_FAILED err=%s", e)
        return []



def _safe_json_write(path_str: str, payload: dict):
    tmp = None
    try:
        _ensure_parent_dir(path_str)
        path = Path(path_str).expanduser().resolve()
        tmp = path.with_name(f"{path.name}.{os.getpid()}.{threading.get_ident()}.{uuid.uuid4().hex}.tmp")
        tmp.write_text(json.dumps(payload, indent=2, default=str), encoding="utf-8")
        tmp.replace(path)
        return True
    except Exception as e:
        logger.warning("SAFE_JSON_WRITE_FAILED path=%s err=%s", path_str, e)
        try:
            if tmp is not None and tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        return False

def _safe_json_read(path_str: str) -> dict:
    try:
        path = Path(path_str).expanduser().resolve()
        if not path.exists():
            return {}
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception as e:
        logger.warning("SAFE_JSON_READ_FAILED path=%s err=%s", path_str, e)
        return {}


def persist_scan_runtime_state(reason: str = ""):
    payload = {
        "saved_at_utc": datetime.now(timezone.utc).isoformat(),
        "reason": reason,
        "last_scan": dict(LAST_SCAN or {}),
        "last_successful_production_scan": dict(LAST_SUCCESSFUL_PRODUCTION_SCAN or {}),
        "swing_scan_background_completion": dict(SWING_SCAN_BACKGROUND_COMPLETION or {}),
        "spread_blocked_selected_retry_queue": dict(SPREAD_BLOCKED_SELECTED_RETRY_QUEUE or {}),
        "same_day_exit_submit_locks": dict(SAME_DAY_EXIT_SUBMIT_LOCKS or {}),
        "scan_history": list(SCAN_HISTORY or []),
        "candidate_history": list(CANDIDATE_HISTORY or []),
        "last_swing_candidates": list(LAST_SWING_CANDIDATES or []),
    }
    return _safe_json_write(SCAN_STATE_PATH, payload)

def restore_scan_runtime_state() -> dict:
    payload = _safe_json_read(SCAN_STATE_PATH)
    restored = {"path": SCAN_STATE_PATH, "loaded": False, "last_scan_restored": False, "last_successful_production_scan_restored": False, "swing_scan_background_completion_restored": False, "swing_scan_background_lost_after_restart": False, "spread_blocked_retry_queue_restored": False, "same_day_exit_submit_locks_restored": False, "scan_history_restored": 0, "candidate_history_restored": 0, "last_swing_candidates_restored": 0}
    if not payload:
        return restored
    try:
        last_scan = payload.get("last_scan") or {}
        last_successful_production_scan = payload.get("last_successful_production_scan") or {}
        swing_scan_background_completion = payload.get("swing_scan_background_completion") or {}
        spread_blocked_retry_queue = payload.get("spread_blocked_selected_retry_queue") or {}
        same_day_exit_submit_locks = payload.get("same_day_exit_submit_locks") or {}
        scan_history = payload.get("scan_history") or []
        candidate_history = payload.get("candidate_history") or []
        last_swing_candidates = payload.get("last_swing_candidates") or []
        if isinstance(last_scan, dict) and last_scan:
            LAST_SCAN.clear()
            LAST_SCAN.update(last_scan)
            restored["last_scan_restored"] = True
        if isinstance(last_successful_production_scan, dict) and last_successful_production_scan:
            LAST_SUCCESSFUL_PRODUCTION_SCAN.clear()
            LAST_SUCCESSFUL_PRODUCTION_SCAN.update(last_successful_production_scan)
            restored["last_successful_production_scan_restored"] = True
        if isinstance(swing_scan_background_completion, dict) and swing_scan_background_completion:
            restored_bg = dict(swing_scan_background_completion)
            restored_bg["restored_after_restart"] = True
            status_l = str(restored_bg.get("status") or "").strip().lower()
            if status_l in {"accepted", "running"}:
                now_iso = datetime.now(timezone.utc).isoformat()
                restored_bg["status"] = "skipped"
                restored_bg["terminal"] = True
                restored_bg["active"] = False
                restored_bg["reason"] = "background_scan_lost_after_restart_recovered"
                restored_bg["error"] = None
                restored_bg["exception_type"] = None
                restored_bg["completed_utc"] = now_iso
                restored_bg["updated_utc"] = now_iso
                restored_bg["recovered_after_restart"] = True
                restored_bg["recovery_reason"] = "previous_process_background_scan_cannot_resume_next_scan_unlocked"
                restored["swing_scan_background_lost_after_restart"] = True
            SWING_SCAN_BACKGROUND_COMPLETION.clear()
            SWING_SCAN_BACKGROUND_COMPLETION.update(restored_bg)
            restored["swing_scan_background_completion_restored"] = True
        if isinstance(spread_blocked_retry_queue, dict) and spread_blocked_retry_queue:
            SPREAD_BLOCKED_SELECTED_RETRY_QUEUE.clear()
            SPREAD_BLOCKED_SELECTED_RETRY_QUEUE.update(spread_blocked_retry_queue)
            restored["spread_blocked_retry_queue_restored"] = True
        if isinstance(same_day_exit_submit_locks, dict) and same_day_exit_submit_locks:
            SAME_DAY_EXIT_SUBMIT_LOCKS.clear()
            SAME_DAY_EXIT_SUBMIT_LOCKS.update(same_day_exit_submit_locks)
            restored["same_day_exit_submit_locks_restored"] = True
        if isinstance(scan_history, list) and scan_history:
            SCAN_HISTORY.clear()
            SCAN_HISTORY.extend(scan_history[-SCAN_HISTORY_SIZE:])
            restored["scan_history_restored"] = len(SCAN_HISTORY)
        if isinstance(candidate_history, list) and candidate_history:
            CANDIDATE_HISTORY.clear()
            CANDIDATE_HISTORY.extend(candidate_history[-CANDIDATE_HISTORY_SIZE:])
            restored["candidate_history_restored"] = len(CANDIDATE_HISTORY)
        if isinstance(last_swing_candidates, list) and last_swing_candidates:
            LAST_SWING_CANDIDATES.clear()
            LAST_SWING_CANDIDATES.extend([
                dict(row or {})
                for row in last_swing_candidates[:250]
                if isinstance(row, dict)
            ])
            restored["last_swing_candidates_restored"] = len(LAST_SWING_CANDIDATES)
        restored["loaded"] = restored["last_scan_restored"] or restored["last_successful_production_scan_restored"] or bool(restored["spread_blocked_retry_queue_restored"]) or bool(restored["same_day_exit_submit_locks_restored"]) or bool(restored["scan_history_restored"]) or bool(restored["candidate_history_restored"])
    except Exception as e:
        restored["error"] = str(e)
    globals()["SCAN_STATE_RESTORE"] = restored
    return restored

def _p324_scan_selected_symbols(scan: dict | None) -> list[str]:
    scan = dict(scan or {})
    summary = dict(scan.get("summary") or {})
    symbols = []

    for source in (
        summary.get("selected_symbols"),
        scan.get("selected_symbols"),
        summary.get("actual_submit_side_effect_symbols"),
        summary.get("swing_production_reset", {}).get("selected_symbols") if isinstance(summary.get("swing_production_reset"), dict) else [],
    ):
        for sym in list(source or []):
            sym = str(sym or "").strip().upper()
            if sym:
                symbols.append(sym)

    return _dedupe_keep_order(symbols)


def _p324_is_successful_production_scan(scan: dict | None) -> bool:
    scan = dict(scan or {})
    summary = dict(scan.get("summary") or {})
    reason = str(scan.get("reason") or summary.get("scan_reason") or "").strip()

    if reason != "scan_completed":
        return False

    if bool(scan.get("skipped")):
        return False

    selected_symbols = _p324_scan_selected_symbols(scan)
    production = dict(summary.get("swing_production_reset") or {})

    return bool(
        selected_symbols
        or int(summary.get("selected_total") or 0) > 0
        or int(production.get("approved_count") or 0) > 0
    )


def _p324_preserve_successful_production_scan(scan: dict | None, reason: str = "") -> bool:
    scan = dict(scan or {})
    if not _p324_is_successful_production_scan(scan):
        return False

    preserved = dict(scan)
    preserved["preserved_at_utc"] = datetime.now(timezone.utc).isoformat()
    preserved["preserved_reason"] = reason or "successful_production_scan"
    preserved["preserved_selected_symbols"] = _p324_scan_selected_symbols(scan)
    preserved["source"] = "last_successful_production_scan"

    LAST_SUCCESSFUL_PRODUCTION_SCAN.clear()
    LAST_SUCCESSFUL_PRODUCTION_SCAN.update(preserved)
    return True


def _p464_scan_runtime_budget_sec() -> int:
    return max(60, int(SCAN_RUNTIME_BUDGET_SEC or 180))


def _p464_scan_duration_ms(scan: dict | None) -> int:
    scan = dict(scan or {})
    summary = dict(scan.get("summary") or {})
    background = dict(scan.get("scan_background_completion_truth") or summary.get("scan_background_completion_truth") or {})
    for value in (scan.get("duration_ms"), summary.get("duration_ms"), background.get("duration_ms")):
        try:
            if value is not None:
                return int(float(value or 0))
        except Exception:
            continue
    return 0


def _p464_scan_over_runtime_budget(scan: dict | None) -> bool:
    duration_ms = _p464_scan_duration_ms(scan)
    budget_ms = int(_p464_scan_runtime_budget_sec() * 1000)
    return bool(duration_ms > budget_ms)

def _p475_scan_candidate_bearing_truth(scan: dict | None) -> dict:
    scan = dict(scan or {})
    summary = dict(scan.get("summary") or {})
    incremental = dict(summary.get("incremental_scan") or {})
    evaluation = dict(incremental.get("evaluation") or {})

    symbols_eval_total = int(
        summary.get("symbols_eval_total")
        or evaluation.get("evaluated_count")
        or scan.get("scanned")
        or 0
    )
    candidates_total = int(summary.get("candidates_total") or 0)
    eligible_total = int(summary.get("eligible_total") or scan.get("eligible_total") or 0)
    selected_total = int(summary.get("selected_total") or scan.get("selected_total") or 0)

    has_candidate_rows = bool(
        summary.get("top_candidates")
        or summary.get("top_rejection_reasons")
        or summary.get("rejection_counts")
    )

    candidate_bearing = bool(
        symbols_eval_total > 0
        or candidates_total > 0
        or eligible_total > 0
        or selected_total > 0
        or has_candidate_rows
    )

    phase = str(summary.get("scan_truth_phase") or "").strip()
    regime_only = bool(
        phase in {
            "regime_to_candidate_fast_publish",
            "regime_truth_only_before_candidate_eval",
        }
        or summary.get("p474_regime_fast_publish")
        or summary.get("p470_regime_budget_close")
        or (
            int(scan.get("scanned") or 0) <= 0
            and symbols_eval_total <= 0
            and not has_candidate_rows
        )
    )

    return {
        "candidate_bearing": candidate_bearing,
        "trade_judgable": bool(candidate_bearing and not regime_only),
        "regime_only_non_actionable": bool(regime_only and not candidate_bearing),
        "symbols_eval_total": symbols_eval_total,
        "candidates_total": candidates_total,
        "eligible_total": eligible_total,
        "selected_total": selected_total,
        "has_candidate_rows": has_candidate_rows,
        "scan_truth_phase": phase or None,
    }


def _p475_normalize_scan_truth_contract(scan: dict | None, source: str = "") -> dict:
    row = dict(scan or {})
    if not row:
        return row

    summary = dict(row.get("summary") or {})
    truth = _p475_scan_candidate_bearing_truth(row)

    row["candidate_bearing_scan"] = bool(truth.get("candidate_bearing"))
    row["trade_judgable"] = bool(truth.get("trade_judgable"))
    row["regime_only_non_actionable"] = bool(truth.get("regime_only_non_actionable"))
    row["p475_scan_truth_contract"] = dict(truth)
    row["p475_scan_truth_source"] = source or "scan_truth_contract"

    summary["candidate_bearing_scan"] = bool(truth.get("candidate_bearing"))
    summary["trade_judgable"] = bool(truth.get("trade_judgable"))
    summary["regime_only_non_actionable"] = bool(truth.get("regime_only_non_actionable"))
    summary["p475_scan_truth_contract"] = dict(truth)

    reason = str(row.get("reason") or summary.get("scan_reason") or "").strip()
    if bool(truth.get("regime_only_non_actionable")):
        if reason in {"scan_completed", "partial_scan_completed", ""}:
            row["reason_before_p475_contract"] = reason or None
            row["reason"] = "regime_only_non_actionable"
        if str(summary.get("scan_reason") or "") in {"scan_completed", "partial_scan_completed", ""}:
            summary["scan_reason_before_p475_contract"] = summary.get("scan_reason") or None
            summary["scan_reason"] = "regime_only_non_actionable"

    row["summary"] = summary
    return row


def _p473_scan_has_atomic_candidate_truth(scan: dict | None) -> bool:
    scan = dict(scan or {})
    summary = dict(scan.get("summary") or {})

    published = bool(
        scan.get("p468_candidate_truth_published")
        or summary.get("candidate_truth_published_before_reports")
        or summary.get("p468_candidate_truth_published")
        or summary.get("scan_truth_phase") == "candidate_truth_before_heavy_reports"
    )

    truth = _p475_scan_candidate_bearing_truth(scan)
    return bool(published and truth.get("candidate_bearing"))


def _p473_accept_over_budget_candidate_truth(scan: dict | None, source: str = "") -> dict:
    row = dict(scan or {})
    if not row:
        return row

    if not _p473_scan_has_atomic_candidate_truth(row):
        return row

    duration_ms = _p464_scan_duration_ms(row)
    budget_ms = int(_p464_scan_runtime_budget_sec() * 1000)
    if duration_ms <= budget_ms:
        return row

    summary = dict(row.get("summary") or {})
    background = dict(row.get("scan_background_completion_truth") or summary.get("scan_background_completion_truth") or {})
    existing_reason = str(row.get("reason") or summary.get("scan_reason") or "").strip()
    accepted_reason = "partial_scan_completed" if bool((summary.get("incremental_scan") or {}).get("partial_scan")) else "scan_completed"

    if existing_reason in {"scan_completed", "partial_scan_completed", "scan_runtime_budget_exceeded", "background_scan_runtime_budget_exceeded", ""}:
        row["reason"] = accepted_reason

    row["p473_over_budget_candidate_truth_accepted"] = True
    row["p473_over_budget_candidate_truth_source"] = source or "candidate_truth_atomic_publish"
    row["runtime_budget_sanitized"] = False
    row["runtime_budget_ms"] = budget_ms
    row["duration_ms"] = duration_ms
    row["actionable_for_diagnostics"] = True
    row["fresh_but_over_budget"] = False

    if str(row.get("exception_type") or "") == "BackgroundScanRuntimeBudgetExceeded":
        row["exception_type"] = None
    if str(row.get("error") or "").lower().strip() in {
        "persisted scan exceeded runtime budget",
        "background scan exceeded runtime budget",
    }:
        row["error"] = None

    summary["scan_reason"] = row.get("reason")
    summary["p473_over_budget_candidate_truth_accepted"] = True
    summary["runtime_budget_ms"] = budget_ms
    summary["duration_ms"] = duration_ms
    summary["actionable_for_diagnostics"] = True
    summary["fresh_but_over_budget"] = False

    if background:
        background["status"] = "completed"
        background["active"] = False
        background["terminal"] = True
        background["reason"] = row.get("reason")
        background["duration_ms"] = duration_ms
        background["runtime_budget_ms"] = budget_ms
        background["p473_over_budget_candidate_truth_accepted"] = True
        if str(background.get("exception_type") or "") == "BackgroundScanRuntimeBudgetExceeded":
            background["exception_type"] = None
        if str(background.get("error") or "").lower().strip() in {
            "persisted background scan exceeded runtime budget",
            "background scan exceeded runtime budget",
        }:
            background["error"] = None
        row["scan_background_completion_truth"] = background
        summary["scan_background_completion_truth"] = background

    row["summary"] = summary
    return row

def _p464_sanitize_persisted_over_budget_scan(scan: dict | None, source: str = "") -> dict:
    row = dict(scan or {})
    if not row:
        return row

    row = _p475_normalize_scan_truth_contract(row, source=source or "p464_sanitize")
    summary = dict(row.get("summary") or {})
    background = dict(row.get("scan_background_completion_truth") or summary.get("scan_background_completion_truth") or {})
    duration_ms = _p464_scan_duration_ms(row)
    budget_ms = int(_p464_scan_runtime_budget_sec() * 1000)
    over_budget = bool(duration_ms > budget_ms)

    if over_budget:
        accepted = _p473_accept_over_budget_candidate_truth(row, source=source or "p464_sanitize")
        if bool(accepted.get("p473_over_budget_candidate_truth_accepted")):
            return accepted

    if not over_budget:
        return row

    reason = str(row.get("reason") or summary.get("scan_reason") or "").strip()
    row["runtime_budget_sanitized"] = True
    row["runtime_budget_sanitized_source"] = source or "p464_hotfix"
    row["runtime_budget_sanitized_at_utc"] = datetime.now(timezone.utc).isoformat()
    row["runtime_budget_ms"] = budget_ms
    row["duration_ms"] = duration_ms
    row["reason_before_runtime_budget_sanitize"] = reason
    row["reason"] = "scan_runtime_budget_exceeded"
    row["error"] = row.get("error") or "persisted scan exceeded runtime budget"
    row["exception_type"] = row.get("exception_type") or "BackgroundScanRuntimeBudgetExceeded"
    row["fresh_but_over_budget"] = True
    row["actionable_for_diagnostics"] = True

    summary["runtime_budget_sanitized"] = True
    summary["runtime_budget_ms"] = budget_ms
    summary["duration_ms"] = duration_ms
    summary["scan_reason_before_runtime_budget_sanitize"] = reason
    summary["scan_reason"] = "scan_runtime_budget_exceeded"
    summary["fresh_but_over_budget"] = True
    summary["actionable_for_diagnostics"] = True
    row["summary"] = summary

    if background:
        background["runtime_budget_sanitized"] = True
        background["runtime_budget_ms"] = budget_ms
        background["duration_ms"] = duration_ms
        background["reason_before_runtime_budget_sanitize"] = background.get("reason")
        background["reason"] = "background_scan_runtime_budget_exceeded"
        background["status"] = "failed"
        background["active"] = False
        background["terminal"] = True
        background["exception_type"] = background.get("exception_type") or "BackgroundScanRuntimeBudgetExceeded"
        background["error"] = background.get("error") or "persisted background scan exceeded runtime budget"
        row["scan_background_completion_truth"] = background
        summary["scan_background_completion_truth"] = background
        row["summary"] = summary

    return row


def _p464_is_actionable_market_scan(scan: dict | None) -> bool:
    scan = _p464_sanitize_persisted_over_budget_scan(scan, source="actionable_market_scan_check")
    summary = dict(scan.get("summary") or {})
    reason = str(scan.get("reason") or summary.get("scan_reason") or "").strip()

    truth = _p475_scan_candidate_bearing_truth(scan)
    if not bool(truth.get("trade_judgable")):
        return False

    if reason not in {"scan_completed", "partial_scan_completed"}:
        if reason == "scan_runtime_budget_exceeded" and bool(scan.get("actionable_for_diagnostics")):
            return bool(truth.get("candidate_bearing"))
        return False
    if _p464_scan_over_runtime_budget(scan) and not bool(scan.get("actionable_for_diagnostics")):
        return False
    if bool(scan.get("skipped")) or bool(summary.get("skipped")) or summary.get("skip_reason"):
        return False
    if str(scan.get("exception_type") or "").strip():
        return False

    return bool(truth.get("candidate_bearing"))


def _p464_preserve_actionable_market_scan(scan: dict | None, reason: str = "") -> bool:
    scan = _p473_accept_over_budget_candidate_truth(dict(scan or {}), source="preserve_actionable_market_scan")
    if not _p464_is_actionable_market_scan(scan):
        return False

    preserved = dict(scan)
    preserved["preserved_at_utc"] = datetime.now(timezone.utc).isoformat()
    preserved["preserved_reason"] = reason or "actionable_market_scan"
    preserved["source"] = "last_actionable_market_scan"

    LAST_ACTIONABLE_MARKET_SCAN.clear()
    LAST_ACTIONABLE_MARKET_SCAN.update(preserved)
    return True

def _p464_effective_market_scan(scan: dict | None = None) -> dict:
    canonical = _p481_canonical_scan_truth(scan)
    effective = dict(canonical.get("effective_trade_scan") or {})
    contract = dict(canonical.get("contract") or {})

    effective["_scan_source"] = contract.get("effective_scan_source") or effective.get("_scan_source") or "last_scan"
    effective["_p480_effective_scan_source"] = effective["_scan_source"]
    effective["_p480_after_hours_skip_preserved"] = bool(contract.get("after_hours_does_not_replace_candidate_truth"))
    effective["_p480_preserved_scan_available"] = bool(contract.get("last_candidate_bearing_scan", {}).get("candidate_bearing"))
    effective["_p480_preserved_scan_trade_judgable"] = bool(contract.get("last_candidate_bearing_scan", {}).get("trade_judgable"))
    effective["_p480_raw_latest_scan"] = dict(contract.get("raw_latest_scan") or {})
    effective["_p481_canonical_scan_truth"] = contract
    return effective

def _p481_scan_brief(scan: dict | None) -> dict:
    scan = dict(scan or {})
    truth = _p475_scan_candidate_bearing_truth(scan)
    return swing_scan_state_build_scan_brief(scan, truth)

def _p481_fast_payload_scan_fallback(limit: int = 25) -> dict:
    global P481_FAST_PAYLOAD_ADOPTION_IN_PROGRESS

    if bool(P481_FAST_PAYLOAD_ADOPTION_IN_PROGRESS):
        return {}

    P481_FAST_PAYLOAD_ADOPTION_IN_PROGRESS = True
    try:
        payload = _p406_fast_current_candidate_payload(limit=max(1, min(int(limit or 25), 100)))
    except Exception as exc:
        return {
            "p481_fast_payload_error": str(exc),
            "_scan_source": "fast_payload_unavailable",
        }
    finally:
        P481_FAST_PAYLOAD_ADOPTION_IN_PROGRESS = False

    rows = [
        dict(row or {})
        for row in list(
            payload.get("candidate_rows")
            or payload.get("top_candidates")
            or payload.get("top_new_entry_candidates")
            or []
        )
        if isinstance(row, dict)
    ]
    if not rows:
        return {}

    candidates_total = int(payload.get("candidate_count") or len(rows) or 0)
    eligible_total = int(payload.get("eligible_count") or 0)
    selected_total = int(payload.get("selected_total") or 0)
    selected_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(payload.get("selected_symbols") or [])
        if str(sym or "").strip()
    ])

    if candidates_total <= 0 and eligible_total <= 0 and selected_total <= 0:
        return {}

    latest = dict(payload.get("latest_scan") or LAST_SCAN or {})
    raw_latest_reason = str(latest.get("reason") or "").strip()
    scan = {
        "ts_utc": latest.get("ts_utc"),
        "reason": "fast_payload_candidate_fallback",
        "raw_latest_reason": raw_latest_reason or None,
        "_scan_source": "fast_current_candidate_payload",
        "source": "fast_current_candidate_payload",
        "scanned": latest.get("scanned"),
        "signals": latest.get("signals"),
        "would_trade": latest.get("would_trade"),
        "blocked": latest.get("blocked"),
        "duration_ms": latest.get("duration_ms"),
        "summary": {
            "scan_truth_phase": "fast_payload_candidate_fallback",
            "candidate_cache_adopted": True,
            "candidate_cache_source": str(payload.get("source") or "fast_current_candidate_payload"),
            "p519_full_candidate_cache_adopted": bool(payload.get("p519_full_candidate_cache_adopted")),
            "p519_full_candidate_cache_source": payload.get("p519_full_candidate_cache_source"),
            "raw_latest_reason": raw_latest_reason or None,
            "effective_reason_normalized": True,
            "fast_payload_status": payload.get("status"),
            "fast_payload_recommended_action": payload.get("recommended_action"),
            "symbols_eval_total": int((payload.get("runtime_universe_coverage") or {}).get("scanned_symbol_count") or latest.get("scanned") or 0),
            "candidates_total": candidates_total,
            "eligible_total": eligible_total,
            "selected_total": selected_total,
            "selected_symbols": selected_symbols,
            "reason_counts": dict(payload.get("reason_counts") or {}),
            "reason_family_counts": dict(payload.get("reason_family_counts") or {}),
            "candidates": rows,
            "top_candidates": rows[:25],
        },
    }
    return _p475_normalize_scan_truth_contract(scan, source="fast_payload_candidate_fallback")

def _p481_candidate_cache_scan_fallback() -> dict:
    rows = [
        dict(row or {})
        for row in list(LAST_SWING_CANDIDATES or [])
        if isinstance(row, dict)
    ]
    if not rows:
        return {}

    rows = _p412_rebuild_current_candidate_contract_rows(rows)
    candidates_total = len(rows)
    eligible_total = len([row for row in rows if bool(row.get("eligible"))])
    selected_total = len([row for row in rows if bool(row.get("selected"))])
    selected_symbols = _dedupe_keep_order([
        str((row or {}).get("symbol") or "").strip().upper()
        for row in rows
        if bool((row or {}).get("selected"))
        and str((row or {}).get("symbol") or "").strip()
    ])

    if candidates_total <= 0 and eligible_total <= 0 and selected_total <= 0:
        return {}

    latest = dict(LAST_SCAN or {})
    latest_summary = dict(latest.get("summary") or {})
    raw_latest_reason = str(latest_summary.get("scan_reason") or latest.get("reason") or "").strip()
    scan = {
        "ts_utc": latest.get("ts_utc"),
        "reason": "candidate_cache_fallback",
        "raw_latest_reason": raw_latest_reason or None,
        "_scan_source": "last_swing_candidates_memory",
        "source": "last_swing_candidates_memory",
        "scanned": latest_summary.get("symbols_eval_total") or latest.get("scanned"),
        "signals": latest.get("signals"),
        "would_trade": latest.get("would_trade"),
        "blocked": latest.get("blocked"),
        "duration_ms": latest.get("duration_ms"),
        "summary": {
            "scan_truth_phase": "candidate_cache_fallback",
            "candidate_cache_adopted": True,
            "candidate_cache_source": "last_swing_candidates_memory",
            "raw_latest_reason": raw_latest_reason or None,
            "effective_reason_normalized": True,
            "symbols_eval_total": int(latest_summary.get("symbols_eval_total") or latest.get("scanned") or 0),
            "candidates_total": candidates_total,
            "eligible_total": eligible_total,
            "selected_total": selected_total,
            "selected_symbols": selected_symbols,
            "top_candidates": rows[:25],
        },
    }
    return _p475_normalize_scan_truth_contract(scan, source="candidate_cache_fallback")

def _p481_candidate_history_scan_fallback() -> dict:
    if not CANDIDATE_HISTORY:
        return {}

    latest_candidate = dict((CANDIDATE_HISTORY or [])[-1] or {})
    summary = dict(latest_candidate.get("summary") or latest_candidate or {})
    rows = list(summary.get("top_candidates") or summary.get("items") or summary.get("rows") or [])

    candidates_total = int(summary.get("candidates_total") or len(rows) or 0)
    eligible_total = int(summary.get("eligible_total") or len([r for r in rows if bool((r or {}).get("eligible"))]) or 0)
    selected_total = int(summary.get("selected_total") or len([r for r in rows if bool((r or {}).get("selected"))]) or 0)

    if candidates_total <= 0 and eligible_total <= 0 and selected_total <= 0:
        return {}

    scan = {
        "ts_utc": latest_candidate.get("ts_utc") or latest_candidate.get("scan_ts_utc") or latest_candidate.get("generated_utc"),
        "reason": summary.get("scan_reason") or latest_candidate.get("reason") or "candidate_history_fallback",
        "_scan_source": "candidate_history",
        "source": "candidate_history",
        "scanned": summary.get("symbols_eval_total") or summary.get("scanned"),
        "signals": summary.get("signals"),
        "would_trade": summary.get("would_trade"),
        "blocked": summary.get("blocked"),
        "duration_ms": summary.get("duration_ms") or latest_candidate.get("duration_ms"),
        "summary": {
            **summary,
            "scan_truth_phase": summary.get("scan_truth_phase") or "candidate_history_fallback",
            "candidates_total": candidates_total,
            "eligible_total": eligible_total,
            "selected_total": selected_total,
            "top_candidates": rows[:25],
        },
    }
    return _p475_normalize_scan_truth_contract(scan, source="candidate_history_fallback")


def _p481_last_candidate_bearing_scan() -> dict:
    candidates = []

    if LAST_ACTIONABLE_MARKET_SCAN:
        row = dict(LAST_ACTIONABLE_MARKET_SCAN or {})
        row["_scan_source"] = row.get("_scan_source") or "last_actionable_market_scan"
        candidates.append(row)

    completed = _latest_completed_scan_record()
    if completed:
        completed = dict(completed)
        completed["_scan_source"] = completed.get("_scan_source") or "latest_completed_scan"
        candidates.append(completed)

    fast_payload_fallback = _p481_fast_payload_scan_fallback(limit=25)
    if fast_payload_fallback and not fast_payload_fallback.get("p481_fast_payload_error"):
        candidates.append(fast_payload_fallback)

    cache_fallback = _p481_candidate_cache_scan_fallback()
    if cache_fallback:
        candidates.append(cache_fallback)

    history_fallback = _p481_candidate_history_scan_fallback()
    if history_fallback:
        candidates.append(history_fallback)

    for row in candidates:
        row = _p464_sanitize_persisted_over_budget_scan(dict(row or {}), source="p481_last_candidate_bearing_scan")
        row = _p475_normalize_scan_truth_contract(row, source="p481_last_candidate_bearing_scan")
        truth = _p475_scan_candidate_bearing_truth(row)
        if bool(truth.get("candidate_bearing")):
            return row

    return {}

def _p481_canonical_scan_truth(raw_scan: dict | None = None) -> dict:
    raw = _p464_sanitize_persisted_over_budget_scan(
        dict(raw_scan or LAST_SCAN or {}),
        source="p481_raw_latest_scan",
    )
    raw = _p475_normalize_scan_truth_contract(raw, source="p481_raw_latest_scan")
    raw_summary = dict(raw.get("summary") or {})
    raw_reason = str(raw.get("reason") or raw_summary.get("scan_reason") or "").strip()
    raw_truth = _p475_scan_candidate_bearing_truth(raw)

    last_candidate = _p481_last_candidate_bearing_scan()
    candidate_truth = _p475_scan_candidate_bearing_truth(last_candidate) if last_candidate else {}

    raw_is_skip = bool(
        raw.get("skipped")
        or raw_summary.get("skipped")
        or raw_summary.get("skip_reason")
        or raw_reason in {"outside_market_hours", "outside_scanner_session", "scanner_disabled"}
    )

    use_candidate = bool(
        last_candidate
        and bool(candidate_truth.get("candidate_bearing"))
        and (
            raw_is_skip
            or not bool(raw_truth.get("trade_judgable"))
        )
    )

    effective = dict(last_candidate if use_candidate else raw)
    effective["_scan_source"] = (
        last_candidate.get("_scan_source")
        if use_candidate
        else raw.get("_scan_source") or "last_scan"
    )
    effective["_p481_canonical_effective"] = True
    effective["_p481_after_hours_does_not_replace_candidate_truth"] = bool(
        use_candidate and raw_reason == "outside_market_hours"
    )
    effective["_p481_raw_latest_scan"] = _p481_scan_brief(raw)
    effective["_p481_last_candidate_bearing_scan"] = _p481_scan_brief(last_candidate)
    effective["_p481_effective_trade_scan"] = _p481_scan_brief(effective)

    contract = swing_scan_state_build_canonical_scan_contract(
        raw_latest_scan=_p481_scan_brief(raw),
        last_candidate_bearing_scan=_p481_scan_brief(last_candidate),
        effective_trade_scan=_p481_scan_brief(effective),
        after_hours_does_not_replace_candidate_truth=bool(use_candidate and raw_reason == "outside_market_hours"),
        effective_scan_source=effective.get("_scan_source"),
        candidate_cache_adopted=bool((effective.get("summary") or {}).get("candidate_cache_adopted")),
        candidate_cache_source=(effective.get("summary") or {}).get("candidate_cache_source"),
        used_candidate_bearing_fallback=bool(use_candidate),
        raw_latest_reason=raw_reason,
    )

    return {
        "raw_latest_scan": raw,
        "last_candidate_bearing_scan": last_candidate,
        "effective_trade_scan": effective,
        "contract": contract,
    }

class SwingScanRuntimeBudgetExceeded(RuntimeError):
    pass

def _p324_backfill_successful_production_scan_from_active_plans(reason: str = "") -> dict:
    rows = []
    selected_symbols = []

    for sym, plan in sorted(dict(TRADE_PLAN or {}).items()):
        if not isinstance(plan, dict):
            continue

        symbol = str(plan.get("symbol") or sym or "").strip().upper()
        if not symbol:
            continue

        if not bool(plan.get("active")):
            continue

        source = str(plan.get("source") or (plan.get("thesis") or {}).get("selected_source") or "").strip()
        entry_type = str(plan.get("entry_type") or (plan.get("thesis") or {}).get("entry_type") or "").strip()

        if source != "swing_production_reset" and entry_type != "swing_production_contract":
            continue

        selected_symbols.append(symbol)
        rows.append({
            "symbol": symbol,
            "strategy": plan.get("strategy_name") or plan.get("signal") or "daily_breakout",
            "signal": plan.get("signal") or "daily_breakout",
            "selected": True,
            "eligible": True,
            "entry_type": entry_type or "swing_production_contract",
            "selected_source": source or "swing_production_reset",
            "rank_score": plan.get("rank_score") or (plan.get("thesis") or {}).get("candidate_rank_score"),
            "selection_quality_score": plan.get("selection_quality_score") or (plan.get("thesis") or {}).get("selection_quality_score"),
            "estimated_qty": plan.get("qty") or plan.get("requested_qty"),
            "entry_price": plan.get("entry_price"),
            "stop_price": plan.get("stop_price"),
            "target_price": plan.get("take_price") or plan.get("target_price"),
            "opened_at": plan.get("opened_at"),
            "source": source or "swing_production_reset",
        })

    selected_symbols = _dedupe_keep_order(selected_symbols)

    if not selected_symbols:
        return {
            "backfilled": False,
            "reason": "no_active_swing_production_reset_plans",
            "selected_symbols": [],
        }

    now_utc = datetime.now(timezone.utc).isoformat()
    preserved = {
        "ts_utc": now_utc,
        "ts_ny": now_ny().isoformat(),
        "reason": "scan_completed",
        "preserved_at_utc": now_utc,
        "preserved_reason": reason or "active_plan_backfill",
        "source": "active_plan_backfill",
        "selected_symbols": selected_symbols,
        "scanned": 0,
        "signals": len(selected_symbols),
        "would_trade": len(selected_symbols),
        "blocked": 0,
        "summary": {
            "scan_reason": "active_plan_backfill",
            "selected_total": len(selected_symbols),
            "selected_symbols": selected_symbols,
            "eligible_total": len(selected_symbols),
            "top_candidates": rows,
            "selected_submission_rows": [
                {
                    "symbol": row.get("symbol"),
                    "actual_submit_side_effect": True,
                    "submit_state": "filled",
                    "submit_reason": "active_plan_backfill",
                    "entry_type": row.get("entry_type"),
                    "source": row.get("source"),
                }
                for row in rows
            ],
            "actual_submit_side_effect_symbols": selected_symbols,
            "selected_submit_gap_symbols": [],
            "selected_submit_gap_count": 0,
            "selected_submit_gap_active": False,
            "swing_production_reset": {
                "enabled": bool(SWING_PRODUCTION_RESET_ENABLED),
                "contract": "single_entry_contract",
                "legacy_gate_mode": "diagnostic_only" if bool(SWING_PRODUCTION_RESET_ENABLED) else "legacy_live",
                "approved_count": len(selected_symbols),
                "approved_symbols": selected_symbols,
                "selected_symbols": selected_symbols,
                "backfilled_from_active_plans": True,
            },
        },
    }

    LAST_SUCCESSFUL_PRODUCTION_SCAN.clear()
    LAST_SUCCESSFUL_PRODUCTION_SCAN.update(preserved)

    try:
        persist_scan_runtime_state(reason="p324_active_plan_backfill")
    except Exception:
        pass

    return {
        "backfilled": True,
        "reason": reason or "active_plan_backfill",
        "selected_symbols": selected_symbols,
        "row_count": len(rows),
    }

def _p324_latest_scan_exception_truth() -> dict:
    latest = dict(LAST_SCAN or {})
    if not LAST_SUCCESSFUL_PRODUCTION_SCAN:
        try:
            _p324_backfill_successful_production_scan_from_active_plans(
                reason="exception_truth_backfill"
            )
        except Exception:
            pass
    reason = str(latest.get("reason") or "").strip()
    if reason != "scan_exception":
        return {
            "active": False,
            "reason": reason or None,
        }

    return {
        "active": True,
        "reason": "scan_exception",
        "ts_utc": latest.get("ts_utc"),
        "duration_ms": latest.get("duration_ms"),
        "error": latest.get("error"),
        "scanned": latest.get("scanned"),
        "signals": latest.get("signals"),
        "would_trade": latest.get("would_trade"),
        "blocked": latest.get("blocked"),
        "preserved_scan_available": bool(LAST_SUCCESSFUL_PRODUCTION_SCAN),
        "preserved_selected_symbols": _p324_scan_selected_symbols(LAST_SUCCESSFUL_PRODUCTION_SCAN),
    }

def _p324_effective_latest_scan_for_light() -> tuple[dict, dict]:
    raw_last_scan = dict(LAST_SCAN or {})
    latest_scan = _p464_effective_market_scan(raw_last_scan)
    latest_summary = dict(latest_scan.get("summary") or {})
    exception_truth = _p324_latest_scan_exception_truth()
    if latest_scan is not raw_last_scan and latest_scan.get("_scan_source") == "last_actionable_market_scan":
        latest_summary["using_last_actionable_market_scan"] = True
        latest_summary["last_scan_replaced_reason"] = raw_last_scan.get("reason")

    if exception_truth.get("active"):
        preserved = dict(LAST_SUCCESSFUL_PRODUCTION_SCAN or {})
        preserved_summary = dict(preserved.get("summary") or {})
        preserved_symbols = _p324_scan_selected_symbols(preserved)

        latest_scan["current_scan_failed"] = True
        latest_scan["using_last_successful_production_scan"] = False
        latest_scan["scanner_exception_truth"] = exception_truth
        latest_scan["preserved_scan_available"] = bool(preserved)
        latest_scan["preserved_selected_symbols"] = preserved_symbols

        current_summary = dict(latest_summary or {})
        current_summary.update({
            "scanner_exception_truth": exception_truth,
            "current_scan_failed": True,
            "current_scan_truth": "failed_current_scan",
            "using_last_successful_production_scan": False,
            "last_successful_production_scan_available": bool(preserved),
            "last_successful_production_selected_symbols": preserved_symbols,
            "preserved_scan_reference": {
                "available": bool(preserved),
                "ts_utc": preserved.get("ts_utc"),
                "reason": preserved.get("reason"),
                "selected_symbols": preserved_symbols,
                "selected_total": int(preserved_summary.get("selected_total") or len(preserved_symbols) or 0),
            },
            "selected_symbols": [],
            "selected_total": 0,
            "eligible_total": 0,
            "would_trade": 0,
            "actual_submit_side_effect_symbols": [],
            "selected_submit_gap_symbols": [],
        })
        return latest_scan, current_summary

    if latest_summary:
        latest_summary["latest_scan_exception"] = exception_truth

    return latest_scan, latest_summary

def _symbol_rows(rows: list[dict] | None) -> list[str]:
    out = []
    for row in rows or []:
        sym = str((row or {}).get("symbol") or "").upper()
        if sym and sym not in out:
            out.append(sym)
    return out


def _build_cohort_evidence_event(summary: dict | None = None, breakout_max_distance_pct: float | None = None, nearest_limit: int | None = None) -> dict:
    summary = dict(summary or {})
    meta = _canonical_scan_meta(summary)
    nearest_n = max(1, min(int(nearest_limit or globals().get("PATCH50_NEAREST_PASS_TOP_N", 3)), 10))
    nearest = _build_nearest_pass(summary, limit=nearest_n)
    relaxed = _build_breakout_relaxed_snapshot(summary, breakout_max_distance_pct=breakout_max_distance_pct, limit=25)
    alt = _build_alternate_entry_shadow(summary, limit=25)
    event = {
        "ts_utc": meta.get("ts_utc"),
        "strategy_name": meta.get("strategy_name"),
        "scan_reason": meta.get("scan_reason"),
        "index_symbol": meta.get("index_symbol"),
        "index_alignment_ok": meta.get("index_alignment_ok"),
        "global_block_reasons": list(meta.get("global_block_reasons") or []),
        "nearest_pass_candidates": list(nearest.get("nearest_pass_candidates") or []),
        "relaxed_first_pass_candidates": list(relaxed.get("first_pass_candidates") or []),
        "relaxed_market_gated_candidates": list(relaxed.get("market_gated_candidates") or []),
        "alternate_first_pass_candidates": list(alt.get("first_pass_candidates") or []),
        "alternate_market_gated_candidates": list(alt.get("market_gated_candidates") or []),
        "nearest_pass_symbols": _symbol_rows(nearest.get("nearest_pass_candidates") or []),
        "relaxed_first_pass_symbols": _symbol_rows(relaxed.get("first_pass_candidates") or []),
        "relaxed_market_gated_symbols": _symbol_rows(relaxed.get("market_gated_candidates") or []),
        "alternate_first_pass_symbols": _symbol_rows(alt.get("first_pass_candidates") or []),
        "alternate_market_gated_symbols": _symbol_rows(alt.get("market_gated_candidates") or []),
    }
    return event


def _append_cohort_evidence_event(summary: dict | None = None):
    try:
        event = _build_cohort_evidence_event(summary)
        COHORT_EVIDENCE_HISTORY.append(event)
        if len(COHORT_EVIDENCE_HISTORY) > COHORT_EVIDENCE_HISTORY_SIZE:
            del COHORT_EVIDENCE_HISTORY[: len(COHORT_EVIDENCE_HISTORY) - COHORT_EVIDENCE_HISTORY_SIZE]
        return event
    except Exception:
        logger.exception("COHORT_EVIDENCE_APPEND_FAILED")
        return {}


def persist_cohort_evidence_state(reason: str = ""):
    payload = {
        "saved_at_utc": datetime.now(timezone.utc).isoformat(),
        "reason": reason,
        "history": list(COHORT_EVIDENCE_HISTORY or []),
    }
    return _safe_json_write(COHORT_EVIDENCE_STATE_PATH, payload)


def restore_cohort_evidence_state() -> dict:
    payload = _safe_json_read(COHORT_EVIDENCE_STATE_PATH)
    restored = {"path": COHORT_EVIDENCE_STATE_PATH, "loaded": False, "history_restored": 0, "backfilled_from_candidate_history": 0}
    if payload:
        try:
            hist = payload.get("history") or []
            if isinstance(hist, list) and hist:
                COHORT_EVIDENCE_HISTORY.clear()
                COHORT_EVIDENCE_HISTORY.extend(hist[-COHORT_EVIDENCE_HISTORY_SIZE:])
                restored["history_restored"] = len(COHORT_EVIDENCE_HISTORY)
                restored["loaded"] = True
        except Exception as e:
            restored["error"] = str(e)
    if not restored.get("loaded") and CANDIDATE_HISTORY:
        try:
            COHORT_EVIDENCE_HISTORY.clear()
            for entry in (CANDIDATE_HISTORY or [])[-COHORT_EVIDENCE_HISTORY_SIZE:]:
                COHORT_EVIDENCE_HISTORY.append(_build_cohort_evidence_event(entry))
            restored["history_restored"] = len(COHORT_EVIDENCE_HISTORY)
            restored["backfilled_from_candidate_history"] = len(COHORT_EVIDENCE_HISTORY)
            restored["loaded"] = bool(COHORT_EVIDENCE_HISTORY)
        except Exception as e:
            restored["backfill_error"] = str(e)
    globals()["COHORT_EVIDENCE_STATE_RESTORE"] = restored
    return restored


def _cohort_history_entries_limited(history_limit: int = PATCH51_MULTI_SCAN_DEFAULT) -> list[dict]:
    lim = max(1, min(int(history_limit or PATCH51_MULTI_SCAN_DEFAULT), COHORT_EVIDENCE_HISTORY_SIZE))
    hist = [dict(item or {}) for item in (COHORT_EVIDENCE_HISTORY or [])[-lim:]]
    if hist:
        return hist
    out = []
    for entry in _history_entries_limited(lim):
        out.append(_build_cohort_evidence_event(entry))
    return out


def _build_cohort_persistence_snapshot(history_limit: int = PATCH51_MULTI_SCAN_DEFAULT, min_hits: int = 1, limit: int = 15) -> dict:
    entries = _cohort_history_entries_limited(history_limit)
    min_hits = max(1, int(min_hits or 1))
    limit = max(1, min(int(limit or 15), 50))
    evidence = {}
    for entry in entries:
        ts = entry.get("ts_utc")
        for cohort_key in ("nearest_pass_candidates", "relaxed_first_pass_candidates", "alternate_first_pass_candidates", "alternate_market_gated_candidates"):
            for item in entry.get(cohort_key) or []:
                sym = str((item or {}).get("symbol") or "").upper()
                if not sym:
                    continue
                ev = evidence.setdefault(sym, {
                    "symbol": sym,
                    "nearest_pass_hits": 0,
                    "relaxed_first_pass_hits": 0,
                    "alternate_first_pass_hits": 0,
                    "alternate_market_gated_hits": 0,
                    "best_rank_score": None,
                    "best_non_market_gap_score": None,
                    "last_seen_utc": None,
                })
                if cohort_key == "nearest_pass_candidates":
                    ev["nearest_pass_hits"] += 1
                    gap = _safe_float((item or {}).get("non_market_gap_score"))
                    best_gap = ev.get("best_non_market_gap_score")
                    if gap is not None and (best_gap is None or gap < best_gap):
                        ev["best_non_market_gap_score"] = gap
                elif cohort_key == "relaxed_first_pass_candidates":
                    ev["relaxed_first_pass_hits"] += 1
                elif cohort_key == "alternate_first_pass_candidates":
                    ev["alternate_first_pass_hits"] += 1
                elif cohort_key == "alternate_market_gated_candidates":
                    ev["alternate_market_gated_hits"] += 1
                rank = _safe_float((item or {}).get("rank_score"))
                best_rank = ev.get("best_rank_score")
                if rank is not None and (best_rank is None or rank > best_rank):
                    ev["best_rank_score"] = rank
                if ts and (not ev.get("last_seen_utc") or str(ts) > str(ev.get("last_seen_utc"))):
                    ev["last_seen_utc"] = ts
    rows = []
    for ev in evidence.values():
        total_hits = int(ev.get("nearest_pass_hits") or 0) + int(ev.get("relaxed_first_pass_hits") or 0) + int(ev.get("alternate_first_pass_hits") or 0) + int(ev.get("alternate_market_gated_hits") or 0)
        if total_hits < min_hits:
            continue
        persistence_score = int(ev.get("nearest_pass_hits") or 0) * 5 + int(ev.get("relaxed_first_pass_hits") or 0) * 4 + int(ev.get("alternate_first_pass_hits") or 0) + int(ev.get("alternate_market_gated_hits") or 0)
        row = dict(ev)
        row["total_hits"] = total_hits
        row["persistence_score"] = persistence_score
        rows.append(row)
    rows.sort(key=lambda r: (-int(r.get("persistence_score") or 0), -int(r.get("alternate_first_pass_hits") or 0), -int(r.get("alternate_market_gated_hits") or 0), -int(r.get("relaxed_first_pass_hits") or 0), float(r.get("best_non_market_gap_score") if r.get("best_non_market_gap_score") is not None else 999.0), -(float(r.get("best_rank_score") or 0.0)), r.get("symbol") or ""))
    latest = entries[-1] if entries else {}
    return {
        "ok": True,
        "history_limit": len(entries),
        "min_hits": min_hits,
        "current": latest,
        "cohort_persistence": rows[:limit],
    }



def _cohort_symbol_current_flags(entries: list[dict], history_limit: int = PATCH51_MULTI_SCAN_DEFAULT, breakout_max_distance_pct: float | None = None) -> dict[str, dict]:
    breakout_test = float(PATCH50_BREAKOUT_TEST_MAX_DISTANCE_PCT if breakout_max_distance_pct is None else breakout_max_distance_pct)
    latest = entries[-1] if entries else {}
    latest_hist = _history_entries_limited(1)
    latest_scan = latest_hist[-1] if latest_hist else {}
    relaxed = _build_breakout_relaxed_snapshot(latest_scan, breakout_max_distance_pct=breakout_test, limit=25) if latest_scan else {"first_pass_candidates": [], "market_gated_candidates": [], "live_eligible_candidates": []}
    alt = _build_alternate_entry_shadow(latest_scan, limit=25) if latest_scan else {"first_pass_candidates": [], "market_gated_candidates": [], "live_eligible_candidates": []}
    current_map: dict[str, dict] = {}

    def ensure(sym: str) -> dict:
        return current_map.setdefault(sym, {
            "current_in_nearest_pass": False,
            "current_in_relaxed_first_pass": False,
            "current_in_relaxed_market_gated": False,
            "current_in_alternate_first_pass": False,
            "current_in_alternate_market_gated": False,
            "current_primary_non_market_failures": 0,
            "current_primary_non_market_reasons": [],
            "current_status": "historical_only",
            "promotion_state": "historical_only",
            "attention_priority": 0,
        })

    for item in latest.get("nearest_pass_candidates") or []:
        sym = str((item or {}).get("symbol") or "").upper()
        if not sym:
            continue
        ensure(sym)["current_in_nearest_pass"] = True

    for item in relaxed.get("first_pass_candidates") or []:
        sym = str((item or {}).get("symbol") or "").upper()
        if not sym:
            continue
        ensure(sym)["current_in_relaxed_first_pass"] = True
    for item in relaxed.get("market_gated_candidates") or []:
        sym = str((item or {}).get("symbol") or "").upper()
        if not sym:
            continue
        ensure(sym)["current_in_relaxed_market_gated"] = True
    for item in alt.get("first_pass_candidates") or []:
        sym = str((item or {}).get("symbol") or "").upper()
        if not sym:
            continue
        ensure(sym)["current_in_alternate_first_pass"] = True
    for item in alt.get("market_gated_candidates") or []:
        sym = str((item or {}).get("symbol") or "").upper()
        if not sym:
            continue
        ensure(sym)["current_in_alternate_market_gated"] = True

    for item in (latest_scan.get("candidates") or []):
        sym = str((item or {}).get("symbol") or "").upper()
        if not sym:
            continue
        row = ensure(sym)
        non_market = list((item or {}).get("shadow_non_market_reasons") or [])
        row["current_primary_non_market_reasons"] = non_market
        row["current_primary_non_market_failures"] = len(non_market)

    for sym, row in current_map.items():
        if row.get("current_in_relaxed_first_pass"):
            row["current_status"] = "relaxed_first_pass"
            row["promotion_state"] = "one_gate_away"
            row["attention_priority"] = 5
        elif row.get("current_in_alternate_first_pass"):
            row["current_status"] = "alternate_first_pass"
            row["promotion_state"] = "one_gate_away"
            row["attention_priority"] = 5
        elif row.get("current_in_relaxed_market_gated"):
            row["current_status"] = "relaxed_market_gated"
            row["promotion_state"] = "market_gate_only"
            row["attention_priority"] = 4
        elif row.get("current_in_alternate_market_gated"):
            row["current_status"] = "alternate_market_gated"
            row["promotion_state"] = "market_gate_only"
            row["attention_priority"] = 4
        elif row.get("current_in_nearest_pass"):
            fails = int(row.get("current_primary_non_market_failures") or 0)
            row["current_status"] = "nearest_pass"
            if fails <= 1:
                row["promotion_state"] = "needs_1_threshold"
                row["attention_priority"] = 3
            elif fails == 2:
                row["promotion_state"] = "needs_2_thresholds"
                row["attention_priority"] = 2
            else:
                row["promotion_state"] = "needs_3plus_thresholds"
                row["attention_priority"] = 1
        else:
            row["current_status"] = "historical_only"
            row["promotion_state"] = "historical_only"
            row["attention_priority"] = 0
    return current_map


def _classify_watchlist_bucket(row: dict) -> str:
    nearest_hits = int(row.get("nearest_pass_hits") or 0)
    relaxed_hits = int(row.get("relaxed_first_pass_hits") or 0)
    alt_first_hits = int(row.get("alternate_first_pass_hits") or 0)
    alt_gate_hits = int(row.get("alternate_market_gated_hits") or 0)
    breakout_strength = nearest_hits * 2 + relaxed_hits * 3
    alternate_strength = alt_first_hits * 2 + alt_gate_hits * 2
    if breakout_strength > 0 and alternate_strength > 0:
        return "mixed_signal"
    if breakout_strength >= alternate_strength and breakout_strength > 0:
        return "breakout_watch"
    if alternate_strength > 0:
        return "alternate_entry_watch"
    return "historical_only"


def _build_cohort_scorecard(history_limit: int = PATCH51_MULTI_SCAN_DEFAULT, min_hits: int = 1, limit: int = PATCH52_SCORECARD_LIMIT, breakout_max_distance_pct: float | None = None) -> dict:
    entries = _cohort_history_entries_limited(history_limit)
    min_hits = max(1, int(min_hits or 1))
    limit = max(1, min(int(limit or PATCH52_SCORECARD_LIMIT), 50))
    breakout_test = float(PATCH50_BREAKOUT_TEST_MAX_DISTANCE_PCT if breakout_max_distance_pct is None else breakout_max_distance_pct)
    persistence = _build_cohort_persistence_snapshot(history_limit=history_limit, min_hits=min_hits, limit=200)
    rows = []
    current_flags = _cohort_symbol_current_flags(entries, history_limit=history_limit, breakout_max_distance_pct=breakout_test)
    latest_index = max(0, len(entries) - 1)
    halflife = max(1.0, float(PATCH52_RECENCY_HALFLIFE_SCANS))
    seen_index_by_symbol: dict[str, list[int]] = {}
    for idx, entry in enumerate(entries):
        seen_syms = set()
        for cohort_key in ("nearest_pass_candidates", "relaxed_first_pass_candidates", "alternate_first_pass_candidates", "alternate_market_gated_candidates"):
            for item in entry.get(cohort_key) or []:
                sym = str((item or {}).get("symbol") or "").upper()
                if sym:
                    seen_syms.add(sym)
        for sym in seen_syms:
            seen_index_by_symbol.setdefault(sym, []).append(idx)
    for base in persistence.get("cohort_persistence") or []:
        sym = str((base or {}).get("symbol") or "").upper()
        if not sym:
            continue
        decayed = 0.0
        for idx in seen_index_by_symbol.get(sym, []):
            distance = max(0, latest_index - idx)
            decayed += 0.5 ** (distance / halflife)
        row = dict(base)
        row.update(current_flags.get(sym) or {})
        row["watchlist_bucket"] = _classify_watchlist_bucket(row)
        row["decayed_hit_score"] = round(decayed, 4)
        row["current_presence_score"] = (2 if row.get("current_in_relaxed_first_pass") else 0) + (2 if row.get("current_in_alternate_first_pass") else 0) + (1 if row.get("current_in_relaxed_market_gated") else 0) + (1 if row.get("current_in_alternate_market_gated") else 0) + (1 if row.get("current_in_nearest_pass") else 0)
        rows.append(row)
    rows.sort(key=lambda r: (-int(r.get("attention_priority") or 0), -float(r.get("decayed_hit_score") or 0.0), -int(r.get("persistence_score") or 0), float(r.get("best_non_market_gap_score") if r.get("best_non_market_gap_score") is not None else 999.0), -(float(r.get("best_rank_score") or 0.0)), r.get("symbol") or ""))
    buckets = {
        "breakout_watch": [r for r in rows if r.get("watchlist_bucket") == "breakout_watch"],
        "alternate_entry_watch": [r for r in rows if r.get("watchlist_bucket") == "alternate_entry_watch"],
        "mixed_signal_watch": [r for r in rows if r.get("watchlist_bucket") == "mixed_signal"],
    }
    return {
        "ok": True,
        "history_limit": len(entries),
        "min_hits": min_hits,
        "breakout_test_max_distance_pct": breakout_test,
        "recency_halflife_scans": int(PATCH52_RECENCY_HALFLIFE_SCANS),
        "scorecard": rows[:limit],
        "breakout_watch": buckets["breakout_watch"][:limit],
        "alternate_entry_watch": buckets["alternate_entry_watch"][:limit],
        "mixed_signal_watch": buckets["mixed_signal_watch"][:limit],
    }


def _build_promotion_watchlist(history_limit: int = PATCH51_MULTI_SCAN_DEFAULT, min_hits: int = 1, limit: int = PATCH52_WATCHLIST_TOP_N, breakout_max_distance_pct: float | None = None) -> dict:
    scorecard = _build_cohort_scorecard(history_limit=history_limit, min_hits=min_hits, limit=100, breakout_max_distance_pct=breakout_max_distance_pct)
    limit = max(1, min(int(limit or PATCH52_WATCHLIST_TOP_N), 25))
    rows = list(scorecard.get("scorecard") or [])
    promoteable = [r for r in rows if str(r.get("promotion_state") or "") != "historical_only"]
    promoteable.sort(key=lambda r: (-int(r.get("attention_priority") or 0), -float(r.get("decayed_hit_score") or 0.0), -int(r.get("current_presence_score") or 0), float(r.get("best_non_market_gap_score") if r.get("best_non_market_gap_score") is not None else 999.0), -(float(r.get("best_rank_score") or 0.0)), r.get("symbol") or ""))
    return {
        "ok": True,
        "history_limit": int(scorecard.get("history_limit") or 0),
        "min_hits": min_hits,
        "promotion_watchlist": promoteable[:limit],
        "top_3_now": promoteable[:3],
        "breakout_watchlist": [r for r in promoteable if r.get("watchlist_bucket") == "breakout_watch"][:limit],
        "alternate_entry_watchlist": [r for r in promoteable if r.get("watchlist_bucket") == "alternate_entry_watch"][:limit],
        "mixed_signal_watchlist": [r for r in promoteable if r.get("watchlist_bucket") == "mixed_signal"][:limit],
    }

def persist_regime_runtime_state(reason: str = ""):
    payload = {
        "saved_at_utc": datetime.now(timezone.utc).isoformat(),
        "reason": reason,
        "current": dict(LAST_REGIME_SNAPSHOT or {}),
        "history": list(REGIME_HISTORY or []),
    }
    return _safe_json_write(REGIME_STATE_PATH, payload)


def restore_regime_runtime_state() -> dict:
    payload = _safe_json_read(REGIME_STATE_PATH)
    restored = {"path": REGIME_STATE_PATH, "loaded": False, "current_restored": False, "history_restored": 0}
    if not payload:
        return restored
    try:
        current = payload.get("current") or {}
        history = payload.get("history") or []
        if isinstance(current, dict) and current:
            LAST_REGIME_SNAPSHOT.clear()
            LAST_REGIME_SNAPSHOT.update(current)
            restored["current_restored"] = True
        if isinstance(history, list) and history:
            REGIME_HISTORY.clear()
            REGIME_HISTORY.extend(history[-SWING_REGIME_HISTORY_SIZE:])
            restored["history_restored"] = len(REGIME_HISTORY)
        restored["loaded"] = restored["current_restored"] or bool(restored["history_restored"])
    except Exception as e:
        restored["error"] = str(e)
    globals()["REGIME_STATE_RESTORE"] = restored
    return restored




def persist_scanner_telemetry_state(reason: str = ""):
    payload = {
        "saved_at_utc": datetime.now(timezone.utc).isoformat(),
        "reason": reason,
        "last": dict(LAST_SCANNER_TELEMETRY or {}),
        "history": list(SCANNER_TELEMETRY_HISTORY or []),
    }
    return _safe_json_write(SCANNER_TELEMETRY_STATE_PATH, payload)


def restore_scanner_telemetry_state() -> dict:
    payload = _safe_json_read(SCANNER_TELEMETRY_STATE_PATH)
    restored = {"path": SCANNER_TELEMETRY_STATE_PATH, "loaded": False, "last_restored": False, "history_restored": 0}
    if not payload:
        return restored
    try:
        last = payload.get("last") or {}
        history = payload.get("history") or []
        if isinstance(last, dict) and last:
            restored_last = dict(last)
            restored_last["restored_from_state"] = True
            LAST_SCANNER_TELEMETRY.clear()
            LAST_SCANNER_TELEMETRY.update(restored_last)
            restored["last_restored"] = True
        if isinstance(history, list) and history:
            SCANNER_TELEMETRY_HISTORY.clear()
            SCANNER_TELEMETRY_HISTORY.extend(history[-SCANNER_TELEMETRY_HISTORY_LIMIT:])
            restored["history_restored"] = len(SCANNER_TELEMETRY_HISTORY)
        restored["loaded"] = restored["last_restored"] or bool(restored["history_restored"])
    except Exception as e:
        restored["error"] = str(e)
    globals()["SCANNER_TELEMETRY_STATE_RESTORE"] = restored
    return restored




def _safe_parse_iso_utc(ts):
    try:
        if not ts:
            return None
        dt = datetime.fromisoformat(str(ts))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return None


def _classify_scanner_warning_codes(state: dict) -> dict:
    state = dict(state or {})
    active = []
    recovered = []
    historical = []

    def _add_unique(seq, code):
        if code and code not in seq:
            seq.append(code)

    in_flight_run = bool(state.get("in_flight_run"))
    incomplete_runs_total = int(state.get("incomplete_runs_total") or 0)
    historical_incomplete_runs_total = int(state.get("historical_incomplete_runs_total") or 0)

    worker_status = str(state.get("worker_status") or "unknown").strip().lower()
    latest_status = str(state.get("status") or state.get("last_status") or "").strip().lower()
    last_worker_event_dt = _safe_parse_iso_utc(state.get("last_worker_event_utc") or state.get("last_event_utc"))
    recent_worker_event = bool(
        last_worker_event_dt
        and (datetime.now(timezone.utc) - last_worker_event_dt).total_seconds()
        <= max(int(state.get("interval_sec") or SCAN_INTERVAL_SEC or 300) + 180, 300)
    )
    if worker_status == "unknown" and recent_worker_event and latest_status in {"ok", "success", "skipped"}:
        worker_status = "up"

    last_dispatch_failure_dt = _safe_parse_iso_utc(state.get("last_dispatch_failure_utc"))
    last_success_dt = _safe_parse_iso_utc(state.get("last_success_utc"))
    last_closed_dt = _safe_parse_iso_utc(state.get("last_closed_utc"))
    last_open_dt = _safe_parse_iso_utc(state.get("last_open_utc"))
    last_closed_status = str(state.get("last_closed_status") or "").strip().lower()
    timeout_sec = int(state.get("timeout_sec") or 0)

    manual_request_today = int(state.get("manual_request_today") or 0)
    external_request_today = int(state.get("external_request_today") or 0)

    if in_flight_run or incomplete_runs_total > 0:
        _add_unique(active, "partial_run_open")
    elif historical_incomplete_runs_total > 0:
        _add_unique(historical, "restored_partial_run_history")

    if manual_request_today > 0:
        _add_unique(historical, "manual_scan_request_observed")
    if external_request_today > 0:
        _add_unique(historical, "external_scan_request_observed")

    if worker_status != "up":
        if worker_status == "late":
            _add_unique(active, "worker_heartbeat_late")
        elif worker_status in {"stale", "down"}:
            _add_unique(active, "worker_heartbeat_stale")
        else:
            _add_unique(active, "worker_status_unknown")

    if last_dispatch_failure_dt is not None:
        side_effect_truth = dict(state.get("side_effect_truth") or {})
        success_after_side_effect = bool(side_effect_truth.get("side_effect_detected"))

        dispatch_recovered_by_success = bool(
            last_success_dt
            and last_closed_dt
            and last_closed_status in {"success", "skipped"}
            and last_success_dt >= last_dispatch_failure_dt
            and last_closed_dt >= last_dispatch_failure_dt
        )
        dispatch_recovered_by_closed_scan = bool(
            last_closed_dt
            and last_closed_status in {"success", "skipped"}
            and last_closed_dt >= last_dispatch_failure_dt
        )
        dispatch_recovered = bool(
            dispatch_recovered_by_success
            or dispatch_recovered_by_closed_scan
            or success_after_side_effect
        )
        dispatch_late_timeout_after_success = bool(
            not dispatch_recovered
            and last_open_dt
            and last_closed_dt
            and last_closed_status in {"success", "skipped"}
            and last_open_dt <= last_closed_dt <= last_dispatch_failure_dt
            and (last_dispatch_failure_dt - last_closed_dt).total_seconds() <= max(timeout_sec + 30, 120)
        )
        if dispatch_recovered or dispatch_late_timeout_after_success:
            if dispatch_recovered_by_closed_scan and not dispatch_recovered_by_success:
                _add_unique(recovered, "dispatch_failure_recovered_by_closed_scan")
            else:
                _add_unique(recovered, "dispatch_failure_recovered")
        else:
            _add_unique(active, "dispatch_failure")

    return {
        "active_warning_codes": active,
        "recovered_warning_codes": recovered,
        "historical_warning_codes": historical,
        "warning_codes": list(active),
        "has_warnings": bool(active),
        "has_active_warnings": bool(active),
        "has_recovered_warnings": bool(recovered),
    }

def _p272_recent_scanner_side_effects(since_utc: str | None = None, window_sec: int = 900) -> dict:
    since_dt = _safe_parse_iso_utc(since_utc)
    now_dt = datetime.now(timezone.utc)
    rows = []

    for sym, plan in (TRADE_PLAN or {}).items():
        if not isinstance(plan, dict):
            continue
        symbol = str(sym or plan.get("symbol") or "").strip().upper()
        if not symbol:
            continue

        submitted_dt = _safe_parse_iso_utc(plan.get("submitted_at") or plan.get("opened_at") or plan.get("execution_updated_utc"))
        updated_dt = _safe_parse_iso_utc(plan.get("execution_updated_utc") or plan.get("submitted_at") or plan.get("opened_at"))
        ref_dt = updated_dt or submitted_dt

        if since_dt and ref_dt and ref_dt < since_dt:
            continue
        if not since_dt and ref_dt and (now_dt - ref_dt).total_seconds() > max(60, int(window_sec or 900)):
            continue

        order_id = str(plan.get("order_id") or "").strip()
        execution_state = str(plan.get("execution_state") or plan.get("lifecycle_state") or plan.get("order_status") or "").strip().lower()
        active = bool(plan.get("active"))
        side_effect = bool(active or order_id or execution_state in {"submitted", "acknowledged", "partially_filled", "filled"})

        if not side_effect:
            continue

        rows.append({
            "symbol": symbol,
            "order_id": order_id or None,
            "active": active,
            "execution_state": execution_state or None,
            "source": plan.get("source"),
            "signal": plan.get("signal") or plan.get("strategy_name"),
            "submitted_at": plan.get("submitted_at"),
            "execution_updated_utc": plan.get("execution_updated_utc"),
        })

    return {
        "ok": True,
        "since_utc": since_utc,
        "window_sec": int(window_sec or 900),
        "count": len(rows),
        "symbols": [r.get("symbol") for r in rows],
        "rows": rows[-25:],
        "side_effect_detected": bool(rows),
    }


def _p272_scanner_dispatch_attempt_key(body: dict | None, source_meta: dict | None = None) -> str:
    body = dict(body or {})
    source_meta = dict(source_meta or {})
    raw = str(
        body.get("scan_attempt_id")
        or body.get("dispatch_id")
        or body.get("idempotency_key")
        or ""
    ).strip()
    if raw:
        return raw[:120]

    material = "|".join([
        str(source_meta.get("source_kind") or "unknown"),
        str(body.get("reason") or "scheduled"),
        str(body.get("mode") or ""),
        str(body.get("provider") or ""),
        str(body.get("symbols_provider") or ""),
        str(body.get("symbols") or ""),
        datetime.now(timezone.utc).replace(second=0, microsecond=0).isoformat(),
    ])
    return hashlib.sha256(material.encode("utf-8")).hexdigest()[:32]


def _p272_prune_scanner_dispatch_attempts() -> None:
    try:
        limit = max(10, int(SCANNER_DISPATCH_ATTEMPT_LIMIT or 100))
        if len(SCANNER_DISPATCH_ATTEMPTS) <= limit:
            return
        ordered = sorted(
            SCANNER_DISPATCH_ATTEMPTS.items(),
            key=lambda kv: str((kv[1] or {}).get("updated_utc") or (kv[1] or {}).get("started_utc") or ""),
        )
        for key, _row in ordered[: max(0, len(ordered) - limit)]:
            SCANNER_DISPATCH_ATTEMPTS.pop(key, None)
    except Exception:
        pass

def _p398_runtime_budget_elapsed_sec(scan_started: float | None = None) -> float:
    try:
        if scan_started is None:
            return 0.0
        return max(0.0, float(_time.perf_counter() - float(scan_started)))
    except Exception:
        return 0.0


def _p398_scan_runtime_over_budget(scan_started: float | None = None) -> bool:
    return _p398_runtime_budget_elapsed_sec(scan_started) >= max(1.0, float(SCAN_RUNTIME_BUDGET_SEC or 1))

def _p273_runtime_budget_snapshot(duration_ms: int | float = 0, timing_ms: dict | None = None) -> dict:
    duration_sec = max(0.0, float(duration_ms or 0) / 1000.0)
    budget_sec = max(1.0, float(SCAN_RUNTIME_BUDGET_SEC or 1))
    warn_sec = max(1.0, budget_sec * float(SCAN_RUNTIME_WARN_RATIO or 0.85))
    over_budget = duration_sec > budget_sec
    near_budget = duration_sec >= warn_sec
    timing = dict(timing_ms or {})
    slowest_stage = None
    slowest_ms = 0
    for key, value in timing.items():
        try:
            ms = int(value or 0)
        except Exception:
            ms = 0
        if key != "total" and ms > slowest_ms:
            slowest_stage = key
            slowest_ms = ms
    return {
        "duration_ms": int(duration_ms or 0),
        "duration_sec": round(duration_sec, 3),
        "budget_sec": int(budget_sec),
        "warn_sec": round(warn_sec, 3),
        "near_budget": bool(near_budget),
        "over_budget": bool(over_budget),
        "runtime_over_timeout_risk": bool(over_budget or near_budget),
        "slowest_stage": slowest_stage,
        "slowest_stage_ms": int(slowest_ms),
        "timing_ms": timing,
    }


def _p273_compact_would_submit(rows: list | None) -> list:
    out = []
    for row in list(rows or [])[:25]:
        if not isinstance(row, dict):
            continue
        out.append({
            "symbol": row.get("symbol"),
            "side": row.get("side"),
            "signal": row.get("signal"),
            "rank_score": row.get("rank_score"),
            "signal_family": row.get("signal_family"),
            "submit_state": row.get("submit_state"),
            "submit_reason": row.get("submit_reason"),
            "submit_attempted": row.get("submit_attempted"),
            "order_id": row.get("order_id"),
            "submitted": bool(row.get("submitted")),
            "ignored": bool(row.get("ignored")),
            "rejected": bool(row.get("rejected")),
            "dry_run": bool(row.get("dry_run")),
        })
    return out


def _p273_compact_scan_results(rows: list | None, limit: int = 10) -> list:
    out = []
    for row in list(rows or [])[:max(0, int(limit or 10))]:
        if not isinstance(row, dict):
            continue
        out.append({
            "symbol": row.get("symbol"),
            "action": row.get("action"),
            "reason": row.get("reason"),
            "signal": row.get("signal"),
            "score": row.get("score"),
            "rank_score": row.get("rank_score"),
            "close": row.get("close"),
        })
    return out


def _p273_should_fast_response(source_kind: str, body: dict | None = None) -> bool:
    body = dict(body or {})
    if str(body.get("full_response") or "").strip().lower() in {"1", "true", "yes", "y", "on"}:
        return False
    if str(body.get("fast_response") or "").strip().lower() in {"1", "true", "yes", "y", "on"}:
        return True
    if not bool(SCAN_FAST_RESPONSE_ENABLED):
        return False
    if bool(SCAN_FAST_RESPONSE_FOR_WORKER_ONLY):
        return str(source_kind or "").strip().lower() == "worker"
    return True


def _p273_fast_scan_response(
    *,
    scan_attempt_id: str,
    scanner_payload: dict,
    reconcile_actions: list | None,
    would_submit: list | None,
    results: list | None,
    timing_ms: dict | None,
    duration_ms: int,
    compact: bool,
) -> dict:
    runtime_budget = _p273_runtime_budget_snapshot(duration_ms, timing_ms)
    submit_rows = _p273_compact_would_submit(would_submit)
    submitted_symbols = [r.get("symbol") for r in submit_rows if r.get("submitted") or r.get("submit_state") == "submitted"]
    attempted_symbols = [r.get("symbol") for r in submit_rows if r.get("submit_attempted")]
    blocked_symbols = [r.get("symbol") for r in submit_rows if r.get("submit_state") in {"blocked", "error"}]

    response = {
        "ok": True,
        "scan_attempt_id": scan_attempt_id,
        "fast_response": bool(compact),
        "scanner": scanner_payload,
        "runtime_budget": runtime_budget,
        "submission_summary": {
            "would_submit_count": len(list(would_submit or [])),
            "submitted_count": len(submitted_symbols),
            "attempted_count": len(attempted_symbols),
            "blocked_count": len(blocked_symbols),
            "submitted_symbols": submitted_symbols,
            "attempted_symbols": attempted_symbols,
            "blocked_symbols": blocked_symbols,
            "rows": submit_rows,
        },
        "reconcile_summary": {
            "action_count": len(list(reconcile_actions or [])),
            "actions": list(reconcile_actions or [])[:10],
        },
    }

    if not compact:
        response["reconcile"] = list(reconcile_actions or [])
        response["would_submit"] = list(would_submit or [])
        response["results"] = list(results or [])
    else:
        response["results_preview"] = _p273_compact_scan_results(results, limit=10)

    return response

def _p274_limit_rows(rows, limit: int | None = None) -> list:
    lim = max(1, int(limit or DIAGNOSTIC_BUNDLE_MAX_ROWS or 10))
    if not isinstance(rows, list):
        return []
    return [dict(r or {}) if isinstance(r, dict) else r for r in rows[:lim]]


