log("CONFIG_EFFECTIVE", **config_effective_snapshot())

# =============================
# Core helpers
# =============================
_MARKET_CLOCK_CACHE: dict = {"ts": 0.0, "snapshot": {}}

def _static_market_window_snapshot(dt_local=None) -> dict:
    dt_local = dt_local or now_ny()
    today = dt_local.date().isoformat()
    weekday_open = False
    try:
        weekday_open = int(dt_local.weekday()) < 5
    except Exception:
        weekday_open = False
    configured_closed = today in MARKET_CLOSED_DATES_NY
    market_day = bool(weekday_open and not configured_closed)
    clock_open = bool(market_day and MARKET_OPEN <= dt_local.time() <= MARKET_CLOSE)
    reason = "open" if clock_open else ("configured_market_closed_date" if configured_closed else ("weekend" if not weekday_open else "outside_market_hours"))
    return {
        "ok": True,
        "source": "static_fallback",
        "is_open": clock_open,
        "market_open_now": clock_open,
        "market_day": market_day,
        "configured_closed": configured_closed,
        "today_ny": today,
        "now_ny": dt_local.isoformat(),
        "reason": reason,
    }

def _coerce_clock_dt(value) -> str | None:
    if not value:
        return None
    try:
        dt = value if isinstance(value, datetime) else datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(NY_TZ).isoformat()
    except Exception:
        return str(value)

def _market_clock_snapshot(force: bool = False) -> dict:
    now_ts = _time.time()
    cached = dict(_MARKET_CLOCK_CACHE.get("snapshot") or {})
    if cached and not force and now_ts - float(_MARKET_CLOCK_CACHE.get("ts") or 0.0) <= max(1, int(MARKET_CLOCK_CACHE_TTL_SEC or 1)):
        return cached

    static = _static_market_window_snapshot()
    try:
        clock = trading_client.get_clock()
        is_open = bool(getattr(clock, "is_open", False))
        today = str(static.get("today_ny") or "")
        if today in MARKET_CLOSED_DATES_NY:
            is_open = False
            reason = "configured_market_closed_date"
        else:
            reason = "alpaca_clock_open" if is_open else "alpaca_clock_closed"
        snap = {
            **static,
            "ok": True,
            "source": "alpaca_clock",
            "is_open": is_open,
            "market_open_now": is_open,
            "reason": reason,
            "timestamp_ny": _coerce_clock_dt(getattr(clock, "timestamp", None)),
            "next_open_ny": _coerce_clock_dt(getattr(clock, "next_open", None)),
            "next_close_ny": _coerce_clock_dt(getattr(clock, "next_close", None)),
        }
    except Exception as exc:
        fail_open = bool(MARKET_CLOCK_FAIL_OPEN)
        snap = {
            **static,
            "ok": False,
            "source": "alpaca_clock_error",
            "is_open": bool(static.get("is_open")) if fail_open else False,
            "market_open_now": bool(static.get("is_open")) if fail_open else False,
            "reason": "alpaca_clock_error_fail_open" if fail_open else "alpaca_clock_error_fail_closed",
            "error": str(exc),
        }

    _MARKET_CLOCK_CACHE["ts"] = now_ts
    _MARKET_CLOCK_CACHE["snapshot"] = dict(snap)
    return dict(snap)

def _is_regular_market_day(dt_local=None) -> bool:
    return bool(_static_market_window_snapshot(dt_local).get("market_day"))

def in_market_hours() -> bool:
    return bool(_market_clock_snapshot().get("is_open"))

def _p388_entry_level_preview(side: str, price: float, meta: dict | None = None) -> dict:
    meta = dict(meta or {})
    side_l = str(side or "buy").lower()
    price = float(price or 0.0)
    stop_raw = meta.get("stop_price") or meta.get("initial_stop_price")
    take_raw = meta.get("take_price") or meta.get("target_price")

    if stop_raw not in (None, "", 0, 0.0, "0", "0.0"):
        stop_price = float(stop_raw)
    elif side_l == "buy":
        stop_price = price * (1.0 - float(STOP_PCT))
    else:
        stop_price = price * (1.0 + float(STOP_PCT))

    if take_raw not in (None, "", 0, 0.0, "0", "0.0"):
        take_price = float(take_raw)
    elif side_l == "buy":
        take_price = price * (1.0 + float(TAKE_PCT))
    else:
        take_price = price * (1.0 - float(TAKE_PCT))

    risk_per_share = abs(price - stop_price)
    return {
        "price": round(price, 4),
        "side": side_l,
        "stop_price": round(stop_price, 4),
        "take_price": round(take_price, 4),
        "risk_per_share": round(risk_per_share, 4),
        "source": "candidate_stop" if stop_raw not in (None, "", 0, 0.0, "0", "0.0") else "default_stop_pct",
    }

def compute_qty(price: float, side: str = "buy", meta: dict | None = None) -> float:
    if price <= 0:
        raise ValueError("Price must be > 0")

    levels = _p388_entry_level_preview(side, price, meta=meta)
    risk_per_share = float(levels.get("risk_per_share") or 0.0)

    if risk_per_share <= 0:
        raise ValueError("entry risk_per_share must be > 0")

    effective_risk_dollars = _p459_effective_swing_risk_dollars()
    qty = float(effective_risk_dollars or 0.0) / risk_per_share

    if bool(SWING_TRUE_DOLLAR_RISK_SIZING_ENABLED):
        min_starter = max(0.0, float(SWING_TRUE_DOLLAR_RISK_MIN_STARTER_QTY or 0.0))
        max_starter_risk = float(effective_risk_dollars or 0.0) * max(
            0.0,
            float(SWING_TRUE_DOLLAR_RISK_MAX_STARTER_RISK_MULTIPLE or 0.0),
        )
        if qty < min_starter and min_starter > 0 and risk_per_share * min_starter <= max_starter_risk:
            qty = min_starter

    qty = max(qty, MIN_QTY)
    qty = min(qty, MAX_QTY)
    return round(qty, 2)

def get_buying_power_snapshot() -> dict:
    try:
        acct = trading_client.get_account()
        bp = float(getattr(acct, "buying_power", 0) or 0)
        equity = float(getattr(acct, "equity", 0) or 0)
        cash = float(getattr(acct, "cash", 0) or 0)
        return {"ok": True, "buying_power": bp, "equity": equity, "cash": cash}
    except Exception as e:
        return {"ok": False, "buying_power": 0.0, "equity": None, "cash": None, "error": str(e)}


def _clip_qty_for_affordability_with_snapshot(price: float, requested_qty: float, broker_snapshot: dict | None = None) -> dict:
    price = float(price or 0)
    requested_qty = float(requested_qty or 0)
    bp = dict(broker_snapshot or get_buying_power_snapshot() or {})
    if price <= 0 or requested_qty <= 0:
        return {"requested_qty": requested_qty, "affordable_qty": 0.0, "submitted_qty": 0.0, "affordability_clipped": False, "buying_power_snapshot": bp, "reason": "invalid_price_or_qty"}
    effective_bp = max(0.0, float(bp.get("buying_power") or 0.0) * max(0.0, min(1.0, ORDER_BP_HAIRCUT_PCT)))
    affordable_qty = 0.0 if effective_bp <= 0 else round(effective_bp / price, 2)
    submitted_qty = min(requested_qty, affordable_qty)
    submitted_qty = round(max(0.0, submitted_qty), 2)
    clipped = submitted_qty < round(requested_qty, 2)
    reason = ""
    if submitted_qty <= 0:
        reason = "insufficient_buying_power_internal"
    elif submitted_qty < max(MIN_AFFORDABLE_QTY, MIN_QTY):
        reason = "qty_below_min_after_affordability_clip"
    return {
        "requested_qty": round(requested_qty, 2),
        "affordable_qty": round(affordable_qty, 2),
        "submitted_qty": round(submitted_qty, 2),
        "affordability_clipped": clipped,
        "buying_power_snapshot": bp,
        "effective_buying_power": round(effective_bp, 2),
        "reason": reason,
    }


def clip_qty_for_affordability(price: float, requested_qty: float) -> dict:
    return _clip_qty_for_affordability_with_snapshot(price, requested_qty)

def get_latest_price(symbol: str) -> Optional[float]:
    req = StockLatestTradeRequest(symbol_or_symbols=[symbol])
    latest = data_client.get_stock_latest_trade(req)
    # Alpaca may omit symbols with no recent trade / unsupported tickers / feed limits.
    # Return None so callers can treat it as "no data" instead of raising KeyError.
    trade = None
    try:
        trade = latest.get(symbol) if hasattr(latest, "get") else latest[symbol]
    except KeyError:
        trade = None
    if trade is None:
        logging.warning("LATEST_PRICE_MISSING symbol=%s", symbol)
        return None
    px = float(trade.price)
    if px <= 0:
        raise ValueError("Latest trade price invalid")
    return px



# -------- Latest price batching + small cache (reduces Alpaca 429) --------
_LATEST_PRICES_CACHE: dict[str, float] | None = None
_LATEST_PRICES_CACHE_TS: float = 0.0
LATEST_PRICES_CACHE_TTL_SEC = getenv_int("LATEST_PRICES_CACHE_TTL_SEC", 5)

# In-process cache for latest prices (reduces rate-limit pressure).
_LATEST_PRICES_CACHE: dict[str, float] = {}
_LATEST_PRICES_CACHE_TS: float = 0.0

def get_latest_prices(symbols: list[str]) -> dict[str, float]:
    """Batch latest-trade prices for many symbols.
    Uses a tiny in-process cache to avoid hammering Alpaca across rapid scans.
    Returns {symbol: price}. Missing symbols are omitted.
    """
    global _LATEST_PRICES_CACHE, _LATEST_PRICES_CACHE_TS
    if not symbols:
        return {}
    now_ts = _time.time()
    ttl = float(LATEST_PRICES_CACHE_TTL_SEC)
    if ttl > 0 and _LATEST_PRICES_CACHE and (now_ts - _LATEST_PRICES_CACHE_TS) <= ttl:
        return {s: _LATEST_PRICES_CACHE[s] for s in symbols if s in _LATEST_PRICES_CACHE}

    # Alpaca can rate-limit (429). Do a small bounded retry with backoff to avoid nuking the whole scan.
    backoffs = [0.15, 0.35, 0.75]  # total <= ~1.25s
    last_err: str | None = None

    for attempt, sleep_s in enumerate([0.0] + backoffs):
        if sleep_s:
            _time.sleep(sleep_s)
        try:
            req = StockLatestTradeRequest(symbol_or_symbols=symbols)
            latest = data_client.get_stock_latest_trade(req)
            out: dict[str, float] = {}
            for sym, trade in (latest or {}).items():
                px = None
                try:
                    px = getattr(trade, "price", None)
                    if px is None and isinstance(trade, dict):
                        px = trade.get("price")
                except Exception:
                    px = None
                if px is not None:
                    out[str(sym)] = float(px)

            # Update cache even if partial; it still reduces load next pass.
            _LATEST_PRICES_CACHE = out
            _LATEST_PRICES_CACHE_TS = _time.time()
            return out
        except Exception as e:
            s = str(e)
            last_err = s
            # Detect rate limit in a few common forms.
            if ("too many requests" in s.lower()) or ("429" in s):
                logger.warning("LATEST_PRICES_BATCH_RATE_LIMIT attempt=%s err=%s", attempt, s)
                continue
            logger.warning("LATEST_PRICES_BATCH_ERROR attempt=%s err=%s", attempt, s)
            break

    logger.warning("LATEST_PRICES_BATCH_GIVEUP err=%s", last_err)
    return {}
def get_position(symbol: str):
    """Returns (qty_signed, side_str) where side_str is 'long'/'short'. If none, (0,'flat')."""
    try:
        pos = trading_client.get_open_position(symbol)
        q = float(pos.qty)
        if q > 0:
            return q, "long"
        if q < 0:
            return q, "short"
        return 0.0, "flat"
    except Exception:
        return 0.0, "flat"


def _order_attr(order, key: str, default=None):
    if isinstance(order, dict):
        return order.get(key, default)
    return getattr(order, key, default)


def _alpaca_trading_base_url() -> str:
    return "https://paper-api.alpaca.markets" if APCA_PAPER else "https://api.alpaca.markets"


def _alpaca_get_orders_rest(status: str = "all", limit: int = 100, symbols: list[str] | None = None, after_iso: str | None = None) -> list[dict]:
    params = {"status": str(status or "all"), "limit": str(max(1, min(int(limit or 100), 500))), "direction": "desc", "nested": "true"}
    if symbols:
        syms = [str(s or "").upper() for s in symbols if str(s or "").upper()]
        if syms:
            params["symbols"] = ",".join(syms)
    if after_iso:
        params["after"] = str(after_iso)
    qs = urlencode(params)
    req = UrlRequest(
        _alpaca_trading_base_url().rstrip("/") + "/v2/orders?" + qs,
        headers={
            "accept": "application/json",
            "APCA-API-KEY-ID": APCA_KEY,
            "APCA-API-SECRET-KEY": APCA_SECRET,
        },
        method="GET",
    )
    try:
        with urlopen(req, timeout=20) as resp:
            raw = resp.read().decode("utf-8") if resp else ""
        data = json.loads(raw) if raw else []
        return data if isinstance(data, list) else []
    except Exception:
        return []


def _find_recent_exit_fill_for_symbol(symbol: str, side: str, after_iso: str | None = None) -> dict:
    sym = str(symbol or "").upper()
    want_side = str(side or "").lower()
    if not sym or want_side not in {"buy", "sell"}:
        return {}
    orders = _alpaca_get_orders_rest(status="all", limit=200, symbols=[sym], after_iso=after_iso)
    best = {}
    for order in orders:
        try:
            osym = str(_order_attr(order, "symbol", "") or "").upper()
            if osym != sym:
                continue
            ostatus = str(getattr(_order_attr(order, "status", None), "value", _order_attr(order, "status", "")) or "").lower()
            if ostatus not in {"filled", "partially_filled"}:
                continue
            oside = str(getattr(_order_attr(order, "side", None), "value", _order_attr(order, "side", "")) or "").lower()
            if oside != want_side:
                continue
            filled_qty = _safe_float(_order_attr(order, "filled_qty", 0.0) or 0.0)
            filled_avg_price = _safe_float(_order_attr(order, "filled_avg_price", 0.0) or 0.0)
            if filled_qty <= 0 or filled_avg_price <= 0:
                continue
            candidate = {
                "id": str(_order_attr(order, "id", "") or ""),
                "symbol": sym,
                "side": oside,
                "status": ostatus,
                "filled_qty": filled_qty,
                "filled_avg_price": filled_avg_price,
                "filled_at": str(_order_attr(order, "filled_at", "") or _order_attr(order, "updated_at", "") or _order_attr(order, "submitted_at", "") or ""),
                "submitted_at": str(_order_attr(order, "submitted_at", "") or ""),
            }
            if not best or str(candidate.get("filled_at") or candidate.get("submitted_at") or "") > str(best.get("filled_at") or best.get("submitted_at") or ""):
                best = candidate
        except Exception:
            continue
    return best


def _strategy_closed_trade_already_recorded(plan: dict | None, exit_price: float | None = None, tolerance_sec: int = 600) -> bool:
    plan = dict(plan or {})
    symbol = str(plan.get("symbol") or plan.get("instrument") or "").upper()
    strategy_name = str(plan.get("strategy_name") or plan.get("signal") or "").strip().lower()
    entry_price = round(_safe_float(plan.get("entry_price") or plan.get("avg_fill_price") or 0.0), 4)
    qty = round(abs(_safe_float(plan.get("filled_qty") or plan.get("qty") or 0.0)), 4)
    exit_px = round(_safe_float(exit_price or 0.0), 4)
    now_utc = datetime.now(timezone.utc)
    for row in list((STRATEGY_PERFORMANCE_STATE or {}).get("closed_trades") or []):
        try:
            if symbol and str(row.get("symbol") or "").upper() != symbol:
                continue
            if strategy_name and str(row.get("strategy_name") or "").strip().lower() != strategy_name:
                continue
            if entry_price > 0 and abs(round(_safe_float(row.get("entry_price") or 0.0), 4) - entry_price) > 0.01:
                continue
            if qty > 0 and abs(round(abs(_safe_float(row.get("qty") or 0.0)), 4) - qty) > 0.01:
                continue
            if exit_px > 0 and abs(round(_safe_float(row.get("exit_price") or 0.0), 4) - exit_px) > 0.05:
                continue
            ts_raw = str(row.get("ts_utc") or "")
            ts = None
            if ts_raw:
                try:
                    ts = datetime.fromisoformat(ts_raw.replace("Z", "+00:00"))
                except Exception:
                    ts = None
            if ts is not None and abs((now_utc - ts).total_seconds()) > max(1, int(tolerance_sec or 0)):
                continue
            return True
        except Exception:
            continue
    return False


def _reconcile_manual_exit_plan(plan: dict | None, symbol: str, source: str = "broker_reconcile") -> dict:
    plan = dict(plan or {})
    sym = str(symbol or plan.get("symbol") or "").upper()
    if not sym:
        return {"ok": False, "reason": "missing_symbol"}
    entry_side = str(plan.get("side") or "buy").strip().lower() or "buy"
    exit_side = "sell" if entry_side == "buy" else "buy"
    after_iso = str(plan.get("submitted_at") or plan.get("opened_at") or plan.get("recovered_at") or "").strip() or None
    order = _find_recent_exit_fill_for_symbol(sym, exit_side, after_iso=after_iso)
    exit_px = _safe_float((order or {}).get("filled_avg_price") or 0.0)
    if exit_px <= 0:
        try:
            exit_px = _safe_float(get_latest_price(sym) or 0.0)
        except Exception:
            exit_px = 0.0
    if exit_px <= 0:
        return {"ok": False, "reason": "no_exit_price"}
    return {"ok": True, "reason": "patch154_quarantined", "exit_price": round(exit_px, 4), "closed_trade_recorded": False, "order_id": str((order or {}).get("id") or "")}


def _valid_strategy_identity(value: object) -> str:
    text = str(value or "").strip()
    lowered = text.lower()
    if not text or lowered in {"recovered", "recovered_open_order", "broker_position", "unknown", "none", "null"}:
        return ""
    return lowered


def _candidate_attribution_meta(row: dict | None, source: str = "") -> dict:
    row = dict(row or {})
    strategy = _valid_strategy_identity(row.get("strategy") or row.get("strategy_name") or row.get("signal"))
    signal = _valid_strategy_identity(row.get("signal") or row.get("strategy") or row.get("strategy_name")) or strategy
    if not strategy and not signal:
        return {}
    return {
        "strategy_name": strategy or signal,
        "signal": signal or strategy,
        "rank_score": row.get("rank_score"),
        "selection_quality_score": row.get("selection_quality_score"),
        "entry_type": row.get("entry_type"),
        "regime_mode": row.get("regime_mode"),
        "breakout_level": row.get("breakout_level"),
        "stop_price": row.get("stop_price"),
        "take_price": row.get("take_price") or row.get("target_price"),
        "target_price": row.get("target_price") or row.get("take_price"),
        "risk_per_share": row.get("risk_per_share"),
        "scan_ts": row.get("scan_ts_utc") or row.get("ts_utc"),
        "attribution_source": source,
    }


def _merge_attribution_meta(base: dict | None, extra: dict | None) -> dict:
    merged = dict(base or {})
    for key, val in dict(extra or {}).items():
        if val in (None, "", [], {}):
            continue
        if key in {"signal", "strategy_name"}:
            val = _valid_strategy_identity(val)
            if not val:
                continue
        if merged.get(key) in (None, "", [], {}) or key in {"signal", "strategy_name", "attribution_source"}:
            merged[key] = val
    return merged


def _infer_recovered_plan_attribution(symbol: str, order_id: str = "") -> dict:
    sym = str(symbol or "").strip().upper()
    order_id = str(order_id or "").strip()
    if not sym:
        return {}
    # Highest confidence: entry decisions persisted with order id / selected scanner metadata.
    decision_rows = [dict(r or {}) for r in list(DECISIONS or [])]
    decision_rows.extend(_read_journal(limit=JOURNAL_BOOTSTRAP_LIMIT, symbol=sym))
    for row in reversed(decision_rows):
        if str(row.get("symbol") or "").strip().upper() != sym:
            continue
        if str(row.get("event") or "").upper() not in {"ENTRY", "CANDIDATE", "SCAN"}:
            continue
        details = dict(row.get("details") or {})
        row_order_id = str(details.get("order_id") or row.get("order_id") or "").strip()
        if order_id and row_order_id and row_order_id != order_id:
            continue
        meta = dict(details.get("meta") or {}) if isinstance(details.get("meta"), dict) else {}
        candidate = dict(meta.get("candidate") or {}) if isinstance(meta.get("candidate"), dict) else {}
        inferred = _candidate_attribution_meta(candidate, "decision_candidate")
        inferred = _merge_attribution_meta(inferred, _candidate_attribution_meta(meta, "decision_meta"))
        inferred = _merge_attribution_meta(inferred, _candidate_attribution_meta(row, "decision_row"))
        if inferred:
            return inferred

    # Lifecycle history often has entry submitted/selected events with signal details.
    events = list(PAPER_LIFECYCLE_HISTORY or [])
    if LAST_PAPER_LIFECYCLE and (not events or events[-1] != LAST_PAPER_LIFECYCLE):
        events.append(dict(LAST_PAPER_LIFECYCLE))
    for ev in reversed(events):
        if str((ev or {}).get("symbol") or "").strip().upper() != sym:
            continue
        details = dict((ev or {}).get("details") or {})
        inferred = _candidate_attribution_meta(details, "paper_lifecycle")
        if inferred:
            return inferred

    # Scanner/candidate state survives restarts and contains selected rows.
    for hist in reversed(list(CANDIDATE_HISTORY or [])):
        if not isinstance(hist, dict):
            continue
        rows = list(hist.get("candidates") or []) + list(hist.get("adaptive_capacity_candidates") or []) + list(hist.get("shadow_candidates") or [])
        selected = {str(x or "").upper() for x in (hist.get("selected") or [])}
        for row in rows:
            if not isinstance(row, dict) or str(row.get("symbol") or "").upper() != sym:
                continue
            inferred = _candidate_attribution_meta(row, "candidate_history_selected" if sym in selected else "candidate_history")
            inferred = _merge_attribution_meta({"regime_mode": hist.get("regime_mode"), "scan_ts": hist.get("ts_utc")}, inferred)
            if inferred:
                return inferred

    for row in reversed(list(LAST_SWING_CANDIDATES or [])):
        if not isinstance(row, dict) or str(row.get("symbol") or "").upper() != sym:
            continue
        inferred = _candidate_attribution_meta(row, "last_swing_candidates")
        if inferred:
            return inferred

    for scan in reversed(list(SCAN_HISTORY or [])):
        if not isinstance(scan, dict):
            continue
        rows = list(scan.get("would_submit") or []) + list(scan.get("results") or []) + list((scan.get("summary") or {}).get("top_candidates") or [])
        for row in rows:
            if not isinstance(row, dict) or str(row.get("symbol") or "").upper() != sym:
                continue
            inferred = _candidate_attribution_meta(row, "scan_history")
            if inferred:
                return inferred
    return {"strategy_name": BREAKOUT_STRATEGY_NAME, "signal": BREAKOUT_STRATEGY_NAME, "attribution_source": "fallback_breakout"}


def _infer_strategy_name_for_symbol(symbol: str) -> str:
    meta = _infer_recovered_plan_attribution(symbol)
    return _valid_strategy_identity(meta.get("strategy_name") or meta.get("signal")) or BREAKOUT_STRATEGY_NAME


def _apply_recovered_plan_attribution(plan: dict | None, symbol: str = "", order_id: str = "") -> dict:
    plan = dict(plan or {})
    inferred = _infer_recovered_plan_attribution(symbol or plan.get("symbol"), order_id or plan.get("order_id"))
    strategy = _valid_strategy_identity(inferred.get("strategy_name") or inferred.get("signal"))
    signal = _valid_strategy_identity(inferred.get("signal") or inferred.get("strategy_name"))
    if not strategy and not signal:
        return plan
    original_signal = str(plan.get("recovered_original_signal") or plan.get("signal") or "")
    original_strategy = str(plan.get("recovered_original_strategy_name") or plan.get("strategy_name") or "")
    plan["recovered_original_signal"] = original_signal
    plan["recovered_original_strategy_name"] = original_strategy
    plan["signal"] = signal or strategy
    plan["strategy_name"] = strategy or signal
    for key in ["rank_score", "selection_quality_score", "entry_type", "regime_mode"]:
        if plan.get(key) in (None, "", [], {}) and inferred.get(key) not in (None, "", [], {}):
            plan[key] = inferred.get(key)
    thesis = dict(plan.get("thesis") or {})
    for key, target in [("rank_score", "candidate_rank_score"), ("selection_quality_score", "selection_quality_score"), ("entry_type", "entry_type"), ("regime_mode", "regime_mode"), ("breakout_level", "breakout_level")]:
        if thesis.get(target) in (None, "", [], {}) and inferred.get(key) not in (None, "", [], {}):
            thesis[target] = inferred.get(key)
    if inferred.get("scan_ts") and thesis.get("candidate_ts") in (None, "", [], {}):
        thesis["candidate_ts"] = inferred.get("scan_ts")
    if thesis:
        plan["thesis"] = thesis
    plan["attribution_backfilled"] = True
    plan["attribution_source"] = inferred.get("attribution_source") or "recovered_backfill"
    return plan
    

def _find_recent_entry_fill_for_symbol(symbol: str, side: str, before_iso: str | None = None) -> dict:
    sym = str(symbol or '').upper()
    want_side = str(side or '').lower()
    if not sym or want_side not in {'buy', 'sell'}:
        return {}
    orders = _alpaca_get_orders_rest(status='all', limit=300, symbols=[sym])
    best = {}
    for order in orders:
        try:
            osym = str(_order_attr(order, 'symbol', '') or '').upper()
            if osym != sym:
                continue
            ostatus = str(getattr(_order_attr(order, 'status', None), 'value', _order_attr(order, 'status', '')) or '').lower()
            if ostatus not in {'filled', 'partially_filled'}:
                continue
            oside = str(getattr(_order_attr(order, 'side', None), 'value', _order_attr(order, 'side', '')) or '').lower()
            if oside != want_side:
                continue
            filled_at = str(_order_attr(order, 'filled_at', '') or _order_attr(order, 'updated_at', '') or _order_attr(order, 'submitted_at', '') or '')
            if before_iso and filled_at and filled_at > str(before_iso):
                continue
            filled_qty = _safe_float(_order_attr(order, 'filled_qty', 0.0) or 0.0)
            filled_avg_price = _safe_float(_order_attr(order, 'filled_avg_price', 0.0) or 0.0)
            if filled_qty <= 0 or filled_avg_price <= 0:
                continue
            candidate = {
                'id': str(_order_attr(order, 'id', '') or ''),
                'symbol': sym,
                'side': oside,
                'status': ostatus,
                'filled_qty': filled_qty,
                'filled_avg_price': filled_avg_price,
                'filled_at': filled_at,
                'submitted_at': str(_order_attr(order, 'submitted_at', '') or ''),
            }
            if not best or str(candidate.get('filled_at') or candidate.get('submitted_at') or '') > str(best.get('filled_at') or best.get('submitted_at') or ''):
                best = candidate
        except Exception:
            continue
    return best


