def _p424_record_broker_transport_shadow_hook(
    *,
    symbol: str,
    side: str,
    qty: float,
    order_type: str,
    client_order_id: str,
    limit_price: float | None = None,
) -> dict:
    shadow = broker_transport_shadow_parity_hook(
        symbol=symbol,
        side=side,
        qty=qty,
        order_type=order_type,
        client_order_id=client_order_id,
        limit_price=limit_price,
        production_submit_uses_transport=False,
    )
    shadow["patch_version"] = PATCH_VERSION
    shadow["recorded_utc"] = datetime.now(timezone.utc).isoformat()
    try:
        BROKER_TRANSPORT_SHADOW_HOOK_LAST.clear()
        BROKER_TRANSPORT_SHADOW_HOOK_LAST.update(dict(shadow))
    except Exception:
        pass
    return shadow

def _alpaca_submit_order_rest(symbol: str, side: str, qty: float, client_order_id: str):
    body = swing_exec_build_market_order_payload(symbol, side, qty, client_order_id)
    req = UrlRequest(
        _alpaca_trading_base_url().rstrip("/") + "/v2/orders",
        data=json.dumps(body).encode("utf-8"),
        headers={
            "accept": "application/json",
            "content-type": "application/json",
            "APCA-API-KEY-ID": APCA_KEY,
            "APCA-API-SECRET-KEY": APCA_SECRET,
        },
        method="POST",
    )
    with urlopen(req, timeout=20) as resp:
        raw = resp.read().decode("utf-8") if resp else ""
    data = json.loads(raw) if raw else {}
    if not isinstance(data, dict):
        raise RuntimeError("alpaca_rest_submit_non_dict_response")
    if not data.get("id"):
        raise RuntimeError(f"alpaca_rest_submit_missing_id:{data}")
    data.setdefault("_submit_transport", "rest_fallback")
    data.setdefault("client_order_id", client_order_id)
    return data

def _alpaca_submit_limit_order_rest(symbol: str, side: str, qty: float, limit_price: float, client_order_id: str):
    body = swing_exec_build_limit_order_payload(symbol, side, qty, limit_price, client_order_id)
    req = UrlRequest(
        _alpaca_trading_base_url().rstrip("/") + "/v2/orders",
        data=json.dumps(body).encode("utf-8"),
        headers={
            "accept": "application/json",
            "content-type": "application/json",
            "APCA-API-KEY-ID": APCA_KEY,
            "APCA-API-SECRET-KEY": APCA_SECRET,
        },
        method="POST",
    )
    with urlopen(req, timeout=20) as resp:
        raw = resp.read().decode("utf-8") if resp else ""
    data = json.loads(raw) if raw else {}
    if not isinstance(data, dict):
        raise RuntimeError("alpaca_rest_limit_submit_non_dict_response")
    if not data.get("id"):
        raise RuntimeError(f"alpaca_rest_limit_submit_missing_id:{data}")
    data.setdefault("_submit_transport", "rest_limit")
    data.setdefault("client_order_id", client_order_id)
    return data

