def list_open_orders_safe(limit: int | None = None) -> list[dict]:
    lim = max(1, min(int(limit or RECONCILE_ORDER_LOOKBACK_LIMIT), 500))
    try:
        orders = trading_client.get_orders()
    except Exception:
        return []
    out: list[dict] = []
    active = {"new", "accepted", "pending_new", "partially_filled", "pending_replace", "accepted_for_bidding", "held"}
    for order in list(orders or []):
        try:
            status = str(getattr(getattr(order, "status", None), "value", getattr(order, "status", "")) or "").lower()
            if status and status not in active:
                continue
            rec = {
                "id": str(getattr(order, "id", "") or ""),
                "symbol": str(_order_attr(order, "symbol", "") or "").upper(),
                "side": str(getattr(getattr(order, "side", None), "value", getattr(order, "side", "")) or ""),
                "status": status,
                "type": str(getattr(getattr(order, "type", None), "value", getattr(order, "type", "")) or ""),
                "qty": str(getattr(order, "qty", "") or ""),
                "filled_qty": str(_order_attr(order, "filled_qty", "") or ""),
                "submitted_at": str(_order_attr(order, "submitted_at", "") or ""),
            }
            out.append(rec)
        except Exception:
            continue
    out.sort(key=lambda x: str(x.get("submitted_at") or ""), reverse=True)
    return out[:lim]


def find_open_order_for_symbol(symbol: str) -> dict:
    sym = str(symbol or "").upper()
    if not sym:
        return {}
    for order in list_open_orders_safe():
        if str(order.get("symbol") or "").upper() == sym:
            return dict(order)
    return {}

def _pending_close_order_for_symbol(symbol: str, close_side: str) -> dict:
    sym = str(symbol or "").upper()
    side = str(close_side or "").lower()
    if not sym or side not in {"buy", "sell"}:
        return {}
    for order in list_open_orders_safe():
        if str((order or {}).get("symbol") or "").upper() == sym and str((order or {}).get("side") or "").lower() == side:
            return dict(order)
    return {}


def _p382_pending_close_qty_for_symbol(symbol: str, close_side: str) -> float:
    sym = str(symbol or "").strip().upper()
    side = str(close_side or "").strip().lower()
    if not sym or side not in {"buy", "sell"}:
        return 0.0

    total = 0.0
    for order in list_open_orders_safe():
        try:
            if str((order or {}).get("symbol") or "").strip().upper() != sym:
                continue
            if str((order or {}).get("side") or "").strip().lower() != side:
                continue
            qty = _safe_float((order or {}).get("qty"), 0.0)
            filled_qty = _safe_float((order or {}).get("filled_qty"), 0.0)
            total += max(0.0, qty - filled_qty)
        except Exception:
            continue
    return _normalize_close_qty(total)

def _normalize_close_qty(qty: float) -> float:
    q = abs(float(qty or 0.0))
    if q <= 0:
        return 0.0
    return float(_format_order_qty(q))

def _p350_broker_qty_exit_clamp(symbol: str, requested_qty: float, close_side: str, reason: str = "", source: str = "") -> dict:
    sym = str(symbol or "").strip().upper()
    close_side = str(close_side or "").strip().lower()
    requested = _normalize_close_qty(requested_qty)

    try:
        broker_qty_signed, _broker_side = get_position(sym)
    except Exception as exc:
        return {
            "ok": False,
            "blocked": True,
            "reason": "broker_qty_lookup_failed",
            "symbol": sym,
            "requested_qty": requested,
            "broker_qty_signed": None,
            "broker_available_qty": 0.0,
            "clamped_qty": 0.0,
            "close_side": close_side,
            "error": str(exc),
        }

    broker_qty_signed = float(_safe_float(broker_qty_signed, 0.0))
    if close_side == "sell":
        broker_available = max(0.0, broker_qty_signed)
    elif close_side == "buy":
        broker_available = max(0.0, abs(min(0.0, broker_qty_signed)))
    else:
        broker_available = 0.0

    clamped = _normalize_close_qty(min(requested, broker_available))
    blocked = clamped <= 0.0

    return {
        "ok": True,
        "blocked": blocked,
        "reason": "exit_blocked_broker_qty_zero" if blocked else ("exit_qty_clamped_to_broker_qty" if clamped < requested else "exit_qty_ok"),
        "symbol": sym,
        "requested_qty": requested,
        "broker_qty_signed": round(broker_qty_signed, 8),
        "broker_available_qty": round(broker_available, 8),
        "clamped_qty": clamped,
        "close_side": close_side,
        "exit_reason": reason or "exit",
        "source": source or "system",
    }


def _p350_record_exit_qty_guard(symbol: str, source: str, reason: str, close_side: str, guard: dict) -> dict:
    sym = str(symbol or "").strip().upper()
    action = str(guard.get("action") or "")
    if not action:
        action = "exit_blocked_broker_qty_zero" if guard.get("blocked") else "exit_qty_clamped_to_broker_qty"
    record_decision(
        "EXIT",
        source or "system",
        sym,
        side=close_side,
        action=action,
        reason=reason or guard.get("reason") or "exit_qty_guard",
        qty=guard.get("clamped_qty") or 0.0,
        meta={"broker_qty_exit_clamp": guard},
    )
    try:
        if isinstance(TRADE_PLAN.get(sym), dict):
            plan_ref = TRADE_PLAN[sym]
            plan_ref["last_exit_qty_guard"] = dict(guard)
            plan_ref["last_exit_qty_guard_at"] = datetime.now(timezone.utc).isoformat()
    except Exception:
        pass
    return {
        "closed": False,
        "symbol": sym,
        "qty": guard.get("clamped_qty") or 0.0,
        "close_side": close_side,
        "reason": guard.get("reason") or action,
        "exit_reason": reason or "exit",
        "broker_qty_exit_clamp": guard,
    }


def _p382_exit_overclose_prevention_guard(
    symbol: str,
    requested_qty: float,
    close_side: str,
    reason: str = "",
    source: str = "",
    plan_ref: dict | None = None,
) -> dict:
    sym = str(symbol or "").strip().upper()
    side = str(close_side or "").strip().lower()
    requested = _normalize_close_qty(requested_qty)
    out = {
        "ok": True,
        "blocked": False,
        "symbol": sym,
        "requested_qty": requested,
        "close_side": side,
        "exit_reason": reason or "exit",
        "source": source or "system",
    }

    if not sym or side not in {"buy", "sell"} or requested <= 0:
        out.update({"blocked": True, "reason": "invalid_exit_overclose_guard_input", "clamped_qty": 0.0})
        return out

    try:
        broker_qty_signed, _broker_side = get_position(sym)
    except Exception as exc:
        out.update({
            "blocked": True,
            "reason": "broker_qty_lookup_failed",
            "broker_qty_signed": None,
            "broker_available_qty": 0.0,
            "pending_close_qty": 0.0,
            "available_after_pending_close": 0.0,
            "clamped_qty": 0.0,
            "error": str(exc),
        })
        return out

    broker_qty_signed = float(_safe_float(broker_qty_signed, 0.0))
    broker_available = max(0.0, broker_qty_signed) if side == "sell" else max(0.0, abs(min(0.0, broker_qty_signed)))
    pending_qty = _p382_pending_close_qty_for_symbol(sym, side)
    available_after_pending = _normalize_close_qty(max(0.0, broker_available - pending_qty))
    clamped_qty = _normalize_close_qty(min(requested, available_after_pending))

    out.update({
        "broker_qty_signed": round(broker_qty_signed, 8),
        "broker_available_qty": round(broker_available, 8),
        "pending_close_qty": pending_qty,
        "available_after_pending_close": available_after_pending,
        "clamped_qty": clamped_qty,
    })

    if clamped_qty <= 0:
        out.update({
            "blocked": True,
            "action": "exit_blocked_overclose_risk",
            "reason": "exit_blocked_overclose_risk",
        })
        return out

    if clamped_qty < requested:
        out.update({
            "blocked": False,
            "action": "exit_qty_clamped_to_available_after_pending_close",
            "reason": "exit_qty_clamped_to_available_after_pending_close",
        })
        return out

    out["reason"] = "exit_overclose_guard_ok"
    return out

def _p373_exit_reason_lockable(reason: str) -> bool:
    reason_l = str(reason or "exit").strip().lower()
    if not reason_l:
        reason_l = "exit"
    return reason_l in SAME_DAY_EXIT_SUBMIT_IDEMPOTENCY_REASONS

def _p373_same_day_exit_lock_key(symbol: str, close_side: str = "") -> str:
    side = str(close_side or "any").strip().lower() or "any"
    return f"{str(symbol or '').strip().upper()}|{side}|{now_ny().date().isoformat()}"

def _p373_same_day_exit_submit_guard(
    symbol: str,
    reason: str = "",
    source: str = "system",
    qty: float | None = None,
    plan_ref: dict | None = None,
    close_side: str = "",
) -> dict:
    sym = str(symbol or "").strip().upper()
    reason_l = str(reason or "exit").strip().lower()
    source_l = str(source or "system").strip().lower()
    close_side_l = str(close_side or "").strip().lower()
    window_sec = max(1, int(SAME_DAY_EXIT_SUBMIT_IDEMPOTENCY_WINDOW_SEC or 900))

    out = {
        "ok": True,
        "enabled": bool(SAME_DAY_EXIT_SUBMIT_IDEMPOTENCY_ENABLED),
        "blocked": False,
        "symbol": sym,
        "reason": reason_l,
        "source": source_l,
        "qty": qty,
        "close_side": close_side_l or None,
        "window_sec": window_sec,
    }

    if not SAME_DAY_EXIT_SUBMIT_IDEMPOTENCY_ENABLED:
        out["status"] = "disabled"
        return out
    if source_l != "worker_exit":
        out["status"] = "source_not_worker_exit"
        return out
    if not _p373_exit_reason_lockable(reason_l):
        out["status"] = "reason_not_lockable"
        return out
    if not sym:
        out["status"] = "missing_symbol"
        return out

    key = _p373_same_day_exit_lock_key(sym, close_side_l)
    now_utc = datetime.now(timezone.utc)
    existing = dict(SAME_DAY_EXIT_SUBMIT_LOCKS.get(key) or {})
    out["lock_key"] = key
    out["existing_lock"] = existing or None

    ts_raw = existing.get("submitted_utc") or existing.get("ts_utc")
    age_sec = None
    try:
        if ts_raw:
            dt = datetime.fromisoformat(str(ts_raw).replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            age_sec = max(0.0, (now_utc - dt.astimezone(timezone.utc)).total_seconds())
    except Exception:
        age_sec = None

    if existing and (age_sec is None or age_sec <= window_sec):
        out.update({
            "blocked": True,
            "status": "same_day_exit_submit_recently_submitted",
            "age_sec": age_sec,
            "prior_order_id": existing.get("order_id"),
            "prior_reason": existing.get("reason"),
        })
        return out

    if isinstance(plan_ref, dict):
        plan_order_id = str(plan_ref.get("last_exit_order_id") or "").strip()
        plan_reason = str(plan_ref.get("last_exit_submit_reason") or "").strip().lower()
        plan_side = str(plan_ref.get("last_exit_submit_side") or "").strip().lower()
        plan_ts = str(plan_ref.get("last_exit_submit_ts_utc") or "").strip()
        plan_age_sec = None
        try:
            if plan_ts:
                dt = datetime.fromisoformat(plan_ts.replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                plan_age_sec = max(0.0, (now_utc - dt.astimezone(timezone.utc)).total_seconds())
        except Exception:
            plan_age_sec = None

        if (
            plan_order_id
            and _p373_exit_reason_lockable(plan_reason or reason_l)
            and (not close_side_l or not plan_side or plan_side == close_side_l)
            and (plan_age_sec is None or plan_age_sec <= window_sec)
        ):
            out.update({
                "blocked": True,
                "status": "plan_exit_submit_recently_submitted",
                "age_sec": plan_age_sec,
                "prior_order_id": plan_order_id,
                "prior_reason": plan_reason or reason_l,
            })
            return out

    out["status"] = "allowed"
    return out


def _p373_mark_same_day_exit_submit_lock(
    symbol: str,
    reason: str = "",
    source: str = "system",
    qty: float | None = None,
    order_id: str = "",
    plan_ref: dict | None = None,
    close_side: str = "",
) -> dict:
    sym = str(symbol or "").strip().upper()
    reason_l = str(reason or "exit").strip().lower()
    close_side_l = str(close_side or "").strip().lower()
    key = _p373_same_day_exit_lock_key(sym, close_side_l)
    row = {
        "symbol": sym,
        "reason": reason_l,
        "source": str(source or "system"),
        "qty": qty,
        "close_side": close_side_l or None,
        "order_id": str(order_id or ""),
        "submitted_utc": datetime.now(timezone.utc).isoformat(),
        "submitted_ny": now_ny().isoformat(),
        "patch_version": PATCH_VERSION,
    }
    SAME_DAY_EXIT_SUBMIT_LOCKS[key] = row

    try:
        if isinstance(plan_ref, dict):
            plan_ref["last_exit_submit_reason"] = reason_l
            plan_ref["last_exit_submit_side"] = close_side_l or None
            plan_ref["last_exit_submit_ts_utc"] = row["submitted_utc"]
            plan_ref["last_exit_submit_idempotency_key"] = key
    except Exception:
        pass

    try:
        persist_scan_runtime_state(reason="same_day_exit_submit_lock")
    except Exception:
        pass

    return row


def _p373_record_exit_submit_idempotency_block(
    symbol: str,
    source: str,
    reason: str,
    close_side: str,
    qty: float,
    guard: dict,
) -> dict:
    sym = str(symbol or "").strip().upper()
    record_decision(
        "EXIT",
        source or "system",
        sym,
        side=close_side,
        action="exit_submit_blocked_same_day_idempotency",
        reason=reason or "same_day_exit_submit_idempotency",
        qty=qty,
        order_id=str(guard.get("prior_order_id") or ""),
        meta={"same_day_exit_submit_idempotency": guard},
    )
    try:
        if isinstance(TRADE_PLAN.get(sym), dict):
            TRADE_PLAN[sym]["last_exit_submit_idempotency_block"] = dict(guard)
            TRADE_PLAN[sym]["last_exit_submit_idempotency_block_at"] = datetime.now(timezone.utc).isoformat()
    except Exception:
        pass

    return {
        "closed": False,
        "blocked": True,
        "symbol": sym,
        "qty": qty,
        "close_side": close_side,
        "reason": "same_day_exit_submit_idempotency",
        "exit_reason": reason or "exit",
        "same_day_exit_submit_idempotency": guard,
    }


def _p373_same_day_exit_submit_lock_truth(limit: int = 20) -> dict:
    limit = max(1, min(int(limit or 20), 50))
    today = now_ny().date().isoformat()
    rows = []
    for key, row in list(SAME_DAY_EXIT_SUBMIT_LOCKS.items()):
        if not isinstance(row, dict):
            continue
        if not str(key or "").endswith(f"|{today}"):
            continue
        rows.append(dict(row, lock_key=key))

    active_plan_rows = []
    for sym, plan in list(TRADE_PLAN.items()):
        if not isinstance(plan, dict):
            continue
        if not str(plan.get("last_exit_submit_idempotency_key") or plan.get("last_exit_order_id") or "").strip():
            continue
        active_plan_rows.append({
            "symbol": str(sym or "").upper(),
            "active": bool(plan.get("active")),
            "last_exit_order_id": plan.get("last_exit_order_id"),
            "last_exit_submit_reason": plan.get("last_exit_submit_reason"),
            "last_exit_submit_ts_utc": plan.get("last_exit_submit_ts_utc"),
            "last_exit_submit_idempotency_key": plan.get("last_exit_submit_idempotency_key"),
            "last_exit_submit_idempotency_block": plan.get("last_exit_submit_idempotency_block"),
        })

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "same_day_exit_submit_lock_truth",
        "read_only": True,
        "enabled": bool(SAME_DAY_EXIT_SUBMIT_IDEMPOTENCY_ENABLED),
        "window_sec": int(SAME_DAY_EXIT_SUBMIT_IDEMPOTENCY_WINDOW_SEC or 900),
        "lockable_reasons": sorted(SAME_DAY_EXIT_SUBMIT_IDEMPOTENCY_REASONS),
        "today_ny": today,
        "lock_count": len(rows),
        "locks": rows[-limit:],
        "active_plan_exit_submit_markers": active_plan_rows[-limit:],
        "recommended_action": "ok" if rows else "watch_next_worker_exit_cycle_for_lock_evidence",
    }


