def _p376_parse_utc_dt(value) -> datetime | None:
    try:
        if value is None:
            return None
        if isinstance(value, datetime):
            dt = value
        else:
            text = str(value or "").strip()
            if not text:
                return None
            dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return None


def _p376_bar_ts_utc(bar: dict | None) -> datetime | None:
    bar = dict(bar or {})
    for key in ("ts_utc", "timestamp", "t", "time", "start"):
        dt = _p376_parse_utc_dt(bar.get(key))
        if dt:
            return dt
    return None


def _p376_entry_window_metrics(symbol: str, entry_ts_utc: str, entry_price: float, side: str = "buy") -> dict:
    sym = str(symbol or "").strip().upper()
    entry_dt = _p376_parse_utc_dt(entry_ts_utc)
    entry_px = _safe_float(entry_price, 0.0)
    side_l = str(side or "buy").strip().lower()

    out = {
        "ok": False,
        "symbol": sym,
        "entry_ts_utc": entry_ts_utc,
        "entry_price": round(entry_px, 4) if entry_px > 0 else None,
        "side": side_l,
        "windows": {},
        "reason": "",
    }

    if not sym or not entry_dt or entry_px <= 0:
        out["reason"] = "missing_entry_context"
        return out

    try:
        bars = fetch_1m_bars(sym, lookback_days=2, limit=3000, feed_override=_DATA_FEED_RAW or "iex")
    except Exception as exc:
        out["reason"] = "bar_fetch_error"
        out["error"] = str(exc)
        return out

    normalized = []
    for raw in list(bars or []):
        bar = dict(raw or {})
        ts = _p376_bar_ts_utc(bar)
        if not ts or ts < entry_dt:
            continue
        close = _safe_float(bar.get("close"), 0.0)
        high = _safe_float(bar.get("high"), close)
        low = _safe_float(bar.get("low"), close)
        if close <= 0:
            continue
        normalized.append({"ts_utc": ts, "close": close, "high": high, "low": low})

    out["bar_count_after_entry"] = len(normalized)
    if not normalized:
        out["reason"] = "no_bars_after_entry"
        return out

    for minutes in (15, 30, 60):
        end_dt = entry_dt + timedelta(minutes=minutes)
        window = [b for b in normalized if b["ts_utc"] <= end_dt]
        if not window:
            out["windows"][f"{minutes}m"] = {"available": False}
            continue

        min_low = min(_safe_float(b.get("low"), 0.0) for b in window)
        max_high = max(_safe_float(b.get("high"), 0.0) for b in window)
        last_close = _safe_float(window[-1].get("close"), 0.0)

        if side_l == "sell":
            adverse_pct = ((max_high - entry_px) / entry_px) * -100.0
            favorable_pct = ((entry_px - min_low) / entry_px) * 100.0
        else:
            adverse_pct = ((min_low - entry_px) / entry_px) * 100.0
            favorable_pct = ((max_high - entry_px) / entry_px) * 100.0

        out["windows"][f"{minutes}m"] = {
            "available": True,
            "bars": len(window),
            "min_low": round(min_low, 4),
            "max_high": round(max_high, 4),
            "last_close": round(last_close, 4),
            "adverse_pct": round(adverse_pct, 4),
            "favorable_pct": round(favorable_pct, 4),
            "close_return_pct": round(((last_close - entry_px) / entry_px) * 100.0, 4) if entry_px > 0 else None,
        }

    first_15 = dict(out["windows"].get("15m") or {})
    first_30 = dict(out["windows"].get("30m") or {})
    adverse_15 = _safe_float(first_15.get("adverse_pct"), 0.0)
    adverse_30 = _safe_float(first_30.get("adverse_pct"), 0.0)

    flags = []
    if first_15.get("available") and adverse_15 <= -1.00:
        flags.append("first_15m_adverse_move_gt_1pct")
    if first_30.get("available") and adverse_30 <= -1.50:
        flags.append("first_30m_adverse_move_gt_1_5pct")
    if first_15.get("available") and _safe_float(first_15.get("favorable_pct"), 0.0) < 0.25:
        flags.append("no_early_followthrough")

    out["ok"] = True
    out["reason"] = "ok"
    out["flags"] = flags
    out["kill_zone_triggered"] = bool(flags)
    return out


def _p376_classify_entry_loss(row: dict, entry_quality: dict, kill_zone: dict) -> list[str]:
    reasons = []
    pnl = _safe_float(row.get("gross_pnl"), 0.0)
    rank_score = _safe_float(entry_quality.get("rank_score") or entry_quality.get("candidate_rank_score"), 0.0)
    target_path_score = _safe_float(entry_quality.get("target_path_score"), 0.0)
    risk_per_share_pct = _safe_float(entry_quality.get("risk_per_share_pct"), 0.0)

    if pnl < 0:
        reasons.append("broker_realized_loss")
    if bool(kill_zone.get("kill_zone_triggered")):
        reasons.append("entry_kill_zone_triggered")
    if "no_early_followthrough" in list(kill_zone.get("flags") or []):
        reasons.append("no_early_followthrough")
    if rank_score > 0 and rank_score < 110:
        reasons.append("rank_score_soft")
    if target_path_score > 0 and target_path_score < 55:
        reasons.append("target_path_score_soft")
    if risk_per_share_pct > 0.18:
        reasons.append("wide_risk_per_share")
    if not entry_quality:
        reasons.append("entry_quality_missing")
    return _dedupe_keep_order(reasons)


def _p376_same_day_breakout_loss_forensics(limit: int = 20) -> dict:
    limit = max(1, min(int(limit or 20), 50))
    broker_truth = _p374_broker_only_daily_loss_truth()
    pnl_truth = today_pnl_truth_snapshot()
    broker_orders = dict(pnl_truth.get("broker_orders_today") or {})
    broker_rows = [
        dict(r or {})
        for r in list(broker_orders.get("rows") or [])
        if isinstance(r, dict)
        and bool(r.get("calc_ok"))
        and str(r.get("symbol") or "").strip()
    ]

    rows = []
    for row in broker_rows:
        sym = str(row.get("symbol") or "").strip().upper()
        gross = _safe_float(row.get("gross_pnl"), 0.0)
        entry_px = _safe_float(row.get("entry_price"), 0.0)
        exit_px = _safe_float(row.get("exit_price"), 0.0)
        entry_order_id = str(row.get("entry_order_id") or "").strip()
        exit_order_id = str(row.get("exit_order_id") or "").strip()
        exit_ts = str(row.get("ts_utc") or "")

        inferred = _infer_recovered_plan_attribution(sym, order_id=entry_order_id)
        entry_quality = {
            "strategy_name": inferred.get("strategy_name"),
            "signal": inferred.get("signal"),
            "rank_score": inferred.get("rank_score"),
            "selection_quality_score": inferred.get("selection_quality_score"),
            "entry_type": inferred.get("entry_type"),
            "regime_mode": inferred.get("regime_mode"),
            "target_path_score": inferred.get("target_path_score"),
            "target_path_profit": inferred.get("target_path_profit"),
            "breakout_level": inferred.get("breakout_level"),
            "scan_ts": inferred.get("scan_ts"),
            "attribution_source": inferred.get("attribution_source"),
        }

        entry_fill = _find_recent_entry_fill_for_symbol(sym, "buy", before_iso=exit_ts)
        entry_ts = str(entry_fill.get("filled_at") or entry_fill.get("submitted_at") or inferred.get("entry_ts_utc") or inferred.get("scan_ts") or "")
        kill_zone = _p376_entry_window_metrics(sym, entry_ts, entry_px, side="buy")

        strategy_name = str(entry_quality.get("strategy_name") or row.get("strategy_name") or "").strip().lower()
        is_breakout = strategy_name in {"daily_breakout", BREAKOUT_STRATEGY_NAME.lower()} or str(row.get("strategy_name") or "").strip().lower() == "daily_breakout"

        item = {
            "symbol": sym,
            "strategy_name": strategy_name or row.get("strategy_name"),
            "is_breakout": bool(is_breakout),
            "broker_realized_loss": bool(gross < 0),
            "gross_pnl": round(gross, 4),
            "entry_price": round(entry_px, 4) if entry_px > 0 else None,
            "exit_price": round(exit_px, 4) if exit_px > 0 else None,
            "entry_order_id": entry_order_id,
            "exit_order_id": exit_order_id,
            "entry_ts_utc": entry_ts,
            "exit_ts_utc": exit_ts,
            "entry_quality": entry_quality,
            "kill_zone": kill_zone,
        }
        item["classification"] = _p376_classify_entry_loss(item | row, entry_quality, kill_zone)
        rows.append(item)

    loss_rows = [r for r in rows if bool(r.get("broker_realized_loss"))]
    breakout_loss_rows = [r for r in loss_rows if bool(r.get("is_breakout"))]
    kill_zone_rows = [r for r in rows if bool((r.get("kill_zone") or {}).get("kill_zone_triggered"))]

    class_counts = Counter()
    for row in rows:
        class_counts.update(list(row.get("classification") or []))

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "same_day_breakout_loss_forensics_entry_quality_kill_zone_audit",
        "read_only": True,
        "canonical_daily_loss_source": "broker_only_daily_loss_truth",
        "broker_only_daily_loss_truth": {
            "today_realized_pnl": broker_truth.get("today_realized_pnl"),
            "today_unrealized_pnl": broker_truth.get("today_unrealized_pnl"),
            "today_net_pnl": broker_truth.get("today_net_pnl"),
            "account_daily_pnl": broker_truth.get("account_daily_pnl"),
            "strategy_state_vs_broker_only_today_delta": broker_truth.get("strategy_state_vs_broker_only_today_delta"),
        },
        "summary": {
            "broker_exit_rows_evaluated": len(rows),
            "broker_loss_rows": len(loss_rows),
            "breakout_loss_rows": len(breakout_loss_rows),
            "kill_zone_triggered_rows": len(kill_zone_rows),
            "class_counts": [{"reason": k, "count": int(v)} for k, v in class_counts.most_common()],
            "symbols": sorted({str(r.get("symbol") or "") for r in rows if str(r.get("symbol") or "")}),
            "loss_symbols": sorted({str(r.get("symbol") or "") for r in loss_rows if str(r.get("symbol") or "")}),
        },
        "rows": rows[-limit:],
        "recommended_action": (
            "review_entry_kill_zone_and_breakout_selection_quality"
            if breakout_loss_rows or kill_zone_rows
            else "no_same_day_breakout_loss_rows_detected"
        ),
    }

def _p377_candidate_float(row: dict, *keys, default: float = 0.0) -> float:
    row = dict(row or {})
    pools = [
        row,
        dict(row.get("thesis") or {}),
        dict(row.get("swing_production_contract") or {}),
        dict(row.get("checks") or {}),
    ]
    for pool in pools:
        for key in keys:
            raw = pool.get(key)
            if raw is None or raw == "":
                continue
            val = _safe_float(raw, 0.0)
            if val != 0:
                return float(val)
    return float(default)

def _p377_is_breakout_candidate(row: dict) -> bool:
    row = dict(row or {})
    strategy = str(
        row.get("strategy")
        or row.get("strategy_name")
        or row.get("signal")
        or (row.get("thesis") or {}).get("strategy_name")
        or (row.get("thesis") or {}).get("signal")
        or ""
    ).strip().lower()
    return strategy in {"daily_breakout", str(BREAKOUT_STRATEGY_NAME or "").strip().lower()}


def _p377_breakout_early_follow_through_gate(row: dict | None) -> dict:
    row = dict(row or {})
    sym = str(row.get("symbol") or "").strip().upper()
    entry_type = str(row.get("entry_type") or row.get("selected_source") or "").strip()
    scoped_entry_type = entry_type

    if scoped_entry_type == "swing_production_reset_blocked":
        scoped_entry_type = "swing_production_contract"

    result = {
        "enabled": bool(BREAKOUT_EARLY_FOLLOW_THROUGH_GATE_ENABLED),
        "advisory_only": bool(BREAKOUT_EARLY_FOLLOW_THROUGH_ADVISORY_ONLY),
        "symbol": sym,
        "is_breakout": _p377_is_breakout_candidate(row),
        "entry_type": entry_type,
        "scoped_entry_type": scoped_entry_type,
        "blocked": False,
        "reason": "not_applicable",
    }

    if not result["enabled"] or not result["is_breakout"]:
        return result

    if scoped_entry_type and scoped_entry_type not in BREAKOUT_EARLY_FOLLOW_THROUGH_BLOCK_ENTRY_TYPES:
        result["reason"] = "entry_type_not_scoped"
        return result

    price = _p377_candidate_float(row, "last", "price", "close", "current_price", "entry_price")
    breakout_level = _p377_candidate_float(row, "breakout_level", "breakout_price", "trigger_price")

    result["price"] = round(price, 4) if price > 0 else None
    result["breakout_level"] = round(breakout_level, 4) if breakout_level > 0 else None

    if price <= 0 or breakout_level <= 0:
        result["reason"] = "missing_breakout_price_context"
        return result

    distance_pct = (price - breakout_level) / breakout_level
    min_distance_pct = float(BREAKOUT_EARLY_FOLLOW_THROUGH_MIN_ABOVE_BREAKOUT_PCT or 0.0)

    result["above_breakout_pct"] = round(distance_pct, 6)
    result["min_above_breakout_pct"] = round(min_distance_pct, 6)

    if distance_pct < min_distance_pct:
        result["blocked"] = not bool(BREAKOUT_EARLY_FOLLOW_THROUGH_ADVISORY_ONLY)
        result["reason"] = "breakout_lacks_early_follow_through"
    else:
        result["reason"] = "breakout_follow_through_ok"

    return result

def _p377_apply_breakout_early_follow_through_gate(row: dict | None) -> dict:
    out = dict(row or {})
    gate = _p377_breakout_early_follow_through_gate(out)
    out["breakout_early_follow_through_gate"] = gate

    if bool(gate.get("blocked")):
        reasons = list(out.get("rejection_reasons") or [])
        reasons.append(str(gate.get("reason") or "breakout_lacks_early_follow_through"))
        out["rejection_reasons"] = _dedupe_keep_order(reasons)
        out["eligible"] = False
        out["selected"] = False
        out["would_trade"] = False
        out["tradeable"] = False

        contract = dict(out.get("swing_production_contract") or {})
        contract["approved"] = False
        contract["blocked"] = True
        contract["p377_blocked"] = True
        contract["p377_reason"] = gate.get("reason")
        out["swing_production_contract"] = contract

    return out


def _p377_filter_rows_for_breakout_follow_through(rows: list | None) -> list[dict]:
    return [_p377_apply_breakout_early_follow_through_gate(r) for r in list(rows or []) if isinstance(r, dict)]

def _p377_profit_giveback_exit_trigger_evidence(row: dict | None) -> dict:
    row = dict(row or {})
    kill_zone = dict(row.get("kill_zone") or {})
    windows = dict(kill_zone.get("windows") or {})

    favorable_30m = _safe_float((windows.get("30m") or {}).get("favorable_pct"), 0.0)
    favorable_60m = _safe_float((windows.get("60m") or {}).get("favorable_pct"), 0.0)
    gross_pnl = _safe_float(row.get("gross_pnl"), 0.0)
    entry_price = _safe_float(row.get("entry_price"), 0.0)
    exit_price = _safe_float(row.get("exit_price"), 0.0)

    best_favorable_pct = max(favorable_30m, favorable_60m)
    exit_return_pct = ((exit_price - entry_price) / entry_price) * 100.0 if entry_price > 0 and exit_price > 0 else 0.0
    giveback_from_best_pct = best_favorable_pct - exit_return_pct

    should_have_preserved = bool(
        best_favorable_pct >= float(BREAKOUT_PROFIT_GIVEBACK_EXIT_TRIGGER_MIN_UNREALIZED_PCT or 0.0)
        and giveback_from_best_pct >= float(BREAKOUT_PROFIT_GIVEBACK_EXIT_TRIGGER_MAX_GIVEBACK_PCT or 0.0)
    )

    return {
        "best_favorable_pct": round(best_favorable_pct, 4),
        "exit_return_pct": round(exit_return_pct, 4),
        "giveback_from_best_pct": round(giveback_from_best_pct, 4),
        "gross_pnl": round(gross_pnl, 4),
        "min_unrealized_pct": float(BREAKOUT_PROFIT_GIVEBACK_EXIT_TRIGGER_MIN_UNREALIZED_PCT or 0.0),
        "max_giveback_pct": float(BREAKOUT_PROFIT_GIVEBACK_EXIT_TRIGGER_MAX_GIVEBACK_PCT or 0.0),
        "should_have_preserved": should_have_preserved,
        "suggested_trigger": (
            "daily_breakout_profit_giveback_preservation_exit"
            if should_have_preserved
            else "no_profit_giveback_preservation_trigger"
        ),
    }

def _p377_pltr_profit_giveback_audit(limit: int = 20) -> dict:
    base = _p376_same_day_breakout_loss_forensics(limit=max(20, int(limit or 20)))
    rows = []

    for row in list(base.get("rows") or []):
        kill_zone = dict(row.get("kill_zone") or {})
        windows = dict(kill_zone.get("windows") or {})
        w30 = dict(windows.get("30m") or {})
        favorable_30m = _safe_float(w30.get("favorable_pct"), 0.0)
        gross_pnl = _safe_float(row.get("gross_pnl"), 0.0)
        trigger_evidence = _p377_profit_giveback_exit_trigger_evidence(row)

        giveback = bool(
            row.get("is_breakout")
            and gross_pnl < 0
            and not bool(kill_zone.get("kill_zone_triggered"))
            and favorable_30m >= float(BREAKOUT_PROFIT_GIVEBACK_AUDIT_MIN_FAVORABLE_30M_PCT or 0.0)
        )

        if giveback or str(row.get("symbol") or "").strip().upper() == "PLTR":
            rows.append({
                "symbol": row.get("symbol"),
                "gross_pnl": row.get("gross_pnl"),
                "entry_price": row.get("entry_price"),
                "exit_price": row.get("exit_price"),
                "entry_ts_utc": row.get("entry_ts_utc"),
                "exit_ts_utc": row.get("exit_ts_utc"),
                "favorable_30m_pct": round(favorable_30m, 4),
                "kill_zone_triggered": bool(kill_zone.get("kill_zone_triggered")),
                "profit_giveback_flag": giveback,
                "profit_giveback_exit_trigger_evidence": trigger_evidence,
                "classification": row.get("classification"),
                "entry_quality": row.get("entry_quality"),
                "recommended_action": (
                    "add_or_tighten_daily_breakout_profit_giveback_preservation_exit"
                    if bool(trigger_evidence.get("should_have_preserved"))
                    else "review_daily_goal_preservation_or_trailing_profit_exit"
                    if giveback
                    else "pltr_context_row"
                ),
            })

    flagged = [r for r in rows if bool(r.get("profit_giveback_flag"))]
    preserve_trigger_rows = [
        r for r in rows
        if bool((r.get("profit_giveback_exit_trigger_evidence") or {}).get("should_have_preserved"))
    ]

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "pltr_profit_giveback_audit",
        "read_only": True,
        "min_favorable_30m_pct": float(BREAKOUT_PROFIT_GIVEBACK_AUDIT_MIN_FAVORABLE_30M_PCT or 0.0),
        "flagged_count": len(flagged),
        "flagged_symbols": sorted({str(r.get("symbol") or "") for r in flagged if str(r.get("symbol") or "")}),
        "preservation_trigger_count": len(preserve_trigger_rows),
        "preservation_trigger_symbols": sorted({str(r.get("symbol") or "") for r in preserve_trigger_rows if str(r.get("symbol") or "")}),
        "rows": rows[-max(1, min(int(limit or 20), 50)):],
        "recommended_action": (
            "add_daily_breakout_profit_giveback_preservation_exit"
            if preserve_trigger_rows
            else "tighten_profit_preservation_for_breakouts_that_show_early_followthrough"
            if flagged
            else "no_profit_giveback_after_valid_followthrough_detected"
        ),
    }

