def _p363_second_slot_truth(
    watch: dict | None = None,
    selected_items: list[dict] | None = None,
    eligible_not_selected_items: list[dict] | None = None,
    captured_items: list[dict] | None = None,
    active_truth: dict | None = None,
) -> dict:
    watch = dict(watch or {})
    selected_items = [dict(row or {}) for row in (selected_items or []) if isinstance(row, dict)]
    eligible_not_selected_items = [dict(row or {}) for row in (eligible_not_selected_items or []) if isinstance(row, dict)]
    captured_items = [dict(row or {}) for row in (captured_items or []) if isinstance(row, dict)]
    active_truth = dict(active_truth or {})

    latest_scan = _latest_completed_scan_record() or dict(LAST_SCAN or {})
    latest_summary = dict((latest_scan or {}).get("summary") or {})
    regime_mode = str(
        latest_summary.get("regime_mode")
        or watch.get("regime_mode")
        or ""
    ).strip().lower()
    regime = dict(latest_summary.get("regime") or {})
    weak_tape_active = bool(
        regime_mode == "defensive"
        or regime.get("favorable") is False
        or "weak_tape" in set(str(r or "").strip() for r in list(latest_summary.get("global_block_reasons") or []))
    )

    weak_tape_cap = int(globals().get("SWING_WEAK_TAPE_MAX_NEW_ENTRIES", 0) or 0)
    selected_count = int(watch.get("selected_total") or len(selected_items) or 0)
    captured_tradeable_count = int(watch.get("captured_tradeable_count") or len(captured_items) or 0)
    consumed_slot_count = max(selected_count, captured_tradeable_count)
    risk_adjusted_capacity = _p385_risk_adjusted_capacity_truth(active_truth)
    open_slots = int(risk_adjusted_capacity.get("risk_adjusted_open_slots") or 0)

    rows = []
    bug_symbols = []
    weak_cap_symbols = []
    risk_symbols = []

    for row in eligible_not_selected_items:
        sym = str(row.get("symbol") or "").strip().upper()
        blocking = [
            str(r or "").strip()
            for r in list(row.get("blocking_reasons") or row.get("selection_blockers") or [])
            if str(r or "").strip()
        ]
        gate_blockers = [
            str(r or "").strip()
            for r in list(row.get("gate_blockers") or [])
            if str(r or "").strip()
        ]
        dollar_risk = _p384_candidate_dollar_risk_truth(row)
        dollar_risk_allowed = bool(dollar_risk.get("allowed"))
        risk_blocked = bool(
            (
                "gate:risk_per_share" in blocking
                or "risk_per_share" in gate_blockers
                or "production_contract_risk_too_wide" in list(row.get("rejection_reasons") or [])
            )
            and not dollar_risk_allowed
        )
        reduced_size_candidate = bool(
            (
                "gate:risk_per_share" in blocking
                or "risk_per_share" in gate_blockers
                or "production_contract_risk_too_wide" in list(row.get("rejection_reasons") or [])
            )
            and dollar_risk_allowed
        )
        weak_cap_blocked = bool(
            weak_tape_active
            and weak_tape_cap > 0
            and consumed_slot_count >= weak_tape_cap
        )

        if weak_cap_blocked:
            decision = "blocked_by_weak_tape_slot_cap"
            weak_cap_symbols.append(sym)
        elif risk_blocked:
            decision = "blocked_by_dollar_risk"
            risk_symbols.append(sym)
        elif reduced_size_candidate:
            decision = "risk_percent_wide_but_dollar_risk_ok"
            bug_symbols.append(sym)
        else:
            decision = "eligible_second_slot_not_selected_bug"
            bug_symbols.append(sym)

        rows.append({
            "symbol": sym,
            "decision": decision,
            "selected": bool(row.get("selected")),
            "eligible": bool(row.get("eligible")),
            "captured": bool(row.get("captured")),
            "rank_score": row.get("rank_score"),
            "target_path_score": row.get("target_path_score"),
            "risk_per_share_pct": row.get("risk_per_share_pct"),
            "dollar_risk_selection_truth": dollar_risk,
            "blocking_reasons": blocking,
            "gate_blockers": gate_blockers,
            "what_needs_to_change": list(row.get("what_needs_to_change") or []),
        })

    reduced_size_symbols = [
        str(r.get("symbol") or "").strip().upper()
        for r in rows
        if str(r.get("decision") or "") == "risk_percent_wide_but_dollar_risk_ok"
    ]

    if reduced_size_symbols:
        read = "eligible_second_slot_dollar_risk_ok_percent_risk_wide"
        recommended_action = "allow_only_if_selection_uses_risk_sized_qty"
    elif bug_symbols:
        read = "eligible_second_slot_not_selected_bug"
        recommended_action = "inspect_selection_slot_builder_before_relaxing_thresholds"
    elif weak_cap_symbols:
        read = "weak_tape_second_slot_cap_active"
        recommended_action = "keep_cap_or_deliberately_raise_weak_tape_max_new_entries"
    elif risk_symbols:
        read = "eligible_second_slot_blocked_by_risk"
        recommended_action = "do_not_force_entry_unless_risk_adjusted_sizing_path_is_explicit"
    elif not eligible_not_selected_items:
        read = "no_second_slot_candidate"
        recommended_action = "monitor_next_scan"
    else:
        read = "second_slot_truth_unclear"
        recommended_action = "inspect_swing_submit_path_trace_rows"

    return {
        "enabled": True,
        "trade_submission_behavior_changed": False,
        "weak_tape_active": weak_tape_active,
        "regime_mode": regime_mode or "unknown",
        "weak_tape_max_new_entries": weak_tape_cap,
        "selected_count": selected_count,
        "captured_tradeable_count": captured_tradeable_count,
        "consumed_slot_count": consumed_slot_count,
        "eligible_not_selected_count": len(eligible_not_selected_items),
        "open_slots": open_slots,
        "risk_adjusted_capacity": risk_adjusted_capacity,
        "weak_tape_slot_cap_applies": bool(weak_tape_active and weak_tape_cap > 0),
        "weak_tape_slot_cap_reached": bool(weak_tape_active and weak_tape_cap > 0 and consumed_slot_count >= weak_tape_cap),
        "weak_cap_symbols": _dedupe_keep_order(weak_cap_symbols),
        "risk_blocked_symbols": _dedupe_keep_order(risk_symbols),
        "reduced_size_candidate_symbols": _dedupe_keep_order(reduced_size_symbols),
        "bug_symbols": _dedupe_keep_order([s for s in bug_symbols if s not in set(reduced_size_symbols)]),
        "rows": rows,
        "read": read,
        "recommended_action": recommended_action,
    }

def _p400_swing_submit_path_trace_light(symbols: str | None = None, limit: int | None = None) -> dict:
    latest_scan, summary = _p298_latest_scan_summary_light()
    latest_scan = dict(latest_scan or LAST_SCAN or {})
    summary = dict((latest_scan or {}).get("summary") or summary or {})
    p481_canonical_scan_truth = dict((latest_scan or {}).get("_p481_canonical_scan_truth") or {})

    requested_symbols = {
        str(sym or "").strip().upper()
        for sym in str(symbols or "").replace(",", " ").split()
        if str(sym or "").strip()
    }
    lim = max(1, min(int(limit or 12), 50))

    selected_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(summary.get("selected_symbols") or latest_scan.get("selected_symbols") or [])
        if str(sym or "").strip()
    ])
    production_selected_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(summary.get("production_contract_selected_symbols") or latest_scan.get("production_contract_selected_symbols") or selected_symbols)
        if str(sym or "").strip()
    ])

    submit_rows_all = [
        dict(row or {})
        for row in list(summary.get("selected_submission_rows") or summary.get("would_submit") or latest_scan.get("would_submit") or [])
        if isinstance(row, dict)
    ]
    if not submit_rows_all:
        selected_truth_rows = []
        selected_truth = summary.get("selected_submission_truth")
        if isinstance(selected_truth, dict):
            selected_truth_rows = list(selected_truth.get("rows") or [])
        submit_rows_all = [
            dict((row or {}).get("scan_submit_row") or row or {})
            for row in selected_truth_rows
            if isinstance(row, dict)
            and (
                isinstance((row or {}).get("scan_submit_row"), dict)
                or str((row or {}).get("symbol") or "").strip()
            )
        ]

    candidate_snapshot_rows = [
        dict(row or {})
        for row in list(
            summary.get("candidate_rows_for_truth")
            or summary.get("candidate_rows")
            or summary.get("top_new_entry_candidates")
            or summary.get("candidates")
            or LAST_SWING_CANDIDATES
            or []
        )
        if isinstance(row, dict)
    ]
    current_candidate_truth = {
        "ok": True,
        "status": "snapshot_only",
        "source": "latest_scan_summary_or_last_candidates",
        "candidate_rows": candidate_snapshot_rows,
        "selected_symbols": selected_symbols,
        "candidate_count": len(candidate_snapshot_rows),
        "eligible_count": len([
            row for row in candidate_snapshot_rows
            if bool(row.get("eligible")) and not bool(row.get("open_position"))
        ]),
        "does_not_recompute_candidate_payload": True,
    }
    eligible_new_entry_rows = _p413_eligible_new_entry_rows_from_fast_payload(current_candidate_truth)
    eligible_new_entry_symbols = _p413_eligible_new_entry_symbols_from_fast_payload(current_candidate_truth)
    if requested_symbols:
        submit_rows_all = [
            row for row in submit_rows_all
            if str(row.get("symbol") or "").strip().upper() in requested_symbols
        ]
        selected_symbols = [sym for sym in selected_symbols if sym in requested_symbols]
        production_selected_symbols = [sym for sym in production_selected_symbols if sym in requested_symbols]
        eligible_new_entry_rows = [
            row for row in eligible_new_entry_rows
            if str(row.get("symbol") or "").strip().upper() in requested_symbols
        ]
        eligible_new_entry_symbols = [
            sym for sym in eligible_new_entry_symbols
            if sym in requested_symbols
        ]

    submit_rows = submit_rows_all[:lim]
    submit_row_symbols = _dedupe_keep_order([
        str((row or {}).get("symbol") or "").strip().upper()
        for row in submit_rows_all
        if str((row or {}).get("symbol") or "").strip()
    ])

    active_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym, plan in dict(TRADE_PLAN or {}).items()
        if str(sym or "").strip()
        and isinstance(plan, dict)
        and bool(plan.get("active"))
    ])
    pending_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym, plan in dict(TRADE_PLAN or {}).items()
        if str(sym or "").strip()
        and isinstance(plan, dict)
        and _plan_is_pending_entry(plan)
    ])

    actual_submit_side_effect_symbols = _dedupe_keep_order([
        str((row or {}).get("symbol") or "").strip().upper()
        for row in submit_rows_all
        if str((row or {}).get("symbol") or "").strip()
        and bool((row or {}).get("actual_submit_side_effect"))
    ])
    rate_limited_symbols = _dedupe_keep_order([
        str((row or {}).get("symbol") or "").strip().upper()
        for row in submit_rows_all
        if str((row or {}).get("symbol") or "").strip()
        and _p398_submit_row_rate_limited(row)
    ])
    queued_rate_limit_symbols = _dedupe_keep_order([
        str((row or {}).get("symbol") or "").strip().upper()
        for row in P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE.values()
        if str((row or {}).get("symbol") or "").strip()
    ])
    current_rate_limit_retry_pending = bool(
        (rate_limited_symbols or queued_rate_limit_symbols)
        and (production_selected_symbols or submit_row_symbols)
    )
    execution_quality_block_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(summary.get("execution_quality_block_symbols") or [])
        if str(sym or "").strip()
    ])
    retryable_spread_block_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(summary.get("retryable_spread_block_symbols") or [])
        if str(sym or "").strip()
    ])
    after_hours_selected_symbols = _dedupe_keep_order([
        str((row or {}).get("symbol") or "").strip().upper()
        for row in submit_rows_all
        if str((row or {}).get("symbol") or "").strip()
        and str((row or {}).get("submit_reason") or (row or {}).get("reason") or "").strip().lower()
        in {"outside_market_hours", "outside_scanner_session", "market_closed"}
        and not bool((row or {}).get("actual_submit_side_effect"))
    ])
    p524_terminal_evidence_symbols = _dedupe_keep_order(
        list(submit_row_symbols)
        + list(active_symbols)
        + list(pending_symbols)
        + list(actual_submit_side_effect_symbols)
        + list(rate_limited_symbols)
        + list(queued_rate_limit_symbols)
        + list(execution_quality_block_symbols)
        + list(retryable_spread_block_symbols)
        + list(after_hours_selected_symbols)
    )
    p524_selection_revalidation = _p524_revalidate_current_selected_symbols(
        production_selected_symbols,
        current_candidate_truth,
        preserve_symbols=p524_terminal_evidence_symbols,
    )
    p524_stale_selected_symbols = set(p524_selection_revalidation.get("stale_symbols") or [])
    if p524_stale_selected_symbols:
        selected_symbols = [sym for sym in selected_symbols if sym not in p524_stale_selected_symbols]
        production_selected_symbols = [
            sym for sym in production_selected_symbols
            if sym not in p524_stale_selected_symbols
        ]

    submit_gap_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(summary.get("selected_submit_gap_symbols") or [])
        if str(sym or "").strip()
        and str(sym or "").strip().upper() not in p524_stale_selected_symbols
        and str(sym or "").strip().upper() not in set(after_hours_selected_symbols)
    ])
    missing_submit_symbols = [
        sym for sym in production_selected_symbols
        if sym not in set(submit_row_symbols)
        and sym not in set(active_symbols)
        and sym not in set(pending_symbols)
        and sym not in set(rate_limited_symbols)
        and sym not in set(queued_rate_limit_symbols)
        and sym not in set(after_hours_selected_symbols)
    ]
    selected_not_attempted_symbols = [
        sym for sym in production_selected_symbols
        if sym not in set(submit_row_symbols)
        and sym not in set(active_symbols)
        and sym not in set(pending_symbols)
    ]

    duration_ms = int(latest_scan.get("duration_ms") or 0)
    budget_sec = int(SCAN_RUNTIME_BUDGET_SEC or 0)
    runtime_over_budget = bool(budget_sec > 0 and duration_ms > budget_sec * 1000)

    if missing_submit_symbols or submit_gap_symbols:
        path_status = "selected_submit_gap_detected"
        recommended_action = "inspect_heavy_trace_or_submit_gap_rows"
    elif after_hours_selected_symbols:
        path_status = "after_hours_selected_not_submitted"
        recommended_action = "monitor_next_open_fresh_scan"
    elif current_rate_limit_retry_pending:
        path_status = "rate_limited_retry_pending"
        recommended_action = "wait_for_retry_queue_consumption"
    elif actual_submit_side_effect_symbols and set(selected_symbols).issubset(set(actual_submit_side_effect_symbols)):
        path_status = "selected_symbols_have_actual_submit_side_effect"
        recommended_action = "monitor_active_positions"
    elif eligible_new_entry_symbols and not selected_symbols:
        path_status = "eligible_new_entry_not_selected"
        recommended_action = "scheduled_scanner_should_promote_current_eligible_contract_rows"
    elif selected_symbols:
        path_status = "selected_candidate_needs_submit_truth"
        recommended_action = "inspect_heavy_trace"
    elif actual_submit_side_effect_symbols:
        path_status = "selected_symbols_have_actual_submit_side_effect"
        recommended_action = "monitor_active_positions"
    elif p524_stale_selected_symbols:
        path_status = "stale_selected_candidate_revalidated_blocked"
        recommended_action = "monitor_next_fresh_eligible_scan"
    else:
        path_status = "no_selected_candidate"
        recommended_action = "monitor_next_scan"

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "swing_submit_path_trace",
        "trace_mode": "light",
        "fast_snapshot_only": True,
        "does_not_recompute_candidate_payload": True,
        "heavy_available": True,
        "heavy_url_hint": "/diagnostics/swing_submit_path_trace?heavy=true",
        "read_only": True,
        "source": str(latest_scan.get("_scan_source") or "last_scan_runtime_snapshot"),
        "p481_canonical_scan_truth": p481_canonical_scan_truth,
        "p484_candidate_eval_module": swing_candidate_eval_module_status(
            patch_version=PATCH_VERSION
        ),
        "swing_candidate_eval_module_version": SWING_CANDIDATE_EVAL_MODULE_VERSION,
        "swing_candidate_eval_module_status": swing_candidate_eval_module_status(
            patch_version=PATCH_VERSION
        ),
        "path_status": path_status,
        "recommended_action": recommended_action,
        "latest_scan": {
            "ts_utc": latest_scan.get("ts_utc"),
            "reason": latest_scan.get("reason"),
            "source": latest_scan.get("_scan_source"),
            "fallback_from_last_scan_reason": latest_scan.get("fallback_from_last_scan_reason"),
            "runtime_budget_sanitized": bool(latest_scan.get("runtime_budget_sanitized")),
            "candidate_cache_adopted": bool(summary.get("candidate_cache_adopted")),
            "candidate_cache_source": summary.get("candidate_cache_source"),
            "raw_latest_reason": summary.get("raw_latest_reason") or latest_scan.get("raw_latest_reason"),
            "effective_reason_normalized": bool(summary.get("effective_reason_normalized")),
            "after_hours_does_not_replace_candidate_truth": bool(p481_canonical_scan_truth.get("after_hours_does_not_replace_candidate_truth")),
            "used_candidate_bearing_fallback": bool(p481_canonical_scan_truth.get("used_candidate_bearing_fallback")),
            "exception_type": latest_scan.get("exception_type"),
            "duration_ms": duration_ms,
            "duration_sec": round(duration_ms / 1000.0, 2),
            "scan_runtime_budget_sec": budget_sec,
            "runtime_over_budget": runtime_over_budget,
            "scanner_runtime_still_slow": runtime_over_budget,
            "scanner_speed_note": (
                "submit_trace_is_fast_but_scanner_runtime_needs_separate_hot_path_cleanup"
                if runtime_over_budget
                else "scanner_runtime_within_budget"
            ),
            "swing_candidate_eval_module_version": SWING_CANDIDATE_EVAL_MODULE_VERSION,
            "swing_candidate_eval_module_status": swing_candidate_eval_module_status(
                patch_version=PATCH_VERSION
            ),
            "selected_total": len(selected_symbols),
            "selected_symbols": selected_symbols,
            "eligible_total": int(summary.get("eligible_total") or latest_scan.get("eligible_total") or 0),
        },
        "direct_submit": {
            "active": bool(SWING_PRODUCTION_CORE_CLEANUP_ENABLED and not SWING_LIVE_USE_SELECTED_INTENT_QUEUE),
            "selection_source": "swing_production_contract",
            "submission_source": "direct_submit",
            "retired_queue_path_active": False,
            "retired_finalizer_path_active": False,
        },
        "selected_opportunity_truth": {
            "raw_selected_count": len(production_selected_symbols),
            "raw_selected_symbols": production_selected_symbols,
            "selected_not_attempted_count": len(selected_not_attempted_symbols),
            "selected_not_attempted_symbols": selected_not_attempted_symbols,
            "eligible_new_entry_count": len(eligible_new_entry_symbols),
            "eligible_new_entry_symbols": eligible_new_entry_symbols,
            "eligible_new_entry_not_selected_count": len([
                sym for sym in eligible_new_entry_symbols
                if sym not in set(production_selected_symbols)
            ]),
            "eligible_new_entry_not_selected_symbols": [
                sym for sym in eligible_new_entry_symbols
                if sym not in set(production_selected_symbols)
            ],
            "submit_row_symbols": submit_row_symbols,
            "actual_submit_side_effect_symbols": actual_submit_side_effect_symbols,
            "rate_limited_submit_symbols": rate_limited_symbols,
            "rate_limit_retry_queue_count": len(P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE),
            "rate_limit_retry_queue_symbols": queued_rate_limit_symbols,
            "current_rate_limit_retry_pending": bool(current_rate_limit_retry_pending),
            "stale_rate_limit_retry_suppressed": bool(
                (rate_limited_symbols or queued_rate_limit_symbols)
                and not current_rate_limit_retry_pending
            ),
            "execution_quality_block_symbols": execution_quality_block_symbols,
            "retryable_spread_block_symbols": retryable_spread_block_symbols,
            "after_hours_selected_symbols": after_hours_selected_symbols,
            "after_hours_selected_count": len(after_hours_selected_symbols),
            "submit_gap_symbols": submit_gap_symbols,
            "missing_submit_symbols": missing_submit_symbols,
            "p524_selection_revalidation": p524_selection_revalidation,
            "stale_revalidated_blocked_symbols": list(p524_stale_selected_symbols),
        },
        "active_capture_truth": {
            "active_symbols": active_symbols,
            "pending_symbols": pending_symbols,
            "captured_selected_symbols": [
                sym for sym in production_selected_symbols
                if sym in set(active_symbols) or sym in set(pending_symbols)
            ],
        },
        "p399": {
            "pre_scan_retry_submit": dict(summary.get("p399_pre_scan_retry_submit") or {}),
            "partial_submit_finalization": dict(summary.get("p399_partial_submit_finalization") or {}),
        },
        "eligible_new_entry_rows": eligible_new_entry_rows[:lim],
        "rows": submit_rows,
        "row_count": len(submit_rows),
        "row_count_total": len(submit_rows_all),
    }

def _p321_swing_submit_path_trace(symbols: str | None = None, limit: int | None = None) -> dict:
    watch = _p316_swing_watchlist_trade_status(
        symbols=symbols or "",
        limit=max(5, min(int(limit or 12), 25)),
    )
    active_truth = _p320_active_position_truth_for_brief()
    selected_or_eligible_items = [
        dict(row)
        for row in list(watch.get("items") or [])
        if isinstance(row, dict)
        and (bool(row.get("selected")) or bool(row.get("eligible")))
        and not bool(row.get("captured"))
    ]
    current_scan_selected_symbols = {
        str(sym or "").strip().upper()
        for sym in list((watch.get("universe_truth") or {}).get("selected_symbols") or [])
        if str(sym or "").strip()
    }
    selected_items = [
        dict(row)
        for row in selected_or_eligible_items
        if str(row.get("symbol") or "").strip().upper() in current_scan_selected_symbols
    ]
    eligible_not_selected_items = [
        dict(row)
        for row in selected_or_eligible_items
        if str(row.get("symbol") or "").strip().upper() not in current_scan_selected_symbols
    ]
    captured_items = [
        dict(row)
        for row in list(watch.get("items") or [])
        if isinstance(row, dict)
        and (
            bool(row.get("captured"))
            or str(row.get("status") or "") in {"already_captured", "captured_tradeable_candidate"}
        )
    ]

    market_open_now = bool(watch.get("market_open"))
    after_hours_suppression = dict(watch.get("after_hours_selected_candidate_suppression") or {})
    after_hours_suppressed = bool(after_hours_suppression.get("active"))
    effective_missing_count = int(watch.get("missing_trade_opportunity_count") or 0)
    effective_missing_symbols = list(watch.get("missing_trade_opportunity_symbols") or [])
    raw_selected_count = len(selected_items)
    raw_selected_symbols = [row.get("symbol") for row in selected_items]
    eligible_not_selected_symbols = [row.get("symbol") for row in eligible_not_selected_items]

    recent_limit_evidence = _p336_recent_limit_entry_evidence(limit=20)
    rate_limited_symbols = _dedupe_keep_order([
        str(row.get("symbol") or "").upper()
        for row in list(recent_limit_evidence.get("rows") or [])
        if (
            str(row.get("stage") or "").lower() == "rate_limited"
            or bool(row.get("rate_limited"))
            or _p352_is_alpaca_rate_limit_error(row.get("error"))
            or _p352_is_alpaca_rate_limit_error(row.get("block_reason"))
        )
        and str(row.get("symbol") or "").strip()
    ])

    latest_scan, latest_summary = _p298_latest_scan_summary_light()
    selected_submit_rows = [
        dict(row or {})
        for row in list((latest_summary or {}).get("selected_submission_rows") or [])
        if isinstance(row, dict)
    ]
    rate_limited_symbols = _dedupe_keep_order(rate_limited_symbols + [
        str(row.get("symbol") or "").strip().upper()
        for row in selected_submit_rows
        if str(row.get("symbol") or "").strip()
        and (
            str(row.get("submit_state") or "").strip().lower() == "retryable_rate_limit"
            or bool(row.get("rate_limited"))
            or _p352_is_alpaca_rate_limit_error(row.get("submit_reason"))
            or _p352_is_alpaca_rate_limit_error(row.get("reason"))
            or _p352_is_alpaca_rate_limit_error((row.get("submit_diagnostics") or {}).get("error"))
        )
    ])
    queued_rate_limit_symbols = {
        str((row or {}).get("symbol") or "").strip().upper()
        for row in P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE.values()
        if str((row or {}).get("symbol") or "").strip()
    }

    rate_limited_selected_symbols = [
        sym for sym in raw_selected_symbols
        if str(sym or "").upper() in set(rate_limited_symbols)
    ]
    selected_not_attempted_symbols = [
        sym for sym in raw_selected_symbols
        if str(sym or "").upper() not in set(rate_limited_symbols)
    ]

    effective_missing_symbols = [
        sym for sym in effective_missing_symbols
        if str(sym or "").strip().upper() not in set(rate_limited_symbols)
        and str(sym or "").strip().upper() not in queued_rate_limit_symbols
    ]
    effective_missing_count = len(effective_missing_symbols)
    direct_submit_enabled = bool(SWING_PRODUCTION_CORE_CLEANUP_ENABLED and not SWING_LIVE_USE_SELECTED_INTENT_QUEUE)
    direct_submit_status = {
        "active": direct_submit_enabled,
        "selection_source": "swing_production_contract",
        "submission_source": "direct_submit",
        "retired_queue_path_active": False,
        "retired_finalizer_path_active": False,
    }
    second_slot_truth = _p363_second_slot_truth(
        watch=watch,
        selected_items=selected_items,
        eligible_not_selected_items=eligible_not_selected_items,
        captured_items=captured_items,
        active_truth=active_truth,
    )
    risk_adjusted_capacity = _p385_risk_adjusted_capacity_truth(active_truth)
    oversized_risk_operator_action = _p386_oversized_risk_operator_action(active_truth)

    blockers = []
    if not bool(NEW_ENTRIES_ENABLED):
        blockers.append("new_entries_disabled")
    if not bool(SCANNER_ALLOW_LIVE) or bool(SCANNER_DRY_RUN):
        blockers.append("scanner_not_live")
    if bool(effective_entry_dry_run("worker_scan")):
        blockers.append("effective_entry_dry_run")
    if daily_halt_active() or realized_closed_trade_loss_halt_active():
        blockers.append("loss_halt_active")
    if int(active_truth.get("active_position_count") or 0) >= int(_effective_max_open_positions()):
        blockers.append("max_open_positions_reached")
    if after_hours_suppressed:
        blockers.append("market_closed_selected_candidates_suppressed")
    elif not selected_items and captured_items:
        blockers.append("latest_candidate_already_captured")
    elif not selected_items and eligible_not_selected_items:
        blockers.append("no_current_scan_selected_candidates")
    elif not selected_items:
        blockers.append("no_selected_or_eligible_candidates")

    path_status = "ready_when_candidate_selected" if not blockers or blockers in (["no_selected_or_eligible_candidates"], ["no_current_scan_selected_candidates"]) else "blocked"
    if blockers == ["market_closed_selected_candidates_suppressed"]:
        path_status = "market_closed_selected_candidates_suppressed"
    if blockers == ["latest_candidate_already_captured"]:
        path_status = "captured_candidate_monitor_existing_position"
    if selected_items and not blockers:
        path_status = "ready_to_submit_selected_candidate"

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "swing_submit_path_trace",
        "read_only": True,
        "path_status": path_status,
        "blockers": blockers,
        "trade_submission_behavior_changed": False,
        "direct_submit": direct_submit_status,
        "selected_or_eligible_count": len(selected_or_eligible_items),
        "selected_or_eligible_symbols": _dedupe_keep_order(raw_selected_symbols + eligible_not_selected_symbols),
        "current_scan_selected_count": raw_selected_count,
        "current_scan_selected_symbols": raw_selected_symbols,
        "captured_candidate_count": len(captured_items),
        "captured_candidate_symbols": [row.get("symbol") for row in captured_items],
        "missing_trade_opportunity_count": effective_missing_count,
        "missing_trade_opportunity_symbols": effective_missing_symbols,
        "selected_opportunity_truth": {
            "raw_selected_count": raw_selected_count,
            "raw_selected_symbols": raw_selected_symbols,
            "selected_not_attempted_count": len(selected_not_attempted_symbols),
            "selected_not_attempted_symbols": selected_not_attempted_symbols,
            "rate_limited_submit_count": len(rate_limited_selected_symbols),
            "rate_limited_submit_symbols": rate_limited_selected_symbols,
            "rate_limit_retry_queue_count": len(P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE),
            "rate_limit_retry_queue_symbols": sorted(queued_rate_limit_symbols),
            "eligible_not_selected_count": len(eligible_not_selected_items),
            "eligible_not_selected_symbols": eligible_not_selected_symbols,
            "current_scan_selected_source": "latest_scan_summary_selected_symbols",
            "second_slot_read": second_slot_truth.get("read"),
            "second_slot_recommended_action": second_slot_truth.get("recommended_action"),
            "read": (
                "selected_submit_rate_limited_retryable"
                if rate_limited_selected_symbols
                else "selected_candidates_waiting_for_submit"
                if selected_not_attempted_symbols
                else second_slot_truth.get("read")
                if eligible_not_selected_items
                else "no_selected_submit_gap"
            ),
        },
        "second_slot_truth": second_slot_truth,
        "after_hours_selected_candidate_suppression": {
            "active": after_hours_suppressed,
            "market_open": market_open_now,
            "raw_selected_count": raw_selected_count,
            "raw_selected_symbols": raw_selected_symbols,
            "suppressed_count": int(after_hours_suppression.get("suppressed_count") or 0),
            "suppressed_symbols": list(after_hours_suppression.get("suppressed_symbols") or []),
            "reason": after_hours_suppression.get("reason"),
        },
        "entry_controls": {
            "new_entries_enabled": bool(NEW_ENTRIES_ENABLED),
            "scanner_allow_live": bool(SCANNER_ALLOW_LIVE),
            "scanner_dry_run": bool(SCANNER_DRY_RUN),
            "effective_entry_dry_run": bool(effective_entry_dry_run("worker_scan")),
            "swing_live_enabled": bool(SWING_LIVE_ENABLED),
        },
        "capacity": {
            "active_position_count": int(active_truth.get("active_position_count") or 0),
            "active_symbols": list(active_truth.get("symbols") or []),
            "effective_max_open_positions": int(_effective_max_open_positions()),
            "raw_open_slots": int(risk_adjusted_capacity.get("raw_open_slots") or 0),
            "open_slots": int(risk_adjusted_capacity.get("risk_adjusted_open_slots") or 0),
            "risk_adjusted_capacity": risk_adjusted_capacity,
            "oversized_risk_operator_action": oversized_risk_operator_action,
        },
        "watch_summary": {
            "truth_source": watch.get("truth_source"),
            "scan_ts_utc": watch.get("scan_ts_utc"),
            "runtime_slim_applied": bool(watch.get("runtime_slim_applied")),
            "selected_total": int(watch.get("selected_total") or 0),
            "eligible_total": int(watch.get("eligible_total") or 0),
            "tradeable_count": int(watch.get("tradeable_count") or 0),
            "actionable_tradeable_count": int(watch.get("actionable_tradeable_count") or 0),
            "captured_count": int(watch.get("captured_count") or 0),
            "captured_tradeable_count": int(watch.get("captured_tradeable_count") or 0),
            "missing_trade_opportunity_count": int(watch.get("missing_trade_opportunity_count") or 0),
            "watch_count": int(watch.get("watch_count") or 0),
            "universe_coverage_ok": bool((watch.get("universe_truth") or {}).get("coverage_ok", True)),
            "active_symbols": list((watch.get("universe_truth") or {}).get("active_symbols") or []),
            "coverage_missing_active_symbols": list((watch.get("universe_truth") or {}).get("coverage_missing_active_symbols") or []),
            "open_slot_read": (watch.get("open_slot_truth") or {}).get("read"),
            "market_open": bool(watch.get("market_open")),
            "after_hours_suppressed_count": int((watch.get("after_hours_selected_candidate_suppression") or {}).get("suppressed_count") or 0),
            "after_hours_suppressed_symbols": list((watch.get("after_hours_selected_candidate_suppression") or {}).get("suppressed_symbols") or []),
            "near_miss_actionable_count": int((watch.get("rejected_candidate_actionability") or {}).get("near_miss_actionable_count") or 0),
            "too_dangerous_count": int((watch.get("rejected_candidate_actionability") or {}).get("too_dangerous_count") or 0),
            "correctly_rejected_count": int((watch.get("rejected_candidate_actionability") or {}).get("correctly_rejected_count") or 0),
            "production_near_miss_count": int((watch.get("production_decision_truth") or {}).get("near_miss_count") or 0),
            "production_near_miss_symbols": list((watch.get("production_decision_truth") or {}).get("near_miss_symbols") or []),
            "production_too_dangerous_count": int((watch.get("production_decision_truth") or {}).get("too_dangerous_count") or 0),
            "production_already_active_count": int((watch.get("production_decision_truth") or {}).get("already_active_count") or 0),
        },
        "profit_path_status": {
            "daily_goal_low": float(globals().get("BROKER_DAILY_GOAL_LOW_DOLLARS", 100) or 100),
            "daily_goal_high": float(globals().get("BROKER_DAILY_GOAL_HIGH_DOLLARS", 200) or 200),
            "missing_trade_opportunity_count": int(watch.get("missing_trade_opportunity_count") or 0),
            "captured_candidate_count": len(captured_items),
            "raw_open_slots": int(risk_adjusted_capacity.get("raw_open_slots") or 0),
            "open_slots": int(risk_adjusted_capacity.get("risk_adjusted_open_slots") or 0),
            "operator_read": (
                "selected_submit_rate_limited_retryable; waiting_for_durable_retry"
                if rate_limited_selected_symbols or queued_rate_limit_symbols
                else "not_missing_current_trade; monitor_existing_positions_and_next_scan"
                if effective_missing_count <= 0
                else "actionable_trade_available; inspect_selected_items_now"
            ),
        },
        "selected_items": selected_items,
        "eligible_not_selected_items": eligible_not_selected_items,
    }


def _p321_candidate_gate_crossing_alert(symbols: str | None = None, limit: int | None = None) -> dict:
    watch = _p316_swing_watchlist_trade_status(
        symbols=symbols or "",
        limit=max(5, min(int(limit or 12), 25)),
    )

    rows = [dict(row) for row in list(watch.get("items") or []) if isinstance(row, dict)]
    crossed = []
    near = []
    hard_blocked = []

    for row in rows:
        sym = str(row.get("symbol") or "").strip().upper()
        if not sym:
            continue

        selected = bool(row.get("selected"))
        eligible = bool(row.get("eligible"))
        active_position = bool(row.get("active_position"))
        pending_plan = bool(row.get("pending_plan"))
        executable = row.get("executable")
        reasons = [str(x) for x in list(row.get("rejection_reasons") or []) if str(x)]
        blockers = [str(x) for x in list(row.get("gate_blockers") or []) if str(x)]

        if selected or eligible:
            crossed.append({
                "symbol": sym,
                "status": "crossed_trade_gate",
                "selected": selected,
                "eligible": eligible,
                "executable": executable,
                "recommendation": "inspect_submit_path_trace",
            })
            continue

        if active_position or pending_plan:
            hard_blocked.append({
                "symbol": sym,
                "status": "already_captured",
                "reason": "active_position_or_pending_plan",
            })
            continue

        if executable is False:
            hard_blocked.append({
                "symbol": sym,
                "status": "not_executable",
                "reason": row.get("sizing_block_reason") or "sizing_not_executable",
            })
            continue

        nearish = (
            row.get("status") == "watch_gate_near_miss"
            or "target_profile_breakout_gate" in reasons
            or bool(blockers)
        )
        if nearish:
            near.append({
                "symbol": sym,
                "status": "near_miss",
                "rank_score": row.get("rank_score"),
                "target_path_score": row.get("target_path_score"),
                "gate_blockers": blockers,
                "what_needs_to_change": list(row.get("what_needs_to_change") or []),
            })
        else:
            hard_blocked.append({
                "symbol": sym,
                "status": row.get("status") or "not_candidate",
                "reason": ",".join(list(row.get("blocking_reasons") or [])) or "not_ready",
            })

    alert_active = bool(crossed)

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "candidate_gate_crossing_alert",
        "read_only": True,
        "alert_active": alert_active,
        "alert_level": "actionable" if alert_active else "watch",
        "crossed_count": len(crossed),
        "crossed_symbols": [row.get("symbol") for row in crossed],
        "near_miss_count": len(near),
        "near_miss_symbols": [row.get("symbol") for row in near],
        "hard_blocked_count": len(hard_blocked),
        "truth_source": watch.get("truth_source"),
        "scan_ts_utc": watch.get("scan_ts_utc"),
        "runtime_slim_applied": bool(watch.get("runtime_slim_applied")),
        "crossed": crossed,
        "near_miss": near,
        "hard_blocked": hard_blocked,
        "operator_action": (
            "open_swing_submit_path_trace"
            if alert_active
            else "keep_monitoring_watchlist_trade_status"
        ),
    }

def _p322_load_gate_crossing_state() -> dict:
    path = str(SWING_GATE_CROSSING_STATE_PATH or "").strip()
    if not path:
        return {"ok": False, "loaded": False, "reason": "state_path_not_configured", "history": []}
    try:
        if not os.path.exists(path):
            return {"ok": True, "loaded": False, "reason": "state_file_missing", "history": []}
        with open(path, "r", encoding="utf-8") as f:
            payload = json.load(f)
        history = list((payload or {}).get("history") or [])
        return {
            "ok": True,
            "loaded": True,
            "path": path,
            "history": [dict(row) for row in history if isinstance(row, dict)],
        }
    except Exception as exc:
        return {"ok": False, "loaded": False, "path": path, "reason": str(exc), "history": []}


def _p322_save_gate_crossing_state(history: list[dict]) -> dict:
    path = str(SWING_GATE_CROSSING_STATE_PATH or "").strip()
    if not path:
        return {"ok": False, "saved": False, "reason": "state_path_not_configured"}
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        lim = max(1, min(int(SWING_GATE_CROSSING_HISTORY_SIZE or 50), 500))
        payload = {
            "ok": True,
            "patch_version": PATCH_VERSION,
            "updated_utc": datetime.now(timezone.utc).isoformat(),
            "history": list(history or [])[-lim:],
        }
        with open(path, "w", encoding="utf-8") as f:
            json.dump(payload, f, indent=2, sort_keys=True)
        return {"ok": True, "saved": True, "path": path, "count": len(payload["history"])}
    except Exception as exc:
        return {"ok": False, "saved": False, "path": path, "reason": str(exc)}


def _p322_numeric_delta(current, previous) -> float | None:
    if current is None or previous is None:
        return None
    try:
        return round(float(current) - float(previous), 4)
    except Exception:
        return None


def _p322_symbol_snapshot_from_alert(alert: dict) -> dict:
    rows = []
    for bucket in ("crossed", "near_miss", "hard_blocked"):
        for row in list((alert or {}).get(bucket) or []):
            if not isinstance(row, dict):
                continue
            item = dict(row)
            item["bucket"] = bucket
            item["symbol"] = str(item.get("symbol") or "").strip().upper()
            if item.get("symbol"):
                rows.append(item)
    return {
        str(row.get("symbol")): row
        for row in rows
        if str(row.get("symbol") or "").strip()
    }


def _p322_near_miss_drift_tracker(symbols: str | None = None, limit: int | None = None, persist: bool = True) -> dict:
    alert = _p321_candidate_gate_crossing_alert(
        symbols=symbols or "",
        limit=max(5, min(int(limit or 12), 25)),
    )
    state = _p322_load_gate_crossing_state()
    history = [dict(row) for row in list(state.get("history") or []) if isinstance(row, dict)]

    current_symbols = _p322_symbol_snapshot_from_alert(alert)
    previous_snapshot = {}
    if history:
        previous_snapshot = dict((history[-1] or {}).get("symbols") or {})

    drift_rows = []
    for sym, current in sorted(current_symbols.items()):
        prev = dict(previous_snapshot.get(sym) or {})
        rank_delta = _p322_numeric_delta(current.get("rank_score"), prev.get("rank_score"))
        target_delta = _p322_numeric_delta(current.get("target_path_score"), prev.get("target_path_score"))

        current_changes = list(current.get("what_needs_to_change") or [])
        prev_changes = list(prev.get("what_needs_to_change") or [])
        blockers_cleared = sorted(set(prev_changes) - set(current_changes))
        blockers_added = sorted(set(current_changes) - set(prev_changes))

        if current.get("bucket") == "crossed":
            drift = "crossed_trade_gate"
        elif target_delta is not None and target_delta > 0:
            drift = "improving"
        elif target_delta is not None and target_delta < 0:
            drift = "deteriorating"
        elif blockers_cleared:
            drift = "improving"
        elif blockers_added:
            drift = "deteriorating"
        else:
            drift = "flat_or_unknown"

        drift_rows.append({
            "symbol": sym,
            "bucket": current.get("bucket"),
            "status": current.get("status"),
            "drift": drift,
            "rank_score": current.get("rank_score"),
            "rank_delta": rank_delta,
            "target_path_score": current.get("target_path_score"),
            "target_path_delta": target_delta,
            "blockers_cleared": blockers_cleared,
            "blockers_added": blockers_added,
            "what_needs_to_change": current_changes,
        })

    snapshot = {
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "scan_ts_utc": alert.get("scan_ts_utc"),
        "truth_source": alert.get("truth_source"),
        "runtime_slim_applied": bool(alert.get("runtime_slim_applied")),
        "alert_active": bool(alert.get("alert_active")),
        "crossed_symbols": list(alert.get("crossed_symbols") or []),
        "near_miss_symbols": list(alert.get("near_miss_symbols") or []),
        "symbols": current_symbols,
    }

    save_result = {"saved": False, "reason": "persist_false"}
    if persist:
        history.append(snapshot)
        save_result = _p322_save_gate_crossing_state(history)

    improving = [row for row in drift_rows if row.get("drift") in {"improving", "crossed_trade_gate"}]
    deteriorating = [row for row in drift_rows if row.get("drift") == "deteriorating"]

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "near_miss_drift_tracker",
        "read_only": not bool(persist),
        "persisted": bool(save_result.get("saved")),
        "save_result": save_result,
        "history_loaded": bool(state.get("loaded")),
        "history_count_before": len(history) - (1 if persist else 0),
        "scan_ts_utc": alert.get("scan_ts_utc"),
        "truth_source": alert.get("truth_source"),
        "alert_active": bool(alert.get("alert_active")),
        "crossed_symbols": list(alert.get("crossed_symbols") or []),
        "improving_symbols": [row.get("symbol") for row in improving],
        "deteriorating_symbols": [row.get("symbol") for row in deteriorating],
        "drift": drift_rows,
        "operator_action": (
            "inspect_submit_path_trace"
            if bool(alert.get("alert_active"))
            else "keep_monitoring_drift_until_symbol_crosses_gate"
        ),
    }

def _p319_trade_readiness_morning_brief(symbols: str | None = None, limit: int | None = None) -> dict:
    watch = _p316_swing_watchlist_trade_status(
        symbols=symbols or "",
        limit=max(5, min(int(limit or 12), 25)),
    )
    intraday_sep = _p317_intraday_separation_status()

    latest_scan = {}
    try:
        latest_scan = dict(_latest_completed_scan_record() or {})
    except Exception:
        latest_scan = {}

    summary = dict((latest_scan.get("summary") if isinstance(latest_scan, dict) else {}) or {})
    scanner_runtime = dict(summary.get("scanner_runtime") or {})
    active_truth = _p320_active_position_truth_for_brief()
    position_truth = dict(active_truth.get("position_truth") or {})

    tradeable_count = int(watch.get("tradeable_count") or 0)
    watch_count = int(watch.get("watch_count") or 0)
    active_position_count = int(active_truth.get("active_position_count") or 0)

    open_slots = max(0, int(_effective_max_open_positions()) - active_position_count)
    scanner_ready = bool(
        str((latest_scan.get("reason") or summary.get("reason") or "")).lower() in {"scan_completed", "none", ""}
        and not bool(summary.get("daily_halt_active"))
    )

    blockers = []
    if daily_halt_active() or realized_closed_trade_loss_halt_active():
        blockers.append("daily_or_realized_loss_halt_active")
    if not bool(NEW_ENTRIES_ENABLED):
        blockers.append("new_entries_disabled")
    if not bool(SCANNER_ALLOW_LIVE) or bool(SCANNER_DRY_RUN):
        blockers.append("scanner_not_live")
    if open_slots <= 0:
        blockers.append("no_open_slots")
    if not scanner_ready:
        blockers.append("latest_scan_not_ready")
    if tradeable_count <= 0:
        blockers.append("no_tradeable_watch_candidates")

    if blockers:
        readiness = "watching_not_ready_to_submit"
    else:
        readiness = "ready_to_submit_when_selected_candidate_present"

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "swing_trade_readiness_morning_brief",
        "read_only": True,
        "readiness": readiness,
        "blockers": blockers,
        "now_utc": datetime.now(timezone.utc).isoformat(),
        "strategy_mode": STRATEGY_MODE,
        "entry_controls": {
            "new_entries_enabled": bool(NEW_ENTRIES_ENABLED),
            "scanner_allow_live": bool(SCANNER_ALLOW_LIVE),
            "scanner_dry_run": bool(SCANNER_DRY_RUN),
            "swing_live_enabled": bool(SWING_LIVE_ENABLED),
            "effective_entry_dry_run": bool(effective_entry_dry_run("worker_scan")),
            "exits_still_permitted": bool(is_live_exit_permitted("worker_exit")),
        },
        "capacity": {
            "active_position_count": active_position_count,
            "active_symbols": list(active_truth.get("symbols") or []),
            "position_count_source": active_truth.get("source"),
            "effective_max_open_positions": int(_effective_max_open_positions()),
            "open_slots": open_slots,
        },
        "latest_scan": {
            "truth_source": watch.get("truth_source"),
            "scan_ts_utc": watch.get("scan_ts_utc") or latest_scan.get("ts_utc"),
            "runtime_slim_applied": bool(watch.get("runtime_slim_applied")),
            "runtime_symbols_used_count": watch.get("runtime_symbols_used_count"),
            "runtime_symbols_original_count": watch.get("runtime_symbols_original_count"),
            "selected_total": int(watch.get("selected_total") or summary.get("selected_total") or 0),
            "eligible_total": int(watch.get("eligible_total") or summary.get("eligible_total") or 0),
            "tradeable_count": tradeable_count,
            "watch_count": watch_count,
        },
        "position_truth": {
            "ok": bool(position_truth.get("ok", True)),
            "status": position_truth.get("status"),
            "mismatch_count": position_truth.get("mismatch_count"),
            "recommended_action": position_truth.get("recommended_action"),
        },
        "top_watch": list(watch.get("items") or [])[:max(1, min(int(limit or 6), 12))],
        "intraday_separation_status": intraday_sep,
        "dead_path_phase_1": _p320_swing_dead_path_phase1_status(),
        "operator_action": (
            "monitor_watch_endpoint_and_wait_for_candidate_to_cross_gate"
            if tradeable_count <= 0
            else "inspect_submission_truth_for_tradeable_candidate"
        ),
    }

def _p313_fast_no_trade_recheck_hint(summary: dict | None = None, rows: list | None = None) -> dict:
    summary = dict(summary or {})
    if not bool(SWING_FAST_NO_TRADE_RECHECK_ENABLED):
        return {"enabled": False, "apply": False, "reason": "fast_no_trade_recheck_disabled"}

    selected_total = int(summary.get("selected_total") or 0)
    eligible_total = int(summary.get("eligible_total") or 0)
    if selected_total > 0 or eligible_total > 0:
        return {"enabled": True, "apply": False, "reason": "scan_has_selected_or_eligible_candidates"}

    if daily_halt_active() or realized_closed_trade_loss_halt_active():
        return {"enabled": True, "apply": False, "reason": "loss_halt_active"}

    candidate_rows = [dict(r) for r in list(rows or summary.get("top_candidates") or []) if isinstance(r, dict)]
    watch = []
    for row in candidate_rows:
        target_path = dict(row.get("target_path_profit") or _p283_target_path_profit_score(row))
        score = float(_safe_float(target_path.get("score")))
        rank_score = float(_safe_float(row.get("rank_score")))
        reasons = [str(x) for x in list(row.get("rejection_reasons") or []) if str(x)]
        if (
            rank_score >= float(SWING_FAST_NO_TRADE_RECHECK_MIN_RANK_SCORE)
            and score >= float(SWING_FAST_NO_TRADE_RECHECK_MIN_TARGET_SCORE)
            and "target_profile_breakout_gate" in reasons
        ):
            watch.append({
                "symbol": row.get("symbol"),
                "rank_score": round(rank_score, 4),
                "target_path_score": round(score, 4),
                "rejection_reasons": reasons,
            })

    watch = watch[:max(1, int(SWING_FAST_NO_TRADE_RECHECK_MAX_SYMBOLS or 5))]
    apply = bool(watch and in_market_hours())

    return {
        "enabled": True,
        "apply": apply,
        "reason": "rank_strong_target_gate_watchlist" if apply else "no_rank_strong_target_gate_watchlist",
        "sleep_sec": int(SWING_FAST_NO_TRADE_RECHECK_SEC),
        "watch_symbols": [r.get("symbol") for r in watch],
        "watch": watch,
    }

def _p283_latest_thrive_candidates(limit: int | None = None) -> dict:
    lim = max(1, min(int(limit or SWING_THRIVE_BRIEF_LIMIT or 10), 25))
    active_scan = _p285_saved_truth_scan(limit=max(25, lim))
    rows = _p285_saved_candidate_rows(active_scan, limit=max(25, lim))

    target_rows = [
        row for row in rows
        if str(row.get("strategy") or "").strip().lower() in {BREAKOUT_STRATEGY_NAME, "daily_breakout"}
    ]
    mean_reversion_rows = [
        row for row in rows
        if str(row.get("strategy") or "").strip().lower() == MEAN_REVERSION_STRATEGY_NAME
    ]

    target_rows.sort(key=_p283_candidate_sort_key, reverse=True)
    mean_reversion_rows.sort(key=_p283_candidate_sort_key, reverse=True)

    recovery_rows = [
        row for row in target_rows
        if bool((row.get("target_path_recovery") or {}).get("applies"))
    ]

    return {
        "target_path_candidates": target_rows[:lim],
        "mean_reversion_candidates": mean_reversion_rows[:lim],
        "target_path_pass_count": sum(1 for row in target_rows if bool((row.get("target_path_profit") or {}).get("passed"))),
        "target_path_strong_count": sum(1 for row in target_rows if float(_safe_float((row.get("target_path_profit") or {}).get("score"))) >= float(SWING_TARGET_PATH_STRONG_SCORE)),
        "target_path_recovery_count": len(recovery_rows),
        "target_path_recovery_symbols": sorted({
            str(row.get("symbol") or "").upper()
            for row in recovery_rows
            if row.get("symbol")
        }),
        "mean_reversion_eligible_count": sum(1 for row in mean_reversion_rows if bool(row.get("eligible"))),
    }

def _p283_swing_thrive_brief(limit: int | None = None) -> dict:
    lim = max(1, min(int(limit or SWING_THRIVE_BRIEF_LIMIT or 10), 25))
    active_scan = _p285_saved_truth_scan(limit=max(25, int(limit or SWING_THRIVE_BRIEF_LIMIT or 10)))
    summary = dict((active_scan.get("summary") if isinstance(active_scan, dict) else {}) or {})
    try:
        control = _p282_profit_restoration_control_surface()
    except Exception as exc:
        logger.exception("P285_THRIVE_CONTROL_SURFACE_FAILED")
        control = {
            "control_error": str(exc),
            "target_winner_profile": _p282_target_winner_profile(),
        }
    candidates = _p283_latest_thrive_candidates(limit=lim)

    selected_symbols = list(summary.get("selected_symbols") or [])
    target_pass = int(candidates.get("target_path_pass_count") or 0)
    target_strong = int(candidates.get("target_path_strong_count") or 0)
    target_recovery_count = int(candidates.get("target_path_recovery_count") or 0)
    target_recovery_symbols = list(candidates.get("target_path_recovery_symbols") or [])
    mr_eligible = int(candidates.get("mean_reversion_eligible_count") or 0)

    if selected_symbols:
        status = "thriving_selected"
        action = "monitor_entries_and_fills"
    elif target_recovery_count > 0:
        status = "target_path_recovery_available"
        action = "allow_recovered_target_path_entries"
    elif target_pass > 0:
        status = "profit_candidates_available_not_selected"
        action = "inspect_capacity_or_submission_path"
    elif mr_eligible > 0:
        status = "mean_reversion_fallback_available"
        action = "allow_mean_reversion_fallback"
    else:
        status = "waiting_for_profit_path"
        action = "wait_for_target_path_or_mean_reversion_setup"

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "swing_thrive_brief",
        "read_only": True,
        "truth_source": str((active_scan or {}).get("_scan_source") or "current_runtime_truth"),
        "status": status,
        "recommended_action": action,
        "profit_engine": {
            "enabled": bool(SWING_TARGET_PATH_PROFIT_ENGINE_ENABLED),
            "min_score": float(SWING_TARGET_PATH_MIN_SCORE),
            "strong_score": float(SWING_TARGET_PATH_STRONG_SCORE),
            "target_path_pass_count": target_pass,
            "target_path_strong_count": target_strong,
            "mean_reversion_fallback_enabled": bool(SWING_TARGET_PATH_MEAN_REVERSION_FALLBACK_ENABLED),
            "mean_reversion_eligible_count": mr_eligible,
        },
        "target_path_recovery_mode": {
            "enabled": bool(SWING_TARGET_PATH_RECOVERY_MODE_ENABLED),
            "recovered_count": target_recovery_count,
            "recovered_symbols": target_recovery_symbols,
            "min_score": float(SWING_TARGET_PATH_RECOVERY_MIN_SCORE),
            "allow_weak_tape_only": bool(SWING_TARGET_PATH_RECOVERY_ALLOW_WEAK_TAPE_ONLY),
        },
        "dynamic_entry_cap": dict(summary.get("target_path_dynamic_entry_cap") or {
            "enabled": bool(SWING_TARGET_PATH_DYNAMIC_ENTRY_CAP_ENABLED),
            "base_daily_entry_cap": int(SWING_MAX_NEW_ENTRIES_PER_DAY),
            "effective_daily_entry_cap": int(SWING_MAX_NEW_ENTRIES_PER_DAY),
            "applied": False,
            "configured_dynamic_cap": int(SWING_TARGET_PATH_DYNAMIC_ENTRY_CAP),
            "min_strong_candidates": int(SWING_TARGET_PATH_DYNAMIC_ENTRY_CAP_MIN_STRONG_CANDIDATES),
            "reasons": [],
        }),
        "strong_target_path_weak_tape_override": dict(summary.get("strong_target_path_weak_tape_override") or {
            "enabled": bool(SWING_STRONG_TARGET_PATH_WEAK_TAPE_OVERRIDE_ENABLED),
            "weak_tape": None,
            "applies": False,
            "reason": "no_capacity_truth_available",
        }),
        "target_path_opportunity_expansion_lab": dict(
            summary.get("target_path_opportunity_expansion_lab")
            or _p285_target_path_opportunity_expansion_lab(
                list(candidates.get("target_path_candidates") or [])
                + list(candidates.get("mean_reversion_candidates") or []),
                summary=summary,
                limit=lim,
            )
        ),
        "profit_model_reset": _p291_profit_model_reset_lab(
            list(candidates.get("target_path_candidates") or [])
            + list(candidates.get("mean_reversion_candidates") or []),
            summary,
        ),
        "expanded_swing_universe_discovery": _p293_expanded_swing_universe_discovery_lab(
            limit=min(lim, 10),
            max_symbols=min(int(SWING_EXPANDED_DISCOVERY_MAX_SYMBOLS or 60), 60),
        ),
        "thrive_capacity_truth": dict(summary.get("thrive_capacity_truth") or {}),
        "selected": {
            "selected_total": int(summary.get("selected_total") or 0),
            "selected_symbols": selected_symbols,
            "selected_strategy": summary.get("selected_strategy"),
        },
        "capacity": {
            "remaining_new_entries_today": summary.get("remaining_new_entries_today"),
            "max_new_entries_effective": summary.get("max_new_entries_effective"),
            "open_slots": candidate_slots_available(),
            "portfolio_exposure_remaining": summary.get("portfolio_exposure_remaining"),
        },
        "protection": {
            "daily_halt_active": bool((today_pnl_truth_snapshot() or {}).get("daily_halt_active")),
            "new_entries_globally_blocked": bool(summary.get("new_entries_globally_blocked")),
            "global_block_reasons": list(summary.get("global_block_reasons") or []),
            "top_rejection_reasons": list(summary.get("top_rejection_reasons") or [])[:lim],
        },
        "target_path_top": [
            {
                "symbol": row.get("symbol"),
                "eligible": bool(row.get("eligible")),
                "rank_score": row.get("rank_score"),
                "selection_quality_score": row.get("selection_quality_score"),
                "target_path_profit": row.get("target_path_profit"),
                "rejection_reasons": list(row.get("rejection_reasons") or []),
            }
            for row in list(candidates.get("target_path_candidates") or [])[:lim]
        ],
        "mean_reversion_top": [
            {
                "symbol": row.get("symbol"),
                "eligible": bool(row.get("eligible")),
                "rank_score": row.get("rank_score"),
                "selection_quality_score": row.get("selection_quality_score"),
                "target_path_profit": row.get("target_path_profit"),
                "rejection_reasons": list(row.get("rejection_reasons") or []),
            }
            for row in list(candidates.get("mean_reversion_candidates") or [])[:lim]
        ],
        "target_winner_profile": control.get("target_winner_profile"),
    }

def _restore_snapshot_plan_classification(plan: dict) -> dict:
    plan = dict(plan or {})
    signal = str(plan.get("signal") or "").strip().upper()
    strategy_name = str(plan.get("strategy_name") or "").strip().upper()
    explicit_class = str(plan.get("startup_restore_classification") or "").strip().lower()
    looks_recovered = signal in {"RECOVERED", "RECOVERED_OPEN_ORDER"} or strategy_name in {"RECOVERED", "RECOVERED_OPEN_ORDER"} or explicit_class == "recovered" or bool(plan.get("recovered"))
    was_recovered = bool(plan.get("recovered")) and looks_recovered
    if was_recovered:
        plan["recovered"] = True
        plan["startup_restore_classification"] = "recovered"
    else:
        plan.pop("recovered", None)
        plan.pop("recovered_at", None)
        plan["startup_restore_classification"] = "strategy"
    plan["startup_restored"] = True
    plan["broker_backed"] = True
    return plan


def _p471_exit_worker_readiness_truth(worker_status: dict | None = None, diagnostic: dict | None = None) -> dict:
    ws = dict(worker_status or {})
    if not ws:
        try:
            ws = dict(_worker_status_snapshot() or {})
        except Exception:
            ws = {}

    diag = dict(diagnostic or {})
    diag_error = ""
    if not diag and not bool(ws.get("exit_worker_running")):
        try:
            diag = dict(_worker_exit_status_snapshot(limit=5) or {})
        except Exception as exc:
            diag_error = str(exc)

    hb = dict(diag.get("heartbeat") or LAST_EXIT_HEARTBEAT or {})
    hb_status = str(hb.get("status") or ws.get("exit_worker_status") or "").strip().lower()
    age_sec = ws.get("exit_worker_age_sec")
    if age_sec is None:
        age_sec = diag.get("heartbeat_age_sec")

    max_age_sec = max(int(READINESS_EXIT_MAX_AGE_SEC or 0), 15)
    direct_running = bool(ws.get("exit_worker_running"))
    diagnostic_healthy = bool(diag.get("healthy"))
    started_stale = bool(diag.get("started_stale"))
    heartbeat_error_fresh = bool(diag.get("heartbeat_error_fresh"))
    sync_contract_ok = bool(diag.get("sync_contract_ok", True))
    risk_evidence_ok = bool(diag.get("risk_evidence_ok", True))
    retry_action = str((diag.get("exit_submit_retry_readiness") or {}).get("recommended_action") or diag.get("recommended_action") or "none").strip().lower()
    retry_clean = retry_action in {"", "none", "monitor_active_exit_truth", "ignore_stale_giveback_heartbeat_use_active_exit_truth"}
    recent_terminal_ok = bool(
        hb_status in {
            "ok",
            "idle",
            "heartbeat",
            "completed",
            "complete",
            "success",
            "outside_market_hours",
            "outside_market_hours_noop",
            "no_active_positions",
            "no_positions",
        }
        and age_sec is not None
        and float(age_sec) <= max(max_age_sec * 2, 60)
    )

    ready = bool(
        direct_running
        or diagnostic_healthy
        or (
            recent_terminal_ok
            and not started_stale
            and not heartbeat_error_fresh
            and sync_contract_ok
            and risk_evidence_ok
            and retry_clean
        )
    )

    if direct_running:
        reason = "exit_worker_running"
    elif diagnostic_healthy:
        reason = "worker_exit_status_healthy"
    elif recent_terminal_ok:
        reason = "recent_terminal_exit_heartbeat_clean"
    elif diag_error:
        reason = "worker_exit_diagnostic_unavailable"
    else:
        reason = "exit_worker_not_ready"

    return {
        "ok": True,
        "ready": ready,
        "reason": reason,
        "direct_exit_worker_running": direct_running,
        "diagnostic_healthy": diagnostic_healthy,
        "heartbeat_status": hb_status,
        "heartbeat_age_sec": age_sec,
        "max_age_sec": max_age_sec,
        "started_stale": started_stale,
        "heartbeat_error_fresh": heartbeat_error_fresh,
        "sync_contract_ok": sync_contract_ok,
        "risk_evidence_ok": risk_evidence_ok,
        "retry_action": retry_action,
        "retry_clean": retry_clean,
        "diagnostic_error": diag_error,
    }


def _normalize_worker_unmet_conditions(unmet: list[str], worker_status: dict | None = None) -> list[str]:
    items = [str(x or "").strip() for x in list(unmet or []) if str(x or "").strip()]
    ws = dict(worker_status or {})
    if bool(ws.get("scanner_running")):
        items = [x for x in items if x != "scanner_worker_not_ready"]
    if "exit_worker_not_ready" in items:
        try:
            exit_truth = _p471_exit_worker_readiness_truth(ws)
            if bool(exit_truth.get("ready")):
                items = [x for x in items if x != "exit_worker_not_ready"]
        except Exception:
            if bool(ws.get("exit_worker_running")):
                items = [x for x in items if x != "exit_worker_not_ready"]
    return list(dict.fromkeys(items))

def startup_restore_state() -> dict:
    """
    Restore active trade plans from persistent snapshot and broker positions.
    Runs at startup so redeploys do not silently lose internal exit plans.
    """
    global STARTUP_STATE
    state = {
        "ran": True,
        "ts_utc": datetime.now(tz=timezone.utc).isoformat(),
        "ts_ny": now_ny().isoformat(),
        "snapshot_found": False,
        "snapshot_path": POSITION_SNAPSHOT_PATH,
        "journal_path": JOURNAL_PATH,
        "recovered_from_snapshot_count": 0,
        "recovered_from_broker_only_count": 0,
        "stale_snapshot_count": 0,
        "stale_snapshot_symbols": [],
        "reconcile_actions": [],
        "error": "",
    }
    try:
        broker_positions = list_open_positions_details_allowed()
        broker_syms = {str(p.get("symbol") or "").upper() for p in broker_positions if str(p.get("symbol") or "").upper()}

        snapshot = read_positions_snapshot()
        active_snapshot_plans = (snapshot or {}).get("active_plans") or {}
        if active_snapshot_plans:
            state["snapshot_found"] = True

        with STATE_LOCK:
            for sym, plan in active_snapshot_plans.items():
                sym = str(sym or "").upper()
                if not sym:
                    continue
                if sym not in broker_syms:
                    state["stale_snapshot_count"] += 1
                    state["stale_snapshot_symbols"].append(sym)
                    try:
                        reconcile_info = _reconcile_manual_exit_plan(plan, sym, source="startup_reconcile")
                        if reconcile_info.get("closed_trade_recorded"):
                            state.setdefault("manual_exit_reconciled_symbols", []).append(sym)
                    except Exception as _manual_exit_err:
                        state.setdefault("manual_exit_reconcile_errors", []).append({"symbol": sym, "error": str(_manual_exit_err)})
                    continue
                if TRADE_PLAN.get(sym, {}).get("active"):
                    continue
                restored = json.loads(json.dumps(plan))
                restored["active"] = True
                restored = _restore_snapshot_plan_classification(restored)
                if restored.get("recovered"):
                    restored["recovered_at"] = now_ny().isoformat()
                    state["recovered_from_snapshot_count"] += 1
                TRADE_PLAN[sym] = restored

        rec_actions = reconcile_trade_plans_from_alpaca()
        state["reconcile_actions"] = rec_actions
        state["recovered_from_broker_only_count"] = len([a for a in rec_actions if str(a.get("action")) == "recovered_plan"])
        try:
            state["paper_lifecycle_normalization"] = normalize_paper_lifecycle_current_state(reason="startup_restore_state")
        except Exception as _norm_err:
            state["paper_lifecycle_normalization"] = {"checked": False, "error": str(_norm_err)}

        if (state["recovered_from_snapshot_count"] or state["recovered_from_broker_only_count"] or state["stale_snapshot_count"]):
            persist_positions_snapshot(reason="startup_state_restore", extra=state)
            logger.warning(
                "STARTUP_STATE_RESTORE snapshot=%s recovered_from_snapshot=%s recovered_from_broker_only=%s stale_snapshot=%s",
                state["snapshot_found"], state["recovered_from_snapshot_count"], state["recovered_from_broker_only_count"], state["stale_snapshot_count"]
            )
        else:
            logger.info("STARTUP_STATE_RESTORE snapshot=%s recovered_from_snapshot=0 recovered_from_broker_only=0 stale_snapshot=0", state["snapshot_found"])
    except Exception as e:
        state["error"] = str(e)
        logger.warning("STARTUP_STATE_RESTORE_FAILED err=%s", e)
    scan_restore = restore_scan_runtime_state()
    regime_restore = restore_regime_runtime_state()
    paper_restore = restore_paper_lifecycle_state()
    selected_entry_intent_restore = {
        "loaded": False,
        "count": 0,
        "retired": True,
        "config_removed": True,
        "reason": "selected_entry_intent_queue_retired_direct_submit_is_authoritative",
    }
    cohort_restore = restore_cohort_evidence_state()
    strategy_perf_restore = restore_strategy_performance_state()
    hybrid_proof_restore = restore_hybrid_proof_ledger_state()
    state["scan_state_restore"] = scan_restore
    state["regime_state_restore"] = regime_restore
    state["paper_lifecycle_state_restore"] = paper_restore
    state["selected_entry_intent_queue_restore"] = selected_entry_intent_restore
    state["cohort_evidence_state_restore"] = cohort_restore
    state["strategy_performance_state_restore"] = strategy_perf_restore
    state["hybrid_proof_ledger_state_restore"] = hybrid_proof_restore
    state["release_state_restore"] = restore_release_state()
    STARTUP_STATE = state
    return state


# Run startup restore only after all helper functions it depends on are defined.


def eval_hf_signal_with_debug(bars_today: list[dict], bars_5m: list[dict]) -> tuple[tuple[str, str] | None, dict]:
    """
    Higher-frequency entry logic (5m): 5m ORB + VWAP reclaim + EMA pullback.

    Returns: (signal_or_None, debug_dict)
    """
    debug: dict = {
        "enabled": True,
        "reason": None,
        "components": {},
        "near_miss": {},
    }

    if not bars_today or not bars_5m:
        debug["reason"] = "no_bars"
        return None, debug

    # Require market hours gating is handled elsewhere; this is pure signal logic.

    # --- Config (all optional envs; safe defaults) ---
    ORB_LOOKBACK_BARS = int(os.getenv("HF5_ORB_LOOKBACK_BARS", "6"))  # ~30 minutes
    RECLAIM_LOOKBACK_BARS = int(os.getenv("HF5_RECLAIM_LOOKBACK_BARS", "6"))
    ORB_TOUCH_EPS = float(os.getenv("HF5_ORB_TOUCH_EPS", "0.0015"))   # 0.15%
    VWAP_RECLAIM_EPS = float(os.getenv("HF5_VWAP_RECLAIM_EPS", "0.0005"))  # 0.05%
    EMA_RECLAIM_EPS = float(os.getenv("HF5_EMA_RECLAIM_EPS", "0.0005"))    # 0.05%

    # If you want *more* trades, set these to 0 (False)
    REQUIRE_EMA_CONFIRM = env_bool("HF5_REQUIRE_EMA_CONFIRM", False)
    REQUIRE_VWAP_CONFIRM = env_bool("HF5_REQUIRE_VWAP_CONFIRM", True)

    # --- Helpers ---
    def _bar_num(b: dict, primary: str, fallback: str, default: float = 0.0) -> float:
        v = b.get(primary)
        if v is None:
            v = b.get(fallback)
        return float(v or default)

    def _recent_cross_above(level: float, n: int) -> bool:
        if level is None:
            return False
        start_i = max(1, len(bars_5m) - n)
        for i in range(start_i, len(bars_5m)):
            prev = bars_5m[i - 1]
            cur = bars_5m[i]
            prev_close = _bar_num(prev, "close", "c")
            cur_close = _bar_num(cur, "close", "c")
            if prev_close < level and cur_close >= level:
                return True
        return False

    def _recent_reclaim_field(field: str, n: int, eps: float) -> bool:
        start_i = max(1, len(bars_5m) - n)
        for i in range(start_i, len(bars_5m)):
            prev = bars_5m[i - 1]
            cur = bars_5m[i]
            prev_close = _bar_num(prev, "close", "c")
            cur_close = _bar_num(cur, "close", "c")
            cur_low = _bar_num(cur, "low", "l", cur_close)

            prev_level = prev.get(field)
            cur_level = cur.get(field)
            if prev_level is None or cur_level is None:
                continue

            prev_level = float(prev_level)
            cur_level = float(cur_level)

            # Reclaim: was below, then closes above (or wicks through and closes above)
            if prev_close < prev_level and (cur_low <= cur_level) and cur_close >= cur_level * (1.0 + eps):
                return True
        return False

    # --- ORB levels (first 5m bar of the day) ---
    orb = bars_5m[0]
    orb_high = _bar_num(orb, "high", "h")
    orb_low = _bar_num(orb, "low", "l")

    last5 = bars_5m[-1]
    price = _bar_num(last5, "close", "c")

    # Use the most recent indicators (per-bar values exist in bars_5m)
    vwap_now = last5.get("vwap")
    ema_now = last5.get("ema_fast") or last5.get("ema")

    vwap_now_f = float(vwap_now) if vwap_now is not None else None
    ema_now_f = float(ema_now) if ema_now is not None else None

    # --- Core conditions ---
    orb_is_above = (price > orb_high) if orb_high else False
    orb_recent = _recent_cross_above(orb_high, ORB_LOOKBACK_BARS) if orb_high else False
    orb_touch = (price >= orb_high * (1.0 - ORB_TOUCH_EPS)) if orb_high else False
    orb_breakout_like = bool(orb_is_above or orb_recent or orb_touch)

    vwap_above = (vwap_now_f is not None and price >= vwap_now_f)
    vwap_reclaim = _recent_reclaim_field("vwap", RECLAIM_LOOKBACK_BARS, VWAP_RECLAIM_EPS) if vwap_now_f is not None else False

    ema_touch = (ema_now_f is not None and abs(price - ema_now_f) / max(ema_now_f, 1e-9) <= 0.0025)  # 0.25% proximity
    ema_reclaim = _recent_reclaim_field("ema_fast", RECLAIM_LOOKBACK_BARS, EMA_RECLAIM_EPS) if ema_now_f is not None else False

    debug["components"] = {
        "price": price,
        "orb_high": orb_high,
        "orb_low": orb_low,
        "orb_is_above": orb_is_above,
        "orb_recent": orb_recent,
        "orb_touch": orb_touch,
        "vwap_now": vwap_now_f,
        "vwap_above": vwap_above,
        "vwap_reclaim": vwap_reclaim,
        "ema_now": ema_now_f,
        "ema_touch": ema_touch,
        "ema_reclaim": ema_reclaim,
        "require_vwap_confirm": REQUIRE_VWAP_CONFIRM,
        "require_ema_confirm": REQUIRE_EMA_CONFIRM,
    }

    # Near-miss metrics (so we can see what's close)
    if orb_high:
        debug["near_miss"]["orb_dist_pct"] = max(0.0, (orb_high - price) / max(orb_high, 1e-9))
        debug["near_miss"]["orb_touch_eps"] = ORB_TOUCH_EPS
    if vwap_now_f:
        debug["near_miss"]["vwap_dist_pct"] = max(0.0, (vwap_now_f - price) / max(vwap_now_f, 1e-9))
        debug["near_miss"]["vwap_reclaim_eps"] = VWAP_RECLAIM_EPS
    if ema_now_f:
        debug["near_miss"]["ema_dist_pct"] = abs(price - ema_now_f) / max(ema_now_f, 1e-9)
        debug["near_miss"]["ema_reclaim_eps"] = EMA_RECLAIM_EPS

    # --- Decision logic ---
    if not orb_breakout_like:
        debug["reason"] = "no_orb_breakout"
        return None, debug

    if REQUIRE_VWAP_CONFIRM and not (vwap_above or vwap_reclaim):
        debug["reason"] = "no_vwap_confirm"
        return None, debug

    if REQUIRE_EMA_CONFIRM and not (ema_touch or ema_reclaim):
        debug["reason"] = "no_ema_confirm"
        return None, debug

    # If VWAP confirm isn't required, at least ensure we aren't breaking down
    if not REQUIRE_VWAP_CONFIRM and vwap_now_f is not None and price < vwap_now_f * 0.995:
        debug["reason"] = "below_vwap_hard"
        return None, debug

    debug["reason"] = None
    return ("hf5", "buy"), debug


def eval_hf_signal(bars_today: list[dict], bars_5m: list[dict]) -> tuple[str, str] | None:
    sig, _dbg = eval_hf_signal_with_debug(bars_today, bars_5m)
    return sig
def build_trade_plan(symbol: str, side: str, qty: float, entry_price: float, signal: str, meta: dict | None = None) -> dict:
    entry_price = float(entry_price)
    meta = meta or {}
    stop_override = meta.get("stop_price")
    take_override = meta.get("take_price")
    if stop_override is not None:
        stop_price = round(float(stop_override), 4)
    elif side == "buy":
        stop_price = round(entry_price * (1 - STOP_PCT), 2)
    else:
        stop_price = round(entry_price * (1 + STOP_PCT), 2)
    if take_override is not None:
        take_price = round(float(take_override), 4)
    elif side == "buy":
        take_price = round(entry_price * (1 + TAKE_PCT), 2)
    else:
        take_price = round(entry_price * (1 - TAKE_PCT), 2)

    requested_qty = float(qty)
    risk_per_share = abs(float(entry_price) - float(stop_price))
    actual_risk_dollars = round(abs(requested_qty) * risk_per_share, 4)
    plan = {
        "active": True,
        "side": side,
        "qty": requested_qty,
        "requested_qty": requested_qty,
        "filled_qty": requested_qty,
        "avg_fill_price": round(entry_price, 4),
        "entry_price": round(entry_price, 4),
        "stop_price": stop_price,
        "take_price": take_price,
        "initial_stop_price": stop_price,
        "initial_take_price": take_price,
        "signal": signal,
        "opened_at": now_ny().isoformat(),
        "last_exit_attempt_ts": 0,
        "actual_risk_dollars": actual_risk_dollars,
        "risk_per_share": round(risk_per_share, 4),
        "max_hold_days": int(meta.get("max_hold_days") or SWING_MAX_HOLD_DAYS),
        "strategy_name": str(meta.get("strategy_name") or meta.get("strategy") or signal or "").strip(),
        "rank_score": meta.get("rank_score"),
        "selection_quality_score": meta.get("selection_quality_score"),
        "entry_type": meta.get("entry_type"),
        "regime_mode": meta.get("regime_mode"),
        "target_path_score": meta.get("target_path_score"),
        "target_path_profit": meta.get("target_path_profit"),
        "target_path_recovery": meta.get("target_path_recovery"),
        "target_path_recovery_mode": bool(meta.get("target_path_recovery_mode")),
        "weak_tape_target_override": bool(meta.get("weak_tape_target_override")),
        "true_dollar_risk_sizing": dict(meta.get("p388_true_dollar_risk_sizing") or {}),
        "sizing_contract": "true_dollar_risk_from_active_stop",
    }
    plan["thesis"] = {
        "candidate_rank_score": meta.get("rank_score"),
        "selection_quality_score": meta.get("selection_quality_score"),
        "entry_type": meta.get("entry_type"),
        "regime_mode": meta.get("regime_mode"),
        "breakout_level": meta.get("breakout_level"),
        "breakout_ref": meta.get("breakout_ref"),
        "breakout_lookback_days": meta.get("breakout_lookback_days") or SWING_BREAKOUT_LOOKBACK_DAYS,
        "stop_basis": meta.get("stop_basis") or SWING_STOP_MODE,
        "target_r_mult": meta.get("target_r_mult") or SWING_TARGET_R_MULT,
        "candidate_ts": meta.get("scan_ts") or now_ny().isoformat(),
        "target_path_score": meta.get("target_path_score"),
        "target_path_profit": meta.get("target_path_profit"),
        "target_path_recovery": meta.get("target_path_recovery"),
        "target_path_recovery_mode": bool(meta.get("target_path_recovery_mode")),
        "weak_tape_target_override": bool(meta.get("weak_tape_target_override")),
        "entry_quality_snapshot": {
            "symbol": meta.get("symbol"),
            "strategy": meta.get("strategy") or meta.get("strategy_name") or signal,
            "rank_score": meta.get("rank_score"),
            "min_rank_score": meta.get("min_rank_score"),
            "selection_quality_score": meta.get("selection_quality_score"),
            "regime_mode": meta.get("regime_mode"),
            "return_20d_pct": meta.get("return_20d_pct"),
            "risk_per_share_pct": meta.get("risk_per_share_pct"),
            "breakout_distance_pct": meta.get("breakout_distance_pct"),
            "close_to_high_pct": meta.get("close_to_high_pct"),
            "strong_atr_relax_applied": meta.get("strong_atr_relax_applied"),
            "defensive_tightening_enabled": meta.get("defensive_tightening_enabled"),
            "defensive_max_20d_return_pct": meta.get("defensive_max_20d_return_pct"),
            "defensive_max_risk_per_share_pct": meta.get("defensive_max_risk_per_share_pct"),
            "rejection_reasons_at_entry": list(meta.get("rejection_reasons") or []),
        },
    }
    return plan



def _strategy_performance_default_state() -> dict:
    return {"closed_trades": [], "by_strategy": {}, "kill_switch": {}}


def _strategy_trade_row_fingerprint(row: dict | None) -> str:
    row = dict(row or {})
    explicit = str(row.get("close_fingerprint") or "").strip()
    if explicit:
        return explicit
    material = "|".join([
        str(row.get("symbol") or "").upper(),
        str(row.get("strategy_name") or row.get("signal") or "").strip().lower(),
        f"{_safe_float(row.get('entry_price') or 0.0):.4f}",
        f"{_safe_float(row.get('exit_price') or 0.0):.4f}",
        f"{abs(_safe_float(row.get('qty') or 0.0)):.4f}",
        str(row.get("reason") or "").strip().lower(),
        str(row.get("ts_utc") or "").strip(),
    ])
    return hashlib.sha256(material.encode("utf-8")).hexdigest()[:24]


def _sanitize_strategy_performance_state(state: dict | None) -> tuple[dict, dict]:
    state = dict(state or {})
    original_closed = list(state.get("closed_trades") or [])
    kept = []
    quarantined = []
    seen = set()
    for raw in original_closed:
        row = dict(raw or {})
        source = str(row.get("source") or "").strip().lower()
        if source in STRATEGY_PERFORMANCE_QUARANTINE_SOURCES:
            quarantined.append(row)
            continue
        fp = _strategy_trade_row_fingerprint(row)
        if fp in seen:
            quarantined.append(row)
            continue
        seen.add(fp)
        row["close_fingerprint"] = fp
        kept.append(row)
    sanitized = {
        "closed_trades": kept[-max(1, STRATEGY_PERFORMANCE_HISTORY_LIMIT):],
        "by_strategy": dict(state.get("by_strategy") or {}),
        "kill_switch": dict(state.get("kill_switch") or {}),
    }
    meta = {
        "original_count": len(original_closed),
        "kept_count": len(kept),
        "quarantined_count": len(quarantined),
        "changed": len(original_closed) != len(kept),
        "quarantined_rows": quarantined,
    }
    return sanitized, meta


def persist_strategy_performance_state(reason: str = ""):
    payload = {"saved_at_utc": datetime.now(timezone.utc).isoformat(), "reason": reason, "state": dict(STRATEGY_PERFORMANCE_STATE or _strategy_performance_default_state())}
    return _safe_json_write(STRATEGY_PERFORMANCE_STATE_PATH, payload)


def restore_strategy_performance_state() -> dict:
    payload = _safe_json_read(STRATEGY_PERFORMANCE_STATE_PATH)
    restored = {"path": STRATEGY_PERFORMANCE_STATE_PATH, "loaded": False, "closed_trades_restored": 0, "quarantine_applied": False, "quarantined_count": 0, "quarantine_path": STRATEGY_PERFORMANCE_QUARANTINE_PATH}
    state = payload.get("state") if isinstance(payload, dict) else {}
    if not isinstance(state, dict) or not state:
        globals()["STRATEGY_PERFORMANCE_STATE"] = _strategy_performance_default_state()
        return restored
    sanitized, meta = _sanitize_strategy_performance_state(state)
    enrich_meta = {"rows_seen": len(list(sanitized.get("closed_trades") or [])), "rows_changed": 0, "changed": False, "deferred": False}
    enrich_fn = globals().get("_p175_enrich_closed_trades_state")
    if callable(enrich_fn):
        sanitized, enrich_meta = enrich_fn(sanitized)
    else:
        enrich_meta["deferred"] = True
    if meta.get("changed"):
        quarantine_payload = {
            "saved_at_utc": datetime.now(timezone.utc).isoformat(),
            "reason": "patch154_quarantine",
            "prior_payload": payload if isinstance(payload, dict) else {"state": state},
            "quarantined_rows": meta.get("quarantined_rows") or [],
        }
        try:
            _safe_json_write(STRATEGY_PERFORMANCE_QUARANTINE_PATH, quarantine_payload)
        except Exception:
            pass
        restored["quarantine_applied"] = True
        restored["quarantined_count"] = int(meta.get("quarantined_count") or 0)
    globals()["STRATEGY_PERFORMANCE_STATE"] = sanitized
    _recompute_strategy_performance_state()
    if meta.get("changed") or enrich_meta.get("changed"):
        persist_strategy_performance_state(reason="patch175_historical_enrichment_rebuild")
    restored["loaded"] = True
    restored["closed_trades_restored"] = len(list((STRATEGY_PERFORMANCE_STATE or {}).get("closed_trades") or []))
    restored["patch175_enrichment"] = enrich_meta
    return restored


def _patch175_enrich_state_if_needed(state: dict | None) -> tuple[dict, dict]:
    state = dict(state or _strategy_performance_default_state())
    enrich_fn = globals().get("_p175_enrich_closed_trades_state")
    meta = {"rows_seen": len(list(state.get("closed_trades") or [])), "rows_changed": 0, "changed": False, "deferred": False}
    if not callable(enrich_fn):
        meta["deferred"] = True
        return state, meta
    enriched_state, meta = enrich_fn(state)
    if meta.get("changed"):
        globals()["STRATEGY_PERFORMANCE_STATE"] = enriched_state
        _recompute_strategy_performance_state()
        persist_strategy_performance_state(reason="patch175_late_enrichment_rebuild")
        return dict(globals().get("STRATEGY_PERFORMANCE_STATE") or enriched_state), meta
    return enriched_state, meta
    

def _recompute_strategy_performance_state() -> dict:
    state = dict(STRATEGY_PERFORMANCE_STATE or _strategy_performance_default_state())
    closed = list(state.get("closed_trades") or [])[-max(1, STRATEGY_PERFORMANCE_HISTORY_LIMIT):]
    by_strategy = {}
    for row in closed:
        strategy = str(row.get("strategy_name") or row.get("signal") or "unknown").strip().lower() or "unknown"
        bucket = by_strategy.setdefault(strategy, {"closed_trades": 0, "wins": 0, "losses": 0, "flat": 0, "avg_r_total": 0.0, "avg_return_total": 0.0, "gross_pnl": 0.0, "last_exit_utc": None, "regime_mode_counts": {}})
        bucket["closed_trades"] += 1
        pnl_r = float(row.get("pnl_r") or 0.0)
        ret_pct = float(row.get("return_pct") or 0.0)
        pnl = float(row.get("gross_pnl") or 0.0)
        if pnl_r > 0: bucket["wins"] += 1
        elif pnl_r < 0: bucket["losses"] += 1
        else: bucket["flat"] += 1
        bucket["avg_r_total"] += pnl_r
        bucket["avg_return_total"] += ret_pct
        bucket["gross_pnl"] += pnl
        bucket["last_exit_utc"] = row.get("ts_utc") or bucket.get("last_exit_utc")
        rm = str(row.get("entry_regime_mode") or "unknown").strip().lower() or "unknown"
        bucket["regime_mode_counts"][rm] = int(bucket["regime_mode_counts"].get(rm) or 0) + 1
    for bucket in by_strategy.values():
        count = max(1, int(bucket.get("closed_trades") or 0))
        bucket["avg_r"] = round(float(bucket.pop("avg_r_total") or 0.0) / count, 4)
        bucket["avg_return_pct"] = round(float(bucket.pop("avg_return_total") or 0.0) / count, 4)
        bucket["gross_pnl"] = round(float(bucket.get("gross_pnl") or 0.0), 4)
        bucket["win_rate"] = round(float(bucket.get("wins") or 0) / count, 4)
    mr_recent = [r for r in reversed(closed) if str(r.get("strategy_name") or "").strip().lower() == MEAN_REVERSION_STRATEGY_NAME][:max(1, int(SWING_MEAN_REVERSION_KILL_SWITCH_LOOKBACK_TRADES or 1))]
    mr_count = len(mr_recent)
    mr_win_rate = (sum(1 for r in mr_recent if float(r.get("pnl_r") or 0.0) > 0.0) / mr_count) if mr_count else 0.0
    mr_avg_r = (sum(float(r.get("pnl_r") or 0.0) for r in mr_recent) / mr_count) if mr_count else 0.0
    active = False; reasons = []
    active = False; reasons = []
    if SWING_MEAN_REVERSION_KILL_SWITCH_ENABLED and mr_count >= max(1, int(SWING_MEAN_REVERSION_KILL_SWITCH_MIN_TRADES or 1)):
        win_rate_bad = mr_win_rate < float(SWING_MEAN_REVERSION_KILL_SWITCH_MIN_WIN_RATE)
        avg_r_bad = mr_avg_r < float(SWING_MEAN_REVERSION_KILL_SWITCH_MIN_AVG_R)

        if bool(SWING_MEAN_REVERSION_KILL_SWITCH_REQUIRE_BOTH_WIN_RATE_AND_AVG_R):
            if win_rate_bad and avg_r_bad:
                active = True
                reasons.extend(["win_rate_below_min", "avg_r_below_min"])
            elif win_rate_bad:
                reasons.append("win_rate_below_min_but_avg_r_ok")
            elif avg_r_bad:
                reasons.append("avg_r_below_min_but_win_rate_ok")
        else:
            if win_rate_bad:
                active = True
                reasons.append("win_rate_below_min")
            if avg_r_bad:
                active = True
                reasons.append("avg_r_below_min")
    kill_switch = dict(state.get("kill_switch") or {})
    kill_switch[MEAN_REVERSION_STRATEGY_NAME] = {"enabled": bool(SWING_MEAN_REVERSION_KILL_SWITCH_ENABLED), "active": bool(active), "reasons": reasons, "sample_trades": mr_count, "lookback_trades": int(SWING_MEAN_REVERSION_KILL_SWITCH_LOOKBACK_TRADES or 0), "min_trades": int(SWING_MEAN_REVERSION_KILL_SWITCH_MIN_TRADES or 0), "win_rate": round(mr_win_rate, 4), "avg_r": round(mr_avg_r, 4), "min_win_rate": float(SWING_MEAN_REVERSION_KILL_SWITCH_MIN_WIN_RATE), "min_avg_r": float(SWING_MEAN_REVERSION_KILL_SWITCH_MIN_AVG_R), "require_both_win_rate_and_avg_r": bool(SWING_MEAN_REVERSION_KILL_SWITCH_REQUIRE_BOTH_WIN_RATE_AND_AVG_R)}
    globals()["STRATEGY_PERFORMANCE_STATE"] = {"closed_trades": closed, "by_strategy": by_strategy, "kill_switch": kill_switch}
    return globals()["STRATEGY_PERFORMANCE_STATE"]


def _append_strategy_closed_trade(plan: dict | None, exit_price: float | None, reason: str = "", source: str = "") -> dict:
    plan = dict(plan or {})
    thesis = plan.get("thesis") if isinstance(plan.get("thesis"), dict) else {}
    strategy_name = str(plan.get("strategy_name") or plan.get("signal") or "").strip().lower()
    if not strategy_name: return {}
    entry_price = _safe_float(plan.get("entry_price") or plan.get("avg_fill_price")); stop_price = _safe_float(plan.get("initial_stop_price") or plan.get("stop_price")); qty = abs(_safe_float(plan.get("filled_qty") or plan.get("qty") or 0.0)); exit_px = _safe_float(exit_price)
    if entry_price <= 0 or qty <= 0 or exit_px <= 0: return {}
    side = str(plan.get("side") or "buy").strip().lower() or "buy"
    pnl_per_share = (exit_px - entry_price) if side == "buy" else (entry_price - exit_px)
    gross_pnl = pnl_per_share * qty
    risk_per_share = abs(entry_price - stop_price) if stop_price > 0 else abs(_safe_float(plan.get("risk_per_share") or 0.0))
    exit_dt = datetime.now(timezone.utc)
    entry_dt = _p175_parse_dt(plan.get("opened_at") or plan.get("submitted_at") or plan.get("created_at"))
    holding_hours = round((exit_dt - entry_dt).total_seconds() / 3600.0, 4) if entry_dt and exit_dt >= entry_dt else None
    rank_score = _p175_rank_score(plan)
    row = {"ts_utc": exit_dt.isoformat(), "symbol": str(plan.get("symbol") or plan.get("instrument") or "").upper(), "strategy_name": strategy_name, "signal": str(plan.get("signal") or strategy_name), "entry_price": round(entry_price,4), "exit_price": round(exit_px,4), "qty": round(qty,4), "gross_pnl": round(gross_pnl,4), "pnl_r": round((pnl_per_share / risk_per_share) if risk_per_share > 0 else 0.0,4), "return_pct": round((pnl_per_share / entry_price * 100.0) if entry_price > 0 else 0.0,4), "reason": str(reason or ""), "exit_reason": str(reason or ""), "source": str(source or ""), "entry_regime_mode": str((thesis.get("regime_mode") or plan.get("regime_mode") or "")).strip().lower() or None, "max_hold_days": int(plan.get("max_hold_days") or 0), "rank_score": rank_score, "selection_quality_score": _p175_first(plan, "selection_quality_score") or thesis.get("selection_quality_score"), "entry_ts_utc": entry_dt.isoformat() if entry_dt else None, "holding_hours": holding_hours, "holding_days": round(holding_hours / 24.0, 4) if holding_hours is not None else None, "entry_type": plan.get("entry_type") or thesis.get("entry_type"), "breakout_level": thesis.get("breakout_level"), "recovered": bool(plan.get("recovered")), "attribution_backfilled": bool(plan.get("attribution_backfilled")), "attribution_source": plan.get("attribution_source")}
    row["close_fingerprint"] = _strategy_trade_row_fingerprint(row)
    state = dict(STRATEGY_PERFORMANCE_STATE or _strategy_performance_default_state()); closed = list(state.get("closed_trades") or []); closed.append(row); state["closed_trades"] = closed[-max(1, STRATEGY_PERFORMANCE_HISTORY_LIMIT):]; globals()["STRATEGY_PERFORMANCE_STATE"] = state; _recompute_strategy_performance_state(); persist_strategy_performance_state(reason=f"closed_trade:{strategy_name}"); return row


def _append_strategy_closed_trade_row(row: dict | None, reason: str = "") -> dict:
    row = dict(row or {})
    if not row.get("symbol") or not row.get("strategy_name"):
        return {}
    row["close_fingerprint"] = _strategy_trade_row_fingerprint(row)
    state = dict(STRATEGY_PERFORMANCE_STATE or _strategy_performance_default_state())
    closed = list(state.get("closed_trades") or [])
    existing = {str(r.get("close_fingerprint") or _strategy_trade_row_fingerprint(r)) for r in closed if isinstance(r, dict)}
    exit_order_id = str(row.get("exit_order_id") or "").strip()
    if exit_order_id and any(str((r or {}).get("exit_order_id") or "").strip() == exit_order_id for r in closed if isinstance(r, dict)):
        return {}
    if str(row.get("close_fingerprint") or "") in existing:
        return {}
    closed.append(row)
    state["closed_trades"] = closed[-max(1, STRATEGY_PERFORMANCE_HISTORY_LIMIT):]
    globals()["STRATEGY_PERFORMANCE_STATE"] = state
    _recompute_strategy_performance_state()
    persist_strategy_performance_state(reason=reason or "closed_trade_row_append")
    return row

def _p244_exit_audit_session_key(row: dict | None) -> str:
    row = dict(row or {})
    ts = _p175_parse_dt(row.get("ts_utc") or row.get("closed_at") or row.get("exit_ts_utc"))
    day = ts.date().isoformat() if ts else str(row.get("session_date") or "")[:10]
    return "|".join([
        str(row.get("symbol") or "").upper(),
        str(row.get("strategy_name") or row.get("signal") or "").strip().lower(),
        day,
    ])


def _p244_duplicate_realized_exit_audit(state: dict | None = None) -> dict:
    rows = [dict(r or {}) for r in list((state or STRATEGY_PERFORMANCE_STATE or {}).get("closed_trades") or []) if isinstance(r, dict)]
    groups: dict[str, list[dict]] = {}
    for row in rows:
        key = _p244_exit_audit_session_key(row)
        if key.strip("|"):
            groups.setdefault(key, []).append(row)

    duplicate_groups = []
    worker_shadowed_rows = []
    broker_rows = []
    for key, group in groups.items():
        broker = [r for r in group if str(r.get("source") or "").strip().lower() == "alpaca_orders_reconciled" or str(r.get("reason") or "").strip().lower() == "broker_exit_fill"]
        worker = [r for r in group if str(r.get("source") or "").strip().lower() == "worker_exit"]
        if broker:
            broker_rows.extend(broker)
        if broker and worker:
            worker_shadowed_rows.extend(worker)
            duplicate_groups.append({
                "key": key,
                "symbol": str((broker[0] or {}).get("symbol") or (worker[0] or {}).get("symbol") or "").upper(),
                "broker_count": len(broker),
                "worker_count": len(worker),
                "broker_gross_pnl": round(sum(_safe_float(r.get("gross_pnl")) for r in broker), 4),
                "worker_gross_pnl": round(sum(_safe_float(r.get("gross_pnl")) for r in worker), 4),
                "broker_rows": broker[-5:],
                "worker_rows": worker[-5:],
            })

    broker_total = round(sum(_safe_float(r.get("gross_pnl")) for r in broker_rows), 4)
    shadowed_total = round(sum(_safe_float(r.get("gross_pnl")) for r in worker_shadowed_rows), 4)
    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "read_only_duplicate_realized_exit_audit",
        "closed_trade_count": len(rows),
        "duplicate_group_count": len(duplicate_groups),
        "worker_shadowed_count": len(worker_shadowed_rows),
        "broker_reconciled_count": len(broker_rows),
        "broker_reconciled_gross_pnl": broker_total,
        "worker_shadowed_gross_pnl": shadowed_total,
        "accounting_preference": "broker_exit_fill_rows_preferred_over_worker_exit_estimates",
        "duplicate_groups": duplicate_groups[-25:],
        "recommended_action": "ignore_worker_shadowed_rows_for_realized_pnl" if duplicate_groups else "none",
    }

def _p245_is_broker_reconciled_exit(row: dict | None) -> bool:
    row = dict(row or {})
    source = str(row.get("source") or "").strip().lower()
    reason = str(row.get("reason") or row.get("exit_reason") or "").strip().lower()
    return bool(row.get("broker_reconciled")) or source == "alpaca_orders_reconciled" or reason == "broker_exit_fill"

def _p443_known_exit_reason(value: object) -> str:
    reason = str(value or "").strip().lower()
    if not reason or reason in {"broker_exit_fill", "alpaca_orders_reconciled", "order_submitted", "partial_order_submitted"}:
        return ""
    return reason


def _p443_dt_distance_seconds(a: object, b: object) -> float | None:
    da = _p175_parse_dt(a)
    db = _p175_parse_dt(b)
    if not da or not db:
        return None
    return abs((da.astimezone(timezone.utc) - db.astimezone(timezone.utc)).total_seconds())


def _p443_infer_broker_exit_attribution(row: dict | None) -> dict:
    broker = dict(row or {})
    sym = str(broker.get("symbol") or "").strip().upper()
    if not sym:
        return {}

    broker_ts = broker.get("ts_utc") or broker.get("closed_at") or broker.get("exit_ts_utc")
    candidates = []

    decision_rows = [dict(r or {}) for r in list(DECISIONS or [])]
    decision_rows.extend(_read_journal(limit=JOURNAL_BOOTSTRAP_LIMIT, symbol=sym))

    for item in reversed(decision_rows):
        if str(item.get("symbol") or "").strip().upper() != sym:
            continue
        event = str(item.get("event") or "").strip().upper()
        if event not in {"EXIT", "RECONCILE"}:
            continue

        details = dict(item.get("details") or {}) if isinstance(item.get("details"), dict) else {}
        reason = _p443_known_exit_reason(
            item.get("exit_reason")
            or item.get("reason")
            or details.get("exit_reason")
            or details.get("reason")
            or item.get("action")
            or details.get("action")
        )
        if not reason:
            continue

        distance = _p443_dt_distance_seconds(
            broker_ts,
            item.get("ts_utc") or item.get("timestamp") or details.get("ts_utc"),
        )
        if distance is not None and distance > 6 * 60 * 60:
            continue

        candidates.append({
            "exit_reason": reason,
            "reason": reason,
            "attributed_exit_reason": reason,
            "exit_attribution_source": "decision_exit_row",
            "exit_attribution_ts_utc": item.get("ts_utc") or item.get("timestamp"),
            "exit_attribution_distance_sec": round(distance, 2) if distance is not None else None,
        })

    if candidates:
        candidates.sort(key=lambda r: (
            r.get("exit_attribution_distance_sec") is None,
            float(r.get("exit_attribution_distance_sec") or 999999.0),
        ))
        return candidates[0]

    return {}


def _p443_is_breakout_candidate(row: dict | None) -> bool:
    r = dict(row or {})
    blob = " ".join([
        str(r.get("strategy") or ""),
        str(r.get("strategy_name") or ""),
        str(r.get("signal") or ""),
        str(r.get("entry_type") or ""),
        str(r.get("selected_source") or ""),
    ]).strip().lower()
    return "breakout" in blob


def _p443_breakout_dollar_risk_containment(candidate: dict | None) -> dict:
    c = dict(candidate or {})
    truth = _p384_candidate_dollar_risk_truth(c)
    max_risk = max(0.0, float(SWING_BREAKOUT_DOLLAR_RISK_MAX_DOLLARS or 0.0))
    dollar_risk = float(_safe_float(truth.get("dollar_risk"), 0.0))
    applies = bool(
        SWING_BREAKOUT_DOLLAR_RISK_CONTAINMENT_ENABLED
        and _p443_is_breakout_candidate(c)
        and max_risk > 0
        and dollar_risk > max_risk
    )
    return {
        "enabled": bool(SWING_BREAKOUT_DOLLAR_RISK_CONTAINMENT_ENABLED),
        "applies": applies,
        "reason": "breakout_dollar_risk_above_containment_max" if applies else "ok",
        "max_dollar_risk": round(max_risk, 4),
        "dollar_risk": round(dollar_risk, 4),
        "dollar_risk_selection_truth": truth,
    }


def _p443_apply_breakout_dollar_risk_containment(candidate: dict | None) -> dict:
    c = dict(candidate or {})
    containment = _p443_breakout_dollar_risk_containment(c)
    c["breakout_dollar_risk_containment"] = containment
    if containment.get("applies"):
        reasons = _dedupe_candidate_reasons(
            list(c.get("rejection_reasons") or [])
            + ["breakout_dollar_risk_above_containment_max"]
        )
        c["eligible"] = False
        c["selected"] = False
        c["production_contract_approved"] = False
        c["rejection_reasons"] = reasons
        contract = dict(c.get("swing_production_contract") or {})
        contract["approved"] = False
        contract["p443_breakout_dollar_risk_containment"] = containment
        blockers = _dedupe_candidate_reasons(list(contract.get("blockers") or []) + ["breakout_dollar_risk_above_containment_max"])
        contract["blockers"] = blockers
        c["swing_production_contract"] = contract
    return c

def _p441_broker_reconciled_r_backfill(row: dict | None, attribution: dict | None = None) -> dict:
    out = dict(row or {})
    attribution = dict(attribution or {})
    if not _p245_is_broker_reconciled_exit(out):
        return out

    out["accounting_source"] = out.get("accounting_source") or "broker_reconciled_fill"
    out["broker_accounting_reason"] = out.get("broker_accounting_reason") or str(out.get("reason") or out.get("exit_reason") or "broker_exit_fill")

    for key in (
        "strategy_name",
        "signal",
        "entry_type",
        "entry_regime_mode",
        "regime_mode",
        "rank_score",
        "selection_quality_score",
        "breakout_level",
        "entry_ts_utc",
        "holding_hours",
        "holding_days",
    ):
        if out.get(key) in (None, "", [], {}) and attribution.get(key) not in (None, "", [], {}):
            out[key] = attribution.get(key)

    attributed_exit_reason = str(
        attribution.get("exit_reason")
        or attribution.get("reason")
        or out.get("attributed_exit_reason")
        or ""
    ).strip().lower()
    if attributed_exit_reason and attributed_exit_reason != "broker_exit_fill":
        out["attributed_exit_reason"] = attributed_exit_reason
        out["exit_reason"] = attributed_exit_reason
        out["reason"] = attributed_exit_reason
        out["broker_exit_reason"] = "broker_exit_fill"

    if out.get("entry_type") in (None, "", "alpaca_orders_reconciled"):
        recovered_entry_type = attribution.get("entry_type")
        out["entry_type"] = recovered_entry_type if recovered_entry_type not in (None, "", [], {}) else "broker_reconciled"

    entry_px = _safe_float(out.get("entry_price"), 0.0)
    exit_px = _safe_float(out.get("exit_price"), 0.0)
    qty = abs(_safe_float(out.get("qty"), 0.0))
    gross = _safe_float(out.get("gross_pnl"), 0.0)

    risk_per_share = _safe_float(
        out.get("risk_per_share")
        or attribution.get("risk_per_share")
        or 0.0,
        0.0,
    )
    stop_px = _safe_float(
        out.get("stop_price")
        or out.get("initial_stop_price")
        or attribution.get("stop_price")
        or attribution.get("initial_stop_price")
        or 0.0,
        0.0,
    )
    if risk_per_share <= 0 and entry_px > 0 and stop_px > 0:
        risk_per_share = abs(entry_px - stop_px)

    existing_r = _safe_float(out.get("pnl_r"), 0.0)
    if qty > 0 and risk_per_share > 0 and abs(existing_r) <= 1e-9:
        pnl_per_share = gross / qty
        out["pnl_r"] = round(pnl_per_share / risk_per_share, 4)
        out["attributed_pnl_r"] = out["pnl_r"]
        out["r_backfill_source"] = "broker_fill_gross_pnl_over_qty_risk_per_share"
        out["risk_per_share"] = round(risk_per_share, 4)
    elif risk_per_share > 0:
        out["risk_per_share"] = round(risk_per_share, 4)

    if entry_px > 0 and exit_px > 0 and out.get("return_pct") in (None, "", 0, 0.0):
        out["return_pct"] = round(((exit_px - entry_px) / entry_px) * 100.0, 4)

    out["broker_reconciled_attribution_cleaned"] = True
    out["broker_reconciled_attribution_patch"] = PATCH_VERSION
    return out

def _p375_broker_fill_economic_key(row: dict | None) -> str:
    row = dict(row or {})
    exit_order_id = str(row.get("exit_order_id") or row.get("order_id") or "").strip()
    if exit_order_id:
        return f"exit_order_id:{exit_order_id}"

    symbol = str(row.get("symbol") or "").strip().upper()
    qty = abs(_safe_float(row.get("qty"), 0.0))
    entry_px = _safe_float(row.get("entry_price"), 0.0)
    exit_px = _safe_float(row.get("exit_price"), 0.0)
    ts = str(row.get("ts_utc") or row.get("closed_at") or row.get("exit_ts") or "").strip()
    ts_bucket = ts[:19] if ts else ""
    return "|".join([
        "economic_fill",
        symbol,
        f"{qty:.4f}",
        f"{entry_px:.4f}",
        f"{exit_px:.4f}",
        ts_bucket,
    ])

def _p245_broker_preferred_closed_rows(state: dict | None = None) -> dict:
    rows = [dict(r or {}) for r in list((state or STRATEGY_PERFORMANCE_STATE or {}).get("closed_trades") or []) if isinstance(r, dict)]
    broker_keys = {
        _p244_exit_audit_session_key(r)
        for r in rows
        if _p245_is_broker_reconciled_exit(r)
    }

    broker_seen: dict[str, dict] = {}
    kept = []
    shadowed = []
    broker_fill_duplicates = []

    for row in rows:
        key = _p244_exit_audit_session_key(row)
        source = str(row.get("source") or "").strip().lower()
        is_broker = _p245_is_broker_reconciled_exit(row)

        if key in broker_keys and source == "worker_exit" and not is_broker:
            shadow = dict(row)
            shadow["preferred_basis"] = "worker_exit_shadowed_by_broker_reconciled_exit"
            shadow["daily_loss_truth_included"] = False
            shadowed.append(shadow)
            continue

        if is_broker:
            economic_key = _p375_broker_fill_economic_key(row)
            if economic_key in broker_seen:
                duplicate = dict(row)
                duplicate["duplicate_of"] = economic_key
                duplicate["preferred_basis"] = "duplicate_broker_fill_shadowed"
                duplicate["daily_loss_truth_included"] = False
                broker_fill_duplicates.append(duplicate)
                continue
            inferred = _infer_recovered_plan_attribution(
                str(row.get("symbol") or ""),
                order_id=str(row.get("entry_order_id") or ""),
            )
            exit_inferred = _p443_infer_broker_exit_attribution(row)
            if exit_inferred:
                inferred = {**inferred, **exit_inferred}
            clean = _p441_broker_reconciled_r_backfill(row, attribution=inferred)
            if exit_inferred:
                clean["exit_attribution_recovered"] = True
            clean["broker_fill_economic_key"] = economic_key
            clean["preferred_basis"] = "strategy_state_broker_reconciled_estimate_row"
            clean["daily_loss_truth_included"] = True
            broker_seen[economic_key] = clean
            kept.append(clean)
            continue

        kept.append(row)

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "source": "strategy_state_broker_reconciled_estimate",
        "legacy_name": "broker_preferred_strategy_state",
        "canonical_daily_loss_source": "broker_only_daily_loss_truth",
        "raw_count": len(rows),
        "kept_count": len(kept),
        "broker_fill_deduped_count": len(broker_seen),
        "broker_fill_duplicate_count": len(broker_fill_duplicates),
        "shadowed_worker_count": len(shadowed),
        "shadowed_worker_gross_pnl": round(sum(_safe_float(r.get("gross_pnl")) for r in shadowed), 4),
        "broker_fill_duplicate_gross_pnl": round(sum(_safe_float(r.get("gross_pnl")) for r in broker_fill_duplicates), 4),
        "kept_rows": kept,
        "shadowed_rows": shadowed[-25:],
        "broker_fill_duplicate_rows": broker_fill_duplicates[-25:],
    }

def _p245_performance_rollup(rows: list[dict] | None) -> dict:
    rows = [dict(r or {}) for r in list(rows or []) if isinstance(r, dict)]
    wins = losses = flat = 0
    gross = 0.0
    r_total = 0.0
    by_strategy: dict[str, dict] = {}
    for row in rows:
        pnl = _safe_float(row.get("gross_pnl"), 0.0)
        pnl_r = _safe_float(row.get("pnl_r"), 0.0)
        gross += pnl
        r_total += pnl_r
        if pnl > 0:
            wins += 1
        elif pnl < 0:
            losses += 1
        else:
            flat += 1

        strategy = str(row.get("strategy_name") or row.get("signal") or "unknown").strip().lower() or "unknown"
        bucket = by_strategy.setdefault(strategy, {"closed_trades": 0, "wins": 0, "losses": 0, "flat": 0, "gross_pnl": 0.0, "avg_r_total": 0.0})
        bucket["closed_trades"] += 1
        bucket["gross_pnl"] += pnl
        bucket["avg_r_total"] += pnl_r
        if pnl > 0:
            bucket["wins"] += 1
        elif pnl < 0:
            bucket["losses"] += 1
        else:
            bucket["flat"] += 1

    for bucket in by_strategy.values():
        count = max(1, int(bucket.get("closed_trades") or 0))
        bucket["gross_pnl"] = round(float(bucket.get("gross_pnl") or 0.0), 4)
        bucket["avg_r"] = round(float(bucket.pop("avg_r_total") or 0.0) / count, 4)
        bucket["win_rate"] = round(float(bucket.get("wins") or 0) / count, 4)

    count = len(rows)
    return {
        "closed_trades": count,
        "wins": wins,
        "losses": losses,
        "flat": flat,
        "win_rate": round(wins / max(1, count), 4) if count else 0.0,
        "gross_pnl": round(gross, 4),
        "avg_r": round(r_total / max(1, count), 4) if count else 0.0,
        "sample_maturity": "ESTABLISHED" if count >= 100 else "BUILDING",
        "by_strategy": by_strategy,
    }


def _p245_broker_preferred_performance_snapshot() -> dict:
    preferred = _p245_broker_preferred_closed_rows()
    kept_rows = list(preferred.get("kept_rows") or [])
    rollup = _p245_performance_rollup(kept_rows)
    broker_rows = [r for r in kept_rows if _p245_is_broker_reconciled_exit(r)]
    broker_rows_with_r = [r for r in broker_rows if abs(_safe_float(r.get("pnl_r"), 0.0)) > 1e-9]
    raw_rollup = _p245_performance_rollup(list((STRATEGY_PERFORMANCE_STATE or {}).get("closed_trades") or []))
    broker_only = _p374_broker_only_daily_loss_truth() if "_p374_broker_only_daily_loss_truth" in globals() else {}

    today_strategy_estimate = _p254_broker_preferred_today_strategy_realized_pnl()
    broker_only_realized = _safe_float(broker_only.get("today_realized_pnl"), 0.0)
    today_strategy_realized = _safe_float(today_strategy_estimate.get("today_realized_pnl"), 0.0)
    today_delta = round(today_strategy_realized - broker_only_realized, 4)

    all_time_strategy_state_estimate = _safe_float(rollup.get("gross_pnl"), 0.0)
    all_time_minus_today_broker_delta = round(all_time_strategy_state_estimate - broker_only_realized, 4)

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "strategy_state_broker_reconciled_estimate_rollup",
        "legacy_mode": "broker_preferred_performance_rollup",
        "canonical_daily_loss_source": "broker_only_daily_loss_truth",
        "accounting_note": "This endpoint is a strategy-state estimate only. Use /diagnostics/broker_only_daily_loss_truth for daily loss and halt truth.",
        "broker_reconciled_attribution_cleanup": {
            "broker_row_count": len(broker_rows),
            "broker_rows_with_nonzero_r": len(broker_rows_with_r),
            "broker_rows_missing_r": max(0, len(broker_rows) - len(broker_rows_with_r)),
            "r_coverage_pct": round(len(broker_rows_with_r) / max(1, len(broker_rows)), 4) if broker_rows else 0.0,
            "entry_type_scrubbed": True,
            "broker_exit_fill_kept_as_accounting_source": True,
            "recommended_action": "use_cleaned_r_for_risk_scaling_review" if broker_rows_with_r else "continue_backfilling_broker_r",
        },
        "raw": raw_rollup,
        "strategy_state_broker_reconciled_estimate": rollup,
        "broker_preferred": rollup,
        "broker_only_daily_loss_truth": {
            "today_realized_pnl": broker_only.get("today_realized_pnl"),
            "today_net_pnl": broker_only.get("today_net_pnl"),
            "account_daily_pnl": broker_only.get("account_daily_pnl"),
            "accounting_source": broker_only.get("accounting_source"),
        },
        "strategy_state_vs_broker_only_today_delta": today_delta,
        "today_strategy_state_broker_reconciled_estimate": {
            "today_realized_pnl": today_strategy_estimate.get("today_realized_pnl"),
            "closed_trades_today": today_strategy_estimate.get("closed_trades_today"),
            "broker_reconciled_rows_today": today_strategy_estimate.get("broker_reconciled_rows_today"),
            "worker_exit_shadow_quarantined_rows_today": today_strategy_estimate.get("worker_exit_shadow_quarantined_rows_today"),
            "shadow_worker_exit_estimate_pnl": today_strategy_estimate.get("shadow_worker_exit_estimate_pnl"),
            "source": today_strategy_estimate.get("source"),
        },
        "all_time_strategy_state_rollup_gross_pnl": rollup.get("gross_pnl"),
        "all_time_strategy_state_vs_today_broker_delta_unusable": all_time_minus_today_broker_delta,
        "broker_fill_deduped_count": preferred.get("broker_fill_deduped_count"),
        "broker_fill_duplicate_count": preferred.get("broker_fill_duplicate_count"),
        "broker_fill_duplicate_gross_pnl": preferred.get("broker_fill_duplicate_gross_pnl"),
        "shadowed_worker_count": preferred.get("shadowed_worker_count"),
        "shadowed_worker_gross_pnl": preferred.get("shadowed_worker_gross_pnl"),
        "shadowed_rows": preferred.get("shadowed_rows") or [],
        "broker_fill_duplicate_rows": preferred.get("broker_fill_duplicate_rows") or [],
        "duplicate_exit_audit": _p244_duplicate_realized_exit_audit(),
        "recommended_action": "use_broker_only_daily_loss_truth_for_daily_pnl; use_this_endpoint_for_strategy_state_drift_only",
    }

def _p442_trade_ts_utc(row: dict | None) -> str:
    r = dict(row or {})
    return str(r.get("ts_utc") or r.get("closed_at") or r.get("exit_ts_utc") or r.get("exit_ts") or "")


def _p442_trade_dollar_risk(row: dict | None) -> float:
    r = dict(row or {})
    qty = abs(_safe_float(r.get("qty"), 0.0))
    risk_per_share = _safe_float(r.get("risk_per_share"), 0.0)
    if risk_per_share <= 0:
        entry = _safe_float(r.get("entry_price"), 0.0)
        stop = _safe_float(r.get("stop_price") or r.get("initial_stop_price"), 0.0)
        if entry > 0 and stop > 0:
            risk_per_share = abs(entry - stop)
    return max(0.0, qty * risk_per_share)


def _p442_trade_notional(row: dict | None) -> float:
    r = dict(row or {})
    qty = abs(_safe_float(r.get("qty"), 0.0))
    entry = _safe_float(r.get("entry_price"), 0.0)
    return max(0.0, qty * entry)


def _p442_bucket_summary(rows: list[dict] | None, key_fn, *, limit: int = 20) -> list[dict]:
    buckets: dict[str, dict] = {}
    for raw in list(rows or []):
        row = dict(raw or {})
        key = str(key_fn(row) or "unknown").strip().lower() or "unknown"
        pnl = _safe_float(row.get("gross_pnl"), 0.0)
        pnl_r = _safe_float(row.get("pnl_r"), 0.0)
        dollar_risk = _p442_trade_dollar_risk(row)
        notional = _p442_trade_notional(row)
        qty = abs(_safe_float(row.get("qty"), 0.0))
        risk_per_share = _safe_float(row.get("risk_per_share"), 0.0)
        hold_hours = _safe_float(row.get("holding_hours"), 0.0)

        b = buckets.setdefault(key, {
            "name": key,
            "closed_trades": 0,
            "wins": 0,
            "losses": 0,
            "flat": 0,
            "gross_pnl": 0.0,
            "r_total": 0.0,
            "dollar_risk_total": 0.0,
            "position_notional_total": 0.0,
            "qty_total": 0.0,
            "risk_per_share_total": 0.0,
            "holding_hours_total": 0.0,
            "largest_win": None,
            "largest_loss": None,
            "worst_r": None,
            "best_r": None,
        })
        b["closed_trades"] += 1
        b["gross_pnl"] += pnl
        b["r_total"] += pnl_r
        b["dollar_risk_total"] += dollar_risk
        b["position_notional_total"] += notional
        b["qty_total"] += qty
        b["risk_per_share_total"] += risk_per_share
        b["holding_hours_total"] += hold_hours
        if pnl > 0:
            b["wins"] += 1
        elif pnl < 0:
            b["losses"] += 1
        else:
            b["flat"] += 1
        b["largest_win"] = pnl if b["largest_win"] is None else max(float(b["largest_win"]), pnl)
        b["largest_loss"] = pnl if b["largest_loss"] is None else min(float(b["largest_loss"]), pnl)
        b["worst_r"] = pnl_r if b["worst_r"] is None else min(float(b["worst_r"]), pnl_r)
        b["best_r"] = pnl_r if b["best_r"] is None else max(float(b["best_r"]), pnl_r)

    out = []
    for b in buckets.values():
        count = max(1, int(b.get("closed_trades") or 0))
        out.append({
            "name": b.get("name"),
            "closed_trades": int(b.get("closed_trades") or 0),
            "wins": int(b.get("wins") or 0),
            "losses": int(b.get("losses") or 0),
            "flat": int(b.get("flat") or 0),
            "win_rate": round(float(b.get("wins") or 0) / count, 4),
            "gross_pnl": round(float(b.get("gross_pnl") or 0.0), 4),
            "avg_pnl": round(float(b.get("gross_pnl") or 0.0) / count, 4),
            "avg_r": round(float(b.get("r_total") or 0.0) / count, 4),
            "avg_dollar_risk": round(float(b.get("dollar_risk_total") or 0.0) / count, 4),
            "avg_position_notional": round(float(b.get("position_notional_total") or 0.0) / count, 4),
            "avg_qty": round(float(b.get("qty_total") or 0.0) / count, 4),
            "avg_risk_per_share": round(float(b.get("risk_per_share_total") or 0.0) / count, 4),
            "avg_holding_hours": round(float(b.get("holding_hours_total") or 0.0) / count, 4),
            "largest_win": round(float(b.get("largest_win") or 0.0), 4),
            "largest_loss": round(float(b.get("largest_loss") or 0.0), 4),
            "best_r": round(float(b.get("best_r") or 0.0), 4),
            "worst_r": round(float(b.get("worst_r") or 0.0), 4),
        })
    out.sort(key=lambda x: (_safe_float(x.get("gross_pnl"), 0.0), _safe_float(x.get("avg_r"), 0.0)), reverse=True)
    return out[: max(1, int(limit or 20))]


def _p442_risk_tier(row: dict | None) -> str:
    risk = _p442_trade_dollar_risk(row)
    if risk <= 0:
        return "unknown"
    if risk <= 15:
        return "risk_0_15"
    if risk <= 30:
        return "risk_15_30"
    if risk <= 50:
        return "risk_30_50"
    return "risk_over_50"


def _p442_size_tier(row: dict | None) -> str:
    notional = _p442_trade_notional(row)
    if notional <= 0:
        return "unknown"
    if notional <= 1200:
        return "notional_0_1200"
    if notional <= 2500:
        return "notional_1200_2500"
    if notional <= 5000:
        return "notional_2500_5000"
    return "notional_over_5000"


def _p442_is_breakout_row(row: dict | None) -> bool:
    r = dict(row or {})
    blob = " ".join([
        str(r.get("strategy_name") or ""),
        str(r.get("signal") or ""),
        str(r.get("entry_type") or ""),
    ]).strip().lower()
    return "breakout" in blob


def _p442_broker_reconciled_strategy_attribution_report(limit: int = 20) -> dict:
    preferred = _p245_broker_preferred_closed_rows()
    rows = [
        dict(r or {})
        for r in list(preferred.get("kept_rows") or [])
        if isinstance(r, dict) and _p245_is_broker_reconciled_exit(r)
    ]
    rows.sort(key=_p442_trade_ts_utc, reverse=True)

    breakout_rows = [r for r in rows if _p442_is_breakout_row(r)]
    non_breakout_rows = [r for r in rows if not _p442_is_breakout_row(r)]
    rollup = _p245_performance_rollup(rows)
    breakout_rollup = _p245_performance_rollup(breakout_rows)
    non_breakout_rollup = _p245_performance_rollup(non_breakout_rows)

    breakout_gross = _safe_float(breakout_rollup.get("gross_pnl"), 0.0)
    breakout_avg_r = _safe_float(breakout_rollup.get("avg_r"), 0.0)
    mean_reversion = dict((rollup.get("by_strategy") or {}).get("daily_mean_reversion") or {})

    recommendations = []
    if breakout_rows and (breakout_gross < 0 or breakout_avg_r < 0.05):
        recommendations.append("reduce_or_segment_breakout_before_any_risk_scale")
    if mean_reversion and _safe_float(mean_reversion.get("avg_r"), 0.0) > breakout_avg_r:
        recommendations.append("preserve_mean_reversion_sleeve")
    worst_breakout = sorted(breakout_rows, key=lambda r: _safe_float(r.get("pnl_r"), 0.0))[:5]
    if worst_breakout and _safe_float(worst_breakout[0].get("pnl_r"), 0.0) <= -1.0:
        recommendations.append("audit_breakout_tail_loss_by_exit_reason_and_entry_type")
    if not recommendations:
        recommendations.append("monitor_broker_reconciled_strategy_mix")

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "broker_reconciled_strategy_attribution_report",
        "source": "broker_reconciled_kept_rows_only",
        "behavior_changed": False,
        "p443_breakout_dollar_risk_containment": {
            "enabled": bool(SWING_BREAKOUT_DOLLAR_RISK_CONTAINMENT_ENABLED),
            "max_dollar_risk": float(SWING_BREAKOUT_DOLLAR_RISK_MAX_DOLLARS or 0.0),
            "basis": "patch_442_broker_reconciled_risk_over_50_underperformed",
        },
        "row_counts": {
            "broker_reconciled_rows": len(rows),
            "breakout_rows": len(breakout_rows),
            "non_breakout_rows": len(non_breakout_rows),
            "shadowed_worker_rows_excluded": preferred.get("shadowed_worker_count"),
            "broker_duplicate_rows_excluded": preferred.get("broker_fill_duplicate_count"),
        },
        "rollup": rollup,
        "breakout_rollup": breakout_rollup,
        "non_breakout_rollup": non_breakout_rollup,
        "by_strategy": _p442_bucket_summary(rows, lambda r: r.get("strategy_name") or r.get("signal"), limit=limit),
        "by_entry_type": _p442_bucket_summary(rows, lambda r: r.get("entry_type"), limit=limit),
        "by_exit_reason": _p442_bucket_summary(rows, lambda r: r.get("attributed_exit_reason") or r.get("exit_reason") or r.get("reason"), limit=limit),
        "by_symbol": _p442_bucket_summary(rows, lambda r: r.get("symbol"), limit=limit),
        "breakout_by_entry_type": _p442_bucket_summary(breakout_rows, lambda r: r.get("entry_type"), limit=limit),
        "breakout_by_exit_reason": _p442_bucket_summary(breakout_rows, lambda r: r.get("attributed_exit_reason") or r.get("exit_reason") or r.get("reason"), limit=limit),
        "breakout_by_risk_tier": _p442_bucket_summary(breakout_rows, _p442_risk_tier, limit=limit),
        "breakout_by_size_tier": _p442_bucket_summary(breakout_rows, _p442_size_tier, limit=limit),
        "worst_breakout_trades": [
            {
                "symbol": r.get("symbol"),
                "ts_utc": _p442_trade_ts_utc(r),
                "strategy_name": r.get("strategy_name"),
                "entry_type": r.get("entry_type"),
                "exit_reason": r.get("attributed_exit_reason") or r.get("exit_reason") or r.get("reason"),
                "gross_pnl": r.get("gross_pnl"),
                "pnl_r": r.get("pnl_r"),
                "qty": r.get("qty"),
                "entry_price": r.get("entry_price"),
                "exit_price": r.get("exit_price"),
                "risk_per_share": r.get("risk_per_share"),
                "dollar_risk": round(_p442_trade_dollar_risk(r), 4),
                "position_notional": round(_p442_trade_notional(r), 4),
                "rank_score": r.get("rank_score"),
                "selection_quality_score": r.get("selection_quality_score"),
                "holding_hours": r.get("holding_hours"),
            }
            for r in worst_breakout
        ],
        "best_breakout_trades": [
            {
                "symbol": r.get("symbol"),
                "ts_utc": _p442_trade_ts_utc(r),
                "strategy_name": r.get("strategy_name"),
                "entry_type": r.get("entry_type"),
                "exit_reason": r.get("attributed_exit_reason") or r.get("exit_reason") or r.get("reason"),
                "gross_pnl": r.get("gross_pnl"),
                "pnl_r": r.get("pnl_r"),
                "qty": r.get("qty"),
                "entry_price": r.get("entry_price"),
                "exit_price": r.get("exit_price"),
                "risk_per_share": r.get("risk_per_share"),
                "dollar_risk": round(_p442_trade_dollar_risk(r), 4),
                "position_notional": round(_p442_trade_notional(r), 4),
                "rank_score": r.get("rank_score"),
                "selection_quality_score": r.get("selection_quality_score"),
                "holding_hours": r.get("holding_hours"),
            }
            for r in sorted(breakout_rows, key=lambda r: _safe_float(r.get("pnl_r"), 0.0), reverse=True)[:5]
        ],
        "recommended_actions": recommendations,
        "recommended_action": recommendations[0],
    }

def _sync_broker_realized_rows_to_strategy_performance(broker_realized: dict | None) -> dict:
    payload = dict(broker_realized or {})
    if not payload.get("ok"):
        return {"ok": False, "synced": 0, "reason": "broker_realized_unavailable"}
    synced = 0
    skipped = 0
    for raw in list(payload.get("rows") or []):
        row = dict(raw or {})
        if not row.get("calc_ok"):
            skipped += 1
            continue
        sym = str(row.get("symbol") or "").upper()
        inferred = _infer_recovered_plan_attribution(sym, order_id=str(row.get("entry_order_id") or ""))
        strategy = _valid_strategy_identity(inferred.get("strategy_name") or inferred.get("signal")) or BREAKOUT_STRATEGY_NAME
        signal = _valid_strategy_identity(inferred.get("signal") or inferred.get("strategy_name")) or strategy
        entry_px = _safe_float(row.get("entry_price"), 0.0)
        exit_px = _safe_float(row.get("exit_price"), 0.0)
        qty = abs(_safe_float(row.get("qty"), 0.0))
        pnl = _safe_float(row.get("gross_pnl"), 0.0)
        if not sym or entry_px <= 0 or exit_px <= 0 or qty <= 0:
            skipped += 1
            continue
        trade_row = {
            "ts_utc": str(row.get("ts_utc") or datetime.now(timezone.utc).isoformat()),
            "symbol": sym,
            "strategy_name": strategy,
            "signal": signal,
            "entry_price": round(entry_px, 4),
            "exit_price": round(exit_px, 4),
            "qty": round(qty, 4),
            "gross_pnl": round(pnl, 4),
            "pnl_r": 0.0,
            "return_pct": round(((exit_px - entry_px) / entry_px * 100.0) if entry_px > 0 else 0.0, 4),
            "reason": "broker_exit_fill",
            "exit_reason": "broker_exit_fill",
            "broker_accounting_reason": "broker_exit_fill",
            "source": "alpaca_orders_reconciled",
            "entry_order_id": str(row.get("entry_order_id") or ""),
            "exit_order_id": str(row.get("exit_order_id") or ""),
            "broker_reconciled": True,
            "attribution_source": inferred.get("attribution_source") or "broker_realized_sync",
        }
        trade_row = _p441_broker_reconciled_r_backfill(trade_row, attribution=inferred)
        if trade_row.get("exit_order_id"):
            trade_row["close_fingerprint"] = f"broker_exit:{trade_row['exit_order_id']}"
        appended = _append_strategy_closed_trade_row(trade_row, reason="broker_realized_sync")
        if appended:
            synced += 1
        else:
            skipped += 1
    return {"ok": True, "synced": synced, "skipped": skipped, "duplicate_exit_audit": _p244_duplicate_realized_exit_audit()}


def _strategy_kill_switch_active(strategy_name: str) -> tuple[bool, list[str]]:
    strategy = str(strategy_name or "").strip().lower(); state = dict((STRATEGY_PERFORMANCE_STATE or {}).get("kill_switch") or {}).get(strategy) or {}; return bool(state.get("active")), list(state.get("reasons") or [])


def _strategy_perf_summary(strategy_name: str) -> dict:
    strategy = str(strategy_name or "").strip().lower(); return dict((STRATEGY_PERFORMANCE_STATE or {}).get("by_strategy") or {}).get(strategy) or {}

def _paper_lifecycle_counts() -> dict:
    events = list(PAPER_LIFECYCLE_HISTORY or [])
    if LAST_PAPER_LIFECYCLE and (not events or events[-1] != LAST_PAPER_LIFECYCLE):
        events.append(dict(LAST_PAPER_LIFECYCLE))
    counts = {
        "scan_completed": 0,
        "candidate_selected": 0,
        "entry_events": 0,
        "exit_events": 0,
    }
    for ev in events:
        stage = str((ev or {}).get("stage") or "").strip().lower()
        status = str((ev or {}).get("status") or "").strip().lower()
        if stage == "scan" and status == "completed":
            counts["scan_completed"] += 1
        if stage == "candidate" and status == "selected":
            counts["candidate_selected"] += 1
        if stage == "entry" and status in {"planned", "submitted", "filled", "opened"}:
            counts["entry_events"] += 1
        if stage == "exit" and status in {"armed", "submitted", "closed", "filled", "completed", "dry_run"}:
            counts["exit_events"] += 1
    synthetic_exit_symbols = []
    for symbol, plan in list((TRADE_PLAN or {}).items()):
        if not isinstance(plan, dict) or not plan.get("active"):
            continue
        try:
            qty_signed, _ = get_position(symbol)
        except Exception:
            qty_signed = 0.0
        if abs(float(qty_signed or 0.0)) <= 0:
            continue
        if plan.get("stop_price") is None and plan.get("take_price") is None:
            continue
        has_exit_event = False
        for ev in reversed(events):
            if str((ev or {}).get("symbol") or "").strip().upper() != str(symbol or "").strip().upper():
                continue
            if str((ev or {}).get("stage") or "").strip().lower() != "exit":
                continue
            if str((ev or {}).get("status") or "").strip().lower() in {"armed", "submitted", "closed", "filled", "completed", "dry_run"}:
                has_exit_event = True
                break
        if not has_exit_event:
            synthetic_exit_symbols.append(str(symbol).strip().upper())
    counts["synthetic_exit_events"] = len(synthetic_exit_symbols)
    counts["synthetic_exit_symbols"] = synthetic_exit_symbols
    counts["exit_events"] += len(synthetic_exit_symbols)
    counts["history_count"] = len(events)
    return counts


def _ts_parse_or_none(value) -> datetime | None:
    s = str(value or "").strip()
    if not s:
        return None
    try:
        s = s.replace("Z", "+00:00")
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    except Exception:
        return None


def _plan_exit_snapshot(symbol: str, plan: dict) -> dict:
    now_dt = now_ny()
    opened_dt = _ts_parse_or_none(plan.get("opened_at"))
    max_hold_days = int(plan.get("max_hold_days") or SWING_MAX_HOLD_DAYS or 0)
    hold_deadline = (opened_dt + timedelta(days=max_hold_days)).isoformat() if opened_dt and max_hold_days > 0 else None
    age_days = None
    if opened_dt:
        try:
            age_days = round(max(0.0, (now_dt - opened_dt).total_seconds()) / 86400.0, 4)
        except Exception:
            age_days = None
    next_trigger = []
    if plan.get("active"):
        next_trigger = [
            {"type": "stop", "price": plan.get("stop_price")},
            {"type": "target", "price": plan.get("take_price")},
        ]
        if hold_deadline:
            next_trigger.append({"type": "max_hold", "deadline": hold_deadline})
    return {
        "signal": plan.get("signal"),
        "strategy_name": plan.get("strategy_name"),
        "opened_at": plan.get("opened_at"),
        "age_days": age_days,
        "max_hold_days": max_hold_days,
        "max_hold_deadline": hold_deadline,
        "entry_price": plan.get("entry_price"),
        "avg_fill_price": plan.get("avg_fill_price"),
        "requested_qty": plan.get("requested_qty"),
        "submitted_qty": plan.get("submitted_qty"),
        "filled_qty": plan.get("filled_qty"),
        "stop_price": plan.get("stop_price"),
        "take_price": plan.get("take_price"),
        "initial_stop_price": plan.get("initial_stop_price"),
        "initial_take_price": plan.get("initial_take_price"),
        "last_exit_attempt_ts": plan.get("last_exit_attempt_ts"),
        "actual_risk_dollars": plan.get("actual_risk_dollars"),
        "risk_per_share": plan.get("risk_per_share"),
        "order_id": plan.get("order_id"),
        "order_status": plan.get("order_status"),
        "source": plan.get("source"),
        "active": bool(plan.get("active")),
        "next_exit_triggers": next_trigger,
    }


def _symbol_lifecycle_proof(symbol: str, active_scan: dict | None = None) -> dict:
    sym = str(symbol or "").strip().upper()
    if not sym:
        return {}
    active_scan = dict(active_scan or {})
    summary = dict(active_scan.get("summary") or {})
    candidates = [dict(r) for r in (summary.get("top_candidates") or []) if isinstance(r, dict)]
    candidate = next((dict(r) for r in candidates if str(r.get("symbol") or "").strip().upper() == sym), {})
    plan = dict((TRADE_PLAN or {}).get(sym) or {})
    if not plan and str(active_scan.get('_scan_source') or '') == 'current_runtime_preview':
        preview_plans = dict(active_scan.get('preview_plans') or summary.get('preview_plans') or {})
        plan = dict(preview_plans.get(sym) or {})
    broker_order = None
    order_id = str(plan.get("order_id") or "").strip()
    if order_id:
        try:
            broker_order = get_order_status(order_id)
        except Exception:
            broker_order = None
    qty_signed, pos_side = get_position(sym)
    exec_state = _derive_execution_lifecycle_state(sym, plan or None, broker_order=broker_order, broker_position_qty=qty_signed)
    lifecycle_events = [dict(ev) for ev in (PAPER_LIFECYCLE_HISTORY or []) if str((ev or {}).get("symbol") or "").strip().upper() == sym]
    if LAST_PAPER_LIFECYCLE and str((LAST_PAPER_LIFECYCLE or {}).get("symbol") or "").strip().upper() == sym:
        if not lifecycle_events or lifecycle_events[-1] != LAST_PAPER_LIFECYCLE:
            lifecycle_events.append(dict(LAST_PAPER_LIFECYCLE))
    lifecycle_events = lifecycle_events[-20:]
    decisions = [dict(row) for row in (DECISIONS or []) if str((row or {}).get("symbol") or "").strip().upper() == sym]
    decisions = decisions[-25:]
    selected = sym in [str(s).strip().upper() for s in (summary.get("selected_symbols") or []) if str(s).strip()]
    selection_blockers = list((candidate.get("selection_blockers") or [])) if candidate else []
    entry_events = [ev for ev in lifecycle_events if str(ev.get("stage") or "").lower() == "entry"]
    exit_events = [ev for ev in lifecycle_events if str(ev.get("stage") or "").lower() == "exit"]
    plan_exit = _plan_exit_snapshot(sym, plan) if plan else {}
    fill_event = next((ev for ev in reversed(entry_events) if str(ev.get("status") or "").lower() in {"filled", "opened"}), None)
    exit_event = next((ev for ev in reversed(exit_events) if str(ev.get("status") or "").lower() in {"armed", "submitted", "closed", "filled", "completed", "dry_run"}), None)
    latest_decision = decisions[-1] if decisions else {}
    if not fill_event and abs(float(qty_signed or 0.0)) > 0:
        fill_event = {
            "ts_utc": datetime.now(timezone.utc).isoformat(),
            "ts_ny": now_ny().isoformat(),
            "stage": "entry",
            "status": "opened",
            "symbol": sym,
            "details": {"synthetic": True, "source": "broker_position", "qty": abs(float(qty_signed or 0.0))},
        }
    if not exit_event and bool(plan and plan.get("active")) and abs(float(qty_signed or 0.0)) > 0 and (plan.get("stop_price") is not None or plan.get("take_price") is not None):
        exit_event = {
            "ts_utc": datetime.now(timezone.utc).isoformat(),
            "ts_ny": now_ny().isoformat(),
            "stage": "exit",
            "status": "armed",
            "symbol": sym,
            "details": {
                "synthetic": True,
                "source": "active_plan",
                "stop_price": plan.get("stop_price"),
                "take_price": plan.get("take_price"),
                "qty": abs(float(qty_signed or 0.0)),
            },
        }
    stage = "candidate"
    if candidate and candidate.get("eligible"):
        stage = "eligible"
    if selected:
        stage = "selected"
    if plan:
        stage = "planned"
    if str(exec_state.get("state") or "") in {"submitted", "partially_filled", "filled", "open", "close_submitted", "closed"}:
        stage = str(exec_state.get("state") or stage)
    if exit_event:
        stage = f"exit_{str(exit_event.get('status') or '').lower()}"
    fill_is_current = bool(fill_event) and _proof_row_is_active_or_recent({
        "active_position": bool(abs(float(qty_signed or 0.0)) > 0),
        "plan_created": bool(plan),
        "order_submitted": bool(order_id),
        "exit_armed": bool(plan and plan.get("active")),
        "entry_event": dict(fill_event or {}),
        "exit_event": dict(exit_event or {}),
        "latest_decision": latest_decision,
        "lifecycle_events": lifecycle_events,
        "decisions": decisions,
    })
    proof = {
        "symbol": sym,
        "candidate_present": bool(candidate),
        "candidate_rank_score": candidate.get("rank_score"),
        "candidate_rejection_reasons": list(candidate.get("rejection_reasons") or []),
        "selection_blockers": selection_blockers,
        "eligible": bool(candidate.get("eligible")) if candidate else False,
        "selected": bool(selected),
        "plan_created": bool(plan),
        "order_submitted": bool(order_id),
        "fill_observed": bool(fill_event),
        "current_fill_observed": bool(fill_event) and bool(fill_is_current),
        "historical_fill_observed": bool(fill_event) and not bool(fill_is_current),
        "active_position": bool(abs(float(qty_signed or 0.0)) > 0),
        "position_qty": round(float(qty_signed or 0.0), 6),
        "position_side": pos_side,
        "exit_armed": bool(plan and plan.get("active")),
        "current_stage": stage,
        "latest_decision": latest_decision,
        "entry_event": dict(fill_event or {}),
        "exit_event": dict(exit_event or {}),
        "execution_lifecycle": {
            "state": exec_state.get("state"),
            "order_status": exec_state.get("order_status"),
            "position_qty": exec_state.get("position_qty"),
            "issues": list(exec_state.get("issues") or []),
        },
        "exit_snapshot": plan_exit,
        "lifecycle_events": lifecycle_events,
        "decisions": decisions,
    }
    return proof


def _proof_row_is_active_or_recent(row: dict, lookback_days: int = 5) -> bool:
    if not isinstance(row, dict):
        return False
    if row.get("active_position") or row.get("plan_created") or row.get("order_submitted") or row.get("exit_armed"):
        return True
    cutoff = datetime.now(timezone.utc) - timedelta(days=max(1, int(lookback_days or 5)))
    candidates = []
    for ev in (row.get("entry_event"), row.get("exit_event"), row.get("latest_decision")):
        if isinstance(ev, dict):
            candidates.append(ev)
    candidates.extend([ev for ev in (row.get("lifecycle_events") or []) if isinstance(ev, dict)])
    candidates.extend([ev for ev in (row.get("decisions") or []) if isinstance(ev, dict)])
    for ev in candidates:
        ts = _parse_bar_ts(ev.get("ts_utc"))
        if ts is None:
            dt_ny = _coerce_dt_ny(ev.get("ts_ny"))
            if dt_ny is not None:
                ts = dt_ny.astimezone(timezone.utc)
        if ts is not None and ts >= cutoff:
            return True
    return False


def _proof_row_fill_flags(row: dict, recency_days: int = 5) -> dict:
    if not isinstance(row, dict):
        return {"fill_observed": False, "historical_fill_observed": False}
    any_fill = bool(row.get("fill_observed"))
    if not any_fill:
        return {"fill_observed": False, "historical_fill_observed": False}
    current_fill = bool(row.get("active_position") or row.get("plan_created") or row.get("order_submitted") or row.get("exit_armed") or _proof_row_is_active_or_recent(row, lookback_days=recency_days))
    return {
        "fill_observed": bool(current_fill),
        "historical_fill_observed": bool(any_fill and not current_fill),
    }


def _pipeline_guardrail_rows(rows: list[dict], truth_source: str | None = None) -> list[dict]:
    preview_only = str(truth_source or "") == "current_runtime_preview"
    now_ts = datetime.now(timezone.utc).isoformat()
    out = []
    for row in rows:
        sym = str(row.get("symbol") or "").strip().upper()
        fill_flags = _proof_row_fill_flags(row)
        issues = []
        if row.get("selected") and not row.get("plan_created"):
            issues.append({
                "code": "selected_preview_only" if preview_only else "selected_without_plan",
                "severity": "info" if preview_only else "error",
            })
        if row.get("plan_created") and not row.get("order_submitted"):
            issues.append({
                "code": "plan_waiting_for_order" if is_paper_execution_permitted("worker_scan") else "plan_without_order",
                "severity": "warn" if is_paper_execution_permitted("worker_scan") else "info",
            })
        if fill_flags.get("fill_observed") and not row.get("exit_armed") and not row.get("exit_event"):
            issues.append({"code": "fill_without_exit_arm", "severity": "warn"})
        if any(str((d or {}).get("action") or "") == "recovered_plan" for d in (row.get("decisions") or [])) and _proof_row_is_active_or_recent(row):
            issues.append({"code": "reconcile_recovered", "severity": "warn"})
        out.append({
            "symbol": sym,
            "ts_utc": now_ts,
            "current_stage": str(row.get("current_stage") or ""),
            "selected": bool(row.get("selected")),
            "plan_created": bool(row.get("plan_created")),
            "order_submitted": bool(row.get("order_submitted")),
            "fill_observed": bool(fill_flags.get("fill_observed")),
            "historical_fill_observed": bool(fill_flags.get("historical_fill_observed")),
            "exit_armed": bool(row.get("exit_armed")),
            "issues": issues,
        })
    return out


def _pipeline_guardrail_snapshot(limit: int = 20) -> dict:
    proof = _paper_execution_proof_snapshot(limit=limit)
    truth_source = str(proof.get("truth_source") or "")
    rows = _pipeline_guardrail_rows(list(proof.get("rows") or []), truth_source=truth_source)
    violations = [r for r in rows if r.get("issues")]
    lim = max(1, min(int(limit or 20), 100))
    return {
        "ok": True,
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "truth_source": truth_source,
        "preview_only": truth_source == "current_runtime_preview",
        "paper_execution_enabled": PAPER_EXECUTION_ENABLED,
        "paper_execution_permitted": bool(is_paper_execution_permitted("worker_scan")),
        "effective_entry_dry_run": bool(effective_entry_dry_run("worker_scan")),
        "selected_symbols": list(proof.get("selected_symbols") or []),
        "planned_symbols": list(proof.get("planned_symbols") or []),
        "submitted_symbols": list(proof.get("submitted_symbols") or []),
        "filled_symbols": list(proof.get("filled_symbols") or []),
        "historical_filled_symbols": list(proof.get("historical_filled_symbols") or []),
        "violation_count": len(violations),
        "violations": violations[:lim],
        "rows": rows[:lim],
    }


def _paper_execution_stage_failures(rows: list[dict], truth_source: str | None = None) -> list[dict]:
    buckets = {
        "selected_but_no_plan": [],
        "plan_without_order": [],
        "order_without_fill": [],
        "fill_without_exit_arm": [],
        "reconcile_recovered": [],
    }
    for row in rows:
        row = row if isinstance(row, dict) else {}
        sym = row.get("symbol")
        fill_flags = _proof_row_fill_flags(row)
        if row.get("selected") and not row.get("plan_created") and str(truth_source or "") != "current_runtime_preview":
            buckets["selected_but_no_plan"].append(sym)
        if row.get("plan_created") and not row.get("order_submitted"):
            buckets["plan_without_order"].append(sym)
        if row.get("order_submitted") and not bool(fill_flags.get("fill_observed")):
            buckets["order_without_fill"].append(sym)
        if bool(fill_flags.get("fill_observed")) and not row.get("exit_armed") and not row.get("exit_event"):
            buckets["fill_without_exit_arm"].append(sym)
        if any(str((d or {}).get("action") or "") == "recovered_plan" for d in (row.get("decisions") or [])) and _proof_row_is_active_or_recent(row):
            buckets["reconcile_recovered"].append(sym)
    out = []
    for code, syms in buckets.items():
        out.append({"code": code, "count": len(syms), "symbols": syms})
    return out


def _paper_execution_proof_snapshot(limit: int = 20) -> dict:
    lim = max(1, min(int(limit or 20), 50))
    active_scan = _active_truth_scan(limit=max(10, lim * 2))
    summary = dict((active_scan or {}).get("summary") or {})
    runtime_symbols = _dedupe_keep_order([str(s).strip().upper() for s in (summary.get("symbols") or (active_scan or {}).get("symbols") or universe_symbols() or []) if str(s).strip()])
    candidate_symbols = _dedupe_keep_order([str((r or {}).get("symbol") or "").strip().upper() for r in (summary.get("top_candidates") or []) if str((r or {}).get("symbol") or "").strip()])
    plan_symbols = _dedupe_keep_order([str(s).strip().upper() for s, plan in (TRADE_PLAN or {}).items() if isinstance(plan, dict)])
    decision_symbols = _dedupe_keep_order([str((r or {}).get("symbol") or "").strip().upper() for r in list(DECISIONS or [])[-250:] if str((r or {}).get("symbol") or "").strip()])
    lifecycle_symbols = _dedupe_keep_order([str((r or {}).get("symbol") or "").strip().upper() for r in list(PAPER_LIFECYCLE_HISTORY or [])[-250:] if str((r or {}).get("symbol") or "").strip()])
    symbols = _dedupe_keep_order(runtime_symbols + candidate_symbols + plan_symbols + lifecycle_symbols + decision_symbols)
    rows = [_symbol_lifecycle_proof(sym, active_scan=active_scan) for sym in symbols[:max(lim, len(runtime_symbols))]]
    rows = [r for r in rows if r]
    stage_failures = _paper_execution_stage_failures(rows, truth_source=(active_scan or {}).get("_scan_source"))
    selected_symbols = [r.get("symbol") for r in rows if r.get("selected")]
    planned_symbols = [r.get("symbol") for r in rows if r.get("plan_created")]
    submitted_symbols = [r.get("symbol") for r in rows if r.get("order_submitted")]
    filled_symbols = [r.get("symbol") for r in rows if _proof_row_fill_flags(r).get("fill_observed")]
    historical_filled_symbols = [r.get("symbol") for r in rows if _proof_row_fill_flags(r).get("historical_fill_observed")]
    active_position_symbols = [r.get("symbol") for r in rows if r.get("active_position")]
    exit_armed_symbols = [r.get("symbol") for r in rows if r.get("exit_armed") or r.get("exit_event")]
    recent_reconcile_symbols = [r.get("symbol") for r in rows if any(str((d or {}).get("action") or "") == "recovered_plan" for d in (r.get("decisions") or []))]
    return {
        "ok": True,
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "truth_source": (active_scan or {}).get("_scan_source"),
        "scan_ts_utc": (active_scan or {}).get("ts_utc"),
        "runtime_symbols": runtime_symbols,
        "candidate_symbols": candidate_symbols,
        "rows": rows[:lim],
        "row_count": min(len(rows), lim),
        "stage_failures": stage_failures,
        "selected_symbols": selected_symbols,
        "planned_symbols": planned_symbols,
        "submitted_symbols": submitted_symbols,
        "filled_symbols": filled_symbols,
        "historical_filled_symbols": historical_filled_symbols,
        "active_position_symbols": active_position_symbols,
        "exit_armed_symbols": exit_armed_symbols,
        "recent_reconcile_symbols": recent_reconcile_symbols,
        "planned_count": len(planned_symbols),
        "submitted_count": len(submitted_symbols),
        "filled_count": len(filled_symbols),
        "exit_armed_count": len(exit_armed_symbols),
    }


def _execution_proof_snapshot(limit: int = 10) -> dict:
    lim = max(1, min(int(limit or 10), 50))
    active_scan = _active_truth_scan(limit=max(10, lim * 2))
    proof = _paper_execution_proof_snapshot(limit=max(10, lim * 2))
    summary = dict((active_scan or {}).get("summary") or {})
    selected_symbols = _dedupe_keep_order([str(s).strip().upper() for s in (summary.get("selected_symbols") or proof.get("selected_symbols") or []) if str(s).strip()])
    proof_rows = {str((r or {}).get("symbol") or "").strip().upper(): dict(r) for r in (proof.get("rows") or []) if isinstance(r, dict) and str((r or {}).get("symbol") or "").strip()}
    focus_symbols = _dedupe_keep_order(
        list(selected_symbols)
        + [str((r or {}).get("symbol") or "").strip().upper() for r in (proof.get("rows") or []) if isinstance(r, dict) and (r.get("plan_created") or r.get("order_submitted") or _proof_row_fill_flags(r).get("fill_observed") or r.get("active_position") or r.get("exit_armed") or r.get("exit_event"))]
    )
    out_rows = []
    for sym in focus_symbols[:lim]:
        row = dict(proof_rows.get(sym) or {})
        decisions = [dict(d) for d in (row.get("decisions") or []) if isinstance(d, dict)]
        lifecycle_events = [dict(ev) for ev in (row.get("lifecycle_events") or []) if isinstance(ev, dict)]
        selected_event = next((d for d in reversed(decisions) if str(d.get("event") or "").upper() == "SCAN" and str(d.get("action") or "") == "candidate_selected"), {})
        plan_event = next((d for d in reversed(decisions) if str(d.get("event") or "").upper() == "ENTRY" and str(d.get("action") or "") in {"dry_run_plan_created", "order_submitted"}), {})
        order_event = next((d for d in reversed(decisions) if str(d.get("event") or "").upper() == "ENTRY" and str(d.get("action") or "") == "order_submitted"), {})
        fill_event = dict(row.get("entry_event") or {})
        exit_event = dict(row.get("exit_event") or {})
        submit_decision = _latest_scan_submit_decision(decisions)
        out_rows.append({
            "symbol": sym,
            "selected": bool(row.get("selected")),
            "plan_created": bool(row.get("plan_created")),
            "order_submitted": bool(row.get("order_submitted")),
            "fill_observed": bool(row.get("fill_observed")),
            "exit_armed": bool(row.get("exit_armed")),
            "current_stage": row.get("current_stage"),
            "preview_only": bool((active_scan or {}).get("_scan_source") == "current_runtime_preview" and str(((row.get("latest_decision") or {}).get("action") or "")) != "order_submitted"),
            "selected_event": selected_event,
            "plan_event": plan_event,
            "order_event": order_event,
            "fill_event": fill_event,
            "exit_event": exit_event,
            "submit_decision": submit_decision,
            "submit_state": str(submit_decision.get("action") or "").replace("paper_submit_", "") if submit_decision else ("submitted" if bool(row.get("order_submitted")) else ""),
            "submit_reason": str(submit_decision.get("reason") or "") if submit_decision else "",
            "submit_attempted": bool(submit_decision.get("attempted")) if submit_decision else bool(row.get("order_submitted")),
            "decision_count": len(decisions),
            "lifecycle_event_count": len(lifecycle_events),
            "issues": list(next((g.get("issues") for g in (_pipeline_guardrail_rows([row], truth_source=(proof.get("truth_source") or "")) or []) if isinstance(g, dict)), []) or []),
        })
    return {
        "ok": True,
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "truth_source": proof.get("truth_source"),
        "runtime_symbols": list((proof.get("runtime_symbols") or [])),
        "selected_symbols": selected_symbols,
        "focus_symbols": focus_symbols,
        "selected_count": len(selected_symbols),
        "planned_count": sum(1 for r in out_rows if r.get("plan_created")),
        "submitted_count": sum(1 for r in out_rows if r.get("order_submitted")),
        "filled_count": sum(1 for r in out_rows if r.get("fill_observed")),
        "exit_armed_count": sum(1 for r in out_rows if r.get("exit_armed")),
        "items": out_rows,
    }


def _execution_visibility_snapshot(limit: int = 10) -> dict:
    lim = max(1, min(int(limit or 10), 100))
    proof = _execution_proof_snapshot(limit=max(10, lim))
    lifecycle = execution_lifecycle_snapshot(limit=max(10, lim * 2))
    lifecycle_rows = {
        str((row or {}).get("symbol") or "").strip().upper(): dict(row)
        for row in (lifecycle.get("items") or [])
        if isinstance(row, dict) and str((row or {}).get("symbol") or "").strip()
    }
    out_items = []
    for row in (proof.get("items") or [])[:lim]:
        if not isinstance(row, dict):
            continue
        sym = str(row.get("symbol") or "").strip().upper()
        life = dict(lifecycle_rows.get(sym) or {})
        history_tail = list(life.get("history_tail") or [])
        latest_transition = dict(history_tail[-1] or {}) if history_tail else {}
        out_items.append({
            **dict(row),
            "execution_state": life.get("execution_state"),
            "derived_state": life.get("derived_state"),
            "order_status": life.get("order_status"),
            "position_qty": life.get("position_qty"),
            "execution_updated_utc": life.get("execution_updated_utc"),
            "submitted_at": life.get("submitted_at"),
            "latest_transition": latest_transition,
            "execution_issue_count": len(list(life.get("issues") or [])),
            "persisted_issue_count": int(life.get("persisted_issue_count") or 0),
        })
    visible_symbols = [str((row or {}).get("symbol") or "").strip().upper() for row in out_items if str((row or {}).get("symbol") or "").strip()]
    selected_symbols = [s for s in (proof.get("selected_symbols") or []) if s in visible_symbols]
    if not selected_symbols:
        selected_symbols = [s for s in (proof.get("focus_symbols") or []) if s in visible_symbols]
    return {
        "ok": True,
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "truth_source": proof.get("truth_source"),
        "runtime_symbols": list(proof.get("runtime_symbols") or []),
        "selected_symbols": selected_symbols,
        "selected_count": len(selected_symbols),
        "planned_count": int(proof.get("planned_count") or 0),
        "submitted_count": int(proof.get("submitted_count") or 0),
        "filled_count": int(proof.get("filled_count") or 0),
        "exit_armed_count": int(proof.get("exit_armed_count") or 0),
        "execution_lifecycle_issue_counts": dict(lifecycle.get("issue_counts") or {}),
        "items": out_items,
    }


def _live_readiness_gate_snapshot(limit: int = 10) -> dict:
    release = release_gate_status()
    paper_gate = _paper_proof_gate_snapshot()
    readiness = diagnostics_readiness(Request({"type": "http", "headers": [], "query_string": b"", "method": "GET", "path": "/diagnostics/live_readiness_gate"}))
    proof = _execution_proof_snapshot(limit=max(5, min(int(limit or 10), 25)))
    workflow = dict(release.get("release_workflow") or {})
    promotion_targets = dict(workflow.get("promotion_targets") or {})
    live_target = dict(promotion_targets.get("live_guarded") or {})
    eligible_target = dict(promotion_targets.get("guarded_live_eligible") or {})
    blockers = []
    if not bool(readiness.get("component_ready")):
        blockers.append("component_not_ready")
    if not bool(readiness.get("trade_path_proven")):
        blockers.append("trade_path_not_proven")
    if not bool(readiness.get("same_session_proven")):
        blockers.append("same_session_not_proven")
    if DRY_RUN:
        blockers.append("dry_run_enabled")
    if not LIVE_TRADING_ENABLED:
        blockers.append("live_trading_disabled")
    if not SCANNER_ALLOW_LIVE:
        blockers.append("scanner_live_disabled")
    blockers.extend([str(x) for x in (release.get("unmet_conditions") or []) if str(x)])
    blockers = list(dict.fromkeys(blockers))
    return {
        "ok": True,
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "component_ready": bool(readiness.get("component_ready")),
        "trade_path_proven": bool(readiness.get("trade_path_proven")),
        "same_session_proven": bool(readiness.get("same_session_proven")),
        "go_live_eligible": bool(release.get("go_live_eligible")),
        "live_orders_permitted": bool(release.get("live_orders_permitted")),
        "effective_release_stage": release.get("effective_release_stage"),
        "configured_release_stage": release.get("configured_release_stage"),
        "approval_armed": bool(workflow.get("approval_armed")),
        "live_activation_armed": bool(workflow.get("live_activation_armed")),
        "env": {
            "dry_run": bool(DRY_RUN),
            "live_trading_enabled": bool(LIVE_TRADING_ENABLED),
            "scanner_allow_live": bool(SCANNER_ALLOW_LIVE),
            "release_gate_enforced": bool(RELEASE_GATE_ENFORCED),
        },
        "promotion_targets": {
            "guarded_live_eligible": eligible_target,
            "live_guarded": live_target,
        },
        "proof_counts": {
            "selected_count": int(proof.get("selected_count") or 0),
            "planned_count": int(proof.get("planned_count") or 0),
            "submitted_count": int(proof.get("submitted_count") or 0),
            "filled_count": int(proof.get("filled_count") or 0),
            "exit_armed_count": int(proof.get("exit_armed_count") or 0),
        },
        "proof_symbols": {
            "selected_symbols": list(proof.get("selected_symbols") or []),
        },
        "blockers": blockers,
        "unmet_conditions": list(release.get("unmet_conditions") or []),
        "worker_status": dict(release.get("worker_status") or {}),
        "paper_proof_eligible": bool(paper_gate.get("paper_proof_eligible")),
        "paper_orders_permitted": bool(paper_gate.get("paper_orders_permitted")),
        "paper_proof_unmet_conditions": list(paper_gate.get("paper_proof_unmet_conditions") or []),
    }


def _worker_status_snapshot() -> dict:
    now_utc = datetime.now(tz=timezone.utc)
    scanner_running = False
    scanner_age_sec = None
    scanner_ref_ts = str((LAST_SCANNER_TELEMETRY.get("last_worker_event_utc") or "")).strip()
    scanner_status = "unknown"
    scanner_last_event = (LAST_SCANNER_TELEMETRY.get("last_worker_event") or None)
    scanner_expected_cycle_sec = max(30, SCANNER_INTERVAL_SEC + SCANNER_TIMEOUT_SEC + max(10, SCANNER_JITTER_SEC) + 30)
    scanner_late_after_sec = scanner_expected_cycle_sec
    scanner_stale_after_sec = max(READINESS_SCANNER_MAX_AGE_SEC, scanner_expected_cycle_sec + max(60, SCANNER_TIMEOUT_SEC))
    scanner_down_after_sec = max(scanner_stale_after_sec + max(120, SCANNER_TIMEOUT_SEC), scanner_expected_cycle_sec * 2)
    if scanner_ref_ts:
        try:
            scanner_ts = datetime.fromisoformat(scanner_ref_ts)
            if scanner_ts.tzinfo is None:
                scanner_ts = scanner_ts.replace(tzinfo=timezone.utc)
            scanner_age_sec = max(0.0, (now_utc - scanner_ts.astimezone(timezone.utc)).total_seconds())
            if scanner_age_sec <= scanner_late_after_sec:
                scanner_status = "up"
                scanner_running = True
            elif scanner_age_sec <= scanner_stale_after_sec:
                scanner_status = "late"
                scanner_running = True
            elif scanner_age_sec <= scanner_down_after_sec:
                scanner_status = "stale"
                scanner_running = False
            else:
                scanner_status = "down"
                scanner_running = False
        except Exception:
            scanner_running = False
            scanner_status = "unknown"
    exit_worker_running = False
    exit_age_sec = None
    exit_status = "unknown"
    if LAST_EXIT_HEARTBEAT.get("ts_utc"):
        try:
            exit_ts = datetime.fromisoformat(str(LAST_EXIT_HEARTBEAT.get("ts_utc")))
            if exit_ts.tzinfo is None:
                exit_ts = exit_ts.replace(tzinfo=timezone.utc)
            exit_age_sec = max(0.0, (now_utc - exit_ts.astimezone(timezone.utc)).total_seconds())
            if exit_age_sec <= max(READINESS_EXIT_MAX_AGE_SEC, 15):
                exit_worker_running = True
                exit_status = "up"
            elif exit_age_sec <= max(READINESS_EXIT_MAX_AGE_SEC * 2, 60):
                exit_worker_running = False
                exit_status = "stale"
            else:
                exit_worker_running = False
                exit_status = "down"
        except Exception:
            exit_worker_running = False
            exit_status = "unknown"
    return {
        "scanner_running": scanner_running,
        "scanner_status": scanner_status,
        "scanner_age_sec": scanner_age_sec,
        "scanner_last_event": scanner_last_event,
        "scanner_last_event_utc": LAST_SCANNER_TELEMETRY.get("last_worker_event_utc"),
        "scanner_expected_cycle_sec": scanner_expected_cycle_sec,
        "scanner_late_after_sec": scanner_late_after_sec,
        "scanner_stale_after_sec": scanner_stale_after_sec,
        "scanner_down_after_sec": scanner_down_after_sec,
        "exit_worker_running": exit_worker_running,
        "exit_worker_status": exit_status,
        "exit_worker_age_sec": exit_age_sec,
    }


def _safe_iso_to_dt(value) -> datetime | None:
    s = str(value or '').strip()
    if not s:
        return None
    try:
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return None


def _session_boundary_snapshot() -> dict:
    now_local = now_ny()
    today_ny = now_local.date().isoformat()
    open_local = datetime.combine(now_local.date(), MARKET_OPEN, tzinfo=NY_TZ)
    close_local = datetime.combine(now_local.date(), MARKET_CLOSE, tzinfo=NY_TZ)
    clock = _market_clock_snapshot()
    market_day = bool(clock.get("market_day"))
    market_open_now = bool(clock.get("is_open"))
    market_closed_reason = "" if market_open_now else str(clock.get("reason") or "")
    opening_window_minutes = max(1, int(OPENING_WINDOW_REFRESH_MINUTES or 15))
    opening_window_sec = opening_window_minutes * 60
    seconds_since_open = None
    if market_day and now_local >= open_local:
        seconds_since_open = max(0.0, (now_local - open_local).total_seconds())
    opening_window_active = bool(market_open_now and seconds_since_open is not None and seconds_since_open <= opening_window_sec)
    return {
        "today_ny": today_ny,
        "now_ny": now_local.isoformat(),
        "market_open_ny": open_local.isoformat(),
        "market_close_ny": close_local.isoformat(),
        "market_open_utc": open_local.astimezone(timezone.utc).isoformat(),
        "market_close_utc": close_local.astimezone(timezone.utc).isoformat(),
        "market_day": bool(market_day),
        "market_closed_reason": market_closed_reason,
        "market_open_now": bool(market_open_now),
        "market_clock": clock,
        "seconds_since_open": seconds_since_open,
        "opening_window_active": opening_window_active,
        "opening_window_minutes": opening_window_minutes,
    }


def _regime_snapshot_needs_refresh(session: dict | None = None) -> bool:
    session = dict(session or _session_boundary_snapshot())
    current = dict(LAST_REGIME_SNAPSHOT or {})
    if not current:
        return True
    if current.get("data_complete") is False:
        return True
    ts_raw = current.get("ts_utc")
    dt = _safe_iso_to_dt(ts_raw) if ts_raw else None
    same_session = False
    age_sec = None
    if dt:
        dt_ny = dt.astimezone(NY_TZ)
        same_session = dt_ny.date().isoformat() == str(session.get("today_ny"))
        age_sec = max(0.0, (datetime.now(tz=timezone.utc) - dt.astimezone(timezone.utc)).total_seconds())
    if bool(session.get("market_open_now")) and not same_session:
        return True
    if bool(session.get("opening_window_active")) and age_sec is not None and age_sec > max(60, int(OPENING_WINDOW_REGIME_MAX_AGE_SEC or 600)):
        return True
    return False


def _paper_proof_gate_snapshot() -> dict:
    session = _session_boundary_snapshot()
    worker_status = _worker_status_snapshot()
    freshness = freshness_snapshot()
    freshness_entries = dict(freshness.get("entries") or {})
    same_session_proven = all(bool((freshness_entries.get(name) or {}).get("same_session")) for name in ("last_scan", "regime", "paper_lifecycle", "scanner_telemetry"))

    recent_scan_status = _recent_market_scan_status(RELEASE_MAX_SCAN_AGE_SEC, bool(session.get("market_open_now")))
    last_scan_age_sec = recent_scan_status.get("age_sec")
    recent_market_scan_ok = bool(recent_scan_status.get("ok"))

    broker_connected = True
    broker_error = ""
    try:
        trading_client.get_account()
    except Exception as e:
        broker_connected = False
        broker_error = str(e)

    journal_ok = True
    journal_error = ""
    if JOURNAL_ENABLED:
        try:
            _ensure_parent_dir(JOURNAL_PATH)
            Path(JOURNAL_PATH).parent.mkdir(parents=True, exist_ok=True)
        except Exception as e:
            journal_ok = False
            journal_error = str(e)

    risk_ok = risk_limits_ok()
    halt_active = daily_halt_active()
    component_ready = _compute_system_health_ok(
        scanner_running=bool(worker_status.get("scanner_running")),
        exit_worker_running=bool(worker_status.get("exit_worker_running")),
        broker_connected=broker_connected,
        risk_limits_ok=risk_ok,
        kill_switch=KILL_SWITCH,
        daily_halt_active_flag=halt_active,
        journal_ok=journal_ok,
        require_workers=READINESS_REQUIRE_WORKERS,
    )

    workflow = _release_workflow_snapshot(include_gate=False)
    effective_stage = _normalize_release_stage(workflow.get("effective_stage") or SYSTEM_RELEASE_STAGE, default="paper")

    unmet = []
    if effective_stage != "paper":
        unmet.append("release_stage_not_paper")
    if not bool(session.get("market_open_now")):
        unmet.append("market_closed")
    if READINESS_REQUIRE_WORKERS and not bool(worker_status.get("scanner_running")):
        unmet.append("scanner_worker_not_ready")
    if READINESS_REQUIRE_WORKERS and not bool(worker_status.get("exit_worker_running")):
        unmet.append("exit_worker_not_ready")
    if not component_ready:
        unmet.append("component_not_ready")
    if not same_session_proven:
        unmet.append("same_session_not_proven")
    if RELEASE_REQUIRE_RECENT_MARKET_SCAN and not recent_market_scan_ok:
        unmet.append("recent_market_scan_missing")
    if KILL_SWITCH:
        unmet.append("kill_switch_on")
    if halt_active:
        unmet.append("daily_halt_active")
    if DRY_RUN:
        unmet.append("dry_run_enabled")
    if not bool(PAPER_EXECUTION_ENABLED):
        unmet.append("paper_execution_disabled")
    if not bool(SCANNER_ALLOW_LIVE):
        unmet.append("scanner_live_disabled")
    unmet = list(dict.fromkeys(str(x) for x in unmet if x))

    return {
        "ok": True,
        "paper_release_stage": effective_stage == "paper",
        "paper_proof_eligible": len(unmet) == 0,
        "paper_orders_permitted": len(unmet) == 0,
        "paper_proof_unmet_conditions": unmet,
        "effective_release_stage": effective_stage,
        "recent_market_scan_ok": recent_market_scan_ok,
        "last_scan_age_sec": last_scan_age_sec,
        "recent_market_scan_source": recent_scan_status.get("source"),
        "recent_market_scan_reason": recent_scan_status.get("reason"),
        "component_ready": component_ready,
        "same_session_proven": same_session_proven,
        "worker_status": worker_status,
        "session": session,
        "broker_connected": broker_connected,
        "broker_error": broker_error,
        "journal_ok": journal_ok,
        "journal_error": journal_error,
        "risk_limits_ok": risk_ok,
        "env": {
            "dry_run": bool(DRY_RUN),
            "paper_execution_enabled": bool(PAPER_EXECUTION_ENABLED),
            "scanner_allow_live": bool(SCANNER_ALLOW_LIVE),
            "live_trading_enabled": bool(LIVE_TRADING_ENABLED),
        },
    }


def _proof_capture_plan_snapshot(limit: int = 10) -> dict:
    lim = max(1, min(int(limit or 10), 25))
    preview = _current_runtime_preview_snapshot(limit=max(5, lim))
    visibility = _execution_visibility_snapshot(limit=max(5, lim))
    live_gate = _live_readiness_gate_snapshot(limit=max(5, lim))
    paper_gate = _paper_proof_gate_snapshot()
    readiness = diagnostics_readiness(Request({"type": "http", "headers": [], "query_string": b"", "method": "GET", "path": "/diagnostics/proof_capture_plan"}))
    worker_status = dict((paper_gate.get("worker_status") or live_gate.get("worker_status") or {}))
    truth_source = str(visibility.get("truth_source") or preview.get("preview_source") or "")
    current_runtime = list(preview.get("runtime_symbols") or [])
    matched_scan = _latest_matching_scan_record(current_runtime)
    matched_scan_source = str((matched_scan or {}).get('_scan_source') or '')
    matched_would_submit = list((matched_scan or {}).get("would_submit") or [])
    if truth_source == "current_runtime_preview" and matched_scan_source == "candidate_history_match":
        matched_would_submit = []
    submit_decisions = {}
    for row in matched_would_submit:
        symbol = str((row or {}).get("symbol") or "").strip().upper()
        if not symbol or symbol in submit_decisions:
            continue
        state = str((row or {}).get("submit_state") or "").strip().lower()
        reason = str((row or {}).get("submit_reason") or (row or {}).get("reason") or "")
        attempted = bool((row or {}).get("submit_attempted"))
        rejected = bool((row or {}).get("rejected"))
        submit_decisions[symbol] = {
            "submit_state": state or None,
            "submit_reason": reason,
            "submit_attempted": attempted,
            "submit_ok": (row or {}).get("ok"),
            "submit_rejected": rejected,
            "submit_preview_only": (not attempted) and (rejected or state in {"blocked", "preview_only", "not_submitted"}),
        }

    def _next_step(row: dict) -> str:
        current_stage = str((row or {}).get("current_stage") or "").strip().lower()
        selected = bool((row or {}).get("selected"))
        plan_created = bool((row or {}).get("plan_created"))
        order_submitted = bool((row or {}).get("order_submitted"))
        fill_observed = bool((row or {}).get("fill_observed"))
        exit_armed = bool((row or {}).get("exit_armed"))
        preview_only = bool((row or {}).get("preview_only"))
        if exit_armed:
            return "observe_exit_fill_or_close"
        if fill_observed or current_stage in {"filled", "open", "opened", "exit_armed", "close_submitted"}:
            return "arm_or_submit_exit"
        submit_state = str((row or {}).get("submit_state") or "").strip().lower()
        submit_reason = str((row or {}).get("submit_reason") or "").strip().lower()
        if order_submitted or current_stage in {"submitted", "entry_submitted"}:
            return "observe_entry_fill"
        if submit_state == "blocked":
            if submit_reason in {"spread_too_wide", "quote_missing", "quote_stale", "fresh_quote_required"}:
                return "wait_for_submitable_quote"
            return "resolve_submit_blocker"
        if submit_state == "ignored":
            return "clear_submit_blocker_or_wait_next_scan"
        if plan_created or current_stage in {"planned", "selected"}:
            if preview_only and bool((paper_gate.get("env") or {}).get("dry_run", DRY_RUN)):
                return "disable_dry_run_and_submit_in_paper_session"
            if preview_only and truth_source == "current_runtime_preview":
                return "await_next_scanner_submission_window"
            return "submit_entry_order"
        if selected:
            return "create_trade_plan"
        return "wait_for_selection"

    def _status_label(row: dict) -> str:
        if bool((row or {}).get("exit_armed")):
            return "exit_armed"
        if bool((row or {}).get("fill_observed")):
            return "filled"
        if bool((row or {}).get("order_submitted")):
            return "submitted"
        if bool((row or {}).get("plan_created")):
            return "planned"
        if bool((row or {}).get("selected")):
            return "selected"
        return "watching"

    items = []
    for row in list(visibility.get("items") or [])[:lim]:
        symbol = str((row or {}).get("symbol") or "").upper()
        if not symbol:
            continue
        submit_meta = dict(submit_decisions.get(symbol) or {})
        effective_row = dict(row or {})
        if not effective_row.get("submit_state") and submit_meta.get("submit_state") is not None:
            effective_row["submit_state"] = submit_meta.get("submit_state")
        if not effective_row.get("submit_reason") and submit_meta.get("submit_reason"):
            effective_row["submit_reason"] = submit_meta.get("submit_reason")
        if not bool(effective_row.get("submit_attempted")) and submit_meta:
            effective_row["submit_attempted"] = bool(submit_meta.get("submit_attempted"))
        if submit_meta.get("submit_preview_only"):
            effective_row["preview_only"] = True
        row_preview_only = bool((effective_row or {}).get("preview_only"))
        if truth_source == "current_runtime_preview" and not submit_meta.get("submit_preview_only") and not bool((effective_row or {}).get("order_submitted")):
            row_preview_only = False
        effective_row["preview_only"] = row_preview_only
        items.append({
            "symbol": symbol,
            "status": _status_label(effective_row),
            "next_step": _next_step(effective_row),
            "selected": bool((effective_row or {}).get("selected")),
            "plan_created": bool((effective_row or {}).get("plan_created")),
            "order_submitted": bool((effective_row or {}).get("order_submitted")),
            "fill_observed": bool((effective_row or {}).get("fill_observed")),
            "exit_armed": bool((effective_row or {}).get("exit_armed")),
            "preview_only": bool(row_preview_only),
            "submit_state": (effective_row or {}).get("submit_state"),
            "submit_reason": (effective_row or {}).get("submit_reason"),
            "submit_attempted": bool((effective_row or {}).get("submit_attempted")),
            "issues": list((effective_row or {}).get("issues") or []),
            "execution_state": (effective_row or {}).get("execution_state"),
            "derived_state": (effective_row or {}).get("derived_state"),
        })

    selected_symbols = list(visibility.get("selected_symbols") or preview.get("selected_symbols") or [])
    if not selected_symbols and items:
        selected_symbols = [str((row or {}).get("symbol") or "").strip().upper() for row in items if str((row or {}).get("symbol") or "").strip()]
    top_candidates = []
    selected_set = {str(s).upper() for s in selected_symbols if str(s).strip()}
    for row in list(preview.get("top_candidates") or [])[: max(lim, 10)]:
        symbol = str((row or {}).get("symbol") or "").upper()
        if not symbol or symbol in selected_set:
            continue
        top_candidates.append({
            "symbol": symbol,
            "eligible": bool((row or {}).get("eligible")),
            "rejection_reasons": list((row or {}).get("rejection_reasons") or []),
            "selection_blockers": list((row or {}).get("selection_blockers") or []),
            "rank_score": (row or {}).get("rank_score"),
        })
        if len(top_candidates) >= lim:
            break

    env_requirements = {
        "market_open": bool((paper_gate.get("session") or {}).get("market_open_now", (readiness or {}).get("market_open"))),
        "scanner_running": bool(worker_status.get("scanner_running")),
        "exit_worker_running": bool(worker_status.get("exit_worker_running")),
        "release_stage_paper": bool(paper_gate.get("paper_release_stage")),
        "dry_run_disabled": not bool((paper_gate.get("env") or {}).get("dry_run")),
        "paper_execution_enabled": bool((paper_gate.get("env") or {}).get("paper_execution_enabled")),
        "scanner_live_enabled": bool((paper_gate.get("env") or {}).get("scanner_allow_live")),
        "component_ready": bool(paper_gate.get("component_ready")),
        "same_session_proven": bool(paper_gate.get("same_session_proven")),
        "recent_market_scan_ok": bool(paper_gate.get("recent_market_scan_ok")),
    }
    proof_capture_possible_now = bool(paper_gate.get("paper_orders_permitted"))
    arming_gaps = [name for name, ok in env_requirements.items() if not bool(ok)]
    plan_blockers = list(dict.fromkeys([str(x) for x in (paper_gate.get("paper_proof_unmet_conditions") or []) if str(x)]))

    return {
        "ok": True,
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "truth_source": truth_source,
        "proof_capture_possible_now": proof_capture_possible_now,
        "arming_gaps": arming_gaps,
        "env_requirements": env_requirements,
        "component_ready": bool(paper_gate.get("component_ready")),
        "trade_path_proven": bool(live_gate.get("trade_path_proven")),
        "same_session_proven": bool(paper_gate.get("same_session_proven")),
        "go_live_eligible": bool(live_gate.get("go_live_eligible")),
        "paper_proof_eligible": bool(paper_gate.get("paper_proof_eligible")),
        "paper_orders_permitted": bool(paper_gate.get("paper_orders_permitted")),
        "blockers": plan_blockers,
        "runtime_symbols": list(preview.get("runtime_symbols") or []),
        "selected_symbols": selected_symbols,
        "selected_count": int(visibility.get("selected_count") or 0),
        "proof_counts": {
            "planned_count": int(visibility.get("planned_count") or 0),
            "submitted_count": int(visibility.get("submitted_count") or 0),
            "filled_count": int(visibility.get("filled_count") or 0),
            "exit_armed_count": int(visibility.get("exit_armed_count") or 0),
        },
        "items": items,
        "submit_truth_source": matched_scan_source or None,
        "top_runtime_candidates": top_candidates,
        "operator_focus": items[0] if items else {},
    }

def _freshness_entry(name: str, ts_value, *, source: str = "", max_age_sec: float | None = None, require_same_session: bool = False, extra: dict | None = None) -> dict:
    now_utc = datetime.now(tz=timezone.utc)
    session = _session_boundary_snapshot()
    dt = _safe_iso_to_dt(ts_value)
    row = {
        "name": name,
        "ts_utc": dt.isoformat() if dt else None,
        "age_sec": None,
        "source": source or "",
        "same_session": None,
        "fresh": False,
        "status": "missing",
    }
    if dt:
        age_sec = max(0.0, (now_utc - dt).total_seconds())
        dt_ny = dt.astimezone(NY_TZ)
        same_session = (dt_ny.date().isoformat() == session["today_ny"])
        fresh = True
        if max_age_sec is not None:
            fresh = fresh and (age_sec <= max_age_sec)
        if require_same_session:
            fresh = fresh and same_session
        row.update({
            "ts_ny": dt_ny.isoformat(),
            "age_sec": age_sec,
            "same_session": same_session,
            "fresh": bool(fresh),
            "status": "fresh" if fresh else "stale",
        })
    if extra:
        row.update(extra)
    return row



def _normalize_release_stage(stage: object, default: str = "paper") -> str:
    stage_s = str(stage or "").strip().lower()
    aliases = {
        "eligible": "guarded_live_eligible",
        "guarded": "live_guarded",
        "prod": "live",
        "production": "live",
        "disabled": "emergency_disabled",
        "emergency_disable": "emergency_disabled",
        "emergency": "emergency_disabled",
    }
    stage_s = aliases.get(stage_s, stage_s)
    return stage_s if stage_s in RELEASE_VALID_STAGES else default


def _default_release_state() -> dict:
    configured_stage = _normalize_release_stage(SYSTEM_RELEASE_STAGE, default="paper")
    now_utc = datetime.now(timezone.utc).isoformat()
    now_ny_iso = now_ny().isoformat()
    return {
        "configured_stage": configured_stage,
        "current_stage": configured_stage,
        "last_transition_utc": now_utc,
        "last_transition_ny": now_ny_iso,
        "last_transition_reason": "startup_default",
        "last_transition_actor": "system",
        "approval_status": "approved" if configured_stage == "live_guarded" else "not_required",
        "approval_armed": bool(configured_stage == "live_guarded"),
        "history": [
            {
                "ts_utc": now_utc,
                "ts_ny": now_ny_iso,
                "from_stage": None,
                "to_stage": configured_stage,
                "reason": "startup_default",
                "actor": "system",
            }
        ],
    }


def _sanitize_release_state(payload: dict) -> dict:
    state = _default_release_state()
    if not isinstance(payload, dict):
        return state
    configured_stage = _normalize_release_stage(SYSTEM_RELEASE_STAGE, default=state["configured_stage"])
    payload_configured_stage = _normalize_release_stage(payload.get("configured_stage") or configured_stage, default=configured_stage)
    payload_current_stage = _normalize_release_stage(payload.get("current_stage") or payload_configured_stage, default=payload_configured_stage)
    current_stage = configured_stage if configured_stage == "live" else payload_current_stage
    state.update({
        "configured_stage": configured_stage,
        "current_stage": current_stage,
        "last_transition_utc": payload.get("last_transition_utc") or state.get("last_transition_utc"),
        "last_transition_ny": payload.get("last_transition_ny") or state.get("last_transition_ny"),
        "last_transition_reason": str(payload.get("last_transition_reason") or state.get("last_transition_reason") or ""),
        "last_transition_actor": str(payload.get("last_transition_actor") or state.get("last_transition_actor") or "system"),
        "approval_status": str(payload.get("approval_status") or ("approved" if current_stage in {"live_guarded", "live"} else "not_required")),
        "approval_armed": bool(payload.get("approval_armed") or (current_stage in {"live_guarded", "live"})),
    })
    history = []
    for item in list(payload.get("history") or [])[-max(1, RELEASE_STATE_HISTORY_LIMIT):]:
        if not isinstance(item, dict):
            continue
        history.append({
            "ts_utc": item.get("ts_utc"),
            "ts_ny": item.get("ts_ny"),
            "from_stage": _normalize_release_stage(item.get("from_stage"), default="paper") if item.get("from_stage") is not None else None,
            "to_stage": _normalize_release_stage(item.get("to_stage"), default=current_stage),
            "reason": str(item.get("reason") or ""),
            "actor": str(item.get("actor") or "system"),
        })
    if history:
        state["history"] = history
    return state


def restore_release_state() -> dict:
    global RELEASE_STATE
    payload = _safe_json_read(RELEASE_STATE_PATH)
    if payload:
        state = _sanitize_release_state(payload)
        state["restored_from_state"] = True
        RELEASE_STATE = state
        return {
            "path": RELEASE_STATE_PATH,
            "loaded": True,
            "current_stage": state.get("current_stage"),
            "history_restored": len(state.get("history") or []),
        }
    state = _default_release_state()
    state["restored_from_state"] = False
    RELEASE_STATE = state
    _safe_json_write(RELEASE_STATE_PATH, state)
    return {
        "path": RELEASE_STATE_PATH,
        "loaded": False,
        "current_stage": state.get("current_stage"),
        "history_restored": len(state.get("history") or []),
    }


def persist_release_state(reason: str = "") -> bool:
    payload = dict(RELEASE_STATE or _default_release_state())
    payload["saved_at_utc"] = datetime.now(timezone.utc).isoformat()
    if reason:
        payload["save_reason"] = str(reason)
    return _safe_json_write(RELEASE_STATE_PATH, payload)


def _release_transition_allowed(current_stage: str, target_stage: str) -> bool:
    allowed = {
        "paper": {"paper", "guarded_live_eligible", "live_guarded", "live", "emergency_disabled"},
        "guarded_live_eligible": {"paper", "guarded_live_eligible", "live_guarded", "live", "emergency_disabled"},
        "live_guarded": {"paper", "live_guarded", "live", "emergency_disabled"},
        "live": {"paper", "live_guarded", "live", "emergency_disabled"},
        "emergency_disabled": {"paper", "emergency_disabled"},
    }
    return target_stage in allowed.get(current_stage, {"paper"})


def _manual_promotion_unmet_conditions(target_stage: str, preflight: dict | None = None) -> list[str]:
    target_stage = _normalize_release_stage(target_stage, default="paper")
    if target_stage not in {"guarded_live_eligible", "live_guarded", "live"}:
        return list((preflight or {}).get("unmet_conditions") or [])
    base_unmet = [str(x or "").strip().lower() for x in list((preflight or {}).get("unmet_conditions") or []) if str(x or "").strip()]
    if not RELEASE_PROMOTION_MANUAL_ARM_ALLOWED:
        return base_unmet
    arm_safe_ignored = set(RELEASE_PROMOTION_ARMING_IGNORE_CONDITIONS)
    return [item for item in base_unmet if item not in arm_safe_ignored]


def _release_workflow_snapshot(include_gate: bool = True) -> dict:
    configured_stage = _normalize_release_stage(SYSTEM_RELEASE_STAGE, default="paper")
    state = _sanitize_release_state(RELEASE_STATE or {})
    persisted_stage = _normalize_release_stage(state.get("current_stage") or configured_stage, default=configured_stage)
    if configured_stage == "live":
        effective_stage = "live"
        persisted_stage = "live"
    else:
        effective_stage = persisted_stage if RELEASE_WORKFLOW_ENFORCED else configured_stage
    history = list(state.get("history") or [])[-max(1, RELEASE_STATE_HISTORY_LIMIT):]
    out = {
        "workflow_enforced": bool(RELEASE_WORKFLOW_ENFORCED),
        "promotion_require_readiness": bool(RELEASE_PROMOTION_REQUIRE_READINESS),
        "configured_stage": configured_stage,
        "persisted_stage": persisted_stage,
        "effective_stage": effective_stage,
        "configured_stage_drift": bool(configured_stage != persisted_stage),
        "approval_status": str(state.get("approval_status") or "not_required"),
        "approval_armed": bool(state.get("approval_armed")),
        "last_transition_utc": state.get("last_transition_utc"),
        "last_transition_ny": state.get("last_transition_ny"),
        "last_transition_reason": state.get("last_transition_reason"),
        "last_transition_actor": state.get("last_transition_actor"),
        "history_count": len(history),
        "history": history,
        "allowed_transitions": sorted(_release_transition_allowed(effective_stage, s) and s or None for s in RELEASE_VALID_STAGES if _release_transition_allowed(effective_stage, s)),
    }
    out["allowed_transitions"] = [x for x in out["allowed_transitions"] if x]
    if include_gate:
        target_live = _build_release_gate_snapshot("live_guarded", include_stage_check=False)
        target_eligible = _build_release_gate_snapshot("guarded_live_eligible", include_stage_check=False)
        eligible_execution_unmet = list(target_eligible.get("unmet_conditions") or [])
        live_execution_unmet = list(target_live.get("unmet_conditions") or []) + (["live_env_not_armed"] if (DRY_RUN or (not LIVE_TRADING_ENABLED)) else [])
        worker_status_now = _worker_status_snapshot()
        eligible_execution_unmet = _normalize_worker_unmet_conditions(eligible_execution_unmet, worker_status_now)
        live_execution_unmet = _normalize_worker_unmet_conditions(live_execution_unmet, worker_status_now)
        eligible_arm_unmet = _manual_promotion_unmet_conditions("guarded_live_eligible", {"unmet_conditions": eligible_execution_unmet})
        live_arm_unmet = _manual_promotion_unmet_conditions("live_guarded", {"unmet_conditions": live_execution_unmet})
        direct_live_unmet = _manual_promotion_unmet_conditions("live", {"unmet_conditions": live_execution_unmet})
        out["promotion_targets"] = {
            "guarded_live_eligible": {
                "ready": len(eligible_execution_unmet) == 0,
                "unmet_conditions": eligible_execution_unmet,
                "arm_ready": len(eligible_arm_unmet) == 0,
                "arm_unmet_conditions": eligible_arm_unmet,
            },
            "live_guarded": {
                "ready": len(live_execution_unmet) == 0,
                "unmet_conditions": live_execution_unmet,
                "arm_ready": len(live_arm_unmet) == 0,
                "arm_unmet_conditions": live_arm_unmet,
            },
            "live": {
                "ready": len(live_execution_unmet) == 0,
                "unmet_conditions": live_execution_unmet,
                "arm_ready": len(direct_live_unmet) == 0,
                "arm_unmet_conditions": direct_live_unmet,
            },
        }
        out["live_activation_armed"] = bool(effective_stage in {"live_guarded", "live"} and (effective_stage == "live" or out.get("approval_armed")) and LIVE_TRADING_ENABLED and (not DRY_RUN))
    return out


def _build_release_gate_snapshot(stage: str, include_stage_check: bool = True) -> dict:
    lifecycle = _paper_lifecycle_counts()
    worker_status = _worker_status_snapshot()
    reconcile = build_reconcile_snapshot()
    regime = dict(LAST_REGIME_SNAPSHOT or {})
    session = _session_boundary_snapshot()
    market_open_now = bool(session.get("market_open_now"))
    recent_scan_status = _recent_market_scan_status(RELEASE_MAX_SCAN_AGE_SEC, market_open_now)
    last_scan_age_sec = recent_scan_status.get("age_sec")
    recent_market_scan_ok = bool(recent_scan_status.get("ok"))
    unmet = []
    if include_stage_check and stage not in RELEASE_ALLOWED_LIVE_STAGES:
        unmet.append("release_stage_not_allowed")
    if stage == "emergency_disabled":
        unmet.append("release_stage_emergency_disabled")
    if KILL_SWITCH:
        unmet.append("kill_switch_on")
    if daily_halt_active():
        unmet.append("daily_halt_active")
    if READINESS_REQUIRE_WORKERS and not worker_status["scanner_running"]:
        unmet.append("scanner_worker_not_ready")
    if READINESS_REQUIRE_WORKERS and not worker_status["exit_worker_running"]:
        unmet.append("exit_worker_not_ready")
    if RELEASE_REQUIRE_REGIME_COMPLETE and not bool(regime.get("data_complete")):
        unmet.append("regime_incomplete")
    if RELEASE_REQUIRE_REGIME_FAVORABLE and not bool(regime.get("favorable")):
        unmet.append("regime_not_favorable")
    if RELEASE_REQUIRE_RECENT_MARKET_SCAN and not recent_market_scan_ok:
        unmet.append("recent_market_scan_missing")
    if lifecycle["scan_completed"] < RELEASE_MIN_COMPLETED_SCANS:
        unmet.append("insufficient_completed_scans")
    if lifecycle["candidate_selected"] < RELEASE_MIN_SELECTED_CANDIDATES:
        unmet.append("insufficient_selected_candidates")
    if lifecycle["entry_events"] < RELEASE_MIN_ENTRY_EVENTS:
        unmet.append("insufficient_entry_events")
    if lifecycle["exit_events"] < RELEASE_MIN_EXIT_EVENTS:
        unmet.append("insufficient_exit_events")
    if reconcile.get("orphan_open_order_symbols"):
        unmet.append("orphan_open_orders_present")
    if reconcile.get("plans_missing_open_order"):
        unmet.append("plans_missing_open_order")
    if reconcile.get("stale_active_plans"):
        unmet.append("stale_active_plans_present")
    if reconcile.get("partial_fill_plan_symbols"):
        unmet.append("partial_fill_aging_present")
    unmet = _normalize_worker_unmet_conditions(unmet, worker_status)

    freshness = freshness_snapshot()
    continuity = {}
    continuity_issues = []
    continuity_error = ""
    try:
        continuity = continuity_snapshot(normalize_current=True)
        continuity_issues = list(continuity.get("issues") or [])
    except Exception as e:
        continuity_error = str(e)
        continuity = {
            "ok": False,
            "error": continuity_error,
            "issues": [
                {
                    "code": "continuity_snapshot_failed",
                    "severity": "error",
                    "details": {"error": continuity_error},
                }
            ],
            "issue_codes": ["continuity_snapshot_failed"],
        }
        continuity_issues = list(continuity.get("issues") or [])

    if continuity_issues:
        unmet.append("continuity_issues_present")
    if continuity.get("issue_codes"):
        unmet.extend(sorted(set(str(code or "") for code in continuity.get("issue_codes") or [] if code)))

    unmet = list(dict.fromkeys(str(x) for x in unmet if x))
    go_live_eligible = len(unmet) == 0
    return {
        "system_release_stage": stage,
        "session": freshness.get("session"),
        "freshness": freshness,
        "release_gate_enforced": RELEASE_GATE_ENFORCED,
        "release_allowed_live_stages": sorted(RELEASE_ALLOWED_LIVE_STAGES),
        "go_live_eligible": go_live_eligible,
        "unmet_conditions": unmet,
        "last_scan_age_sec": last_scan_age_sec,
        "recent_market_scan_source": recent_scan_status.get("source"),
        "recent_market_scan_reason": recent_scan_status.get("reason"),
        "recent_market_scan_ok": recent_market_scan_ok,
        "regime": {
            "known": bool(regime),
            "data_complete": bool(regime.get("data_complete")),
            "favorable": regime.get("favorable"),
            "reasons": list(regime.get("reasons") or []),
        },
        "lifecycle_counts": lifecycle,
        "worker_status": worker_status,
        "reconcile_snapshot": {
            "orphan_open_order_symbols": list(reconcile.get("orphan_open_order_symbols") or []),
            "plans_missing_open_order": list(reconcile.get("plans_missing_open_order") or []),
            "stale_active_plans": list(reconcile.get("stale_active_plans") or []),
            "partial_fill_plan_symbols": list(reconcile.get("partial_fill_plan_symbols") or []),
            "open_order_count": int(reconcile.get("open_order_count") or 0),
            "active_plan_count": int(reconcile.get("active_plan_count") or 0),
            "broker_positions_count": int(reconcile.get("broker_positions_count") or 0),
        },
        "continuity": continuity,
        "daily_halt_truth": daily_halt_truth_snapshot(),
        "daily_halt_reason": daily_halt_truth_snapshot().get("daily_halt_reason"),
        "today_pnl_truth": today_pnl_truth_snapshot(),
        "today_realized_pnl": today_pnl_truth_snapshot().get("today_realized_pnl"),
        "today_unrealized_pnl": today_pnl_truth_snapshot().get("today_unrealized_pnl"),
        "today_net_pnl": today_pnl_truth_snapshot().get("today_net_pnl"),
    }


def release_stage_transition(target_stage: str, actor: str = "system", reason: str = "") -> dict:
    global RELEASE_STATE
    target_stage = _normalize_release_stage(target_stage, default="paper")
    current = _sanitize_release_state(RELEASE_STATE or {})
    current_stage = _normalize_release_stage(current.get("current_stage") or SYSTEM_RELEASE_STAGE, default="paper")
    if not _release_transition_allowed(current_stage, target_stage):
        raise HTTPException(status_code=400, detail=f"Transition not allowed: {current_stage} -> {target_stage}")
    if RELEASE_PROMOTION_REQUIRE_READINESS and target_stage in {"guarded_live_eligible", "live_guarded", "live"}:
        preflight = _release_workflow_snapshot(include_gate=True).get("promotion_targets", {}).get(target_stage, {})
        unmet = _manual_promotion_unmet_conditions(target_stage, preflight)
        if unmet:
            raise HTTPException(
                status_code=409,
                detail={
                    "target_stage": target_stage,
                    "unmet_conditions": unmet,
                    "arm_ready": bool(preflight.get("arm_ready")),
                    "execution_unmet_conditions": list(preflight.get("unmet_conditions") or []),
                    "arm_unmet_conditions": list(preflight.get("arm_unmet_conditions") or []),
                },
            )
    now_utc = datetime.now(timezone.utc).isoformat()
    now_ny_iso = now_ny().isoformat()
    entry = {
        "ts_utc": now_utc,
        "ts_ny": now_ny_iso,
        "from_stage": current_stage,
        "to_stage": target_stage,
        "reason": str(reason or "manual_transition"),
        "actor": str(actor or "system"),
    }
    history = list(current.get("history") or [])
    history.append(entry)
    current.update({
        "configured_stage": _normalize_release_stage(SYSTEM_RELEASE_STAGE, default="paper"),
        "current_stage": target_stage,
        "last_transition_utc": now_utc,
        "last_transition_ny": now_ny_iso,
        "last_transition_reason": entry["reason"],
        "last_transition_actor": entry["actor"],
        "approval_status": "approved" if target_stage in {"live_guarded", "live"} else ("not_required" if target_stage == "paper" else str(current.get("approval_status") or "not_required")),
        "approval_armed": bool(target_stage in {"live_guarded", "live"}),
        "history": history[-max(1, RELEASE_STATE_HISTORY_LIMIT):],
        "restored_from_state": False,
    })
    RELEASE_STATE = current
    persist_release_state(reason=entry["reason"])
    return _release_workflow_snapshot(include_gate=True)


# Run startup restore only after all helper functions it depends on are defined.


def freshness_snapshot() -> dict:
    session = _session_boundary_snapshot()
    if _regime_snapshot_needs_refresh(session):
        _refresh_regime_snapshot_if_needed(force=True)
    scanner_ref = (LAST_SCANNER_TELEMETRY or {}).get("last_worker_event_utc") or (LAST_SCANNER_TELEMETRY or {}).get("last_success_utc") or (LAST_SCANNER_TELEMETRY or {}).get("last_event_utc")
    scan_source = "memory" if LAST_SCAN else ("restored" if (globals().get("SCAN_STATE_RESTORE") or {}).get("last_scan_restored") else "empty")
    regime_source = "memory" if LAST_REGIME_SNAPSHOT else ("restored" if (globals().get("REGIME_STATE_RESTORE") or {}).get("current_restored") else "empty")
    lifecycle_source = "memory" if LAST_PAPER_LIFECYCLE else ("restored" if (globals().get("PAPER_LIFECYCLE_STATE_RESTORE") or {}).get("last_event_restored") else "empty")
    scanner_source = "memory" if LAST_SCANNER_TELEMETRY else ("restored" if (globals().get("SCANNER_TELEMETRY_STATE_RESTORE") or {}).get("last_event_restored") else "empty")
    aligned_last_scan = _aligned_last_scan_display(session)
    lifecycle_activity = _paper_lifecycle_same_session_activity(session)
    entries = {
        "last_scan": _freshness_entry("last_scan", aligned_last_scan.get("ts_utc") or LAST_SCAN.get("ts_utc"), source=str(aligned_last_scan.get("source") or scan_source), max_age_sec=max(60, RELEASE_MAX_SCAN_AGE_SEC), require_same_session=True, extra={"reason": aligned_last_scan.get("reason") or LAST_SCAN.get("reason"), "display_reason": aligned_last_scan.get("reason"), "fallback_from_last_scan_reason": aligned_last_scan.get("fallback_from_last_scan_reason"), "fallback_from_last_scan_source": aligned_last_scan.get("fallback_from_last_scan_source")}),
        "regime": _freshness_entry("regime", (LAST_REGIME_SNAPSHOT or {}).get("ts_utc"), source=regime_source, max_age_sec=max(60, RELEASE_MAX_SCAN_AGE_SEC), require_same_session=True, extra={"favorable": (LAST_REGIME_SNAPSHOT or {}).get("favorable"), "data_complete": (LAST_REGIME_SNAPSHOT or {}).get("data_complete")}),
        "paper_lifecycle": _freshness_entry("paper_lifecycle", (LAST_PAPER_LIFECYCLE or {}).get("ts_utc"), source=lifecycle_source, require_same_session=True, extra={"stage": (LAST_PAPER_LIFECYCLE or {}).get("stage"), "status_value": (LAST_PAPER_LIFECYCLE or {}).get("status"), "same_session_activity_count": lifecycle_activity.get("count", 0)}),
        "scanner_telemetry": _freshness_entry("scanner_telemetry", scanner_ref, source=scanner_source, max_age_sec=max(READINESS_SCANNER_MAX_AGE_SEC, SCANNER_INTERVAL_SEC + SCANNER_TIMEOUT_SEC + max(10, SCANNER_JITTER_SEC) + 60), extra={"event": (LAST_SCANNER_TELEMETRY or {}).get("event"), "attempts_today": (LAST_SCANNER_TELEMETRY or {}).get("attempts_today")}),
        "exit_heartbeat": _freshness_entry("exit_heartbeat", LAST_EXIT_HEARTBEAT.get("ts_utc"), source="memory" if LAST_EXIT_HEARTBEAT else "empty", max_age_sec=max(READINESS_EXIT_MAX_AGE_SEC, 30)),
    }
    regime_row = entries.get("regime") or {}
    if (not bool(session.get("market_day"))) and regime_row.get("status") == "stale":
        regime_row["fresh"] = True
        regime_row["status"] = "deferred"
        regime_row["freshness_deferred"] = True
        regime_row["freshness_deferred_reason"] = session.get("market_closed_reason") or "market_closed"
        regime_row["freshness_note"] = "Regime freshness is deferred while the market is closed."
    lifecycle_row = entries.get("paper_lifecycle") or {}
    if lifecycle_row.get("status") == "stale" and not lifecycle_activity.get("has_same_session_activity"):
        lifecycle_row["fresh"] = True
        lifecycle_row["status"] = "deferred"
        lifecycle_row["freshness_deferred"] = True
        lifecycle_row["freshness_deferred_reason"] = "no_same_session_activity_yet"
        lifecycle_row["freshness_note"] = "Paper lifecycle freshness is deferred until a same-session lifecycle event occurs."
    stale = [name for name, row in entries.items() if row.get("status") == "stale"]
    missing = [name for name, row in entries.items() if row.get("status") == "missing"]
    return {
        "session": session,
        "entries": entries,
        "stale_entries": stale,
        "missing_entries": missing,
        "all_fresh": (not stale and not missing),
        "aligned_last_scan": aligned_last_scan,
        "paper_lifecycle_same_session_activity": lifecycle_activity,
    }


def release_gate_status() -> dict:
    workflow = _release_workflow_snapshot(include_gate=True)
    stage = _normalize_release_stage(workflow.get("effective_stage") or SYSTEM_RELEASE_STAGE, default="paper")
    status = _build_release_gate_snapshot(stage, include_stage_check=True)
    paper_gate = _paper_proof_gate_snapshot()
    current_worker_status = _worker_status_snapshot()
    raw_unmet_conditions = list(status.get("unmet_conditions") or [])
    p471_exit_truth = _p471_exit_worker_readiness_truth(current_worker_status)
    normalized_unmet_conditions = _normalize_worker_unmet_conditions(raw_unmet_conditions, current_worker_status)
    p471_exit_truth["suppressed_exit_worker_not_ready"] = bool(
        "exit_worker_not_ready" in raw_unmet_conditions
        and "exit_worker_not_ready" not in normalized_unmet_conditions
    )

    status["worker_status"] = current_worker_status
    status["p471_exit_worker_readiness_truth"] = p471_exit_truth
    status["unmet_conditions"] = normalized_unmet_conditions
    status["go_live_eligible"] = len(status.get("unmet_conditions") or []) == 0
    status.update({
        "system_release_stage": stage,
        "configured_release_stage": workflow.get("configured_stage"),
        "effective_release_stage": workflow.get("effective_stage"),
        "release_workflow": workflow,
        "paper_proof_eligible": bool(paper_gate.get("paper_proof_eligible")),
        "paper_orders_permitted": bool(paper_gate.get("paper_orders_permitted")),
        "paper_proof_unmet_conditions": list(paper_gate.get("paper_proof_unmet_conditions") or []),
    })
    status["live_orders_permitted"] = bool(status.get("go_live_eligible") and workflow.get("live_activation_armed"))
    if workflow.get("configured_stage_drift"):
        unmet = list(status.get("unmet_conditions") or [])
        if "release_stage_config_drift" not in unmet:
            unmet.append("release_stage_config_drift")
        status["unmet_conditions"] = unmet
        status["go_live_eligible"] = False
        status["live_orders_permitted"] = False
    return status

def is_live_trading_permitted(source: str = "") -> bool:
    source = str(source or "").strip()
    if DRY_RUN or (not LIVE_TRADING_ENABLED):
        return False
    if source == "worker_scan" and (not NEW_ENTRIES_ENABLED):
        return False
    if source == "worker_scan" and realized_closed_trade_loss_halt_active():
        return False
    if source == "worker_scan" and (not SCANNER_ALLOW_LIVE):
        return False
    if RELEASE_GATE_ENFORCED:
        gate = _p469_release_gate_snapshot_cached() if source == "worker_scan" else release_gate_status()
        if not gate.get("live_orders_permitted"):
            return False
    return True


def is_live_exit_permitted(source: str = "", reason: str = "") -> bool:
    """Permit protective exits when only entry-admission gates are stale.

    Patch 166 separates exits from entry freshness. A missing recent market
    scan can block new entries, but it must not strand an open position after a
    stop/target/profit-lock/time-exit condition fires. Hard controls still
    block exits: explicit DRY_RUN, disabled live trading, market closed, or any
    non-exit-safe release-gate blocker.
    """
    if DRY_RUN or (not LIVE_TRADING_ENABLED):
        return False
    gate = release_gate_status() if RELEASE_GATE_ENFORCED else {}
    if RELEASE_GATE_ENFORCED and (not gate.get("live_orders_permitted")):
        unmet = {str(x).strip().lower() for x in (gate.get("unmet_conditions") or []) if str(x).strip()}
        exit_safe_unmet = {"daily_halt_active", "recent_market_scan_missing"}
        if unmet and unmet.issubset(exit_safe_unmet):
            return True
        return False
    return True


def is_paper_execution_permitted(source: str = "") -> bool:
    stage = _normalize_release_stage(SYSTEM_RELEASE_STAGE, default="paper")
    if source != "worker_scan":
        return False
    if not PAPER_EXECUTION_ENABLED:
        return False
    if stage != "paper":
        return False
    if not APCA_PAPER:
        return False
    if not SCANNER_ALLOW_LIVE:
        return False
    if not NEW_ENTRIES_ENABLED:
        return False
    return True


def effective_entry_dry_run(source: str = "") -> bool:
    if source == EARLY_ENTRY_OVERRIDE_SOURCE and SWING_EARLY_ENTRY_OVERRIDE_ENABLED:
        return False
    if is_paper_execution_permitted(source):
        return False
    if source == "worker_scan":
        return bool(SCANNER_DRY_RUN or (not is_live_trading_permitted(source)))
    return bool(not is_live_trading_permitted(source))


def _parse_plan_opened_dt(plan: dict) -> Optional[datetime]:
    raw = str((plan or {}).get("opened_at") or "").strip()
    if not raw:
        return None
    try:
        dt = datetime.fromisoformat(raw)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=NY_TZ)
        return dt.astimezone(NY_TZ)
    except Exception:
        return None


def plan_days_held(plan: dict) -> int:
    opened = _parse_plan_opened_dt(plan)
    if opened is None:
        return 0
    return max(0, (now_ny().date() - opened.date()).days)


def same_day_exit_blocked(plan: dict, reason: str = "") -> bool:
    if STRATEGY_MODE != "swing":
        return False
    if SWING_ALLOW_SAME_DAY_EXIT:
        return False
    protective_reasons = {
        "kill_switch",
        "daily_stop_hit",
        "broker_reconcile_failure",
        "manual_emergency",
        "catastrophic_invalid",
        "stop",
        "profit_lock_stop",
        "target",
        "opening_damage_exit",
        "stall_loss_guard",
        "daily_breakout_profit_giveback_preservation_exit",
        "daily_breakout_failed_followthrough_exit",
    }
    if (reason or "").strip().lower() in protective_reasons:
        return False
    opened = _parse_plan_opened_dt(plan)
    if opened is None:
        return False
    return opened.date() == now_ny().date()

def cleanup_caches():
    """Housekeeping for in-memory caches (dedup + symbol locks)."""
    now = utc_ts()
    with STATE_LOCK:
        # dedup
        for k in list(DEDUP_CACHE.keys()):
            if now - DEDUP_CACHE[k] > max(DEDUP_WINDOW_SEC * 2, 300):
                del DEDUP_CACHE[k]
        # symbol locks
        for sym in list(SYMBOL_LOCKS.keys()):
            if SYMBOL_LOCKS[sym] <= now:
                del SYMBOL_LOCKS[sym]



def dedup_key(payload: dict) -> str:
    raw = f"{payload.get('symbol','')}-{payload.get('side','')}-{payload.get('signal','')}-{payload.get('secret','')}"
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:24]


def is_symbol_locked(symbol: str) -> bool:
    now = utc_ts()
    with STATE_LOCK:
        exp = SYMBOL_LOCKS.get(symbol, 0)
    return exp > now


def lock_symbol(symbol: str):
    with STATE_LOCK:
        SYMBOL_LOCKS[symbol] = utc_ts() + SYMBOL_LOCK_SEC


def take_symbol_lock(symbol: str, lock_sec: int | None = None) -> bool:
    """Atomically take/update a symbol lock if it is not currently locked."""
    now = utc_ts()
    ttl = int(lock_sec if lock_sec is not None else SYMBOL_LOCK_SEC)
    with STATE_LOCK:
        exp = SYMBOL_LOCKS.get(symbol, 0)
        if exp > now:
            return False
        SYMBOL_LOCKS[symbol] = now + max(ttl, 1)
        return True


def release_symbol_lock(symbol: str):
    with STATE_LOCK:
        SYMBOL_LOCKS.pop(symbol, None)


def soften_symbol_lock(symbol: str, lock_sec: int = 5):
    with STATE_LOCK:
        SYMBOL_LOCKS[symbol] = utc_ts() + max(int(lock_sec), 1)
        

def _scanner_min_rank_for_signal(signal_name: str, family: str = "primary") -> float:
    sig = str(signal_name or "").upper()
    if sig == "INTRADAY_VWAP_RECLAIM":
        return float(INTRADAY_VWAP_RECLAIM_MIN_RANK_SCORE)
    if sig == "INTRADAY_VWAP_CONTINUATION":
        return float(INTRADAY_VWAP_CONTINUATION_MIN_RANK_SCORE)
    return float(SCANNER_FALLBACK_MIN_RANK_SCORE if str(family or "") == "fallback" else SCANNER_RANK_MIN_SCORE)


def compute_signal_rank(signal_name: str, vp_diag: dict | None = None) -> tuple[float, dict]:
    vp_diag = vp_diag or {}
    raw_score = float(vp_diag.get("score", 0.0) or 0.0)
    rank = raw_score
    family = "fallback" if "FALLBACK" in str(signal_name or "").upper() else "primary"
    components: dict[str, float] = {"raw_score": raw_score}
    if family == "primary":
        rank += SIGNAL_RANK_PRIMARY_BONUS
        components["primary_bonus"] = SIGNAL_RANK_PRIMARY_BONUS
    else:
        rank -= SIGNAL_RANK_FALLBACK_PENALTY
        components["fallback_penalty"] = -SIGNAL_RANK_FALLBACK_PENALTY
    if vp_diag.get("touched"):
        rank += SIGNAL_RANK_TOUCH_BONUS
        components["touch_bonus"] = SIGNAL_RANK_TOUCH_BONUS
    if vp_diag.get("relvol_ok"):
        rank += SIGNAL_RANK_RELVOL_BONUS
        components["relvol_bonus"] = SIGNAL_RANK_RELVOL_BONUS
    if vp_diag.get("atr_ok"):
        rank += SIGNAL_RANK_ATR_BONUS
        components["atr_bonus"] = SIGNAL_RANK_ATR_BONUS
    if vp_diag.get("micro_vol_ok"):
        rank += SIGNAL_RANK_MICRO_BONUS
        components["micro_bonus"] = SIGNAL_RANK_MICRO_BONUS
    if vp_diag.get("entry_confirm_ok"):
        rank += SIGNAL_RANK_CONFIRM_BONUS
        components["confirm_bonus"] = SIGNAL_RANK_CONFIRM_BONUS
    if vp_diag.get("last_1m_green"):
        rank += SIGNAL_RANK_GREEN_BONUS
        components["green_bonus"] = SIGNAL_RANK_GREEN_BONUS
    if vp_diag.get("higher_low_ok"):
        rank += SIGNAL_RANK_HIGHER_LOW_BONUS
        components["higher_low_bonus"] = SIGNAL_RANK_HIGHER_LOW_BONUS
    dist = abs(float(vp_diag.get("dist_to_vwap_pct", 0.0) or 0.0))
    if dist > SIGNAL_RANK_MAX_DIST_VWAP_PCT:
        rank -= SIGNAL_RANK_DISTANCE_PENALTY
        components["distance_penalty"] = -SIGNAL_RANK_DISTANCE_PENALTY
    return float(rank), {"family": family, "raw_score": raw_score, "rank_score": float(rank), "components": components}

def candidate_slots_available(extra_buffer: int = 0) -> int:
    max_positions = _effective_max_open_positions()
    try:
        remaining = int(max_positions) - count_open_positions_allowed() - max(int(extra_buffer), 0)
        return max(0, remaining)
    except Exception:
        return max(0, int(max_positions))

def count_open_positions_allowed() -> int:
    return len(list_open_positions_allowed())


def max_open_positions_reached(extra_buffer: int = 0) -> bool:
    max_positions = _effective_max_open_positions()
    if max_positions <= 0:
        return False
    return count_open_positions_allowed() + max(int(extra_buffer), 0) >= max_positions


def daily_pnl() -> float | None:
    """
    Best-effort daily P&L using Alpaca account equity change from last_equity.
    This is *not* perfect but is reliable enough as a safety brake.
    """
    try:
        acct = trading_client.get_account()
        equity = float(acct.equity)
        last_equity = float(acct.last_equity)
        return equity - last_equity
    except Exception:
        return None


def _account_daily_pnl_snapshot() -> dict:
    """Broker account equity delta used as the highest-level daily P&L truth."""
    try:
        acct = trading_client.get_account()
        equity = _safe_float(getattr(acct, "equity", None), 0.0)
        last_equity = _safe_float(getattr(acct, "last_equity", None), 0.0)
        buying_power = _safe_float(getattr(acct, "buying_power", None), 0.0)
        cash = _safe_float(getattr(acct, "cash", None), 0.0)
        pnl = equity - last_equity if equity or last_equity else 0.0
        pct = (pnl / last_equity) if last_equity else 0.0
        return {
            "ok": True,
            "source": "alpaca_account_equity",
            "equity": round(equity, 4),
            "last_equity": round(last_equity, 4),
            "account_daily_pnl": round(pnl, 4),
            "account_daily_pnl_pct": round(pct, 6),
            "buying_power": round(buying_power, 4),
            "cash": round(cash, 4),
            "ts_utc": datetime.now(timezone.utc).isoformat(),
            "ts_ny": now_ny().isoformat(),
        }
    except Exception as exc:
        return {
            "ok": False,
            "source": "alpaca_account_equity",
            "error": str(exc),
            "account_daily_pnl": None,
            "ts_utc": datetime.now(timezone.utc).isoformat(),
            "ts_ny": now_ny().isoformat(),
        }


def daily_stop_hit() -> bool:
    context = _daily_stop_evaluation_context()
    if not bool(context.get("allowed")):
        return False
    stop_dollars = _configured_daily_stop_dollars_safe()
    if stop_dollars <= 0:
        return False
    pnl = daily_pnl()
    if pnl is None:
        return False
    return pnl <= -abs(stop_dollars)


def _daily_stop_evaluation_context(ts_ny: datetime | None = None) -> dict:
    """Daily stop is a regular-session control; do not re-arm yesterday's loss premarket/after-hours."""
    now = ts_ny or now_ny()
    market_day = bool(_is_regular_market_day(now))
    market_open_now = bool(in_market_hours())
    reasons: list[str] = []
    if not market_day:
        reasons.append("not_regular_market_day")
    if not market_open_now:
        reasons.append("outside_regular_market_hours")
    return {
        "allowed": bool(market_day and market_open_now),
        "session": now.date().isoformat(),
        "market_day": market_day,
        "market_open_now": market_open_now,
        "reasons": reasons,
    }


def _daily_stop_action() -> str:
    configured = str(globals().get("DAILY_STOP_ACTION") or getenv_any("DAILY_STOP_ACTION", default="") or "").strip().lower()
    if configured in {"flatten", "flatten_all", "liquidate", "close_all"}:
        return "flatten_all"
    if configured in {"halt", "halt_only", "block_only", "no_flatten"}:
        return "halt_only"
    mode = str(globals().get("STRATEGY_MODE") or getenv_any("STRATEGY_MODE", default="") or "").strip().lower()
    return "halt_only" if mode == "swing" else "flatten_all"


def _minutes_since_market_open(ts_ny: datetime | None = None) -> float:
    now = ts_ny or now_ny()
    market_open_dt = now.replace(hour=MARKET_OPEN.hour, minute=MARKET_OPEN.minute, second=0, microsecond=0)
    return (now - market_open_dt).total_seconds() / 60.0


def _daily_stop_flatten_decision(ts_ny: datetime | None = None) -> dict:
    now = ts_ny or now_ny()
    action = _daily_stop_action()
    allow_bulk = bool(globals().get("ALLOW_DAILY_STOP_BULK_FLATTEN", False))
    confirm_sec = max(0, int(globals().get("DAILY_STOP_CONFIRMATION_SEC", 60) or 0))
    grace_min = max(0, int(globals().get("SWING_DAILY_STOP_OPEN_GRACE_MIN", 15) or 0))
    mode = str(globals().get("STRATEGY_MODE") or "").strip().lower()
    minutes_since_open = _minutes_since_market_open(now)
    in_open_grace = bool(mode == "swing" and in_market_hours() and grace_min > 0 and 0 <= minutes_since_open < float(grace_min))

    reasons: list[str] = []
    if action != "flatten_all":
        reasons.append("daily_stop_action_halt_only")
    if not allow_bulk:
        reasons.append("bulk_flatten_not_explicitly_enabled")
    if in_open_grace:
        reasons.append("swing_open_grace_active")

    state = globals().setdefault("DAILY_STOP_CONFIRMATION_STATE", {})
    first_seen_raw = state.get("first_seen_utc")
    first_seen_dt = None
    if first_seen_raw:
        try:
            first_seen_dt = datetime.fromisoformat(str(first_seen_raw).replace("Z", "+00:00"))
            if first_seen_dt.tzinfo is None:
                first_seen_dt = first_seen_dt.replace(tzinfo=timezone.utc)
        except Exception:
            first_seen_dt = None
    now_utc = datetime.now(timezone.utc)
    if first_seen_dt is None:
        first_seen_dt = now_utc
        state["first_seen_utc"] = now_utc.isoformat()
        state["breach_count"] = 1
    else:
        state["breach_count"] = int(state.get("breach_count") or 1) + 1
    elapsed_sec = max(0.0, (now_utc - first_seen_dt).total_seconds())
    confirmed = elapsed_sec >= float(confirm_sec) or confirm_sec == 0
    if not confirmed:
        reasons.append("daily_stop_confirmation_pending")

    can_flatten = bool(action == "flatten_all" and allow_bulk and confirmed and not in_open_grace)
    if can_flatten:
        state["last_confirmed_utc"] = now_utc.isoformat()
    return {
        "action": action,
        "can_flatten": can_flatten,
        "allow_bulk_flatten": allow_bulk,
        "confirmation_sec": confirm_sec,
        "confirmation_elapsed_sec": round(elapsed_sec, 3),
        "confirmation_ready": confirmed,
        "swing_open_grace_min": grace_min,
        "in_open_grace": in_open_grace,
        "minutes_since_market_open": round(minutes_since_open, 3),
        "reasons": reasons,
        "recommended_action": "halt_only_no_bulk_flatten" if not can_flatten else "bulk_flatten_confirmed",
    }


def _deactivate_plans_without_broker_positions(source: str = "reconcile", reason: str = "broker_flat_verified") -> list[dict]:
    live_symbols: set[str] = set()
    try:
        live_symbols.update({str((p or {}).get("symbol") or "").upper() for p in list_open_positions_details_allowed()})
    except Exception:
        pass
    try:
        live_symbols.update({str((p or {}).get("symbol") or "").upper() for p in list_open_positions_allowed()})
    except Exception:
        pass
    try:
        open_order_symbols = {str((o or {}).get("symbol") or "").upper() for o in list_open_orders_safe()}
    except Exception:
        open_order_symbols = set()
    actions: list[dict] = []
    for sym, plan in list((TRADE_PLAN or {}).items()):
        symbol = str(sym or "").upper()
        if not symbol or symbol in live_symbols or symbol in open_order_symbols:
            continue
        if not isinstance(plan, dict) or not bool(plan.get("active")) or _plan_is_pending_entry(plan):
            continue
        plan["active"] = False
        plan["stale_position_recovered_at"] = now_ny().isoformat()
        plan["stale_position_recovery_reason"] = reason
        try:
            _transition_execution_lifecycle(plan, symbol, "closed", reason=reason, details={"source": source}, allow_illegal=True)
        except Exception:
            pass
        record_decision("RECONCILE", source, symbol, action="deactivated", reason=reason)
        actions.append({"symbol": symbol, "action": "deactivated_stale_plan", "reason": reason})
    if actions:
        persist_positions_snapshot(reason=reason, extra={"stale_plan_recovery": actions})
    return actions


# Patch 167B: fail-safe daily halt / today P&L truth helpers.
def _configured_daily_loss_limit_safe() -> float:
    base = float(getenv_float_any("DAILY_LOSS_LIMIT", default=0.0) or 0.0)
    intraday = float(getenv_float_any("INTRADAY_DAILY_LOSS_LIMIT", default=0.0) or 0.0)
    mode = str(globals().get("STRATEGY_MODE") or getenv_any("STRATEGY_MODE", default="")).strip().lower()
    return intraday if mode == "intraday" and intraday > 0 else base

def _configured_daily_stop_dollars_safe() -> float:
    try:
        base = float(globals().get("DAILY_STOP_DOLLARS", getenv_float_any("DAILY_STOP_DOLLARS", default=0.0)) or 0.0)
    except Exception:
        base = float(getenv_float_any("DAILY_STOP_DOLLARS", default=0.0) or 0.0)
    intraday = float(getenv_float_any("INTRADAY_DAILY_STOP_DOLLARS", default=0.0) or 0.0)
    mode = str(globals().get("STRATEGY_MODE") or getenv_any("STRATEGY_MODE", default="")).strip().lower()
    return intraday if mode == "intraday" and intraday > 0 else base


def _effective_max_open_positions() -> int:
    base = int(globals().get("MAX_OPEN_POSITIONS", getenv_int_any("SWING_MAX_OPEN_POSITIONS", "MAX_OPEN_POSITIONS", default=2)) or 0)
    intraday = int(getenv_int_any("INTRADAY_MAX_OPEN_POSITIONS", default=0) or 0)
    mode = str(globals().get("STRATEGY_MODE") or getenv_any("STRATEGY_MODE", default="")).strip().lower()
    return intraday if mode == "intraday" and intraday > 0 else base


def _effective_portfolio_exposure_cap_pct() -> float:
    base = float(globals().get("SWING_MAX_PORTFOLIO_EXPOSURE_PCT", getenv_float_any("SWING_MAX_PORTFOLIO_EXPOSURE_PCT", default=0.90)) or 0.0)
    intraday = float(getenv_float_any("INTRADAY_MAX_PORTFOLIO_EXPOSURE_PCT", default=0.0) or 0.0)
    mode = str(globals().get("STRATEGY_MODE") or getenv_any("STRATEGY_MODE", default="")).strip().lower()
    return intraday if mode == "intraday" and intraday > 0 else base


def _effective_symbol_exposure_cap_pct() -> float:
    base = float(globals().get("SWING_MAX_SYMBOL_EXPOSURE_PCT", getenv_float_any("SWING_MAX_SYMBOL_EXPOSURE_PCT", default=0.35)) or 0.0)
    intraday = float(getenv_float_any("INTRADAY_MAX_SYMBOL_EXPOSURE_PCT", default=0.0) or 0.0)
    mode = str(globals().get("STRATEGY_MODE") or getenv_any("STRATEGY_MODE", default="")).strip().lower()
    return intraday if mode == "intraday" and intraday > 0 else base


def _intraday_launch_projection(open_count_override: int | None = None) -> dict:
    mode = str(globals().get("STRATEGY_MODE") or getenv_any("STRATEGY_MODE", default="")).strip().lower()
    base_max_positions = int(globals().get("MAX_OPEN_POSITIONS", getenv_int_any("SWING_MAX_OPEN_POSITIONS", "MAX_OPEN_POSITIONS", default=2)) or 0)
    intraday_max_positions = int(getenv_int_any("INTRADAY_MAX_OPEN_POSITIONS", default=0) or 0)
    min_launch_open_slots = max(1, int(getenv_int_any("INTRADAY_LAUNCH_MIN_OPEN_SLOTS", default=3) or 3))
    base_daily_stop = float(globals().get("DAILY_STOP_DOLLARS", getenv_float_any("DAILY_STOP_DOLLARS", default=0.0)) or 0.0)
    intraday_daily_stop = float(getenv_float_any("INTRADAY_DAILY_STOP_DOLLARS", default=0.0) or 0.0)
    base_daily_loss = float(getenv_float_any("DAILY_LOSS_LIMIT", default=0.0) or 0.0)
    intraday_daily_loss = float(getenv_float_any("INTRADAY_DAILY_LOSS_LIMIT", default=0.0) or 0.0)
    base_portfolio_cap = float(globals().get("SWING_MAX_PORTFOLIO_EXPOSURE_PCT", getenv_float_any("SWING_MAX_PORTFOLIO_EXPOSURE_PCT", default=0.90)) or 0.0)
    intraday_portfolio_cap = float(getenv_float_any("INTRADAY_MAX_PORTFOLIO_EXPOSURE_PCT", default=0.0) or 0.0)
    base_symbol_cap = float(globals().get("SWING_MAX_SYMBOL_EXPOSURE_PCT", getenv_float_any("SWING_MAX_SYMBOL_EXPOSURE_PCT", default=0.35)) or 0.0)
    intraday_symbol_cap = float(getenv_float_any("INTRADAY_MAX_SYMBOL_EXPOSURE_PCT", default=0.0) or 0.0)
    projected_max_positions = intraday_max_positions if intraday_max_positions > 0 else base_max_positions
    projected_daily_stop = intraday_daily_stop if intraday_daily_stop > 0 else base_daily_stop
    projected_daily_loss = intraday_daily_loss if intraday_daily_loss > 0 else base_daily_loss
    projected_portfolio_cap = intraday_portfolio_cap if intraday_portfolio_cap > 0 else base_portfolio_cap
    projected_symbol_cap = intraday_symbol_cap if intraday_symbol_cap > 0 else base_symbol_cap
    daily_stop_multiplier = max(1.0, float(getenv_float_any("INTRADAY_LAUNCH_DAILY_STOP_MULTIPLIER", default=2.0) or 2.0))
    daily_loss_multiplier = max(1.0, float(getenv_float_any("INTRADAY_LAUNCH_DAILY_LOSS_MULTIPLIER", default=2.0) or 2.0))
    daily_stop_floor = max(float(base_daily_stop), float(getenv_float_any("INTRADAY_LAUNCH_BASE_DAILY_STOP_DOLLARS", default=150.0) or 150.0))
    daily_loss_floor = max(float(base_daily_loss), float(getenv_float_any("INTRADAY_LAUNCH_BASE_DAILY_LOSS_LIMIT", default=200.0) or 200.0))
    recommended_intraday_daily_stop = round(max(float(projected_daily_stop), daily_stop_floor * daily_stop_multiplier), 2)
    recommended_intraday_daily_loss = round(max(float(projected_daily_loss), daily_loss_floor * daily_loss_multiplier), 2)
    open_count = int(open_count_override) if open_count_override is not None else count_open_positions_allowed()
    projected_open_slots = max(0, int(projected_max_positions) - int(open_count))
    recommended_intraday_max_positions = max(
        int(projected_max_positions),
        int(base_max_positions) + int(min_launch_open_slots),
        int(open_count) + int(min_launch_open_slots),
    )
    open_slots_gap_to_min = max(0, int(min_launch_open_slots) - int(projected_open_slots))
    recommended_intraday_open_slots = max(0, int(recommended_intraday_max_positions) - int(open_count))
    recommended_env = {
        "STRATEGY_MODE": "intraday",
        "INTRADAY_MAX_OPEN_POSITIONS": str(recommended_intraday_max_positions),
        "INTRADAY_LAUNCH_MIN_OPEN_SLOTS": str(min_launch_open_slots),
        "INTRADAY_DAILY_STOP_DOLLARS": f"{recommended_intraday_daily_stop:.2f}",
        "INTRADAY_DAILY_LOSS_LIMIT": f"{recommended_intraday_daily_loss:.2f}",
    }
    next_actions = []
    optional_actions = []
    blockers = []
    if mode != "intraday":
        next_actions.append("set_STRATEGY_MODE_intraday_for_launch")
    if intraday_max_positions <= base_max_positions:
        capacity_actions = [
            "set_INTRADAY_MAX_OPEN_POSITIONS_above_current_base",
            f"set_INTRADAY_MAX_OPEN_POSITIONS_to_at_least_{recommended_intraday_max_positions}",
        ]
        if projected_open_slots < min_launch_open_slots:
            blockers.append("intraday_max_open_positions_not_above_base")
            next_actions.extend(capacity_actions)
        else:
            optional_actions.extend(capacity_actions)
    if projected_open_slots <= 0:
        blockers.append("projected_intraday_open_slots_zero")
        next_actions.append("raise_INTRADAY_MAX_OPEN_POSITIONS_or_free_existing_slots")
    if projected_open_slots < min_launch_open_slots:
        blockers.append("projected_intraday_open_slots_below_launch_min")
        required_capacity_action = f"set_INTRADAY_MAX_OPEN_POSITIONS_to_at_least_{recommended_intraday_max_positions}"
        if required_capacity_action not in next_actions:
            next_actions.append(required_capacity_action)
    if intraday_daily_stop <= base_daily_stop:
        optional_actions.append("consider_raising_INTRADAY_DAILY_STOP_DOLLARS")
    if intraday_daily_loss <= base_daily_loss:
        optional_actions.append("consider_raising_INTRADAY_DAILY_LOSS_LIMIT")
    if intraday_portfolio_cap <= base_portfolio_cap:
        optional_actions.append("consider_raising_INTRADAY_MAX_PORTFOLIO_EXPOSURE_PCT")
    if intraday_symbol_cap <= base_symbol_cap:
        optional_actions.append("consider_raising_INTRADAY_MAX_SYMBOL_EXPOSURE_PCT")
    return {
        "strategy_mode": mode,
        "mode_switch_required": mode != "intraday",
        "current_open_positions": open_count,
        "launch_min_open_slots": min_launch_open_slots,
        "recommended_intraday_max_open_positions": recommended_intraday_max_positions,
        "recommended_intraday_open_slots": recommended_intraday_open_slots,
        "recommended_intraday_daily_stop_dollars": recommended_intraday_daily_stop,
        "recommended_intraday_daily_loss_limit": recommended_intraday_daily_loss,
        "recommended_env": recommended_env,
        "launch_action_plan": _intraday_launch_action_plan(
            required_actions=next_actions,
            optional_scaling_actions=optional_actions,
            recommended_env=recommended_env,
        ),
        "blockers": blockers,
        "next_actions": next_actions,
        "optional_actions": optional_actions,
        "active": {
            "max_open_positions": _effective_max_open_positions(),
            "open_slots_available": candidate_slots_available(),
            "daily_stop_dollars": _configured_daily_stop_dollars_safe(),
            "daily_loss_limit": _configured_daily_loss_limit_safe(),
            "portfolio_exposure_cap_pct": _effective_portfolio_exposure_cap_pct(),
            "symbol_exposure_cap_pct": _effective_symbol_exposure_cap_pct(),
        },
        "configured_intraday_overrides": {
            "max_open_positions": intraday_max_positions,
            "daily_stop_dollars": intraday_daily_stop,
            "daily_loss_limit": intraday_daily_loss,
            "portfolio_exposure_cap_pct": intraday_portfolio_cap,
            "symbol_exposure_cap_pct": intraday_symbol_cap,
        },
        "projected_intraday": {
            "max_open_positions": projected_max_positions,
            "open_slots_available": projected_open_slots,
            "open_slots_gap_to_min": open_slots_gap_to_min,
            "daily_stop_dollars": projected_daily_stop,
            "daily_loss_limit": projected_daily_loss,
            "portfolio_exposure_cap_pct": projected_portfolio_cap,
            "symbol_exposure_cap_pct": projected_symbol_cap,
        },
    }

def _today_realized_pnl_from_strategy_state() -> dict:
    session = _session_boundary_snapshot()
    today = str((session or {}).get("today_ny") or "")
    rows = []
    gross = 0.0
    wins = losses = flat = 0
    try:
        for row in list((STRATEGY_PERFORMANCE_STATE or {}).get("closed_trades") or []):
            if not isinstance(row, dict):
                continue
            ts = str(row.get("ts_utc") or "")
            ts_ny = ""
            try:
                if ts:
                    dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=timezone.utc)
                    ts_ny = dt.astimezone(NY).date().isoformat()
            except Exception:
                ts_ny = ""
            if today and ts_ny != today:
                continue
            pnl = _safe_float(row.get("gross_pnl"), 0.0)
            gross += pnl
            if pnl > 0: wins += 1
            elif pnl < 0: losses += 1
            else: flat += 1
            rows.append({"symbol": str(row.get("symbol") or "").upper(), "strategy_name": str(row.get("strategy_name") or row.get("signal") or ""), "ts_utc": ts, "gross_pnl": round(pnl, 4), "reason": str(row.get("reason") or ""), "source": str(row.get("source") or "")})
    except Exception as exc:
        return {"ok": False, "source": "strategy_performance_state", "error": str(exc), "today_realized_pnl": 0.0, "closed_trades_today": 0, "rows": []}
    return {"ok": True, "source": "strategy_performance_state", "today_realized_pnl": round(gross, 4), "closed_trades_today": len(rows), "wins_today": wins, "losses_today": losses, "flat_today": flat, "rows": rows[-20:]}

def _p254_broker_preferred_today_strategy_realized_pnl(perf_state: dict | None = None) -> dict:
    try:
        strategy_rows = _p228_today_strategy_rows(perf_state=perf_state)
        worker_rows = [r for r in strategy_rows if str(r.get("source") or "") == "worker_exit"]
        broker_rows = [
            r for r in strategy_rows
            if str(r.get("source") or "") == "alpaca_orders_reconciled"
            or str(r.get("reason") or "") == "broker_exit_fill"
        ]
        other_rows = [
            r for r in strategy_rows
            if r not in worker_rows and r not in broker_rows
        ]

        economic_rows = []
        shadow_worker_rows = []
        used_worker: set[int] = set()

        for broker in sorted(broker_rows, key=lambda r: str(r.get("ts_utc") or "")):
            wi, worker = _p228_find_match(broker, worker_rows, used_worker)
            if wi is not None:
                used_worker.add(int(wi))
            attribution = dict(worker or {})
            if not attribution:
                attribution = _infer_recovered_plan_attribution(
                    str(broker.get("symbol") or ""),
                    order_id=str(broker.get("entry_order_id") or ""),
                )
            row = _p441_broker_reconciled_r_backfill(broker, attribution=attribution)
            row["preferred_basis"] = "broker_reconciled_strategy_row"
            row["paired_worker_exit"] = bool(worker)
            row["daily_loss_truth_included"] = True
            economic_rows.append(row)

        for i, worker in enumerate(worker_rows):
            if i in used_worker:
                continue
            row = dict(worker)
            row["preferred_basis"] = "unmatched_worker_exit_shadow_quarantined"
            row["paired_worker_exit"] = False
            row["daily_loss_truth_included"] = False
            row["shadow_quarantine_reason"] = "worker_exit_estimate_without_broker_reconciled_exit"
            shadow_worker_rows.append(row)

            if not bool(WORKER_EXIT_SHADOW_QUARANTINE_ENABLED):
                copy = dict(row)
                copy["preferred_basis"] = "unmatched_worker_exit_legacy_included"
                copy["daily_loss_truth_included"] = True
                economic_rows.append(copy)

        for row in other_rows:
            copy = dict(row)
            copy["preferred_basis"] = copy.get("preferred_basis") or "non_worker_non_broker_strategy_row"
            copy["daily_loss_truth_included"] = True
            economic_rows.append(copy)

        gross = round(sum(_safe_float(r.get("gross_pnl"), 0.0) for r in economic_rows), 4)
        raw_gross = round(sum(_safe_float(r.get("gross_pnl"), 0.0) for r in strategy_rows), 4)
        shadow_gross = round(sum(_safe_float(r.get("gross_pnl"), 0.0) for r in shadow_worker_rows), 4)

        wins = sum(1 for r in economic_rows if _safe_float(r.get("gross_pnl"), 0.0) > 0)
        losses = sum(1 for r in economic_rows if _safe_float(r.get("gross_pnl"), 0.0) < 0)
        flat = sum(1 for r in economic_rows if _safe_float(r.get("gross_pnl"), 0.0) == 0)

        duplicate_worker_rows_removed = max(0, len(strategy_rows) - len(economic_rows))
        shadow_quarantined_count = len(shadow_worker_rows) if bool(WORKER_EXIT_SHADOW_QUARANTINE_ENABLED) else 0

        return {
            "ok": True,
            "source": "strategy_performance_state_broker_preferred_deduped",
            "accounting_policy": "broker_rows_preferred_worker_exit_estimates_shadow_quarantined",
            "broker_only_daily_loss_truth_enabled": bool(BROKER_ONLY_DAILY_LOSS_TRUTH_ENABLED),
            "worker_exit_shadow_quarantine_enabled": bool(WORKER_EXIT_SHADOW_QUARANTINE_ENABLED),
            "today_realized_pnl": gross,
            "raw_strategy_state_realized_pnl": raw_gross,
            "duplicate_adjustment": round(gross - raw_gross, 4),
            "shadow_worker_exit_estimate_pnl": shadow_gross,
            "closed_trades_today": len(economic_rows),
            "raw_closed_rows_today": len(strategy_rows),
            "broker_reconciled_rows_today": len(broker_rows),
            "worker_exit_rows_today": len(worker_rows),
            "worker_exit_shadow_quarantined_rows_today": shadow_quarantined_count,
            "duplicate_worker_rows_removed": duplicate_worker_rows_removed,
            "wins_today": wins,
            "losses_today": losses,
            "flat_today": flat,
            "rows": economic_rows[-20:],
            "raw_rows": strategy_rows[-20:],
            "shadow_worker_exit_rows": shadow_worker_rows[-20:],
            "recommended_action": "use_broker_preferred_deduped_daily_pnl_with_worker_exit_shadow_quarantined",
        }
    except Exception as exc:
        return {
            "ok": False,
            "source": "strategy_performance_state_broker_preferred_deduped",
            "error": str(exc),
            "today_realized_pnl": 0.0,
            "closed_trades_today": 0,
            "rows": [],
            "shadow_worker_exit_rows": [],
        }

def _ny_date_from_iso(ts: str) -> str:
    try:
        if not ts:
            return ""
        dt = datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(NY).date().isoformat()
    except Exception:
        return ""

def _filled_order_row(order: dict) -> dict | None:
    try:
        status = str(getattr(_order_attr(order, "status", None), "value", _order_attr(order, "status", "")) or "").lower()
        if status not in {"filled", "partially_filled"}:
            return None
        symbol = str(_order_attr(order, "symbol", "") or "").upper()
        side = str(getattr(_order_attr(order, "side", None), "value", _order_attr(order, "side", "")) or "").lower()
        qty = abs(_safe_float(_order_attr(order, "filled_qty", 0.0) or 0.0))
        price = _safe_float(_order_attr(order, "filled_avg_price", 0.0) or 0.0)
        ts = str(_order_attr(order, "filled_at", "") or _order_attr(order, "updated_at", "") or _order_attr(order, "submitted_at", "") or "")
        if not symbol or side not in {"buy", "sell"} or qty <= 0 or price <= 0:
            return None
        return {"id": str(_order_attr(order, "id", "") or ""), "symbol": symbol, "side": side, "filled_qty": qty, "filled_avg_price": price, "filled_at": ts, "submitted_at": str(_order_attr(order, "submitted_at", "") or "")}
    except Exception:
        return None

def _today_realized_pnl_from_broker_orders() -> dict:
    session = _session_boundary_snapshot()
    today = str((session or {}).get("today_ny") or "")
    try:
        orders = _alpaca_get_orders_rest(status="all", limit=500)
        filled = []
        for order in orders:
            row = _filled_order_row(order)
            if row:
                filled.append(row)
        today_exits = [r for r in filled if r.get("side") == "sell" and _ny_date_from_iso(str(r.get("filled_at") or r.get("submitted_at") or "")) == today]
        rows = []
        wins = losses = flat = 0
        gross = 0.0
        for exit_row in sorted(today_exits, key=lambda r: str(r.get("filled_at") or r.get("submitted_at") or "")):
            sym = str(exit_row.get("symbol") or "").upper()
            exit_ts = str(exit_row.get("filled_at") or exit_row.get("submitted_at") or "")
            entry = _find_recent_entry_fill_for_symbol(sym, "buy", before_iso=exit_ts)
            entry_px = _safe_float((entry or {}).get("filled_avg_price"), 0.0)
            exit_px = _safe_float(exit_row.get("filled_avg_price"), 0.0)
            qty = abs(_safe_float(exit_row.get("filled_qty"), 0.0))
            pnl = 0.0
            calc_ok = False
            if entry_px > 0 and exit_px > 0 and qty > 0:
                pnl = (exit_px - entry_px) * qty
                calc_ok = True
                gross += pnl
                if pnl > 0:
                    wins += 1
                elif pnl < 0:
                    losses += 1
                else:
                    flat += 1
            rows.append({"symbol": sym, "ts_utc": exit_ts, "qty": round(qty, 4), "entry_price": round(entry_px, 4) if entry_px > 0 else None, "exit_price": round(exit_px, 4) if exit_px > 0 else None, "gross_pnl": round(pnl, 4), "calc_ok": calc_ok, "exit_order_id": str(exit_row.get("id") or ""), "entry_order_id": str((entry or {}).get("id") or ""), "source": "alpaca_orders"})
        return {"ok": True, "source": "alpaca_orders", "broker_truth_sync_enabled": True, "today_realized_pnl": round(gross, 4), "closed_trades_today": len([r for r in rows if r.get("calc_ok")]), "broker_exit_fills_today": len(today_exits), "wins_today": wins, "losses_today": losses, "flat_today": flat, "rows": rows[-20:]}
    except Exception as exc:
        return {"ok": False, "source": "alpaca_orders", "broker_truth_sync_enabled": True, "error": str(exc), "today_realized_pnl": 0.0, "closed_trades_today": 0, "broker_exit_fills_today": 0, "rows": []}

def _p246_live_unrealized_pnl_truth() -> dict:
    rows = []
    total = 0.0
    source = "broker_positions_detail"
    try:
        positions = list(list_open_positions_details_allowed() or [])
        for pos in positions:
            row = dict(pos or {})
            sym = str(row.get("symbol") or "").upper()
            unreal = _safe_float(row.get("unrealized_pl"), 0.0)
            total += unreal
            rows.append({
                "symbol": sym,
                "qty": row.get("qty"),
                "avg_entry_price": row.get("avg_entry_price"),
                "last_price": row.get("current_price") or row.get("last_price"),
                "market_value": row.get("market_value"),
                "unrealized_pl": round(unreal, 4),
                "unrealized_plpc": row.get("unrealized_plpc"),
            })
        return {
            "ok": True,
            "source": source,
            "open_position_count": len(rows),
            "today_unrealized_pnl": round(total, 4),
            "rows": rows,
        }
    except Exception as exc:
        return {
            "ok": False,
            "source": source,
            "error": str(exc),
            "open_position_count": 0,
            "today_unrealized_pnl": 0.0,
            "rows": [],
        }

def today_pnl_truth_snapshot() -> dict:
    account_pnl = _account_daily_pnl_snapshot()
    broker_realized = _today_realized_pnl_from_broker_orders()
    broker_strategy_sync = _sync_broker_realized_rows_to_strategy_performance(broker_realized)
    strategy_realized = _today_realized_pnl_from_strategy_state()
    deduped_strategy_realized = _p254_broker_preferred_today_strategy_realized_pnl()

    broker_calc_count = int(broker_realized.get("closed_trades_today") or 0)
    deduped_count = int(deduped_strategy_realized.get("closed_trades_today") or 0)
    strategy_count = int(strategy_realized.get("closed_trades_today") or 0)

    if bool(BROKER_ONLY_DAILY_LOSS_TRUTH_ENABLED) and broker_realized.get("ok") and broker_calc_count > 0:
        realized = broker_realized
        accounting_source = "alpaca_orders_broker_only_daily_loss_truth"
    elif broker_realized.get("ok") and broker_calc_count > 0:
        realized = broker_realized
        accounting_source = "alpaca_orders"
    elif deduped_strategy_realized.get("ok") and deduped_count > 0:
        realized = deduped_strategy_realized
        accounting_source = "strategy_performance_state_broker_preferred_deduped"
    elif strategy_realized.get("ok") and strategy_count > 0 and not bool(WORKER_EXIT_SHADOW_QUARANTINE_ENABLED):
        realized = strategy_realized
        accounting_source = "strategy_performance_state_legacy_worker_exit_included"
    else:
        realized = broker_realized if broker_realized.get("ok") else deduped_strategy_realized
        accounting_source = realized.get("source") or "broker_or_broker_preferred_no_worker_shadow"

    unrealized_truth = _p246_live_unrealized_pnl_truth()
    unrealized = _safe_float(unrealized_truth.get("today_unrealized_pnl"), 0.0)
    unrealized_error = str(unrealized_truth.get("error") or "")
    realized_value = _safe_float(realized.get("today_realized_pnl"), 0.0)

    return {
        "ok": bool(realized.get("ok", True)),
        "accounting_source": accounting_source,
        "broker_truth_sync_enabled": bool(broker_realized.get("broker_truth_sync_enabled", True)),
        "account_daily_pnl_source": account_pnl.get("source"),
        "account_daily_pnl": account_pnl.get("account_daily_pnl"),
        "account_daily_pnl_pct": account_pnl.get("account_daily_pnl_pct"),
        "account_equity": account_pnl.get("equity"),
        "account_last_equity": account_pnl.get("last_equity"),
        "account_pnl_ok": bool(account_pnl.get("ok")),
        "today_realized_pnl": round(realized_value, 4),
        "today_unrealized_pnl": round(unrealized, 4),
        "today_net_pnl": round(realized_value + unrealized, 4),
        "strategy_attribution_pnl": round(realized_value + unrealized, 4),
        "daily_goal_progress": _p295_broker_daily_goal_progress({
            "account_daily_pnl": account_pnl.get("account_daily_pnl"),
            "today_net_pnl": round(realized_value + unrealized, 4),
            "today_realized_pnl": round(realized_value, 4),
            "today_unrealized_pnl": round(unrealized, 4),
        }),
        "closed_trades_today": int(realized.get("closed_trades_today") or 0),
        "raw_strategy_closed_rows_today": int(deduped_strategy_realized.get("raw_closed_rows_today") or strategy_count),
        "duplicate_worker_rows_removed": int(deduped_strategy_realized.get("duplicate_worker_rows_removed") or 0),
        "duplicate_adjustment": deduped_strategy_realized.get("duplicate_adjustment"),
        "broker_only_daily_loss_truth_enabled": bool(BROKER_ONLY_DAILY_LOSS_TRUTH_ENABLED),
        "worker_exit_shadow_quarantine_enabled": bool(WORKER_EXIT_SHADOW_QUARANTINE_ENABLED),
        "worker_exit_shadow_quarantined_rows_today": int(deduped_strategy_realized.get("worker_exit_shadow_quarantined_rows_today") or 0),
        "shadow_worker_exit_estimate_pnl": deduped_strategy_realized.get("shadow_worker_exit_estimate_pnl"),
        "broker_exit_fills_today": int(broker_realized.get("broker_exit_fills_today") or deduped_strategy_realized.get("broker_reconciled_rows_today") or 0),
        "wins_today": int(realized.get("wins_today") or 0),
        "losses_today": int(realized.get("losses_today") or 0),
        "flat_today": int(realized.get("flat_today") or 0),
        "unrealized_source": unrealized_truth.get("source") or "broker_positions_detail",
        "unrealized_truth": unrealized_truth,
        "unrealized_error": unrealized_error,
        "account_pnl": account_pnl,
        "sample_rows": list(realized.get("rows") or []),
        "strategy_state_today": strategy_realized,
        "deduped_strategy_state_today": deduped_strategy_realized,
        "broker_orders_today": broker_realized,
        "broker_strategy_sync": broker_strategy_sync,
        "error": str(realized.get("error") or ""),
    }

def _p295_broker_daily_goal_progress(pnl_truth: dict | None = None) -> dict:
    pnl = dict(pnl_truth or today_pnl_truth_snapshot() or {})
    account_daily = pnl.get("account_daily_pnl")
    attribution = _safe_float(pnl.get("today_net_pnl"), 0.0)
    low = float(SWING_PROFIT_MODEL_DAILY_TARGET_LOW or 100.0)
    high = float(SWING_PROFIT_MODEL_DAILY_TARGET_HIGH or 200.0)

    broker_available = account_daily not in (None, "")
    broker_value = _safe_float(account_daily, 0.0) if broker_available else None
    primary = broker_value if broker_available and bool(SWING_BROKER_DAILY_GOAL_TRUTH_ENABLED) else attribution
    source = "broker_account_daily_change" if broker_available and bool(SWING_BROKER_DAILY_GOAL_TRUTH_ENABLED) else "strategy_realized_plus_unrealized"

    remaining_low = None if primary is None else max(0.0, low - float(primary))
    remaining_high = None if primary is None else max(0.0, high - float(primary))

    return {
        "enabled": bool(SWING_BROKER_DAILY_GOAL_TRUTH_ENABLED),
        "primary_source": source,
        "primary_daily_pnl": round(float(primary), 4) if primary is not None else None,
        "broker_account_daily_pnl": round(float(broker_value), 4) if broker_value is not None else None,
        "strategy_realized_plus_unrealized": round(float(attribution), 4),
        "today_realized_pnl": pnl.get("today_realized_pnl"),
        "today_unrealized_pnl": pnl.get("today_unrealized_pnl"),
        "target_low": round(low, 2),
        "target_high": round(high, 2),
        "progress_to_low_pct": round((float(primary) / low) * 100.0, 2) if primary is not None and low > 0 else None,
        "progress_to_high_pct": round((float(primary) / high) * 100.0, 2) if primary is not None and high > 0 else None,
        "remaining_to_low": round(remaining_low, 4) if remaining_low is not None else None,
        "remaining_to_high": round(remaining_high, 4) if remaining_high is not None else None,
        "low_target_hit": bool(primary is not None and float(primary) >= low),
        "high_target_hit": bool(primary is not None and float(primary) >= high),
        "note": "Use broker/account daily change for the operator daily goal; realized+unrealized remains strategy attribution.",
    }


def _p228_dt_utc(ts: object):
    try:
        text = str(ts or "").strip()
        if not text:
            return None
        dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return None


def _p228_delta_sec(a: object, b: object) -> float | None:
    da = _p228_dt_utc(a)
    db = _p228_dt_utc(b)
    if not da or not db:
        return None
    return abs((da - db).total_seconds())


def _p228_norm_strategy_row(row: dict | None) -> dict:
    row = dict(row or {})
    reason = str(row.get("reason") or row.get("exit_reason") or "")
    source = str(row.get("source") or "")
    return {
        "symbol": str(row.get("symbol") or "").upper(),
        "strategy_name": str(row.get("strategy_name") or row.get("signal") or ""),
        "ts_utc": str(row.get("ts_utc") or ""),
        "qty": round(abs(_safe_float(row.get("qty"), 0.0)), 4),
        "entry_price": round(_safe_float(row.get("entry_price"), 0.0), 4) if _safe_float(row.get("entry_price"), 0.0) > 0 else None,
        "exit_price": round(_safe_float(row.get("exit_price"), 0.0), 4) if _safe_float(row.get("exit_price"), 0.0) > 0 else None,
        "gross_pnl": round(_safe_float(row.get("gross_pnl"), 0.0), 4),
        "pnl_r": round(_safe_float(row.get("pnl_r"), 0.0), 4),
        "reason": reason,
        "source": source,
        "exit_order_id": str(row.get("exit_order_id") or ""),
        "entry_order_id": str(row.get("entry_order_id") or ""),
        "holding_days": row.get("holding_days"),
        "holding_period": _p175_holding_bucket(row),
        "recovered": bool(row.get("recovered")),
        "attribution_source": row.get("attribution_source"),
        "broker_reconciled": bool(row.get("broker_reconciled")) or source == "alpaca_orders_reconciled",
    }


def _p228_norm_broker_row(row: dict | None) -> dict:
    row = dict(row or {})
    return {
        "symbol": str(row.get("symbol") or "").upper(),
        "ts_utc": str(row.get("ts_utc") or ""),
        "qty": round(abs(_safe_float(row.get("qty"), 0.0)), 4),
        "entry_price": round(_safe_float(row.get("entry_price"), 0.0), 4) if _safe_float(row.get("entry_price"), 0.0) > 0 else None,
        "exit_price": round(_safe_float(row.get("exit_price"), 0.0), 4) if _safe_float(row.get("exit_price"), 0.0) > 0 else None,
        "gross_pnl": round(_safe_float(row.get("gross_pnl"), 0.0), 4),
        "calc_ok": bool(row.get("calc_ok")),
        "exit_order_id": str(row.get("exit_order_id") or ""),
        "entry_order_id": str(row.get("entry_order_id") or ""),
        "source": str(row.get("source") or "alpaca_orders"),
    }


def _p228_today_strategy_rows(perf_state: dict | None = None) -> list[dict]:
    state = perf_state if isinstance(perf_state, dict) else dict(STRATEGY_PERFORMANCE_STATE or {})
    session = _session_boundary_snapshot()
    today = str((session or {}).get("today_ny") or "")
    rows = []
    for raw in list((state or {}).get("closed_trades") or []):
        if not isinstance(raw, dict):
            continue
        ts = str(raw.get("ts_utc") or "")
        if today and _ny_date_from_iso(ts) != today:
            continue
        rows.append(_p228_norm_strategy_row(raw))
    return rows


def _p228_same_exit(a: dict, b: dict, max_delta_sec: int = 300) -> bool:
    if str(a.get("symbol") or "").upper() != str(b.get("symbol") or "").upper():
        return False
    aid = str(a.get("exit_order_id") or "").strip()
    bid = str(b.get("exit_order_id") or "").strip()
    if aid and bid and aid == bid:
        return True
    delta = _p228_delta_sec(a.get("ts_utc"), b.get("ts_utc"))
    if delta is None or delta > max_delta_sec:
        return False
    aq = _safe_float(a.get("qty"), 0.0)
    bq = _safe_float(b.get("qty"), 0.0)
    return aq <= 0 or bq <= 0 or abs(aq - bq) <= max(0.01, 0.02 * max(aq, bq))


def _p228_find_match(row: dict, candidates: list[dict], used: set[int] | None = None) -> tuple[int | None, dict | None]:
    used = used or set()
    best_i = None
    best_row = None
    best_delta = None
    for i, candidate in enumerate(candidates):
        if i in used:
            continue
        if not _p228_same_exit(row, candidate):
            continue
        delta = _p228_delta_sec(row.get("ts_utc"), candidate.get("ts_utc"))
        delta = 0.0 if delta is None else delta
        if best_delta is None or delta < best_delta:
            best_i = i
            best_row = candidate
            best_delta = delta
    return best_i, best_row


def _p228_bucket_losses(rows: list[dict], key_fn) -> list[dict]:
    buckets: dict[str, dict] = {}
    for row in rows:
        name = str(key_fn(row) or "unknown")
        bucket = buckets.setdefault(name, {"name": name, "closed_trades": 0, "gross_pnl": 0.0, "losses": 0, "wins": 0, "flat": 0})
        pnl = _safe_float(row.get("gross_pnl"), 0.0)
        bucket["closed_trades"] += 1
        bucket["gross_pnl"] += pnl
        if pnl > 0:
            bucket["wins"] += 1
        elif pnl < 0:
            bucket["losses"] += 1
        else:
            bucket["flat"] += 1
    out = []
    for bucket in buckets.values():
        bucket["gross_pnl"] = round(float(bucket.get("gross_pnl") or 0.0), 4)
        out.append(bucket)
    return sorted(out, key=lambda r: float(r.get("gross_pnl") or 0.0))
    
def _p229_realized_closed_trade_loss_halt(pnl_truth: dict | None = None) -> dict:
    """Read-only closed-trade realized loss halt for entry admission.

    This deliberately blocks new entries only. It does not disable exits, does
    not activate bulk flatten, and does not mutate DAILY_HALT_STATE.
    """
    try:
        pnl = dict(pnl_truth or today_pnl_truth_snapshot())
        broker_orders = dict(pnl.get("broker_orders_today") or {})
        rows = [_p228_norm_broker_row(r) for r in list(broker_orders.get("rows") or [])]
        calc_rows = [r for r in rows if r.get("calc_ok")]
        realized = round(sum(_safe_float(r.get("gross_pnl"), 0.0) for r in calc_rows), 4)
        daily_stop = abs(_configured_daily_stop_dollars_safe())
        daily_loss = abs(_configured_daily_loss_limit_safe())
        stop_breached = bool(daily_stop > 0 and realized <= -daily_stop)
        loss_breached = bool(daily_loss > 0 and realized <= -daily_loss)
        active = bool(stop_breached or loss_breached)
        reasons = []
        if stop_breached:
            reasons.append("realized_closed_trade_daily_stop_breached")
        if loss_breached:
            reasons.append("realized_closed_trade_daily_loss_breached")
        return {
            "ok": True,
            "active": active,
            "new_entries_blocked": active,
            "exits_still_permitted": True,
            "bulk_flatten_allowed": False,
            "can_flatten": False,
            "reason": reasons[0] if reasons else "none",
            "reasons": reasons,
            "realized_closed_trade_pnl": realized,
            "calc_closed_trades_today": len(calc_rows),
            "broker_exit_fills_today": int(broker_orders.get("broker_exit_fills_today") or len(rows)),
            "configured_daily_stop_dollars": daily_stop,
            "configured_daily_loss_limit": daily_loss,
            "source": "broker_orders_today_calc_rows",
        }
    except Exception as exc:
        return {
            "ok": False,
            "active": False,
            "new_entries_blocked": False,
            "exits_still_permitted": True,
            "bulk_flatten_allowed": False,
            "can_flatten": False,
            "reason": "realized_closed_trade_halt_unavailable",
            "reasons": ["realized_closed_trade_halt_unavailable"],
            "error": str(exc),
        }


def realized_closed_trade_loss_halt_active(pnl_truth: dict | None = None) -> bool:
    return bool(_p229_realized_closed_trade_loss_halt(pnl_truth=pnl_truth).get("active"))


def _loss_cluster_report(perf_state: dict | None = None, pnl_truth: dict | None = None, halt_truth: dict | None = None) -> dict:
    pnl = dict(pnl_truth or today_pnl_truth_snapshot())
    halt = dict(halt_truth or daily_halt_truth_snapshot())
    strategy_rows = _p228_today_strategy_rows(perf_state=perf_state)
    worker_rows = [r for r in strategy_rows if str(r.get("source") or "") == "worker_exit"]
    broker_fill_rows = [
        r for r in strategy_rows
        if str(r.get("source") or "") == "alpaca_orders_reconciled" or str(r.get("reason") or "") == "broker_exit_fill"
    ]
    broker_rows = [_p228_norm_broker_row(r) for r in list(dict(pnl.get("broker_orders_today") or {}).get("rows") or [])]

    duplicate_pairs = []
    used_broker_fill = set()
    for worker in worker_rows:
        idx, fill = _p228_find_match(worker, broker_fill_rows, used_broker_fill)
        if fill is None:
            continue
        used_broker_fill.add(int(idx))
        duplicate_pairs.append({
            "symbol": worker.get("symbol"),
            "worker_ts_utc": worker.get("ts_utc"),
            "broker_fill_ts_utc": fill.get("ts_utc"),
            "delta_sec": _p228_delta_sec(worker.get("ts_utc"), fill.get("ts_utc")),
            "qty_worker": worker.get("qty"),
            "qty_broker_fill": fill.get("qty"),
            "worker_gross_pnl": worker.get("gross_pnl"),
            "broker_fill_gross_pnl": fill.get("gross_pnl"),
            "exit_order_id": fill.get("exit_order_id") or worker.get("exit_order_id"),
            "classification": "duplicate_economic_exit",
        })

    matched_worker_ids = {(p.get("symbol"), p.get("worker_ts_utc")) for p in duplicate_pairs}
    matched_fill_ids = {(p.get("symbol"), p.get("broker_fill_ts_utc")) for p in duplicate_pairs}
    economic_rows = []

    used_worker = set()
    used_fill = set()
    for broker in broker_rows:
        wi, worker = _p228_find_match(broker, worker_rows, used_worker)
        fi, fill = _p228_find_match(broker, broker_fill_rows, used_fill)
        if wi is not None:
            used_worker.add(int(wi))
        if fi is not None:
            used_fill.add(int(fi))

        worker = dict(worker or {})
        fill = dict(fill or {})
        preferred = dict(broker)
        basis = "broker_order_calc" if broker.get("calc_ok") else "missing_broker_entry_basis"

        if not broker.get("calc_ok") and fill:
            preferred = dict(fill)
            basis = "broker_reconciled_strategy_estimate"
        elif not broker.get("calc_ok") and worker:
            preferred = dict(worker)
            basis = "worker_exit_estimate"
        elif broker.get("calc_ok"):
            attribution = worker or fill
            if attribution:
                preferred["strategy_name"] = attribution.get("strategy_name") or preferred.get("strategy_name") or "unknown"
                preferred["signal"] = attribution.get("signal") or attribution.get("strategy_name") or preferred.get("signal")
                preferred["reason"] = attribution.get("reason") or attribution.get("exit_reason") or preferred.get("reason") or "broker_exit_fill"
                preferred["exit_reason"] = attribution.get("exit_reason") or attribution.get("reason") or preferred.get("exit_reason") or preferred.get("reason")
                preferred["holding_days"] = attribution.get("holding_days")
                preferred["holding_period"] = attribution.get("holding_period") or _p175_holding_bucket(attribution)
                preferred["recovered"] = bool(attribution.get("recovered"))
                preferred["attribution_source"] = attribution.get("attribution_source")
                preferred["pnl_r"] = attribution.get("pnl_r")

        preferred["preferred_basis"] = basis
        preferred["paired_worker_exit"] = bool(worker)
        preferred["paired_broker_fill"] = bool(fill)
        economic_rows.append(preferred)

    for i, fill in enumerate(broker_fill_rows):
        if i in used_fill or (fill.get("symbol"), fill.get("ts_utc")) in matched_fill_ids:
            continue
        fill = dict(fill)
        fill["preferred_basis"] = "unmatched_broker_reconciled_strategy_row"
        economic_rows.append(fill)

    for i, worker in enumerate(worker_rows):
        if i in used_worker or (worker.get("symbol"), worker.get("ts_utc")) in matched_worker_ids:
            continue
        worker = dict(worker)
        worker["preferred_basis"] = "unmatched_worker_exit"
        economic_rows.append(worker)

    broker_calc_rows = [r for r in broker_rows if r.get("calc_ok")]
    missing_basis_rows = [r for r in broker_rows if not r.get("calc_ok")]
    strategy_total = round(sum(_safe_float(r.get("gross_pnl"), 0.0) for r in strategy_rows), 4)
    broker_calc_total = round(sum(_safe_float(r.get("gross_pnl"), 0.0) for r in broker_calc_rows), 4)
    adjusted_total = round(sum(_safe_float(r.get("gross_pnl"), 0.0) for r in economic_rows), 4)
    duplicate_overstatement = round(strategy_total - adjusted_total, 4)
    closed_trade_stop = abs(_safe_float(halt.get("configured_daily_stop_dollars") or pnl.get("configured_daily_stop_dollars"), 0.0))
    closed_trade_loss_limit = abs(_safe_float(halt.get("configured_daily_loss_limit"), 0.0))
    closed_trade_breach = bool((closed_trade_stop > 0 and adjusted_total <= -closed_trade_stop) or (closed_trade_loss_limit > 0 and adjusted_total <= -closed_trade_loss_limit))
    account_daily_pnl = halt.get("account_daily_pnl", pnl.get("account_daily_pnl"))
    realized_halt = _p229_realized_closed_trade_loss_halt(pnl_truth=pnl)

    recommended_actions = ["do_not_shut_off_trading", "do_not_enable_intraday_live", "do_not_size_up"]
    if duplicate_pairs:
        recommended_actions.append("dedupe_strategy_state_realized_exit_reporting")
    if missing_basis_rows:
        recommended_actions.append("backfill_missing_broker_entry_basis")
    if closed_trade_breach and not bool(halt.get("daily_halt_active")):
        recommended_actions.append("add_realized_closed_trade_loss_halt_check")
    if _p228_bucket_losses(economic_rows, lambda r: str(r.get("reason") or r.get("preferred_basis") or "unknown")):
        recommended_actions.append("review_stall_exit_tightening_before_risk_scale")

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "read_only_forensic_report",
        "summary": {
            "strategy_state_realized_pnl": strategy_total,
            "strategy_state_closed_rows": len(strategy_rows),
            "broker_calc_realized_pnl": broker_calc_total,
            "broker_calc_closed_rows": len(broker_calc_rows),
            "broker_exit_fills": len(broker_rows),
            "missing_broker_entry_basis_count": len(missing_basis_rows),
            "duplicate_pair_count": len(duplicate_pairs),
            "duplicate_adjusted_realized_pnl": adjusted_total,
            "duplicate_overstatement": duplicate_overstatement,
            "account_daily_pnl": account_daily_pnl,
            "daily_halt_active": bool(halt.get("daily_halt_active")),
            "closed_trade_realized_halt_breached": closed_trade_breach,
            "realized_closed_trade_loss_halt_active": bool(realized_halt.get("active")),
            "realized_closed_trade_loss_halt_reason": realized_halt.get("reason"),
            "trust_assessment": "strategy_state_duplicate_accounting_suspect" if duplicate_pairs else "no_duplicate_pairs_detected",
        },
        "broker_realized_exits_today": broker_rows,
        "worker_exit_rows_today": worker_rows,
        "broker_exit_fill_rows_today": broker_fill_rows,
        "duplicate_pairs": duplicate_pairs,
        "duplicate_adjusted_economic_exits": economic_rows,
        "missing_entry_basis_rows": missing_basis_rows,
        "losses_by_symbol": _p228_bucket_losses(economic_rows, lambda r: str(r.get("symbol") or "unknown").upper()),
        "losses_by_strategy": _p228_bucket_losses(economic_rows, lambda r: str(r.get("strategy_name") or "unknown")),
        "losses_by_exit_reason": _p228_bucket_losses(economic_rows, lambda r: str(r.get("reason") or r.get("preferred_basis") or "unknown")),
        "losses_by_holding_period": _p228_bucket_losses(economic_rows, lambda r: str(r.get("holding_period") or "unknown")),
        "losses_by_recovered": _p228_bucket_losses(economic_rows, lambda r: "recovered" if r.get("recovered") else "not_recovered"),
        "halt_comparison": {
            "account_daily_pnl": account_daily_pnl,
            "account_daily_pnl_source": pnl.get("account_daily_pnl_source"),
            "duplicate_adjusted_realized_pnl": adjusted_total,
            "configured_daily_stop_dollars": halt.get("configured_daily_stop_dollars"),
            "configured_daily_loss_limit": halt.get("configured_daily_loss_limit"),
            "daily_halt_active": bool(halt.get("daily_halt_active")),
            "daily_halt_reason": halt.get("daily_halt_reason"),
            "closed_trade_realized_halt_breached": closed_trade_breach,
            "realized_closed_trade_loss_halt": realized_halt,
        },
        "recommended_actions": recommended_actions,
    }

def daily_halt_truth_snapshot() -> dict:
    try:
        configured_daily_loss_limit = _configured_daily_loss_limit_safe()
        configured_daily_stop_dollars = _configured_daily_stop_dollars_safe()
        pnl_truth = today_pnl_truth_snapshot()
        account_pnl = _account_daily_pnl_snapshot()
        acct_daily_pnl = account_pnl.get("account_daily_pnl") if account_pnl.get("ok") else daily_pnl()
        realized_halt = _p229_realized_closed_trade_loss_halt(pnl_truth=pnl_truth)
        halt_active = bool(daily_halt_active() or realized_halt.get("active"))
        trigger = "none"
        trigger_detail = "No daily halt is active."
        if bool(realized_halt.get("active")) and not bool(daily_halt_active()):
            trigger = realized_halt.get("reason") or "realized_closed_trade_loss_halt"
            trigger_detail = f"Broker-calculated closed-trade realized P&L {float(realized_halt.get('realized_closed_trade_pnl') or 0.0):.2f} breached the realized-loss entry halt. Exits remain permitted; bulk flatten is not enabled."
        if halt_active:
            net_today = _safe_float(pnl_truth.get("today_net_pnl"), 0.0)
            if configured_daily_stop_dollars > 0 and acct_daily_pnl is not None and float(acct_daily_pnl) <= -abs(configured_daily_stop_dollars):
                trigger = "daily_stop_dollars"
                trigger_detail = f"Account equity daily P&L {float(acct_daily_pnl):.2f} is at/below -{abs(configured_daily_stop_dollars):.2f}."
            elif configured_daily_loss_limit > 0 and net_today <= -abs(configured_daily_loss_limit):
                trigger = "daily_loss_limit"
                trigger_detail = f"Today net P&L estimate {net_today:.2f} is at/below -{abs(configured_daily_loss_limit):.2f}."
            elif configured_daily_stop_dollars > 0 and net_today <= -abs(configured_daily_stop_dollars):
                trigger = "daily_stop_dollars_estimate"
                trigger_detail = f"Today net P&L estimate {net_today:.2f} is at/below -{abs(configured_daily_stop_dollars):.2f}."
            else:
                trigger = "manual_or_persisted_halt"
                trigger_detail = "Daily halt is active, but configured P&L thresholds were not proven by available diagnostics."
        return {"ok": True, "daily_halt_active": halt_active, "daily_halt_reason": trigger, "daily_halt_detail": trigger_detail, "configured_daily_loss_limit": configured_daily_loss_limit, "configured_daily_stop_dollars": configured_daily_stop_dollars, "account_daily_pnl": round(float(acct_daily_pnl), 4) if acct_daily_pnl is not None else None, "account_pnl": account_pnl, "today_pnl_truth": pnl_truth, "realized_closed_trade_loss_halt": realized_halt}
    except Exception as exc:
        return {"ok": False, "daily_halt_active": bool(daily_halt_active()) if "daily_halt_active" in globals() else False, "daily_halt_reason": "halt_truth_unavailable", "daily_halt_detail": f"Daily halt truth failed safely: {exc}", "configured_daily_loss_limit": _configured_daily_loss_limit_safe(), "configured_daily_stop_dollars": _configured_daily_stop_dollars_safe(), "today_pnl_truth": {"ok": False, "error": str(exc), "today_realized_pnl": 0.0, "today_unrealized_pnl": 0.0, "today_net_pnl": 0.0}}


def _loss_control_incident_summary(
    *,
    daily_halt_truth: dict | None = None,
    today_pnl_truth: dict | None = None,
    account_pnl: dict | None = None,
    flatten_decision: dict | None = None,
    snapshot: dict | None = None,
    reconcile_actions: list | None = None,
) -> dict:
    """Operator-facing incident summary for daily halt and loss-control events."""
    halt_truth = dict(daily_halt_truth or {})
    pnl_truth = dict(today_pnl_truth or halt_truth.get("today_pnl_truth") or {})
    acct_pnl = dict(account_pnl or pnl_truth.get("account_pnl") or halt_truth.get("account_pnl") or {})
    decision = dict(flatten_decision or {})
    snap = dict(snapshot or read_positions_snapshot() or {})
    snap_extra = snap.get("extra") if isinstance(snap.get("extra"), dict) else {}
    if not decision:
        decision = dict((snap_extra or {}).get("daily_stop_flatten_decision") or {})
    positions = list(snap.get("positions") or [])
    active_plans = dict(snap.get("active_plans") or {})
    try:
        open_order_count = len(list_open_orders_safe())
    except Exception:
        open_order_count = int(snap.get("open_order_count") or 0)

    account_daily_pnl = acct_pnl.get("account_daily_pnl")
    if account_daily_pnl is None:
        account_daily_pnl = pnl_truth.get("account_daily_pnl")
    account_daily_pnl = _safe_float(account_daily_pnl, 0.0) if account_daily_pnl not in (None, "") else None
    today_net_pnl = _safe_float(pnl_truth.get("today_net_pnl"), 0.0)
    daily_stop = _configured_daily_stop_dollars_safe()
    daily_loss = _configured_daily_loss_limit_safe()
    halt_active = bool(halt_truth.get("daily_halt_active") or daily_halt_active())
    fully_flat = len(positions) == 0 and len(active_plans) == 0 and int(open_order_count or 0) == 0

    breach_source = "none"
    breach_value = None
    if account_daily_pnl is not None and daily_stop > 0 and account_daily_pnl <= -abs(daily_stop):
        breach_source = "alpaca_account_daily_pnl"
        breach_value = round(account_daily_pnl, 4)
    elif daily_loss > 0 and today_net_pnl <= -abs(daily_loss):
        breach_source = "strategy_or_order_today_net_pnl"
        breach_value = round(today_net_pnl, 4)
    elif daily_stop > 0 and today_net_pnl <= -abs(daily_stop):
        breach_source = "strategy_or_order_today_net_pnl_vs_daily_stop"
        breach_value = round(today_net_pnl, 4)

    recommended = []
    if halt_active:
        recommended.append("remain_halted_until_next_session")
    if not fully_flat:
        recommended.append("verify_open_positions_and_orders")
    if account_daily_pnl is not None and abs(account_daily_pnl - today_net_pnl) > max(25.0, abs(account_daily_pnl) * 0.10):
        recommended.append("reconcile_broker_realized_pnl_gap")
    if not bool(decision.get("can_flatten")):
        recommended.append("do_not_bulk_flatten_without_explicit_policy")
    if not recommended:
        recommended.append("monitor")

    return {
        "ok": True,
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "ts_ny": now_ny().isoformat(),
        "active": halt_active,
        "session": str((DAILY_HALT_STATE or {}).get("session") or ""),
        "triggered_at": str((DAILY_HALT_STATE or {}).get("triggered_at") or ""),
        "daily_halt_reason": str(halt_truth.get("daily_halt_reason") or (DAILY_HALT_STATE or {}).get("reason") or "none"),
        "daily_halt_detail": str(halt_truth.get("daily_halt_detail") or ""),
        "configured_daily_stop_dollars": daily_stop,
        "configured_daily_loss_limit": daily_loss,
        "account_daily_pnl": round(account_daily_pnl, 4) if account_daily_pnl is not None else None,
        "account_daily_pnl_pct": acct_pnl.get("account_daily_pnl_pct") or pnl_truth.get("account_daily_pnl_pct"),
        "account_equity": acct_pnl.get("equity") or pnl_truth.get("account_equity"),
        "account_last_equity": acct_pnl.get("last_equity") or pnl_truth.get("account_last_equity"),
        "today_net_pnl_estimate": round(today_net_pnl, 4),
        "today_realized_pnl_estimate": pnl_truth.get("today_realized_pnl"),
        "broker_exit_fills_today": pnl_truth.get("broker_exit_fills_today"),
        "closed_trades_today": pnl_truth.get("closed_trades_today"),
        "breach_source": breach_source,
        "breach_value": breach_value,
        "flatten_policy": decision.get("action") or _daily_stop_action(),
        "bulk_flatten_allowed": bool(decision.get("allow_bulk_flatten", globals().get("ALLOW_DAILY_STOP_BULK_FLATTEN", False))),
        "can_flatten": bool(decision.get("can_flatten", False)),
        "flatten_decision_reasons": list(decision.get("reasons") or []),
        "snapshot_reason": snap.get("reason") or "",
        "snapshot_ts_utc": snap.get("ts_utc") or "",
        "broker_positions_count": len(positions),
        "active_plan_count": len(active_plans),
        "open_order_count": int(open_order_count or 0),
        "fully_flat": fully_flat,
        "reconcile_action_count": len(list(reconcile_actions or [])),
        "recommended_actions": recommended,
        "recommended_action": recommended[0],
    }


def risk_limits_ok() -> bool:
    return (not KILL_SWITCH) and (not daily_halt_active()) and (not daily_stop_hit())


def require_admin(request: Request):
    if not ADMIN_SECRET:
        raise HTTPException(status_code=403, detail="ADMIN_SECRET not set")
    got = request.headers.get("x-admin-secret", "").strip()
    if got != ADMIN_SECRET:
        raise HTTPException(status_code=401, detail="Invalid admin secret")
      

def require_admin_if_configured(request: Request):
    """Legacy no-op auth shim for non-/admin routes.

    Patch 095 narrows ADMIN_SECRET enforcement to explicit /admin routes only.
    Existing call sites can remain in place without forcing header auth on
    dashboards and read-only diagnostics.
    """
    return None


def flatten_all(reason: str) -> list[dict]:
    results = []
    for p in list_open_positions_allowed():
        sym = p["symbol"]
        out = close_position(sym, reason=reason, source="risk_guard")
        if sym in TRADE_PLAN:
            TRADE_PLAN[sym]["active"] = False
        results.append({"symbol": sym, "action": "flatten", "reason": reason, **out})
    return results




# =============================
# Scanner helpers (server-side signal evaluation)
# =============================
def _session_key(dt_ny: datetime) -> str:
    return dt_ny.strftime("%Y-%m-%d")



def _dedupe_keep_order(items: list[str]) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    for s in items or []:
        sym = str(s or "").strip().upper()
        if not sym or sym in seen:
            continue
        seen.add(sym)
        out.append(sym)
    return out

def _p295_csv_symbols(value: object, limit: int | None = None) -> list[str]:
    raw = str(value or "")
    symbols = _dedupe_keep_order([s.strip().upper() for s in raw.split(",") if s.strip()])
    if limit is not None:
        symbols = symbols[:max(0, int(limit or 0))]
    return symbols


def _p295_swing_pilot_symbols() -> list[str]:
    if not bool(SWING_PILOT_UNIVERSE_ENABLED):
        return []
    return _p295_csv_symbols(
        SWING_PILOT_UNIVERSE_SYMBOLS,
        limit=max(0, int(SWING_PILOT_UNIVERSE_MAX_SYMBOLS or 0)),
    )


def _p295_defensive_relaxation_pilot_symbols() -> list[str]:
    return _p295_csv_symbols(SWING_DEFENSIVE_RELAXATION_PILOT_SYMBOLS)


def _p295_apply_swing_pilot_symbols(symbols: list[str]) -> list[str]:
    base = _dedupe_keep_order([str(s).strip().upper() for s in list(symbols or []) if str(s).strip()])
    pilots = _p295_swing_pilot_symbols()
    if not pilots:
        return base
    max_total = max(len(base), int(SCANNER_MAX_SYMBOLS_PER_CYCLE or len(base) or 1))
    merged = _dedupe_keep_order(base + pilots)
    return merged[:max_total]


def _p296_defensive_relaxation_entries_today() -> dict:
    today = now_ny().date()
    entry_type = str(SWING_DEFENSIVE_RELAXATION_ENTRY_TYPE or "defensive_near_miss_relaxation").strip().lower()
    seen: set[str] = set()
    items = []

    for symbol, plan in (TRADE_PLAN or {}).items():
        p = dict(plan or {})
        if not bool(p.get("active")):
            continue
        dt = _parse_plan_opened_dt(p)
        if not dt or dt.date() != today:
            continue
        plan_entry_type = str(
            p.get("entry_type")
            or (p.get("thesis") or {}).get("entry_type")
            or ""
        ).strip().lower()
        if plan_entry_type != entry_type:
            continue
        key = f"plan:{str(symbol or '').upper()}:{dt.isoformat()}"
        if key in seen:
            continue
        seen.add(key)
        items.append({
            "source": "trade_plan",
            "symbol": str(symbol or "").upper(),
            "opened_at": dt.isoformat(),
            "entry_type": plan_entry_type,
        })

    events = list(PAPER_LIFECYCLE_HISTORY or [])
    if LAST_PAPER_LIFECYCLE and (not events or events[-1] != LAST_PAPER_LIFECYCLE):
        events.append(dict(LAST_PAPER_LIFECYCLE))
    for ev in events:
        row = dict(ev or {})
        if str(row.get("stage") or "").strip().lower() != "entry":
            continue
        if str(row.get("status") or "").strip().lower() not in {"planned", "submitted", "filled"}:
            continue
        try:
            ts = datetime.fromisoformat(str(row.get("ts_ny") or row.get("ts_utc") or ""))
            ts_ny = ts.astimezone(NY_TZ) if ts.tzinfo else ts.replace(tzinfo=timezone.utc).astimezone(NY_TZ)
        except Exception:
            continue
        if ts_ny.date() != today:
            continue
        details = dict(row.get("details") or {})
        event_entry_type = str(details.get("entry_type") or "").strip().lower()
        if event_entry_type != entry_type:
            continue
        symbol = str(row.get("symbol") or details.get("symbol") or "").upper()
        key = f"lifecycle:{symbol}:{ts_ny.isoformat()}"
        if key in seen:
            continue
        seen.add(key)
        items.append({
            "source": "paper_lifecycle",
            "symbol": symbol,
            "opened_at": ts_ny.isoformat(),
            "entry_type": event_entry_type,
        })

    return {
        "today_ny": today.isoformat(),
        "entry_type": entry_type,
        "count": len(items),
        "max_entries_per_day": int(SWING_DEFENSIVE_RELAXATION_MAX_ENTRIES_PER_DAY),
        "items": items[:20],
    }


def _p296_apply_defensive_relaxation_promotion(
    candidate: dict | None,
    global_block_reasons: list | None = None,
    *,
    daily_goal_progress: dict | None = None,
) -> dict:
    c = dict(candidate or {})
    symbol = str(c.get("symbol") or "").strip().upper()
    decision = _p294_defensive_near_miss_decision(c, global_block_reasons or [])
    c["defensive_near_miss_relaxation"] = decision

    blockers = []
    if not bool(SWING_DEFENSIVE_RELAXATION_LIVE_ENABLED):
        blockers.append("live_promotion_disabled")
    if not bool(decision.get("applies")):
        blockers.append(str(decision.get("reason") or "defensive_near_miss_not_applicable"))

    pilot_symbols = set(_p295_defensive_relaxation_pilot_symbols())
    if bool(SWING_DEFENSIVE_RELAXATION_PILOT_ONLY) and symbol not in pilot_symbols:
        blockers.append("symbol_not_in_defensive_relaxation_pilot")

    goal = dict(daily_goal_progress or _p295_broker_daily_goal_progress())
    if bool(SWING_DEFENSIVE_RELAXATION_REQUIRE_DAILY_GOAL_BELOW_LOW) and bool(goal.get("low_target_hit")):
        blockers.append("broker_daily_low_goal_already_hit")

    today = _p296_defensive_relaxation_entries_today()
    if int(today.get("count") or 0) >= max(0, int(SWING_DEFENSIVE_RELAXATION_MAX_ENTRIES_PER_DAY or 0)):
        blockers.append("defensive_relaxation_daily_slot_used")

    c["defensive_near_miss_live_promotion"] = {
        "enabled": bool(SWING_DEFENSIVE_RELAXATION_LIVE_ENABLED),
        "applies": len(blockers) == 0,
        "symbol": symbol,
        "pilot_only": bool(SWING_DEFENSIVE_RELAXATION_PILOT_ONLY),
        "pilot_symbols": sorted(pilot_symbols),
        "daily_goal_progress": goal,
        "daily_slot": today,
        "blockers": blockers,
        "decision": decision,
        "entry_type": str(SWING_DEFENSIVE_RELAXATION_ENTRY_TYPE or "defensive_near_miss_relaxation"),
    }

    if blockers:
        return c

    removable = {
        "target_profile_breakout_gate",
        "defensive_daily_breakout_rollback",
        "defensive_risk_per_share_too_wide",
        "weak_tape",
    }
    reasons = [
        str(r) for r in list(c.get("rejection_reasons") or [])
        if str(r) and str(r) not in removable
    ]
    c["rejection_reasons"] = _dedupe_candidate_reasons(reasons)
    c["eligible"] = len(c["rejection_reasons"]) == 0
    c["defensive_near_miss_relaxation_entry"] = True
    c["target_path_recovery_mode"] = True
    c["weak_tape_target_override"] = True
    c["entry_type"] = str(SWING_DEFENSIVE_RELAXATION_ENTRY_TYPE or "defensive_near_miss_relaxation")
    c["recovered_from_reasons"] = list(decision.get("original_rejection_reasons") or [])

    target_path = dict(c.get("target_path_profit") or {})
    target_path["defensive_near_miss_relaxation"] = True
    target_path["passed"] = True
    target_path["tier"] = "defensive_near_miss_relaxation"
    target_path["reason"] = "ma_pilot_defensive_near_miss_relaxation_promoted"
    c["target_path_profit"] = target_path
    c["target_path_score"] = target_path.get("score")

    c = _p291_apply_risk_adjusted_entry_sizing(
        c,
        sleeve=str(SWING_DEFENSIVE_RELAXATION_ENTRY_TYPE or "defensive_near_miss_relaxation"),
        risk_multiplier=SWING_DEFENSIVE_NEAR_MISS_LAB_RISK_MULTIPLIER,
    )
    return c


def _base_scanner_pool() -> list[str]:
    if SCANNER_POOL_SYMBOLS:
        return _dedupe_keep_order([s for s in SCANNER_POOL_SYMBOLS.split(",") if s.strip()])
    if SCANNER_UNIVERSE_SYMBOLS:
        return _dedupe_keep_order([s for s in SCANNER_UNIVERSE_SYMBOLS.split(",") if s.strip()])
    if ALLOWED_SYMBOLS:
        allowed = sorted(ALLOWED_SYMBOLS)
        if len(allowed) >= 15:
            return _dedupe_keep_order(allowed)
    return _dedupe_keep_order(DEFAULT_DYNAMIC_POOL)


def universe_symbols() -> list[str]:
    """Return the symbol universe for scanning.

    static: fixed configured list. Prefer SCANNER_UNIVERSE_SYMBOLS when present.
    env: explicit env-driven list.
    dynamic: ranked/fetched pool.
    Patch 295 appends a tiny swing pilot list, currently MA, without broadening rules.
    """
    if SCANNER_UNIVERSE_PROVIDER == "static":
        if SCANNER_UNIVERSE_SYMBOLS:
            syms = [s.strip().upper() for s in SCANNER_UNIVERSE_SYMBOLS.split(",") if s.strip()]
            if syms:
                return _p295_apply_swing_pilot_symbols(_dedupe_keep_order(syms)[:SCANNER_MAX_SYMBOLS_PER_CYCLE])
        return _p295_apply_swing_pilot_symbols(sorted(ALLOWED_SYMBOLS)[:SCANNER_MAX_SYMBOLS_PER_CYCLE])

    if SCANNER_UNIVERSE_PROVIDER == "env":
        raw = getenv_any("SCANNER_UNIVERSE_SYMBOLS", "SCANNER_SYMBOLS", default="")
        if not raw:
            return _p295_apply_swing_pilot_symbols(sorted(ALLOWED_SYMBOLS)[:SCANNER_MAX_SYMBOLS_PER_CYCLE])
        syms = [s.strip().upper() for s in raw.split(",") if s.strip()]
        return _p295_apply_swing_pilot_symbols(syms[:SCANNER_MAX_SYMBOLS_PER_CYCLE])

    if SCANNER_UNIVERSE_PROVIDER == "dynamic":
        base = _base_scanner_pool()
        top_n = max(1, int(SCANNER_DYNAMIC_TOP_N or SCANNER_MAX_SYMBOLS_PER_CYCLE or 20))
        fetch_n = min(len(base), max(top_n * 2, top_n))
        return _p295_apply_swing_pilot_symbols(base[:fetch_n])

    return _p295_apply_swing_pilot_symbols(sorted(ALLOWED_SYMBOLS)[:SCANNER_MAX_SYMBOLS_PER_CYCLE])

def _p407_runtime_rotation_seed(scan_options: dict | None = None) -> int:
    scan_options = dict(scan_options or {})
    raw = str(scan_options.get("rotation_seed") or scan_options.get("scan_reason") or "").strip()
    if raw:
        return abs(hash(raw)) % 100000

    now = now_ny()
    # Rotate during the session without adding persistent state.
    return int(now.strftime("%Y%m%d%H"))


def _p407_rotate_symbols(symbols: list[str], seed: int, take: int) -> list[str]:
    ordered = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(symbols or [])
        if str(sym or "").strip()
    ])
    if not ordered or take <= 0:
        return []
    offset = int(seed or 0) % len(ordered)
    rotated = ordered[offset:] + ordered[:offset]
    return rotated[: max(0, min(int(take or 0), len(rotated)))]


def _p407_runtime_rotation_slot_count(configured_max: int, protected_count: int, original_count: int) -> int:
    if configured_max <= 0 or original_count <= configured_max:
        return 0
    target = max(3, int(round(float(configured_max) * 0.16)))
    return max(1, min(target, max(1, int(configured_max) // 4)))

def _p419_runtime_coverage_preview_without_scan(limit: int = 100) -> dict:
    lim = max(1, min(int(limit or 100), 250))

    runtime_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(universe_symbols() or [])
        if str(sym or "").strip()
    ])

    preview = _p315_swing_runtime_scan_symbols(
        runtime_symbols,
        scan_options={
            "scan_reason": "runtime_coverage_preview_without_market_hours_scan",
            "max_symbols": int(SWING_RUNTIME_SLIM_MAX_SYMBOLS or 0),
        },
    )

    preview_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(preview.get("symbols") or [])
        if str(sym or "").strip()
    ])

    runtime_set = set(runtime_symbols)
    preview_set = set(preview_symbols)
    missing = [sym for sym in runtime_symbols if sym not in preview_set]
    extra = [sym for sym in preview_symbols if sym not in runtime_set]

    configured_max = max(1, int(SWING_RUNTIME_SLIM_MAX_SYMBOLS or 25))
    full_expected = bool(
        not bool(SWING_RUNTIME_SLIM_ENABLED)
        or configured_max >= len(runtime_symbols)
    )
    full_preview = bool(runtime_symbols and preview_symbols == runtime_symbols)

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "runtime_coverage_preview_without_market_hours_scan",
        "read_only": True,
        "does_not_fetch_bars": True,
        "does_not_submit_orders": True,
        "does_not_change_state": True,
        "runtime_symbol_count": len(runtime_symbols),
        "preview_symbol_count": len(preview_symbols),
        "coverage_pct": round((len(preview_set & runtime_set) / max(1, len(runtime_set))) * 100.0, 2),
        "matches_runtime": full_preview,
        "current_env": {
            "SWING_RUNTIME_SLIM_ENABLED": bool(SWING_RUNTIME_SLIM_ENABLED),
            "SWING_RUNTIME_SLIM_MAX_SYMBOLS": configured_max,
            "SCANNER_MAX_SYMBOLS_PER_CYCLE": int(SCANNER_MAX_SYMBOLS_PER_CYCLE or 0),
            "SCAN_RUNTIME_BUDGET_SEC": int(SCAN_RUNTIME_BUDGET_SEC or 0),
        },
        "full_coverage_expected_from_current_env": full_expected,
        "runtime_selector_preview": {
            "enabled": bool(preview.get("enabled")),
            "applied": bool(preview.get("applied")),
            "reason": preview.get("reason"),
            "configured_max_symbols": preview.get("configured_max_symbols"),
            "original_count": preview.get("original_count"),
            "excluded_count": preview.get("excluded_count"),
            "rotation_enabled": bool(preview.get("rotation_enabled")),
            "rotation_slots": int(preview.get("rotation_slots") or 0),
            "rotation_symbols": list(preview.get("rotation_symbols") or []),
            "protected_symbols": list(preview.get("protected_symbols") or []),
            "watch_symbols": list(preview.get("watch_symbols") or []),
            "active_symbols": list(preview.get("active_symbols") or []),
        },
        "runtime_symbols": runtime_symbols[:lim],
        "preview_symbols": preview_symbols[:lim],
        "missing_runtime_symbols": missing[:lim],
        "extra_preview_symbols": extra[:lim],
        "recommended_action": (
            "runtime_config_predicts_full_coverage_next_scan"
            if full_preview and full_expected
            else "runtime_config_still_predicts_partial_scan_review_envs"
            if full_expected and not full_preview
            else "runtime_slim_intentionally_predicts_subset"
        ),
    }

def _p407_candidate_coverage_opportunity_audit(limit: int = 25) -> dict:
    lim = max(1, min(int(limit or 25), 100))
    latest_scan, summary = _p298_latest_scan_summary_light()
    coverage = _p404_runtime_universe_coverage(latest_scan=latest_scan, summary=summary)
    runtime_slim = dict(summary.get("runtime_slim") or {})

    skipped = list(
        runtime_slim.get("excluded_symbols")
        or coverage.get("excluded_by_runtime_slim_symbols")
        or coverage.get("missing_runtime_symbols")
        or []
    )
    rotated_in = list(runtime_slim.get("rotation_symbols") or [])
    due_next = _p407_rotate_symbols(
        [sym for sym in skipped if sym not in set(rotated_in)],
        _p407_runtime_rotation_seed({"scan_reason": "candidate_coverage_opportunity_audit_next"}),
        max(1, int(runtime_slim.get("rotation_slots") or 4)),
    )

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "candidate_coverage_opportunity_audit",
        "source": "latest_scan_runtime_slim_summary",
        "runtime_universe_coverage": coverage,
        "runtime_slim": {
            "enabled": bool(runtime_slim.get("enabled")),
            "applied": bool(runtime_slim.get("applied")),
            "reason": runtime_slim.get("reason"),
            "configured_max_symbols": runtime_slim.get("configured_max_symbols"),
            "original_count": runtime_slim.get("original_count"),
            "scanned_count": len(runtime_slim.get("symbols") or []),
            "excluded_count": int(runtime_slim.get("excluded_count") or 0),
            "rotation_enabled": bool(runtime_slim.get("rotation_enabled")),
            "rotation_slots": int(runtime_slim.get("rotation_slots") or 0),
            "rotation_seed": runtime_slim.get("rotation_seed"),
        },
        "anchor_symbols": list(runtime_slim.get("anchor_symbols") or []),
        "active_symbols": list(runtime_slim.get("active_symbols") or []),
        "watch_symbols": list(runtime_slim.get("watch_symbols") or []),
        "rotation_symbols": rotated_in[:lim],
        "excluded_symbols": skipped[:lim],
        "symbols_due_next_rotation": due_next[:lim],
        "recommended_action": (
            "rerun_scan_to_confirm_new_runtime_env"
            if str(coverage.get("recommended_action") or "") == "rerun_scan_to_confirm_new_runtime_env"
            else "runtime_rotation_active_monitor_coverage"
            if bool(runtime_slim.get("rotation_enabled"))
            else "runtime_slim_not_rotating_review_scan_cap"
            if bool(runtime_slim.get("applied"))
            else "full_runtime_scanned"
        ),
    }

def _p315_swing_runtime_scan_symbols(all_symbols: list[str], scan_options: dict | None = None) -> dict:
    scan_options = dict(scan_options or {})
    original = _dedupe_keep_order([str(s or "").strip().upper() for s in list(all_symbols or []) if str(s or "").strip()])

    payload_max = 0
    try:
        payload_max = int(scan_options.get("max_symbols") or 0)
    except Exception:
        payload_max = 0

    configured_env_max = max(1, int(SWING_RUNTIME_SLIM_MAX_SYMBOLS or 25))
    configured_max_before_thrive = max(1, int(payload_max or configured_env_max))
    configured_max = configured_max_before_thrive
    min_original = max(1, int(SWING_RUNTIME_SLIM_MIN_ORIGINAL_SYMBOLS or 26))
    force_full_coverage = str(
        scan_options.get("force_full_coverage")
        or scan_options.get("full_coverage")
        or ""
    ).strip().lower() in {"1", "true", "yes", "y", "on"}

    thrive_fast_scan_applied = False
    if (
        bool(SWING_THRIVE_FAST_SCAN_ENABLED)
        and not force_full_coverage
        and len(original) >= min_original
    ):
        thrive_max = max(1, int(SWING_THRIVE_FAST_SCAN_MAX_SYMBOLS or configured_max))
        if thrive_max < configured_max:
            configured_max = thrive_max
            thrive_fast_scan_applied = True

    if (
        not bool(SWING_RUNTIME_SLIM_ENABLED)
        or len(original) < min_original
        or configured_max >= len(original)
    ):
        return {
            "enabled": bool(SWING_RUNTIME_SLIM_ENABLED),
            "applied": False,
            "reason": "runtime_slim_not_needed_or_disabled",
            "configured_max_symbols": configured_max,
            "configured_max_symbols_before_thrive": configured_max_before_thrive,
            "original_count": len(original),
            "symbols": original,
            "excluded_symbols": [],
            "watch_symbols": [],
            "thrive_fast_scan_enabled": bool(SWING_THRIVE_FAST_SCAN_ENABLED),
            "thrive_fast_scan_applied": bool(thrive_fast_scan_applied),
            "force_full_coverage": bool(force_full_coverage),
        }

    active_symbols = []
    try:
        active_symbols = [
            str(sym or "").strip().upper()
            for sym, plan in (TRADE_PLAN or {}).items()
            if str(sym or "").strip()
            and isinstance(plan, dict)
            and (
                bool(plan.get("active"))
                or _plan_is_pending_entry(plan)
                or str(plan.get("status") or "").strip().lower() in {"pending_entry", "submitted", "filled"}
            )
        ]
    except Exception:
        active_symbols = []

    previous_rows = [dict(r or {}) for r in list(LAST_SWING_CANDIDATES or []) if isinstance(r, dict)]
    previous_rows.sort(
        key=lambda r: (
            float(_safe_float(r.get("rank_score"))),
            float(_safe_float((r.get("target_path_profit") or {}).get("score") if isinstance(r.get("target_path_profit"), dict) else r.get("target_path_score"))),
            float(_safe_float(r.get("selection_quality_score"))),
        ),
        reverse=True,
    )

    watch_symbols = []
    for row in previous_rows:
        sym = str(row.get("symbol") or "").strip().upper()
        if not sym:
            continue
        rank_score = float(_safe_float(row.get("rank_score")))
        target_score = float(_safe_float((row.get("target_path_profit") or {}).get("score") if isinstance(row.get("target_path_profit"), dict) else row.get("target_path_score")))
        if (
            rank_score >= float(SWING_RUNTIME_SLIM_MIN_RANK_SCORE)
            or target_score >= float(SWING_RUNTIME_SLIM_MIN_TARGET_PATH_SCORE)
            or bool(row.get("defensive_near_miss_relaxation_entry"))
            or bool(row.get("risk_adjusted_near_miss_entry"))
            or bool(row.get("first_2k_similarity_revival_entry"))
            or bool((row.get("swing_production_contract") or {}).get("approved"))
        ):
            watch_symbols.append(sym)

    watch_symbols = _dedupe_keep_order(watch_symbols[: max(1, int(SWING_RUNTIME_SLIM_KEEP_PREVIOUS_TOP or 12))])

    original_set = set(original)
    active_protected = [s for s in _dedupe_keep_order(active_symbols) if s in original_set]
    anchor_protected = [
        s for s in _dedupe_keep_order(list(SWING_RUNTIME_SLIM_ANCHOR_SYMBOLS or []))
        if s in original_set
    ]

    rotation_seed = _p407_runtime_rotation_seed(scan_options)
    rotation_slots = _p407_runtime_rotation_slot_count(
        configured_max=configured_max,
        protected_count=len(active_protected) + len(anchor_protected),
        original_count=len(original),
    )

    protected_slot_cap = max(1, configured_max - rotation_slots)
    protected_priority = _dedupe_keep_order(active_protected + anchor_protected + watch_symbols)
    protected_priority = [s for s in protected_priority if s in original_set][:protected_slot_cap]

    rotation_pool = [s for s in original if s not in set(protected_priority)]
    rotation_symbols = _p407_rotate_symbols(rotation_pool, rotation_seed, rotation_slots)

    remaining_slots = max(0, configured_max - len(_dedupe_keep_order(protected_priority + rotation_symbols)))
    filler_symbols = [
        s for s in original
        if s not in set(protected_priority)
        and s not in set(rotation_symbols)
    ][:remaining_slots]

    slimmed = _dedupe_keep_order(protected_priority + rotation_symbols + filler_symbols)[:configured_max]
    if not slimmed:
        slimmed = original[:configured_max]

    excluded = [s for s in original if s not in set(slimmed)]

    return {
        "enabled": True,
        "applied": len(slimmed) < len(original),
        "reason": "thrive_fast_scan_priority_cycle" if thrive_fast_scan_applied else "main_web_swing_runtime_slim_applied",
        "configured_max_symbols": configured_max,
        "configured_max_symbols_before_thrive": configured_max_before_thrive,
        "original_count": len(original),
        "symbols": slimmed,
        "excluded_symbols": excluded,
        "excluded_count": len(excluded),
        "watch_symbols": watch_symbols,
        "active_symbols": active_symbols,
        "anchor_symbols": [s for s in list(SWING_RUNTIME_SLIM_ANCHOR_SYMBOLS or []) if s in set(original)],
        "rotation_enabled": bool(rotation_slots > 0 and rotation_symbols),
        "rotation_slots": int(rotation_slots),
        "rotation_seed": int(rotation_seed),
        "rotation_symbols": rotation_symbols,
        "protected_slot_cap": int(protected_slot_cap),
        "protected_symbols": protected_priority,
        "filler_symbols": filler_symbols,
        "priority_symbols": slimmed,
        "thrive_fast_scan_enabled": bool(SWING_THRIVE_FAST_SCAN_ENABLED),
        "thrive_fast_scan_applied": bool(thrive_fast_scan_applied),
        "force_full_coverage": bool(force_full_coverage),
    }

def _bars_for_today_regular_session(bars: list[dict]) -> list[dict]:
    if not bars:
        return []
    return _bars_for_regular_session_date(bars, now_ny().date())


def _mean(nums: list[float]) -> float:
    return (sum(nums) / len(nums)) if nums else 0.0


def _activity_profile(symbol: str, bars: list[dict]) -> dict:
    today = _bars_for_today_regular_session(bars)
    if len(today) < 10:
        return {"symbol": symbol, "eligible": False, "reason": "insufficient_intraday_bars", "score": 0.0}

    price = float(today[-1].get("close") or 0.0)
    if price <= 0:
        return {"symbol": symbol, "eligible": False, "reason": "bad_price", "score": 0.0}
    if price < SCANNER_MIN_PRICE or price > SCANNER_MAX_PRICE:
        return {"symbol": symbol, "eligible": False, "reason": "price_filter", "score": 0.0, "price": price}

    lookback = max(10, min(len(today), int(SCANNER_ACTIVITY_LOOKBACK_BARS)))
    recent_n = max(3, min(lookback // 2, int(SCANNER_ACTIVITY_RECENT_BARS)))
    win = today[-lookback:]
    recent = win[-recent_n:]
    earlier = win[:-recent_n] or win

    closes = [float(b.get("close") or 0.0) for b in win]
    highs = [float(b.get("high", b.get("close") or 0.0) or 0.0) for b in win]
    lows = [float(b.get("low", b.get("close") or 0.0) or 0.0) for b in win]
    vols = [float(b.get("volume") or 0.0) for b in win]
    recent_vol = sum(float(b.get("volume") or 0.0) for b in recent)
    earlier_vol_avg = _mean([float(b.get("volume") or 0.0) for b in earlier]) or 0.0
    relvol = recent_vol / max(earlier_vol_avg * len(recent), 1.0) if earlier_vol_avg > 0 else 0.0

    open_price = float(win[0].get("open", closes[0]) or closes[0] or 0.0)
    intraday_change = (price / open_price - 1.0) if open_price > 0 else 0.0
    recent_change = (price / max(float(recent[0].get("open", price) or price), 1e-9) - 1.0) if recent else 0.0
    range_pct = ((max(highs) - min(lows)) / price) if price > 0 else 0.0
    dollar_vol = price * sum(vols)

    score = 0.0
    score += abs(intraday_change) * 800.0
    score += abs(recent_change) * 600.0
    score += range_pct * 400.0
    score += max(0.0, min(relvol, 3.0)) * 20.0
    if intraday_change > 0:
        score += 8.0
    if recent_change > 0:
        score += 4.0
    if dollar_vol >= 1_000_000:
        score += min(20.0, dollar_vol / 50_000_000.0)

    return {
        "symbol": symbol,
        "eligible": True,
        "score": round(score, 4),
        "price": round(price, 4),
        "intraday_change_pct": round(intraday_change * 100.0, 3),
        "recent_change_pct": round(recent_change * 100.0, 3),
        "range_pct": round(range_pct * 100.0, 3),
        "relvol": round(relvol, 3),
        "dollar_vol": round(dollar_vol, 2),
        "bars": len(today),
    }


def rank_scan_candidates(symbols: list[str], bars_map: dict[str, list[dict]]) -> list[dict]:
    profiles = [_activity_profile(sym, bars_map.get(sym, [])) for sym in symbols]
    profiles = [p for p in profiles if p.get("eligible")]
    profiles.sort(key=lambda x: float(x.get("score", 0.0)), reverse=True)
    return profiles


def fetch_daily_bars_multi(symbols: list[str], lookback_days: int = 90) -> dict[str, list[dict]]:
    end = datetime.now(tz=timezone.utc)
    start = end - timedelta(days=max(5, int(lookback_days)))
    req = StockBarsRequest(symbol_or_symbols=list(symbols or []), timeframe=TimeFrame.Day, start=start, end=end, adjustment=ADJUSTMENT, feed=DATA_FEED)
    bars = data_client.get_stock_bars(req)
    out: dict[str, list[dict]] = {}
    data = getattr(bars, 'data', {}) or {}
    for symbol in symbols or []:
        rows = []
        for b in data.get(symbol, []) or []:
            try:
                ts = b.timestamp
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=timezone.utc)
                rows.append({
                    'ts_utc': ts,
                    'ts_ny': ts.astimezone(NY_TZ),
                    'open': float(b.open),
                    'high': float(b.high),
                    'low': float(b.low),
                    'close': float(b.close),
                    'volume': float(getattr(b, 'volume', 0) or 0),
                    'vwap': float(getattr(b, 'vwap', 0) or 0),
                })
            except Exception:
                continue
        out[symbol] = rows
    return out

def _p402_fetch_daily_bars_multi_budgeted(
    symbols: list[str],
    lookback_days: int = 90,
    scan_started: float | None = None,
) -> tuple[dict[str, list[dict]], dict]:
    requested = _dedupe_keep_order([str(s or "").strip().upper() for s in symbols or [] if str(s or "").strip()])
    chunk_size = max(1, int(SWING_SCAN_DAILY_FETCH_CHUNK_SIZE or 8))
    budget_sec = max(1.0, float(SCAN_RUNTIME_BUDGET_SEC or 1))
    reserve_sec = max(0.0, float(SWING_SCAN_BUDGET_RESERVE_SEC or 0))
    min_symbols = max(1, int(SWING_SCAN_MIN_SYMBOLS_BEFORE_BUDGET_STOP or 1))

    out: dict[str, list[dict]] = {}
    errors: list[dict] = []
    skipped: list[str] = []
    fetched: list[str] = []
    chunks_attempted = 0
    stopped_for_budget = False
    over_budget_after_fetch = False
    last_chunk_symbols: list[str] = []

    _p402_stage_checkpoint(
        "daily_fetch_start",
        requested_count=len(requested),
        lookback_days=int(lookback_days or 0),
        chunk_size=chunk_size,
        budget_sec=int(budget_sec),
        reserve_sec=int(reserve_sec),
    )

    for idx in range(0, len(requested), chunk_size):
        chunk = requested[idx: idx + chunk_size]
        last_chunk_symbols = list(chunk)
        elapsed = _p398_runtime_budget_elapsed_sec(scan_started)
        remaining = budget_sec - elapsed

        if (
            bool(SWING_SCAN_INCREMENTAL_EVAL_ENABLED)
            and len(fetched) >= min_symbols
            and remaining <= reserve_sec
        ):
            skipped.extend(chunk)
            skipped.extend(requested[idx + chunk_size:])
            stopped_for_budget = True
            _p402_stage_checkpoint(
                "daily_fetch_budget_stop",
                fetched_count=len(fetched),
                skipped_count=len(skipped),
                elapsed_sec=round(elapsed, 3),
                remaining_sec=round(max(0.0, remaining), 3),
            )
            break

        chunks_attempted += 1
        _p402_stage_checkpoint(
            "daily_fetch_chunk",
            chunk_index=chunks_attempted,
            symbols=list(chunk),
            fetched_count=len(fetched),
            elapsed_sec=round(elapsed, 3),
            remaining_sec=round(max(0.0, remaining), 3),
        )

        try:
            chunk_map = fetch_daily_bars_multi(chunk, lookback_days=lookback_days)
            for sym in chunk:
                out[sym] = list((chunk_map or {}).get(sym) or [])
                fetched.append(sym)
        except Exception as e:
            errors.append({
                "stage": "daily_fetch_chunk",
                "symbols": list(chunk),
                "error": str(e),
            })
            for sym in chunk:
                out.setdefault(sym, [])

        elapsed_after = _p398_runtime_budget_elapsed_sec(scan_started)
        if elapsed_after >= budget_sec:
            over_budget_after_fetch = True
            if idx + chunk_size < len(requested):
                skipped.extend(requested[idx + chunk_size:])
                stopped_for_budget = True
            _p402_stage_checkpoint(
                "daily_fetch_over_budget_after_chunk",
                chunk_index=chunks_attempted,
                symbols=list(chunk),
                fetched_count=len(fetched),
                skipped_count=len(skipped),
                elapsed_sec=round(elapsed_after, 3),
                budget_sec=int(budget_sec),
            )
            break

    truth = {
        "enabled": bool(SWING_SCAN_INCREMENTAL_EVAL_ENABLED),
        "requested_count": len(requested),
        "fetched_count": len(fetched),
        "skipped_count": len(skipped),
        "fetched_symbols": list(fetched),
        "skipped_symbols": list(_dedupe_keep_order(skipped)),
        "last_chunk_symbols": list(last_chunk_symbols),
        "chunk_size": chunk_size,
        "chunks_attempted": chunks_attempted,
        "stopped_for_budget": bool(stopped_for_budget),
        "over_budget_after_fetch": bool(over_budget_after_fetch),
        "errors": errors,
        "error_count": len(errors),
        "budget_sec": int(budget_sec),
        "reserve_sec": int(reserve_sec),
        "elapsed_sec": round(_p398_runtime_budget_elapsed_sec(scan_started), 3),
    }

    _p402_stage_checkpoint(
        "daily_fetch_complete",
        fetched_count=truth["fetched_count"],
        skipped_count=truth["skipped_count"],
        error_count=truth["error_count"],
        stopped_for_budget=truth["stopped_for_budget"],
        elapsed_sec=truth["elapsed_sec"],
    )
    return out, truth

def _sma(values: list[float], length: int) -> float | None:
    if len(values) < max(1, int(length)):
        return None
    win = values[-int(length):]
    return sum(win) / len(win) if win else None

def _atr(highs: list[float], lows: list[float], closes: list[float], length: int = 14) -> float | None:
    length = max(1, int(length))
    if len(highs) < length + 1 or len(lows) < length + 1 or len(closes) < length + 1:
        return None
    start = len(closes) - length
    trs: list[float] = []
    for i in range(start, len(closes)):
        hi = _safe_float(highs[i])
        lo = _safe_float(lows[i])
        prev_close = _safe_float(closes[i - 1])
        trs.append(max(hi - lo, abs(hi - prev_close), abs(lo - prev_close)))
    return (sum(trs) / len(trs)) if trs else None

def _candidate_selection_quality_score(item: dict | None) -> float:
    item = dict(item or {})
    strategy_name = str(item.get("strategy") or item.get("signal") or "").strip().lower()
    rank_score = float(_safe_float(item.get("rank_score")))
    close_to_high_pct = float(_safe_float(item.get("close_to_high_pct")))
    avg_dollar_volume = float(_safe_float(item.get("avg_dollar_volume_20d")))
    breakout_distance_pct = float(_safe_float(item.get("breakout_distance_pct")))
    effective_max_distance_pct = float(_safe_float(item.get("effective_breakout_max_distance_pct")))
    correlation_group_open_count = float(_safe_float(item.get("correlation_group_open_count")))

    volume_floor = max(float(SWING_BREAKOUT_QUALITY_MIN_AVG_DOLLAR_VOLUME), 1.0)
    volume_ratio = avg_dollar_volume / volume_floor
    volume_bonus = min(max(math.log10(max(volume_ratio, 1.0)), 0.0), 2.0)

    extension_penalty = 0.0
    if strategy_name == BREAKOUT_STRATEGY_NAME:
        max_dist = max(effective_max_distance_pct, 1e-9)
        if breakout_distance_pct > 0:
            extension_ratio = max(0.0, breakout_distance_pct / max_dist)
            extension_penalty = extension_ratio ** 2
            if extension_ratio > float(SWING_SELECTION_EXTENSION_HARD_RATIO):
                extension_penalty += (extension_ratio - float(SWING_SELECTION_EXTENSION_HARD_RATIO)) * float(SWING_SELECTION_EXTENSION_HARD_PENALTY)

    mean_reversion_bonus = 0.0
    if strategy_name == MEAN_REVERSION_STRATEGY_NAME:
        dist_to_mean = abs(float(_safe_float(item.get("distance_to_slow_ma_pct"))))
        max_dist = max(float(_safe_float(((item.get("mode_thresholds") or {}).get("max_dist_to_slow_ma_pct")))), 0.01)
        mean_reversion_bonus = max(0.0, 1.0 - min(dist_to_mean / max_dist, 1.0))

    score = 0.0
    score += rank_score * float(SWING_SELECTION_RANK_WEIGHT)
    score += close_to_high_pct * float(SWING_SELECTION_CLOSE_TO_HIGH_WEIGHT)
    score += volume_bonus * 10.0 * float(SWING_SELECTION_VOLUME_WEIGHT)
    score += mean_reversion_bonus * 10.0
    score -= extension_penalty * 10.0 * float(SWING_SELECTION_EXTENSION_PENALTY_WEIGHT)
    score -= correlation_group_open_count * 10.0 * float(SWING_SELECTION_CORRELATION_PENALTY_WEIGHT)
    return round(score, 4)


def _breakout_min_rank_score_for_mode(mode: str | None) -> float:
    mode = str(mode or "trend").strip().lower() or "trend"
    if mode == "defensive":
        return float(SWING_DEFENSIVE_BREAKOUT_MIN_RANK_SCORE)
    if mode == "neutral":
        return float(SWING_NEUTRAL_BREAKOUT_MIN_RANK_SCORE)
    return float(SWING_TREND_BREAKOUT_MIN_RANK_SCORE)

def _safe_float(x, default=0.0):
    try:
        return float(x)
    except Exception:
        return float(default)

def _current_equity_estimate() -> float:
    snap = get_buying_power_snapshot()
    return _safe_float(snap.get('equity') or 0.0)

def _plan_is_recovered(plan: dict | None) -> bool:
    p = plan or {}
    signal = str(p.get("signal") or "").upper()
    return bool(p.get("recovered")) or signal == "RECOVERED"

def _p254_plan_strategy_name(plan: dict | None) -> str:
    p = plan or {}
    return str(p.get("strategy_name") or p.get("signal") or "").strip().lower()


def _p254_is_swing_strategy_plan(plan: dict | None) -> bool:
    strategy = _p254_plan_strategy_name(plan)
    return strategy in {
        str(BREAKOUT_STRATEGY_NAME).strip().lower(),
        str(MEAN_REVERSION_STRATEGY_NAME).strip().lower(),
        "daily_breakout",
        "daily_mean_reversion",
    }


def _p254_position_notional(pos: dict | None) -> float:
    row = dict(pos or {})
    market_value = abs(_safe_float(row.get("market_value"), 0.0))
    if market_value > 0:
        return market_value
    qty = abs(_safe_float(row.get("qty"), 0.0))
    px = _safe_float(row.get("avg_entry_price") or row.get("current_price") or row.get("last_price"), 0.0)
    return max(0.0, qty * px)


def _p254_recovered_broker_backed_counts_as_strategy(sym: str, plan: dict | None, broker_by_symbol: dict[str, dict]) -> bool:
    symbol = str(sym or "").strip().upper()
    if not symbol or symbol not in broker_by_symbol:
        return False
    if not bool(SWING_BROKER_BACKED_RECOVERED_COUNTS_AS_STRATEGY):
        return False
    if not _plan_is_recovered(plan):
        return False
    return _p254_is_swing_strategy_plan(plan)

def _current_portfolio_exposure_breakdown() -> dict:
    total = 0.0
    strategy_managed = 0.0
    recovered = 0.0
    unmanaged = 0.0
    by_symbol: dict[str, float] = {}
    by_symbol_class: dict[str, str] = {}
    recovered_symbols: list[str] = []
    strategy_symbols: list[str] = []
    unmanaged_symbols: list[str] = []
    corrected_recovered_as_strategy_symbols: list[str] = []

    broker_positions = list(list_open_positions_details_allowed() or [])
    broker_by_symbol = {
        str((p or {}).get("symbol") or "").upper(): dict(p or {})
        for p in broker_positions
        if str((p or {}).get("symbol") or "").strip()
    }

    for p in broker_positions:
        sym = str(p.get("symbol") or "").upper()
        notion = _p254_position_notional(p)
        total += notion
        if sym:
            by_symbol[sym] = notion

        plan = (TRADE_PLAN or {}).get(sym) or {}
        recovered_counts_as_strategy = _p254_recovered_broker_backed_counts_as_strategy(sym, plan, broker_by_symbol)

        if recovered_counts_as_strategy:
            strategy_managed += notion
            if sym:
                by_symbol_class[sym] = "strategy_managed"
                strategy_symbols.append(sym)
                corrected_recovered_as_strategy_symbols.append(sym)
        elif _plan_is_recovered(plan):
            recovered += notion
            if sym:
                by_symbol_class[sym] = "recovered"
                recovered_symbols.append(sym)
        elif bool(plan.get("active")):
            strategy_managed += notion
            if sym:
                by_symbol_class[sym] = "strategy_managed"
                strategy_symbols.append(sym)
        else:
            unmanaged += notion
            if sym:
                by_symbol_class[sym] = "unmanaged"
                unmanaged_symbols.append(sym)

    return {
        "total": total,
        "strategy_managed": strategy_managed,
        "recovered": recovered,
        "unmanaged": unmanaged,
        "by_symbol": by_symbol,
        "by_symbol_class": by_symbol_class,
        "recovered_symbols": recovered_symbols,
        "strategy_symbols": strategy_symbols,
        "unmanaged_symbols": unmanaged_symbols,
        "corrected_recovered_as_strategy_symbols": corrected_recovered_as_strategy_symbols,
        "classification_source": "broker_backed_corrected",
        "counts_recovered_as_strategy": bool(SWING_BROKER_BACKED_RECOVERED_COUNTS_AS_STRATEGY),
    }

def _current_portfolio_exposure() -> tuple[float, dict[str, float]]:
    b = _current_portfolio_exposure_breakdown()
    return float(b.get('total') or 0.0), dict(b.get('by_symbol') or {})


def _portfolio_cap_remaining_by_mode(exposure: dict | None, portfolio_cap: float) -> tuple[float | None, str]:
    exposure = dict(exposure or {})
    portfolio_cap = float(portfolio_cap or 0.0)
    if portfolio_cap <= 0:
        return None, 'none'
    open_total = float(exposure.get('total') or 0.0)
    open_strategy = float(exposure.get('strategy_managed') or 0.0)
    mode = str(SWING_PORTFOLIO_CAP_BLOCK_MODE or 'none').strip().lower()
    if mode == 'total':
        return max(0.0, portfolio_cap - open_total), 'total'
    if mode == 'strategy':
        return max(0.0, portfolio_cap - open_strategy), 'strategy'
    if mode == 'both':
        return max(0.0, min(portfolio_cap - open_total, portfolio_cap - open_strategy)), 'both'
    return None, mode or 'none'


def _portfolio_exposure_projection(projected_notional: float, exposure: dict | None = None, portfolio_cap: float = 0.0) -> dict:
    projected_notional = max(0.0, float(projected_notional or 0.0))
    exposure = dict(exposure or {})
    remaining_capacity, basis = _portfolio_cap_remaining_by_mode(exposure, portfolio_cap)
    if remaining_capacity is None:
        return {
            'blocked': False,
            'blocking_basis': basis,
            'remaining_capacity': None,
            'over_amount': 0.0,
            'projected_notional': round(projected_notional, 4),
        }
    remaining_capacity = max(0.0, float(remaining_capacity or 0.0))
    blocked = projected_notional > (remaining_capacity + 1e-9)
    over_amount = max(0.0, projected_notional - remaining_capacity)
    return {
        'blocked': bool(blocked),
        'blocking_basis': basis,
        'remaining_capacity': round(remaining_capacity, 4),
        'over_amount': round(over_amount, 4),
        'projected_notional': round(projected_notional, 4),
    }

def _dedupe_candidate_reasons(reasons: list | None) -> list[str]:
    seen = set()
    out = []
    for reason in (reasons or []):
        r = str(reason or '').strip()
        if not r or r in seen:
            continue
        seen.add(r)
        out.append(r)
    return out


def _canonical_portfolio_cap_gate(candidate: dict, projected_notional: float, exposure: dict | None, portfolio_cap: float, selection_blockers: list | None = None, restore_eligibility: bool = True) -> dict:
    """Single source of truth for portfolio-cap admission.

    A candidate is blocked by portfolio exposure only when the candidate's projected
    notional is greater than the remaining capacity for the configured cap mode.
    This helper also removes stale legacy portfolio_exposure_limit reasons before
    applying the canonical decision.
    """
    c = candidate if isinstance(candidate, dict) else {}
    projected_notional = max(0.0, float(projected_notional or 0.0))

    existing_reasons = _dedupe_candidate_reasons(c.get('rejection_reasons') or [])
    had_legacy_cap_reason = 'portfolio_exposure_limit' in existing_reasons
    reasons = [r for r in existing_reasons if r != 'portfolio_exposure_limit']
    c['rejection_reasons'] = reasons

    if selection_blockers is not None:
        selection_blockers[:] = [str(r) for r in selection_blockers if str(r) != 'portfolio_exposure_limit']

    projection = _portfolio_exposure_projection(projected_notional, exposure=exposure, portfolio_cap=portfolio_cap)
    c['portfolio_exposure_projection'] = dict(projection)
    c['portfolio_cap_gate'] = {
        'source': 'canonical_helper',
        'decision': 'block' if projection.get('blocked') else 'allow',
        'compared_projected_notional': projection.get('projected_notional'),
        'compared_remaining_capacity': projection.get('remaining_capacity'),
        'blocking_basis': projection.get('blocking_basis'),
        'over_amount': projection.get('over_amount'),
    }

    if projection.get('blocked'):
        c['eligible'] = False
        reasons = _dedupe_candidate_reasons(list(c.get('rejection_reasons') or []) + ['portfolio_exposure_limit'])
        c['rejection_reasons'] = reasons
        c['portfolio_exposure_limit_basis'] = projection.get('blocking_basis')
        c['portfolio_exposure_limit_over_amount'] = projection.get('over_amount')
        if selection_blockers is not None:
            selection_blockers.append('portfolio_exposure_limit')
    else:
        c['portfolio_exposure_limit_basis'] = projection.get('blocking_basis')
        c['portfolio_exposure_limit_over_amount'] = 0.0
        if restore_eligibility and had_legacy_cap_reason:
            qty = float(c.get('estimated_qty') or 0.0)
            min_qty = max(float(MIN_AFFORDABLE_QTY), float(MIN_QTY))
            if not c.get('rejection_reasons') and qty >= min_qty:
                c['eligible'] = True

    c['rejection_reasons'] = _dedupe_candidate_reasons(c.get('rejection_reasons') or [])
    return dict(projection)


def _cap_adjust_candidate_qty(close: float, estimated_qty: float, open_symbol_notional: float, symbol_cap: float, exposure: dict | None, portfolio_cap: float) -> dict:
    close = float(close or 0.0)
    estimated_qty = max(0.0, float(estimated_qty or 0.0))
    open_symbol_notional = max(0.0, float(open_symbol_notional or 0.0))
    symbol_cap = max(0.0, float(symbol_cap or 0.0))
    remaining_portfolio, basis = _portfolio_cap_remaining_by_mode(exposure, portfolio_cap)
    symbol_remaining = max(0.0, symbol_cap - open_symbol_notional) if symbol_cap > 0 else None
    if close <= 0 or estimated_qty <= 0:
        return {
            'raw_estimated_qty': round(estimated_qty, 4),
            'effective_estimated_qty': 0.0,
            'raw_projected_notional': 0.0,
            'effective_projected_notional': 0.0,
            'portfolio_remaining': round(float(remaining_portfolio), 4) if remaining_portfolio is not None else None,
            'symbol_remaining': round(float(symbol_remaining), 4) if symbol_remaining is not None else None,
            'portfolio_basis': basis,
            'portfolio_qty_cap': None,
            'symbol_qty_cap': None,
            'qty_clipped_to_portfolio_cap': False,
            'qty_clipped_to_symbol_cap': False,
        }
    raw_projected_notional = estimated_qty * close
    portfolio_qty_cap = (remaining_portfolio / close) if remaining_portfolio is not None else None
    symbol_qty_cap = (symbol_remaining / close) if symbol_remaining is not None else None
    effective_qty = estimated_qty
    clipped_portfolio = False
    clipped_symbol = False
    if portfolio_qty_cap is not None and effective_qty > portfolio_qty_cap:
        effective_qty = portfolio_qty_cap
        clipped_portfolio = True
    if symbol_qty_cap is not None and effective_qty > symbol_qty_cap:
        effective_qty = symbol_qty_cap
        clipped_symbol = True
    effective_qty = max(0.0, round(effective_qty, 2))
    return {
        'raw_estimated_qty': round(estimated_qty, 4),
        'effective_estimated_qty': round(effective_qty, 4),
        'raw_projected_notional': round(raw_projected_notional, 4),
        'effective_projected_notional': round(effective_qty * close, 4),
        'portfolio_remaining': round(float(remaining_portfolio), 4) if remaining_portfolio is not None else None,
        'symbol_remaining': round(float(symbol_remaining), 4) if symbol_remaining is not None else None,
        'portfolio_basis': basis,
        'portfolio_qty_cap': round(float(portfolio_qty_cap), 4) if portfolio_qty_cap is not None else None,
        'symbol_qty_cap': round(float(symbol_qty_cap), 4) if symbol_qty_cap is not None else None,
        'qty_clipped_to_portfolio_cap': bool(clipped_portfolio),
        'qty_clipped_to_symbol_cap': bool(clipped_symbol),
    }

def _p300_broker_can_afford_one_share(close: float, broker_snapshot: dict | None = None) -> bool:
    close = float(close or 0.0)
    snap = dict(broker_snapshot or get_buying_power_snapshot() or {})
    buying_power = float(snap.get("buying_power") or 0.0)
    cash = float(snap.get("cash") or 0.0)
    if close <= 0:
        return False
    return bool(max(buying_power, cash) >= close)


def _p300_executable_sizing_truth(candidate: dict | None, cap_truth: dict | None = None) -> dict:
    c = dict(candidate or {})
    cap = dict(cap_truth or c.get("sizing_truth") or {})
    affordability = dict(c.get("affordability") or {})
    broker_snapshot = dict(
        c.get("scan_broker_snapshot")
        or affordability.get("buying_power_snapshot")
        or get_buying_power_snapshot()
        or {}
    )

    close = float(_safe_float(c.get("close") or c.get("price") or 0.0))
    requested_qty = float(_safe_float(c.get("requested_qty") or 0.0))
    raw_estimated_qty = float(_safe_float(cap.get("raw_estimated_qty") if cap.get("raw_estimated_qty") is not None else c.get("estimated_qty")))
    effective_estimated_qty = float(_safe_float(cap.get("effective_estimated_qty") if cap.get("effective_estimated_qty") is not None else c.get("estimated_qty")))
    min_qty = max(float(SWING_EXECUTABLE_SELECTION_MIN_QTY or 1.0), float(MIN_AFFORDABLE_QTY), float(MIN_QTY))

    broker_can_afford_one = _p300_broker_can_afford_one_share(close, broker_snapshot)
    executable = bool(effective_estimated_qty >= min_qty)

    sizing_block_reason = "none"
    broker_label_valid = False
    if not executable:
        if close <= 0:
            sizing_block_reason = "missing_price"
        elif requested_qty <= 0 and raw_estimated_qty <= 0:
            sizing_block_reason = "internal_sizing_qty_zero"
        elif broker_can_afford_one:
            sizing_block_reason = "internal_sizing_qty_zero"
        else:
            sizing_block_reason = "broker_insufficient_buying_power"
            broker_label_valid = True

    dollar_risk_truth = _p384_candidate_dollar_risk_truth({
        **c,
        "estimated_qty": effective_estimated_qty,
    })

    return {
        "enabled": bool(SWING_EXECUTABLE_SELECTION_TRUTH_ENABLED),
        "executable": executable,
        "sizing_block_reason": sizing_block_reason,
        "broker_buying_power_label_valid": broker_label_valid,
        "dollar_risk_selection_truth": dollar_risk_truth,
        "min_executable_qty": round(min_qty, 4),
        "close": round(close, 4),
        "requested_qty": round(requested_qty, 4),
        "raw_estimated_qty": round(raw_estimated_qty, 4),
        "effective_estimated_qty": round(effective_estimated_qty, 4),
        "raw_projected_notional": cap.get("raw_projected_notional"),
        "effective_projected_notional": cap.get("effective_projected_notional"),
        "risk_per_share": c.get("risk_per_share"),
        "risk_per_share_pct": c.get("risk_per_share_pct"),
        "broker_buying_power": broker_snapshot.get("buying_power"),
        "broker_cash": broker_snapshot.get("cash"),
        "broker_can_afford_one_share": broker_can_afford_one,
        "affordability_reason": affordability.get("reason"),
        "portfolio_remaining": cap.get("portfolio_remaining"),
        "symbol_remaining": cap.get("symbol_remaining"),
        "portfolio_basis": cap.get("portfolio_basis"),
        "portfolio_qty_cap": cap.get("portfolio_qty_cap"),
        "symbol_qty_cap": cap.get("symbol_qty_cap"),
        "qty_clipped_to_portfolio_cap": bool(cap.get("qty_clipped_to_portfolio_cap")),
        "qty_clipped_to_symbol_cap": bool(cap.get("qty_clipped_to_symbol_cap")),
    }


def _p300_apply_executable_selection_contract(candidate: dict | None, cap_truth: dict | None = None) -> dict:
    c = dict(candidate or {})
    if not bool(SWING_EXECUTABLE_SELECTION_TRUTH_ENABLED):
        return c

    truth = _p300_executable_sizing_truth(c, cap_truth=cap_truth)
    c["executable_sizing_truth"] = truth
    c["estimated_qty"] = round(float(truth.get("effective_estimated_qty") or 0.0), 2)

    reasons = [
        str(r)
        for r in list(c.get("rejection_reasons") or [])
        if str(r)
    ]

    if "insufficient_buying_power" in reasons and not bool(truth.get("broker_buying_power_label_valid")):
        reasons = [r for r in reasons if r != "insufficient_buying_power"]
        if "internal_sizing_qty_zero" not in reasons:
            reasons.append("internal_sizing_qty_zero")

    if not bool(truth.get("executable")):
        c["eligible"] = False
        reason = str(truth.get("sizing_block_reason") or "internal_sizing_qty_zero")
        if reason not in reasons:
            reasons.append(reason)

    c["rejection_reasons"] = _dedupe_candidate_reasons(reasons)
    return c


def _p300_selection_contract_cleanup(rows: list | None) -> list[dict]:
    cleaned = []
    for row in list(rows or []):
        if not isinstance(row, dict):
            continue
        c = _p300_apply_executable_selection_contract(row)
        if bool(c.get("eligible")) and not bool((c.get("executable_sizing_truth") or {}).get("executable")):
            c["eligible"] = False
            c.setdefault("rejection_reasons", []).append("internal_sizing_qty_zero")
            c["rejection_reasons"] = _dedupe_candidate_reasons(c.get("rejection_reasons") or [])
        cleaned.append(c)
    return cleaned

def _p459_active_swing_regime_profile() -> dict:
    mode = str(SWING_FIRST_2K_REGIME_PROFILE_MODE or "auto").strip().lower()
    regime = dict(globals().get("LAST_REGIME_SNAPSHOT") or {})
    score = float(_safe_float(regime.get("score"), 0.0))
    breadth = float(_safe_float(regime.get("breadth"), 0.0))
    favorable = bool(regime.get("favorable"))

    if not bool(SWING_FIRST_2K_REGIME_PROFILE_SWITCH_ENABLED):
        profile = "static"
        reason = "profile_switch_disabled"
    elif mode in {"momentum", "momentum_thrive", "thrive"}:
        profile = "momentum_thrive"
        reason = "forced_momentum_profile"
    elif mode in {"chop", "chop_preserve", "preserve"}:
        profile = "chop_preserve"
        reason = "forced_chop_profile"
    elif (
        favorable
        and score >= float(SWING_FIRST_2K_REGIME_MOMENTUM_SCORE_MIN)
        and breadth >= float(SWING_FIRST_2K_REGIME_MOMENTUM_BREADTH_MIN)
    ):
        profile = "momentum_thrive"
        reason = "regime_score_and_breadth_match_first_2k_window"
    else:
        profile = "chop_preserve"
        reason = "recent_window_chop_preservation_profile"

    if profile == "momentum_thrive":
        contract = {
            "risk_dollars": float(SWING_FIRST_2K_MOMENTUM_RISK_DOLLARS),
            "target_r_mult": float(SWING_FIRST_2K_MOMENTUM_TARGET_R_MULT),
            "min_rank_score": float(SWING_FIRST_2K_MOMENTUM_MIN_RANK_SCORE),
            "max_below_breakout_pct": float(SWING_FIRST_2K_MOMENTUM_MAX_BELOW_BREAKOUT_PCT),
            "max_risk_per_share_pct": float(SWING_FIRST_2K_MOMENTUM_MAX_RISK_PER_SHARE_PCT),
            "max_entries_per_day": int(SWING_FIRST_2K_MOMENTUM_MAX_ENTRIES_PER_DAY),
            "max_entries_per_scan": int(SWING_FIRST_2K_MOMENTUM_MAX_ENTRIES_PER_SCAN),
            "sleeve_symbols": str(SWING_FIRST_2K_MOMENTUM_SYMBOLS or ""),
        }
    elif profile == "chop_preserve":
        contract = {
            "risk_dollars": float(SWING_FIRST_2K_CHOP_RISK_DOLLARS),
            "target_r_mult": float(SWING_FIRST_2K_CHOP_TARGET_R_MULT),
            "min_rank_score": float(SWING_FIRST_2K_CHOP_MIN_RANK_SCORE),
            "max_below_breakout_pct": float(SWING_FIRST_2K_CHOP_MAX_BELOW_BREAKOUT_PCT),
            "max_risk_per_share_pct": float(SWING_FIRST_2K_CHOP_MAX_RISK_PER_SHARE_PCT),
            "max_entries_per_day": int(SWING_FIRST_2K_CHOP_MAX_ENTRIES_PER_DAY),
            "max_entries_per_scan": int(SWING_FIRST_2K_CHOP_MAX_ENTRIES_PER_SCAN),
            "sleeve_symbols": str(SWING_FIRST_2K_GEOMETRY_SLEEVE_SYMBOLS or ""),
        }
    else:
        contract = {
            "risk_dollars": float(RISK_DOLLARS or 0.0),
            "target_r_mult": float(SWING_TARGET_R_MULT or 0.0),
            "min_rank_score": float(SWING_PRODUCTION_RESET_MIN_RANK_SCORE),
            "max_below_breakout_pct": float(SWING_PRODUCTION_RESET_MAX_BELOW_BREAKOUT_PCT),
            "max_risk_per_share_pct": float(SWING_PRODUCTION_RESET_MAX_RISK_PER_SHARE_PCT),
            "max_entries_per_day": int(SWING_MAX_NEW_ENTRIES_PER_DAY),
            "max_entries_per_scan": int(SWING_PRODUCTION_RESET_MAX_ENTRIES_PER_SCAN),
            "sleeve_symbols": str(SWING_FIRST_2K_GEOMETRY_SLEEVE_SYMBOLS or ""),
        }

    return {
        "enabled": bool(SWING_FIRST_2K_REGIME_PROFILE_SWITCH_ENABLED),
        "mode": mode,
        "active_profile": profile,
        "reason": reason,
        "regime": {
            "favorable": favorable,
            "score": score,
            "breadth": breadth,
            "ts_utc": regime.get("ts_utc"),
        },
        "contract": contract,
        "replay_basis": {
            "momentum_window": "2026-05-26_to_2026-06-30",
            "momentum_best": "risk_60_daily_5_scan_1_target_2p0_rank_103_below_9pct",
            "chop_window": "2026-07-01_to_2026-07-31",
            "chop_best": "risk_30_daily_4_scan_2_target_1p5_rank_100_below_9pct",
        },
    }

