def _p323_value(candidate: dict | None, *keys):
    c = dict(candidate or {})
    for key in keys:
        val = c.get(key)
        if val is not None and str(val).strip() != "":
            return val
    return None

def _p323_pct_decimal(value):
    if value is None or str(value).strip() == "":
        return None
    val = float(_safe_float(value))
    if abs(val) > 1.0:
        return val / 100.0
    return val

def _p365_same_day_stall_churn_reentry_cooldown(symbol: str) -> dict:
    sym = str(symbol or "").strip().upper()
    if not sym:
        return {"active": False, "reason": "missing_symbol"}

    if not bool(SWING_STALL_CHURN_REENTRY_COOLDOWN_ENABLED):
        return {"active": False, "reason": "disabled"}

    today = now_ny().date()
    stall_rows = []
    for row in list(DECISIONS or [])[-1000:]:
        if not isinstance(row, dict):
            continue
        if str(row.get("source") or "") != "worker_exit":
            continue
        if str(row.get("symbol") or "").strip().upper() != sym:
            continue

        ts = _ts_parse_or_none(row.get("ts_utc") or row.get("timestamp") or row.get("time"))
        if not ts or ts.astimezone(NY_TZ).date() != today:
            continue

        action = str(row.get("action") or "").strip().lower()
        reason = str(row.get("reason") or "").strip().lower()
        if reason in {"stall_exit", "stall_loss_guard"} or action in {"stall_exit", "stall_loss_guard"}:
            stall_rows.append({
                "ts_utc": row.get("ts_utc"),
                "action": row.get("action"),
                "reason": row.get("reason"),
            })

    if not stall_rows:
        return {"active": False, "reason": "no_same_day_stall_family_exit"}

    return {
        "active": True,
        "reason": "same_day_stall_churn_reentry_cooldown",
        "symbol": sym,
        "stall_exit_count_today": len(stall_rows),
        "latest_stall_exit": stall_rows[-1],
    }


def _p365_apply_stall_churn_reentry_cooldown(candidate: dict | None) -> dict:
    c = dict(candidate or {})
    sym = str(c.get("symbol") or "").strip().upper()
    cooldown = _p365_same_day_stall_churn_reentry_cooldown(sym)
    c["same_day_stall_churn_reentry_cooldown"] = cooldown

    if bool(cooldown.get("active")):
        reasons = list(c.get("rejection_reasons") or [])
        if "same_day_stall_churn_reentry_cooldown" not in reasons:
            reasons.append("same_day_stall_churn_reentry_cooldown")
        c["rejection_reasons"] = _dedupe_candidate_reasons(reasons)
        c["eligible"] = False

    return c

def _p403_late_day_entry_window_active(now_dt: datetime | None = None) -> bool:
    if not bool(SWING_LATE_DAY_ENTRY_QUALITY_TIGHTEN_ENABLED):
        return False
    try:
        dt = now_dt.astimezone(NY_TZ) if now_dt else now_ny()
        raw = str(SWING_LATE_DAY_ENTRY_QUALITY_START_NY or "15:00").strip()
        hh, mm = raw.split(":", 1)
        start = dt.replace(hour=int(hh), minute=int(mm), second=0, microsecond=0)
        return bool(dt >= start)
    except Exception:
        return False


def _p528_late_day_first_2k_sleeve(candidate: dict | None, blockers: list | None = None) -> dict:
    c = dict(candidate or {})
    blocker_set = {
        str(reason)
        for reason in list(blockers or [])
        if str(reason)
    }
    residual_rejection_reasons = [
        str(reason)
        for reason in list(c.get("rejection_reasons") or [])
        if str(reason)
        and str(reason) not in {
            "late_day_entry_quality_tightening",
            "late_day_rank_below_min",
        }
    ]
    profile = _p409_first_2k_symbol_profile()
    profile_match = _p409_candidate_profile_match(c, profile)
    symbol = str(c.get("symbol") or "").strip().upper()
    rank_score = float(_safe_float(c.get("rank_score"), 0.0))
    rank_gap = max(0.0, float(SWING_LATE_DAY_ENTRY_MIN_RANK_SCORE) - rank_score)
    breakout_distance = _p410_geometry_value_pct(c, "breakout_distance_pct")
    close_to_high = _p410_geometry_value_pct(c, "close_to_high_pct")
    risk_pct = _p410_geometry_value_pct(c, "risk_per_share_pct")
    contract = dict(c.get("swing_production_contract") or {})
    checks = dict(contract.get("checks") or {})
    entry_type = str(c.get("entry_type") or "").strip()
    match_score = float(_safe_float(profile_match.get("match_score"), 0.0))
    risk_calibrated = bool(checks.get("risk_calibrated_starter_ok")) or entry_type in {
        "swing_production_risk_calibrated_starter",
        "swing_production_near_rank_revival",
        "first_2k_geometry_sleeve",
        "target_path_risk_adjusted_near_miss",
    }
    geometry_ok = bool(
        breakout_distance >= -1.0
        and close_to_high >= 98.5
        and 0.0 < risk_pct <= 12.0
    )
    only_rank_blocked = bool(blocker_set) and blocker_set.issubset({"late_day_rank_below_min"})
    applies = bool(
        SWING_LATE_DAY_FIRST_2K_SLEEVE_ENABLED
        and only_rank_blocked
        and risk_calibrated
        and geometry_ok
        and not residual_rejection_reasons
        and rank_gap <= float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MAX_RANK_GAP)
        and match_score >= float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MIN_MATCH_SCORE)
    )

    if applies:
        reason = "late_day_first_2k_reduced_risk_sleeve_applied"
    elif not bool(SWING_LATE_DAY_FIRST_2K_SLEEVE_ENABLED):
        reason = "late_day_first_2k_sleeve_disabled"
    elif not only_rank_blocked:
        reason = "late_day_blockers_not_rank_only"
    elif residual_rejection_reasons:
        reason = "non_late_day_rejection_reasons_present"
    elif not risk_calibrated:
        reason = "not_risk_calibrated_starter"
    elif not geometry_ok:
        reason = "geometry_not_first_2k_like"
    elif rank_gap > float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MAX_RANK_GAP):
        reason = "late_day_rank_gap_too_wide"
    elif match_score < float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MIN_MATCH_SCORE):
        reason = "first_2k_match_score_below_min"
    else:
        reason = "not_applied"

    return {
        "enabled": bool(SWING_LATE_DAY_FIRST_2K_SLEEVE_ENABLED),
        "applies": bool(applies),
        "reason": reason,
        "symbol": symbol,
        "rank_score": round(rank_score, 4),
        "late_day_min_rank_score": float(SWING_LATE_DAY_ENTRY_MIN_RANK_SCORE),
        "rank_gap": round(rank_gap, 4),
        "max_rank_gap": float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MAX_RANK_GAP),
        "match_score": round(match_score, 4),
        "min_match_score": float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MIN_MATCH_SCORE),
        "risk_multiplier": float(SWING_LATE_DAY_FIRST_2K_SLEEVE_RISK_MULTIPLIER),
        "risk_calibrated": bool(risk_calibrated),
        "geometry_ok": bool(geometry_ok),
        "breakout_distance_pct": breakout_distance,
        "close_to_high_pct": close_to_high,
        "risk_per_share_pct": risk_pct,
        "profile_match": profile_match,
        "blockers_before_sleeve": sorted(blocker_set),
        "residual_rejection_reasons": list(residual_rejection_reasons),
    }


def _p403_late_day_entry_quality(candidate: dict | None) -> dict:
    c = dict(candidate or {})
    active = _p403_late_day_entry_window_active()
    rank_score = _safe_float(c.get("rank_score"), 0.0)
    target_path = dict(c.get("target_path_profit") or {})
    target_path_score = _safe_float(target_path.get("score") or c.get("target_path_score"), 0.0)
    entry_type = str(c.get("entry_type") or "").strip()
    contract = dict(c.get("swing_production_contract") or {})
    checks = dict(contract.get("checks") or {})

    blockers = []
    if active:
        if rank_score < float(SWING_LATE_DAY_ENTRY_MIN_RANK_SCORE):
            blockers.append("late_day_rank_below_min")
        if target_path_score < float(SWING_LATE_DAY_ENTRY_MIN_TARGET_PATH_SCORE):
            blockers.append("late_day_target_path_below_min")
        if (
            bool(SWING_LATE_DAY_ENTRY_ALLOW_RISK_CALIBRATED_ONLY)
            and not bool(checks.get("risk_calibrated_starter_ok"))
            and entry_type != "swing_production_risk_calibrated_starter"
        ):
            blockers.append("late_day_not_risk_calibrated_starter")

    sleeve = _p528_late_day_first_2k_sleeve(c, blockers=blockers) if active else {
        "enabled": bool(SWING_LATE_DAY_FIRST_2K_SLEEVE_ENABLED),
        "applies": False,
        "reason": "late_day_window_not_active",
    }
    if bool(sleeve.get("applies")):
        blockers = [
            reason
            for reason in blockers
            if str(reason) != "late_day_rank_below_min"
        ]

    return {
        "enabled": bool(SWING_LATE_DAY_ENTRY_QUALITY_TIGHTEN_ENABLED),
        "active": bool(active),
        "start_ny": str(SWING_LATE_DAY_ENTRY_QUALITY_START_NY),
        "rank_score": rank_score,
        "min_rank_score": float(SWING_LATE_DAY_ENTRY_MIN_RANK_SCORE),
        "target_path_score": target_path_score,
        "min_target_path_score": float(SWING_LATE_DAY_ENTRY_MIN_TARGET_PATH_SCORE),
        "risk_calibrated_only": bool(SWING_LATE_DAY_ENTRY_ALLOW_RISK_CALIBRATED_ONLY),
        "entry_type": entry_type,
        "allowed": not blockers,
        "blockers": blockers,
        "first_2k_reduced_risk_sleeve": sleeve,
        "risk_multiplier": (
            float(SWING_LATE_DAY_FIRST_2K_SLEEVE_RISK_MULTIPLIER)
            if bool(sleeve.get("applies"))
            else 1.0
        ),
    }


def _p403_apply_late_day_entry_quality(candidate: dict | None) -> dict:
    c = dict(candidate or {})
    truth = _p403_late_day_entry_quality(c)
    c["late_day_entry_quality"] = truth
    sleeve = dict(truth.get("first_2k_reduced_risk_sleeve") or {})
    if bool(truth.get("active")) and bool(truth.get("allowed")) and bool(sleeve.get("applies")):
        reasons = [
            str(reason)
            for reason in list(c.get("rejection_reasons") or [])
            if str(reason)
            and str(reason) not in {
                "late_day_entry_quality_tightening",
                "late_day_rank_below_min",
            }
        ]
        c["rejection_reasons"] = _dedupe_candidate_reasons(reasons)
        c["eligible"] = not bool(c["rejection_reasons"])
        c["late_day_first_2k_sleeve_entry"] = True
        c["entry_type"] = "late_day_first_2k_reduced_risk_sleeve"
        c["selection_source"] = c.get("selection_source") or "late_day_first_2k_reduced_risk_sleeve"
        c = _p291_apply_risk_adjusted_entry_sizing(
            c,
            sleeve="late_day_first_2k_reduced_risk_sleeve",
            risk_multiplier=float(SWING_LATE_DAY_FIRST_2K_SLEEVE_RISK_MULTIPLIER),
        )
        c = _p300_apply_executable_selection_contract(c)
        contract = dict(c.get("swing_production_contract") or {})
        contract["approved"] = bool(c.get("eligible", True)) and bool((c.get("executable_sizing_truth") or {}).get("executable", True))
        contract["late_day_entry_quality"] = truth
        contract["late_day_first_2k_sleeve"] = sleeve
        checks = dict(contract.get("checks") or {})
        checks["late_day_first_2k_sleeve_ok"] = bool(contract.get("approved"))
        contract["checks"] = checks
        c["swing_production_contract"] = contract
        c["production_contract_approved"] = bool(contract.get("approved"))
        c["eligible"] = bool(contract.get("approved"))
    elif bool(truth.get("active")) and not bool(truth.get("allowed")):
        c["eligible"] = False
        reasons = list(c.get("rejection_reasons") or [])
        reasons.append("late_day_entry_quality_tightening")
        reasons.extend(list(truth.get("blockers") or []))
        c["rejection_reasons"] = _dedupe_candidate_reasons(reasons)
        contract = dict(c.get("swing_production_contract") or {})
        contract["approved"] = False
        contract["late_day_entry_quality"] = truth
        c["swing_production_contract"] = contract
    return c


def _p528_enforce_late_day_first_2k_sleeve_cap(rows: list | None) -> list[dict]:
    out = [
        dict(row or {})
        for row in list(rows or [])
        if isinstance(row, dict)
    ]
    sleeve_rows = [
        row for row in out
        if bool(row.get("late_day_first_2k_sleeve_entry"))
        and bool(row.get("eligible"))
        and bool(row.get("production_contract_approved"))
    ]
    if len(sleeve_rows) <= 1:
        return out

    sleeve_rows.sort(
        key=lambda row: (
            _safe_float(((row.get("late_day_entry_quality") or {}).get("first_2k_reduced_risk_sleeve") or {}).get("match_score"), 0.0),
            _safe_float(row.get("rank_score"), 0.0),
            _safe_float(row.get("selection_quality_score"), 0.0),
        ),
        reverse=True,
    )
    allowed_symbol = str((sleeve_rows[0] or {}).get("symbol") or "").strip().upper()
    for row in out:
        sym = str(row.get("symbol") or "").strip().upper()
        if (
            bool(row.get("late_day_first_2k_sleeve_entry"))
            and sym
            and sym != allowed_symbol
        ):
            row["eligible"] = False
            row["production_contract_approved"] = False
            row["selected"] = False
            row["selection_source"] = "late_day_first_2k_sleeve_cap_blocked"
            reasons = list(row.get("rejection_reasons") or [])
            reasons.append("late_day_first_2k_sleeve_max_one_per_scan")
            row["rejection_reasons"] = _dedupe_candidate_reasons(reasons)
            contract = dict(row.get("swing_production_contract") or {})
            contract["approved"] = False
            contract["late_day_first_2k_sleeve_cap"] = {
                "allowed_symbol": allowed_symbol,
                "blocked_symbol": sym,
                "max_entries_per_scan": 1,
                "reason": "late_day_first_2k_sleeve_max_one_per_scan",
            }
            row["swing_production_contract"] = contract
    return out


def _p403_winner_day_add_slot_adjustment(
    base_max_new_entries: int,
    daily_goal_progress: dict | None = None,
) -> dict:
    goal = dict(daily_goal_progress or {})
    primary_pnl = _safe_float(goal.get("primary_daily_pnl"), 0.0)
    target_low = _safe_float(goal.get("target_low"), 100.0)
    below_low = primary_pnl < target_low

    blockers = []
    if not bool(SWING_WINNER_DAY_ADD_SLOT_ENABLED):
        blockers.append("disabled")
    if primary_pnl < float(SWING_WINNER_DAY_ADD_SLOT_MIN_PNL):
        blockers.append("daily_pnl_below_winner_day_min")
    if bool(SWING_WINNER_DAY_ADD_SLOT_BELOW_LOW_TARGET_ONLY) and not below_low:
        blockers.append("daily_goal_low_already_hit")

    extra = 0 if blockers else max(0, int(SWING_WINNER_DAY_ADD_SLOT_MAX_EXTRA or 0))
    adjusted = max(0, int(base_max_new_entries or 0)) + int(extra)

    return {
        "enabled": bool(SWING_WINNER_DAY_ADD_SLOT_ENABLED),
        "applied": bool(extra > 0),
        "base_max_new_entries": int(base_max_new_entries or 0),
        "effective_max_new_entries": int(adjusted),
        "extra_slots": int(extra),
        "primary_daily_pnl": round(primary_pnl, 4),
        "target_low": round(target_low, 4),
        "min_pnl": float(SWING_WINNER_DAY_ADD_SLOT_MIN_PNL),
        "below_low_target_only": bool(SWING_WINNER_DAY_ADD_SLOT_BELOW_LOW_TARGET_ONLY),
        "blockers": blockers,
    }

def _p323_swing_production_contract(candidate: dict | None, global_block_reasons: list | None = None) -> dict:
    candidate = _p365_apply_stall_churn_reentry_cooldown(candidate)
    return swing_contract_production_contract(
        candidate,
        config=_p333_swing_selection_contract_config(),
        global_block_reasons=global_block_reasons,
        sizing_truth_fn=_p300_executable_sizing_truth,
    )

def _p323_apply_swing_production_contract(candidate: dict | None, global_block_reasons: list | None = None) -> dict:
    candidate = _p365_apply_stall_churn_reentry_cooldown(candidate)
    out = swing_contract_apply(
        candidate,
        config=_p333_swing_selection_contract_config(),
        global_block_reasons=global_block_reasons,
        sizing_truth_fn=_p300_executable_sizing_truth,
    )
    return _p385_apply_dollar_risk_add_slot_contract(out)

def _p323_swing_production_sort_key(candidate: dict | None) -> tuple:
    return swing_contract_sort_key(
        candidate,
        config=_p333_swing_selection_contract_config(),
    )

def _p323_enforce_production_contract_selection(
    rows: list | None,
    global_block_reasons: list | None = None,
) -> list[dict]:
    rows = [_p365_apply_stall_churn_reentry_cooldown(row) for row in list(rows or [])]
    rows = _p377_filter_rows_for_breakout_follow_through(rows)
    enforced = swing_contract_enforce(
        rows,
        config=_p333_swing_selection_contract_config(),
        global_block_reasons=global_block_reasons,
        sizing_truth_fn=_p300_executable_sizing_truth,
    )
    enforced = [_p385_apply_dollar_risk_add_slot_contract(row) for row in enforced]
    enforced = [_p403_apply_late_day_entry_quality(row) for row in enforced]
    return _p528_enforce_late_day_first_2k_sleeve_cap(enforced)

def _p323_contract_approved_rows(rows: list | None) -> list[dict]:
    rows = [_p365_apply_stall_churn_reentry_cooldown(row) for row in list(rows or [])]
    rows = _p377_filter_rows_for_breakout_follow_through(rows)
    rows = [_p385_apply_dollar_risk_add_slot_contract(row) for row in rows]
    rows = [_p403_apply_late_day_entry_quality(row) for row in rows]
    rows = _p528_enforce_late_day_first_2k_sleeve_cap(rows)
    return swing_contract_approved_rows(
        rows,
        config=_p333_swing_selection_contract_config(),
        sizing_truth_fn=_p300_executable_sizing_truth,
    )

def _p326_finalize_production_contract_selection(
    rows: list | None,
    max_new_entries: int,
    global_block_reasons: list | None = None,
) -> dict:
    rows = [_p365_apply_stall_churn_reentry_cooldown(row) for row in list(rows or [])]
    rows = _p377_filter_rows_for_breakout_follow_through(rows)
    rows = [_p403_apply_late_day_entry_quality(row) for row in rows]
    rows = _p528_enforce_late_day_first_2k_sleeve_cap(rows)
    finalized = swing_contract_finalize(
        rows,
        config=_p333_swing_selection_contract_config(),
        max_new_entries=max_new_entries,
        global_block_reasons=global_block_reasons,
        sizing_truth_fn=_p300_executable_sizing_truth,
    )
    return _p385_sync_dollar_risk_add_slot_finalizer(finalized, max_new_entries=max_new_entries)

def _p414_sync_selected_from_current_eligible_contract_rows(
    finalizer: dict | None,
    *,
    max_new_entries: int,
) -> dict:
    out = dict(finalizer or {})
    rows = [
        dict(row or {})
        for row in list(out.get("rows") or [])
        if isinstance(row, dict)
    ]
    approved = [
        dict(row or {})
        for row in list(out.get("approved") or [])
        if isinstance(row, dict)
    ]
    selected = [
        dict(row or {})
        for row in list(out.get("selected") or [])
        if isinstance(row, dict)
    ]

    open_symbols = set(_p404_active_position_symbols_light())
    max_total = max(0, int(max_new_entries or 0))

    def _row_symbol(row: dict) -> str:
        return str((row or {}).get("symbol") or "").strip().upper()

    def _contract_approved(row: dict) -> bool:
        contract = dict((row or {}).get("swing_production_contract") or {})
        return bool(contract.get("approved"))

    selected_new_entry = [
        row for row in selected
        if _row_symbol(row) and _row_symbol(row) not in open_symbols
    ]
    selected_open_echo = [
        row for row in selected
        if _row_symbol(row) in open_symbols
    ]

    row_approved_new_entry = [
        row for row in rows
        if _row_symbol(row)
        and _row_symbol(row) not in open_symbols
        and _contract_approved(row)
    ]
    approved_new_entry = [
        row for row in approved
        if _row_symbol(row)
        and _row_symbol(row) not in open_symbols
        and _contract_approved(row)
    ]

    approved_by_symbol = {}
    for row in approved_new_entry + row_approved_new_entry:
        sym = _row_symbol(row)
        if sym and sym not in approved_by_symbol:
            approved_by_symbol[sym] = dict(row or {})

    approved_new_entry_raw = list(approved_by_symbol.values())
    approved_new_entry_checked = [
        _p443_apply_breakout_dollar_risk_containment(row)
        for row in approved_new_entry_raw
    ]
    approved_new_entry = [
        row for row in approved_new_entry_checked
        if not bool((row.get("breakout_dollar_risk_containment") or {}).get("applies"))
    ]
    p443_contained_rows = [
        row for row in approved_new_entry_checked
        if bool((row.get("breakout_dollar_risk_containment") or {}).get("applies"))
    ]

    approved_new_entry.sort(
        key=lambda row: (
            float(_safe_float(row.get("rank_score"), 0.0)),
            float(_safe_float(row.get("selection_quality_score"), 0.0)),
            float(_safe_float((row.get("target_path_profit") or {}).get("score") or row.get("target_path_score"), 0.0)),
        ),
        reverse=True,
    )

    applied = False
    reason = "selected_new_entry_already_present"

    if not selected_new_entry and approved_new_entry and max_total > 0:
        selected = approved_new_entry[:max_total]
        applied = True
        reason = "selected_rebuilt_from_current_approved_contract_rows"
    elif selected_open_echo and not selected_new_entry and not approved_new_entry:
        selected = []
        applied = True
        reason = "open_position_selection_echo_removed_no_current_approved_new_entry"
    elif selected_open_echo and selected_new_entry:
        selected = selected_new_entry[:max_total]
        applied = True
        reason = "open_position_selection_echo_removed_selected_new_entries_preserved"

    selected_symbols = {
        _row_symbol(row)
        for row in selected
        if _row_symbol(row)
    }

    p443_contained_by_symbol = {
        _row_symbol(row): dict(row or {})
        for row in p443_contained_rows
        if _row_symbol(row)
    }

    rebuilt_rows = []
    for row in rows:
        c = dict(row or {})
        sym = _row_symbol(c)
        if sym and sym in p443_contained_by_symbol:
            c = dict(p443_contained_by_symbol[sym])
        is_selected = bool(sym and sym in selected_symbols)
        c["selected"] = is_selected
        if is_selected:
            contract = dict(c.get("swing_production_contract") or {})
            checks = dict(contract.get("checks") or {})
            if bool(checks.get("first_2k_geometry_sleeve_ok")):
                c["entry_type"] = "swing_production_first_2k_geometry_sleeve"
                c["selected_source"] = "swing_production_first_2k_geometry_sleeve"
            elif bool(checks.get("near_rank_revival_ok")):
                c["entry_type"] = "swing_production_near_rank_revival"
                c["selected_source"] = "swing_production_near_rank_revival"
                c["near_rank_revival_applied"] = True
            elif bool(checks.get("risk_calibrated_starter_ok")):
                c["entry_type"] = "swing_production_risk_calibrated_starter"
                c["selected_source"] = "swing_production_risk_calibration"
                c["risk_calibration_applied"] = True
            else:
                c["entry_type"] = "swing_production_contract"
                c["selected_source"] = "swing_production_reset"
            c["selection_finalizer"] = "p436_eligible_sleeve_selection_finalizer"
        rebuilt_rows.append(c)

    selected_final = []
    by_symbol = {
        _row_symbol(row): dict(row or {})
        for row in rebuilt_rows
        if _row_symbol(row)
    }
    for row in selected:
        sym = _row_symbol(row)
        if sym and sym in by_symbol:
            selected_final.append(by_symbol[sym])
        elif sym:
            selected_final.append(dict(row or {}))

    selected_symbols_final = [
        _row_symbol(row)
        for row in selected_final
        if _row_symbol(row)
    ]

    out["rows"] = rebuilt_rows
    out["selected"] = selected_final
    out["selected_symbols"] = selected_symbols_final
    out["selected_count"] = len(selected_final)
    out["p436_eligible_sleeve_selection_finalizer"] = {
        "applied": bool(applied),
        "reason": reason,
        "max_new_entries": max_total,
        "open_position_echo_symbols": [
            _row_symbol(row)
            for row in selected_open_echo
            if _row_symbol(row)
        ],
        "approved_new_entry_count": len(approved_new_entry),
        "approved_new_entry_symbols": [
            _row_symbol(row)
            for row in approved_new_entry
            if _row_symbol(row)
        ],
        "p443_breakout_dollar_risk_containment": {
            "enabled": bool(SWING_BREAKOUT_DOLLAR_RISK_CONTAINMENT_ENABLED),
            "max_dollar_risk": float(SWING_BREAKOUT_DOLLAR_RISK_MAX_DOLLARS or 0.0),
            "contained_count": len(p443_contained_rows),
            "contained_symbols": [
                _row_symbol(row)
                for row in p443_contained_rows
                if _row_symbol(row)
            ],
        },
        "row_approved_new_entry_count": len(row_approved_new_entry),
        "row_approved_new_entry_symbols": [
            _row_symbol(row)
            for row in row_approved_new_entry
            if _row_symbol(row)
        ],
        "selected_symbols": selected_symbols_final,
    }
    return out

def _p344_sync_selected_from_approved_finalizer(
    finalizer: dict | None,
    *,
    max_new_entries: int,
) -> dict:
    out = dict(finalizer or {})
    rows = [dict(r or {}) for r in list(out.get("rows") or []) if isinstance(r, dict)]
    approved = [dict(r or {}) for r in list(out.get("approved") or []) if isinstance(r, dict)]
    selected = [dict(r or {}) for r in list(out.get("selected") or []) if isinstance(r, dict)]

    max_total = max(0, int(max_new_entries or 0))
    if not selected and approved and max_total > 0:
        selected = approved[:max_total]
        out["p344_selected_sync_applied"] = True
        out["p344_selected_sync_reason"] = "approved_rows_present_but_finalizer_selected_empty"
    else:
        out["p344_selected_sync_applied"] = False
        out["p344_selected_sync_reason"] = "finalizer_selection_already_consistent"

    selected_symbols = {
        str((row or {}).get("symbol") or "").strip().upper()
        for row in selected
        if str((row or {}).get("symbol") or "").strip()
    }

    rebuilt_rows = []
    for row in rows:
        c = dict(row or {})
        sym = str(c.get("symbol") or "").strip().upper()
        is_selected = bool(sym and sym in selected_symbols)
        c["selected"] = is_selected
        if is_selected:
            contract = dict(c.get("swing_production_contract") or {})
            checks = dict(contract.get("checks") or {})
            if bool(checks.get("near_rank_revival_ok")):
                c["entry_type"] = "swing_production_near_rank_revival"
                c["selected_source"] = "swing_production_near_rank_revival"
                c["near_rank_revival_applied"] = True
            elif bool(checks.get("risk_calibrated_starter_ok")):
                c["entry_type"] = "swing_production_risk_calibrated_starter"
                c["selected_source"] = "swing_production_risk_calibration"
                c["risk_calibration_applied"] = True
            elif bool(checks.get("dollar_risk_add_slot_ok")):
                c["entry_type"] = "swing_production_dollar_risk_add_slot"
                c["selected_source"] = "swing_production_dollar_risk_add_slot"
                c["dollar_risk_add_slot_selected"] = True
            else:
                c["entry_type"] = "swing_production_contract"
                c["selected_source"] = "swing_production_reset"
            c["selection_finalizer"] = "p344_approved_candidate_final_selection_sync"
        rebuilt_rows.append(c)

    selected_by_symbol = {
        str((row or {}).get("symbol") or "").strip().upper(): dict(row or {})
        for row in rebuilt_rows
        if str((row or {}).get("symbol") or "").strip().upper() in selected_symbols
    }
    selected_final = [
        selected_by_symbol.get(str((row or {}).get("symbol") or "").strip().upper(), dict(row or {}))
        for row in selected
        if str((row or {}).get("symbol") or "").strip()
    ]

    out["rows"] = rebuilt_rows
    out["selected"] = selected_final
    out["selected_symbols"] = [
        str((row or {}).get("symbol") or "").strip().upper()
        for row in selected_final
        if str((row or {}).get("symbol") or "").strip()
    ]
    out["selected_count"] = len(selected_final)
    return out

def _p300_executable_sizing_audit(limit: int = 25) -> dict:
    latest_scan, summary = _p298_latest_scan_summary_light()
    rows = list(summary.get("top_candidates") or summary.get("items") or LAST_SWING_CANDIDATES or [])
    checked = [_p300_apply_executable_selection_contract(dict(r or {})) for r in rows if isinstance(r, dict)]
    selected_symbols = [
        str(s or "").strip().upper()
        for s in list(summary.get("selected_symbols") or [])
        if str(s or "").strip()
    ]
    broken_selected = [
        r for r in checked
        if str(r.get("symbol") or "").strip().upper() in selected_symbols
        and not bool((r.get("executable_sizing_truth") or {}).get("executable"))
    ]

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "executable_sizing_truth_audit",
        "latest_scan_ts_utc": latest_scan.get("ts_utc"),
        "latest_scan_reason": latest_scan.get("reason"),
        "selected_symbols": selected_symbols,
        "broken_selected_symbols": [r.get("symbol") for r in broken_selected],
        "broken_selected_count": len(broken_selected),
        "zero_qty_symbols": [
            r.get("symbol")
            for r in checked
            if float((r.get("executable_sizing_truth") or {}).get("effective_estimated_qty") or 0.0) <= 0
        ],
        "misleading_buying_power_labels": [
            r.get("symbol")
            for r in checked
            if "insufficient_buying_power" in list(r.get("rejection_reasons") or [])
            and not bool((r.get("executable_sizing_truth") or {}).get("broker_buying_power_label_valid"))
        ],
        "rows": [
            {
                "symbol": r.get("symbol"),
                "eligible": bool(r.get("eligible")),
                "selected": str(r.get("symbol") or "").strip().upper() in selected_symbols,
                "rank_score": r.get("rank_score"),
                "estimated_qty": r.get("estimated_qty"),
                "requested_qty": r.get("requested_qty"),
                "rejection_reasons": list(r.get("rejection_reasons") or []),
                "executable_sizing_truth": r.get("executable_sizing_truth"),
            }
            for r in checked[: max(1, min(int(limit or 25), 50))]
        ],
        "recommended_action": (
            "fix_selection_contract_before_forcing_entries"
            if broken_selected
            else "selection_contract_clean"
        ),
    }



def _p301_executable_near_miss_decision(candidate: dict | None, daily_goal_progress: dict | None = None) -> dict:
    c = dict(candidate or {})
    reasons = _dedupe_candidate_reasons(c.get("rejection_reasons") or [])
    sizing = dict(c.get("executable_sizing_truth") or _p300_executable_sizing_truth(c))
    target_path = dict(c.get("target_path_profit") or {})
    daily_goal = dict(daily_goal_progress or _p295_broker_daily_goal_progress() or {})

    symbol = str(c.get("symbol") or "").strip().upper()
    rank_score = float(_safe_float(c.get("rank_score") or 0.0))
    target_score = float(_safe_float(target_path.get("score") or c.get("target_path_score") or 0.0))
    risk_pct = float(_safe_float(c.get("risk_per_share_pct") or 0.0)) / 100.0

    allowed_reasons = {
        "target_profile_breakout_gate",
        "defensive_risk_per_share_too_wide",
        "defensive_daily_breakout_rollback",
        "rank_score_below_min",
    }
    hard_blockers = {
        "internal_sizing_qty_zero",
        "broker_insufficient_buying_power",
        "insufficient_buying_power",
        "daily_halt_active",
        "daily_stop_hit",
        "kill_switch_enabled",
        "plan_or_pending_entry_exists",
        "position_already_open",
        "pending_order_entry_freeze",
        "same_day_symbol_loss_cooldown",
        "strategy_kill_switch_active",
        "correlation_group_limit",
        "symbol_exposure_limit",
        "portfolio_exposure_limit",
        "portfolio_already_over_cap_total",
        "portfolio_already_over_cap_strategy",
        "swing_post_change_drawdown_circuit",
        "swing_loss_day_entry_throttle",
        "stall_loss_entry_feedback",
    }

    disallowed_reasons = sorted([r for r in reasons if r not in allowed_reasons])
    hard_present = sorted([r for r in reasons if r in hard_blockers])

    daily_goal_ok = True
    if bool(SWING_EXECUTABLE_NEAR_MISS_REQUIRE_DAILY_GOAL_BELOW_LOW):
        daily_goal_ok = not bool(daily_goal.get("low_target_hit"))

    blockers = []
    if not bool(SWING_EXECUTABLE_NEAR_MISS_ENTRY_ENABLED):
        blockers.append("near_miss_sleeve_disabled")
    if not bool(sizing.get("executable")):
        blockers.append("not_executable")
    if hard_present:
        blockers.append("hard_blocker_present")
    if disallowed_reasons:
        blockers.append("disallowed_rejection_reason")
    if rank_score < float(SWING_EXECUTABLE_NEAR_MISS_MIN_RANK_SCORE):
        blockers.append("rank_score_below_near_miss_min")
    if target_score < float(SWING_EXECUTABLE_NEAR_MISS_MIN_TARGET_PATH_SCORE):
        blockers.append("target_path_score_below_near_miss_min")
    if risk_pct > float(SWING_EXECUTABLE_NEAR_MISS_MAX_RISK_PER_SHARE_PCT):
        blockers.append("risk_per_share_above_near_miss_cap")
    if not daily_goal_ok:
        blockers.append("daily_goal_low_already_hit")

    applies = not blockers
    return {
        "enabled": bool(SWING_EXECUTABLE_NEAR_MISS_ENTRY_ENABLED),
        "applies": applies,
        "symbol": symbol,
        "blockers": blockers,
        "original_rejection_reasons": reasons,
        "allowed_reasons": sorted(allowed_reasons),
        "hard_blockers": hard_present,
        "disallowed_reasons": disallowed_reasons,
        "rank_score": round(rank_score, 4),
        "min_rank_score": float(SWING_EXECUTABLE_NEAR_MISS_MIN_RANK_SCORE),
        "target_path_score": round(target_score, 4),
        "min_target_path_score": float(SWING_EXECUTABLE_NEAR_MISS_MIN_TARGET_PATH_SCORE),
        "risk_per_share_pct": round(risk_pct, 5),
        "max_risk_per_share_pct": float(SWING_EXECUTABLE_NEAR_MISS_MAX_RISK_PER_SHARE_PCT),
        "daily_goal_ok": bool(daily_goal_ok),
        "daily_goal_progress": daily_goal,
        "executable_sizing_truth": sizing,
        "reason": "near_miss_entry_approved" if applies else ",".join(blockers),
    }


def _p301_apply_executable_near_miss_entry(candidate: dict | None, daily_goal_progress: dict | None = None) -> dict:
    c = dict(candidate or {})
    decision = _p301_executable_near_miss_decision(c, daily_goal_progress=daily_goal_progress)
    c["executable_near_miss_entry"] = decision

    if decision.get("applies"):
        c["eligible"] = True
        c["entry_type"] = "executable_near_miss"
        c["selected_source"] = "executable_near_miss_sleeve"
        c["near_miss_original_rejection_reasons"] = list(c.get("rejection_reasons") or [])
        c["rejection_reasons"] = []
        c["selection_blockers"] = []
    return c

def _p397_selected_submit_bridge_truth(selected_rows: list | None, submit_rows: list | None) -> dict:
    selected_symbols = _dedupe_keep_order([
        str((row or {}).get("symbol") or "").strip().upper()
        for row in list(selected_rows or [])
        if str((row or {}).get("symbol") or "").strip()
    ])
    submit_symbols = _dedupe_keep_order([
        str((row or {}).get("symbol") or "").strip().upper()
        for row in list(submit_rows or [])
        if str((row or {}).get("symbol") or "").strip()
    ])
    submit_symbol_set = set(submit_symbols)
    missing_submit_symbols = [
        sym for sym in selected_symbols
        if sym not in submit_symbol_set
    ]
    return {
        "ok": True,
        "selected_symbols": selected_symbols,
        "submit_symbols": submit_symbols,
        "missing_submit_symbols": missing_submit_symbols,
        "missing_submit_count": len(missing_submit_symbols),
        "bridge_complete": len(missing_submit_symbols) == 0,
        "read": (
            "production_selected_submit_bridge_complete"
            if not missing_submit_symbols
            else "production_selected_without_submit_row"
        ),
    }

def _p302_fast_swing_scan_trigger(apply: bool = False, finalize: bool = True, limit: int = 25) -> dict:
    latest_scan, summary = _p298_latest_scan_summary_light()
    generated_utc = datetime.now(timezone.utc).isoformat()

    rows = _p300_selection_contract_cleanup(
        list(summary.get("top_candidates") or summary.get("items") or LAST_SWING_CANDIDATES or [])
    )
    daily_goal_progress = _p295_broker_daily_goal_progress()

    scan_ts = str(latest_scan.get("ts_utc") or "")
    scan_age_sec = None
    scan_fresh_enough = False
    try:
        if scan_ts:
            dt = datetime.fromisoformat(scan_ts)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            scan_age_sec = max(0.0, (datetime.now(timezone.utc) - dt.astimezone(timezone.utc)).total_seconds())
            scan_fresh_enough = scan_age_sec <= float(SWING_FAST_SCAN_TRIGGER_MAX_SCAN_AGE_SEC)
    except Exception:
        scan_age_sec = None
        scan_fresh_enough = False

    blockers = []
    if not bool(SWING_FAST_SCAN_TRIGGER_ENABLED):
        blockers.append("fast_scan_trigger_disabled")
    if not bool(in_market_hours()):
        blockers.append("market_closed")
    if not bool(LIVE_TRADING_ENABLED):
        blockers.append("live_trading_disabled")
    if bool(DRY_RUN):
        blockers.append("dry_run_enabled")
    if not bool(SCANNER_ALLOW_LIVE):
        blockers.append("scanner_live_not_allowed")
    if bool(SCANNER_DRY_RUN):
        blockers.append("scanner_dry_run_enabled")
    if bool(KILL_SWITCH):
        blockers.append("kill_switch_enabled")
    if bool(daily_halt_active()) or bool(daily_stop_hit()):
        blockers.append("daily_halt_or_stop_active")
    if not scan_fresh_enough:
        blockers.append("latest_scan_too_stale")
    if not rows:
        blockers.append("no_cached_candidate_rows")

    candidates = []
    for row in rows:
        candidate = _p301_apply_executable_near_miss_entry(
            row,
            daily_goal_progress=daily_goal_progress,
        )
        if bool((candidate.get("executable_near_miss_entry") or {}).get("applies")):
            candidates.append(candidate)

    candidates.sort(
        key=lambda x: (
            float(_safe_float((x.get("target_path_profit") or {}).get("score") or x.get("target_path_score") or 0.0)),
            float(_safe_float(x.get("selection_quality_score") or 0.0)),
            float(_safe_float(x.get("rank_score") or 0.0)),
        ),
        reverse=True,
    )

    selected = candidates[:1]
    if not selected:
        blockers.append("no_executable_near_miss_candidate")

    rows_out = []
    queued = []
    finalizer = None

    can_apply = bool(apply) and not blockers
    for candidate in selected:
        sym = str(candidate.get("symbol") or "").strip().upper()
        side_effect = _p297_symbol_entry_side_effect(sym)
        row = {
            "symbol": sym,
            "action": "inspect",
            "side_effect_before": side_effect,
            "candidate": {
                "symbol": sym,
                "signal": candidate.get("signal"),
                "rank_score": candidate.get("rank_score"),
                "target_path_score": (candidate.get("target_path_profit") or {}).get("score") or candidate.get("target_path_score"),
                "estimated_qty": candidate.get("estimated_qty"),
                "entry_type": candidate.get("entry_type"),
                "near_miss_original_rejection_reasons": list(candidate.get("near_miss_original_rejection_reasons") or []),
                "executable_near_miss_entry": candidate.get("executable_near_miss_entry"),
                "executable_sizing_truth": candidate.get("executable_sizing_truth"),
            },
        }

        if bool(side_effect.get("side_effect_detected")):
            row["action"] = "skip_side_effect_exists"
            rows_out.append(row)
            continue

        if not can_apply:
            row["action"] = "would_queue"
            rows_out.append(row)
            continue

        meta = {
            "fast_swing_scan_trigger": True,
            "fast_swing_scan_patch": PATCH_VERSION,
            "latest_scan_ts_utc": latest_scan.get("ts_utc"),
            "latest_scan_reason": latest_scan.get("reason"),
            "executable_near_miss_entry": candidate.get("executable_near_miss_entry"),
            "near_miss_original_rejection_reasons": list(candidate.get("near_miss_original_rejection_reasons") or []),
            "rank_score": candidate.get("rank_score"),
            "selection_quality_score": candidate.get("selection_quality_score"),
            "target_path_score": (candidate.get("target_path_profit") or {}).get("score") or candidate.get("target_path_score"),
            "risk_per_share": candidate.get("risk_per_share"),
            "risk_per_share_pct": candidate.get("risk_per_share_pct"),
            "stop_price": candidate.get("stop_price"),
            "target_price": candidate.get("target_price"),
            "close": candidate.get("close"),
            "avg_dollar_volume_20d": candidate.get("avg_dollar_volume_20d"),
            "close_to_high_pct": candidate.get("close_to_high_pct"),
            "breakout_distance_pct": candidate.get("breakout_distance_pct"),
            "return_20d_pct": candidate.get("return_20d_pct"),
            "strategy_name": candidate.get("strategy") or candidate.get("signal") or "daily_breakout",
            "entry_type": "executable_near_miss",
        }

        queue_result = _p299_queue_selected_entry_intent(
            candidate,
            meta=meta,
            source_name="fast_swing_scan_trigger",
            live_allowed=True,
        )
        queued.append(queue_result)
        row["action"] = "queued"
        row["queue_result"] = queue_result
        rows_out.append(row)

    if can_apply and bool(finalize):
        finalizer = _p299_finalize_selected_entry_intents(
            apply=True,
            max_items=max(1, min(int(SWING_FAST_SCAN_TRIGGER_MAX_FINALIZE or 1), 5)),
        )

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "main_web_fast_swing_scan_trigger",
        "generated_utc": generated_utc,
        "applied": bool(apply),
        "finalize": bool(finalize),
        "can_apply": bool(can_apply),
        "blockers": blockers,
        "latest_scan": {
            "ts_utc": latest_scan.get("ts_utc"),
            "reason": latest_scan.get("reason"),
            "age_sec": round(scan_age_sec, 2) if scan_age_sec is not None else None,
            "fresh_enough": bool(scan_fresh_enough),
            "scanned": latest_scan.get("scanned"),
            "signals": latest_scan.get("signals"),
            "would_trade": latest_scan.get("would_trade"),
            "blocked": latest_scan.get("blocked"),
            "duration_ms": latest_scan.get("duration_ms"),
        },
        "daily_goal_progress": daily_goal_progress,
        "candidate_count": len(candidates),
        "candidate_symbols": [c.get("symbol") for c in candidates],
        "selected_symbols": [c.get("symbol") for c in selected],
        "queued": queued,
        "rows": rows_out[: max(1, min(int(limit or 25), 50))],
        "finalizer": finalizer,
        "queue": _p299_selected_entry_finalizer_status(),
        "recommended_action": (
            "apply_true_available"
            if candidates and not apply and not blockers
            else "queued_and_finalizer_ran"
            if can_apply and finalizer
            else "blocked_review_reasons"
            if blockers
            else "no_candidate_available"
        ),
    }

def _same_day_entry_stats() -> dict:
    today = now_ny().date()
    counted = 0
    skipped_recovered = 0
    recovered_counted_as_strategy = 0
    skipped_inactive = 0
    skipped_not_today = 0
    items = []

    try:
        broker_positions = list(list_open_positions_details_allowed() or [])
    except Exception:
        broker_positions = []

    broker_by_symbol = {
        str((p or {}).get("symbol") or "").upper(): dict(p or {})
        for p in broker_positions
        if str((p or {}).get("symbol") or "").strip()
    }

    for symbol, plan in (TRADE_PLAN or {}).items():
        sym = str(symbol or "").upper()
        p = plan or {}
        active = bool(p.get("active"))
        signal = str(p.get("signal") or "")
        recovered = _plan_is_recovered(p)
        recovered_counts_as_strategy = _p254_recovered_broker_backed_counts_as_strategy(sym, p, broker_by_symbol)
        dt = _parse_plan_opened_dt(p)
        opened_today = bool(dt and dt.date() == today)
        counted_here = False

        if not active:
            skipped_inactive += 1
        elif not opened_today:
            skipped_not_today += 1
        elif recovered and not recovered_counts_as_strategy:
            skipped_recovered += 1
        else:
            counted += 1
            counted_here = True
            if recovered_counts_as_strategy:
                recovered_counted_as_strategy += 1

        items.append({
            "symbol": sym,
            "active": active,
            "recovered": recovered,
            "recovered_counted_as_strategy": recovered_counts_as_strategy,
            "broker_backed": sym in broker_by_symbol,
            "signal": signal,
            "strategy_name": str(p.get("strategy_name") or ""),
            "opened_at": dt.isoformat() if dt else None,
            "opened_today": opened_today,
            "counted": counted_here,
        })

    return {
        "today_ny": today.isoformat(),
        "counted": counted,
        "total_active": sum(1 for plan in (TRADE_PLAN or {}).values() if bool((plan or {}).get("active"))),
        "recovered_counted_as_strategy": recovered_counted_as_strategy,
        "skipped_recovered": skipped_recovered,
        "skipped_inactive": skipped_inactive,
        "skipped_not_today": skipped_not_today,
        "classification_source": "broker_backed_corrected",
        "items": items[:50],
    }

def _same_day_entry_count() -> int:
    return int((_same_day_entry_stats() or {}).get("counted") or 0)


def _early_entry_override_count_today() -> int:
    today = now_ny().date()
    count = 0
    events = list(PAPER_LIFECYCLE_HISTORY or [])
    if LAST_PAPER_LIFECYCLE and (not events or events[-1] != LAST_PAPER_LIFECYCLE):
        events.append(dict(LAST_PAPER_LIFECYCLE))
    for ev in events:
        row = dict(ev or {})
        if str(row.get("stage") or "").strip().lower() != "entry":
            continue
        if str(row.get("status") or "").strip().lower() not in {"planned", "submitted", "filled"}:
            continue
        try:
            ts_ny = datetime.fromisoformat(str(row.get("ts_ny") or row.get("ts_utc")))
            if ts_ny.tzinfo is None:
                ts_ny = ts_ny.replace(tzinfo=timezone.utc).astimezone(NY_TZ)
            else:
                ts_ny = ts_ny.astimezone(NY_TZ)
        except Exception:
            continue
        if ts_ny.date() != today:
            continue
        details = dict(row.get("details") or {})
        if str(details.get("entry_type") or "").strip().lower() != "early_override":
            continue
        count += 1
    return count


def _candidate_qualifies_early_entry_override(candidate: dict | None, regime: dict | None = None) -> tuple[bool, list[str]]:
    c = dict(candidate or {})
    reasons: list[str] = []
    if not SWING_EARLY_ENTRY_OVERRIDE_ENABLED:
        reasons.append("disabled")
    if str(c.get("strategy") or "").strip().lower() != BREAKOUT_STRATEGY_NAME:
        reasons.append("strategy_not_breakout")
    if not bool(c.get("eligible")):
        reasons.append("candidate_not_eligible")
    if SWING_EARLY_ENTRY_OVERRIDE_ONLY_WHEN_REGIME_UNFAVORABLE and bool((regime or {}).get("favorable")):
        reasons.append("regime_not_unfavorable")
    if _safe_float(c.get("rank_score")) < float(SWING_EARLY_ENTRY_OVERRIDE_MIN_RANK_SCORE):
        reasons.append("rank_below_threshold")
    if (_safe_float(c.get("close_to_high_pct")) / 100.0) < float(SWING_EARLY_ENTRY_OVERRIDE_MIN_CLOSE_TO_HIGH_PCT):
        reasons.append("close_not_strong_enough")
    if (_safe_float(c.get("range_pct")) / 100.0) < float(SWING_EARLY_ENTRY_OVERRIDE_MIN_RANGE_PCT):
        reasons.append("range_below_threshold")
    if ((_safe_float(c.get("return_20d_pct")) if c.get("return_20d_pct") is not None else -999.0) / 100.0) < float(SWING_EARLY_ENTRY_OVERRIDE_MIN_20D_RETURN_PCT):
        reasons.append("return_20d_below_threshold")
    return (len(reasons) == 0, reasons)


def _early_entry_override_live_permitted(candidate: dict | None, regime: dict | None = None) -> tuple[bool, list[str]]:
    reasons: list[str] = []
    if not SWING_EARLY_ENTRY_OVERRIDE_ENABLED:
        reasons.append("disabled")
        return False, reasons
    if str(SYSTEM_RELEASE_STAGE or "").strip().lower() != "live_guarded":
        reasons.append("release_stage_not_live_guarded")
    if DRY_RUN or (not LIVE_TRADING_ENABLED) or SCANNER_DRY_RUN or (not SCANNER_ALLOW_LIVE):
        reasons.append("live_path_disabled")
    ok, candidate_reasons = _candidate_qualifies_early_entry_override(candidate, regime=regime)
    if not ok:
        reasons.extend(candidate_reasons)
    gate = release_gate_status()
    if bool(gate.get("live_orders_permitted")):
        reasons.append("normal_live_path_already_permitted")
    unmet = {str(x) for x in (gate.get("unmet_conditions") or []) if str(x)}
    if not unmet:
        reasons.append("no_override_needed")
    elif not unmet.issubset({"regime_not_favorable"}):
        reasons.append("non_regime_gate_blockers_present")
    if _early_entry_override_count_today() >= max(0, int(SWING_EARLY_ENTRY_OVERRIDE_MAX_NEW_ENTRIES_PER_DAY)):
        reasons.append("daily_override_limit_reached")
    return (len(reasons) == 0), reasons


def _plan_is_pending_entry(plan: dict | None) -> bool:
    p = dict(plan or {})
    if not p:
        return False
    status = str(p.get("order_status") or "").lower()
    exec_state = str(p.get("execution_state") or p.get("lifecycle_state") or "").lower()
    active_order_statuses = {"submitted", "new", "accepted", "pending_new", "partially_filled", "accepted_for_bidding", "held", "pending_replace"}
    active_exec_states = {"submitted", "acknowledged", "partially_filled"}
    return status in active_order_statuses or exec_state in active_exec_states


def _has_pending_entry_plan(symbol: str) -> bool:
    p = (TRADE_PLAN or {}).get(str(symbol or "").upper()) or {}
    if not p:
        return False
    if bool(p.get("active")):
        return True
    return _plan_is_pending_entry(p)


# Run startup restore only after all helper functions it depends on are defined.


def _normalize_correlation_groups_raw(raw: str) -> str:
    raw_s = str(raw or '').replace("\r", "\n")
    raw_s = raw_s.replace("\n", "|").replace(";", "|")
    raw_s = re.sub(r"\s*\|\s*", "|", raw_s)
    raw_s = re.sub(r"\s*,\s*", ",", raw_s)
    raw_s = re.sub(r"\|{2,}", "|", raw_s)
    return raw_s.strip(" |,\t")


def _parse_correlation_groups(raw: str) -> dict[str, int]:
    mapping: dict[str, int] = {}
    normalized = _normalize_correlation_groups_raw(raw)
    groups = [g.strip() for g in normalized.split('|') if g.strip()]
    for idx, group in enumerate(groups, start=1):
        for sym in [s.strip().upper() for s in group.split(',') if s.strip()]:
            mapping[sym] = idx
    return mapping


def _correlation_groups_list(raw: str | None = None) -> list[list[str]]:
    normalized = _normalize_correlation_groups_raw(raw if raw is not None else SWING_CORRELATION_GROUPS)
    out: list[list[str]] = []
    for group in [g.strip() for g in normalized.split('|') if g.strip()]:
        syms = [s.strip().upper() for s in group.split(',') if s.strip()]
        if syms:
            out.append(syms)
    return out


def _symbol_group_id(symbol: str) -> int | None:
    return _parse_correlation_groups(SWING_CORRELATION_GROUPS).get(str(symbol or '').upper())


def _open_group_position_count(symbol: str) -> int:
    gid = _symbol_group_id(symbol)
    if gid is None:
        return 0
    count = 0
    seen = set()
    for p in list_open_positions_details_allowed():
        sym = str((p or {}).get('symbol') or '').upper()
        if not sym or sym in seen:
            continue
        if _symbol_group_id(sym) == gid:
            count += 1
            seen.add(sym)
    for sym, plan in (TRADE_PLAN or {}).items():
        s = str(sym or '').upper()
        if not s or s in seen:
            continue
        if isinstance(plan, dict) and plan.get('active') and _symbol_group_id(s) == gid:
            count += 1
            seen.add(s)
    return count


def _build_swing_regime(index_bars: list[dict], daily_map: dict[str, list[dict]], symbols: list[str]) -> dict:
    closes = [_safe_float(b.get('close')) for b in (index_bars or []) if _safe_float(b.get('close'))]
    idx_close = closes[-1] if closes else None
    idx_fast = _sma(closes, SWING_REGIME_FAST_MA_DAYS) if closes else None
    idx_slow = _sma(closes, SWING_REGIME_SLOW_MA_DAYS) if closes else None
    index_trend_ok = bool(idx_close and idx_fast and idx_slow and idx_close > idx_fast > idx_slow) if idx_close and idx_fast and idx_slow else None
    breadth_total = 0
    breadth_pass = 0
    ret_pass = 0
    ret_lookback = max(2, int(REGIME_BREADTH_RETURN_LOOKBACK_DAYS))
    min_seq_needed = max(SWING_REGIME_SLOW_MA_DAYS + 1, ret_lookback + 1)
    for sym in (symbols or []):
        bars = daily_map.get(sym, []) or []
        seq = [_safe_float(b.get('close')) for b in bars if _safe_float(b.get('close'))]
        if len(seq) < min_seq_needed:
            continue
        breadth_total += 1
        slow = _sma(seq, SWING_REGIME_SLOW_MA_DAYS)
        if slow and seq[-1] > slow:
            breadth_pass += 1
        ref = seq[-(ret_lookback + 1)]
        if ref > 0 and (seq[-1] / ref - 1.0) > 0:
            ret_pass += 1
    breadth = (breadth_pass / breadth_total) if breadth_total else None
    ret_breadth = (ret_pass / breadth_total) if breadth_total else None
    data_complete = bool(index_trend_ok is not None and breadth is not None and breadth_total >= REGIME_MIN_SYMBOLS_FOR_BREADTH)
    favorable = None
    reasons = []
    if SWING_REGIME_FILTER_ENABLED:
        if index_trend_ok is None:
            reasons.append('index_trend_unknown')
        if breadth is None or breadth_total < REGIME_MIN_SYMBOLS_FOR_BREADTH:
            reasons.append('breadth_unknown')
        if REGIME_REQUIRE_COMPLETE_DATA and not data_complete:
            favorable = None
        elif index_trend_ok is False:
            favorable = False
            reasons.append('index_trend_weak')
        elif breadth is not None and breadth < SWING_REGIME_MIN_BREADTH:
            favorable = False
            reasons.append('breadth_below_min')
        elif index_trend_ok is True and breadth is not None:
            favorable = True
        else:
            favorable = None
    else:
        favorable = True
    score = 0.0
    if index_trend_ok is True:
        score += 50.0
    if breadth is not None:
        score += max(0.0, min(30.0, breadth * 30.0))
    if ret_breadth is not None:
        score += max(0.0, min(20.0, ret_breadth * 20.0))
    return {
        'ts_utc': datetime.now(timezone.utc).isoformat(),
        'enabled': SWING_REGIME_FILTER_ENABLED,
        'index_symbol': SWING_INDEX_SYMBOL,
        'index_close': round(idx_close, 4) if idx_close else None,
        'index_fast_ma': round(idx_fast, 4) if idx_fast else None,
        'index_slow_ma': round(idx_slow, 4) if idx_slow else None,
        'index_trend_ok': index_trend_ok,
        'breadth': round(breadth, 4) if breadth is not None else None,
        'ret_breadth': round(ret_breadth, 4) if ret_breadth is not None else None,
        'breadth_total': int(breadth_total),
        'favorable': favorable,
        'score': round(score, 2),
        'reasons': reasons,
        'data_complete': data_complete,
    }


def _get_regime_mode(regime: dict | None = None, index_alignment_ok: bool | None = None) -> str:
    regime = dict(regime or {})
    favorable = regime.get("favorable")
    data_complete = bool(regime.get("data_complete"))
    if favorable is True and (index_alignment_ok is not False):
        return "trend"
    breadth = _safe_float(regime.get("breadth_pct"))
    range_ok = False
    if breadth is not None:
        range_ok = breadth >= max(0.0, SWING_REGIME_MIN_BREADTH * 0.75)
    if data_complete and favorable is not True and range_ok:
        return "neutral"
    return "defensive"


def _regime_mode_thresholds(mode: str) -> dict:
    mode = str(mode or "trend").strip().lower()
    if mode == "neutral":
        return {
            "mode": "neutral",
            "breakout_max_distance_pct": float(SWING_NEUTRAL_BREAKOUT_MAX_DISTANCE_PCT),
            "close_to_high_min_pct": float(SWING_NEUTRAL_MIN_CLOSE_TO_HIGH_PCT),
            "return_20d_min_pct": float(SWING_NEUTRAL_MIN_20D_RETURN_PCT),
            "require_trend": False,
            "require_index_alignment": bool(SWING_NEUTRAL_REQUIRE_INDEX_ALIGNMENT),
            "allow_entries_when_regime_unfavorable": True,
        }
    if mode == "defensive":
        return {
            "mode": "defensive",
            "breakout_max_distance_pct": float(SWING_DEFENSIVE_BREAKOUT_MAX_DISTANCE_PCT),
            "close_to_high_min_pct": float(SWING_DEFENSIVE_MIN_CLOSE_TO_HIGH_PCT),
            "return_20d_min_pct": float(SWING_DEFENSIVE_MIN_20D_RETURN_PCT),
            "require_trend": False,
            "require_index_alignment": bool(SWING_REGIME_DEFENSIVE_REQUIRE_INDEX_ALIGNMENT),
            "allow_entries_when_regime_unfavorable": bool(SWING_REGIME_MODE_ALLOW_DEFENSIVE_ENTRIES),
        }
    return {
        "mode": "trend",
        "breakout_max_distance_pct": float(SWING_TREND_BREAKOUT_MAX_DISTANCE_PCT),
        "close_to_high_min_pct": float(SWING_TREND_MIN_CLOSE_TO_HIGH_PCT),
        "return_20d_min_pct": float(SWING_TREND_MIN_20D_RETURN_PCT),
        "require_trend": True,
        "require_index_alignment": True,
        "allow_entries_when_regime_unfavorable": bool(SWING_ALLOW_NEW_ENTRIES_IN_WEAK_TAPE),
    }

def _p275_defensive_breakout_tier_gate(candidate: dict | None) -> dict:
    row = dict(candidate or {})
    rank_score = _safe_float(row.get("rank_score"))
    close_to_high_pct = _safe_float(row.get("close_to_high_pct")) / 100.0
    breakout_distance_pct = _safe_float(row.get("breakout_distance_pct")) / 100.0
    risk_per_share_pct = _safe_float(row.get("risk_per_share_pct")) / 100.0

    checks = [
        {
            "name": "rank_score",
            "ok": rank_score >= float(SWING_DEFENSIVE_BREAKOUT_TIER_MIN_RANK_SCORE),
            "value": round(rank_score, 4),
            "min": float(SWING_DEFENSIVE_BREAKOUT_TIER_MIN_RANK_SCORE),
        },
        {
            "name": "close_to_high",
            "ok": close_to_high_pct >= float(SWING_DEFENSIVE_BREAKOUT_TIER_MIN_CLOSE_TO_HIGH_PCT),
            "value": round(close_to_high_pct, 5),
            "min": float(SWING_DEFENSIVE_BREAKOUT_TIER_MIN_CLOSE_TO_HIGH_PCT),
        },
        {
            "name": "breakout_extension",
            "ok": breakout_distance_pct <= float(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_BREAKOUT_EXTENSION_PCT),
            "value": round(breakout_distance_pct, 5),
            "max": float(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_BREAKOUT_EXTENSION_PCT),
        },
        {
            "name": "risk_per_share",
            "ok": risk_per_share_pct <= float(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_RISK_PER_SHARE_PCT),
            "value": round(risk_per_share_pct, 5),
            "max": float(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_RISK_PER_SHARE_PCT),
        },
    ]
    blockers = [str(c.get("name")) for c in checks if not c.get("ok")]
    return {
        "enabled": bool(SWING_DEFENSIVE_BREAKOUT_TIER_GATE_ENABLED),
        "passed": bool(SWING_DEFENSIVE_BREAKOUT_TIER_GATE_ENABLED and not blockers),
        "blockers": blockers,
        "checks": checks,
        "max_new_entries_per_scan": int(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_NEW_ENTRIES_PER_SCAN),
    }


def _p264_defensive_daily_breakout_rollback_snapshot(regime_mode: str | None = None, candidate: dict | None = None) -> dict:
    mode = str(regime_mode or "").strip().lower()
    active = bool(not SWING_REGIME_MODE_ALLOW_DEFENSIVE_ENTRIES)
    tier_gate = _p275_defensive_breakout_tier_gate(candidate) if candidate else {
        "enabled": bool(SWING_DEFENSIVE_BREAKOUT_TIER_GATE_ENABLED),
        "passed": False,
        "blockers": ["candidate_not_scored_yet"],
        "checks": [],
        "max_new_entries_per_scan": int(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_NEW_ENTRIES_PER_SCAN),
    }

    broad_blocked = bool(
        STRATEGY_MODE == "swing"
        and active
        and mode == "defensive"
    )
    blocked = bool(broad_blocked and not tier_gate.get("passed"))

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "defensive_daily_breakout_rollback",
        "active": active,
        "blocked": blocked,
        "broad_blocked": broad_blocked,
        "tier_gate_enabled": bool(tier_gate.get("enabled")),
        "tier_gate_passed": bool(tier_gate.get("passed")),
        "tier_gate": tier_gate,
        "strategy_blocked": BREAKOUT_STRATEGY_NAME,
        "regime_mode": mode or "unknown",
        "mean_reversion_preserved": True,
        "env": {
            "SWING_REGIME_MODE_ALLOW_DEFENSIVE_ENTRIES": bool(SWING_REGIME_MODE_ALLOW_DEFENSIVE_ENTRIES),
            "SWING_DEFENSIVE_BREAKOUT_TIER_GATE_ENABLED": bool(SWING_DEFENSIVE_BREAKOUT_TIER_GATE_ENABLED),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MIN_RANK_SCORE": float(SWING_DEFENSIVE_BREAKOUT_TIER_MIN_RANK_SCORE),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MIN_CLOSE_TO_HIGH_PCT": float(SWING_DEFENSIVE_BREAKOUT_TIER_MIN_CLOSE_TO_HIGH_PCT),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MAX_BREAKOUT_EXTENSION_PCT": float(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_BREAKOUT_EXTENSION_PCT),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MAX_RISK_PER_SHARE_PCT": float(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_RISK_PER_SHARE_PCT),
        },
        "reason": "defensive_daily_breakout_rollback" if blocked else "none",
    }

def evaluate_daily_breakout_candidate(symbol: str, bars: list[dict], index_aligned: bool | None = None, regime_mode: str = 'trend', broker_snapshot: dict | None = None) -> dict:
    candidate = {
        'symbol': symbol,
        'strategy': BREAKOUT_STRATEGY_NAME,
        'scan_ts_utc': datetime.now(timezone.utc).isoformat(),
        'eligible': False,
        'rejection_reasons': [],
    }
    closes = [_safe_float(b.get('close')) for b in bars]
    highs = [_safe_float(b.get('high')) for b in bars]
    lows = [_safe_float(b.get('low')) for b in bars]
    vols = [_safe_float(b.get('volume')) for b in bars]
    need = max(SWING_SLOW_MA_DAYS + 5, SWING_BREAKOUT_LOOKBACK_DAYS + 2, 25)
    if len(closes) < need:
        candidate['rejection_reasons'].append('insufficient_daily_bars')
        return candidate
    thresholds = _regime_mode_thresholds(regime_mode)
    defensive_rollback = {
        "blocked": False,
        "reason": "pending_scored_candidate",
    }
    close = closes[-1]
    prev_close = closes[-2]
    high = highs[-1]
    low = lows[-1]
    fast_ma = _sma(closes, SWING_FAST_MA_DAYS)
    slow_ma = _sma(closes, SWING_SLOW_MA_DAYS)
    atr_14 = _atr(highs, lows, closes, length=14)
    atr_pct = ((atr_14 or 0.0) / max(close, 1e-9)) if close else 0.0
    avg_dollar_vol_20 = sum((closes[-20+i] * vols[-20+i]) for i in range(20)) / 20.0
    ret_20 = (close / closes[-21] - 1.0) if len(closes) >= 21 and closes[-21] > 0 else 0.0
    breakout_ref = max(highs[-(SWING_BREAKOUT_LOOKBACK_DAYS+1):-1])
    trailing_low = min(lows[-5:])
    close_to_high = (close / max(high, 1e-9))
    breakout_distance = (close / max(breakout_ref, 1e-9)) - 1.0
    range_pct = (high - low) / max(close, 1e-9)
    stop_price = min(trailing_low, breakout_ref * (1.0 - SWING_BREAKOUT_BUFFER_PCT))
    risk_per_share = max(close - stop_price, close * 0.0025)
    effective_target_r_mult = _p459_effective_swing_target_r_mult()
    effective_risk_dollars = _p459_effective_swing_risk_dollars()
    target_price = close + (risk_per_share * effective_target_r_mult)
    requested_qty = min(MAX_QTY, max(MIN_QTY, round(effective_risk_dollars / max(risk_per_share, 1e-9), 2)))
    affordable = _clip_qty_for_affordability_with_snapshot(close, requested_qty, broker_snapshot=broker_snapshot)
    est_qty = float(affordable.get('submitted_qty') or 0.0)
    score = 0.0
    if close >= SWING_MIN_PRICE:
        score += 10
    else:
        candidate['rejection_reasons'].append('price_below_min')
    if avg_dollar_vol_20 >= SWING_MIN_AVG_DOLLAR_VOLUME:
        score += min(20.0, avg_dollar_vol_20 / SWING_MIN_AVG_DOLLAR_VOLUME * 10.0)
    else:
        candidate['rejection_reasons'].append('avg_dollar_volume_below_min')
    if avg_dollar_vol_20 < float(SWING_BREAKOUT_QUALITY_MIN_AVG_DOLLAR_VOLUME):
        candidate['rejection_reasons'].append('low_volume')
    trend_ok = bool(fast_ma and slow_ma and close > fast_ma > slow_ma)
    if trend_ok:
        score += 25
    elif thresholds.get('require_trend'):
        candidate['rejection_reasons'].append('trend_filter_failed')
    if ret_20 >= float(thresholds.get('return_20d_min_pct') or 0.0):
        score += min(20.0, ret_20 * 200.0)
    else:
        candidate['rejection_reasons'].append('return_20d_below_min')
    if close_to_high >= float(thresholds.get('close_to_high_min_pct') or 0.0):
        score += 12
    else:
        candidate['rejection_reasons'].append('close_not_near_high')
    effective_breakout_max_distance = float(thresholds.get('breakout_max_distance_pct') or 0.0)
    strong_atr_relax_applied = False
    defensive_tightening_enabled = bool(SWING_DEFENSIVE_ENTRY_TIGHTENING_ENABLED) and str(thresholds.get("mode") or "").strip().lower() == "defensive"
    if (
        atr_pct >= float(SWING_BREAKOUT_STRONG_ATR_PCT)
        and close_to_high >= float(thresholds.get('close_to_high_min_pct') or 0.0)
        and ret_20 >= float(thresholds.get('return_20d_min_pct') or 0.0)
        and not (defensive_tightening_enabled and bool(SWING_DEFENSIVE_DISABLE_STRONG_ATR_RELAX))
    ):
        effective_breakout_max_distance += float(SWING_BREAKOUT_STRONG_ATR_DISTANCE_RELAX_PCT)
        strong_atr_relax_applied = True
    if breakout_distance >= -effective_breakout_max_distance:
        score += 18
    else:
        candidate['rejection_reasons'].append('too_far_below_breakout')
    score += max(0.0, min(10.0, range_pct * 100.0))
    if atr_pct >= float(SWING_BREAKOUT_MIN_ATR_PCT):
        score += min(5.0, atr_pct * 100.0)
    if defensive_tightening_enabled:
        max_ret_20 = float(SWING_DEFENSIVE_MAX_20D_RETURN_PCT)
        max_risk_pct = float(SWING_DEFENSIVE_MAX_RISK_PER_SHARE_PCT)
        risk_per_share_pct = risk_per_share / max(close, 1e-9)
        if max_ret_20 > 0 and ret_20 > max_ret_20:
            candidate['rejection_reasons'].append('defensive_20d_return_too_extended')
        if max_risk_pct > 0 and risk_per_share_pct > max_risk_pct:
            candidate['rejection_reasons'].append('defensive_risk_per_share_too_wide')
        if bool(SWING_DEFENSIVE_REQUIRE_BREAKOUT_NOT_EXTENDED) and breakout_distance > effective_breakout_max_distance:
            candidate['rejection_reasons'].append('defensive_breakout_extension_too_high')
    if bool(thresholds.get('require_index_alignment')) and index_aligned is False:
        candidate['rejection_reasons'].append('index_alignment_failed')
    min_rank_score = _breakout_min_rank_score_for_mode(thresholds.get('mode'))
    candidate.update({
        'close': round(close, 4),
        'prev_close': round(prev_close, 4),
        'high': round(high, 4),
        'low': round(low, 4),
        'fast_ma': round(fast_ma, 4) if fast_ma else None,
        'slow_ma': round(slow_ma, 4) if slow_ma else None,
        'atr_14': round(atr_14, 4) if atr_14 is not None else None,
        'atr_pct': round(atr_pct * 100.0, 3) if atr_pct is not None else None,
        'avg_dollar_volume_20d': round(avg_dollar_vol_20, 2),
        'return_20d_pct': round(ret_20 * 100.0, 3),
        'close_to_high_pct': round(close_to_high * 100.0, 3),
        'breakout_level': round(breakout_ref, 4),
        'breakout_distance_pct': round(breakout_distance * 100.0, 3),
        'effective_breakout_max_distance_pct': round(effective_breakout_max_distance * 100.0, 3),
        'strong_atr_relax_applied': bool(strong_atr_relax_applied),
        'defensive_tightening_enabled': bool(defensive_tightening_enabled),
        'defensive_max_20d_return_pct': round(float(SWING_DEFENSIVE_MAX_20D_RETURN_PCT) * 100.0, 3),
        'defensive_max_risk_per_share_pct': round(float(SWING_DEFENSIVE_MAX_RISK_PER_SHARE_PCT) * 100.0, 3),
        'risk_per_share_pct': round((risk_per_share / max(close, 1e-9)) * 100.0, 3),
        'range_pct': round(range_pct * 100.0, 3),
        'stop_price': round(stop_price, 4),
        'target_price': round(target_price, 4),
        'risk_per_share': round(risk_per_share, 4),
        'requested_qty': round(requested_qty, 2),
        'estimated_qty': round(est_qty, 2),
        'affordability': dict(affordable),
        'scan_broker_snapshot': dict(broker_snapshot or affordable.get("buying_power_snapshot") or {}),
        'p479_broker_free_eval': True,
        'rank_score': round(score, 4),
        'min_rank_score': round(min_rank_score, 4),
        'signal': 'daily_breakout',
        'side': 'buy',
        'regime_mode': thresholds.get('mode'),
        'mode_thresholds': {
            'breakout_max_distance_pct': round(float(thresholds.get('breakout_max_distance_pct') or 0.0) * 100.0, 3),
            'effective_breakout_max_distance_pct': round(float(effective_breakout_max_distance or 0.0) * 100.0, 3),
            'close_to_high_min_pct': round(float(thresholds.get('close_to_high_min_pct') or 0.0) * 100.0, 3),
            'return_20d_min_pct': round(float(thresholds.get('return_20d_min_pct') or 0.0) * 100.0, 3),
            'min_atr_pct': round(float(SWING_BREAKOUT_MIN_ATR_PCT) * 100.0, 3),
            'strong_atr_pct': round(float(SWING_BREAKOUT_STRONG_ATR_PCT) * 100.0, 3),
            'distance_relax_pct': round(float(SWING_BREAKOUT_STRONG_ATR_DISTANCE_RELAX_PCT) * 100.0, 3),
            'quality_min_avg_dollar_volume': round(float(SWING_BREAKOUT_QUALITY_MIN_AVG_DOLLAR_VOLUME), 2),
            'min_rank_score': round(float(min_rank_score), 3),
            'require_trend': bool(thresholds.get('require_trend')),
            'require_index_alignment': bool(thresholds.get('require_index_alignment')),
        },
    })
    defensive_rollback = _p264_defensive_daily_breakout_rollback_snapshot(
        thresholds.get("mode") or regime_mode,
        candidate=candidate,
    )
    candidate["defensive_daily_breakout_rollback"] = defensive_rollback
    if defensive_rollback.get("blocked"):
        candidate['rejection_reasons'].append('defensive_daily_breakout_rollback')
    elif defensive_rollback.get("broad_blocked") and defensive_rollback.get("tier_gate_passed"):
        candidate["defensive_breakout_tier_approved"] = True

    candidate = _p282_apply_breakout_restoration_controls(candidate)
    score = float(_safe_float(candidate.get("rank_score")))

    if score < min_rank_score:
        candidate['rejection_reasons'].append('rank_score_below_min')

    candidate['rejection_reasons'] = _dedupe_candidate_reasons(candidate.get('rejection_reasons') or [])
    candidate['eligible'] = len(candidate['rejection_reasons']) == 0 and est_qty >= max(MIN_AFFORDABLE_QTY, MIN_QTY)

    if not candidate['eligible'] and est_qty < max(MIN_AFFORDABLE_QTY, MIN_QTY):
        sizing_truth = _p300_executable_sizing_truth(candidate)
        candidate['executable_sizing_truth'] = sizing_truth
        candidate['rejection_reasons'].append(
            "broker_insufficient_buying_power"
            if sizing_truth.get("broker_buying_power_label_valid")
            else "internal_sizing_qty_zero"
        )
        candidate['rejection_reasons'] = _dedupe_candidate_reasons(candidate.get('rejection_reasons') or [])

    candidate = _p300_apply_executable_selection_contract(candidate)
    return candidate

def _index_alignment_ok(index_bars: list[dict]) -> bool | None:
    closes = [_safe_float(b.get('close')) for b in index_bars]
    if len(closes) < max(25, SWING_SLOW_MA_DAYS + 2):
        return None
    fast_ma = _sma(closes, SWING_FAST_MA_DAYS)
    slow_ma = _sma(closes, SWING_SLOW_MA_DAYS)
    if not fast_ma or not slow_ma:
        return None
    return bool(closes[-1] > fast_ma > slow_ma)



def _return_pct(closes: list[float], lookback: int) -> float | None:
    try:
        lb = max(1, int(lookback or 0))
        if len(closes) < lb + 1: return None
        base = float(closes[-(lb + 1)] or 0.0)
        if base <= 0: return None
        return (float(closes[-1]) / base) - 1.0
    except Exception:
        return None


def _distance_to_ma_pct(close: float | None, ma: float | None) -> float | None:
    try:
        c = float(close or 0.0); m = float(ma or 0.0)
        if c <= 0 or m <= 0: return None
        return abs(c - m) / m
    except Exception:
        return None


def evaluate_daily_mean_reversion_candidate(symbol: str, bars: list[dict], regime: dict | None = None, regime_mode: str = 'defensive', broker_snapshot: dict | None = None) -> dict:
    candidate = {'symbol': symbol, 'strategy': MEAN_REVERSION_STRATEGY_NAME, 'scan_ts_utc': datetime.now(timezone.utc).isoformat(), 'eligible': False, 'rejection_reasons': []}
    if not SWING_MEAN_REVERSION_ENABLED:
        candidate['rejection_reasons'].append('mean_reversion_disabled'); return candidate
    regime = dict(regime or {})
    if SWING_MEAN_REVERSION_ONLY_WHEN_REGIME_UNFAVORABLE and regime.get('favorable') is True:
        candidate['rejection_reasons'].append('regime_not_unfavorable'); return candidate
    closes = [_safe_float(b.get('close')) for b in bars]; highs = [_safe_float(b.get('high')) for b in bars]; lows = [_safe_float(b.get('low')) for b in bars]; vols = [_safe_float(b.get('volume')) for b in bars]
    need = max(SWING_SLOW_MA_DAYS + 5, 25)
    if len(closes) < need:
        candidate['rejection_reasons'].append('insufficient_daily_bars'); return candidate
    close = closes[-1]; prev_close = closes[-2]; high = highs[-1]; low = lows[-1]; fast_ma = _sma(closes, SWING_FAST_MA_DAYS); slow_ma = _sma(closes, SWING_SLOW_MA_DAYS)
    avg_dollar_vol_20 = sum((closes[-20+i] * vols[-20+i]) for i in range(20)) / 20.0
    ret_5 = _return_pct(closes, 5); ret_20 = _return_pct(closes, 20); close_to_high = close / max(high, 1e-9); dist_to_slow = _distance_to_ma_pct(close, slow_ma); range_pct = (high - low) / max(close, 1e-9); mean_anchor = slow_ma or fast_ma or close
    stop_price = round(close * (1.0 - float(SWING_MEAN_REVERSION_STOP_PCT)), 4); target_price = round(close * (1.0 + float(SWING_MEAN_REVERSION_TARGET_PCT)), 4); risk_per_share = max(close - stop_price, close * 0.0025)
    risk_budget = max(0.01, float(RISK_DOLLARS) * max(0.01, float(SWING_MEAN_REVERSION_RISK_MULTIPLIER))); requested_qty = min(MAX_QTY, max(MIN_QTY, round(risk_budget / max(risk_per_share, 1e-9), 2))); affordable = _clip_qty_for_affordability_with_snapshot(close, requested_qty, broker_snapshot=broker_snapshot); est_qty = float(affordable.get('submitted_qty') or 0.0)
    score = 0.0
    if close >= SWING_MEAN_REVERSION_MIN_PRICE: score += 10.0
    else: candidate['rejection_reasons'].append('price_below_min')
    if avg_dollar_vol_20 >= SWING_MEAN_REVERSION_MIN_AVG_DOLLAR_VOLUME: score += min(15.0, avg_dollar_vol_20 / max(1.0, SWING_MEAN_REVERSION_MIN_AVG_DOLLAR_VOLUME) * 6.0)
    else: candidate['rejection_reasons'].append('avg_dollar_volume_below_min')
    if ret_5 is None or ret_5 < float(SWING_MEAN_REVERSION_MIN_5D_RETURN_PCT): candidate['rejection_reasons'].append('return_5d_too_weak')
    elif ret_5 > float(SWING_MEAN_REVERSION_MAX_5D_RETURN_PCT): candidate['rejection_reasons'].append('return_5d_not_pulled_back')
    else: score += max(0.0, min(18.0, abs(ret_5) * 300.0))
    if ret_20 is None or ret_20 < float(SWING_MEAN_REVERSION_MIN_20D_RETURN_PCT): candidate['rejection_reasons'].append('return_20d_below_floor')
    else: score += max(0.0, min(12.0, (ret_20 + 0.10) * 40.0))
    if close_to_high >= float(SWING_MEAN_REVERSION_MIN_CLOSE_TO_HIGH_PCT): score += 20.0
    else: candidate['rejection_reasons'].append('close_not_near_high')
    if dist_to_slow is None or dist_to_slow > float(SWING_MEAN_REVERSION_MAX_DIST_TO_SLOW_MA_PCT): candidate['rejection_reasons'].append('too_far_from_mean')
    else: score += max(0.0, 15.0 - (dist_to_slow * 500.0))
    if range_pct >= float(SWING_MEAN_REVERSION_MIN_RANGE_PCT): score += max(0.0, min(10.0, range_pct * 100.0))
    else: candidate['rejection_reasons'].append('insufficient_range')
    if slow_ma and close >= slow_ma: score += 8.0
