def fetch_1m_bars(symbol: str, lookback_days: int = 1, limit: int | None = None, feed_override=None) -> list[dict]:
    """Fetch recent 1-minute bars for a symbol using the REST helper on the configured feed.

    This intentionally avoids the SDK default path so the bar fallback stays on an IEX-safe
    code path when the account is not entitled to recent SIP data.
    """
    end = datetime.now(tz=timezone.utc)
    start = end - timedelta(days=max(1, int(lookback_days or 1)))
    rows_by_symbol, _debug = _fetch_bars_via_rest(
        [str(symbol or '').upper()],
        start=start,
        end=end,
        feed_override=(feed_override or _DATA_FEED_RAW or "iex"),
        limit=int(limit or 5000),
    )
    rows = list((rows_by_symbol or {}).get(str(symbol or '').upper(), []) or [])
    return rows


def _try_build_snapshot_from_recent_1m_bar(symbol: str, max_age_sec: float | None = None) -> tuple[dict | None, dict]:
    """Try to build a synthetic fresh quote snapshot from the latest recent 1-minute bar.

    Returns (snapshot, debug). The debug payload is always populated so callers can see *why*
    the fallback was not accepted.
    """
    threshold = float(max_age_sec if max_age_sec is not None else ENTRY_BAR_FALLBACK_MAX_AGE_SEC)
    debug = {
        "attempted": True,
        "source": "recent_1m_bar",
        "max_age_sec": threshold,
        "activated": False,
    }
    try:
        bars = fetch_1m_bars(symbol, lookback_days=1, feed_override=_DATA_FEED_RAW or "iex")
        debug["bar_count"] = int(len(bars or []))
    except Exception as e:
        debug["reason"] = "bar_fetch_error"
        debug["error"] = str(e)
        return None, debug
    if not bars:
        debug["reason"] = "no_bars"
        return None, debug
    latest = bars[-1] or {}
    ts_utc = latest.get("ts_utc")
    px = _safe_float(latest.get("close"))
    debug["bar_ts_utc"] = ts_utc.isoformat() if hasattr(ts_utc, "isoformat") else ts_utc
    debug["bar_close"] = px
    if ts_utc is None:
        debug["reason"] = "missing_bar_timestamp"
        return None, debug
    if px is None or px <= 0:
        debug["reason"] = "invalid_bar_close"
        return None, debug
    if ts_utc.tzinfo is None:
        ts_utc = ts_utc.replace(tzinfo=timezone.utc)
    age_sec = max(0.0, (datetime.now(timezone.utc) - ts_utc.astimezone(timezone.utc)).total_seconds())
    debug["bar_age_sec"] = round(float(age_sec), 6)
    if age_sec > threshold:
        debug["reason"] = "bar_too_old"
        return None, debug
    quote_debug = {
        "method": "recent_1m_bar",
        "feed": str(_DATA_FEED_RAW),
        "count": 1,
        "url": None,
        "attempts": [],
        "attempt_count": 1,
        "retry_sleep_sec": 0.0,
        "fallback_used": True,
        "fallback_source": "recent_1m_bar",
        "synthetic_quote": True,
        "final_quote_valid": True,
        "final_missing_fields": [],
        "freshness_reference": "bar_ts",
        "freshness_threshold_sec": threshold,
        "bar_ts_utc": ts_utc.isoformat(),
        "bar_age_sec": round(float(age_sec), 6),
    }
    debug["activated"] = True
    debug["reason"] = "accepted"
    return {
        "symbol": str(symbol or "").upper(),
        "price": round(float(px), 6),
        "trade_price": round(float(px), 6),
        "bid": round(float(px), 6),
        "ask": round(float(px), 6),
        "mid": round(float(px), 6),
        "spread": 0.0,
        "spread_pct": 0.0,
        "quote_ts_utc": ts_utc.isoformat(),
        "trade_ts_utc": ts_utc.isoformat(),
        "price_age_sec": round(float(age_sec), 6),
        "quote_ok": True,
        "fresh": True,
        "quote_debug": quote_debug,
    }, debug


def _try_build_snapshot_from_candidate_meta(symbol: str, meta: dict | None = None, max_age_sec: float | None = None) -> tuple[dict | None, dict]:
    """Last-resort fallback using the current scan candidate's own observed close/scan timestamp.

    This only activates when the selected candidate metadata is fresh enough from the current scan.
    """
    threshold = float(max_age_sec if max_age_sec is not None else max(120.0, ENTRY_BAR_FALLBACK_MAX_AGE_SEC))
    debug = {
        "attempted": True,
        "source": "candidate_scan",
        "max_age_sec": threshold,
        "activated": False,
    }
    meta = dict(meta or {})
    ts_raw = meta.get("scan_ts_utc") or meta.get("ts_utc")
    px = _safe_float(meta.get("close") or meta.get("price") or meta.get("trade_price"))
    debug["scan_ts_utc"] = str(ts_raw) if ts_raw is not None else None
    debug["candidate_price"] = px
    if ts_raw is None:
        debug["reason"] = "missing_scan_timestamp"
        return None, debug
    if px is None or px <= 0:
        debug["reason"] = "invalid_candidate_price"
        return None, debug
    try:
        if isinstance(ts_raw, datetime):
            ts_utc = ts_raw
        else:
            ts_utc = datetime.fromisoformat(str(ts_raw).replace("Z", "+00:00"))
        if ts_utc.tzinfo is None:
            ts_utc = ts_utc.replace(tzinfo=timezone.utc)
    except Exception as e:
        debug["reason"] = "scan_timestamp_parse_error"
        debug["error"] = str(e)
        return None, debug
    age_sec = max(0.0, (datetime.now(timezone.utc) - ts_utc.astimezone(timezone.utc)).total_seconds())
    debug["scan_age_sec"] = round(float(age_sec), 6)
    if age_sec > threshold:
        debug["reason"] = "candidate_scan_too_old"
        return None, debug
    quote_debug = {
        "method": "candidate_scan",
        "feed": str(_DATA_FEED_RAW),
        "count": 1,
        "url": None,
        "attempts": [],
        "attempt_count": 1,
        "retry_sleep_sec": 0.0,
        "fallback_used": True,
        "fallback_source": "candidate_scan",
        "synthetic_quote": True,
        "final_quote_valid": True,
        "final_missing_fields": [],
        "freshness_reference": "scan_ts",
        "freshness_threshold_sec": threshold,
        "scan_ts_utc": ts_utc.isoformat(),
        "scan_age_sec": round(float(age_sec), 6),
    }
    debug["activated"] = True
    debug["reason"] = "accepted"
    return {
        "symbol": str(symbol or "").upper(),
        "price": round(float(px), 6),
        "trade_price": round(float(px), 6),
        "bid": round(float(px), 6),
        "ask": round(float(px), 6),
        "mid": round(float(px), 6),
        "spread": 0.0,
        "spread_pct": 0.0,
        "quote_ts_utc": ts_utc.isoformat(),
        "trade_ts_utc": ts_utc.isoformat(),
        "price_age_sec": round(float(age_sec), 6),
        "quote_ok": True,
        "fresh": True,
        "quote_debug": quote_debug,
    }, debug


def ema_series(closes: list[float], length: int) -> list[float]:
    """Compute EMA series."""
    if not closes:
        return []
    alpha = 2.0 / (length + 1.0)
    ema = closes[0]
    out = [ema]
    for c in closes[1:]:
        ema = (alpha * c) + ((1 - alpha) * ema)
        out.append(ema)
    return out

def resample_5m(bars_1m: list[dict], minutes: int = 5) -> list[dict]:
    """Resample 1-minute bars (dicts) into N-minute bars with simple indicators.

    Input bar keys expected: ts_utc (epoch sec), ts_ny (ISO), open, high, low, close, volume, vwap (optional).
    Output bars include: ts_utc, ts_ny, open, high, low, close, volume, vwap (session cumulative),
    ema_fast, ema_slow.
    """
    if not bars_1m:
        return []

    def _parse_ts_ny(x) -> datetime:
        # bars_1m["ts_ny"] is usually a timezone-aware datetime; sometimes an ISO string.
        if isinstance(x, datetime):
            return x
        return datetime.fromisoformat(str(x))

    buckets: dict[datetime, list[dict]] = {}

    for b in bars_1m:
        tsn = b.get("ts_ny")
        if not tsn:
            continue
        dt = _parse_ts_ny(tsn)
        mm = (dt.minute // minutes) * minutes
        key = dt.replace(minute=mm, second=0, microsecond=0)
        buckets.setdefault(key, []).append(b)

    out: list[dict] = []
    for key in sorted(buckets.keys()):
        grp = buckets[key]
        if not grp:
            continue
        grp_sorted = sorted(grp, key=lambda x: x.get("ts_utc") or datetime.min.replace(tzinfo=timezone.utc))
        o = float(grp_sorted[0].get("open", grp_sorted[0].get("close", 0.0)) or 0.0)
        h = max(float(x.get("high", x.get("close", 0.0)) or 0.0) for x in grp_sorted)
        l = min(float(x.get("low", x.get("close", 0.0)) or 0.0) for x in grp_sorted)
        c = float(grp_sorted[-1].get("close", 0.0) or 0.0)
        v = sum(float(x.get("volume", 0.0) or 0.0) for x in grp_sorted)

        pv = 0.0
        for x in grp_sorted:
            vol = float(x.get("volume", 0.0) or 0.0)
            px = x.get("vwap", None)
            if px is None:
                px = x.get("close", 0.0)
            pv += float(px or 0.0) * vol
        bar_vwap = (pv / v) if v > 0 else c
        
        ts_utc = grp_sorted[-1].get("ts_utc")
        out.append({
            "ts_utc": ts_utc,
            "ts_ny": key.isoformat(),
            "open": o,
            "high": h,
            "low": l,
            "close": c,
            "volume": v,
            "vwap_bar": bar_vwap,
        })

    if not out:
        return []

    cum_pv = 0.0
    cum_v = 0.0
    for b in out:
        vol = float(b.get("volume", 0.0) or 0.0)
        px = float(b.get("vwap_bar", b.get("close", 0.0)) or 0.0)
        cum_pv += px * vol
        cum_v += vol
        b["vwap"] = (cum_pv / cum_v) if cum_v > 0 else float(b.get("close", 0.0) or 0.0)

    closes = [float(b.get("close", 0.0) or 0.0) for b in out]
    ema_fast = ema_series(closes, SCANNER_HF_EMA_FAST)
    ema_slow = ema_series(closes, SCANNER_HF_EMA_SLOW)
    for i, b in enumerate(out):
        b["ema_fast"] = ema_fast[i]
        b["ema_slow"] = ema_slow[i]

    return out


def fetch_1m_bars_multi(
    symbols: list[str], lookback_days: int = 1, limit_per_symbol: int | None = None
) -> dict[str, list[dict]]:
    """Fetch 1-minute bars for multiple symbols in a single Alpaca call.

    Returns mapping symbol -> list[dict] with the same schema as fetch_1m_bars().
    Symbols with no data will have an empty list.
    """
    symbols = [s.strip().upper() for s in (symbols or []) if s and s.strip()]
    if not symbols:
        return {}

    end = now_ny()
    start = end - timedelta(days=max(1, int(lookback_days)))
    req = StockBarsRequest(
        symbol_or_symbols=symbols,
        timeframe=TimeFrame.Minute,
        start=start,
        end=end,
        adjustment=ADJUSTMENT,
        feed=DATA_FEED,
    )

    out: dict[str, list[dict]] = {s: [] for s in symbols}

    def _fallback_from_rest(reason: str) -> dict[str, list[dict]]:
        rest_rows, rest_debug = _fetch_bars_via_rest(
            symbols,
            start=start.astimezone(timezone.utc),
            end=end.astimezone(timezone.utc),
            feed_override=_DATA_FEED_RAW,
            limit=(limit_per_symbol or 10000),
        )
        logger.warning(
            "BARS_MULTI_FALLBACK reason=%s symbols=%s feed=%s count=%s debug=%s",
            reason,
            ",".join(symbols[:10]),
            str(DATA_FEED),
            sum(len(v) for v in rest_rows.values()),
            rest_debug,
        )
        return rest_rows

    try:
        df = data_client.get_stock_bars(req).df
    except Exception as e:
        return _fallback_from_rest(f"sdk_exception:{e}")
    if df is None or len(df) == 0:
        return _fallback_from_rest("sdk_empty")

    # Expected Alpaca shape: multiindex (symbol, timestamp)
    try:
        for (sym, ts), row in df.iterrows():
            ts_utc = ts.to_pydatetime() if hasattr(ts, "to_pydatetime") else ts
            ts_ny = ts_utc.astimezone(NY)
            out.setdefault(sym, []).append(
                {
                    "ts_utc": ts_utc,
                    "ts_ny": ts_ny,
                    "open": float(row["open"]),
                    "high": float(row["high"]),
                    "low": float(row["low"]),
                    "close": float(row["close"]),
                    "volume": float(row.get("volume", 0.0)),
                    "vwap": float(row.get("vwap", 0.0) or 0.0),
                }
            )
    except Exception:
        # Fallback if df isn't multiindex
        for sym in symbols:
            try:
                sdf = df.xs(sym, level=0)
            except Exception:
                continue
            for ts, row in sdf.iterrows():
                ts_utc = ts.to_pydatetime() if hasattr(ts, "to_pydatetime") else ts
                ts_ny = ts_utc.astimezone(NY)
                out.setdefault(sym, []).append(
                    {
                        "ts_utc": ts_utc,
                        "ts_ny": ts_ny,
                        "open": float(row["open"]),
                        "high": float(row["high"]),
                        "low": float(row["low"]),
                        "close": float(row["close"]),
                        "volume": float(row.get("volume", 0.0)),
                        "vwap": float(row.get("vwap", 0.0) or 0.0),
                    }
                )

    for sym in list(out.keys()):
        out[sym] = sorted(out[sym], key=lambda r: r["ts_utc"])
        if limit_per_symbol and len(out[sym]) > limit_per_symbol:
            out[sym] = out[sym][-limit_per_symbol:]
    if not any(out.values()):
        return _fallback_from_rest("sdk_parsed_empty")
    return out




def _chunked(items: list, size: int) -> list[list]:
    chunk_size = max(1, int(size or 1))
    return [items[i : i + chunk_size] for i in range(0, len(items), chunk_size)]


def fetch_1m_bars_multi_guarded(symbols: list[str], lookback_days: int = 1) -> dict[str, list[dict]]:
    """Memory-guarded 1m bar fetch for scanner runs.

    The Alpaca SDK can materialize a large dataframe for multi-symbol minute bars.
    Fetching in chunks and trimming per-symbol rows keeps peak memory lower while
    preserving broad scanner coverage.
    """
    syms = _dedupe_keep_order([str(s or "").strip().upper() for s in (symbols or []) if str(s or "").strip()])
    if not syms:
        return {}
    limit = int(SCANNER_MAX_1M_BARS_PER_SYMBOL or 0) or None
    out: dict[str, list[dict]] = {s: [] for s in syms}
    for chunk in _chunked(syms, SCANNER_FETCH_CHUNK_SIZE):
        chunk_rows = fetch_1m_bars_multi(chunk, lookback_days=lookback_days, limit_per_symbol=limit)
        for sym in chunk:
            rows = list((chunk_rows or {}).get(sym) or [])
            if limit and len(rows) > limit:
                rows = rows[-limit:]
            out[sym] = rows
        del chunk_rows
        gc.collect()
    return out


def _latest_scan_item() -> dict:
    if SCAN_HISTORY:
        current = next((it for it in reversed(SCAN_HISTORY) if str((it or {}).get("boot_id") or "") == SYSTEM_BOOT_ID), None)
        if isinstance(current, dict):
            return dict(current)
        if isinstance(SCAN_HISTORY[-1], dict):
            return dict(SCAN_HISTORY[-1])
    if isinstance(LAST_SCAN, dict) and LAST_SCAN:
        return dict(LAST_SCAN)
    return {}


def _scan_summary_payload(scan: dict | None) -> dict:
    if not isinstance(scan, dict):
        return {}
    summary = scan.get("summary")
    return dict(summary) if isinstance(summary, dict) else {}


def _scan_result_items(scan: dict | None) -> list[dict]:
    if not isinstance(scan, dict):
        return []
    rows = scan.get("results")
    if not isinstance(rows, list):
        return []
    return [dict(r) for r in rows if isinstance(r, dict)]


def _current_position_symbols_from_snapshot(snapshot: dict | None = None) -> set[str]:
    snap = snapshot if isinstance(snapshot, dict) else {}
    out: set[str] = set()
    for row in snap.get("positions") or []:
        if not isinstance(row, dict):
            continue
        sym = str(row.get("symbol") or "").strip().upper()
        if not sym:
            continue
        qty = _safe_float(row.get("qty") or row.get("quantity") or row.get("filled_qty"), 0.0)
        if qty != 0:
            out.add(sym)
    return out


def _current_active_plan_symbols_from_snapshot(snapshot: dict | None = None) -> set[str]:
    snap = snapshot if isinstance(snapshot, dict) else {}
    plans = snap.get("active_plans") if isinstance(snap.get("active_plans"), dict) else {}
    out: set[str] = set()
    for sym, plan in plans.items():
        if not isinstance(plan, dict) or not bool(plan.get("active")):
            continue
        usym = str(sym or plan.get("symbol") or "").strip().upper()
        if usym:
            out.add(usym)
    return out


def _dashboard_rejection_truth_status(symbol: str, reasons: list[str], *, current_positions: set[str], current_active_plans: set[str]) -> dict:
    sym = str(symbol or "").strip().upper()
    reason_set = {str(r or "").strip() for r in (reasons or []) if str(r or "").strip()}
    current_position = bool(sym and sym in current_positions)
    current_plan = bool(sym and sym in current_active_plans)
    stale_reasons = []
    if "position_already_open" in reason_set and not current_position:
        stale_reasons.append("position_already_open")
    if "plan_or_pending_entry_exists" in reason_set and not current_plan:
        stale_reasons.append("plan_or_pending_entry_exists")
    status = "current"
    if stale_reasons and len(stale_reasons) == len(reason_set & {"position_already_open", "plan_or_pending_entry_exists"}):
        status = "historical_book_state"
    elif stale_reasons:
        status = "mixed_historical_book_state"
    return {
        "symbol": sym,
        "current_position": current_position,
        "current_active_plan": current_plan,
        "stale_book_reasons": stale_reasons,
        "status": status,
    }


def _intraday_signal_debug_from_scan(scan: dict | None) -> dict:
    scan_item = dict(scan or {}) if isinstance(scan, dict) else _latest_scan_item()
    summary = _scan_summary_payload(scan_item)
    results = _scan_result_items(scan_item)
    ignored = scan_item.get("ignored_ranked_out") if isinstance(scan_item.get("ignored_ranked_out"), list) else []
    would_submit = scan_item.get("would_submit") if isinstance(scan_item.get("would_submit"), list) else []
    top_pre_ranked = summary.get("top_pre_ranked_candidates") if isinstance(summary.get("top_pre_ranked_candidates"), list) else []
    top_signals = summary.get("top_signals") if isinstance(summary.get("top_signals"), list) else []
    strategy_breakdown = summary.get("strategy_breakdown") if isinstance(summary.get("strategy_breakdown"), dict) else {}
    reclaim_breakdown = strategy_breakdown.get("intraday_vwap_reclaim") if isinstance(strategy_breakdown.get("intraday_vwap_reclaim"), list) else []
    action = "waiting_for_reclaim_signal"
    if top_signals:
        action = "signal_seen_check_submit_path"
    if ignored:
        action = "signal_rank_or_slot_filtered"
    if would_submit:
        action = "submit_attempted"
    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "strategy_mode": STRATEGY_MODE,
        "scan_ts_utc": scan_item.get("ts_utc") or LAST_SCAN.get("ts_utc"),
        "current_boot_scan_available": bool(str(scan_item.get("boot_id") or "") == SYSTEM_BOOT_ID),
        "scanned": scan_item.get("scanned") or summary.get("scanned") or len(scan_item.get("symbols") or []),
        "signals": scan_item.get("signals") if scan_item.get("signals") is not None else len(top_signals),
        "would_trade": scan_item.get("would_trade"),
        "candidate_slots": scan_item.get("candidate_slots"),
        "raw_results_count": scan_item.get("raw_results_count") if scan_item.get("raw_results_count") is not None else len(results),
        "results_compacted": bool(scan_item.get("results_compacted")) if scan_item else None,
        "actionable_state": action,
        "intraday_vwap_reclaim": {
            "enabled": bool(INTRADAY_VWAP_RECLAIM_ENABLE and str(STRATEGY_MODE or "").strip().lower() == "intraday"),
            "score_min": float(INTRADAY_VWAP_RECLAIM_SCORE_MIN),
            "breakdown": reclaim_breakdown,
        },
        "intraday_vwap_continuation": {
            "enabled": bool(INTRADAY_VWAP_CONTINUATION_ENABLE and str(STRATEGY_MODE or "").strip().lower() == "intraday"),
            "score_min": float(INTRADAY_VWAP_CONTINUATION_SCORE_MIN),
            "min_rank_score": float(INTRADAY_VWAP_CONTINUATION_MIN_RANK_SCORE),
            "breakdown": strategy_breakdown.get("intraday_vwap_continuation") if isinstance(strategy_breakdown.get("intraday_vwap_continuation"), list) else [],
        },
        "top_component_blockers": list(summary.get("top_component_blockers") or [])[:8],
        "top_macro_blockers": list(summary.get("top_macro_blockers") or [])[:8],
        "top_micro_blockers": list(summary.get("top_micro_blockers") or [])[:8],
        "near_miss_symbols": list(summary.get("near_miss_symbols") or [])[:8],
        "top_pre_ranked_candidates": list(top_pre_ranked)[:8],
        "top_signals": list(top_signals)[:8],
        "ignored_ranked_out": [dict(r) for r in ignored[:8] if isinstance(r, dict)],
        "would_submit": [dict(r) for r in would_submit[:8] if isinstance(r, dict)],
    }


def _compact_scan_result(row: dict | None) -> dict:
    item = dict(row or {})
    compact = {
        "symbol": item.get("symbol"),
        "action": item.get("action"),
        "reason": item.get("reason"),
        "side": item.get("side"),
        "signal": item.get("signal"),
        "price": item.get("price"),
        "rank_score": item.get("rank_score"),
        "score": item.get("score"),
    }
    no_signal = item.get("no_signal") if isinstance(item.get("no_signal"), dict) else {}
    if no_signal:
        compact["no_signal"] = {"primary": no_signal.get("primary")}
    diagnostics = item.get("diagnostics") if isinstance(item.get("diagnostics"), dict) else {}
    vp = diagnostics.get("vwap_pullback") if isinstance(diagnostics.get("vwap_pullback"), dict) else {}
    if vp:
        compact["vwap_pullback"] = {
            "reason": vp.get("reason"),
            "score": vp.get("score"),
            "dist_to_vwap_pct": vp.get("dist_to_vwap_pct"),
            "fallback_ready": bool((vp.get("trend_components") or {}).get("fallback_ready")) if isinstance(vp.get("trend_components"), dict) else None,
        }
    reclaim = diagnostics.get("intraday_vwap_reclaim") if isinstance(diagnostics.get("intraday_vwap_reclaim"), dict) else {}
    if reclaim:
        compact["intraday_vwap_reclaim"] = {
            "reason": reclaim.get("reason"),
            "score": reclaim.get("score"),
            "dist_to_vwap_pct": reclaim.get("dist_to_vwap_pct"),
            "reclaimed_vwap": reclaim.get("reclaimed_vwap"),
        }
    continuation = diagnostics.get("intraday_vwap_continuation") if isinstance(diagnostics.get("intraday_vwap_continuation"), dict) else {}
    if continuation:
        compact["intraday_vwap_continuation"] = {
            "reason": continuation.get("reason"),
            "score": continuation.get("score"),
            "dist_to_vwap_pct": continuation.get("dist_to_vwap_pct"),
            "continuation": continuation.get("continuation"),
        }
    return {k: v for k, v in compact.items() if v is not None}


def _scan_history_results_for_storage(rows: list[dict]) -> list[dict]:
    items = [dict(r or {}) for r in (rows or []) if isinstance(r, dict)]
    if SCAN_HISTORY_STORE_FULL_RESULTS:
        return items[: max(0, int(SCAN_HISTORY_RESULT_LIMIT or 0))] if SCAN_HISTORY_RESULT_LIMIT else items
    limit = max(0, int(SCAN_HISTORY_RESULT_LIMIT or 0))
    if limit:
        items = items[:limit]
    return [_compact_scan_result(r) for r in items]
    
def _volatility_score(bars_1m: list[dict], bars_n: int, metric: str) -> float:
    """Compute a simple volatility score for ranking symbols."""
    if not bars_1m:
        return 0.0
    closes = [float(b.get("close") or 0.0) for b in bars_1m[-max(10, bars_n):] if b.get("close") is not None]
    closes = [c for c in closes if c > 0]
    if len(closes) < 10:
        return 0.0

    metric = (metric or "range_pct").strip()
    if metric == "stdev_ret":
        rets = [math.log(closes[i] / closes[i - 1]) for i in range(1, len(closes)) if closes[i - 1] > 0]
        if len(rets) < 5:
            return 0.0
        mu = sum(rets) / len(rets)
        var = sum((r - mu) ** 2 for r in rets) / max(1, (len(rets) - 1))
        return float(math.sqrt(var))

    cmin = min(closes)
    cmax = max(closes)
    cmean = sum(closes) / len(closes)
    return float((cmax - cmin) / cmean) if cmean > 0 else 0.0



def resample_to_5m(bars_1m: list[Bar]) -> list[Bar]:
    """Resample 1m bars into 5m bars (NY time), producing OHLCV + VWAP.
    Bar.ts_ny is kept as the *end* of each 5m bucket (last minute in the bucket).
    """
    if not bars_1m:
        return []
    buckets: dict[datetime, list[Bar]] = {}
    for b in bars_1m:
        bucket_start = b.ts_ny.replace(second=0, microsecond=0, minute=(b.ts_ny.minute // 5) * 5)
        buckets.setdefault(bucket_start, []).append(b)

    out: list[Bar] = []
    for bucket_start in sorted(buckets.keys()):
        group = buckets[bucket_start]
        group.sort(key=lambda x: x.ts_ny)
        o = group[0].open
        h = max(x.high for x in group)
        l = min(x.low for x in group)
        c = group[-1].close
        v = sum(x.volume for x in group)
        pv = sum((x.close * x.volume) for x in group)
        vwap = (pv / v) if v > 0 else c
        out.append(Bar(ts_utc=group[-1].ts_utc, ts_ny=group[-1].ts_ny, open=o, high=h, low=l, close=c, volume=v, vwap=vwap))
    return out


def _bars_for_today_session(bars: list[dict]) -> list[dict]:
    if not bars:
        return []
    today = now_ny().date()
    out = []
    for r in bars:
        ts = r["ts_ny"]
        if ts.date() != today:
            continue
        # Regular session only
        if ts.time() < MARKET_OPEN or ts.time() > MARKET_CLOSE:
            continue
        out.append(r)
    return out


def eval_midbox_signal(bars_today: list[dict]) -> tuple[str, str] | None:
    if not bars_today:
        return None
    ts_ny = bars_today[-1].get("ts_ny")
    if ts_ny is None:
        return None

    # Must be inside trade session
    if not _bars_for_today_session(bars_today, ts_ny, MIDBOX_TRADE_SESSION):
        return None

    build_bars = _bars_for_today_session(bars_today, ts_ny, MIDBOX_BUILD_SESSION)
    if len(build_bars) < 10:
        return None

    use_hl = bool(MIDBOX_BREAKOUT_USE_HIGHLOW)
    highs = [float(b.get("high", b.get("close"))) for b in build_bars]
    lows = [float(b.get("low", b.get("close"))) for b in build_bars]
    closes = [float(b.get("close")) for b in build_bars]
    box_high = max(highs) if use_hl else max(closes)
    box_low = min(lows) if use_hl else min(closes)

    price = float(bars_today[-1].get("close"))
    buf = float(MIDBOX_BREAKOUT_BUFFER_PCT)

    # Light trend filter (keeps frequency reasonable, avoids chop)
    ema_fast = ema_series(closes + [price], 20)
    ema_slow = ema_series(closes + [price], 50)
    if ema_fast is None or ema_slow is None:
        return None
    if price < ema_fast[-1] or ema_fast[-1] < ema_slow[-1]:
        return None

    if price >= box_high * (1.0 + buf):
        return ("midbox_breakout_up", "BUY")

    # Shorts are disabled in this system; return None for breakdowns.
    return None

def _scan_diag_midbox(bars_1m: list[dict]) -> dict:
    out: dict = {"enabled": True, "eligible": True}
    try:
        # calc_midbox expects 1m bars
        box = calc_midbox(bars_1m)
        box_high = float(box["box_high"])
        buf = float(MIDBOX_BREAKOUT_BUFFER_PCT)

        # Buffered confirm level vs raw box high (for touch/near)
        level = box_high * (1.0 + buf)
        raw_level = box_high

        price = float(bars_1m[-1].get("close") or 0.0)
        prev_close = float(bars_1m[-2].get("close") or 0.0)
        high = float(bars_1m[-1].get("high", price))

        crossed_up = (price >= level) and (prev_close < level)
        crossed_down = (price <= level) and (prev_close > level)

        touch_eps = float(MIDBOX_TOUCH_EPS_PCT)
        # Touch uses RAW level (not buffered)
        touched = bool(high >= raw_level and price >= raw_level * (1.0 - touch_eps) and prev_close < raw_level)

        out.update({
            "box_high": box_high,
            "level": level,
            "raw_level": raw_level,
            "prev_close": prev_close,
            "close": price,
            "high": high,
            "buf": buf,
            "crossed_up": bool(crossed_up),
            "crossed_down": bool(crossed_down),
            "touched": bool(touched),
        })

        # Trend filter
        trend_ok = True
        if MIDBOX_TREND_FILTER_ENABLE:
            ema_fast = ema_series(bars_1m, MIDBOX_TREND_FAST_LEN)
            ema_slow = ema_series(bars_1m, MIDBOX_TREND_SLOW_LEN)
            if ema_fast and ema_slow:
                trend_ok = (price >= ema_fast[-1]) and (ema_fast[-1] >= ema_slow[-1])
        out["trend_ok"] = bool(trend_ok)

        if not trend_ok:
            out["reason"] = "trend_fail"
            return out

        if crossed_up or crossed_down or touched:
            out["reason"] = "breakout_cross"
            return out

        out["reason"] = "no_breakout_cross"
        near_pct = float(MIDBOX_NEAR_PCT)
        out["near_miss"] = {
            "near": bool(price >= raw_level * (1.0 - near_pct) and prev_close < raw_level),
            "near_pct": near_pct,
            "dist_to_level_pct": (raw_level - price) / raw_level if raw_level else None,
            "raw_level": raw_level,
            "touch_eps": touch_eps,
        }
        return out
    except Exception as e:
        out["eligible"] = None
        out["reason"] = f"error:{type(e).__name__}"
        return out

def _scan_diag_pwr(bars_today: list[dict]) -> dict:
    out: dict = {"enabled": True, "eligible": True}
    try:
        session_ok, pre_bars, _ = split_power_hour(bars_today)
        if not session_ok:
            out["eligible"] = False
            out["reason"] = "not_in_session"
            return out

        use_hl = any(("high" in b) for b in pre_bars)
        pre_high = (
            max(float(b.get("high", b.get("close"))) for b in pre_bars)
            if use_hl
            else max(float(b.get("close")) for b in pre_bars)
        )

        buf = float(PWR_BREAKOUT_BUFFER_PCT)
        level = pre_high * (1.0 + buf)
        raw_level = pre_high

        price = float(bars_today[-1].get("close") or 0.0)
        prev_close = float(bars_today[-2].get("close") or 0.0)
        high = float(bars_today[-1].get("high", price))

        breakout = (price >= level) and (prev_close < level)

        touch_eps = float(PWR_TOUCH_EPS_PCT)
        touched = bool(high >= raw_level and price >= raw_level * (1.0 - touch_eps) and prev_close < raw_level)

        out.update({
            "pre_high": pre_high,
            "level": level,
            "raw_level": raw_level,
            "prev_close": prev_close,
            "close": price,
            "high": high,
            "buf": buf,
            "breakout": bool(breakout),
            "touched": bool(touched),
        })

        # Volume confirmation (loose)
        volume_ok = True
        try:
            last_vol = float(bars_today[-1].get("volume") or 0.0)
            vols20 = sorted([float(b.get("volume") or 0.0) for b in bars_today[-20:]])
            med = vols20[len(vols20) // 2] if vols20 else 0.0
            if med > 0:
                volume_ok = last_vol >= (0.8 * med)
        except Exception:
            volume_ok = True
        out["volume_ok"] = bool(volume_ok)

        out["vwap_5m"] = None
        out["ema20_5m"] = None
        out["ema200_slope_up"] = True

        if (breakout or touched) and not volume_ok:
            out["reason"] = "volume_fail"
            return out

        if not breakout and not touched:
            out["reason"] = "no_breakout"
            near_pct = float(PWR_NEAR_PCT)
            out["near_miss"] = {
                "near": bool(price >= raw_level * (1.0 - near_pct) and prev_close < raw_level),
                "near_pct": near_pct,
                "dist_to_level_pct": (raw_level - price) / raw_level if raw_level else None,
                "raw_level": raw_level,
                "touch_eps": touch_eps,
            }
            return out

        out["reason"] = "ok"
        return out
    except Exception as e:
        out["eligible"] = None
        out["reason"] = f"error:{type(e).__name__}"
        return out

def _vwap_pullback_setup(bars_today: list[dict]) -> dict:
    out: dict = {"enabled": bool(VWAP_PB_ENABLE), "eligible": True, "strategy": "vwap_pullback_5m"}
    if not VWAP_PB_ENABLE:
        out["eligible"] = False
        out["reason"] = "disabled"
        return out

    bars_today = _bars_for_today_regular_session(bars_today)
    bars_5m = resample_5m(bars_today) if bars_today else []
    out["bars_5m"] = len(bars_5m)
    min_bars = max(12, int(VWAP_PB_MIN_BARS_5M))
    out["min_bars_5m"] = min_bars
    out["min_bars_5m_source"] = "env" if os.getenv("VWAP_PB_MIN_BARS_5M") is not None else "default"
    if len(bars_5m) < min_bars:
        out["eligible"] = False
        out["reason"] = "insufficient_5m_bars"
        return out

    closes = [float(b.get("close") or 0.0) for b in bars_5m]
    highs = [float(b.get("high", b.get("close") or 0.0) or 0.0) for b in bars_5m]
    lows = [float(b.get("low", b.get("close") or 0.0) or 0.0) for b in bars_5m]
    opens = [float(b.get("open", b.get("close") or 0.0) or 0.0) for b in bars_5m]
    volumes = [float(b.get("volume") or 0.0) for b in bars_5m]
    price = closes[-1]
    prev_close = closes[-2]

    ema_fast = ema_series(closes, int(VWAP_PB_EMA_FAST))
    ema_slow = ema_series(closes, int(VWAP_PB_EMA_SLOW))
    if not ema_fast or not ema_slow:
        out["eligible"] = False
        out["reason"] = "ema_not_ready"
        return out

    vwaps: list[float] = []
    pv = 0.0
    vv = 0.0
    for h, l, c, v in zip(highs, lows, closes, volumes):
        tp = (h + l + c) / 3.0
        pv += tp * v
        vv += v
        vwaps.append((pv / vv) if vv > 0 else c)
    vwap = vwaps[-1]

    lookback = max(3, min(int(VWAP_PB_TOUCH_LOOKBACK_BARS), len(closes)))
    touch_band = float(VWAP_PB_TOUCH_BAND_PCT)
    touch_level = vwap * (1.0 + touch_band)
    touched = min(lows[-lookback:]) <= touch_level

    extension_pct = ((price - vwap) / vwap) if vwap else 0.0
    extension_ok = extension_pct <= float(VWAP_PB_MAX_EXTENSION_PCT)

    slope_back = max(1, min(int(VWAP_PB_SLOPE_LOOKBACK_BARS), len(ema_fast) - 1, len(vwaps) - 1))
    ema_slope = (ema_fast[-1] / max(ema_fast[-1 - slope_back], 1e-9) - 1.0) if len(ema_fast) > slope_back else 0.0
    vwap_slope = (vwaps[-1] / max(vwaps[-1 - slope_back], 1e-9) - 1.0) if len(vwaps) > slope_back else 0.0

    allow_below_vwap_pct = float(VWAP_PB_ALLOW_BELOW_VWAP_PCT)
    ema_stack_slack_pct = float(VWAP_PB_EMA_STACK_SLACK_PCT)
    allow_below_fast_pct = float(VWAP_PB_ALLOW_PRICE_BELOW_EMA_FAST_PCT)

    price_above_vwap = price >= vwap * (1.0 - allow_below_vwap_pct)
    ema_stack_ok = ema_fast[-1] >= ema_slow[-1] * (1.0 - ema_stack_slack_pct)
    price_above_fast = price >= ema_fast[-1] * (1.0 - allow_below_fast_pct)
    strict_trend_ok = (ema_fast[-1] > ema_slow[-1]) and (price >= ema_slow[-1]) and (price >= vwap)
    permissive_trend_ok = price_above_vwap and ema_stack_ok and price_above_fast

    slope_ok = ema_slope >= float(VWAP_PB_MIN_EMA_SLOPE) and vwap_slope >= float(VWAP_PB_ALLOW_NEG_VWAP_SLOPE_PCT)
    regained_vwap = price >= vwap * 0.9985
    momentum_ok = price >= prev_close * 0.999 and price >= opens[-1] * 0.998

    recent_vol = sum(volumes[-3:])
    baseline_vol = _mean(volumes[-9:-3]) * 3 if len(volumes) >= 9 else _mean(volumes[:-3]) * 3
    relvol = recent_vol / max(baseline_vol, 1.0) if baseline_vol > 0 else 1.0
    relvol_ok = relvol >= float(VWAP_PB_MIN_RELVOL)

    trs: list[float] = []
    for i, (h, l, c) in enumerate(zip(highs, lows, closes)):
        prev_c_i = closes[i - 1] if i > 0 else c
        tr = max(h - l, abs(h - prev_c_i), abs(l - prev_c_i))
        trs.append(float(tr))
    atr_window = min(5, len(trs))
    atr_5m = _mean(trs[-atr_window:]) if atr_window else 0.0
    atr_pct = (atr_5m / max(price, 1e-9)) if price else 0.0
    atr_ok = float(VWAP_PB_MIN_5M_ATR_PCT) <= atr_pct <= float(VWAP_PB_MAX_5M_ATR_PCT)

    day_high = max(highs) if highs else price
    day_low = min(lows) if lows else price
    day_range_pct = ((day_high - day_low) / max(price, 1e-9)) if price else 0.0
    day_range_ok = day_range_pct >= float(VWAP_PB_MIN_DAY_RANGE_PCT)

    bars_1m = bars_today[-20:] if len(bars_today) >= 20 else list(bars_today)
    last_1m = bars_1m[-1] if bars_1m else None
    prev_1m = bars_1m[-2] if len(bars_1m) >= 2 else None
    raw_last_1m_green = True
    raw_higher_low_ok = True
    raw_entry_confirm_ok = True
    if last_1m:
        raw_last_1m_green = float(last_1m.get("close") or 0.0) >= float(last_1m.get("open") or 0.0)
    if prev_1m and last_1m:
        raw_higher_low_ok = float(last_1m.get("low") or 0.0) >= float(prev_1m.get("low") or 0.0)
        confirm_level = float(prev_1m.get("high") or 0.0) * (1.0 + float(VWAP_PB_ENTRY_CONFIRM_BUFFER_PCT))
        raw_entry_confirm_ok = float(last_1m.get("close") or 0.0) >= confirm_level

    micro_checks = []
    if VWAP_PB_REQUIRE_GREEN_LAST_1M:
        micro_checks.append(("green", bool(raw_last_1m_green)))
    if VWAP_PB_REQUIRE_HIGHER_LOW:
        micro_checks.append(("higher_low", bool(raw_higher_low_ok)))
    if VWAP_PB_ENTRY_CONFIRM_ABOVE_PRIOR_1M_HIGH:
        micro_checks.append(("entry_confirm", bool(raw_entry_confirm_ok)))

    last_1m_green = bool(raw_last_1m_green) if VWAP_PB_REQUIRE_GREEN_LAST_1M else True
    higher_low_ok = bool(raw_higher_low_ok) if VWAP_PB_REQUIRE_HIGHER_LOW else True
    entry_confirm_ok = bool(raw_entry_confirm_ok) if VWAP_PB_ENTRY_CONFIRM_ABOVE_PRIOR_1M_HIGH else True

    micro_pass_count = sum(1 for _, ok in micro_checks if ok)
    micro_enabled_checks = len(micro_checks)
    micro_mode = str(VWAP_PB_MICRO_CONFIRM_MODE or "soft2").strip().lower()
    if micro_enabled_checks == 0 or micro_mode == "off":
        micro_confirm_ok = True
    elif micro_mode in {"strict", "all"}:
        micro_confirm_ok = all(ok for _, ok in micro_checks)
    elif micro_mode in {"soft1", "one"}:
        micro_confirm_ok = micro_pass_count >= 1
    else:
        required_passes = max(1, min(int(VWAP_PB_SOFT_CONFIRM_MIN_PASSES), micro_enabled_checks))
        micro_confirm_ok = micro_pass_count >= required_passes

    recent_1m_vol = _mean([float(b.get("volume") or 0.0) for b in bars_1m[-3:]]) if len(bars_1m) >= 3 else 0.0
    baseline_1m_vol = _mean([float(b.get("volume") or 0.0) for b in bars_1m[-13:-3]]) if len(bars_1m) >= 13 else _mean([float(b.get("volume") or 0.0) for b in bars_1m[:-3]])
    recent_1m_vol_ratio = recent_1m_vol / max(baseline_1m_vol, 1.0) if baseline_1m_vol > 0 else 1.0
    micro_vol_ok = recent_1m_vol_ratio >= float(VWAP_PB_MIN_RECENT_1M_VOL_RATIO)

    dist_to_vwap_pct = ((price - vwap) / vwap) if vwap else 0.0
    trend_strength = 0.0
    if price_above_vwap:
        trend_strength += 12.0
    if ema_stack_ok:
        trend_strength += 12.0
    if price_above_fast:
        trend_strength += 8.0
    if strict_trend_ok:
        trend_strength += 8.0

    score = 0.0
    score += trend_strength
    if permissive_trend_ok:
        score += 12.0
    if touched:
        score += 16.0
    if regained_vwap:
        score += 14.0
    if momentum_ok:
        score += 8.0
    if extension_ok:
        score += 8.0
    if slope_ok:
        score += 6.0
    if atr_ok:
        score += 8.0
    if day_range_ok:
        score += 6.0
    if micro_vol_ok:
        score += 6.0
    if last_1m_green:
        score += 4.0
    if higher_low_ok:
        score += 4.0
    if entry_confirm_ok:
        score += 6.0
    score += max(0.0, min(relvol, 2.5)) * 6.0
    score += max(0.0, min(recent_1m_vol_ratio, 2.0)) * 4.0
    score += max(0.0, min(ema_slope * 10000.0, 8.0))
    score += max(0.0, 6.0 - abs(dist_to_vwap_pct) * 1000.0)

    component_reasons = []
    if not price_above_vwap:
        component_reasons.append("price_below_vwap")
    if not ema_stack_ok:
        component_reasons.append("ema_stack_fail")
    if not price_above_fast:
        component_reasons.append("price_below_ema_fast")
    if not slope_ok:
        component_reasons.append("slope_fail")
    if not touched:
        component_reasons.append("touch_fail")
    if not regained_vwap:
        component_reasons.append("not_back_above_vwap")
    if not extension_ok:
        component_reasons.append("too_extended_from_vwap")
    if not relvol_ok:
        component_reasons.append("relvol_fail")
    if not atr_ok:
        component_reasons.append("atr_regime_fail")
    if not day_range_ok:
        component_reasons.append("day_range_too_small")
    if not micro_vol_ok:
        component_reasons.append("recent_1m_volume_fail")
    if not last_1m_green:
        component_reasons.append("last_1m_not_green")
    if not higher_low_ok:
        component_reasons.append("micro_higher_low_fail")
    if not entry_confirm_ok:
        component_reasons.append("entry_confirm_fail")
    if not momentum_ok:
        component_reasons.append("bounce_not_confirmed")
    if not micro_confirm_ok:
        component_reasons.append("micro_confirm_fail")

    macro_blockers = [r for r in component_reasons if r in {"price_below_vwap", "ema_stack_fail", "price_below_ema_fast", "slope_fail", "touch_fail", "not_back_above_vwap", "too_extended_from_vwap", "relvol_fail", "atr_regime_fail", "day_range_too_small", "bounce_not_confirmed"}]
    micro_blockers = [r for r in component_reasons if r in {"recent_1m_volume_fail", "last_1m_not_green", "micro_higher_low_fail", "entry_confirm_fail", "micro_confirm_fail"}]

    near = bool(
        (permissive_trend_ok and touched and (not regained_vwap))
        or (touched and regained_vwap and score >= float(VWAP_PB_NEAR_MISS_SCORE_MIN))
        or (price_above_vwap and ema_stack_ok and abs(dist_to_vwap_pct) <= touch_band * 1.35)
    )
    fallback_touch_ok = bool(touched or (bool(VWAP_PB_FALLBACK_ALLOW_TOUCHLESS) and abs(dist_to_vwap_pct) <= touch_band * 1.10))
    fallback_slope_ok = bool(
        ema_slope >= float(VWAP_PB_FALLBACK_MIN_EMA_SLOPE)
        and vwap_slope >= float(VWAP_PB_FALLBACK_MIN_VWAP_SLOPE)
    )
    fallback_bounce_ok = bool(
        regained_vwap and (
            momentum_ok
            or (
                bool(VWAP_PB_FALLBACK_ALLOW_BOUNCE_SLACK)
                and dist_to_vwap_pct >= -float(VWAP_PB_FALLBACK_BOUNCE_SLACK_PCT)
            )
        )
    )
    fallback_distance_ok = bool(abs(dist_to_vwap_pct) <= float(VWAP_PB_FALLBACK_MAX_DIST_VWAP_PCT))
    fallback_ready = bool(
        VWAP_PB_ALLOW_NEAR_MISS_FALLBACK
        and permissive_trend_ok
        and fallback_touch_ok
        and extension_ok
        and near
        and score >= float(VWAP_PB_FALLBACK_SIGNAL_SCORE_MIN)
    )
    fallback_blockers = []
    if not fallback_touch_ok:
        fallback_blockers.append("fallback_touch_fail")
    if not fallback_slope_ok:
        fallback_blockers.append("fallback_slope_fail")
    if not fallback_bounce_ok:
        fallback_blockers.append("fallback_bounce_fail")
    if not fallback_distance_ok:
        fallback_blockers.append("fallback_distance_fail")

    out.update({
        "price": round(price, 4),
        "prev_close": round(prev_close, 4),
        "vwap": round(vwap, 4),
        "ema_fast": round(ema_fast[-1], 4),
        "ema_slow": round(ema_slow[-1], 4),
        "ema_slope": round(ema_slope, 6),
        "vwap_slope": round(vwap_slope, 6),
        "strict_trend_ok": bool(strict_trend_ok),
        "trend_ok": bool(permissive_trend_ok),
        "price_above_vwap": bool(price_above_vwap),
        "ema_stack_ok": bool(ema_stack_ok),
        "price_above_fast": bool(price_above_fast),
        "touched": bool(touched),
        "regained_vwap": bool(regained_vwap),
        "momentum_ok": bool(momentum_ok),
        "extension_ok": bool(extension_ok),
        "relvol": round(relvol, 3),
        "relvol_ok": bool(relvol_ok),
        "atr_5m": round(atr_5m, 4),
        "atr_pct": round(atr_pct * 100.0, 3),
        "atr_ok": bool(atr_ok),
        "day_range_pct": round(day_range_pct * 100.0, 3),
        "day_range_ok": bool(day_range_ok),
        "recent_1m_vol_ratio": round(recent_1m_vol_ratio, 3),
        "micro_vol_ok": bool(micro_vol_ok),
        "last_1m_green": bool(last_1m_green),
        "higher_low_ok": bool(higher_low_ok),
        "entry_confirm_ok": bool(entry_confirm_ok),
        "raw_last_1m_green": bool(raw_last_1m_green),
        "raw_higher_low_ok": bool(raw_higher_low_ok),
        "raw_entry_confirm_ok": bool(raw_entry_confirm_ok),
        "micro_confirm_mode": micro_mode,
        "micro_confirm_passes": int(micro_pass_count),
        "micro_confirm_enabled_checks": int(micro_enabled_checks),
        "micro_confirm_ok": bool(micro_confirm_ok),
        "score_min": float(VWAP_PB_SCORE_MIN),
        "dist_to_vwap_pct": round(dist_to_vwap_pct * 100.0, 3),
        "score": round(score, 3),
        "component_reasons": component_reasons,
        "blocker_split": {"macro": macro_blockers, "micro": micro_blockers, "fallback": fallback_blockers},
        "fallback_checks": {
            "touch_ok": bool(fallback_touch_ok),
            "slope_ok": bool(fallback_slope_ok),
            "bounce_ok": bool(fallback_bounce_ok),
            "distance_ok": bool(fallback_distance_ok),
            "blockers": fallback_blockers,
        },
        "trend_components": {
            "price_above_vwap": bool(price_above_vwap),
            "ema_stack_ok": bool(ema_stack_ok),
            "price_above_fast": bool(price_above_fast),
            "strict_trend_ok": bool(strict_trend_ok),
            "allow_below_vwap_pct": round(allow_below_vwap_pct * 100.0, 3),
            "ema_stack_slack_pct": round(ema_stack_slack_pct * 100.0, 3),
            "allow_price_below_ema_fast_pct": round(allow_below_fast_pct * 100.0, 3),
            "fallback_ready": bool(fallback_ready),
            "fallback_touch_ok": bool(fallback_touch_ok),
            "fallback_slope_ok": bool(fallback_slope_ok),
            "fallback_bounce_ok": bool(fallback_bounce_ok),
            "fallback_distance_ok": bool(fallback_distance_ok),
            "fallback_min_ema_slope": float(VWAP_PB_FALLBACK_MIN_EMA_SLOPE),
            "fallback_min_vwap_slope": float(VWAP_PB_FALLBACK_MIN_VWAP_SLOPE),
            "fallback_bounce_slack_pct": round(float(VWAP_PB_FALLBACK_BOUNCE_SLACK_PCT) * 100.0, 3),
            "fallback_max_dist_vwap_pct": round(float(VWAP_PB_FALLBACK_MAX_DIST_VWAP_PCT) * 100.0, 3),
            "micro_confirm_mode": micro_mode,
            "micro_confirm_ok": bool(micro_confirm_ok),
            "score_min": float(VWAP_PB_SCORE_MIN),
            "min_5m_atr_pct": round(float(VWAP_PB_MIN_5M_ATR_PCT) * 100.0, 3),
            "max_5m_atr_pct": round(float(VWAP_PB_MAX_5M_ATR_PCT) * 100.0, 3),
            "min_day_range_pct": round(float(VWAP_PB_MIN_DAY_RANGE_PCT) * 100.0, 3),
            "min_recent_1m_vol_ratio": float(VWAP_PB_MIN_RECENT_1M_VOL_RATIO),
        },
        "near_miss": {
            "near": near,
            "near_pct": round(touch_band * 100.0, 3),
            "dist_to_level_pct": round(((vwap - price) / vwap) * 100.0, 3) if vwap else None,
            "fallback_ready": bool(fallback_ready),
            "score": round(score, 3),
        },
    })

    if strict_trend_ok and slope_ok and touched and regained_vwap and extension_ok and relvol_ok and momentum_ok and atr_ok and day_range_ok and micro_vol_ok and micro_confirm_ok and score >= float(VWAP_PB_SCORE_MIN):
        out["reason"] = "ok"
        out["triggered"] = True
    elif fallback_ready and fallback_slope_ok and fallback_bounce_ok and fallback_distance_ok and atr_ok and day_range_ok and micro_vol_ok and micro_confirm_ok and score >= float(VWAP_PB_SCORE_MIN):
        out["reason"] = "fallback_ready"
        out["triggered"] = True
        out["fallback_trigger"] = True
    else:
        if score < float(VWAP_PB_SCORE_MIN):
            out["reason"] = "score_too_low"
        elif not permissive_trend_ok:
            out["reason"] = component_reasons[0] if component_reasons else "trend_fail"
        elif fallback_ready and not fallback_slope_ok:
            out["reason"] = "fallback_slope_fail"
        elif fallback_ready and not fallback_bounce_ok:
            out["reason"] = "fallback_bounce_fail"
        elif fallback_ready and not fallback_distance_ok:
            out["reason"] = "fallback_distance_fail"
        elif not slope_ok:
            out["reason"] = "slope_fail"
        elif not touched:
            out["reason"] = "touch_fail"
        elif not regained_vwap:
            out["reason"] = "not_back_above_vwap"
        elif not extension_ok:
            out["reason"] = "too_extended_from_vwap"
        elif not relvol_ok:
            out["reason"] = "relvol_fail"
        elif not atr_ok:
            out["reason"] = "atr_regime_fail"
        elif not day_range_ok:
            out["reason"] = "day_range_too_small"
        elif not micro_vol_ok:
            out["reason"] = "recent_1m_volume_fail"
        elif not micro_confirm_ok:
            if VWAP_PB_REQUIRE_GREEN_LAST_1M and not raw_last_1m_green:
                out["reason"] = "last_1m_not_green"
            elif VWAP_PB_REQUIRE_HIGHER_LOW and not raw_higher_low_ok:
                out["reason"] = "micro_higher_low_fail"
            elif VWAP_PB_ENTRY_CONFIRM_ABOVE_PRIOR_1M_HIGH and not raw_entry_confirm_ok:
                out["reason"] = "entry_confirm_fail"
            else:
                out["reason"] = "micro_confirm_fail"
        elif not momentum_ok:
            out["reason"] = "bounce_not_confirmed"
        else:
            out["reason"] = component_reasons[0] if component_reasons else "trend_fail"

    return out

def _scan_diag_vwap_pb(bars_today: list[dict]) -> dict:
    return _vwap_pullback_setup(bars_today)


def eval_vwap_pullback_signal(bars_5m_or_today: list[dict]) -> str | None:
    diag = _vwap_pullback_setup(bars_5m_or_today)
    return "BUY" if diag.get("triggered") else None


def eval_vwap_pullback_signal_with_diag(bars_5m_or_today: list[dict]) -> tuple[str | None, dict]:
    diag = _vwap_pullback_setup(bars_5m_or_today)
    return ("BUY" if diag.get("triggered") else None, diag)




def _intraday_vwap_reclaim_setup(
    bars_today: list[dict],
    force_enable: bool = False,
    session_date=None,
) -> dict:
    """Dedicated intraday VWAP reclaim candidate path.

    This is intentionally separate from the swing/daily breakout filters.  It only
    runs in STRATEGY_MODE=intraday and evaluates same-session 1m/5m structure so
    intraday entries can be found even when daily breakout candidates are not
    near a daily high.
    """
    enabled = bool((INTRADAY_VWAP_RECLAIM_ENABLE or force_enable) and (force_enable or str(STRATEGY_MODE or "").strip().lower() == "intraday"))
    out: dict = {
        "enabled": enabled,
        "eligible": True,
        "strategy": "intraday_vwap_reclaim",
        "candidate_path": "intraday_vwap_reclaim",
    }
    if not enabled:
        out["eligible"] = False
        out["reason"] = "strategy_mode_not_intraday" if str(STRATEGY_MODE or "").strip().lower() != "intraday" and not force_enable else "disabled"
        return out

    rows = _bars_for_regular_session_date(bars_today, session_date) if session_date else _bars_for_today_regular_session(bars_today)
    out["bars_1m"] = len(rows)
    min_1m = max(10, int(INTRADAY_VWAP_RECLAIM_MIN_1M_BARS or 0))
    out["min_bars_1m"] = min_1m
    if len(rows) < min_1m:
        out["eligible"] = False
        out["reason"] = "insufficient_1m_bars"
        return out

    bars_5m = resample_5m(rows)
    out["bars_5m"] = len(bars_5m)
    min_5m = max(3, int(INTRADAY_VWAP_RECLAIM_MIN_5M_BARS or 0))
    out["min_bars_5m"] = min_5m
    if len(bars_5m) < min_5m:
        out["eligible"] = False
        out["reason"] = "insufficient_5m_bars"
        return out

    closes_1m = [float(b.get("close") or 0.0) for b in rows]
    highs_1m = [float(b.get("high", b.get("close") or 0.0) or 0.0) for b in rows]
    lows_1m = [float(b.get("low", b.get("close") or 0.0) or 0.0) for b in rows]
    opens_1m = [float(b.get("open", b.get("close") or 0.0) or 0.0) for b in rows]
    volumes_1m = [float(b.get("volume") or 0.0) for b in rows]
    price = closes_1m[-1]
    prev_close = closes_1m[-2]

    vwaps: list[float] = []
    pv = 0.0
    vv = 0.0
    for h, l, c, v in zip(highs_1m, lows_1m, closes_1m, volumes_1m):
        tp = (h + l + c) / 3.0
        pv += tp * v
        vv += v
        vwaps.append((pv / vv) if vv > 0 else c)
    vwap = vwaps[-1]
    prev_vwap = vwaps[-2] if len(vwaps) >= 2 else vwap

    closes_5m = [float(b.get("close") or 0.0) for b in bars_5m]
    ema_fast = ema_series(closes_5m, max(3, int(VWAP_PB_EMA_FAST or 9)))
    ema_slow = ema_series(closes_5m, max(5, int(VWAP_PB_EMA_SLOW or 20)))
    ema_fast_now = ema_fast[-1] if ema_fast else price
    ema_slow_now = ema_slow[-1] if ema_slow else price

    touch_lookback = max(3, min(8, len(lows_1m)))
    touch_band = float(INTRADAY_VWAP_RECLAIM_TOUCH_BAND_PCT)
    recent_low = min(lows_1m[-touch_lookback:])
    touched = bool(recent_low <= vwap * (1.0 + touch_band))
    price_above_vwap = bool(price >= vwap)
    crossed_vwap = bool(prev_close <= prev_vwap * (1.0 + touch_band * 0.50) and price >= vwap)
    reclaimed_vwap = bool(price_above_vwap and (crossed_vwap or touched))

    extension_pct = ((price - vwap) / max(vwap, 1e-9)) if vwap else 0.0
    dist_to_vwap_pct = extension_pct
    extension_ok = bool(0.0 <= extension_pct <= float(INTRADAY_VWAP_RECLAIM_MAX_EXTENSION_PCT))

    slope_back = max(1, min(5, len(vwaps) - 1))
    vwap_slope = (vwaps[-1] / max(vwaps[-1 - slope_back], 1e-9) - 1.0) if len(vwaps) > slope_back else 0.0
    trend_ok = bool(price >= ema_fast_now * 0.997 and ema_fast_now >= ema_slow_now * 0.997 and vwap_slope >= -0.0010)

    recent_vol = _mean(volumes_1m[-5:]) if len(volumes_1m) >= 5 else _mean(volumes_1m)
    baseline_vol = _mean(volumes_1m[-20:-5]) if len(volumes_1m) >= 20 else _mean(volumes_1m[:-5])
    recent_1m_vol_ratio = recent_vol / max(baseline_vol, 1.0) if baseline_vol > 0 else 1.0
    micro_vol_ok = bool(recent_1m_vol_ratio >= float(INTRADAY_VWAP_RECLAIM_MIN_RECENT_VOL_RATIO))
    relvol_ok = micro_vol_ok

    last_1m_green = bool(closes_1m[-1] >= opens_1m[-1])
    higher_low_ok = bool(lows_1m[-1] >= lows_1m[-2]) if len(lows_1m) >= 2 else True
    entry_confirm_ok = bool(closes_1m[-1] >= highs_1m[-2] * (1.0 + float(VWAP_PB_ENTRY_CONFIRM_BUFFER_PCT))) if len(highs_1m) >= 2 else True
    micro_pass_count = sum(1 for ok in (last_1m_green, higher_low_ok, entry_confirm_ok) if ok)
    micro_confirm_ok = bool(micro_pass_count >= 2)

    day_high = max(highs_1m) if highs_1m else price
    day_low = min(lows_1m) if lows_1m else price
    day_range_pct = ((day_high - day_low) / max(price, 1e-9)) if price else 0.0
    day_range_ok = bool(day_range_pct >= float(INTRADAY_VWAP_RECLAIM_MIN_DAY_RANGE_PCT))
    atr_ok = day_range_ok

    score = 0.0
    if trend_ok: score += 18.0
    if price_above_vwap: score += 12.0
    if touched: score += 14.0
    if crossed_vwap: score += 10.0
    if reclaimed_vwap: score += 14.0
    if extension_ok: score += 8.0
    if vwap_slope >= -0.0005: score += 6.0
    if micro_vol_ok: score += 8.0
    if day_range_ok: score += 6.0
    score += float(micro_pass_count) * 4.0
    score += max(0.0, min(recent_1m_vol_ratio, 2.0)) * 4.0
    score += max(0.0, 6.0 - abs(dist_to_vwap_pct) * 800.0)

    component_reasons = []
    if not trend_ok: component_reasons.append("intraday_trend_fail")
    if not price_above_vwap: component_reasons.append("price_below_vwap")
    if not touched: component_reasons.append("vwap_touch_missing")
    if not reclaimed_vwap: component_reasons.append("vwap_reclaim_missing")
    if not extension_ok: component_reasons.append("too_extended_from_vwap")
    if not micro_vol_ok: component_reasons.append("recent_1m_volume_fail")
    if not day_range_ok: component_reasons.append("day_range_too_small")
    if not micro_confirm_ok: component_reasons.append("micro_confirm_fail")

    orb_vwap_quality_gate = _intraday_orb_vwap_quality_gate(
        rows,
        path="intraday_vwap_reclaim",
        force_enable=force_enable,
        session_date=session_date,
    )
    if not bool(orb_vwap_quality_gate.get("ok")):
        component_reasons.append(str(orb_vwap_quality_gate.get("reason") or "orb_vwap_quality_fail"))

    triggered = bool(
        trend_ok
        and price_above_vwap
        and touched
        and reclaimed_vwap
        and extension_ok
        and micro_vol_ok
        and day_range_ok
        and micro_confirm_ok
        and bool(orb_vwap_quality_gate.get("ok"))
        and score >= float(INTRADAY_VWAP_RECLAIM_SCORE_MIN)
    )
    reason = "ok" if triggered else ("score_too_low" if score < float(INTRADAY_VWAP_RECLAIM_SCORE_MIN) else (component_reasons[0] if component_reasons else "no_reclaim"))
    stop_price = max(0.01, min(recent_low, vwap * (1.0 - 0.0025)))
    risk_per_share = max(price - stop_price, price * 0.0025)
    target_price = price + (risk_per_share * float(SWING_TARGET_R_MULT or 1.8))
    out.update({
        "reason": reason,
        "triggered": triggered,
        "price": round(price, 4),
        "prev_close": round(prev_close, 4),
        "vwap": round(vwap, 4),
        "ema_fast": round(ema_fast_now, 4),
        "ema_slow": round(ema_slow_now, 4),
        "vwap_slope": round(vwap_slope, 6),
        "touched": bool(touched),
        "crossed_vwap": bool(crossed_vwap),
        "regained_vwap": bool(reclaimed_vwap),
        "reclaimed_vwap": bool(reclaimed_vwap),
        "trend_ok": bool(trend_ok),
        "price_above_vwap": bool(price_above_vwap),
        "extension_ok": bool(extension_ok),
        "dist_to_vwap_pct": round(dist_to_vwap_pct * 100.0, 3),
        "recent_1m_vol_ratio": round(recent_1m_vol_ratio, 3),
        "relvol_ok": bool(relvol_ok),
        "micro_vol_ok": bool(micro_vol_ok),
        "last_1m_green": bool(last_1m_green),
        "higher_low_ok": bool(higher_low_ok),
        "entry_confirm_ok": bool(entry_confirm_ok),
        "day_range_pct": round(day_range_pct * 100.0, 3),
        "day_range_ok": bool(day_range_ok),
        "atr_ok": bool(atr_ok),
        "score": round(score, 3),
        "score_min": float(INTRADAY_VWAP_RECLAIM_SCORE_MIN),
        "orb_vwap_quality_gate": orb_vwap_quality_gate,
        "component_reasons": component_reasons,
        "blocker_split": {
            "macro": [r for r in component_reasons if r not in {"recent_1m_volume_fail", "micro_confirm_fail"}],
            "micro": [r for r in component_reasons if r in {"recent_1m_volume_fail", "micro_confirm_fail"}],
            "fallback": [],
        },
        "near_miss": {
            "near": bool(not triggered and score >= max(0.0, float(INTRADAY_VWAP_RECLAIM_SCORE_MIN) - 8.0)),
            "score": round(score, 3),
            "dist_to_level_pct": round(((vwap - price) / max(vwap, 1e-9)) * 100.0, 3) if vwap else None,
        },
        "mode_thresholds": {
            "touch_band_pct": round(touch_band * 100.0, 3),
            "max_extension_pct": round(float(INTRADAY_VWAP_RECLAIM_MAX_EXTENSION_PCT) * 100.0, 3),
            "min_recent_1m_vol_ratio": float(INTRADAY_VWAP_RECLAIM_MIN_RECENT_VOL_RATIO),
            "min_day_range_pct": round(float(INTRADAY_VWAP_RECLAIM_MIN_DAY_RANGE_PCT) * 100.0, 3),
            "score_min": float(INTRADAY_VWAP_RECLAIM_SCORE_MIN),
        },
        "stop_price": round(stop_price, 4),
        "target_price": round(target_price, 4),
        "risk_per_share": round(risk_per_share, 4),
    })
    return out


def eval_intraday_vwap_reclaim_signal_with_diag(
    bars_today: list[dict],
    force_enable: bool = False,
    session_date=None,
) -> tuple[str | None, dict]:
    diag = _intraday_vwap_reclaim_setup(bars_today, force_enable=force_enable, session_date=session_date)
    return ("BUY" if diag.get("triggered") else None, diag)


def _intraday_vwap_continuation_setup(
    bars_today: list[dict],
    force_enable: bool = False,
    session_date=None,
) -> dict:
    """Intraday VWAP trend-continuation path.

    This is separate from VWAP reclaim: it can select symbols that are already
    above VWAP with acceptable trend, volume, extension, and micro structure.
    """
    enabled = bool((INTRADAY_VWAP_CONTINUATION_ENABLE or force_enable) and (force_enable or str(STRATEGY_MODE or "").strip().lower() == "intraday"))
    out: dict = {
        "enabled": enabled,
        "eligible": True,
        "strategy": "intraday_vwap_continuation",
        "candidate_path": "intraday_vwap_continuation",
    }
    if not enabled:
        out["eligible"] = False
        out["reason"] = "strategy_mode_not_intraday" if str(STRATEGY_MODE or "").strip().lower() != "intraday" and not force_enable else "disabled"
        return out

    rows = _bars_for_regular_session_date(bars_today, session_date) if session_date else _bars_for_today_regular_session(bars_today)
    out["bars_1m"] = len(rows)
    min_1m = max(10, int(INTRADAY_VWAP_CONTINUATION_MIN_1M_BARS or 0))
    out["min_bars_1m"] = min_1m
    if len(rows) < min_1m:
        out["eligible"] = False
        out["reason"] = "insufficient_1m_bars"
        return out

    bars_5m = resample_5m(rows)
    out["bars_5m"] = len(bars_5m)
    min_5m = max(3, int(INTRADAY_VWAP_CONTINUATION_MIN_5M_BARS or 0))
    out["min_bars_5m"] = min_5m
    if len(bars_5m) < min_5m:
        out["eligible"] = False
        out["reason"] = "insufficient_5m_bars"
        return out

    closes_1m = [float(b.get("close") or 0.0) for b in rows]
    highs_1m = [float(b.get("high", b.get("close") or 0.0) or 0.0) for b in rows]
    lows_1m = [float(b.get("low", b.get("close") or 0.0) or 0.0) for b in rows]
    opens_1m = [float(b.get("open", b.get("close") or 0.0) or 0.0) for b in rows]
    volumes_1m = [float(b.get("volume") or 0.0) for b in rows]
    price = closes_1m[-1]

    vwaps: list[float] = []
    pv = 0.0
    vv = 0.0
    for h, l, c, v in zip(highs_1m, lows_1m, closes_1m, volumes_1m):
        tp = (h + l + c) / 3.0
        pv += tp * v
        vv += v
        vwaps.append((pv / vv) if vv > 0 else c)
    vwap = vwaps[-1]

    closes_5m = [float(b.get("close") or 0.0) for b in bars_5m]
    ema_fast = ema_series(closes_5m, max(3, int(VWAP_PB_EMA_FAST or 9)))
    ema_slow = ema_series(closes_5m, max(5, int(VWAP_PB_EMA_SLOW or 20)))
    ema_fast_now = ema_fast[-1] if ema_fast else price
    ema_slow_now = ema_slow[-1] if ema_slow else price

    slope_back = max(1, min(5, len(vwaps) - 1))
    vwap_slope = (vwaps[-1] / max(vwaps[-1 - slope_back], 1e-9) - 1.0) if len(vwaps) > slope_back else 0.0
    dist_to_vwap_pct = ((price - vwap) / max(vwap, 1e-9)) if vwap else 0.0
    price_above_vwap = bool(price >= vwap)
    price_above_fast = bool(price >= ema_fast_now * 0.998)
    ema_stack_ok = bool(ema_fast_now >= ema_slow_now * 0.998)
    slope_ok = bool(vwap_slope >= float(INTRADAY_VWAP_CONTINUATION_ALLOW_NEGATIVE_VWAP_SLOPE_PCT))
    extension_ok = bool(0.0 <= dist_to_vwap_pct <= float(INTRADAY_VWAP_CONTINUATION_MAX_EXTENSION_PCT))
    trend_ok = bool(price_above_vwap and price_above_fast and ema_stack_ok and slope_ok)

    recent_vol = _mean(volumes_1m[-5:]) if len(volumes_1m) >= 5 else _mean(volumes_1m)
    baseline_vol = _mean(volumes_1m[-20:-5]) if len(volumes_1m) >= 20 else _mean(volumes_1m[:-5])
    recent_1m_vol_ratio = recent_vol / max(baseline_vol, 1.0) if baseline_vol > 0 else 1.0
    micro_vol_ok = bool(recent_1m_vol_ratio >= float(INTRADAY_VWAP_CONTINUATION_MIN_RECENT_VOL_RATIO))
    relvol_ok = micro_vol_ok

    last_1m_green = bool(closes_1m[-1] >= opens_1m[-1])
    higher_low_ok = bool(lows_1m[-1] >= lows_1m[-2]) if len(lows_1m) >= 2 else True
    entry_confirm_ok = bool(closes_1m[-1] >= highs_1m[-2] * (1.0 + float(VWAP_PB_ENTRY_CONFIRM_BUFFER_PCT))) if len(highs_1m) >= 2 else True
    micro_conditions = []
    if INTRADAY_VWAP_CONTINUATION_REQUIRE_GREEN_LAST_1M:
        micro_conditions.append(last_1m_green)
    if INTRADAY_VWAP_CONTINUATION_REQUIRE_HIGHER_LOW:
        micro_conditions.append(higher_low_ok)
    if INTRADAY_VWAP_CONTINUATION_ENTRY_CONFIRM_ABOVE_PRIOR_1M_HIGH:
        micro_conditions.append(entry_confirm_ok)
    micro_confirm_ok = all(micro_conditions) if micro_conditions else True

    day_high = max(highs_1m) if highs_1m else price
    day_low = min(lows_1m) if lows_1m else price
    day_range_pct = ((day_high - day_low) / max(price, 1e-9)) if price else 0.0
    day_range_ok = bool(day_range_pct >= float(INTRADAY_VWAP_CONTINUATION_MIN_DAY_RANGE_PCT))
    atr_ok = day_range_ok

    score = 0.0
    if trend_ok: score += 20.0
    if price_above_vwap: score += 12.0
    if price_above_fast: score += 10.0
    if ema_stack_ok: score += 10.0
    if slope_ok: score += 8.0
    if extension_ok: score += 10.0
    if micro_vol_ok: score += 8.0
    if day_range_ok: score += 6.0
    if last_1m_green: score += 4.0
    if higher_low_ok: score += 4.0
    if entry_confirm_ok: score += 4.0
    score += max(0.0, min(recent_1m_vol_ratio, 2.0)) * 4.0
    score += max(0.0, 6.0 - abs(dist_to_vwap_pct) * 600.0)

    component_reasons = []
    if not price_above_vwap: component_reasons.append("price_below_vwap")
    if not price_above_fast: component_reasons.append("price_below_ema_fast")
    if not ema_stack_ok: component_reasons.append("ema_stack_fail")
    if not slope_ok: component_reasons.append("slope_fail")
    if not extension_ok: component_reasons.append("too_extended_from_vwap")
    if not micro_vol_ok: component_reasons.append("recent_1m_volume_fail")
    if not day_range_ok: component_reasons.append("day_range_too_small")
    if not micro_confirm_ok: component_reasons.append("micro_confirm_fail")
    if not trend_ok and "intraday_trend_fail" not in component_reasons:
        component_reasons.append("intraday_trend_fail")

    orb_vwap_quality_gate = _intraday_orb_vwap_quality_gate(
        rows,
        path="intraday_vwap_continuation",
        force_enable=force_enable,
        session_date=session_date,
    )
    if not bool(orb_vwap_quality_gate.get("ok")):
        component_reasons.append(str(orb_vwap_quality_gate.get("reason") or "orb_vwap_quality_fail"))

    triggered = bool(
        trend_ok
        and extension_ok
        and micro_vol_ok
        and day_range_ok
        and micro_confirm_ok
        and bool(orb_vwap_quality_gate.get("ok"))
        and score >= float(INTRADAY_VWAP_CONTINUATION_SCORE_MIN)
    )
    reason = "ok" if triggered else ("score_too_low" if score < float(INTRADAY_VWAP_CONTINUATION_SCORE_MIN) else (component_reasons[0] if component_reasons else "no_continuation"))
    recent_low = min(lows_1m[-max(3, min(8, len(lows_1m))):])
    stop_price = max(0.01, min(recent_low, vwap * (1.0 - 0.0025)))
    risk_per_share = max(price - stop_price, price * 0.0025)
    target_price = price + (risk_per_share * float(SWING_TARGET_R_MULT or 1.8))
    out.update({
        "reason": reason,
        "triggered": triggered,
        "price": round(price, 4),
        "vwap": round(vwap, 4),
        "ema_fast": round(ema_fast_now, 4),
        "ema_slow": round(ema_slow_now, 4),
        "vwap_slope": round(vwap_slope, 6),
        "touched": bool(price_above_vwap),
        "continuation": True,
        "trend_ok": bool(trend_ok),
        "price_above_vwap": bool(price_above_vwap),
        "price_above_fast": bool(price_above_fast),
        "ema_stack_ok": bool(ema_stack_ok),
        "slope_ok": bool(slope_ok),
        "extension_ok": bool(extension_ok),
        "dist_to_vwap_pct": round(dist_to_vwap_pct * 100.0, 3),
        "recent_1m_vol_ratio": round(recent_1m_vol_ratio, 3),
        "relvol_ok": bool(relvol_ok),
        "micro_vol_ok": bool(micro_vol_ok),
        "last_1m_green": bool(last_1m_green),
        "higher_low_ok": bool(higher_low_ok),
        "entry_confirm_ok": bool(entry_confirm_ok),
        "micro_confirm_ok": bool(micro_confirm_ok),
        "day_range_pct": round(day_range_pct * 100.0, 3),
        "day_range_ok": bool(day_range_ok),
        "atr_ok": bool(atr_ok),
        "score": round(score, 3),
        "score_min": float(INTRADAY_VWAP_CONTINUATION_SCORE_MIN),
        "orb_vwap_quality_gate": orb_vwap_quality_gate,
        "component_reasons": component_reasons,
        "blocker_split": {
            "macro": [r for r in component_reasons if r not in {"recent_1m_volume_fail", "micro_confirm_fail"}],
            "micro": [r for r in component_reasons if r in {"recent_1m_volume_fail", "micro_confirm_fail"}],
            "fallback": [],
        },
        "near_miss": {
            "near": bool(not triggered and score >= max(0.0, float(INTRADAY_VWAP_CONTINUATION_SCORE_MIN) - 8.0)),
            "score": round(score, 3),
            "dist_to_level_pct": round(dist_to_vwap_pct * 100.0, 3),
        },
        "mode_thresholds": {
            "max_extension_pct": round(float(INTRADAY_VWAP_CONTINUATION_MAX_EXTENSION_PCT) * 100.0, 3),
            "min_recent_1m_vol_ratio": float(INTRADAY_VWAP_CONTINUATION_MIN_RECENT_VOL_RATIO),
            "min_day_range_pct": round(float(INTRADAY_VWAP_CONTINUATION_MIN_DAY_RANGE_PCT) * 100.0, 3),
            "score_min": float(INTRADAY_VWAP_CONTINUATION_SCORE_MIN),
        },
        "stop_price": round(stop_price, 4),
        "target_price": round(target_price, 4),
        "risk_per_share": round(risk_per_share, 4),
    })
    return out


def eval_intraday_vwap_continuation_signal_with_diag(
    bars_today: list[dict],
    force_enable: bool = False,
    session_date=None,
) -> tuple[str | None, dict]:
    diag = _intraday_vwap_continuation_setup(bars_today, force_enable=force_enable, session_date=session_date)
    return ("BUY" if diag.get("triggered") else None, diag)

def _intraday_orb_vwap_quality_gate(
    bars_today: list[dict],
    *,
    path: str = "",
    force_enable: bool = False,
    session_date=None,
) -> dict:
    enabled = bool(INTRADAY_ORB_VWAP_QUALITY_GATE_ENABLE and (force_enable or str(STRATEGY_MODE or "").strip().lower() == "intraday"))
    out = {
        "enabled": enabled,
        "path": str(path or ""),
        "ok": True,
        "reason": "disabled",
    }
    if not enabled:
        return out

    rows = _bars_for_regular_session_date(bars_today, session_date) if session_date else _bars_for_today_regular_session(bars_today)
    orb_bars = max(2, int(INTRADAY_ORB_BARS or 5))
    out["bars_1m"] = len(rows)
    out["orb_bars"] = orb_bars
    if len(rows) <= orb_bars:
        out.update({"ok": False, "reason": "orb_window_not_complete"})
        return out

    closes = [float(b.get("close") or 0.0) for b in rows]
    highs = [float(b.get("high", b.get("close") or 0.0) or 0.0) for b in rows]
    lows = [float(b.get("low", b.get("close") or 0.0) or 0.0) for b in rows]
    volumes = [float(b.get("volume") or 0.0) for b in rows]
    price = closes[-1]
    orb_high = max(highs[:orb_bars])
    orb_low = min(lows[:orb_bars])

    pv = 0.0
    vv = 0.0
    vwaps: list[float] = []
    for h, l, c, v in zip(highs, lows, closes, volumes):
        tp = (h + l + c) / 3.0
        pv += tp * v
        vv += v
        vwaps.append((pv / vv) if vv > 0 else c)
    vwap = vwaps[-1] if vwaps else price

    buffer_pct = float(INTRADAY_ORB_BREAKOUT_BUFFER_PCT)
    price_above_orb = bool(price >= orb_high * (1.0 + buffer_pct))
    price_above_vwap = bool(price >= vwap)
    extension_pct = ((price - vwap) / max(vwap, 1e-9)) if vwap else 0.0
    extension_ok = bool(0.0 <= extension_pct <= float(INTRADAY_ORB_MAX_EXTENSION_FROM_VWAP_PCT))

    recent_vol = _mean(volumes[-5:]) if len(volumes) >= 5 else _mean(volumes)
    baseline_vol = _mean(volumes[-20:-5]) if len(volumes) >= 20 else _mean(volumes[:-5])
    recent_1m_vol_ratio = recent_vol / max(baseline_vol, 1.0) if baseline_vol > 0 else 1.0
    volume_ok = bool(recent_1m_vol_ratio >= float(INTRADAY_ORB_MIN_RECENT_VOL_RATIO))

    day_range_pct = ((max(highs) - min(lows)) / max(price, 1e-9)) if price else 0.0
    day_range_ok = bool(day_range_pct >= float(INTRADAY_ORB_MIN_DAY_RANGE_PCT))

    reasons = []
    if not price_above_orb:
        reasons.append("orb_breakout_missing")
    if not price_above_vwap:
        reasons.append("price_below_vwap")
    if not extension_ok:
        reasons.append("too_extended_from_vwap")
    if not volume_ok:
        reasons.append("recent_1m_volume_fail")
    if not day_range_ok:
        reasons.append("day_range_too_small")

    ok = not reasons
    out.update({
        "ok": ok,
        "reason": "ok" if ok else reasons[0],
        "component_reasons": reasons,
        "price": round(price, 4),
        "orb_high": round(orb_high, 4),
        "orb_low": round(orb_low, 4),
        "vwap": round(vwap, 4),
        "price_above_orb": price_above_orb,
        "price_above_vwap": price_above_vwap,
        "extension_ok": extension_ok,
        "dist_to_vwap_pct": round(extension_pct * 100.0, 3),
        "recent_1m_vol_ratio": round(recent_1m_vol_ratio, 3),
        "volume_ok": volume_ok,
        "day_range_pct": round(day_range_pct * 100.0, 3),
        "day_range_ok": day_range_ok,
    })
    return out

def _hybrid_capacity_plan(current_open_positions: int | None = None) -> dict:
    """Report separate sleeve targets for a future swing+intraday hybrid mode.

    Hybrid execution is still disabled.  This makes sleeve targets
    explicit while intraday candidates are proved in a persistent shadow ledger.
    Pass dashboard snapshot counts to avoid broker calls during dashboard render.
    """
    swing_cap = max(0, int(SWING_SLEEVE_MAX_OPEN_POSITIONS or 0))
    intraday_cap = max(0, int(INTRADAY_SLEEVE_MAX_OPEN_POSITIONS or 0))
    current_total = int(current_open_positions) if current_open_positions is not None else int(count_open_positions_allowed())
    paper_enabled = bool(INTRADAY_PAPER_ENABLED or HYBRID_MODE == "paper")
    live_requested = bool(INTRADAY_LIVE_ENABLED and HYBRID_MODE == "live")
    paper_slots = max(0, min(int(INTRADAY_PAPER_MAX_POSITIONS or 0), intraday_cap))
    return {
        "enabled": paper_enabled or live_requested,
        "mode": HYBRID_MODE,
        "strategy_mode": STRATEGY_MODE,
        "swing_live_enabled": bool(SWING_LIVE_ENABLED),
        "intraday_paper_enabled": paper_enabled,
        "intraday_live_enabled": live_requested,
        "intraday_live_orders_permitted": False,
        "swing_sleeve_max_open_positions": swing_cap,
        "intraday_sleeve_max_open_positions": intraday_cap,
        "intraday_paper_max_positions": paper_slots,
        "combined_target_open_positions": swing_cap + intraday_cap,
        "current_open_positions": current_total,
        "sleeves_configured": swing_cap > 0 and intraday_cap > 0,
        "note": "Hybrid paper mode is simulated only; intraday live orders remain disabled until a future live-hybrid execution patch.",
    }


def persist_hybrid_proof_ledger_state(reason: str = "") -> bool:
    payload = {
        "saved_at_utc": datetime.now(timezone.utc).isoformat(),
        "reason": reason,
        "ledger": list(HYBRID_PROOF_LEDGER[-max(1, int(HYBRID_PROOF_LEDGER_LIMIT or 1)):]),
    }
    return _safe_json_write(HYBRID_PROOF_LEDGER_STATE_PATH, payload)


def restore_hybrid_proof_ledger_state() -> dict:
    payload = _safe_json_read(HYBRID_PROOF_LEDGER_STATE_PATH)
    restored = {"path": HYBRID_PROOF_LEDGER_STATE_PATH, "loaded": False, "ledger_restored": 0}
    if not payload:
        return restored
    try:
        rows = payload.get("ledger") or []
        if isinstance(rows, list) and rows:
            HYBRID_PROOF_LEDGER.clear()
            HYBRID_PROOF_LEDGER.extend([dict(r) for r in rows if isinstance(r, dict)][-max(1, int(HYBRID_PROOF_LEDGER_LIMIT or 1)):])
            restored["ledger_restored"] = len(HYBRID_PROOF_LEDGER)
        restored["loaded"] = bool(restored["ledger_restored"])
    except Exception as exc:
        restored["error"] = str(exc)
    return restored


def _hybrid_proof_entry_key(row: dict) -> str:
    return "|".join([
        str((row or {}).get("ny_date") or ""),
        str((row or {}).get("symbol") or "").upper(),
        str((row or {}).get("signal") or "").upper(),
    ])


def _hybrid_proof_price_from_bars(bars: list[dict]) -> float:
    if not bars:
        return 0.0
    return _safe_float((bars[-1] or {}).get("close") or (bars[-1] or {}).get("price") or 0.0)


def _hybrid_proof_update_entry(row: dict, latest_price: float, ts_utc: str = "") -> dict:
    entry = _safe_float((row or {}).get("entry_price") or 0.0)
    if entry <= 0 or latest_price <= 0:
        return row
    ret_pct = (latest_price - entry) / entry
    risk_per_share = abs(entry - _safe_float((row or {}).get("stop_price") or 0.0))
    latest_r = ((latest_price - entry) / risk_per_share) if risk_per_share > 0 else 0.0
    row["latest_price"] = round(latest_price, 4)
    row["latest_return_pct"] = round(ret_pct, 6)
    row["latest_r"] = round(latest_r, 4)
    row["best_return_pct"] = round(max(_safe_float(row.get("best_return_pct") or ret_pct), ret_pct), 6)
    row["worst_return_pct"] = round(min(_safe_float(row.get("worst_return_pct") or ret_pct), ret_pct), 6)
    row["best_r"] = round(max(_safe_float(row.get("best_r") or latest_r), latest_r), 4)
    row["worst_r"] = round(min(_safe_float(row.get("worst_r") or latest_r), latest_r), 4)
    if ts_utc:
        row["last_observed_utc"] = ts_utc

    status = str(row.get("status") or "open_shadow")
    if status == "open_shadow":
        stop = _safe_float(row.get("stop_price") or 0.0)
        target = _safe_float(row.get("target_price") or 0.0)
        if stop > 0 and latest_price <= stop:
            row["status"] = "shadow_stop_hit"
            row["settled_reason"] = "stop_hit"
            row["settled_utc"] = ts_utc or datetime.now(timezone.utc).isoformat()
        elif target > 0 and latest_price >= target:
            row["status"] = "shadow_target_hit"
            row["settled_reason"] = "target_hit"
            row["settled_utc"] = ts_utc or datetime.now(timezone.utc).isoformat()
        else:
            try:
                if not in_market_hours():
                    row["status"] = "shadow_eod_flat"
                    row["settled_reason"] = "eod_flat"
                    row["settled_utc"] = ts_utc or datetime.now(timezone.utc).isoformat()
            except Exception:
                pass
    return row

def _hybrid_shadow_is_settled(row: dict) -> bool:
    status = str((row or {}).get("status") or "").strip().lower()
    return status in {
        "shadow_stop_hit",
        "shadow_target_hit",
        "shadow_eod_flat",
        "shadow_expired",
        "shadow_settled",
    }

def _hybrid_shadow_parse_session_date(session_date: str):
    text = str(session_date or "").strip()[:10]
    if not text:
        return None

    try:
        parts = text.split("-")
        if len(parts) != 3:
            return None
        year = int(parts[0])
        month = int(parts[1])
        day = int(parts[2])
        return datetime(year, month, day, tzinfo=NY_TZ).date()
    except Exception:
        return None

def _hybrid_shadow_is_unverifiable(row: dict) -> bool:
    status = str((row or {}).get("status") or "").strip().lower()
    return status == "shadow_unverifiable"

def _hybrid_shadow_bar_ts_utc(bar: dict) -> str:
    raw = (bar or {}).get("ts_utc") or (bar or {}).get("timestamp") or (bar or {}).get("t")
    if isinstance(raw, datetime):
        dt = raw
    else:
        try:
            dt = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
        except Exception:
            return ""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc).isoformat()


def _hybrid_shadow_bar_ts_ny(bar: dict) -> Optional[datetime]:
    raw = (bar or {}).get("ts_ny") or (bar or {}).get("ts_utc") or (bar or {}).get("timestamp") or (bar or {}).get("t")
    try:
        return _coerce_dt_ny(raw)
    except Exception:
        return None


def _hybrid_shadow_settle_row(row: dict, price: float, status: str, reason: str, ts_utc: str) -> dict:
    _hybrid_proof_update_entry(row, price, ts_utc=ts_utc)
    row["status"] = status
    row["settled_reason"] = reason
    row["settled_utc"] = ts_utc or utc_now_iso()
    row["settlement_price"] = round(float(price), 4)
    row["settlement_backfilled"] = True
    row["settlement_patch"] = PATCH_VERSION
    return row

def _hybrid_shadow_row_session_date(row: dict) -> str:
    ny_date = str((row or {}).get("ny_date") or "").strip()
    if ny_date:
        return ny_date[:10]

    raw = (
        (row or {}).get("scan_ts_utc")
        or (row or {}).get("created_utc")
        or (row or {}).get("ts_utc")
    )
    if not raw:
        return ""

    try:
        return _coerce_dt_ny(raw).date().isoformat()
    except Exception:
        return ""

def _hybrid_shadow_persist_ledger_after_backfill() -> dict:
    existing_helpers = [
        "_save_hybrid_proof_ledger",
        "_persist_hybrid_proof_ledger",
        "_save_runtime_state",
        "_persist_state",
    ]

    for helper_name in existing_helpers:
        helper = globals().get(helper_name)
        if callable(helper):
            try:
                helper()
                return {
                    "ok": True,
                    "method": helper_name,
                    "path": HYBRID_PROOF_LEDGER_STATE_PATH,
                }
            except TypeError:
                try:
                    helper(HYBRID_PROOF_LEDGER)
                    return {
                        "ok": True,
                        "method": helper_name,
                        "path": HYBRID_PROOF_LEDGER_STATE_PATH,
                    }
                except Exception as exc:
                    logger.warning("hybrid proof ledger helper persist failed helper=%s err=%s", helper_name, exc)
            except Exception as exc:
                logger.warning("hybrid proof ledger helper persist failed helper=%s err=%s", helper_name, exc)

    path = str(HYBRID_PROOF_LEDGER_STATE_PATH or "").strip()
    if not path:
        return {
            "ok": False,
            "method": "none",
            "error": "HYBRID_PROOF_LEDGER_STATE_PATH is empty",
        }

    try:
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)

        payload = list(HYBRID_PROOF_LEDGER)

        try:
            if os.path.exists(path):
                with open(path, "r", encoding="utf-8") as existing_file:
                    existing_payload = json.load(existing_file)

                if isinstance(existing_payload, dict):
                    existing_payload["patch_version"] = PATCH_VERSION
                    existing_payload["updated_utc"] = utc_now_iso()
                    if "ledger" in existing_payload:
                        existing_payload["ledger"] = list(HYBRID_PROOF_LEDGER)
                    elif "hybrid_proof_ledger" in existing_payload:
                        existing_payload["hybrid_proof_ledger"] = list(HYBRID_PROOF_LEDGER)
                    elif "rows" in existing_payload:
                        existing_payload["rows"] = list(HYBRID_PROOF_LEDGER)
                    else:
                        existing_payload["ledger"] = list(HYBRID_PROOF_LEDGER)
                    payload = existing_payload
        except Exception as exc:
            logger.warning("hybrid proof ledger existing payload read failed path=%s err=%s", path, exc)

        tmp_path = f"{path}.tmp"
        with open(tmp_path, "w", encoding="utf-8") as f:
            json.dump(payload, f, default=str)

        os.replace(tmp_path, path)

        return {
            "ok": True,
            "method": "json_fallback",
            "path": path,
            "ledger_count": len(HYBRID_PROOF_LEDGER),
        }
    except Exception as exc:
        logger.exception("hybrid proof ledger persist failed")
        return {
            "ok": False,
            "method": "json_fallback",
            "path": path,
            "error": str(exc),
        }

def _hybrid_shadow_status_breakdown(rows: list[dict]) -> dict:
    counts = {
        "open_shadow": 0,
        "shadow_stop_hit": 0,
        "shadow_target_hit": 0,
        "shadow_eod_flat": 0,
        "shadow_unverifiable": 0,
        "other": 0,
    }

    for row in rows or []:
        if not isinstance(row, dict):
            continue

        status = str(row.get("status") or "").strip().lower()
        if status in counts:
            counts[status] += 1
        else:
            counts["other"] += 1

    counts["settled_performance_count"] = (
        counts["shadow_stop_hit"]
        + counts["shadow_target_hit"]
        + counts["shadow_eod_flat"]
    )
    counts["terminal_count"] = counts["settled_performance_count"] + counts["shadow_unverifiable"]
    return counts
    
def _hybrid_proof_extract_ledger_rows(payload) -> list[dict]:
    if isinstance(payload, list):
        return [r for r in payload if isinstance(r, dict)]

    if not isinstance(payload, dict):
        return []

    candidate_keys = [
        "ledger",
        "hybrid_proof_ledger",
        "proof_ledger",
        "rows",
        "data",
        "items",
    ]

    for key in candidate_keys:
        value = payload.get(key)
        if isinstance(value, list):
            return [r for r in value if isinstance(r, dict)]

    nested_state = payload.get("state")
    if isinstance(nested_state, dict):
        for key in candidate_keys:
            value = nested_state.get(key)
            if isinstance(value, list):
                return [r for r in value if isinstance(r, dict)]

    return []


def _hybrid_proof_load_ledger_compat(force: bool = False) -> dict:
    global HYBRID_PROOF_LEDGER

    if HYBRID_PROOF_LEDGER and not force:
        return {
            "ok": True,
            "loaded": False,
            "reason": "memory_ledger_present",
            "count": len(HYBRID_PROOF_LEDGER),
        }

    path = str(HYBRID_PROOF_LEDGER_STATE_PATH or "").strip()
    if not path:
        return {
            "ok": False,
            "loaded": False,
            "reason": "empty_path",
            "count": len(HYBRID_PROOF_LEDGER),
        }

    if not os.path.exists(path):
        return {
            "ok": False,
            "loaded": False,
            "reason": "path_missing",
            "path": path,
            "count": len(HYBRID_PROOF_LEDGER),
        }

    try:
        with open(path, "r", encoding="utf-8") as f:
            payload = json.load(f)

        rows = _hybrid_proof_extract_ledger_rows(payload)
        if not rows:
            return {
                "ok": False,
                "loaded": False,
                "reason": "no_rows_in_payload",
                "path": path,
                "payload_type": type(payload).__name__,
                "count": len(HYBRID_PROOF_LEDGER),
            }

        HYBRID_PROOF_LEDGER.clear()
        HYBRID_PROOF_LEDGER.extend(rows)

        return {
            "ok": True,
            "loaded": True,
            "reason": "loaded_from_disk",
            "path": path,
            "payload_type": type(payload).__name__,
            "count": len(HYBRID_PROOF_LEDGER),
        }
    except Exception as exc:
        logger.exception("hybrid proof ledger compat load failed")
        return {
            "ok": False,
            "loaded": False,
            "reason": "exception",
            "path": path,
            "error": str(exc),
            "count": len(HYBRID_PROOF_LEDGER),
        }

def _hybrid_shadow_is_regular_session_bar(bar: dict) -> bool:
    bar_dt_ny = _hybrid_shadow_bar_ts_ny(bar)
    if not bar_dt_ny:
        return False

    minutes = bar_dt_ny.hour * 60 + bar_dt_ny.minute
    regular_open = 9 * 60 + 30
    regular_close = 16 * 60

    return regular_open <= minutes < regular_close


def _hybrid_shadow_regular_session_bars_for_row(row: dict, symbol_bars: list[dict]) -> list[dict]:
    row_session_date = _hybrid_shadow_row_session_date(row)
    scan_ts = row.get("scan_ts_utc") or row.get("created_utc") or row.get("ts_utc")

    try:
        entry_dt_ny = _coerce_dt_ny(scan_ts)
    except Exception:
        entry_dt_ny = None

    same_session_bars = []
    for bar in symbol_bars or []:
        bar_dt_ny = _hybrid_shadow_bar_ts_ny(bar)
        if not bar_dt_ny:
            continue

        if bar_dt_ny.date().isoformat() != row_session_date:
            continue

        if entry_dt_ny and bar_dt_ny < entry_dt_ny:
            continue

        if not _hybrid_shadow_is_regular_session_bar(bar):
            continue

        same_session_bars.append(bar)

    same_session_bars.sort(key=lambda b: _hybrid_shadow_bar_ts_ny(b) or now_ny())
    return same_session_bars


def _hybrid_shadow_quality_bucket(value: float, cuts: list[float]) -> str:
    v = _safe_float(value)
    if not cuts:
        return "all"

    lower = None
    for cut in cuts:
        if v < cut:
            if lower is None:
                return f"<{cut:g}"
            return f"{lower:g}-{cut:g}"
        lower = cut

    return f">={cuts[-1]:g}"


def _hybrid_shadow_time_bucket(row: dict) -> str:
    raw = row.get("scan_ts_utc") or row.get("created_utc") or row.get("ts_utc")
    try:
        dt = _coerce_dt_ny(raw)
    except Exception:
        return "unknown"

    minutes = dt.hour * 60 + dt.minute

    if minutes < 10 * 60:
        return "09:30-09:59"
    if minutes < 11 * 60:
        return "10:00-10:59"
    if minutes < 12 * 60:
        return "11:00-11:59"
    if minutes < 14 * 60:
        return "12:00-13:59"
    if minutes < 15 * 60:
        return "14:00-14:59"
    if minutes < 16 * 60:
        return "15:00-15:59"
    return "outside_regular"

def _hybrid_shadow_quality_attribution(rows: list[dict]) -> dict:
    performance_rows = [
        r for r in rows or []
        if isinstance(r, dict) and _hybrid_shadow_is_settled(r)
    ]

    def build_group(key_fn):
        groups = {}

        for row in performance_rows:
            key = str(key_fn(row) or "unknown")
            item = groups.setdefault(key, {
                "count": 0,
                "wins": 0,
                "losses": 0,
                "flat": 0,
                "avg_r_sum": 0.0,
                "avg_return_sum": 0.0,
                "best_r": None,
                "worst_r": None,
                "status_counts": {},
            })

            r_value = _safe_float(row.get("latest_r") or 0.0)
            return_pct = _safe_float(row.get("latest_return_pct") or 0.0)
            status = str(row.get("status") or "unknown").strip().lower()

            item["count"] += 1
            item["avg_r_sum"] += r_value
            item["avg_return_sum"] += return_pct
            item["status_counts"][status] = item["status_counts"].get(status, 0) + 1

            if r_value > 0:
                item["wins"] += 1
            elif r_value < 0:
                item["losses"] += 1
            else:
                item["flat"] += 1

            item["best_r"] = r_value if item["best_r"] is None else max(item["best_r"], r_value)
            item["worst_r"] = r_value if item["worst_r"] is None else min(item["worst_r"], r_value)

        out = []
        for key, item in groups.items():
            count = max(1, int(item["count"]))
            out.append({
                "key": key,
                "count": item["count"],
                "wins": item["wins"],
                "losses": item["losses"],
                "flat": item["flat"],
                "win_rate": round(item["wins"] / count, 4),
                "avg_r": round(item["avg_r_sum"] / count, 4),
                "avg_return_pct": round((item["avg_return_sum"] / count) * 100.0, 4),
                "best_r": round(_safe_float(item["best_r"]), 4),
                "worst_r": round(_safe_float(item["worst_r"]), 4),
                "status_counts": item["status_counts"],
            })

        out.sort(key=lambda x: (x.get("avg_r", 0.0), x.get("count", 0)), reverse=True)
        return out

    return {
        "sample_count": len(performance_rows),
        "by_signal": build_group(lambda r: r.get("signal") or r.get("strategy_name") or "unknown"),
        "by_symbol": build_group(lambda r: r.get("symbol") or "unknown"),
        "by_status": build_group(lambda r: r.get("status") or "unknown"),
        "by_score_bucket": build_group(lambda r: _hybrid_shadow_quality_bucket(_safe_float(r.get("score") or 0.0), [90, 100, 110, 120])),
        "by_rank_score_bucket": build_group(lambda r: _hybrid_shadow_quality_bucket(_safe_float(r.get("rank_score") or 0.0), [100, 120, 130, 140])),
        "by_time_bucket": build_group(_hybrid_shadow_time_bucket),
        "unverifiable_count": sum(1 for r in rows or [] if isinstance(r, dict) and _hybrid_shadow_is_unverifiable(r)),
        "open_shadow_count": sum(1 for r in rows or [] if isinstance(r, dict) and str(r.get("status") or "").strip().lower() == "open_shadow"),
    }

def _intraday_quality_csv_set(raw: str) -> set[str]:
    return {str(x or "").strip().upper() for x in str(raw or "").split(",") if str(x or "").strip()}


def _intraday_quality_csv_list(raw: str) -> list[str]:
    return [str(x or "").strip() for x in str(raw or "").split(",") if str(x or "").strip()]


