def _intraday_promotion_source_of_truth_scenario(fallback: str | None = None) -> str:
    source = str(INTRADAY_PROMOTION_SOURCE_OF_TRUTH or "promoted_env").strip().lower()
    promoted = str(INTRADAY_PAPER_PILOT_PROMOTED_SCENARIO or "").strip().lower()
    required = str(INTRADAY_PAPER_PILOT_REQUIRED_SCENARIO or "").strip().lower()
    active = str(INTRADAY_QUALITY_ACTIVE_SCENARIO or "").strip().lower()
    concurrent = str(CONCURRENT_INTRADAY_REQUIRED_QUALITY_SCENARIO or "").strip().lower()
    fallback_name = str(fallback or "").strip().lower()

    if source in {"required_env", "required"}:
        ordered = [required, promoted, active, concurrent, fallback_name]
    elif source in {"active_env", "active"}:
        ordered = [active, promoted, required, concurrent, fallback_name]
    elif source in {"concurrent_env", "concurrent"}:
        ordered = [concurrent, promoted, required, active, fallback_name]
    else:
        ordered = [promoted, required, active, concurrent, fallback_name]

    for name in ordered:
        if name:
            return name
    return "replay_aligned_paper_pilot"

def _intraday_quality_active_config() -> dict:
    scenarios = _intraday_quality_scenario_configs()
    name = _intraday_promotion_source_of_truth_scenario("paper_pilot_conservative")
    cfg = dict(
        scenarios.get(name)
        or scenarios.get("paper_pilot_conservative")
        or scenarios.get("core_symbols_block_10am")
        or scenarios.get("symbol_allowlist_rank_130_140")
        or scenarios.get("rank_130_140_only")
        or scenarios["custom_env"]
    )
    cfg["requested_scenario"] = name
    cfg["promotion_source_of_truth"] = str(INTRADAY_PROMOTION_SOURCE_OF_TRUTH or "promoted_env").strip().lower()
    return cfg

def _intraday_quality_gate_config() -> dict:
    cfg = _intraday_quality_active_config()
    cfg["active_scenario"] = cfg.get("name")
    cfg["available_scenarios"] = sorted(_intraday_quality_scenario_configs().keys())
    return cfg

def _intraday_quality_time_in_windows(ts_utc: str | None, windows_raw: str) -> bool:
    windows = [w.strip() for w in str(windows_raw or "").split(",") if w.strip()]
    if not windows:
        return False
    try:
        dt_ny = _coerce_dt_ny(ts_utc) if ts_utc else now_ny()
    except Exception:
        dt_ny = now_ny()
    minutes = dt_ny.hour * 60 + dt_ny.minute
    for window in windows:
        try:
            start_raw, end_raw = window.split("-", 1)
            start_t = parse_hhmm(start_raw.strip())
            end_t = parse_hhmm(end_raw.strip())
            start_m = start_t.hour * 60 + start_t.minute
            end_m = end_t.hour * 60 + end_t.minute
            if start_m <= minutes <= end_m:
                return True
        except Exception:
            continue
    return False


def _intraday_quality_gate_reasons(candidate: dict, ts_utc: str | None = None, config: dict | None = None) -> list[str]:
    if not INTRADAY_QUALITY_GATE_ENABLED:
        return []

    cfg = dict(config or _intraday_quality_active_config())
    symbol = str((candidate or {}).get("symbol") or "").strip().upper()
    score = _safe_float((candidate or {}).get("score") or 0.0)
    rank_score = _safe_float((candidate or {}).get("rank_score") or 0.0)
    allowed_symbols = {str(x or "").strip().upper() for x in (cfg.get("allowed_symbols") or []) if str(x or "").strip()}
    blocked_symbols = {str(x or "").strip().upper() for x in (cfg.get("blocked_symbols") or []) if str(x or "").strip()}
    blocked_rank_buckets = {str(x or "").strip().upper() for x in (cfg.get("blocked_rank_buckets") or []) if str(x or "").strip()}
    allowed_signals = {str(x or "").strip().upper() for x in (cfg.get("allowed_signals") or []) if str(x or "").strip()}
    blocked_signals = {str(x or "").strip().upper() for x in (cfg.get("blocked_signals") or []) if str(x or "").strip()}
    signal = str((candidate or {}).get("signal") or (candidate or {}).get("strategy_name") or "").strip().upper()
    rank_bucket = _hybrid_shadow_quality_bucket(rank_score, [100, 120, 130, 140])

    reasons = []
    if allowed_symbols and symbol not in allowed_symbols:
        reasons.append("symbol_not_in_quality_allowlist")
    if blocked_symbols and symbol in blocked_symbols:
        reasons.append("symbol_in_quality_blocklist")
    if score < float(cfg.get("min_score") or 0.0):
        reasons.append("score_below_quality_min")
    if rank_score < float(cfg.get("min_rank_score") or 0.0):
        reasons.append("rank_score_below_quality_min")
    if float(cfg.get("max_rank_score") or 0.0) > 0 and rank_score >= float(cfg.get("max_rank_score") or 0.0):
        reasons.append("rank_score_above_quality_max")
    if rank_bucket.upper() in blocked_rank_buckets:
        reasons.append("rank_bucket_blocked")
    if allowed_signals and signal not in allowed_signals:
        reasons.append("signal_not_in_quality_allowlist")
    if blocked_signals and signal in blocked_signals:
        reasons.append("signal_in_quality_blocklist")

    time_windows = str(cfg.get("time_windows") or "").strip()
    if time_windows and not _intraday_quality_time_in_windows(ts_utc, time_windows):
        reasons.append("time_window_blocked")

    blocked_time_windows = str(cfg.get("blocked_time_windows") or "").strip()
    if blocked_time_windows and _intraday_quality_time_in_windows(ts_utc, blocked_time_windows):
        reasons.append("blocked_time_window")

    return reasons


def _intraday_quality_filter_candidates(candidates: list[dict], ts_utc: str | None = None, config: dict | None = None) -> dict:
    cfg = dict(config or _intraday_quality_active_config())
    accepted = []
    rejected = []
    reason_counts = {}
    for row in candidates or []:
        candidate = dict(row or {})
        reasons = _intraday_quality_gate_reasons(candidate, ts_utc=ts_utc, config=cfg)
        candidate["quality_gate_pass"] = not reasons
        candidate["quality_gate_reasons"] = reasons
        candidate["quality_gate_scenario"] = cfg.get("name")
        if reasons:
            rejected.append(candidate)
            for reason in reasons:
                reason_counts[reason] = reason_counts.get(reason, 0) + 1
        else:
            accepted.append(candidate)
    return {
        "enabled": bool(INTRADAY_QUALITY_GATE_ENABLED),
        "scenario": cfg.get("name"),
        "config": cfg,
        "accepted": accepted,
        "rejected": rejected,
        "accepted_count": len(accepted),
        "rejected_count": len(rejected),
        "raw_count": len(candidates or []),
        "non_empty_guard_ok": len(accepted) > 0 or len(candidates or []) == 0,
        "rejection_reason_counts": reason_counts,
    }


def _intraday_filter_simulate_config(rows: list[dict], cfg: dict, limit: int = 1000) -> dict:
    limited_rows = list(rows or [])[-max(1, min(int(limit or 1000), 5000)):]
    accepted = []
    rejected = []
    reason_counts = {}

    for row in limited_rows:
        reasons = _intraday_quality_gate_reasons(
            row,
            ts_utc=row.get("scan_ts_utc") or row.get("created_utc") or row.get("ts_utc"),
            config=cfg,
        )
        copy_row = dict(row)
        copy_row["quality_gate_pass"] = not reasons
        copy_row["quality_gate_reasons"] = reasons
        copy_row["quality_gate_scenario"] = cfg.get("name")
        if reasons:
            rejected.append(copy_row)
            for reason in reasons:
                reason_counts[reason] = reason_counts.get(reason, 0) + 1
        else:
            accepted.append(copy_row)

    r_values = [_safe_float(r.get("latest_r") or 0.0) for r in accepted]
    returns = [_safe_float(r.get("latest_return_pct") or 0.0) for r in accepted]
    stop_hits = sum(1 for r in accepted if str(r.get("status") or "").strip().lower() == "shadow_stop_hit")
    positive = sum(1 for v in r_values if v > 0)
    accepted_count = len(accepted)
    avg_r = _mean(r_values)
    positive_rate = (positive / accepted_count) if accepted_count else 0.0
    stop_hit_rate = (stop_hits / accepted_count) if accepted_count else 0.0

    blockers = []
    if accepted_count < int(INTRADAY_QUALITY_FILTER_MIN_SETTLED):
        blockers.append("quality_filter_sample_below_min")
    if avg_r < float(HYBRID_PROOF_MIN_AVG_R):
        blockers.append("quality_filter_avg_r_below_min")
    if positive_rate < float(HYBRID_PROOF_LIVE_PROMOTION_MIN_POSITIVE_RATE):
        blockers.append("quality_filter_positive_rate_below_min")

    return {
        "scenario": cfg.get("name"),
        "config": cfg,
        "checked": len(limited_rows),
        "accepted_count": accepted_count,
        "rejected_count": len(rejected),
        "rejection_reason_counts": reason_counts,
        "avg_r": round(avg_r, 4),
        "avg_return_pct": round(_mean(returns) * 100.0, 4),
        "positive_rate": round(positive_rate, 4),
        "stop_hit_count": stop_hits,
        "stop_hit_rate": round(stop_hit_rate, 4),
        "ready": not blockers,
        "blockers": blockers,
        "quality_attribution": _hybrid_shadow_quality_attribution(accepted),
        "accepted_examples": accepted[-25:],
        "rejected_examples": rejected[-10:],
    }

def _intraday_filter_compact_result(row: dict | None) -> dict:
    row = dict(row or {})
    return {
        "scenario": row.get("scenario"),
        "ready": bool(row.get("ready")),
        "blockers": row.get("blockers") or [],
        "checked": row.get("checked"),
        "accepted_count": row.get("accepted_count"),
        "rejected_count": row.get("rejected_count"),
        "avg_r": row.get("avg_r"),
        "avg_return_pct": row.get("avg_return_pct"),
        "positive_rate": row.get("positive_rate"),
        "stop_hit_count": row.get("stop_hit_count"),
        "stop_hit_rate": row.get("stop_hit_rate"),
        "rejection_reason_counts": row.get("rejection_reason_counts") or {},
        "config": row.get("config") or {},
    }


def _intraday_paper_gate_tournament(simulation: dict | None = None) -> dict:
    simulation = dict(simulation or {})
    candidate_names = {
        str(x or "").strip().lower()
        for x in str(INTRADAY_PAPER_GATE_TOURNAMENT_CANDIDATES or "").split(",")
        if str(x or "").strip()
    }
    rows = []
    for row in simulation.get("scenarios") or []:
        name = str((row or {}).get("scenario") or "").strip().lower()
        if candidate_names and name not in candidate_names:
            continue
        compact = _intraday_filter_compact_result(row)
        accepted = int(compact.get("accepted_count") or 0)
        avg_r = _safe_float(compact.get("avg_r") or 0.0)
        positive_rate = _safe_float(compact.get("positive_rate") or 0.0)
        stop_hit_rate = _safe_float(compact.get("stop_hit_rate") or 0.0)
        blockers = []
        if accepted < int(INTRADAY_PAPER_GATE_TOURNAMENT_MIN_ACCEPTED):
            blockers.append("tournament_sample_below_min")
        if avg_r < float(INTRADAY_PAPER_GATE_TOURNAMENT_MIN_AVG_R):
            blockers.append("tournament_avg_r_below_min")
        if positive_rate < float(INTRADAY_PAPER_GATE_TOURNAMENT_MIN_POSITIVE_RATE):
            blockers.append("tournament_positive_rate_below_min")
        if stop_hit_rate > float(INTRADAY_PAPER_GATE_TOURNAMENT_MAX_STOP_HIT_RATE):
            blockers.append("tournament_stop_hit_rate_above_max")

        score = (
            avg_r * 100.0
            + positive_rate * 25.0
            - stop_hit_rate * 20.0
            + min(accepted, 40) * 0.25
        )
        compact["tournament_ready"] = not blockers
        compact["tournament_blockers"] = blockers
        compact["tournament_score"] = round(score, 4)
        rows.append(compact)

    rows.sort(
        key=lambda r: (
            bool(r.get("tournament_ready")),
            _safe_float(r.get("tournament_score") or 0.0),
            _safe_float(r.get("avg_r") or 0.0),
            _safe_float(r.get("positive_rate") or 0.0),
            -_safe_float(r.get("stop_hit_rate") or 0.0),
            int(r.get("accepted_count") or 0),
        ),
        reverse=True,
    )
    recommended = rows[0] if rows else {}

    return {
        "ok": True,
        "mode": "read_only_intraday_paper_gate_tournament",
        "keep_intraday_live_disabled": True,
        "thresholds": {
            "min_accepted": int(INTRADAY_PAPER_GATE_TOURNAMENT_MIN_ACCEPTED),
            "min_avg_r": float(INTRADAY_PAPER_GATE_TOURNAMENT_MIN_AVG_R),
            "min_positive_rate": float(INTRADAY_PAPER_GATE_TOURNAMENT_MIN_POSITIVE_RATE),
            "max_stop_hit_rate": float(INTRADAY_PAPER_GATE_TOURNAMENT_MAX_STOP_HIT_RATE),
        },
        "candidate_names": sorted(candidate_names),
        "recommended_scenario": recommended.get("scenario"),
        "recommended_ready": bool(recommended.get("tournament_ready")),
        "recommended": recommended,
        "ranked": rows,
        "recommended_env": {
            "INTRADAY_QUALITY_ACTIVE_SCENARIO": str(recommended.get("scenario") or ""),
            "INTRADAY_PAPER_PILOT_REQUIRED_SCENARIO": str(recommended.get("scenario") or ""),
            "INTRADAY_PAPER_PILOT_PROMOTED_SCENARIO": str(recommended.get("scenario") or ""),
            "INTRADAY_LIVE_ENABLED": "false",
        } if recommended else {},
    }


def _intraday_shadow_config_freshness_audit() -> dict:
    current_cfg = _intraday_quality_gate_config()
    latest = _latest_scan_item()
    summary = _scan_summary_payload(latest)
    latest_shadow = summary.get("intraday_shadow") if isinstance(summary.get("intraday_shadow"), dict) else {}
    latest_quality = latest_shadow.get("quality_gate") if isinstance(latest_shadow.get("quality_gate"), dict) else {}
    latest_cfg = latest_quality.get("config") if isinstance(latest_quality.get("config"), dict) else {}
    if not latest_cfg:
        latest_cfg = latest_shadow.get("config", {}).get("quality_gate") if isinstance(latest_shadow.get("config"), dict) else {}
    if not isinstance(latest_cfg, dict):
        latest_cfg = {}

    def norm(value) -> str:
        if isinstance(value, (list, tuple, set)):
            return ",".join(sorted(str(x or "").strip().upper() for x in value if str(x or "").strip()))
        return str(value if value is not None else "").strip()

    fields = [
        "name",
        "time_windows",
        "blocked_time_windows",
        "allowed_symbols",
        "blocked_symbols",
        "min_score",
        "min_rank_score",
        "max_rank_score",
        "blocked_rank_buckets",
        "allowed_signals",
        "blocked_signals",
    ]
    mismatches = []
    for field in fields:
        current_value = norm(current_cfg.get(field))
        latest_value = norm(latest_cfg.get(field))
        if current_value != latest_value:
            mismatches.append({
                "field": field,
                "current": current_value,
                "latest_shadow": latest_value,
            })

    latest_scenario = str(latest_quality.get("scenario") or latest_cfg.get("name") or "").strip().lower()
    current_scenario = str(current_cfg.get("name") or "").strip().lower()
    fresh = bool(latest_shadow) and not mismatches and latest_scenario == current_scenario

    return {
        "ok": True,
        "fresh": fresh,
        "reason": "fresh" if fresh else ("no_latest_intraday_shadow" if not latest_shadow else "latest_shadow_config_mismatch"),
        "current_scenario": current_scenario,
        "latest_shadow_scenario": latest_scenario,
        "mismatches": mismatches,
        "latest_shadow_status": latest_shadow.get("status"),
        "latest_shadow_raw_would_trade": latest_shadow.get("raw_would_trade"),
        "latest_shadow_would_trade": latest_shadow.get("would_trade"),
        "latest_shadow_quality_accepted": latest_quality.get("accepted_count"),
        "latest_shadow_quality_rejected": latest_quality.get("rejected_count"),
        "latest_shadow_non_empty_guard_ok": latest_quality.get("non_empty_guard_ok"),
        "current_config": current_cfg,
        "latest_shadow_config": latest_cfg,
    }

def _intraday_filter_simulation(rows: list[dict] | None = None, limit: int = 1000) -> dict:
    _ensure_runtime_state_loaded()
    _hybrid_proof_load_ledger_compat()
    source_rows = [dict(r) for r in (rows if rows is not None else HYBRID_PROOF_LEDGER) if isinstance(r, dict)]
    settled_rows = [r for r in source_rows if _hybrid_shadow_is_settled(r)]
    scenarios = _intraday_quality_scenario_configs()
    active_cfg = _intraday_quality_active_config()

    scenario_results = []
    for cfg in scenarios.values():
        scenario_results.append(_intraday_filter_simulate_config(settled_rows, cfg, limit=limit))

    scenario_results.sort(
        key=lambda r: (
            bool(r.get("ready")),
            int(r.get("accepted_count") or 0) >= int(INTRADAY_QUALITY_FILTER_MIN_SETTLED),
            _safe_float(r.get("avg_r") or 0.0),
            _safe_float(r.get("positive_rate") or 0.0),
            -_safe_float(r.get("stop_hit_rate") or 0.0),
            int(r.get("accepted_count") or 0),
        ),
        reverse=True,
    )

    active_result = _intraday_filter_simulate_config(settled_rows, active_cfg, limit=limit)
    best_ready = next((r for r in scenario_results if bool(r.get("ready"))), None)
    best_non_empty = next((r for r in scenario_results if int(r.get("accepted_count") or 0) > 0), None)

    promoted_name = str(INTRADAY_PAPER_PILOT_PROMOTED_SCENARIO or "replay_aligned_paper_pilot").strip().lower()
    promoted = (
        scenarios.get(promoted_name)
        or scenarios.get("replay_aligned_paper_pilot")
        or scenarios.get("replay_aligned_rank_132_140")
        or scenarios.get("paper_pilot_conservative")
        or scenarios.get("rank_130_140_only")
        or {}
    )
    promoted_result = _intraday_filter_simulate_config(settled_rows, promoted, limit=limit) if promoted else {}

    replay_aligned = scenarios.get("replay_aligned_paper_pilot") or {}
    replay_aligned_result = _intraday_filter_simulate_config(settled_rows, replay_aligned, limit=limit) if replay_aligned else {}

    payload = {
        "enabled": bool(INTRADAY_QUALITY_GATE_ENABLED),
        "active_scenario": active_cfg.get("name"),
        "active": active_result,
        "promoted_paper_scenario": promoted_result,
        "replay_aligned_paper_scenario": replay_aligned_result,
        "best_ready_scenario": best_ready,
        "best_non_empty_scenario": best_non_empty,
        "source_settled_count": len(settled_rows),
        "checked": len(settled_rows[-max(1, min(int(limit or 1000), 5000)):]),
        "ready": bool(active_result.get("ready")),
        "blockers": active_result.get("blockers") or [],
        "paper_pilot_recommendation": {
            "scenario": promoted.get("name") or promoted_name,
            "use_for_paper": bool(promoted_result.get("ready")),
            "keep_intraday_live_disabled": True,
            "reason": "paper_gate_tournament_available_live_still_blocked",
            "accepted_count": promoted_result.get("accepted_count"),
            "avg_r": promoted_result.get("avg_r"),
            "positive_rate": promoted_result.get("positive_rate"),
            "stop_hit_rate": promoted_result.get("stop_hit_rate"),
            "required_active_scenario": INTRADAY_PAPER_PILOT_REQUIRED_SCENARIO,
            "promoted_scenario": promoted.get("name") or promoted_name,
        },
        "thresholds": {
            "min_settled": int(INTRADAY_QUALITY_FILTER_MIN_SETTLED),
            "min_avg_r": float(HYBRID_PROOF_MIN_AVG_R),
            "min_positive_rate": float(HYBRID_PROOF_LIVE_PROMOTION_MIN_POSITIVE_RATE),
        },
        "scenarios": scenario_results,
    }
    payload["paper_gate_tournament"] = _intraday_paper_gate_tournament(payload)
    return payload

def _intraday_paper_pilot_readiness() -> dict:
    sim = _intraday_filter_simulation(limit=1000)
    scenarios = _intraday_quality_scenario_configs()
    tournament = sim.get("paper_gate_tournament") or {}

    tournament_recommended = str(tournament.get("recommended_scenario") or "").strip().lower()
    canonical_name = _intraday_promotion_source_of_truth_scenario(tournament_recommended or "replay_aligned_paper_pilot")
    required_name = canonical_name
    promoted_name = canonical_name
    expected_name = canonical_name

    promoted_cfg = (
        scenarios.get(promoted_name)
        or scenarios.get(expected_name)
        or scenarios.get(required_name)
        or scenarios.get("replay_aligned_paper_pilot")
        or {}
    )
    replay_rank_cfg = scenarios.get("replay_aligned_rank_132_140") or {}
    conservative_cfg = scenarios.get("paper_pilot_conservative") or {}
    legacy_core_cfg = scenarios.get("core_symbols_block_10am") or {}
    tournament_cfg = scenarios.get(expected_name) or promoted_cfg

    rows = [dict(r) for r in HYBRID_PROOF_LEDGER if isinstance(r, dict)]
    settled_rows = [r for r in rows if _hybrid_shadow_is_settled(r)]

    promoted = _intraday_filter_simulate_config(settled_rows, promoted_cfg, limit=1000) if promoted_cfg else {}
    replay_rank = _intraday_filter_simulate_config(settled_rows, replay_rank_cfg, limit=1000) if replay_rank_cfg else {}
    conservative = _intraday_filter_simulate_config(settled_rows, conservative_cfg, limit=1000) if conservative_cfg else {}
    legacy_core = _intraday_filter_simulate_config(settled_rows, legacy_core_cfg, limit=1000) if legacy_core_cfg else {}
    tournament_gate = _intraday_filter_simulate_config(settled_rows, tournament_cfg, limit=1000) if tournament_cfg else {}

    active_name = str((sim.get("active_scenario") or "")).strip().lower()
    blockers = []
    if not bool(INTRADAY_PAPER_ENABLED or HYBRID_MODE == "paper"):
        blockers.append("intraday_paper_not_enabled")
    if str(HYBRID_MODE or "").strip().lower() != "paper":
        blockers.append("hybrid_mode_not_paper")
    if bool(INTRADAY_LIVE_ENABLED):
        blockers.append("intraday_live_should_remain_disabled")
    if expected_name and active_name != expected_name:
        blockers.append("active_scenario_not_source_of_truth")
    if not bool(tournament_gate.get("ready")):
        blockers.append("source_of_truth_gate_not_ready_from_shadow_ledger")

    return {
        "ok": not blockers,
        "ready": not blockers,
        "blockers": blockers,
        "active_scenario": sim.get("active_scenario"),
        "required_active_scenario": expected_name,
        "promoted_scenario": promoted_name,
        "tournament_recommended_scenario": tournament_recommended,
        "promotion_source_of_truth": str(INTRADAY_PROMOTION_SOURCE_OF_TRUTH or "promoted_env").strip().lower(),
        "source_of_truth_scenario": expected_name,
        "promoted_paper_gate": promoted,
        "tournament_recommended_gate": tournament_gate,
        "replay_aligned_rank_gate": replay_rank,
        "paper_pilot_conservative_gate": conservative,
        "legacy_core_symbols_gate": legacy_core,
        "paper_gate_tournament": tournament,
        "shadow_config_freshness": _intraday_shadow_config_freshness_audit(),
        "evidence_accelerator": {
            "enabled": True,
            "purpose": "select_best_forward_paper_gate_from_shadow_ledger_tournament",
            "keep_intraday_live_disabled": True,
            "required_settled_samples": int(INTRADAY_QUALITY_FILTER_MIN_SETTLED),
            "current_promoted_accepted_count": promoted.get("accepted_count"),
            "current_promoted_ready": bool(promoted.get("ready")),
            "current_promoted_blockers": promoted.get("blockers") or [],
            "tournament_recommended_scenario": tournament_recommended,
            "tournament_recommended_ready": bool(tournament.get("recommended_ready")),
        },
        "required_env": {
            "HYBRID_MODE": "paper",
            "INTRADAY_LIVE_ENABLED": "false",
            "INTRADAY_QUALITY_ACTIVE_SCENARIO": expected_name,
            "INTRADAY_PAPER_PILOT_REQUIRED_SCENARIO": expected_name,
            "INTRADAY_PAPER_PILOT_PROMOTED_SCENARIO": expected_name,
        },
        "recommended_env": {
            "INTRADAY_QUALITY_ACTIVE_SCENARIO": expected_name,
            "INTRADAY_PAPER_PILOT_REQUIRED_SCENARIO": expected_name,
            "INTRADAY_PAPER_PILOT_PROMOTED_SCENARIO": expected_name,
            "INTRADAY_LIVE_ENABLED": "false",
        },
        "notes": [
            "This is a paper-pilot readiness gate only.",
            "Intraday live remains disabled until the selected paper gate proves itself forward and live promotion truth is clean.",
            "The paper gate tournament ranks candidate gates by sample size, avg R, positive rate, and stop-hit rate.",
            "The active shadow config freshness audit confirms whether the most recent shadow scan used the current active gate.",
        ],
    }

def _intraday_replay_symbols(raw_symbols: str = "") -> list[str]:
    raw = str(raw_symbols or "").strip()
    if raw:
        return _dedupe_keep_order([s.strip().upper() for s in raw.split(",") if s.strip()])

    cfg = _intraday_quality_active_config()
    allowed = [str(s or "").strip().upper() for s in (cfg.get("allowed_symbols") or []) if str(s or "").strip()]
    if allowed:
        return _dedupe_keep_order(allowed)

    env_allowed = _intraday_quality_csv_list(str(INTRADAY_QUALITY_ALLOWED_SYMBOLS or ""))
    if env_allowed:
        return _dedupe_keep_order([s.upper() for s in env_allowed])

    return sorted(ALLOWED_SYMBOLS)[: max(1, min(10, int(SCANNER_MAX_SYMBOLS_PER_CYCLE or 10)))]


def _intraday_replay_session_dates(bars: list[dict]) -> list:
    dates = set()
    for row in bars or []:
        dt = _coerce_dt_ny((row or {}).get("ts_ny") or (row or {}).get("ts_utc"))
        if not dt:
            continue
        if MARKET_OPEN <= dt.time() <= MARKET_CLOSE:
            dates.add(dt.date())
    return sorted(dates)


def _intraday_replay_exit(
    *,
    entry_bar: dict,
    forward_bars: list[dict],
    entry_price: float,
    stop_price: float,
    target_price: float,
) -> dict:
    for row in forward_bars or []:
        low = _safe_float(row.get("low") or row.get("close") or 0.0)
        high = _safe_float(row.get("high") or row.get("close") or 0.0)

        # Conservative same-bar ordering: if both stop and target are touched, count stop first.
        if low <= stop_price:
            return {
                "exit_reason": "stop_hit",
                "exit_price": stop_price,
                "exit_ts_utc": _iso_utc(row.get("ts_utc")),
                "status": "shadow_stop_hit",
            }
        if high >= target_price:
            return {
                "exit_reason": "target_hit",
                "exit_price": target_price,
                "exit_ts_utc": _iso_utc(row.get("ts_utc")),
                "status": "shadow_target_hit",
            }

    eod_bar = (forward_bars or [entry_bar])[-1]
    return {
        "exit_reason": "eod_flat",
        "exit_price": _safe_float(eod_bar.get("close") or entry_price),
        "exit_ts_utc": _iso_utc(eod_bar.get("ts_utc")),
        "status": "shadow_eod_flat",
    }


def _intraday_replay_candidate_from_diag(
    *,
    symbol: str,
    signal_name: str,
    diag: dict,
    signal_bar: dict,
    entry_bar: dict,
    session_date,
) -> dict:
    rank_score, rank_diag = compute_signal_rank(signal_name, diag)
    entry_price = _safe_float(entry_bar.get("open") or entry_bar.get("close") or diag.get("price") or 0.0)
    stop_price = _safe_float(diag.get("stop_price") or 0.0)

    if entry_price <= 0:
        return {}
    if stop_price <= 0 or stop_price >= entry_price:
        stop_price = max(0.01, entry_price * 0.9975)

    risk_per_share = max(entry_price - stop_price, entry_price * 0.0025)
    target_price = entry_price + (risk_per_share * float(SWING_TARGET_R_MULT or 1.8))

    return {
        "id": str(uuid.uuid4()),
        "source": "intraday_replay",
        "ny_date": session_date.isoformat() if session_date else "",
        "session_date": session_date.isoformat() if session_date else "",
        "scan_ts_utc": _iso_utc(signal_bar.get("ts_utc")),
        "entry_ts_utc": _iso_utc(entry_bar.get("ts_utc")),
        "symbol": str(symbol or "").upper(),
        "signal": signal_name,
        "side": "buy",
        "entry_price": round(entry_price, 4),
        "stop_price": round(stop_price, 4),
        "target_price": round(target_price, 4),
        "risk_per_share": round(risk_per_share, 4),
        "score": round(_safe_float(diag.get("score") or 0.0), 4),
        "rank_score": round(rank_score, 4),
        "rank_diag": rank_diag,
        "would_pass_rank": True,
        "diagnostics": {
            "reason": diag.get("reason"),
            "candidate_path": diag.get("candidate_path"),
            "bars_1m": diag.get("bars_1m"),
            "bars_5m": diag.get("bars_5m"),
            "vwap": diag.get("vwap"),
            "dist_to_vwap_pct": diag.get("dist_to_vwap_pct"),
            "recent_1m_vol_ratio": diag.get("recent_1m_vol_ratio"),
            "orb_vwap_quality_gate": diag.get("orb_vwap_quality_gate"),
        },
    }


def _intraday_replay_apply_exit(candidate: dict, exit_result: dict) -> dict:
    row = dict(candidate or {})
    entry_price = _safe_float(row.get("entry_price") or 0.0)
    risk_per_share = _safe_float(row.get("risk_per_share") or 0.0)
    exit_price = _safe_float(exit_result.get("exit_price") or entry_price)

    latest_return_pct = ((exit_price - entry_price) / entry_price) if entry_price else 0.0
    latest_r = ((exit_price - entry_price) / risk_per_share) if risk_per_share else 0.0

    row.update({
        "status": exit_result.get("status"),
        "settled_reason": "intraday_replay_" + str(exit_result.get("exit_reason") or "unknown"),
        "settled_utc": exit_result.get("exit_ts_utc"),
        "settlement_price": round(exit_price, 4),
        "latest_price": round(exit_price, 4),
        "latest_return_pct": round(latest_return_pct, 6),
        "latest_r": round(latest_r, 4),
        "best_return_pct": round(max(latest_return_pct, 0.0), 6),
        "worst_return_pct": round(min(latest_return_pct, 0.0), 6),
        "best_r": round(max(latest_r, 0.0), 4),
        "worst_r": round(min(latest_r, 0.0), 4),
        "last_observed_utc": exit_result.get("exit_ts_utc"),
        "settlement_backfilled": False,
        "settlement_patch": PATCH_VERSION,
        "settlement_session_date": row.get("session_date"),
        "settlement_same_session": True,
        "settlement_regular_session": True,
    })
    return row


def _intraday_replay_summary(rows: list[dict]) -> dict:
    rows = [dict(r) for r in rows or [] if isinstance(r, dict)]
    r_values = [_safe_float(r.get("latest_r") or 0.0) for r in rows]
    returns = [_safe_float(r.get("latest_return_pct") or 0.0) for r in rows]
    wins = sum(1 for r in r_values if r > 0)
    losses = sum(1 for r in r_values if r < 0)
    stops = sum(1 for r in rows if str(r.get("status") or "") == "shadow_stop_hit")
    targets = sum(1 for r in rows if str(r.get("status") or "") == "shadow_target_hit")
    eod = sum(1 for r in rows if str(r.get("status") or "") == "shadow_eod_flat")
    count = len(rows)

    return {
        "count": count,
        "wins": wins,
        "losses": losses,
        "win_rate": round((wins / count) if count else 0.0, 4),
        "avg_r": round(_mean(r_values), 4),
        "avg_return_pct": round(_mean(returns) * 100.0, 4),
        "best_r": round(max(r_values), 4) if r_values else 0.0,
        "worst_r": round(min(r_values), 4) if r_values else 0.0,
        "stop_hit_count": stops,
        "stop_hit_rate": round((stops / count) if count else 0.0, 4),
        "target_hit_count": targets,
        "eod_flat_count": eod,
        "quality_attribution": _hybrid_shadow_quality_attribution(rows),
        "examples": rows[-25:],
    }

def _intraday_replay_lab_scenario_configs(base_cfg: dict) -> dict[str, dict]:
    base_cfg = dict(base_cfg or _intraday_quality_active_config())

    def cfg(
        name: str,
        *,
        allowed_symbols: str = "",
        blocked_symbols: str = "",
        time_windows: str = "",
        blocked_time_windows: str = "",
        min_rank_score: float | None = None,
        max_rank_score: float | None = None,
        allowed_signals: str = "",
        blocked_signals: str = "",
    ) -> dict:
        out = dict(base_cfg)
        out["name"] = name
        if allowed_symbols:
            out["allowed_symbols"] = sorted(_intraday_quality_csv_set(allowed_symbols))
        if blocked_symbols:
            out["blocked_symbols"] = sorted(_intraday_quality_csv_set(blocked_symbols))
        if time_windows:
            out["time_windows"] = time_windows
        if blocked_time_windows:
            out["blocked_time_windows"] = blocked_time_windows
        if min_rank_score is not None:
            out["min_rank_score"] = float(min_rank_score)
        if max_rank_score is not None:
            out["max_rank_score"] = float(max_rank_score)
        out["allowed_signals"] = sorted(_intraday_quality_csv_set(allowed_signals))
        out["blocked_signals"] = sorted(_intraday_quality_csv_set(blocked_signals))
        return out

    return {
        "active_current": cfg("active_current"),
        "core_symbols_only": cfg(
            "core_symbols_only",
            allowed_symbols="MRVL,PANW,CRWD,AMD",
        ),
        "best_three_only": cfg(
            "best_three_only",
            allowed_symbols="MRVL,PANW,CRWD",
        ),
        "exclude_replay_losers": cfg(
            "exclude_replay_losers",
            blocked_symbols="AMAT,NET,SPY,MU",
        ),
        "block_10am_hour": cfg(
            "block_10am_hour",
            blocked_time_windows="10:00-10:59",
        ),
        "core_symbols_block_10am": cfg(
            "core_symbols_block_10am",
            allowed_symbols="MRVL,PANW,CRWD,AMD",
            blocked_time_windows="10:00-10:59",
        ),
        "best_three_block_10am": cfg(
            "best_three_block_10am",
            allowed_symbols="MRVL,PANW,CRWD",
            blocked_time_windows="10:00-10:59",
        ),
        "morning_or_late_only": cfg(
            "morning_or_late_only",
            time_windows="09:30-09:59,11:00-11:59,14:00-15:59",
        ),
        "reclaim_only": cfg(
            "reclaim_only",
            allowed_signals="INTRADAY_VWAP_RECLAIM",
        ),
        "continuation_only": cfg(
            "continuation_only",
            allowed_signals="INTRADAY_VWAP_CONTINUATION",
        ),
        "core_reclaim_block_10am": cfg(
            "core_reclaim_block_10am",
            allowed_symbols="MRVL,PANW,CRWD,AMD",
            blocked_time_windows="10:00-10:59",
            allowed_signals="INTRADAY_VWAP_RECLAIM",
        ),
        "rank_132_140": cfg(
            "rank_132_140",
            min_rank_score=132,
            max_rank_score=140,
        ),
        "core_rank_132_140_block_10am": cfg(
            "core_rank_132_140_block_10am",
            allowed_symbols="MRVL,PANW,CRWD,AMD",
            blocked_time_windows="10:00-10:59",
            min_rank_score=132,
            max_rank_score=140,
        ),
    }


def _intraday_replay_lab_signal_reasons(candidate: dict, cfg: dict) -> list[str]:
    signal = str((candidate or {}).get("signal") or "").strip().upper()
    allowed = {str(x or "").strip().upper() for x in (cfg.get("allowed_signals") or []) if str(x or "").strip()}
    blocked = {str(x or "").strip().upper() for x in (cfg.get("blocked_signals") or []) if str(x or "").strip()}

    reasons = []
    if allowed and signal not in allowed:
        reasons.append("signal_not_in_replay_allowlist")
    if blocked and signal in blocked:
        reasons.append("signal_in_replay_blocklist")
    return reasons


def _intraday_replay_lab_apply_config(rows: list[dict], cfg: dict) -> dict:
    accepted = []
    rejected = []
    reason_counts = Counter()

    for row in rows or []:
        candidate = dict(row or {})
        reasons = _intraday_quality_gate_reasons(
            candidate,
            ts_utc=candidate.get("scan_ts_utc") or candidate.get("entry_ts_utc"),
            config=cfg,
        )
        reasons.extend(_intraday_replay_lab_signal_reasons(candidate, cfg))

        candidate["replay_lab_pass"] = not reasons
        candidate["replay_lab_reasons"] = reasons
        candidate["replay_lab_scenario"] = cfg.get("name")

        if reasons:
            rejected.append(candidate)
            for reason in reasons:
                reason_counts[reason] += 1
        else:
            accepted.append(candidate)

    summary = _intraday_replay_summary(accepted)
    blockers = []
    if summary.get("count", 0) < int(INTRADAY_QUALITY_FILTER_MIN_SETTLED):
        blockers.append("replay_sample_below_min")
    if _safe_float(summary.get("avg_r") or 0.0) < float(HYBRID_PROOF_MIN_AVG_R):
        blockers.append("replay_avg_r_below_min")
    if _safe_float(summary.get("win_rate") or 0.0) < float(HYBRID_PROOF_LIVE_PROMOTION_MIN_POSITIVE_RATE):
        blockers.append("replay_win_rate_below_min")
    if _safe_float(summary.get("stop_hit_rate") or 0.0) > 0.35:
        blockers.append("replay_stop_hit_rate_too_high")

    return {
        "scenario": cfg.get("name"),
        "config": cfg,
        "accepted_count": len(accepted),
        "rejected_count": len(rejected),
        "ready": not blockers,
        "blockers": blockers,
        "summary": summary,
        "rejection_reason_counts": dict(reason_counts),
        "accepted_examples": accepted[-20:],
        "rejected_examples": rejected[-10:],
    }


def _intraday_replay_lab_recommendations(results: list[dict]) -> dict:
    ranked = sorted(
        [dict(r) for r in results or []],
        key=lambda r: (
            bool(r.get("ready")),
            _safe_float((r.get("summary") or {}).get("avg_r") or 0.0),
            _safe_float((r.get("summary") or {}).get("win_rate") or 0.0),
            -_safe_float((r.get("summary") or {}).get("stop_hit_rate") or 0.0),
            int(r.get("accepted_count") or 0),
        ),
        reverse=True,
    )
    best = ranked[0] if ranked else {}

    symbol_rows = ((best.get("summary") or {}).get("quality_attribution") or {}).get("by_symbol") or []
    time_rows = ((best.get("summary") or {}).get("quality_attribution") or {}).get("by_time_bucket") or []
    signal_rows = ((best.get("summary") or {}).get("quality_attribution") or {}).get("by_signal") or []

    reduce_symbols = [
        r.get("key")
        for r in symbol_rows
        if int(r.get("count") or 0) >= 3 and _safe_float(r.get("avg_r") or 0.0) < 0
    ]
    promote_symbols = [
        r.get("key")
        for r in symbol_rows
        if int(r.get("count") or 0) >= 3 and _safe_float(r.get("avg_r") or 0.0) >= float(HYBRID_PROOF_MIN_AVG_R)
    ]
    block_times = [
        r.get("key")
        for r in time_rows
        if int(r.get("count") or 0) >= 5 and _safe_float(r.get("avg_r") or 0.0) < 0
    ]
    promote_signals = [
        r.get("key")
        for r in signal_rows
        if int(r.get("count") or 0) >= 5 and _safe_float(r.get("avg_r") or 0.0) >= float(HYBRID_PROOF_MIN_AVG_R)
    ]

    return {
        "best_scenario": best.get("scenario"),
        "best_ready": bool(best.get("ready")),
        "best_summary": best.get("summary") or {},
        "ranked_scenarios": [
            {
                "scenario": r.get("scenario"),
                "ready": bool(r.get("ready")),
                "blockers": r.get("blockers") or [],
                "accepted_count": r.get("accepted_count"),
                "avg_r": (r.get("summary") or {}).get("avg_r"),
                "win_rate": (r.get("summary") or {}).get("win_rate"),
                "stop_hit_rate": (r.get("summary") or {}).get("stop_hit_rate"),
            }
            for r in ranked
        ],
        "recommended_env_if_promoted_to_paper": {
            "INTRADAY_QUALITY_ALLOWED_SYMBOLS": ",".join([str(s) for s in promote_symbols if s]),
            "INTRADAY_QUALITY_BLOCKED_SYMBOLS": ",".join([str(s) for s in reduce_symbols if s]),
            "INTRADAY_QUALITY_BLOCKED_TIME_WINDOWS": ",".join([str(t) for t in block_times if t]),
        },
        "kill_switch_recommendations": {
            "keep_intraday_live_disabled": True,
            "reduce_or_block_symbols": reduce_symbols,
            "candidate_symbols_for_paper": promote_symbols,
            "block_time_windows": block_times,
            "candidate_signals_for_paper": promote_signals,
        },
    }

def _intraday_symbol_discovery_default_universe() -> list[str]:
    return _dedupe_keep_order([
        "AAPL", "MSFT", "NVDA", "AMD", "AVGO", "TSLA", "META", "AMZN", "GOOGL", "NFLX",
        "PANW", "CRWD", "MRVL", "MU", "AMAT", "LRCX", "KLAC", "ANET", "NET", "DDOG",
        "SNOW", "SHOP", "UBER", "COIN", "PLTR", "ARM", "SMCI", "DELL", "ORCL", "CRM",
        "NOW", "ADBE", "INTC", "QCOM", "TXN", "IBM", "SPY", "QQQ", "IWM", "DIA",
    ])


def _intraday_symbol_discovery_symbols(symbols: str = "", max_symbols: int = 20) -> list[str]:
    if str(symbols or "").strip():
        raw = [s.strip().upper() for s in str(symbols or "").split(",") if s.strip()]
    else:
        raw = _intraday_symbol_discovery_default_universe()
    return _dedupe_keep_order(raw)[: max(1, min(int(max_symbols or 20), 60))]


def _intraday_symbol_discovery_score(summary: dict) -> float:
    count = int((summary or {}).get("count") or 0)
    avg_r = _safe_float((summary or {}).get("avg_r") or 0.0)
    win_rate = _safe_float((summary or {}).get("win_rate") or 0.0)
    stop_hit_rate = _safe_float((summary or {}).get("stop_hit_rate") or 0.0)
    target_hit_count = int((summary or {}).get("target_hit_count") or 0)
    sample_bonus = min(count, 20) * 0.015
    target_bonus = min(target_hit_count, 8) * 0.025
    return round((avg_r * 1.5) + win_rate - stop_hit_rate + sample_bonus + target_bonus, 4)


def _intraday_symbol_discovery_replay_lab(
    *,
    symbols: str = "",
    lookback_days: int = 30,
    max_symbols: int = 20,
    limit_per_symbol: int = 12000,
    min_trades: int = 5,
    min_avg_r: float = 0.10,
    min_win_rate: float = 0.45,
    max_stop_hit_rate: float = 0.40,
    blocked_time_windows: str = "10:00-10:59,15:00-15:59",
    min_rank_score: float = 130,
    max_rank_score: float = 140,
) -> dict:
    syms = _intraday_symbol_discovery_symbols(symbols=symbols, max_symbols=max_symbols)
    results = []

    for sym in syms:
        cfg = _intraday_quality_config_from_values(
            name=f"discovery_{sym.lower()}",
            allowed_symbols=sym,
            blocked_time_windows=blocked_time_windows,
            min_rank_score=float(min_rank_score or 130),
            max_rank_score=float(max_rank_score or 140),
        )

        try:
            replay = _intraday_replay_backtest(
                symbols=sym,
                lookback_days=int(lookback_days or 30),
                scenario="rank_130_140_only",
                limit_per_symbol=int(limit_per_symbol or 12000),
                max_trades_per_symbol_session=1,
                config_override=cfg,
            )
            summary = replay.get("all") or {}
            validation = replay.get("validation") or {}
            count = int(summary.get("count") or 0)
            avg_r = _safe_float(summary.get("avg_r") or 0.0)
            win_rate = _safe_float(summary.get("win_rate") or 0.0)
            stop_hit_rate = _safe_float(summary.get("stop_hit_rate") or 0.0)

            blockers = []
            if count < int(min_trades or 5):
                blockers.append("sample_below_min")
            if avg_r < float(min_avg_r or 0.10):
                blockers.append("avg_r_below_min")
            if win_rate < float(min_win_rate or 0.45):
                blockers.append("win_rate_below_min")
            if stop_hit_rate > float(max_stop_hit_rate or 0.40):
                blockers.append("stop_hit_rate_above_max")

            results.append({
                "symbol": sym,
                "ready": not blockers,
                "blockers": blockers,
                "score": _intraday_symbol_discovery_score(summary),
                "summary": summary,
                "validation": validation,
                "sessions": replay.get("session_count"),
                "bars": (replay.get("bars_by_symbol") or {}).get(sym),
                "fetch_errors": replay.get("fetch_errors") or [],
            })
        except Exception as exc:
            results.append({
                "symbol": sym,
                "ready": False,
                "blockers": ["replay_error"],
                "score": -999,
                "error": str(exc),
            })

    ranked = sorted(
        results,
        key=lambda r: (
            bool(r.get("ready")),
            _safe_float(r.get("score") or 0.0),
            _safe_float((r.get("summary") or {}).get("avg_r") or 0.0),
            _safe_float((r.get("summary") or {}).get("win_rate") or 0.0),
            -_safe_float((r.get("summary") or {}).get("stop_hit_rate") or 0.0),
            int((r.get("summary") or {}).get("count") or 0),
        ),
        reverse=True,
    )

    ready_symbols = [r.get("symbol") for r in ranked if bool(r.get("ready"))]
    top_symbols = [r.get("symbol") for r in ranked[:8] if r.get("symbol")]

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "read_only_intraday_symbol_discovery_replay_lab",
        "lookback_days": int(lookback_days or 30),
        "symbols_checked": syms,
        "blocked_time_windows": blocked_time_windows,
        "rank_window": {
            "min_rank_score": float(min_rank_score or 130),
            "max_rank_score": float(max_rank_score or 140),
        },
        "thresholds": {
            "min_trades": int(min_trades or 5),
            "min_avg_r": float(min_avg_r or 0.10),
            "min_win_rate": float(min_win_rate or 0.45),
            "max_stop_hit_rate": float(max_stop_hit_rate or 0.40),
        },
        "ready_symbols": ready_symbols,
        "top_symbols": top_symbols,
        "recommended_next_allowed_symbols": ",".join(ready_symbols[:6]),
        "keep_intraday_live_disabled": True,
        "ranked": ranked,
        "notes": [
            "Discovery is replay-only and does not change the active paper pilot.",
            "Symbols should be promoted only after replay and forward paper evidence agree.",
            "Use the top candidates to build the next paper pilot allowlist.",
        ],
    }

def _intraday_replay_backtest(
    *,
    symbols: str = "",
    lookback_days: int = 30,
    scenario: str = "",
    limit_per_symbol: int = 12000,
    max_trades_per_symbol_session: int = 1,
    config_override: dict | None = None,
) -> dict:
    syms = _intraday_replay_symbols(symbols)
    lookback = max(1, min(int(lookback_days or 30), 90))
    limit = max(1000, min(int(limit_per_symbol or 12000), 50000))
    max_trades = max(1, min(int(max_trades_per_symbol_session or 1), 10))

    scenarios = _intraday_quality_scenario_configs()
    active_cfg = _intraday_quality_active_config()
    scenario_name = str(scenario or active_cfg.get("name") or "").strip().lower()
    cfg = dict(config_override or scenarios.get(scenario_name) or active_cfg)

    bars_map: dict[str, list[dict]] = {}
    fetch_errors = []
    for chunk in _chunked(syms, 4):
        try:
            chunk_rows = fetch_1m_bars_multi(chunk, lookback_days=lookback, limit_per_symbol=limit)
            for sym in chunk:
                bars_map[sym] = list((chunk_rows or {}).get(sym) or [])
        except Exception as exc:
            fetch_errors.append({"symbols": chunk, "error": str(exc)})
            for sym in chunk:
                bars_map.setdefault(sym, [])

    accepted_rows: list[dict] = []
    rejected_rows: list[dict] = []
    raw_triggered_count = 0
    sessions_seen = set()
    symbol_session_counts: dict[str, int] = {}

    for sym in syms:
        bars = sorted(bars_map.get(sym) or [], key=lambda r: r.get("ts_utc") or datetime.min.replace(tzinfo=timezone.utc))
        for session_date in _intraday_replay_session_dates(bars):
            session_rows = _bars_for_regular_session_date(bars, session_date)
            if len(session_rows) < 25:
                continue

            sessions_seen.add(session_date.isoformat())
            taken_for_session = 0

            for idx in range(10, len(session_rows) - 1):
                if taken_for_session >= max_trades:
                    break

                signal_bar = session_rows[idx]
                entry_bar = session_rows[idx + 1]
                bars_to_signal = session_rows[: idx + 1]
                forward_bars = session_rows[idx + 1 :]

                candidates = []

                reclaim_sig, reclaim_diag = eval_intraday_vwap_reclaim_signal_with_diag(
                    bars_to_signal,
                    force_enable=True,
                    session_date=session_date,
                )
                if reclaim_sig:
                    row = _intraday_replay_candidate_from_diag(
                        symbol=sym,
                        signal_name="INTRADAY_VWAP_RECLAIM",
                        diag=reclaim_diag,
                        signal_bar=signal_bar,
                        entry_bar=entry_bar,
                        session_date=session_date,
                    )
                    if row:
                        candidates.append(row)

                continuation_sig, continuation_diag = eval_intraday_vwap_continuation_signal_with_diag(
                    bars_to_signal,
                    force_enable=True,
                    session_date=session_date,
                )
                if continuation_sig:
                    row = _intraday_replay_candidate_from_diag(
                        symbol=sym,
                        signal_name="INTRADAY_VWAP_CONTINUATION",
                        diag=continuation_diag,
                        signal_bar=signal_bar,
                        entry_bar=entry_bar,
                        session_date=session_date,
                    )
                    if row:
                        candidates.append(row)

                if not candidates:
                    continue

                raw_triggered_count += len(candidates)
                candidates.sort(key=lambda r: _safe_float(r.get("rank_score") or 0.0), reverse=True)

                for candidate in candidates:
                    reasons = _intraday_quality_gate_reasons(
                        candidate,
                        ts_utc=candidate.get("scan_ts_utc"),
                        config=cfg,
                    )
                    candidate["quality_gate_pass"] = not reasons
                    candidate["quality_gate_reasons"] = reasons
                    candidate["quality_gate_scenario"] = cfg.get("name")

                    if reasons:
                        rejected_rows.append(candidate)
                        continue

                    exit_result = _intraday_replay_exit(
                        entry_bar=entry_bar,
                        forward_bars=forward_bars,
                        entry_price=_safe_float(candidate.get("entry_price") or 0.0),
                        stop_price=_safe_float(candidate.get("stop_price") or 0.0),
                        target_price=_safe_float(candidate.get("target_price") or 0.0),
                    )
                    accepted_rows.append(_intraday_replay_apply_exit(candidate, exit_result))
                    taken_for_session += 1
                    symbol_session_counts[sym] = symbol_session_counts.get(sym, 0) + 1
                    break

    session_list = sorted(sessions_seen)
    validation_session_count = max(1, min(5, len(session_list) // 3 if len(session_list) >= 3 else len(session_list)))
    validation_sessions = set(session_list[-validation_session_count:]) if session_list else set()
    train_rows = [r for r in accepted_rows if r.get("session_date") not in validation_sessions]
    validation_rows = [r for r in accepted_rows if r.get("session_date") in validation_sessions]

    filter_result = _intraday_filter_simulate_config(accepted_rows, cfg, limit=max(1000, len(accepted_rows) or 1000))

    lab_configs = _intraday_replay_lab_scenario_configs(cfg)
    lab_results = [
        _intraday_replay_lab_apply_config(accepted_rows, lab_cfg)
        for lab_cfg in lab_configs.values()
    ]
    lab_results.sort(
        key=lambda r: (
            bool(r.get("ready")),
            _safe_float((r.get("summary") or {}).get("avg_r") or 0.0),
            _safe_float((r.get("summary") or {}).get("win_rate") or 0.0),
            -_safe_float((r.get("summary") or {}).get("stop_hit_rate") or 0.0),
            int(r.get("accepted_count") or 0),
        ),
        reverse=True,
    )
    lab_recommendations = _intraday_replay_lab_recommendations(lab_results)

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "read_only_historical_replay",
        "note": "No orders are placed and the hybrid proof ledger is not modified.",
        "symbols": syms,
        "lookback_days": lookback,
        "limit_per_symbol": limit,
        "scenario": cfg.get("name"),
        "config": cfg,
        "sessions_seen": session_list,
        "session_count": len(session_list),
        "validation_sessions": sorted(validation_sessions),
        "bars_by_symbol": {sym: len(bars_map.get(sym) or []) for sym in syms},
        "fetch_errors": fetch_errors,
        "raw_triggered_count": raw_triggered_count,
        "accepted_count": len(accepted_rows),
        "rejected_count": len(rejected_rows),
        "symbol_session_trade_counts": symbol_session_counts,
        "all": _intraday_replay_summary(accepted_rows),
        "train": _intraday_replay_summary(train_rows),
        "validation": _intraday_replay_summary(validation_rows),
        "quality_filter_result": filter_result,
        "scenario_lab": {
            "enabled": True,
            "results": lab_results,
            "recommendations": lab_recommendations,
        },
        "rejection_reason_counts": Counter(
            reason
            for row in rejected_rows
            for reason in (row.get("quality_gate_reasons") or [])
        ),
        "accepted_examples": accepted_rows[-50:],
        "rejected_examples": rejected_rows[-25:],
    }

def _hybrid_shadow_backfill_settlements(
    apply: bool = False,
    limit: int = 1000,
    recompute_terminal: bool = False,
) -> dict:
    _ensure_runtime_state_loaded()
    ledger_load = _hybrid_proof_load_ledger_compat()

    if not HYBRID_PROOF_SETTLEMENT_BACKFILL_ENABLE:
        return {
            "enabled": False,
            "apply": bool(apply),
            "checked": 0,
            "settled": 0,
            "classified_unverifiable": 0,
            "open_remaining": 0,
            "ledger_load": ledger_load,
            "reason": "HYBRID_PROOF_SETTLEMENT_BACKFILL_ENABLE=false",
        }

    rows = [r for r in HYBRID_PROOF_LEDGER if isinstance(r, dict)]

    target_statuses = {"open_shadow"}
    if recompute_terminal:
        target_statuses = {
            "open_shadow",
            "shadow_stop_hit",
            "shadow_target_hit",
            "shadow_eod_flat",
        }

    target_rows = [
        r for r in rows
        if str(r.get("status") or "").strip().lower() in target_statuses
        and str(r.get("source") or "").strip().lower() in {"intraday_shadow", ""}
    ][: max(1, min(int(limit or 1000), 5000))]

    symbols = sorted({
        str(r.get("symbol") or "").upper().strip()
        for r in target_rows
        if str(r.get("symbol") or "").strip()
    })

    bars_by_symbol = {}
    if symbols:
        try:
            bars_by_symbol = fetch_1m_bars_multi_guarded(
                symbols,
                lookback_days=max(1, HYBRID_PROOF_SETTLEMENT_LOOKBACK_DAYS),
            ) or {}
        except Exception as exc:
            logger.warning("hybrid shadow regular-session classification bars fetch failed: %s", exc)
            bars_by_symbol = {}

    now_local = now_ny()
    today_local = now_local.date()
    market_now_open = bool(in_market_hours())
    after_regular_close = now_local.hour > 15 or (now_local.hour == 15 and now_local.minute >= 55)

    checked = 0
    would_settle = 0
    settled = 0
    would_classify_unverifiable = 0
    classified_unverifiable = 0
    no_same_session_bars = 0
    session_incomplete = 0
    cross_session_bars_rejected = 0
    invalid_rows = 0
    stop_hit_count = 0
    target_hit_count = 0
    eod_flat_count = 0
    examples = []

    for row in target_rows:
        checked += 1

        original_status = str(row.get("status") or "").strip().lower()
        symbol = str(row.get("symbol") or "").upper().strip()
        row_session_date = _hybrid_shadow_row_session_date(row)
        entry_price = _safe_float(row.get("entry_price") or row.get("entry") or 0.0)
        stop_price = _safe_float(row.get("stop_price") or row.get("stop") or 0.0)
        target_price = _safe_float(row.get("target_price") or row.get("target") or 0.0)
        scan_ts = row.get("scan_ts_utc") or row.get("created_utc") or row.get("ts_utc")
        row_date = _hybrid_shadow_parse_session_date(row_session_date)

        if not symbol or not row_session_date or not row_date or entry_price <= 0:
            invalid_rows += 1
            would_classify_unverifiable += 1

            if apply:
                row["status"] = "shadow_unverifiable"
                row["unverifiable_reason"] = "invalid_shadow_row"
                row["settlement_patch"] = PATCH_VERSION
                row["settlement_same_session"] = False
                classified_unverifiable += 1

            examples.append({
                "symbol": symbol,
                "scan_ts_utc": scan_ts,
                "row_session_date": row_session_date,
                "original_status": original_status,
                "status": "shadow_unverifiable",
                "reason": "invalid_shadow_row",
                "same_session": False,
            })
            continue

        same_session_bars = _hybrid_shadow_regular_session_bars_for_row(
            row,
            list(bars_by_symbol.get(symbol) or []),
        )

        if not same_session_bars:
            no_same_session_bars += 1
            would_classify_unverifiable += 1

            if apply:
                row["status"] = "shadow_unverifiable"
                row["unverifiable_reason"] = "no_regular_session_bars"
                row["settlement_patch"] = PATCH_VERSION
                row["settlement_same_session"] = False
                classified_unverifiable += 1

            examples.append({
                "symbol": symbol,
                "scan_ts_utc": scan_ts,
                "row_session_date": row_session_date,
                "original_status": original_status,
                "status": "shadow_unverifiable",
                "reason": "no_regular_session_bars",
                "same_session": False,
            })
            continue

        chosen = None
        last_bar = None

        for bar in same_session_bars:
            last_bar = bar
            high = _safe_float(bar.get("high") or bar.get("h") or 0.0)
            low = _safe_float(bar.get("low") or bar.get("l") or 0.0)

            if stop_price > 0 and low > 0 and low <= stop_price:
                chosen = {
                    "status": "shadow_stop_hit",
                    "reason": "regular_session_backfill_stop_hit",
                    "price": stop_price,
                    "ts_utc": _hybrid_shadow_bar_ts_utc(bar),
                }
                break

            if target_price > 0 and high > 0 and high >= target_price:
                chosen = {
                    "status": "shadow_target_hit",
                    "reason": "regular_session_backfill_target_hit",
                    "price": target_price,
                    "ts_utc": _hybrid_shadow_bar_ts_utc(bar),
                }
                break

        if not chosen:
            historical_session = row_date < today_local
            completed_current_session = row_date == today_local and not market_now_open and after_regular_close

            if historical_session or completed_current_session:
                close_price = _safe_float(last_bar.get("close") or last_bar.get("c") or entry_price)
                chosen = {
                    "status": "shadow_eod_flat",
                    "reason": "regular_session_backfill_eod_flat",
                    "price": close_price,
                    "ts_utc": _hybrid_shadow_bar_ts_utc(last_bar),
                }
            else:
                session_incomplete += 1
                if apply:
                    row["settlement_backfill_reason"] = "regular_session_incomplete"
                    row["settlement_patch"] = PATCH_VERSION

                examples.append({
                    "symbol": symbol,
                    "scan_ts_utc": scan_ts,
                    "row_session_date": row_session_date,
                    "original_status": original_status,
                    "status": "open_shadow",
                    "reason": "regular_session_incomplete",
                    "same_session": True,
                })
                continue

        settled_ts_ny = None
        try:
            settled_ts_ny = _coerce_dt_ny(chosen.get("ts_utc"))
        except Exception:
            settled_ts_ny = None

        settled_session_date = settled_ts_ny.date().isoformat() if settled_ts_ny else ""
        if settled_session_date != row_session_date:
            cross_session_bars_rejected += 1
            would_classify_unverifiable += 1

            if apply:
                row["status"] = "shadow_unverifiable"
                row["unverifiable_reason"] = "rejected_cross_session_settlement"
                row["settlement_patch"] = PATCH_VERSION
                row["settlement_same_session"] = False
                classified_unverifiable += 1

            examples.append({
                "symbol": symbol,
                "scan_ts_utc": scan_ts,
                "row_session_date": row_session_date,
                "original_status": original_status,
                "status": "shadow_unverifiable",
                "reason": "rejected_cross_session_settlement",
                "settlement_session_date": settled_session_date,
                "same_session": False,
            })
            continue

        if not _hybrid_shadow_is_regular_session_bar({"ts_utc": chosen.get("ts_utc")}):
            cross_session_bars_rejected += 1
            would_classify_unverifiable += 1

            if apply:
                row["status"] = "shadow_unverifiable"
                row["unverifiable_reason"] = "rejected_non_regular_session_settlement"
                row["settlement_patch"] = PATCH_VERSION
                row["settlement_same_session"] = False
                classified_unverifiable += 1

            examples.append({
                "symbol": symbol,
                "scan_ts_utc": scan_ts,
                "row_session_date": row_session_date,
                "original_status": original_status,
                "status": "shadow_unverifiable",
                "reason": "rejected_non_regular_session_settlement",
                "settlement_session_date": settled_session_date,
                "same_session": False,
            })
            continue

        would_settle += 1

        if chosen["status"] == "shadow_stop_hit":
            stop_hit_count += 1
        elif chosen["status"] == "shadow_target_hit":
            target_hit_count += 1
        elif chosen["status"] == "shadow_eod_flat":
            eod_flat_count += 1

        if apply:
            _hybrid_shadow_settle_row(
                row,
                price=float(chosen["price"]),
                status=str(chosen["status"]),
                reason=str(chosen["reason"]),
                ts_utc=str(chosen["ts_utc"]),
            )
            row["settlement_session_date"] = row_session_date
            row["settlement_same_session"] = True
            row["settlement_regular_session"] = True
            row["settlement_patch"] = PATCH_VERSION
            settled += 1

        examples.append({
            "symbol": symbol,
            "scan_ts_utc": scan_ts,
            "row_session_date": row_session_date,
            "original_status": original_status,
            "status": chosen["status"],
            "reason": chosen["reason"],
            "price": round(float(chosen["price"]), 4),
            "ts_utc": chosen["ts_utc"],
            "settlement_session_date": settled_session_date,
            "same_session": True,
            "regular_session": True,
        })

    persist_result = {"ok": True, "method": "not_needed"}

    if apply and (settled or classified_unverifiable):
        persist_result = _hybrid_shadow_persist_ledger_after_backfill()

    post_rows = [r for r in HYBRID_PROOF_LEDGER if isinstance(r, dict)]
    status_breakdown = _hybrid_shadow_status_breakdown(post_rows)

    return {
        "enabled": True,
        "apply": bool(apply),
        "same_session_only": True,
        "regular_session_only": True,
        "classifies_unverifiable": True,
        "deterministic_classification": True,
        "recompute_terminal": bool(recompute_terminal),
        "checked": checked,
        "would_settle": would_settle,
        "settled": settled,
        "would_classify_unverifiable": would_classify_unverifiable,
        "classified_unverifiable": classified_unverifiable,
        "open_remaining": status_breakdown.get("open_shadow", 0),
        "no_same_session_bars": no_same_session_bars,
        "session_incomplete": session_incomplete,
        "cross_session_bars_rejected": cross_session_bars_rejected,
        "invalid_rows": invalid_rows,
        "stop_hit_count": stop_hit_count,
        "target_hit_count": target_hit_count,
        "eod_flat_count": eod_flat_count,
        "status_breakdown": status_breakdown,
        "symbols_checked": symbols,
        "lookback_days": HYBRID_PROOF_SETTLEMENT_LOOKBACK_DAYS,
        "require_full_session": HYBRID_PROOF_SETTLEMENT_REQUIRE_FULL_SESSION,
        "ledger_load": ledger_load,
        "persist_result": persist_result,
        "examples": examples[:25],
    }

def _hybrid_proof_record_from_signal(signal: dict, bars_today: list[dict], scan_ts_utc: str) -> dict | None:
    sym = str((signal or {}).get("symbol") or "").strip().upper()
    entry = _hybrid_proof_price_from_bars(bars_today)
    if not sym or entry <= 0:
        return None
    stop = round(entry * (1.0 - float(STOP_PCT)), 4)
    target = round(entry * (1.0 + float(TAKE_PCT)), 4)
    ts_ny = (bars_today[-1] or {}).get("ts_ny") if bars_today else now_ny()
    ny_date = ts_ny.date().isoformat() if hasattr(ts_ny, "date") else now_ny().date().isoformat()
    row = {
        "id": str(uuid.uuid4()),
        "status": "open_shadow",
        "ny_date": ny_date,
        "scan_ts_utc": scan_ts_utc,
        "symbol": sym,
        "signal": str(signal.get("signal") or "").upper(),
        "side": "buy",
        "entry_price": round(entry, 4),
        "stop_price": stop,
        "target_price": target,
        "risk_per_share": round(abs(entry - stop), 4),
        "score": round(_safe_float(signal.get("score") or 0.0), 4),
        "rank_score": round(_safe_float(signal.get("rank_score") or 0.0), 4),
        "would_pass_rank": bool(signal.get("would_pass_rank")),
        "source": "intraday_shadow",
        "live_submission": False,
    }
    return _hybrid_proof_update_entry(row, entry, scan_ts_utc)


def _record_intraday_shadow_proof(shadow: dict, bars_map: dict, scan_ts_utc: str) -> dict:
    existing = {_hybrid_proof_entry_key(r): r for r in HYBRID_PROOF_LEDGER if isinstance(r, dict)}
    updated = 0
    appended = 0
    for sym, bars in (bars_map or {}).items():
        price = _hybrid_proof_price_from_bars(_bars_for_today_session(bars or []))
        if price <= 0:
            continue
        for row in HYBRID_PROOF_LEDGER:
            if str((row or {}).get("symbol") or "").upper() == str(sym or "").upper() and str((row or {}).get("status") or "") == "open_shadow":
                _hybrid_proof_update_entry(row, price, scan_ts_utc)
                updated += 1
    bars_by_symbol = {str(k).upper(): _bars_for_today_session(v or []) for k, v in (bars_map or {}).items()}
    for signal in (shadow or {}).get("top_signals") or []:
        if not isinstance(signal, dict) or not bool(signal.get("would_pass_rank")):
            continue
        candidate = _hybrid_proof_record_from_signal(signal, bars_by_symbol.get(str(signal.get("symbol") or "").upper(), []), scan_ts_utc)
        if not candidate:
            continue
        key = _hybrid_proof_entry_key(candidate)
        if key in existing:
            continue
        HYBRID_PROOF_LEDGER.append(candidate)
        existing[key] = candidate
        appended += 1
    del HYBRID_PROOF_LEDGER[:-max(1, int(HYBRID_PROOF_LEDGER_LIMIT or 1))]
    if appended or updated:
        persist_hybrid_proof_ledger_state(reason="intraday_shadow_scan")
    return {"updated": updated, "appended": appended, "ledger_size": len(HYBRID_PROOF_LEDGER)}


def _intraday_live_position_symbols_from_snapshot() -> set[str]:
    """Best-effort set of currently open symbols that look intraday-managed.

    Swing mode can intentionally hold positions overnight.  Hybrid proof should
    not treat those swing holdings as failed intraday EOD flatten residuals.
    """
    intraday_tokens = ("INTRADAY", "VWAP", "PULLBACK")
    out: set[str] = set()
    try:
        snap = _safe_json_read(POSITION_SNAPSHOT_PATH) or {}
        positions = snap.get("positions") if isinstance(snap, dict) else []
        if not isinstance(positions, list):
            positions = []
    except Exception:
        positions = []
    for item in positions:
        if not isinstance(item, dict):
            continue
        sym = str(item.get("symbol") or "").strip().upper()
        signal = str(item.get("signal") or item.get("strategy") or item.get("strategy_name") or "").upper()
        if sym and any(tok in signal for tok in intraday_tokens):
            out.add(sym)
    try:
        for sym, plan in (TRADE_PLAN or {}).items():
            if not isinstance(plan, dict):
                continue
            if not (plan.get("active") or _plan_is_pending_entry(plan)):
                continue
            usym = str(sym or plan.get("symbol") or "").strip().upper()
            signal = str(plan.get("signal") or plan.get("strategy") or plan.get("strategy_name") or "").upper()
            if usym and any(tok in signal for tok in intraday_tokens):
                out.add(usym)
    except Exception:
        pass
    return out


def _hybrid_eod_readiness_view() -> dict:
    """Return sleeve-aware EOD readiness for hybrid proof gates."""
    raw = dict(LAST_EOD_FLATTEN_STATUS or {})
    raw_residuals = raw.get("residual_symbols")
    if isinstance(raw_residuals, (list, tuple, set)):
        residual_iter = raw_residuals
    elif raw_residuals:
        residual_iter = [raw_residuals]
    else:
        residual_iter = []
    residuals = {str(s or "").strip().upper() for s in residual_iter if str(s or "").strip()}
    intraday_live_symbols = _intraday_live_position_symbols_from_snapshot()
    if HYBRID_PROOF_EOD_GATE_MODE in {"off", "disabled", "none"}:
        ok = True
        mode_note = "eod_gate_disabled"
    elif HYBRID_PROOF_EOD_GATE_MODE in {"intraday_only", "sleeve", "sleeve_aware"}:
        unresolved = residuals.intersection(intraday_live_symbols) if intraday_live_symbols else set()
        ok = not unresolved
        mode_note = "swing_positions_ignored"
    else:
        unresolved = residuals
        ok = bool(raw.get("fully_flat", True)) and int(raw.get("residual_count") or 0) == 0
        mode_note = "all_positions_required_flat"
    return {
        "mode": HYBRID_PROOF_EOD_GATE_MODE,
        "ok": bool(ok),
        "raw_fully_flat": raw.get("fully_flat"),
        "raw_residual_count": int(raw.get("residual_count") or 0),
        "raw_residual_symbols": sorted(residuals),
        "intraday_live_symbols": sorted(intraday_live_symbols),
        "unresolved_intraday_residual_symbols": sorted(unresolved if 'unresolved' in locals() else set()),
        "note": mode_note,
    }

def _hybrid_eod_flat_session_key(row: dict) -> str:
    raw = (
        (row or {}).get("settled_utc")
        or (row or {}).get("last_observed_utc")
        or (row or {}).get("scan_ts_utc")
        or (row or {}).get("created_utc")
        or (row or {}).get("ts_utc")
    )
    if not raw:
        return ""
    try:
        return _coerce_dt_ny(raw).date().isoformat()
    except Exception:
        return ""


def _hybrid_eod_flat_session_count(rows: list[dict]) -> int:
    sessions = set()
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        status = str(row.get("status") or "").strip().lower()
        reason = str(row.get("settled_reason") or "").strip().lower()
        if status != "shadow_eod_flat" and "eod_flat" not in reason:
            continue
        session_key = _hybrid_eod_flat_session_key(row)
        if session_key:
            sessions.add(session_key)
    return len(sessions)


def _hybrid_eod_flat_gate_ok(eod_flat_sessions: int, rows: list[dict] | None = None) -> bool:
    required = max(0, int(HYBRID_PROOF_REQUIRE_EOD_FLAT_SESSIONS or 0))
    mode = str(HYBRID_PROOF_EOD_GATE_MODE or "").strip().lower()

    if mode in {"off", "disabled", "none", "false"}:
        return True

    if required <= 0:
        return True

    return int(eod_flat_sessions or 0) >= required

def _intraday_quality_scope_rows(rows: list[dict], config: dict | None = None) -> dict:
    cfg = dict(config or _intraday_quality_active_config())
    accepted = []
    rejected = []
    reason_counts = {}

    for row in rows or []:
        if not isinstance(row, dict):
            continue
        reasons = _intraday_quality_gate_reasons(
            row,
            ts_utc=row.get("scan_ts_utc") or row.get("created_utc") or row.get("ts_utc"),
            config=cfg,
        )
        copy_row = dict(row)
        copy_row["quality_scope_pass"] = not reasons
        copy_row["quality_scope_reasons"] = reasons
        copy_row["quality_scope_scenario"] = cfg.get("name")
        if reasons:
            rejected.append(copy_row)
            for reason in reasons:
                reason_counts[reason] = reason_counts.get(reason, 0) + 1
        else:
            accepted.append(copy_row)

    return {
        "scenario": cfg.get("name"),
        "config": cfg,
        "accepted": accepted,
        "rejected": rejected,
        "accepted_count": len(accepted),
        "rejected_count": len(rejected),
        "rejection_reason_counts": reason_counts,
    }


def _intraday_quality_scoped_live_promotion_truth(rows: list[dict], quality_filter_simulation: dict | None = None) -> dict:
    quality_filter_simulation = dict(quality_filter_simulation or {})
    active_result = dict(quality_filter_simulation.get("active") or {})
    scope = _intraday_quality_scope_rows(rows, config=_intraday_quality_active_config())

    accepted = [dict(r) for r in scope.get("accepted") or [] if isinstance(r, dict)]
    settled = [r for r in accepted if _hybrid_shadow_is_settled(r)]
    open_rows = [
        r for r in accepted
        if str(r.get("status") or "").strip().lower() == "open_shadow"
    ]
    raw_open_rows = [
        dict(r) for r in rows or []
        if isinstance(r, dict) and str(r.get("status") or "").strip().lower() == "open_shadow"
    ]
    irrelevant_open_rows = [
        r for r in raw_open_rows
        if not any(str(r.get("id") or "") and str(r.get("id") or "") == str(q.get("id") or "") for q in open_rows)
    ]

    settled_returns = [_safe_float(r.get("latest_return_pct") or 0.0) for r in settled]
    settled_r_values = [_safe_float(r.get("latest_r") or 0.0) for r in settled]
    settled_count = len(settled)
    open_count = len(open_rows)

    settled_avg_return = _mean(settled_returns)
    settled_avg_r = _mean(settled_r_values)
    settled_positive = sum(1 for v in settled_returns if v > 0)
    settled_positive_rate = (settled_positive / settled_count) if settled_count else 0.0
    settled_worst_r = min(settled_r_values) if settled_r_values else 0.0
    settled_best_r = max(settled_r_values) if settled_r_values else 0.0

    settled_sample_ready = settled_count >= HYBRID_PROOF_LIVE_PROMOTION_MIN_SETTLED
    settled_avg_r_ready = settled_avg_r >= HYBRID_PROOF_MIN_AVG_R
    settled_positive_ready = settled_positive_rate >= HYBRID_PROOF_LIVE_PROMOTION_MIN_POSITIVE_RATE
    settled_worst_r_ready = settled_worst_r >= HYBRID_PROOF_LIVE_PROMOTION_MAX_WORST_R
    open_shadow_ready = open_count <= HYBRID_PROOF_LIVE_PROMOTION_MAX_OPEN_SHADOW

    blockers = []
    if not settled_sample_ready:
        blockers.append("quality_scoped_settled_sample_below_min")
    if not settled_avg_r_ready:
        blockers.append("quality_scoped_settled_avg_r_below_min")
    if not settled_positive_ready:
        blockers.append("quality_scoped_settled_positive_rate_below_min")
    if not settled_worst_r_ready:
        blockers.append("quality_scoped_settled_worst_r_below_limit")
    if not open_shadow_ready:
        blockers.append("quality_scoped_open_shadow_count_above_limit")
    if INTRADAY_QUALITY_REQUIRE_FILTER_PROOF_READY and not bool(active_result.get("ready")):
        blockers.append("quality_filter_proof_not_ready")

    def compact_open(row: dict) -> dict:
        return {
            "id": row.get("id"),
            "symbol": row.get("symbol"),
            "status": row.get("status"),
            "ny_date": row.get("ny_date"),
            "scan_ts_utc": row.get("scan_ts_utc"),
            "signal": row.get("signal"),
            "latest_r": row.get("latest_r"),
            "rank_score": row.get("rank_score"),
            "quality_scope_pass": row.get("quality_scope_pass"),
            "quality_scope_reasons": row.get("quality_scope_reasons") or [],
            "quality_scope_scenario": row.get("quality_scope_scenario"),
        }

    return {
        "scope": "active_quality_gate",
        "scenario": scope.get("scenario"),
        "ready": not blockers,
        "blockers": blockers,
        "accepted_total_count": len(accepted),
        "rejected_total_count": len(scope.get("rejected") or []),
        "rejection_reason_counts": scope.get("rejection_reason_counts") or {},
        "settled_count": settled_count,
        "settled_avg_return_pct": round(settled_avg_return * 100.0, 4),
        "settled_avg_r": round(settled_avg_r, 4),
        "settled_positive_rate": round(settled_positive_rate, 4),
        "settled_worst_r": round(settled_worst_r, 4),
        "settled_best_r": round(settled_best_r, 4),
        "settled_sample_ready": settled_sample_ready,
        "settled_avg_r_ready": settled_avg_r_ready,
        "settled_positive_ready": settled_positive_ready,
        "settled_worst_r_ready": settled_worst_r_ready,
        "open_shadow_count": open_count,
        "open_shadow_ready": open_shadow_ready,
        "open_shadow_rows": [compact_open(r) for r in open_rows[-25:]],
        "raw_open_shadow_count": len(raw_open_rows),
        "irrelevant_open_shadow_count": len(irrelevant_open_rows),
        "irrelevant_open_shadow_rows": [compact_open(r) for r in irrelevant_open_rows[-25:]],
        "quality_attribution": _hybrid_shadow_quality_attribution(settled),
        "active_filter_result": _intraday_filter_compact_result(active_result),
    }

def _hybrid_proof_metrics(capacity_plan: Optional[dict] = None) -> dict:
    ledger_load = _hybrid_proof_load_ledger_compat()
    rows = [dict(r) for r in HYBRID_PROOF_LEDGER if isinstance(r, dict)]
    settled_rows = [r for r in rows if _hybrid_shadow_is_settled(r)]
    unverifiable_rows = [r for r in rows if _hybrid_shadow_is_unverifiable(r)]
    open_rows = [
        r for r in rows
        if str(r.get("status") or "").strip().lower() == "open_shadow"
    ]
    status_breakdown = _hybrid_shadow_status_breakdown(rows)
    quality_attribution = _hybrid_shadow_quality_attribution(rows)
    quality_filter_simulation = _intraday_filter_simulation(rows=rows, limit=1000)
    quality_scoped_truth = _intraday_quality_scoped_live_promotion_truth(
        rows,
        quality_filter_simulation=quality_filter_simulation,
    )

    all_returns = [_safe_float(r.get("latest_return_pct") or 0.0) for r in rows]
    all_r_values = [_safe_float(r.get("latest_r") or 0.0) for r in rows]

    settled_returns = [_safe_float(r.get("latest_return_pct") or 0.0) for r in settled_rows]
    settled_r_values = [_safe_float(r.get("latest_r") or 0.0) for r in settled_rows]

    sample_count = len(rows)
    settled_count = len(settled_rows)
    open_shadow_count = len(open_rows)

    avg_return = _mean(all_returns)
    avg_r = _mean(all_r_values)
    settled_avg_return = _mean(settled_returns)
    settled_avg_r = _mean(settled_r_values)

    settled_positive = sum(1 for v in settled_returns if v > 0)
    settled_positive_rate = (settled_positive / settled_count) if settled_count else 0.0
    settled_worst_r = min(settled_r_values) if settled_r_values else 0.0
    settled_best_r = max(settled_r_values) if settled_r_values else 0.0

    settled_sample_ready = settled_count >= HYBRID_PROOF_LIVE_PROMOTION_MIN_SETTLED
    settled_avg_r_ready = settled_avg_r >= HYBRID_PROOF_MIN_AVG_R
    settled_positive_ready = settled_positive_rate >= HYBRID_PROOF_LIVE_PROMOTION_MIN_POSITIVE_RATE
    settled_worst_r_ready = settled_worst_r >= HYBRID_PROOF_LIVE_PROMOTION_MAX_WORST_R
    open_shadow_ready = open_shadow_count <= HYBRID_PROOF_LIVE_PROMOTION_MAX_OPEN_SHADOW

    eod_flat_sessions = _hybrid_eod_flat_session_count(rows)
    eod_flat_sessions_ready = eod_flat_sessions >= HYBRID_PROOF_REQUIRE_EOD_FLAT_SESSIONS
    eod_flat_ok = _hybrid_eod_flat_gate_ok(
        eod_flat_sessions=eod_flat_sessions,
        rows=rows,
    )

    sleeves_ready = True
    sleeves_reason = "not_checked"
    if capacity_plan is not None:
        sleeves_ready = bool(capacity_plan.get("sleeves_configured"))
        sleeves_reason = str(capacity_plan.get("reason") or "")

    sample_ready = sample_count >= HYBRID_PROOF_MIN_SHADOW_TRADES
    avg_r_ready = avg_r >= HYBRID_PROOF_MIN_AVG_R

    proof_ready_for_paper = bool(
        sample_ready
        and avg_r_ready
        and sleeves_ready
        and (
            not HYBRID_PROOF_REQUIRE_EOD_FOR_PAPER
            or eod_flat_ok
        )
    )

    raw_live_promotion_blockers = []
    if not settled_sample_ready:
        raw_live_promotion_blockers.append("raw_settled_sample_below_min")
    if not settled_avg_r_ready:
        raw_live_promotion_blockers.append("raw_settled_avg_r_below_min")
    if not settled_positive_ready:
        raw_live_promotion_blockers.append("raw_settled_positive_rate_below_min")
    if not settled_worst_r_ready:
        raw_live_promotion_blockers.append("raw_settled_worst_r_below_limit")
    if not open_shadow_ready:
        raw_live_promotion_blockers.append("raw_open_shadow_count_above_limit")
    if INTRADAY_QUALITY_REQUIRE_FILTER_PROOF_READY and not bool(quality_filter_simulation.get("ready")):
        raw_live_promotion_blockers.append("raw_quality_filter_proof_not_ready")

    live_promotion_blockers = list(quality_scoped_truth.get("blockers") or [])
    if not eod_flat_ok:
        live_promotion_blockers.append("eod_flat_gate_not_ready")
    if not sleeves_ready:
        live_promotion_blockers.append("sleeves_not_configured")

    live_promotion_ready = not live_promotion_blockers

    return {
        "sample_count": sample_count,
        "ledger_load": ledger_load,
        "sample_ready": sample_ready,
        "min_shadow_trades": HYBRID_PROOF_MIN_SHADOW_TRADES,
        "avg_return_pct": round(avg_return * 100.0, 4),
        "avg_r": round(avg_r, 4),
        "avg_r_ready": avg_r_ready,
        "min_avg_r": HYBRID_PROOF_MIN_AVG_R,

        "settled_count": settled_count,
        "open_shadow_count": open_shadow_count,
        "unverifiable_count": len(unverifiable_rows),
        "status_breakdown": status_breakdown,
        "quality_attribution": quality_attribution,
        "quality_filter_simulation": quality_filter_simulation,
        "settled_avg_return_pct": round(settled_avg_return * 100.0, 4),
        "settled_avg_r": round(settled_avg_r, 4),
        "settled_positive_rate": round(settled_positive_rate, 4),
        "settled_worst_r": round(settled_worst_r, 4),
        "settled_best_r": round(settled_best_r, 4),
        "settled_sample_ready": settled_sample_ready,
        "settled_avg_r_ready": settled_avg_r_ready,
        "settled_positive_ready": settled_positive_ready,
        "settled_worst_r_ready": settled_worst_r_ready,
        "open_shadow_ready": open_shadow_ready,

        "live_promotion_scope": "quality_scoped_active_gate",
        "quality_scoped_live_promotion_truth": quality_scoped_truth,
        "quality_scoped_settled_count": quality_scoped_truth.get("settled_count"),
        "quality_scoped_open_shadow_count": quality_scoped_truth.get("open_shadow_count"),
        "quality_scoped_settled_avg_r": quality_scoped_truth.get("settled_avg_r"),
        "quality_scoped_settled_positive_rate": quality_scoped_truth.get("settled_positive_rate"),
        "quality_scoped_settled_worst_r": quality_scoped_truth.get("settled_worst_r"),
        "open_shadow_drain_audit": {
            "raw_open_shadow_count": quality_scoped_truth.get("raw_open_shadow_count"),
            "quality_scoped_open_shadow_count": quality_scoped_truth.get("open_shadow_count"),
            "irrelevant_open_shadow_count": quality_scoped_truth.get("irrelevant_open_shadow_count"),
            "blocking_open_shadow_rows": quality_scoped_truth.get("open_shadow_rows") or [],
            "irrelevant_open_shadow_rows": quality_scoped_truth.get("irrelevant_open_shadow_rows") or [],
            "recommended_action": "wait_for_quality_scoped_open_shadows_to_settle" if int(quality_scoped_truth.get("open_shadow_count") or 0) else "quality_scoped_open_shadow_clear",
        },
        "raw_live_promotion_truth": {
            "ready": not raw_live_promotion_blockers,
            "blockers": raw_live_promotion_blockers,
            "settled_count": settled_count,
            "open_shadow_count": open_shadow_count,
            "settled_avg_r": round(settled_avg_r, 4),
            "settled_positive_rate": round(settled_positive_rate, 4),
            "settled_worst_r": round(settled_worst_r, 4),
        },

        "live_promotion_ready": live_promotion_ready,
        "live_promotion_blockers": live_promotion_blockers,
        "live_promotion_thresholds": {
            "scope": "quality_scoped_active_gate",
            "min_settled": HYBRID_PROOF_LIVE_PROMOTION_MIN_SETTLED,
            "min_avg_r": HYBRID_PROOF_MIN_AVG_R,
            "min_positive_rate": HYBRID_PROOF_LIVE_PROMOTION_MIN_POSITIVE_RATE,
            "max_worst_r": HYBRID_PROOF_LIVE_PROMOTION_MAX_WORST_R,
            "max_open_shadow": HYBRID_PROOF_LIVE_PROMOTION_MAX_OPEN_SHADOW,
        },

        "eod_flat_sessions": eod_flat_sessions,
        "eod_flat_sessions_ready": eod_flat_sessions_ready,
        "eod_flat_required_sessions": HYBRID_PROOF_REQUIRE_EOD_FLAT_SESSIONS,
        "eod_flat_ok": eod_flat_ok,
        "eod_gate_mode": HYBRID_PROOF_EOD_GATE_MODE,
        "require_eod_for_paper": HYBRID_PROOF_REQUIRE_EOD_FOR_PAPER,

        "sleeves_ready": sleeves_ready,
        "sleeves_reason": sleeves_reason,
        "proof_ready_for_paper": proof_ready_for_paper,
        "proof_ready_for_live": live_promotion_ready,
    }

def _intraday_live_preflight(proof_metrics: dict | None = None) -> dict:
    metrics = dict(proof_metrics or _hybrid_proof_metrics())
    loss_halt = _p229_realized_closed_trade_loss_halt()
    raw_open_shadow_count = int(metrics.get("open_shadow_count") or 0)
    quality_open_shadow_count = int(metrics.get("quality_scoped_open_shadow_count") or 0)
    open_shadow_count = quality_open_shadow_count
    checks = [
        {"name": "live_trading_enabled", "ok": bool(LIVE_TRADING_ENABLED), "value": bool(LIVE_TRADING_ENABLED)},
        {"name": "market_tradable_now", "ok": bool(in_market_hours()), "value": bool(in_market_hours())},
        {"name": "strategy_mode_intraday", "ok": str(STRATEGY_MODE or "").strip().lower() == "intraday", "value": STRATEGY_MODE},
        {"name": "hybrid_mode_live", "ok": str(HYBRID_MODE or "").strip().lower() == "live", "value": HYBRID_MODE},
        {"name": "intraday_live_enabled", "ok": bool(INTRADAY_LIVE_ENABLED), "value": bool(INTRADAY_LIVE_ENABLED)},
        {"name": "scanner_live_allowed", "ok": bool(SCANNER_ALLOW_LIVE) and not bool(DRY_RUN), "value": {"scanner_allow_live": bool(SCANNER_ALLOW_LIVE), "dry_run": bool(DRY_RUN)}},
        {"name": "realized_loss_halt_clear", "ok": not bool(loss_halt.get("active")), "value": loss_halt},
        {
            "name": "live_promotion_truth_ready",
            "ok": bool(metrics.get("live_promotion_ready")),
            "value": {
                "scope": metrics.get("live_promotion_scope"),
                "ready": bool(metrics.get("live_promotion_ready")),
                "blockers": metrics.get("live_promotion_blockers") or [],
                "quality_scoped_settled_count": metrics.get("quality_scoped_settled_count"),
                "quality_scoped_open_shadow_count": metrics.get("quality_scoped_open_shadow_count"),
                "quality_scoped_settled_avg_r": metrics.get("quality_scoped_settled_avg_r"),
                "quality_scoped_settled_positive_rate": metrics.get("quality_scoped_settled_positive_rate"),
                "quality_scoped_settled_worst_r": metrics.get("quality_scoped_settled_worst_r"),
                "raw_live_promotion_truth": metrics.get("raw_live_promotion_truth") or {},
            },
        },
    ]
    if INTRADAY_LIVE_PREFLIGHT_REQUIRE_SHADOW_SETTLED:
        checks.append({
            "name": "shadow_exits_settled",
            "ok": open_shadow_count <= int(INTRADAY_LIVE_PREFLIGHT_MAX_OPEN_SHADOW),
            "value": {
                "scope": "quality_scoped_active_gate",
                "quality_scoped_open_shadow_count": quality_open_shadow_count,
                "raw_open_shadow_count": raw_open_shadow_count,
                "max_open_shadow": int(INTRADAY_LIVE_PREFLIGHT_MAX_OPEN_SHADOW),
                "open_shadow_drain_audit": metrics.get("open_shadow_drain_audit") or {},
            },
        })
    blockers = [str(c.get("name")) for c in checks if not c.get("ok")]
    return {
        "ok": not blockers,
        "allowed": not blockers,
        "blockers": blockers,
        "checks": checks,
        "proof_ready_for_live": bool(metrics.get("proof_ready_for_live")),
        "live_promotion_ready": bool(metrics.get("live_promotion_ready")),
        "live_promotion_scope": metrics.get("live_promotion_scope"),
        "live_promotion_blockers": metrics.get("live_promotion_blockers") or [],
        "open_shadow_count": open_shadow_count,
        "quality_scoped_open_shadow_count": quality_open_shadow_count,
        "raw_open_shadow_count": raw_open_shadow_count,
        "open_shadow_drain_audit": metrics.get("open_shadow_drain_audit") or {},
        "realized_closed_trade_loss_halt_active": bool(loss_halt.get("active")),
    }

def _hybrid_paper_pilot_plan(would_trade: list[dict], metrics: dict, capacity_plan: dict) -> dict:
    """Plan hypothetical intraday paper entries without changing broker/plans."""
    paper_enabled = bool(capacity_plan.get("intraday_paper_enabled"))
    proof_ready = bool(metrics.get("proof_ready_for_paper"))
    if INTRADAY_PAPER_REQUIRE_PROOF_READY and not proof_ready:
        eligible = False
        reason = "proof_not_ready_for_paper"
    elif not paper_enabled:
        eligible = False
        reason = "paper_pilot_disabled"
    else:
        eligible = True
        reason = "paper_pilot_ready"
    max_positions = max(0, int(capacity_plan.get("intraday_paper_max_positions") or 0))
    selected = [dict(r) for r in (would_trade or [])[:max_positions]] if eligible else []
    for row in selected:
        row["paper_only"] = True
        row["live_submission"] = False
    return {
        "enabled": paper_enabled,
        "eligible": bool(eligible),
        "reason": reason,
        "requires_proof_ready": bool(INTRADAY_PAPER_REQUIRE_PROOF_READY),
        "max_positions": max_positions,
        "planned_count": len(selected),
        "planned_entries": selected,
        "live_submission": False,
    }


def _intraday_shadow_config() -> dict:
    return {
        "enabled": bool(INTRADAY_SHADOW_EVALUATION_ENABLE),
        "force_enabled_paths": bool(INTRADAY_SHADOW_FORCE_ENABLED_PATHS),
        "max_symbols": int(INTRADAY_SHADOW_MAX_SYMBOLS),
        "reclaim_enabled": bool(INTRADAY_VWAP_RECLAIM_ENABLE),
        "continuation_enabled": bool(INTRADAY_VWAP_CONTINUATION_ENABLE),
        "reclaim_score_min": float(INTRADAY_VWAP_RECLAIM_SCORE_MIN),
        "continuation_score_min": float(INTRADAY_VWAP_CONTINUATION_SCORE_MIN),
        "reclaim_min_rank_score": float(INTRADAY_VWAP_RECLAIM_MIN_RANK_SCORE),
        "continuation_min_rank_score": float(INTRADAY_VWAP_CONTINUATION_MIN_RANK_SCORE),
        "quality_gate": _intraday_quality_gate_config(),
    }


def _evaluate_intraday_shadow_symbol(symbol: str, bars_today: list[dict]) -> dict:
    """Evaluate intraday paths without creating plans or submitting orders."""
    sym = str(symbol or "").strip().upper()
    force = bool(INTRADAY_SHADOW_FORCE_ENABLED_PATHS)
    reclaim_sig, reclaim_diag = eval_intraday_vwap_reclaim_signal_with_diag(bars_today, force_enable=force)
    continuation_sig, continuation_diag = eval_intraday_vwap_continuation_signal_with_diag(bars_today, force_enable=force)
    candidates: list[dict] = []
    if reclaim_sig == "BUY":
        rank, rank_meta = compute_signal_rank("INTRADAY_VWAP_RECLAIM", reclaim_diag)
        candidates.append({
            "symbol": sym,
            "signal": "INTRADAY_VWAP_RECLAIM",
            "side": "buy",
            "score": float(reclaim_diag.get("score", 0.0) or 0.0),
            "rank_score": float(rank),
            "rank_meta": rank_meta,
            "would_pass_rank": float(rank) >= float(INTRADAY_VWAP_RECLAIM_MIN_RANK_SCORE),
        })
    if continuation_sig == "BUY":
        rank, rank_meta = compute_signal_rank("INTRADAY_VWAP_CONTINUATION", continuation_diag)
        candidates.append({
            "symbol": sym,
            "signal": "INTRADAY_VWAP_CONTINUATION",
            "side": "buy",
            "score": float(continuation_diag.get("score", 0.0) or 0.0),
            "rank_score": float(rank),
            "rank_meta": rank_meta,
            "would_pass_rank": float(rank) >= float(INTRADAY_VWAP_CONTINUATION_MIN_RANK_SCORE),
        })
    candidates.sort(key=lambda r: float(r.get("rank_score") or 0.0), reverse=True)
    return {
        "symbol": sym,
        "bars_1m": len(bars_today or []),
        "diagnostics": {
            "intraday_vwap_reclaim": reclaim_diag,
            "intraday_vwap_continuation": continuation_diag,
        },
        "signals": candidates,
        "top_signal": candidates[0] if candidates else None,
    }


def _run_intraday_shadow_scan(symbols: list[str], *, lookback_days: int | None = None) -> dict:
    """Run intraday signal evaluation in shadow mode while another strategy is live."""
    cfg = _intraday_shadow_config()
    if not cfg["enabled"]:
        return {"enabled": False, "status": "disabled", "config": cfg, "signals": 0, "would_trade": 0, "results": []}
    if ONLY_MARKET_HOURS and not in_market_hours():
        return {"enabled": True, "status": "skipped_outside_market_hours", "config": cfg, "signals": 0, "would_trade": 0, "results": []}
    max_symbols = max(1, int(cfg["max_symbols"] or 1))
    syms = _dedupe_keep_order([str(s or "").strip().upper() for s in (symbols or []) if str(s or "").strip()])[:max_symbols]
    if not syms:
        return {"enabled": True, "status": "no_symbols", "config": cfg, "signals": 0, "would_trade": 0, "results": []}
    bars_map = fetch_1m_bars_multi_guarded(syms, lookback_days=int(lookback_days or SCANNER_LOOKBACK_DAYS))
    results = []
    signals = []
    for sym in syms:
        bars_today = _bars_for_today_session(bars_map.get(sym) or [])
        row = _evaluate_intraday_shadow_symbol(sym, bars_today)
        results.append(row)
        signals.extend([dict(sig) for sig in row.get("signals") or [] if isinstance(sig, dict)])
    signals.sort(key=lambda r: float(r.get("rank_score") or 0.0), reverse=True)
    raw_would_trade = [s for s in signals if bool(s.get("would_pass_rank"))]
    scan_ts_utc = datetime.now(timezone.utc).isoformat()
    quality_filter = _intraday_quality_filter_candidates(raw_would_trade, ts_utc=scan_ts_utc)
    would_trade = list(quality_filter.get("accepted") or [])
    capacity_plan = _hybrid_capacity_plan()
    proof_metrics = _hybrid_proof_metrics(capacity_plan=capacity_plan)
    paper_pilot = _hybrid_paper_pilot_plan(would_trade, proof_metrics, capacity_plan)
    if bool(INTRADAY_QUALITY_GATE_ENABLED) and raw_would_trade and not would_trade:
        paper_pilot = dict(paper_pilot)
        paper_pilot["eligible"] = False
        paper_pilot["reason"] = "quality_gate_empty_after_filter"
        paper_pilot["planned_count"] = 0
        paper_pilot["planned_entries"] = []
        paper_pilot["quality_gate_non_empty_guard"] = {
            "raw_would_trade": len(raw_would_trade),
            "accepted_count": 0,
            "scenario": quality_filter.get("scenario"),
            "recommended_action": "review_diagnostics_intraday_filter_simulation",
        }
    shadow_payload = {
        "enabled": True,
        "status": "completed",
        "strategy_mode": STRATEGY_MODE,
        "live_submission": False,
        "hybrid_mode": HYBRID_MODE,
        "symbols_scanned": len(syms),
        "signals": len(signals),
        "would_trade": len(would_trade),
        "raw_would_trade": len(raw_would_trade),
        "quality_gate": quality_filter,
        "config": cfg,
        "top_signals": signals[:8],
        "top_quality_signals": would_trade[:8],
        "results": results[:max_symbols],
        "hybrid_capacity_plan": capacity_plan,
        "paper_pilot": paper_pilot,
    }
    shadow_payload["proof_ledger_update"] = _record_intraday_shadow_proof(shadow_payload, bars_map, scan_ts_utc)
    shadow_payload["proof_metrics"] = _hybrid_proof_metrics(capacity_plan=capacity_plan)
    shadow_payload["paper_pilot"] = _hybrid_paper_pilot_plan(would_trade, shadow_payload["proof_metrics"], capacity_plan)
    if bool(INTRADAY_QUALITY_GATE_ENABLED) and raw_would_trade and not would_trade:
        shadow_payload["paper_pilot"] = dict(shadow_payload["paper_pilot"])
        shadow_payload["paper_pilot"]["eligible"] = False
        shadow_payload["paper_pilot"]["reason"] = "quality_gate_empty_after_filter"
        shadow_payload["paper_pilot"]["planned_count"] = 0
        shadow_payload["paper_pilot"]["planned_entries"] = []
        shadow_payload["paper_pilot"]["quality_gate_non_empty_guard"] = {
            "raw_would_trade": len(raw_would_trade),
            "accepted_count": 0,
            "scenario": quality_filter.get("scenario"),
            "recommended_action": "review_diagnostics_intraday_filter_simulation",
        }
    return shadow_payload
    
    
def eval_power_hour_signal(bars_today: list[dict]) -> tuple[str, str] | None:
    if not bars_today:
        return None
    ts_ny = bars_today[-1].get("ts_ny")
    if ts_ny is None:
        return None

    pwr_bars = _bars_for_today_session(bars_today, ts_ny, PWR_SESSION)
    if not pwr_bars:
        return None

    first_pwr_ts = pwr_bars[0]["ts_ny"]
    pre_bars = [b for b in bars_today if b.get("ts_ny") and b["ts_ny"] < first_pwr_ts]
    if len(pre_bars) < 20:
        return None

    use_hl = bool(PWR_BREAKOUT_USE_HIGHLOW)
    pre_high = max(float(b.get("high", b.get("close"))) for b in pre_bars) if use_hl else max(float(b.get("close")) for b in pre_bars)
    pre_low = min(float(b.get("low", b.get("close"))) for b in pre_bars) if use_hl else min(float(b.get("close")) for b in pre_bars)

    price = float(bars_today[-1].get("close"))
    buf = float(PWR_BREAKOUT_BUFFER_PCT)

    closes = [float(b.get("close")) for b in pre_bars[-200:]] + [price]
    ema_fast = ema_series(closes, 20)
    ema_slow = ema_series(closes, 50)
    if ema_fast is None or ema_slow is None:
        return None
    if price < ema_fast[-1] or ema_fast[-1] < ema_slow[-1]:
        return None

    if price >= pre_high * (1.0 + buf):
        return ("power_hour_breakout_up", "BUY")

    return None

def _strategy_reason_disabled() -> str:
    return "strategy_disabled"


def _no_signal_from_midbox(diag: dict) -> str:
    if not diag.get("enabled"):
        return _strategy_reason_disabled()
    if diag.get("eligible") is False:
        return diag.get("reason") or "not_eligible"
    if not diag.get("ema200_slope_up", True) and not diag.get("ema200_slope_down", True):
        return "ema200_not_ready_or_flat"
    if not diag.get("crossed_up") and not diag.get("crossed_down"):
        return "no_breakout_cross"
    if diag.get("crossed_up") and not diag.get("ema200_slope_up", True):
        return "ema200_slope_not_up"
    if diag.get("crossed_down") and not diag.get("ema200_slope_down", True):
        return "ema200_slope_not_down"
    if diag.get("crossed_up") and not diag.get("long_signal", False):
        return "long_filters_failed"
    if diag.get("crossed_down") and not diag.get("short_signal", False):
        return "short_filters_failed"
    return "no_signal"

def _no_signal_from_pwr(diag: dict) -> str:
    if not diag.get("enabled"):
        return _strategy_reason_disabled()
    if diag.get("eligible") is False:
        return diag.get("reason") or "not_eligible"
    if not diag.get("ema200_slope_up", True):
        return "ema200_slope_not_up"
    if not diag.get("breakout", False):
        return "no_breakout"
    if not diag.get("volume_ok", False):
        return "volume_not_ok"
    if not (diag.get("last_close", 0) > (diag.get("vwap_5m", float("inf")))):
        return "below_vwap"
    if not (diag.get("ema20_5m") is None or (diag.get("last_close", 0) > diag.get("ema20_5m", float("inf")))):
        return "below_ema20_5m"
    return "no_signal"

def _no_signal_from_vwap_pb(diag: dict) -> str:
    if not diag.get("enabled"):
        return _strategy_reason_disabled()
    if diag.get("eligible") is False:
        return diag.get("reason") or "not_eligible"
    if not diag.get("uptrend", False):
        return "trend_fail"
    if not diag.get("slope_ok", False):
        return "ema_slope_fail"
    if not diag.get("extension_ok", False):
        return "too_extended_from_vwap"
    if not diag.get("touched", False):
        return "did_not_touch_vwap_band"
    if not diag.get("reclaimed", False):
        return "did_not_reclaim_vwap"
    return "no_signal"


def _no_signal_from_intraday_vwap_reclaim(diag: dict) -> str:
    if not diag.get("enabled"):
        return _strategy_reason_disabled()
    if diag.get("eligible") is False:
        return diag.get("reason") or "not_eligible"
    return diag.get("reason") or "no_reclaim"


def _no_signal_from_intraday_vwap_continuation(diag: dict) -> str:
    if not diag.get("enabled"):
        return _strategy_reason_disabled()
    if diag.get("eligible") is False:
        return diag.get("reason") or "not_eligible"
    return diag.get("reason") or "no_continuation"
    
    
def _no_signal_from_hf5(diag: dict) -> str:
    # Higher-frequency ORB/VWAP/EMA strategy
    if not diag.get("enabled"):
        return "disabled"
    if diag.get("eligible") is False:
        return diag.get("reason") or "ineligible"
    # When there's no signal, we expect a structured reason
    return diag.get("reason") or "no_signal"


def _derive_no_signal_details(diag: dict) -> tuple[str, dict]:
    """Return (primary_reason, details_by_strategy) for hold/no_signal cases.

    Primary selection rules:
    1) If any enabled strategy is blocked by market-hours gating, report `outside_market_hours`.
    2) Else if all enabled strategies are blocked by session gating, report `session_closed`.
    3) Else fall back to the first enabled strategy's specific reason.
    """
    details: dict = {}
    mb = diag.get("midbox") or {}
    pw = diag.get("pwr") or {}
    hf = diag.get("hf5") or {}
    vp = diag.get("vwap_pullback") or {}
    intraday_reclaim = diag.get("intraday_vwap_reclaim") or {}
    intraday_continuation = diag.get("intraday_vwap_continuation") or {}

    mb_reason = _no_signal_from_midbox(mb)
    pw_reason = _no_signal_from_pwr(pw)
    vp_reason = _no_signal_from_vwap_pb(vp)
    intraday_reclaim_reason = _no_signal_from_intraday_vwap_reclaim(intraday_reclaim)
    intraday_continuation_reason = _no_signal_from_intraday_vwap_continuation(intraday_continuation)
    hf_reason = "no_signal"

    details["midbox"] = {"enabled": bool(mb.get("enabled")), "eligible": mb.get("eligible"), "reason": mb_reason}
    details["pwr"] = {"enabled": bool(pw.get("enabled")), "eligible": pw.get("eligible"), "reason": pw_reason}
    details["vwap_pullback"] = {"enabled": bool(vp.get("enabled")), "eligible": vp.get("eligible"), "reason": vp_reason}
    details["intraday_vwap_reclaim"] = {"enabled": bool(intraday_reclaim.get("enabled")), "eligible": intraday_reclaim.get("eligible"), "reason": intraday_reclaim_reason}
    details["intraday_vwap_continuation"] = {"enabled": bool(intraday_continuation.get("enabled")), "eligible": intraday_continuation.get("eligible"), "reason": intraday_continuation_reason}
    details["hf5"] = {"enabled": bool(hf.get("enabled")), "eligible": hf.get("eligible"), "reason": hf_reason}

    strategy_order = ("midbox", "pwr", "vwap_pullback", "intraday_vwap_reclaim", "intraday_vwap_continuation")
    if str(STRATEGY_MODE or "").strip().lower() == "intraday" and SCANNER_PRIMARY_STRATEGY in ("vwap", "vwap_pullback", "vwap_pullback_only"):
        strategy_order = ("intraday_vwap_reclaim", "intraday_vwap_continuation", "vwap_pullback", "midbox", "pwr")
    enabled = [s for s in strategy_order if details[s]["enabled"]]
    if not enabled:
        return "no_strategy_enabled", details

    # Hard market-hours gating takes precedence
    for s in enabled:
        if details[s]["reason"] in ("outside_market_hours", "outside_regular_session"):
            return "outside_market_hours", details

    # If every enabled strategy is session-gated, expose that clearly
    if all(details[s]["reason"] in ("session_closed", "outside_market_hours", "outside_regular_session") for s in enabled):
        if any(details[s]["reason"] == "session_closed" for s in enabled):
            return "session_closed", details
        return "outside_market_hours", details

    # Otherwise: first enabled strategy's reason
    return details[enabled[0]]["reason"], details

def scanner_idempotency_key(symbol: str, signal: str, bar_ts_ny: datetime) -> str:
    # One-per-symbol-per-signal-per-minute bucket (Phase 1C)
    bucket = bar_ts_ny.replace(second=0, microsecond=0).isoformat()
    raw = f"scan-{symbol}-{signal}-{bucket}"
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:24]
