def _p275_executed_entry_eligibility_audit(limit: int = 25) -> dict:
    snap = dict(read_positions_snapshot() or {})
    plans = dict(snap.get("active_plans") or {})
    if not plans:
        plans = {
            str(sym or "").upper(): dict(plan or {})
            for sym, plan in dict(TRADE_PLAN or {}).items()
            if isinstance(plan, dict) and bool(plan.get("active"))
        }

    rows = []
    suspicious = []
    unresolved = []

    for sym, plan in sorted(plans.items()):
        row = dict(plan or {})
        strategy = str(row.get("strategy_name") or row.get("signal") or "").strip().lower()
        if strategy != BREAKOUT_STRATEGY_NAME:
            continue

        thesis = dict(row.get("thesis") or {}) if isinstance(row.get("thesis"), dict) else {}
        existing = dict(thesis.get("entry_quality_snapshot") or {}) if isinstance(thesis.get("entry_quality_snapshot"), dict) else {}
        existing_reasons = [str(r) for r in existing.get("rejection_reasons_at_entry") or []]

        match_payload = _p276_entry_quality_match_for_plan(sym, row)
        recovered = dict(match_payload.get("recovered_snapshot") or {})
        recovered_reasons = [str(r) for r in recovered.get("rejection_reasons_at_entry") or []]
        match = dict(match_payload.get("match") or {})

        timestamp_match_available = bool(match.get("timestamp_eligible_count"))
        conflict = bool(
            timestamp_match_available
            and "defensive_daily_breakout_rollback" in recovered_reasons
            and "defensive_daily_breakout_rollback" not in existing_reasons
            and not bool(recovered.get("defensive_breakout_tier_approved"))
        )

        item = {
            "symbol": str(sym or "").upper(),
            "strategy": strategy,
            "opened_at": row.get("opened_at"),
            "source": row.get("source"),
            "entry_type": row.get("entry_type"),
            "has_existing_snapshot": bool(_p249_snapshot_has_useful_values(existing)),
            "timestamp_match_available": timestamp_match_available,
            "timestamp_match_count": int(match.get("timestamp_eligible_count") or 0),
            "all_match_count": int(match.get("all_match_count") or 0),
            "missing_ts_count": int(match.get("missing_ts_count") or 0),
            "excluded_after_entry_count": int(match.get("excluded_after_entry_count") or 0),
            "excluded_too_old_count": int(match.get("excluded_too_old_count") or 0),
            "match_window": dict(match.get("window") or {}),
            "existing_rejection_reasons": existing_reasons,
            "matched_candidate_rejection_reasons": recovered_reasons,
            "matched_candidate_ts_utc": recovered.get("candidate_context_ts_utc"),
            "entry_match_delta_sec": recovered.get("entry_match_delta_sec"),
            "defensive_breakout_tier_approved": bool(recovered.get("defensive_breakout_tier_approved")),
            "candidate_match_conflicts_with_live_entry": conflict,
            "recommended_action": (
                "inspect_timestamp_matched_entry_attribution"
                if conflict
                else ("no_timestamp_matched_candidate" if not timestamp_match_available else "none")
            ),
        }
        rows.append(item)

        if conflict:
            suspicious.append(item)
        elif not timestamp_match_available:
            unresolved.append(item)

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "timestamp_aware_executed_entry_eligibility_audit",
        "active_breakout_plan_count": len(rows),
        "conflict_count": len(suspicious),
        "conflict_symbols": [r.get("symbol") for r in suspicious],
        "unresolved_count": len(unresolved),
        "unresolved_symbols": [r.get("symbol") for r in unresolved],
        "rows": rows[: max(1, min(int(limit or 25), 100))],
        "recommended_action": (
            "inspect_timestamp_matched_entry_attribution"
            if suspicious
            else ("collect_more_timestamped_candidate_history" if unresolved else "none")
        ),
    }

def _p276_latest_swing_candidate_rows(limit: int = 100) -> list[dict]:
    payloads: list[tuple[dict, str | None, str]] = []

    try:
        if LAST_SWING_CANDIDATES:
            payloads.append(({"items": list(LAST_SWING_CANDIDATES or [])}, None, "last_swing_candidates"))
    except Exception:
        pass

    try:
        if CANDIDATE_HISTORY:
            for payload in list(CANDIDATE_HISTORY or [])[-max(1, int(SWING_DEFENSIVE_TIER_EVIDENCE_HISTORY_SCANS or 5)):]:
                if isinstance(payload, dict):
                    payloads.append((dict(payload), payload.get("ts_utc") or payload.get("scan_ts_utc"), "candidate_history"))
    except Exception:
        pass

    rows = []
    seen = set()
    for payload, fallback_ts, source in reversed(payloads):
        for row in _p247_candidate_like_rows_from_payload(payload, limit=limit):
            strategy = str(row.get("strategy") or row.get("strategy_name") or row.get("signal") or "").strip().lower()
            signal = str(row.get("signal") or "").strip().lower()
            if strategy != BREAKOUT_STRATEGY_NAME and signal != "daily_breakout":
                continue

            sym = str(row.get("symbol") or "").strip().upper()
            row_dt = _p276_candidate_row_ts(row, fallback_ts=fallback_ts)
            key = (
                sym,
                row_dt.isoformat() if row_dt else "",
                str(row.get("rank_score") or ""),
                str(row.get("regime_mode") or ""),
            )
            if key in seen:
                continue
            seen.add(key)

            copy = dict(row)
            copy["candidate_context_source"] = source
            copy["candidate_context_ts_utc"] = row_dt.isoformat() if row_dt else None
            rows.append(copy)

    rows.sort(
        key=lambda r: (
            str(r.get("candidate_context_ts_utc") or ""),
            _safe_float(r.get("rank_score"), 0.0),
        ),
        reverse=True,
    )
    return rows[:max(1, int(limit or 100))]


def _p276_defensive_tier_evidence_report(limit: int = 50) -> dict:
    rows = _p276_latest_swing_candidate_rows(limit=max(50, int(limit or 50)))
    evidence = []

    for row in rows:
        regime_mode = str(row.get("regime_mode") or "").strip().lower()
        rollback = _p264_defensive_daily_breakout_rollback_snapshot(regime_mode, candidate=row)
        tier = dict(rollback.get("tier_gate") or {})
        rejection_reasons = [str(r) for r in row.get("rejection_reasons") or []]

        item = {
            "symbol": str(row.get("symbol") or "").strip().upper(),
            "candidate_ts_utc": row.get("candidate_context_ts_utc") or row.get("scan_ts_utc"),
            "regime_mode": regime_mode or "unknown",
            "rank_score": row.get("rank_score"),
            "min_rank_score": row.get("min_rank_score"),
            "close_to_high_pct": row.get("close_to_high_pct"),
            "breakout_distance_pct": row.get("breakout_distance_pct"),
            "risk_per_share_pct": row.get("risk_per_share_pct"),
            "eligible": bool(row.get("eligible")),
            "rejection_reasons": rejection_reasons,
            "rollback_broad_blocked": bool(rollback.get("broad_blocked")),
            "rollback_blocked": bool(rollback.get("blocked")),
            "tier_gate_enabled": bool(rollback.get("tier_gate_enabled")),
            "tier_gate_passed": bool(rollback.get("tier_gate_passed")),
            "tier_gate_blockers": list(tier.get("blockers") or []),
            "tier_gate_checks": list(tier.get("checks") or []),
            "would_be_allowed_by_defensive_tier": bool(
                rollback.get("broad_blocked")
                and rollback.get("tier_gate_passed")
            ),
            "would_be_blocked_by_defensive_tier": bool(
                rollback.get("broad_blocked")
                and rollback.get("blocked")
            ),
        }
        evidence.append(item)

    defensive_rows = [r for r in evidence if str(r.get("regime_mode") or "") == "defensive"]
    tier_allowed = [r for r in defensive_rows if r.get("would_be_allowed_by_defensive_tier")]
    tier_blocked = [r for r in defensive_rows if r.get("would_be_blocked_by_defensive_tier")]

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "defensive_breakout_tier_evidence_report",
        "read_only": True,
        "total_rows": len(evidence),
        "defensive_rows": len(defensive_rows),
        "tier_allowed_count": len(tier_allowed),
        "tier_allowed_symbols": [r.get("symbol") for r in tier_allowed],
        "tier_blocked_count": len(tier_blocked),
        "tier_blocked_symbols": [r.get("symbol") for r in tier_blocked[:25]],
        "current_env": {
            "SWING_REGIME_MODE_ALLOW_DEFENSIVE_ENTRIES": bool(SWING_REGIME_MODE_ALLOW_DEFENSIVE_ENTRIES),
            "SWING_DEFENSIVE_BREAKOUT_TIER_GATE_ENABLED": bool(SWING_DEFENSIVE_BREAKOUT_TIER_GATE_ENABLED),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MIN_RANK_SCORE": float(SWING_DEFENSIVE_BREAKOUT_TIER_MIN_RANK_SCORE),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MIN_CLOSE_TO_HIGH_PCT": float(SWING_DEFENSIVE_BREAKOUT_TIER_MIN_CLOSE_TO_HIGH_PCT),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MAX_BREAKOUT_EXTENSION_PCT": float(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_BREAKOUT_EXTENSION_PCT),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MAX_RISK_PER_SHARE_PCT": float(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_RISK_PER_SHARE_PCT),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MAX_NEW_ENTRIES_PER_SCAN": int(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_NEW_ENTRIES_PER_SCAN),
        },
        "rows": evidence[: max(1, min(int(limit or 50), 200))],
        "recommended_action": (
            "observe_next_defensive_scan"
            if not defensive_rows
            else ("tier_gate_has_allowed_candidates" if tier_allowed else "tier_gate_currently_blocks_all_defensive_candidates")
        ),
    }

def _p277_recent_swing_scan_rows(limit: int | None = None) -> list[dict]:
    scan_limit = max(1, int(limit or SWING_AWAY_MODE_SUPPRESSION_HISTORY_SCANS or 12))
    rows = []
    for payload in list(CANDIDATE_HISTORY or [])[-scan_limit:]:
        if not isinstance(payload, dict):
            continue
        candidates = [
            dict(row)
            for row in list(payload.get("candidates") or payload.get("items") or [])
            if isinstance(row, dict)
        ]
        selected_symbols = {
            str(sym or "").strip().upper()
            for sym in list(payload.get("selected") or payload.get("selected_symbols") or [])
            if str(sym or "").strip()
        }
        rows.append({
            "ts_utc": payload.get("ts_utc") or payload.get("scan_ts_utc"),
            "regime_mode": payload.get("regime_mode"),
            "regime_favorable": (payload.get("regime") or {}).get("favorable"),
            "candidate_count": len(candidates),
            "eligible_count": sum(1 for row in candidates if bool(row.get("eligible"))),
            "selected_count": len(selected_symbols),
            "selected_symbols": sorted(selected_symbols),
            "candidates": candidates,
        })
    return rows


def _p277_reason_family(reason: str) -> str:
    reason = str(reason or "").strip()
    protective = {
        "daily_halt_active",
        "daily_stop_hit",
        "swing_loss_day_entry_throttle",
        "same_day_symbol_loss_cooldown",
        "strategy_kill_switch_active",
        "swing_post_change_drawdown_circuit",
        "defensive_daily_breakout_rollback",
        "weak_tape",
    }
    capacity = {
        "position_already_open",
        "plan_or_pending_entry_exists",
        "selection_capacity_exhausted",
        "entry_capacity_exhausted",
        "portfolio_exposure_limit",
        "symbol_exposure_limit",
        "correlation_group_limit",
        "portfolio_already_over_cap_total",
        "portfolio_already_over_cap_strategy",
    }
    if reason in protective:
        return "protective"
    if reason in capacity:
        return "capacity_or_existing_exposure"
    if reason:
        return "quality"
    return "unknown"


def _p277_auto_suppression_evidence(limit: int | None = None) -> dict:
    scans = _p277_recent_swing_scan_rows(limit=limit)
    reason_counts: dict[str, int] = {}
    family_counts: dict[str, int] = {}
    symbol_counts: dict[str, int] = {}
    sample_rows = []

    total_candidates = 0
    total_eligible = 0
    total_selected = 0

    for scan in scans:
        candidates = list(scan.get("candidates") or [])
        total_candidates += len(candidates)
        total_eligible += int(scan.get("eligible_count") or 0)
        total_selected += int(scan.get("selected_count") or 0)

        for row in candidates:
            sym = str(row.get("symbol") or "").strip().upper()
            reasons = [str(r) for r in list(row.get("rejection_reasons") or []) if str(r).strip()]
            if not reasons:
                continue
            for reason in reasons:
                reason_counts[reason] = int(reason_counts.get(reason) or 0) + 1
                family = _p277_reason_family(reason)
                family_counts[family] = int(family_counts.get(family) or 0) + 1
            if sym:
                symbol_counts[sym] = int(symbol_counts.get(sym) or 0) + 1
            if len(sample_rows) < 25:
                sample_rows.append({
                    "symbol": sym,
                    "scan_ts_utc": scan.get("ts_utc"),
                    "regime_mode": row.get("regime_mode") or scan.get("regime_mode"),
                    "eligible": bool(row.get("eligible")),
                    "rank_score": row.get("rank_score"),
                    "selection_quality_score": row.get("selection_quality_score"),
                    "rejection_reasons": reasons,
                    "reason_families": sorted({_p277_reason_family(reason) for reason in reasons}),
                })

    quality_rejections = int(family_counts.get("quality") or 0)
    protective_rejections = int(family_counts.get("protective") or 0)
    capacity_rejections = int(family_counts.get("capacity_or_existing_exposure") or 0)
    rejection_total = max(1, quality_rejections + protective_rejections + capacity_rejections)
    quality_rejection_rate = round(quality_rejections / rejection_total, 4)

    if protective_rejections > 0:
        recommended_action = "review_protective_suppression_before_relaxing"
    elif capacity_rejections > quality_rejections and total_selected == 0:
        recommended_action = "review_capacity_or_existing_exposure"
    elif total_selected == 0 and quality_rejection_rate >= float(SWING_AWAY_MODE_MAX_QUALITY_REJECTION_RATE):
        recommended_action = "no_action_quality_filters_are_doing_their_job"
    elif total_selected == 0:
        recommended_action = "monitor_for_next_scan"
    else:
        recommended_action = "healthy_scanner_is_selecting"

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "swing_auto_suppression_evidence",
        "read_only": True,
        "scan_window": len(scans),
        "total_candidates": total_candidates,
        "total_eligible": total_eligible,
        "total_selected": total_selected,
        "selected_symbols": sorted({
            sym
            for scan in scans
            for sym in list(scan.get("selected_symbols") or [])
        }),
        "reason_counts": dict(sorted(reason_counts.items(), key=lambda item: item[1], reverse=True)),
        "reason_family_counts": dict(sorted(family_counts.items(), key=lambda item: item[1], reverse=True)),
        "quality_rejection_rate": quality_rejection_rate,
        "top_suppressed_symbols": [
            {"symbol": sym, "count": count}
            for sym, count in sorted(symbol_counts.items(), key=lambda item: item[1], reverse=True)[:15]
        ],
        "sample_rows": sample_rows,
        "recommended_action": recommended_action,
    }


def _p277_swing_away_mode_profit_monitor() -> dict:
    _ensure_runtime_state_loaded()
    snap = dict(read_positions_snapshot() or {})
    pnl = today_pnl_truth_snapshot()
    halt = daily_halt_truth_snapshot()
    suppression = _p277_auto_suppression_evidence()
    capacity = _p255_corrected_swing_capacity_truth_snapshot()
    post_change = _p261_post_change_drawdown_snapshot()
    release = _p264_daily_breakout_circuit_release_criteria()
    entry_audit = _p275_executed_entry_eligibility_audit(limit=25)

    positions = list(snap.get("positions") or [])
    active_plans = dict(snap.get("active_plans") or {})
    broker_position_count = len(positions)
    active_plan_count = len([
        plan for plan in active_plans.values()
        if isinstance(plan, dict) and bool(plan.get("active"))
    ])

    effective_max = int(_effective_max_open_positions() or 0)
    open_slots = max(0, effective_max - max(broker_position_count, active_plan_count))
    today_net = _safe_float(pnl.get("today_net_pnl"), 0.0)
    selected_recent = int(suppression.get("total_selected") or 0)
    candidate_total = int(suppression.get("total_candidates") or 0)

    alerts = []
    if bool(halt.get("daily_halt_active")):
        alerts.append("daily_halt_active")
    if today_net <= float(SWING_AWAY_MODE_WARN_DAILY_NET_BELOW):
        alerts.append("daily_net_below_away_mode_warning")
    if broker_position_count < int(SWING_AWAY_MODE_MIN_OPEN_POSITIONS) and selected_recent == 0 and open_slots > 0:
        alerts.append("underinvested_with_open_slots")
    if candidate_total < int(SWING_AWAY_MODE_MIN_CANDIDATES_PER_SCAN):
        alerts.append("candidate_flow_low")
    if int(entry_audit.get("conflict_count") or 0) > 0:
        alerts.append("entry_attribution_conflict")
    if bool(post_change.get("block_new_entries")):
        alerts.append("post_change_drawdown_circuit_blocking")
    if bool(release.get("broad_circuit_currently_blocking")) and not bool(release.get("release_candidate")):
        alerts.append("daily_breakout_release_not_ready")

    if bool(halt.get("daily_halt_active")):
        status = "protected_halt"
        recommended_action = "monitor_existing_positions_no_new_entries"
    elif "entry_attribution_conflict" in alerts:
        status = "needs_operator_review"
        recommended_action = "inspect_executed_entry_eligibility_audit"
    elif "post_change_drawdown_circuit_blocking" in alerts:
        status = "protected_by_drawdown_circuit"
        recommended_action = "keep_circuit_active_until_release_criteria_pass"
    elif broker_position_count >= int(SWING_AWAY_MODE_TARGET_OPEN_POSITIONS):
        status = "fully_alive"
        recommended_action = "monitor_profit_and_exits"
    elif selected_recent > 0:
        status = "alive_selecting"
        recommended_action = "monitor_entries_and_fills"
    elif open_slots > 0 and suppression.get("recommended_action") == "no_action_quality_filters_are_doing_their_job":
        status = "alive_waiting_for_quality"
        recommended_action = "do_not_loosen_quality_filters_yet"
    elif open_slots > 0:
        status = "available_but_quiet"
        recommended_action = "review_auto_suppression_evidence_after_next_scan"
    else:
        status = "at_capacity"
        recommended_action = "monitor_exits_before_new_entries"

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "swing_away_mode_profit_monitor",
        "read_only": True,
        "status": status,
        "recommended_action": recommended_action,
        "alerts": alerts,
        "profit": {
            "target_daily_profit_dollars": float(SWING_AWAY_MODE_PROFIT_TARGET_DOLLARS),
            "today_realized_pnl": pnl.get("today_realized_pnl"),
            "today_unrealized_pnl": pnl.get("today_unrealized_pnl"),
            "today_net_pnl": pnl.get("today_net_pnl"),
            "closed_trades_today": pnl.get("closed_trades_today"),
            "accounting_source": pnl.get("accounting_source"),
        },
        "exposure": {
            "broker_position_count": broker_position_count,
            "active_plan_count": active_plan_count,
            "effective_max_open_positions": effective_max,
            "open_slots": open_slots,
            "min_open_positions": int(SWING_AWAY_MODE_MIN_OPEN_POSITIONS),
            "target_open_positions": int(SWING_AWAY_MODE_TARGET_OPEN_POSITIONS),
            "capacity_truth": capacity,
        },
        "protection": {
            "daily_halt": halt,
            "post_change_drawdown": post_change,
            "daily_breakout_release": release,
            "entry_eligibility_audit": {
                "conflict_count": entry_audit.get("conflict_count"),
                "conflict_symbols": entry_audit.get("conflict_symbols"),
                "unresolved_count": entry_audit.get("unresolved_count"),
                "recommended_action": entry_audit.get("recommended_action"),
            },
        },
        "suppression": {
            "scan_window": suppression.get("scan_window"),
            "total_candidates": suppression.get("total_candidates"),
            "total_eligible": suppression.get("total_eligible"),
            "total_selected": suppression.get("total_selected"),
            "reason_family_counts": suppression.get("reason_family_counts"),
            "top_suppressed_symbols": suppression.get("top_suppressed_symbols"),
            "recommended_action": suppression.get("recommended_action"),
        },
    }


def _p277_swing_daily_health_brief() -> dict:
    monitor = _p277_swing_away_mode_profit_monitor()
    suppression = _p277_auto_suppression_evidence(limit=SWING_AWAY_MODE_QUIET_SCAN_WINDOW)
    current_scan = _p277h_current_scan_suppression_truth(limit=50)
    near_miss = _p277h_defensive_tier_near_miss_report(limit=50)

    status = monitor.get("status")
    recommended_action = monitor.get("recommended_action")
    alerts = list(monitor.get("alerts") or [])

    if current_scan.get("status") == "suppressed_by_protection":
        status = "current_scan_suppressed_by_protection"
        recommended_action = "review_current_scan_suppression_truth"
        if "current_scan_protective_suppression" not in alerts:
            alerts.append("current_scan_protective_suppression")

    if int(near_miss.get("tier_passed_count") or 0) > 0:
        status = "defensive_tier_candidate_available"
        recommended_action = "monitor_next_scanner_submission"
        if "defensive_tier_candidate_available" not in alerts:
            alerts.append("defensive_tier_candidate_available")
    elif int(near_miss.get("near_miss_count") or 0) > 0:
        if "defensive_tier_near_miss" not in alerts:
            alerts.append("defensive_tier_near_miss")

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "swing_daily_health_brief",
        "read_only": True,
        "status": status,
        "recommended_action": recommended_action,
        "alerts": alerts,
        "today_net_pnl": (monitor.get("profit") or {}).get("today_net_pnl"),
        "today_realized_pnl": (monitor.get("profit") or {}).get("today_realized_pnl"),
        "today_unrealized_pnl": (monitor.get("profit") or {}).get("today_unrealized_pnl"),
        "broker_position_count": (monitor.get("exposure") or {}).get("broker_position_count"),
        "effective_max_open_positions": (monitor.get("exposure") or {}).get("effective_max_open_positions"),
        "open_slots": (monitor.get("exposure") or {}).get("open_slots"),
        "recent_selected_count": suppression.get("total_selected"),
        "recent_eligible_count": suppression.get("total_eligible"),
        "recent_candidate_count": suppression.get("total_candidates"),
        "recent_selected_symbols": suppression.get("selected_symbols"),
        "top_suppression_reasons": list((suppression.get("reason_counts") or {}).items())[:10],
        "suppression_recommended_action": suppression.get("recommended_action"),
        "current_scan": {
            "status": current_scan.get("status"),
            "recommended_action": current_scan.get("recommended_action"),
            "candidate_count": current_scan.get("candidate_count"),
            "eligible_count": current_scan.get("eligible_count"),
            "selected_total": current_scan.get("selected_total"),
            "selected_symbols": current_scan.get("selected_symbols"),
            "regime_mode": current_scan.get("regime_mode"),
            "protective_reason_counts": current_scan.get("protective_reason_counts"),
            "defensive_rollback_blocked_count": current_scan.get("defensive_rollback_blocked_count"),
        },
        "defensive_tier": {
            "tier_passed_count": near_miss.get("tier_passed_count"),
            "tier_passed_symbols": near_miss.get("tier_passed_symbols"),
            "near_miss_count": near_miss.get("near_miss_count"),
            "near_miss_symbols": near_miss.get("near_miss_symbols"),
            "recommended_action": near_miss.get("recommended_action"),
        },
        "daily_checklist": [
            "confirm_status_not_protected_halt",
            "confirm_position_truth_aligned_on_live_positions",
            "confirm_no_entry_attribution_conflicts",
            "confirm_current_scan_not_unexpectedly_suppressed",
            "review_defensive_tier_near_misses_before_changing_envs",
        ],
    }

def _p277h_candidate_reason_counts(items: list[dict]) -> dict:
    reason_counts: dict[str, int] = {}
    family_counts: dict[str, int] = {}

    for row in items:
        reasons = [str(r) for r in list((row or {}).get("rejection_reasons") or []) if str(r).strip()]
        for reason in reasons:
            reason_counts[reason] = int(reason_counts.get(reason) or 0) + 1
            family = _p277_reason_family(reason)
            family_counts[family] = int(family_counts.get(family) or 0) + 1

    return {
        "reason_counts": dict(sorted(reason_counts.items(), key=lambda item: item[1], reverse=True)),
        "reason_family_counts": dict(sorted(family_counts.items(), key=lambda item: item[1], reverse=True)),
    }


def _p277h_defensive_tier_near_miss_row(row: dict | None) -> dict:
    row = dict(row or {})
    rollback = _p264_defensive_daily_breakout_rollback_snapshot(
        str(row.get("regime_mode") or ""),
        candidate=row,
    )
    tier = dict(rollback.get("tier_gate") or {})
    checks = list(tier.get("checks") or [])

    deltas = {}
    near_miss_blockers = []

    for check in checks:
        check = dict(check or {})
        name = str(check.get("name") or "")
        value = _safe_float(check.get("value"), 0.0)

        if "min" in check:
            threshold = _safe_float(check.get("min"), 0.0)
            miss = round(threshold - value, 6)
            deltas[name] = miss
            if name == "rank_score" and 0 < miss <= float(SWING_DEFENSIVE_TIER_NEAR_MISS_RANK_DELTA):
                near_miss_blockers.append(name)
            elif name == "close_to_high_pct" and 0 < miss <= float(SWING_DEFENSIVE_TIER_NEAR_MISS_CLOSE_TO_HIGH_DELTA):
                near_miss_blockers.append(name)

        if "max" in check:
            threshold = _safe_float(check.get("max"), 0.0)
            miss = round(value - threshold, 6)
            deltas[name] = miss
            if name == "breakout_extension_pct" and 0 < miss <= float(SWING_DEFENSIVE_TIER_NEAR_MISS_BREAKOUT_EXTENSION_DELTA):
                near_miss_blockers.append(name)
            elif name == "risk_per_share_pct" and 0 < miss <= float(SWING_DEFENSIVE_TIER_NEAR_MISS_RISK_DELTA):
                near_miss_blockers.append(name)

    blockers = [str(b) for b in list(tier.get("blockers") or [])]
    near_miss = bool(blockers and len(set(blockers) - set(near_miss_blockers)) == 0)

    return {
        "symbol": str(row.get("symbol") or "").strip().upper(),
        "eligible": bool(row.get("eligible")),
        "regime_mode": str(row.get("regime_mode") or "").strip().lower(),
        "rank_score": row.get("rank_score"),
        "selection_quality_score": row.get("selection_quality_score"),
        "close_to_high_pct": row.get("close_to_high_pct"),
        "breakout_distance_pct": row.get("breakout_distance_pct"),
        "risk_per_share_pct": row.get("risk_per_share_pct"),
        "rejection_reasons": list(row.get("rejection_reasons") or []),
        "rollback_blocked": bool(rollback.get("blocked")),
        "rollback_broad_blocked": bool(rollback.get("broad_blocked")),
        "tier_gate_passed": bool(tier.get("passed")),
        "tier_gate_blockers": blockers,
        "tier_gate_checks": checks,
        "near_miss": near_miss,
        "near_miss_blockers": near_miss_blockers,
        "tier_gate_deltas": deltas,
    }

def _p277h_current_scan_suppression_truth(limit: int = 50) -> dict:
    payload = _p406_fast_current_candidate_payload(limit=max(1, min(int(limit or 50), 100)))
    effective_scan = _p464_effective_market_scan(LAST_SCAN)
    latest = dict(payload.get("latest_scan") or {})
    if effective_scan and str(effective_scan.get("_scan_source") or "") == "last_actionable_market_scan":
        payload["status"] = "cached_market_scan_truth" if payload.get("status") == "stale_scan_not_actionable" else payload.get("status")
        payload["recommended_action"] = "use_preserved_market_scan_until_next_market_scan" if payload.get("recommended_action") == "recover_fresh_scan_before_evaluating_candidates" else payload.get("recommended_action")
        latest.update({
            "ts_utc": effective_scan.get("ts_utc"),
            "reason": effective_scan.get("reason"),
            "source": effective_scan.get("_scan_source"),
            "fallback_from_last_scan_reason": effective_scan.get("fallback_from_last_scan_reason"),
            "runtime_budget_sanitized": bool(effective_scan.get("runtime_budget_sanitized")),
        })
        payload["latest_scan"] = latest
    else:
        latest["source"] = effective_scan.get("_scan_source") if isinstance(effective_scan, dict) else latest.get("source")
        latest["runtime_budget_sanitized"] = bool((effective_scan or {}).get("runtime_budget_sanitized")) if isinstance(effective_scan, dict) else False
        payload["latest_scan"] = latest
    p475_effective_truth = _p475_scan_candidate_bearing_truth(effective_scan)
    payload["mode"] = "current_scan_suppression_truth"
    payload["read_only"] = True
    payload["source"] = "fast_cached_candidate_truth"
    payload["effective_market_scan_source"] = (effective_scan or {}).get("_scan_source") if isinstance(effective_scan, dict) else None
    payload["candidate_bearing_scan"] = bool(p475_effective_truth.get("candidate_bearing"))
    payload["trade_judgable"] = bool(p475_effective_truth.get("trade_judgable"))
    payload["regime_only_non_actionable"] = bool(p475_effective_truth.get("regime_only_non_actionable"))
    payload["p475_scan_truth_contract"] = dict(p475_effective_truth)
    payload["p480_effective_scan_truth"] = {
        "effective_scan_source": (effective_scan or {}).get("_p480_effective_scan_source") or (effective_scan or {}).get("_scan_source"),
        "after_hours_skip_preserved": bool((effective_scan or {}).get("_p480_after_hours_skip_preserved")),
        "preserved_scan_available": bool((effective_scan or {}).get("_p480_preserved_scan_available")),
        "preserved_scan_trade_judgable": bool((effective_scan or {}).get("_p480_preserved_scan_trade_judgable")),
        "raw_latest_scan": dict((effective_scan or {}).get("_p480_raw_latest_scan") or {}),
    }
    payload["p481_canonical_scan_truth"] = dict((effective_scan or {}).get("_p481_canonical_scan_truth") or {})
    payload["p484_candidate_eval_module"] = swing_candidate_eval_module_status(
        patch_version=PATCH_VERSION
    )
    payload = swing_candidate_eval_attach_status(payload, patch_version=PATCH_VERSION)

    if not bool(p475_effective_truth.get("trade_judgable")):
        payload["status"] = "scan_not_trade_judgable"
        payload["recommended_action"] = "wait_for_candidate_bearing_scan_completion"
    elif bool((effective_scan or {}).get("_p480_after_hours_skip_preserved")):
        payload["status"] = "preserved_candidate_bearing_scan"
        payload["recommended_action"] = "use_preserved_market_scan_until_next_market_scan"
    return payload

def _p277h_defensive_tier_near_miss_report(limit: int = 50) -> dict:
    payload = _diagnostics_candidates_payload(limit=max(1, min(int(limit or 50), 100)), full=True)
    items = [
        dict(row)
        for row in list(payload.get("items") or [])
        if isinstance(row, dict)
    ]

    defensive_rows = [
        row for row in items
        if str(row.get("regime_mode") or "").strip().lower() == "defensive"
    ]
    evaluated = [_p277h_defensive_tier_near_miss_row(row) for row in defensive_rows]

    blocked = [row for row in evaluated if bool(row.get("rollback_blocked"))]
    passable = [row for row in evaluated if bool(row.get("tier_gate_passed"))]
    near_misses = [row for row in evaluated if bool(row.get("near_miss"))]

    near_misses.sort(
        key=lambda row: (
            len(list(row.get("tier_gate_blockers") or [])),
            -_safe_float(row.get("rank_score"), 0.0),
        )
    )

    if passable:
        recommended_action = "tier_has_passable_defensive_candidates"
    elif near_misses:
        recommended_action = "review_near_miss_env_delta"
    elif blocked:
        recommended_action = "keep_defensive_tier_blocking"
    else:
        recommended_action = "observe_next_defensive_scan"

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "defensive_tier_near_miss_report",
        "read_only": True,
        "current_env": {
            "SWING_DEFENSIVE_BREAKOUT_TIER_GATE_ENABLED": bool(SWING_DEFENSIVE_BREAKOUT_TIER_GATE_ENABLED),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MIN_RANK_SCORE": float(SWING_DEFENSIVE_BREAKOUT_TIER_MIN_RANK_SCORE),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MIN_CLOSE_TO_HIGH_PCT": float(SWING_DEFENSIVE_BREAKOUT_TIER_MIN_CLOSE_TO_HIGH_PCT),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MAX_BREAKOUT_EXTENSION_PCT": float(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_BREAKOUT_EXTENSION_PCT),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MAX_RISK_PER_SHARE_PCT": float(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_RISK_PER_SHARE_PCT),
            "SWING_DEFENSIVE_BREAKOUT_TIER_MAX_NEW_ENTRIES_PER_SCAN": int(SWING_DEFENSIVE_BREAKOUT_TIER_MAX_NEW_ENTRIES_PER_SCAN),
        },
        "candidate_count": len(items),
        "defensive_rows": len(defensive_rows),
        "rollback_blocked_count": len(blocked),
        "tier_passed_count": len(passable),
        "tier_passed_symbols": [row.get("symbol") for row in passable],
        "near_miss_count": len(near_misses),
        "near_miss_symbols": [row.get("symbol") for row in near_misses[:25]],
        "near_misses": near_misses[:25],
        "top_defensive_rows": evaluated[:25],
        "recommended_action": recommended_action,
    }

