def _is_market_tradable_now(session: dict, data_feed_ok: bool) -> bool:
    """True only when the market is open and the current data feed is usable for trading decisions."""
    market_open = bool((session or {}).get("market_open_now"))
    return market_open and bool(data_feed_ok)


def _readiness_data_feed_state(session: dict, snapshot: dict) -> dict:
    """Classify quote/trade readiness separately from component health."""
    session = session or {}
    snapshot = snapshot or {}
    market_open = bool(session.get("market_open_now"))
    price_present = bool(snapshot.get("price"))
    quote_required = bool(ENTRY_REQUIRE_QUOTE)
    quote_ok = bool(snapshot.get("quote_ok"))
    fresh_required = bool(ENTRY_REQUIRE_FRESH_QUOTE)
    fresh = bool(snapshot.get("fresh"))
    spread_pct = snapshot.get("spread_pct")
    spread_limit = float(ENTRY_MAX_SPREAD_PCT)
    spread_ok = True
    if spread_pct is not None:
        try:
            spread_ok = float(spread_pct) <= spread_limit
        except Exception:
            spread_ok = False

    if not market_open:
        return {
            "ok": False,
            "reason": "market_closed",
            "label": "Market closed",
            "detail": "The market is closed, so quote tradability is not evaluated for promotion.",
        }
    if not price_present:
        return {
            "ok": False,
            "reason": "price_missing",
            "label": "Price missing",
            "detail": "No current trade or midpoint price was available for the readiness symbol.",
        }
    if quote_required and not quote_ok:
        return {
            "ok": False,
            "reason": "quote_missing_or_invalid",
            "label": "Quote missing/invalid",
            "detail": "A tradable two-sided quote was not available for the readiness symbol.",
        }
    if fresh_required and not fresh:
        age = snapshot.get("price_age_sec")
        age_txt = _dashboard_fmt(age) if age is not None else "unknown"
        return {
            "ok": False,
            "reason": "quote_stale",
            "label": "Quote stale",
            "detail": f"The latest readiness price is stale (age_sec={age_txt}).",
        }
    if not spread_ok:
        try:
            spread_txt = f"{float(spread_pct):.6f}"
        except Exception:
            spread_txt = "unknown"
        return {
            "ok": False,
            "reason": "spread_too_wide",
            "label": "Spread too wide",
            "detail": f"Current spread_pct={spread_txt} exceeds ENTRY_MAX_SPREAD_PCT={spread_limit:.6f}.",
        }
    return {
        "ok": True,
        "reason": "tradable",
        "label": "Tradable",
        "detail": "Market is open and the current quote data passes tradability checks.",
    }


def _compute_system_health_ok(
    *,
    scanner_running: bool,
    exit_worker_running: bool,
    broker_connected: bool,
    risk_limits_ok: bool,
    kill_switch: bool,
    daily_halt_active_flag: bool,
    journal_ok: bool,
    require_workers: bool = True,
) -> bool:
    """Pure component/process health, excluding session state, quote freshness, and release gating."""
    workers_ok = (bool(scanner_running) and bool(exit_worker_running)) if require_workers else True
    return all([
        workers_ok,
        bool(broker_connected),
        bool(risk_limits_ok),
        bool(journal_ok),
        not bool(kill_switch),
        not bool(daily_halt_active_flag),
    ])




def _universe_validation_snapshot() -> dict:
    runtime_syms = [str(s).strip().upper() for s in (universe_symbols() or []) if str(s).strip()]
    allowed_syms = sorted({str(s).strip().upper() for s in ALLOWED_SYMBOLS if str(s).strip()})
    allowed_set = set(allowed_syms)
    invalid = []
    valid = []
    for sym in runtime_syms:
        if sym in allowed_set:
            valid.append(sym)
        else:
            invalid.append({
                "symbol": sym,
                "suggestions": get_close_matches(sym, allowed_syms, n=3, cutoff=0.6),
            })
    return {
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "runtime_symbols": runtime_syms,
        "runtime_symbols_count": len(runtime_syms),
        "valid_runtime_symbols": valid,
        "invalid_runtime_symbols": invalid,
        "healthy": len(invalid) == 0,
    }


def _current_runtime_preview_snapshot(limit: int = 25) -> dict:
    limit = max(1, min(int(limit or 25), 100))
    runtime_syms = list(universe_symbols() or [])
    syms_for_fetch = list(runtime_syms)
    if SWING_INDEX_SYMBOL and SWING_INDEX_SYMBOL not in syms_for_fetch:
        syms_for_fetch.append(SWING_INDEX_SYMBOL)
    lookback_days = max(int(SCANNER_LOOKBACK_DAYS or 20) + 40, SWING_REGIME_SLOW_MA_DAYS + REGIME_BREADTH_RETURN_LOOKBACK_DAYS + 30, SWING_SLOW_MA_DAYS + SWING_BREAKOUT_LOOKBACK_DAYS + 20)
    daily_map = fetch_daily_bars_multi(syms_for_fetch, lookback_days=lookback_days) if runtime_syms else {}
    index_ok = _index_alignment_ok(daily_map.get(SWING_INDEX_SYMBOL, [])) if SWING_REQUIRE_INDEX_ALIGNMENT else None
    regime = _build_swing_regime(daily_map.get(SWING_INDEX_SYMBOL, []), daily_map, runtime_syms) if runtime_syms else {}
    regime_mode = _get_regime_mode(regime, index_ok) if SWING_REGIME_MODE_SWITCHING_ENABLED else ('trend' if regime.get('favorable') else 'defensive')
    thresholds = _regime_mode_thresholds(regime_mode)
    global_block_reasons = []
    if regime.get('favorable') is False and not bool(thresholds.get('allow_entries_when_regime_unfavorable')):
        global_block_reasons.append('weak_tape')

    post_change_drawdown = _p261_post_change_drawdown_snapshot()
    daily_goal_progress = _p295_broker_daily_goal_progress()
    breakout_drawdown_blocked = bool(
        STRATEGY_MODE == "swing"
        and post_change_drawdown.get("block_new_entries")
        and BREAKOUT_STRATEGY_NAME
        in set(post_change_drawdown.get("guarded_strategies") or [])
    )
    if breakout_drawdown_blocked:
        global_block_reasons.append(
            "swing_post_change_drawdown_circuit"
        )

    exposure = _current_portfolio_exposure_breakdown()
    open_total = float(exposure.get('total') or 0.0)
    open_strategy = float(exposure.get('strategy_managed') or 0.0)
    open_by_symbol = dict(exposure.get('by_symbol') or {})
    equity = max(0.0, _current_equity_estimate())
    portfolio_cap = equity * SWING_MAX_PORTFOLIO_EXPOSURE_PCT if equity > 0 else 0.0
    symbol_cap = equity * SWING_MAX_SYMBOL_EXPOSURE_PCT if equity > 0 else 0.0
    same_day_stats = _same_day_entry_stats()
    base_daily_entry_cap = int(SWING_MAX_NEW_ENTRIES_PER_DAY)
    effective_daily_entry_cap = base_daily_entry_cap
    dynamic_entry_cap_applied = False
    dynamic_entry_cap_reasons = []
    remaining_today = max(0, effective_daily_entry_cap - int(same_day_stats.get('counted') or 0))
    max_new_entries = max(0, min(int(effective_daily_entry_cap), int(candidate_slots_available()), int(SCANNER_MAX_ENTRIES_PER_SCAN)))
    

    rows = []
    for sym in runtime_syms:
        c = evaluate_daily_breakout_candidate(sym, daily_map.get(sym, []), index_ok, regime_mode=regime_mode)
        qty_signed, _ = get_position(sym)
        group_count = _open_group_position_count(sym)
        local_symbol_cap = float(symbol_cap)
        cap_truth = _cap_adjust_candidate_qty(
            _safe_float(c.get('close')),
            _safe_float(c.get('estimated_qty')),
            float(open_by_symbol.get(sym, 0.0) or 0.0),
            local_symbol_cap,
            exposure,
            portfolio_cap,
        )
        c['sizing_truth'] = dict(cap_truth)
        c['raw_estimated_qty'] = cap_truth.get('raw_estimated_qty')
        effective_est_qty = float(cap_truth.get('effective_estimated_qty') or 0.0)
        if effective_est_qty > 0 and effective_est_qty < float(c.get('estimated_qty') or 0.0):
            c['estimated_qty'] = round(effective_est_qty, 2)
        projected_notional = float(cap_truth.get('effective_projected_notional') or 0.0)
        selection_blockers = []
        if _has_pending_entry_plan(sym):
            c['eligible'] = False
            c.setdefault('rejection_reasons', []).append('plan_or_pending_entry_exists')
            selection_blockers.append('plan_or_pending_entry_exists')
        if qty_signed != 0:
            c['eligible'] = False
            c.setdefault('rejection_reasons', []).append('position_already_open')
            selection_blockers.append('position_already_open')
        if c.get('eligible') and global_block_reasons:
            c['eligible'] = False
            c.setdefault('rejection_reasons', []).extend(global_block_reasons)
            selection_blockers.extend([str(r) for r in global_block_reasons if str(r)])
        c['correlation_group_id'] = _symbol_group_id(sym)
        c['correlation_group_open_count'] = int(group_count)
        if c.get('eligible') and SWING_MAX_GROUP_POSITIONS > 0 and group_count >= SWING_MAX_GROUP_POSITIONS:
            c['eligible'] = False
            c.setdefault('rejection_reasons', []).append('correlation_group_limit')
            selection_blockers.append('correlation_group_limit')
        if c.get('eligible') and local_symbol_cap > 0 and projected_notional + float(open_by_symbol.get(sym, 0.0) or 0.0) > local_symbol_cap:
            c['eligible'] = False
            c.setdefault('rejection_reasons', []).append('symbol_exposure_limit')
            selection_blockers.append('symbol_exposure_limit')
        _canonical_portfolio_cap_gate(c, projected_notional, exposure, portfolio_cap, selection_blockers=selection_blockers, restore_eligibility=True)
        c['selection_blockers'] = list(dict.fromkeys([str(r) for r in selection_blockers if str(r)]))
        c = _p283_enrich_candidate_profit_truth(c)
        c = _p286_apply_target_path_recovery(c, global_block_reasons)
        c = _p296_apply_defensive_relaxation_promotion(
            c,
            global_block_reasons,
            daily_goal_progress=daily_goal_progress,
        )
        c = _p300_apply_executable_selection_contract(c, cap_truth=cap_truth)
        c = _p323_apply_swing_production_contract(c, global_block_reasons=global_block_reasons)
        rows.append(c)

    rows.sort(key=_p323_swing_production_sort_key, reverse=True)

    rows = _p323_enforce_production_contract_selection(
        rows,
        global_block_reasons=global_block_reasons,
    )
    production_approved = _p323_contract_approved_rows(rows)

    breakout_approved = [
        r for r in production_approved
        if str(r.get("strategy") or "").strip().lower() in {BREAKOUT_STRATEGY_NAME, "daily_breakout"}
    ]
    mean_reversion_approved = [
        r for r in production_approved
        if str(r.get("strategy") or "").strip().lower() == MEAN_REVERSION_STRATEGY_NAME
    ]
    target_path_approved = [
        r for r in breakout_approved
        if bool((r.get("target_path_profit") or {}).get("passed"))
    ]
    target_path_strong = [
        r for r in target_path_approved
        if float(_safe_float((r.get("target_path_profit") or {}).get("score"))) >= float(SWING_TARGET_PATH_STRONG_SCORE)
    ]

    dynamic_entry_cap_applied = False
    dynamic_entry_cap_reasons = ["legacy_dynamic_entry_cap_bypassed_by_p323"]

    remaining_today = max(0, effective_daily_entry_cap - int(same_day_stats.get('counted') or 0))
    max_new_entries = max(
        0,
        min(
            int(effective_daily_entry_cap),
            int(candidate_slots_available()),
            int(SCANNER_MAX_ENTRIES_PER_SCAN),
            int(SWING_PRODUCTION_RESET_MAX_ENTRIES_PER_SCAN),
        ),
    )
    max_new_entries = min(max_new_entries, remaining_today)

    weak_tape_capacity_override = {
        "enabled": False,
        "weak_tape": bool(regime_mode == "defensive" or regime.get("favorable") is False),
        "applies": False,
        "base_cap_before_override": int(max_new_entries),
        "effective_cap_after_override": int(max_new_entries),
        "reason": "legacy_weak_tape_capacity_override_bypassed_by_p323",
    }

    approved = production_approved
    selected = approved[:max_new_entries]
    selected_symbols = [str((r or {}).get('symbol') or '').upper() for r in selected if str((r or {}).get('symbol') or '').strip()]
    selected_symbol_set = set(selected_symbols)
    for row in rows:
        row["selected"] = str(row.get("symbol") or "").strip().upper() in selected_symbol_set
    eligible_but_not_selected = []
    if max_new_entries < len(approved):
        for row in approved[max_new_entries:]:
            sym = str((row or {}).get('symbol') or '').upper()
            eligible_but_not_selected.append({
                'symbol': sym,
                'rank_score': row.get('rank_score'),
                'reason': 'selection_capacity_exhausted',
            })
    validation = _universe_validation_snapshot()
    return {
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "preview_source": "current_runtime_env",
        "runtime_symbols": runtime_syms,
        "runtime_symbols_count": len(runtime_syms),
        "index_alignment_ok": index_ok,
        "regime": regime,
        "regime_mode": regime_mode,
        "mode_thresholds": thresholds,
        "global_block_reasons": global_block_reasons,
        "post_change_drawdown_circuit": post_change_drawdown,
        "blocked_by_post_change_drawdown": breakout_drawdown_blocked,
        "eligible_total": len(approved),
        "selected_total": len(selected_symbols),
        "selected_symbols": selected_symbols,
        'swing_production_reset': {
            'enabled': bool(SWING_PRODUCTION_RESET_ENABLED),
            'contract': 'single_entry_contract',
            'legacy_gate_mode': 'diagnostic_only' if bool(SWING_PRODUCTION_RESET_ENABLED) else 'legacy_live',
            'approved_count': len(production_approved),
            'approved_symbols': [c.get('symbol') for c in production_approved],
            'selected_symbols': [c.get('symbol') for c in selected],
            'max_entries_per_scan': int(SWING_PRODUCTION_RESET_MAX_ENTRIES_PER_SCAN),
            'min_rank_score': float(SWING_PRODUCTION_RESET_MIN_RANK_SCORE),
            'max_risk_per_share_pct': float(SWING_PRODUCTION_RESET_MAX_RISK_PER_SHARE_PCT),
        },
        "remaining_new_entries_today": int(remaining_today),
        "max_new_entries_effective": int(max_new_entries),
        "target_path_recovery_mode": {
            "enabled": bool(SWING_TARGET_PATH_RECOVERY_MODE_ENABLED),
            "min_score": float(SWING_TARGET_PATH_RECOVERY_MIN_SCORE),
            "allow_weak_tape_only": bool(SWING_TARGET_PATH_RECOVERY_ALLOW_WEAK_TAPE_ONLY),
            "max_entries_per_scan": int(SWING_TARGET_PATH_RECOVERY_MAX_ENTRIES_PER_SCAN),
            "recovered_count": sum(1 for r in rows if bool(r.get("target_path_recovery_mode"))),
            "recovered_symbols": [r.get("symbol") for r in rows if bool(r.get("target_path_recovery_mode"))],
            "risk_adjusted_near_miss_enabled": bool(SWING_TARGET_PATH_RISK_ADJUSTED_NEAR_MISS_ENABLED),
            "risk_adjusted_near_miss_count": sum(1 for r in rows if bool(r.get("risk_adjusted_near_miss_entry"))),
            "risk_adjusted_near_miss_symbols": [r.get("symbol") for r in rows if bool(r.get("risk_adjusted_near_miss_entry"))],
            "first_2k_revival_enabled": bool(SWING_FIRST_2K_REVIVAL_ENABLED),
            "first_2k_revival_count": sum(1 for r in rows if bool(r.get("first_2k_revival_entry"))),
            "first_2k_revival_symbols": [r.get("symbol") for r in rows if bool(r.get("first_2k_revival_entry"))],
            "first_2k_similarity_revival_enabled": bool(SWING_FIRST_2K_SIMILARITY_REVIVAL_ENABLED),
            "first_2k_similarity_revival_count": sum(1 for r in rows if bool(r.get("first_2k_similarity_revival_entry"))),
            "first_2k_similarity_revival_symbols": [r.get("symbol") for r in rows if bool(r.get("first_2k_similarity_revival_entry"))],
            "defensive_near_miss_relaxation_enabled": bool(SWING_DEFENSIVE_RELAXATION_LIVE_ENABLED),
            "defensive_near_miss_relaxation_count": sum(1 for r in rows if bool(r.get("defensive_near_miss_relaxation_entry"))),
            "defensive_near_miss_relaxation_symbols": [r.get("symbol") for r in rows if bool(r.get("defensive_near_miss_relaxation_entry"))],
        },
        "target_path_profit_engine": {
            "enabled": bool(SWING_TARGET_PATH_PROFIT_ENGINE_ENABLED),
            "min_score": float(SWING_TARGET_PATH_MIN_SCORE),
            "strong_score": float(SWING_TARGET_PATH_STRONG_SCORE),
            "target_path_approved_count": len(target_path_approved),
            "target_path_strong_count": len(target_path_strong),
            "target_path_approved_symbols": [r.get("symbol") for r in target_path_approved],
            "target_path_strong_symbols": [r.get("symbol") for r in target_path_strong],
            "risk_adjusted_near_miss_approved_count": len([r for r in target_path_approved if bool(r.get("risk_adjusted_near_miss_entry"))]),
            "risk_adjusted_near_miss_approved_symbols": [r.get("symbol") for r in target_path_approved if bool(r.get("risk_adjusted_near_miss_entry"))],
            "first_2k_revival_approved_count": len([r for r in target_path_approved if bool(r.get("first_2k_revival_entry"))]),
            "first_2k_revival_approved_symbols": [r.get("symbol") for r in target_path_approved if bool(r.get("first_2k_revival_entry"))],
            "first_2k_similarity_revival_approved_count": len([r for r in target_path_approved if bool(r.get("first_2k_similarity_revival_entry"))]),
            "first_2k_similarity_revival_approved_symbols": [r.get("symbol") for r in target_path_approved if bool(r.get("first_2k_similarity_revival_entry"))],
            "defensive_near_miss_relaxation_approved_count": len([r for r in target_path_approved if bool(r.get("defensive_near_miss_relaxation_entry"))]),
            "defensive_near_miss_relaxation_approved_symbols": [r.get("symbol") for r in target_path_approved if bool(r.get("defensive_near_miss_relaxation_entry"))],
            "mean_reversion_fallback_enabled": bool(SWING_TARGET_PATH_MEAN_REVERSION_FALLBACK_ENABLED),
        },
        "target_path_dynamic_entry_cap": {
            "enabled": bool(SWING_TARGET_PATH_DYNAMIC_ENTRY_CAP_ENABLED),
            "base_daily_entry_cap": int(base_daily_entry_cap),
            "effective_daily_entry_cap": int(effective_daily_entry_cap),
            "applied": bool(dynamic_entry_cap_applied),
            "configured_dynamic_cap": int(SWING_TARGET_PATH_DYNAMIC_ENTRY_CAP),
            "min_strong_candidates": int(SWING_TARGET_PATH_DYNAMIC_ENTRY_CAP_MIN_STRONG_CANDIDATES),
            "reasons": list(dynamic_entry_cap_reasons),
        },
        "strong_target_path_weak_tape_override": dict(weak_tape_capacity_override),
        "target_path_opportunity_expansion_lab": _p285_target_path_opportunity_expansion_lab(
            rows,
            limit=SWING_TARGET_PATH_OPPORTUNITY_LAB_LIMIT,
        ),
        "thrive_capacity_truth": {
            "base_daily_entry_cap": int(base_daily_entry_cap),
            "effective_daily_entry_cap": int(effective_daily_entry_cap),
            "remaining_new_entries_today": int(remaining_today),
            "max_new_entries_effective": int(max_new_entries),
            "candidate_slots_available": int(candidate_slots_available()),
            "scanner_max_entries_per_scan": int(SCANNER_MAX_ENTRIES_PER_SCAN),
            "weak_tape": bool(regime_mode == "defensive" or regime.get("favorable") is False),
            "weak_tape_override_applied": bool(weak_tape_capacity_override.get("applies")),
            "selected_total": len(selected),
            "selected_symbols": list(selected_symbols),
            "target_path_approved_count": len(target_path_approved),
            "target_path_strong_count": len(target_path_strong),
            "risk_adjusted_near_miss_selected_count": len([r for r in selected if bool(r.get("risk_adjusted_near_miss_entry"))]),
            "risk_adjusted_near_miss_selected_symbols": [r.get("symbol") for r in selected if bool(r.get("risk_adjusted_near_miss_entry"))],
            "first_2k_revival_selected_count": len([r for r in selected if bool(r.get("first_2k_revival_entry"))]),
            "first_2k_revival_selected_symbols": [r.get("symbol") for r in selected if bool(r.get("first_2k_revival_entry"))],
            "first_2k_similarity_revival_selected_count": len([r for r in selected if bool(r.get("first_2k_similarity_revival_entry"))]),
            "first_2k_similarity_revival_selected_symbols": [r.get("symbol") for r in selected if bool(r.get("first_2k_similarity_revival_entry"))],
            "defensive_near_miss_relaxation_selected_count": len([r for r in selected if bool(r.get("defensive_near_miss_relaxation_entry"))]),
            "defensive_near_miss_relaxation_selected_symbols": [r.get("symbol") for r in selected if bool(r.get("defensive_near_miss_relaxation_entry"))],
            "mean_reversion_eligible_total": len(mean_reversion_approved),
        },
        "portfolio_exposure": round(open_total, 2),
        "strategy_portfolio_exposure": round(open_strategy, 2),
        "portfolio_exposure_cap": round(portfolio_cap, 2),
        "portfolio_exposure_remaining": round(max(0.0, portfolio_cap - open_strategy), 2) if portfolio_cap > 0 else None,
        "symbol_exposure_cap": round(symbol_cap, 2),
        "top_candidates": rows[:limit],
        "eligible_but_not_selected": eligible_but_not_selected[:limit],
        "invalid_runtime_symbols": list(validation.get('invalid_runtime_symbols') or []),
        "healthy": len(validation.get('invalid_runtime_symbols') or []) == 0,
    }

