def _plan_risk_per_share(plan: dict) -> float:
    try:
        r = float(plan.get("risk_per_share") or 0.0)
        if r > 0:
            return r
    except Exception:
        pass
    try:
        return abs(float(plan.get("entry_price") or 0.0) - float(plan.get("initial_stop_price") or plan.get("stop_price") or 0.0))
    except Exception:
        return 0.0


def _restore_recovered_plan_protection(plan: dict) -> bool:
    if not isinstance(plan, dict):
        return False
    if not bool(plan.get("recovered")) or not bool(plan.get("broker_backed")):
        return False
    if str(plan.get("execution_state") or "").lower() not in {"filled", "open", "partial", "partially_filled"} and str(plan.get("order_status") or "").lower() not in {"filled", "partially_filled"}:
        return False
    side = str(plan.get("side") or "buy").lower()
    entry = _safe_float(plan.get("entry_price") or plan.get("avg_fill_price") or plan.get("filled_avg_price") or 0.0)
    current_stop = _safe_float(plan.get("stop_price") or 0.0)
    initial_stop = _safe_float(plan.get("initial_stop_price") or 0.0)
    if entry <= 0 or initial_stop <= 0:
        return False
    # Recovery should never silently neutralize initial protection by pinning stop to entry.
    if side == "buy":
        should_restore = abs(current_stop - entry) <= 0.011 and initial_stop < entry - 0.011
    else:
        should_restore = abs(current_stop - entry) <= 0.011 and initial_stop > entry + 0.011
    if not should_restore:
        return False
    plan["stop_price"] = round(initial_stop, 4)
    qty = abs(_safe_float(plan.get("filled_qty") or plan.get("qty") or 0.0))
    risk_per_share = abs(entry - initial_stop)
    if risk_per_share > 0:
        plan["risk_per_share"] = round(risk_per_share, 4)
        if qty > 0:
            plan["actual_risk_dollars"] = round(risk_per_share * qty, 4)
    return True


# Run startup restore only after all helper functions it depends on are defined.
startup_restore_state()


def _swing_unrealized_r(plan: dict, px: float) -> float:
    entry = _safe_float((plan or {}).get("entry_price") or 0.0)
    risk = _plan_risk_per_share(plan or {})
    if entry <= 0 or risk <= 0:
        return 0.0
    side = str((plan or {}).get("side") or "buy").lower()
    if side == "buy":
        return (float(px) - entry) / risk
    return (entry - float(px)) / risk


def _swing_opening_damage_guard(symbol: str, plan: dict, px: float) -> dict:
    out = {
        "enabled": bool(SWING_OPENING_DAMAGE_GUARD_ENABLED),
        "triggered": False,
        "reason": "disabled",
        "symbol": str(symbol or "").upper(),
    }
    if not SWING_OPENING_DAMAGE_GUARD_ENABLED:
        return out
    if STRATEGY_MODE != "swing":
        out["reason"] = "strategy_mode_not_swing"
        return out
    if SWING_OPENING_DAMAGE_REQUIRE_MARKET_OPEN and not in_market_hours():
        out["reason"] = "market_not_open"
        return out

    side = str((plan or {}).get("side") or "buy").lower()
    if side != "buy":
        out["reason"] = "not_long"
        return out

    entry = _safe_float((plan or {}).get("entry_price") or (plan or {}).get("avg_fill_price") or 0.0)
    risk = _plan_risk_per_share(plan or {})
    if entry <= 0 or risk <= 0 or px <= 0:
        out["reason"] = "missing_entry_or_risk"
        return out

    hold_days = plan_days_held(plan or {})
    unrealized_r = _swing_unrealized_r(plan or {}, float(px))
    minutes_since_open = _minutes_since_market_open()
    max_loss_r = float(SWING_OPENING_DAMAGE_MAX_LOSS_R or -1.10)
    grace_min = max(0, int(SWING_OPENING_DAMAGE_GRACE_MIN or 0))

    out.update({
        "reason": "ok",
        "entry_price": round(entry, 4),
        "price": round(float(px), 4),
        "risk_per_share": round(risk, 4),
        "hold_days": int(hold_days),
        "unrealized_r": round(unrealized_r, 4),
        "max_loss_r": float(max_loss_r),
        "minutes_since_market_open": round(float(minutes_since_open), 3),
        "grace_min": int(grace_min),
    })

    if minutes_since_open < grace_min:
        out["reason"] = "opening_grace_active"
        return out

    if unrealized_r <= max_loss_r:
        out["triggered"] = True
        out["reason"] = "opening_damage_max_loss_r"
        return out

    stop = _safe_float((plan or {}).get("stop_price") or 0.0)
    initial_stop = _safe_float((plan or {}).get("initial_stop_price") or 0.0)
    protective_stop = initial_stop if initial_stop > 0 else stop
    if protective_stop > 0 and float(px) <= protective_stop:
        out["triggered"] = True
        out["reason"] = "opening_damage_below_protective_stop"
        out["protective_stop"] = round(protective_stop, 4)
        return out

    return out


def _normalize_long_exit_plan(plan: dict, px: float) -> dict:
    """
    Separate protective stop logic from profit-lock logic for long positions.

    Fields:
      - stop_price: protective stop (never above entry for longs)
      - profit_lock_price: managed winner floor (may rise above entry, but must stay below market)
      - take_price: final full target
    """
    out = {"changed": False, "flags": []}
    if not isinstance(plan, dict):
        return out
    side = str((plan or {}).get("side") or "buy").lower()
    if side != "buy":
        return out

    px = _safe_float(px)
    entry = _safe_float((plan or {}).get("entry_price") or (plan or {}).get("avg_fill_price") or 0.0)
    stop = _safe_float((plan or {}).get("stop_price") or 0.0)
    take = _safe_float((plan or {}).get("take_price") or 0.0)
    profit_lock = _safe_float((plan or {}).get("profit_lock_price") or 0.0)
    initial_stop = _safe_float((plan or {}).get("initial_stop_price") or 0.0)
    risk = max(_plan_risk_per_share(plan or {}), 0.0)

    if px <= 0:
        return out

    clamp_tick = max(0.01, round(max(risk * 0.05, px * 0.0005), 4))

    # Migrate legacy above-entry stop into explicit profit-lock semantics.
    if entry > 0 and stop > entry + 1e-9:
        migrated_profit_lock = stop
        profit_lock = max(profit_lock, migrated_profit_lock)
        plan["profit_lock_price"] = round(profit_lock, 4)
        plan["stop_price"] = round(entry, 4)
        stop = entry
        out["changed"] = True
        out["flags"].append("migrated_above_entry_stop_to_profit_lock")

    # If a winner lock was armed, keep the original protective stop below entry and
    # express break-even/profit protection through profit_lock_price instead.
    entry_pinned_stop = entry > 0 and abs(stop - entry) <= 0.011
    has_initial_protection = initial_stop > 0 and initial_stop < entry - 0.011
    intentional_winner_lock = bool(
        profit_lock > 0
        or (plan or {}).get("partial_profit_taken")
        or (plan or {}).get("break_even_armed")
        or (plan or {}).get("time_exit_grace_active")
    )
    if entry_pinned_stop and has_initial_protection and intentional_winner_lock:
        profit_lock = max(profit_lock, entry)
        plan["profit_lock_price"] = round(profit_lock, 4)
        plan["stop_price"] = round(initial_stop, 4)
        stop = initial_stop
        out["changed"] = True
        out["flags"].append("migrated_entry_pinned_stop_to_profit_lock")

    # Protective stop for long positions should never exceed entry.
    if entry > 0 and stop > entry + 1e-9:
        plan["stop_price"] = round(entry, 4)
        stop = entry
        out["changed"] = True
        out["flags"].append("protective_stop_capped_at_entry")

    # Keep protective stop from arming above the live price.
    if stop > 0 and stop >= px - 1e-9:
        safe_stop = min(stop, (entry if entry > 0 else px) , px - clamp_tick)
        if take > 0:
            safe_stop = min(safe_stop, take - 0.01)
        safe_stop = max(safe_stop, 0.0)
        if safe_stop > 0 and abs(safe_stop - stop) > 1e-9:
            plan["stop_price"] = round(safe_stop, 4)
            stop = safe_stop
            out["changed"] = True
            out["flags"].append("protective_stop_clamped_below_market")

    # Managed profit-lock may rise above entry, but must remain below market and target.
    if profit_lock > 0 and profit_lock >= px - 1e-9:
        safe_floor = px - clamp_tick
        if take > 0:
            safe_floor = min(safe_floor, take - 0.01)
        safe_floor = max(safe_floor, entry if entry > 0 else 0.0)
        if safe_floor > 0 and abs(safe_floor - profit_lock) > 1e-9:
            plan["profit_lock_price"] = round(safe_floor, 4)
            profit_lock = safe_floor
            out["changed"] = True
            out["flags"].append("profit_lock_clamped_below_market")

    if take > 0 and stop > 0 and stop >= take - 1e-9:
        safe_stop = min(entry if entry > 0 else take - 0.01, take - 0.01)
        safe_stop = max(safe_stop, 0.0)
        if safe_stop > 0 and abs(safe_stop - stop) > 1e-9:
            plan["stop_price"] = round(safe_stop, 4)
            stop = safe_stop
            out["changed"] = True
            out["flags"].append("protective_stop_clamped_below_take")

    if take > 0 and profit_lock > 0 and profit_lock >= take - 1e-9:
        safe_floor = max(entry if entry > 0 else 0.0, take - 0.01)
        safe_floor = min(safe_floor, take - 0.01)
        if safe_floor > 0 and abs(safe_floor - profit_lock) > 1e-9:
            plan["profit_lock_price"] = round(safe_floor, 4)
            out["changed"] = True
            out["flags"].append("profit_lock_clamped_below_take")

    return out

def _p378_is_daily_breakout_plan(plan: dict | None) -> bool:
    plan = dict(plan or {})
    thesis = dict(plan.get("thesis") or {})
    strategy = str(
        plan.get("strategy_name")
        or plan.get("strategy")
        or plan.get("signal")
        or thesis.get("strategy_name")
        or thesis.get("signal")
        or ""
    ).strip().lower()
    return strategy in {"daily_breakout", str(BREAKOUT_STRATEGY_NAME or "").strip().lower()}


def _p378_plan_opened_minutes_ago(plan: dict | None) -> float | None:
    opened = _parse_plan_opened_dt(dict(plan or {}))
    if opened is None:
        return None
    return max(0.0, (now_ny() - opened).total_seconds() / 60.0)

def _p378_plan_entry_ts_utc(plan: dict | None) -> datetime | None:
    plan = dict(plan or {})
    for key in ("opened_at", "entry_ts_utc", "filled_at", "submitted_at"):
        dt = _p376_parse_utc_dt(plan.get(key))
        if dt:
            return dt
    thesis = dict(plan.get("thesis") or {})
    for key in ("opened_at", "entry_ts_utc", "scan_ts", "submitted_at"):
        dt = _p376_parse_utc_dt(thesis.get(key))
        if dt:
            return dt
    return None


def _p378_recent_backfill_fresh(prior: dict | None) -> bool:
    prior = dict(prior or {})
    refresh_sec = max(0, int(DAILY_BREAKOUT_PROFIT_GIVEBACK_HIGH_WATER_BACKFILL_MIN_REFRESH_SEC or 0))
    if refresh_sec <= 0:
        return False
    ts = _p376_parse_utc_dt(prior.get("high_water_backfill_ts_utc"))
    if not ts:
        return False
    age_sec = (datetime.now(timezone.utc) - ts).total_seconds()
    return bool(age_sec < refresh_sec)


def _p378_active_breakout_high_water_backfill(symbol: str, plan: dict | None, entry_price: float) -> dict:
    sym = str(symbol or "").strip().upper()
    plan = dict(plan or {})
    prior = dict(plan.get("daily_breakout_profit_giveback") or {})

    out = {
        "ok": False,
        "enabled": bool(DAILY_BREAKOUT_PROFIT_GIVEBACK_HIGH_WATER_BACKFILL_ENABLED),
        "symbol": sym,
        "reason": "disabled",
    }

    if not DAILY_BREAKOUT_PROFIT_GIVEBACK_HIGH_WATER_BACKFILL_ENABLED:
        return out
    if _p378_recent_backfill_fresh(prior):
        out.update({
            "ok": True,
            "reason": "recent_backfill_fresh",
            "max_favorable_return_pct": _safe_float(prior.get("high_return_pct"), 0.0),
            "high_price": _safe_float(prior.get("high_price"), 0.0),
            "source": "cached_plan_state",
        })
        return out

    entry = _safe_float(entry_price, 0.0)
    if not sym or entry <= 0:
        out["reason"] = "missing_symbol_or_entry"
        return out

    entry_dt = _p378_plan_entry_ts_utc(plan)
    if not entry_dt:
        out["reason"] = "missing_entry_ts"
        return out

    try:
        bars = fetch_1m_bars(
            sym,
            lookback_days=max(1, int(DAILY_BREAKOUT_PROFIT_GIVEBACK_HIGH_WATER_BACKFILL_LOOKBACK_DAYS or 3)),
            limit=max(100, int(DAILY_BREAKOUT_PROFIT_GIVEBACK_HIGH_WATER_BACKFILL_LIMIT or 3000)),
            feed_override=_DATA_FEED_RAW or "iex",
        )
    except Exception as exc:
        out["reason"] = "bar_fetch_error"
        out["error"] = str(exc)
        return out

    max_high = 0.0
    max_high_ts = None
    bars_after_entry = 0

    for raw in list(bars or []):
        bar = dict(raw or {})
        ts = _p376_bar_ts_utc(bar)
        if not ts or ts < entry_dt:
            continue
        high = _safe_float(bar.get("high") or bar.get("close") or 0.0, 0.0)
        if high <= 0:
            continue
        bars_after_entry += 1
        if high > max_high:
            max_high = high
            max_high_ts = ts.isoformat()

    if max_high <= 0 or bars_after_entry <= 0:
        out["reason"] = "no_bars_after_entry"
        out["entry_ts_utc"] = entry_dt.isoformat()
        return out

    max_return_pct = ((max_high - entry) / entry) * 100.0

    out.update({
        "ok": True,
        "reason": "backfilled_from_1m_bars",
        "source": "recent_1m_bars",
        "entry_ts_utc": entry_dt.isoformat(),
        "bars_after_entry": int(bars_after_entry),
        "max_high_ts_utc": max_high_ts,
        "high_price": round(max_high, 4),
        "max_favorable_return_pct": round(max_return_pct, 4),
        "lookback_days": int(DAILY_BREAKOUT_PROFIT_GIVEBACK_HIGH_WATER_BACKFILL_LOOKBACK_DAYS or 3),
    })
    return out

def _p378_daily_breakout_profit_giveback_state(symbol: str, plan: dict | None, px: float) -> dict:
    plan = plan if isinstance(plan, dict) else {}
    sym = str(symbol or plan.get("symbol") or "").strip().upper()
    entry = _safe_float(plan.get("entry_price") or plan.get("avg_fill_price") or 0.0, 0.0)
    side = str(plan.get("side") or "buy").strip().lower()
    prior = dict(plan.get("daily_breakout_profit_giveback") or {})

    out = {
        "enabled": bool(DAILY_BREAKOUT_PROFIT_GIVEBACK_EXIT_ENABLED),
        "symbol": sym,
        "is_daily_breakout": _p378_is_daily_breakout_plan(plan),
        "triggered": False,
        "reason": "not_applicable",
        "updates": {},
    }

    if not DAILY_BREAKOUT_PROFIT_GIVEBACK_EXIT_ENABLED:
        out["reason"] = "disabled"
        return out
    if STRATEGY_MODE != "swing":
        out["reason"] = "strategy_mode_not_swing"
        return out
    if not out["is_daily_breakout"]:
        out["reason"] = "not_daily_breakout"
        return out
    if side != "buy":
        out["reason"] = "not_long"
        return out
    if entry <= 0 or px <= 0:
        out["reason"] = "missing_entry_or_price"
        return out

    hold_min = _p378_plan_opened_minutes_ago(plan)
    min_hold = max(0, int(DAILY_BREAKOUT_PROFIT_GIVEBACK_MIN_HOLD_MIN or 0))
    current_return_pct = ((float(px) - entry) / entry) * 100.0

    backfill = _p378_active_breakout_high_water_backfill(sym, plan, entry)
    prior_high_pct = _safe_float(prior.get("high_return_pct"), 0.0)
    backfill_high_pct = _safe_float(backfill.get("max_favorable_return_pct"), 0.0) if bool(backfill.get("ok")) else 0.0

    high_return_pct = max(prior_high_pct, backfill_high_pct, current_return_pct)
    high_price = _safe_float(prior.get("high_price"), 0.0)

    if backfill_high_pct >= prior_high_pct and _safe_float(backfill.get("high_price"), 0.0) > 0:
        high_price = _safe_float(backfill.get("high_price"), 0.0)
    if current_return_pct >= high_return_pct or high_price <= 0:
        high_price = float(px)

    giveback_pct = high_return_pct - current_return_pct
    min_favorable = float(DAILY_BREAKOUT_PROFIT_GIVEBACK_MIN_FAVORABLE_PCT or 0.0)
    max_giveback = float(DAILY_BREAKOUT_PROFIT_GIVEBACK_MAX_GIVEBACK_PCT or 0.0)
    min_lock_profit = float(DAILY_BREAKOUT_PROFIT_GIVEBACK_MIN_LOCK_PROFIT_PCT or 0.0)

    lock_return_pct = max(min_lock_profit, high_return_pct - max_giveback)
    lock_price = entry * (1.0 + (lock_return_pct / 100.0)) if high_return_pct >= min_favorable else 0.0

    state = {
        "high_return_pct": round(high_return_pct, 4),
        "high_price": round(high_price, 4),
        "current_return_pct": round(current_return_pct, 4),
        "giveback_pct": round(giveback_pct, 4),
        "lock_return_pct": round(lock_return_pct, 4) if lock_price > 0 else None,
        "lock_price": round(lock_price, 4) if lock_price > 0 else None,
        "min_favorable_pct": round(min_favorable, 4),
        "max_giveback_pct": round(max_giveback, 4),
        "min_hold_min": int(min_hold),
        "hold_min": round(float(hold_min), 2) if hold_min is not None else None,
        "high_water_backfill": backfill,
        "high_water_backfill_ts_utc": datetime.now(timezone.utc).isoformat() if bool(backfill.get("ok")) else prior.get("high_water_backfill_ts_utc"),
        "updated_at_utc": datetime.now(timezone.utc).isoformat(),
    }

    out["state"] = state
    out["updates"]["daily_breakout_profit_giveback"] = state

    if high_return_pct >= min_favorable and lock_price > 0:
        current_profit_lock = _safe_float(plan.get("profit_lock_price") or 0.0, 0.0)
        if lock_price > current_profit_lock:
            out["updates"]["profit_lock_price"] = round(lock_price, 4)
            out["profit_lock_armed"] = True

    if hold_min is not None and hold_min < min_hold:
        out["reason"] = "minimum_hold_window_active"
        return out

    if high_return_pct >= min_favorable and giveback_pct >= max_giveback:
        out["triggered"] = True
        out["reason"] = "daily_breakout_profit_giveback_preservation_exit"
        return out

    out["reason"] = "monitoring_profit_giveback"
    return out

def _p445_plan_available_qty(plan: dict | None) -> float:
    return float(swing_exec_available_qty_from_plan(plan))


def _p445_qty_source(plan: dict | None) -> str:
    return str(swing_exec_qty_source_from_plan(plan))


def _p446_clamp_exit_qty(qty_to_close: float, available_qty: float) -> float:
    return _normalize_close_qty(float(swing_exec_clamp_exit_qty(qty_to_close, available_qty)))

def _p444_breakout_partial_profit_bias_state(symbol: str, plan: dict | None, px: float, dynamic_exit: dict | None = None) -> dict:
    plan = plan if isinstance(plan, dict) else {}
    dyn = dict(dynamic_exit or {})
    sym = str(symbol or plan.get("symbol") or "").strip().upper()
    qty = _p445_plan_available_qty(plan)
    qty_source = _p445_qty_source(plan)
    unrealized_r = _safe_float(dyn.get("stall_r"), _swing_unrealized_r(plan, px))
    partial_taken = bool(plan.get("partial_profit_taken") or plan.get("breakout_partial_profit_bias_taken"))

    fraction = min(max(float(SWING_BREAKOUT_PARTIAL_PROFIT_FRACTION or 0.5), 0.05), 0.95)
    qty_to_close = _p446_clamp_exit_qty(qty * fraction, qty)
    min_qty = float(SWING_PARTIAL_PROFIT_MIN_QTY or 0.0)

    applies = bool(
        SWING_BREAKOUT_PARTIAL_PROFIT_BIAS_ENABLED
        and _p378_is_daily_breakout_plan(plan)
        and qty > 0
        and not partial_taken
        and unrealized_r >= float(SWING_BREAKOUT_PARTIAL_PROFIT_R or 0.75)
        and qty_to_close >= min_qty
        and qty_to_close < qty
    )

    return {
        "enabled": bool(SWING_BREAKOUT_PARTIAL_PROFIT_BIAS_ENABLED),
        "symbol": sym,
        "is_daily_breakout": bool(_p378_is_daily_breakout_plan(plan)),
        "applies": applies,
        "reason": "breakout_partial_profit_bias_ready" if applies else "not_ready",
        "unrealized_r": round(unrealized_r, 4),
        "trigger_r": float(SWING_BREAKOUT_PARTIAL_PROFIT_R or 0.75),
        "qty": round(qty, 4),
        "qty_source": qty_source,
        "qty_to_close": round(qty_to_close, 4),
        "fraction": round(fraction, 4),
        "partial_taken": partial_taken,
    }


def _p444_breakout_stall_loss_reduce_first_state(symbol: str, plan: dict | None, px: float, dynamic_exit: dict | None = None) -> dict:
    plan = plan if isinstance(plan, dict) else {}
    dyn = dict(dynamic_exit or {})
    sym = str(symbol or plan.get("symbol") or "").strip().upper()
    flags = set(str(x or "") for x in list(dyn.get("flags") or []))
    stall_loss_due = bool("stall_loss_guard_ready" in flags or dyn.get("stall_loss_guard"))
    qty = _p445_plan_available_qty(plan)
    qty_source = _p445_qty_source(plan)
    fraction = min(max(float(SWING_BREAKOUT_STALL_LOSS_REDUCE_FRACTION or 0.5), 0.05), 0.95)
    qty_to_close = _p446_clamp_exit_qty(qty * fraction, qty)
    min_qty = float(SWING_PARTIAL_PROFIT_MIN_QTY or 0.0)

    applies = bool(
        SWING_BREAKOUT_STALL_LOSS_REDUCE_FIRST_ENABLED
        and _p378_is_daily_breakout_plan(plan)
        and stall_loss_due
        and qty_to_close >= min_qty
        and qty_to_close < qty
        and not bool(plan.get("breakout_stall_loss_reduce_first_taken"))
    )

    return {
        "enabled": bool(SWING_BREAKOUT_STALL_LOSS_REDUCE_FIRST_ENABLED),
        "symbol": sym,
        "is_daily_breakout": bool(_p378_is_daily_breakout_plan(plan)),
        "applies": applies,
        "reason": "breakout_stall_loss_reduce_first_ready" if applies else "not_ready",
        "stall_loss_due": bool(stall_loss_due),
        "unrealized_r": round(_safe_float(dyn.get("stall_r"), _swing_unrealized_r(plan, px)), 4),
        "qty": round(qty, 4),
        "qty_source": qty_source,
        "qty_to_close": round(qty_to_close, 4),
        "fraction": round(fraction, 4),
        "already_taken": bool(plan.get("breakout_stall_loss_reduce_first_taken")),
    }

def _p380_daily_breakout_failed_followthrough_state(symbol: str, plan: dict | None, px: float) -> dict:
    plan = plan if isinstance(plan, dict) else {}
    sym = str(symbol or plan.get("symbol") or "").strip().upper()
    entry = _safe_float(plan.get("entry_price") or plan.get("avg_fill_price") or 0.0, 0.0)
    side = str(plan.get("side") or "buy").strip().lower()

    out = {
        "enabled": bool(DAILY_BREAKOUT_FAILED_FOLLOWTHROUGH_EXIT_ENABLED),
        "symbol": sym,
        "is_daily_breakout": _p378_is_daily_breakout_plan(plan),
        "triggered": False,
        "reason": "not_applicable",
    }

    if not DAILY_BREAKOUT_FAILED_FOLLOWTHROUGH_EXIT_ENABLED:
        out["reason"] = "disabled"
        return out
    if STRATEGY_MODE != "swing":
        out["reason"] = "strategy_mode_not_swing"
        return out
    if not out["is_daily_breakout"]:
        out["reason"] = "not_daily_breakout"
        return out
    if side != "buy":
        out["reason"] = "not_long"
        return out
    if entry <= 0 or px <= 0:
        out["reason"] = "missing_entry_or_price"
        return out

    opened = _parse_plan_opened_dt(plan)
    opened_today = bool(opened and opened.date() == now_ny().date())
    hold_min = _p378_plan_opened_minutes_ago(plan)
    current_return_pct = ((float(px) - entry) / entry) * 100.0

    backfill = _p378_active_breakout_high_water_backfill(sym, plan, entry)
    prior = dict(plan.get("daily_breakout_profit_giveback") or {})
    prior_high_pct = _safe_float(prior.get("high_return_pct"), 0.0)
    backfill_high_pct = _safe_float(backfill.get("max_favorable_return_pct"), 0.0) if bool(backfill.get("ok")) else 0.0
    high_return_pct = max(prior_high_pct, backfill_high_pct, current_return_pct, 0.0)

    min_hold = max(0, int(DAILY_BREAKOUT_FAILED_FOLLOWTHROUGH_MIN_HOLD_MIN or 0))
    min_favorable = float(DAILY_BREAKOUT_FAILED_FOLLOWTHROUGH_MIN_FAVORABLE_PCT or 0.0)
    max_current_return = float(DAILY_BREAKOUT_FAILED_FOLLOWTHROUGH_MAX_CURRENT_RETURN_PCT or 0.0)

    out.update({
        "opened_today": opened_today,
        "hold_min": round(float(hold_min), 2) if hold_min is not None else None,
        "min_hold_min": int(min_hold),
        "entry_price": round(entry, 4),
        "current_price": round(float(px), 4),
        "current_return_pct": round(current_return_pct, 4),
        "high_return_pct": round(high_return_pct, 4),
        "min_favorable_pct": round(min_favorable, 4),
        "max_current_return_pct": round(max_current_return, 4),
        "high_water_backfill": backfill,
    })

    if not opened_today:
        out["reason"] = "not_opened_today"
        return out
    if hold_min is None or hold_min < min_hold:
        out["reason"] = "minimum_hold_window_active"
        return out
    if high_return_pct >= min_favorable:
        out["reason"] = "had_enough_followthrough"
        return out
    if current_return_pct <= max_current_return:
        out["triggered"] = True
        out["reason"] = "daily_breakout_failed_followthrough_exit"
        return out

    out["reason"] = "monitoring_failed_followthrough"
    return out

def _p381_forbidden_short_cleanup_state(symbol: str, plan: dict | None, qty_signed: float | None = None) -> dict:
    sym = str(symbol or "").strip().upper()
    qty = _safe_float(qty_signed, 0.0)

    out = {
        "enabled": bool(FORBIDDEN_SHORT_POSITION_CLEANUP_ENABLED),
        "symbol": sym,
        "allow_short": bool(ALLOW_SHORT),
        "qty_signed": round(qty, 8),
        "triggered": False,
        "reason": "not_applicable",
        "close_side": None,
    }

    if not FORBIDDEN_SHORT_POSITION_CLEANUP_ENABLED:
        out["reason"] = "disabled"
        return out
    if ALLOW_SHORT:
        out["reason"] = "shorts_allowed"
        return out
    if qty >= 0:
        out["reason"] = "not_short"
        return out

    out["triggered"] = True
    out["reason"] = "forbidden_short_position_cleanup"
    out["close_side"] = "buy"
    out["qty_to_cover"] = _normalize_close_qty(abs(qty))
    return out

def _p381_forbidden_short_cleanup_truth() -> dict:
    positions = _p364_snapshot_position_by_symbol()
    rows = []

    for symbol, pos in sorted(positions.items()):
        sym = str(symbol or "").strip().upper()
        qty = _safe_float((pos or {}).get("qty") or 0.0, 0.0)
        plan = dict((TRADE_PLAN or {}).get(sym) or {})
        state = _p381_forbidden_short_cleanup_state(sym, plan, qty)
        rows.append({
            "symbol": sym,
            "qty": qty,
            "has_active_plan": bool(plan.get("active")),
            "state": state,
        })

    due = [r for r in rows if bool((r.get("state") or {}).get("triggered"))]

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "forbidden_short_cleanup_truth",
        "read_only": True,
        "enabled": bool(FORBIDDEN_SHORT_POSITION_CLEANUP_ENABLED),
        "allow_short": bool(ALLOW_SHORT),
        "due_count": len(due),
        "due_symbols": [r.get("symbol") for r in due],
        "rows": rows,
        "recommended_action": (
            "worker_exit_should_buy_to_cover_forbidden_short_positions"
            if due
            else "none"
        ),
    }

def _p388_oversized_winner_preservation_plan(symbol: str, plan: dict, px: float) -> dict:
    if not bool(SWING_OVERSIZED_WINNER_PRESERVATION_ENABLED):
        return {"triggered": False, "reason": "disabled"}
    if bool((plan or {}).get("oversized_winner_preservation_taken")):
        return {"triggered": False, "reason": "already_taken"}

    side = str((plan or {}).get("side") or "buy").lower()
    if side != "buy":
        return {"triggered": False, "reason": "not_long"}

    qty = abs(_safe_float((plan or {}).get("filled_qty") or (plan or {}).get("qty") or 0.0))
    entry = _safe_float((plan or {}).get("entry_price") or (plan or {}).get("avg_fill_price") or 0.0)
    stop = _safe_float((plan or {}).get("stop_price") or (plan or {}).get("initial_stop_price") or 0.0)

    if qty <= 0 or entry <= 0 or stop <= 0:
        return {"triggered": False, "reason": "missing_qty_entry_or_stop"}

    risk_per_share = max(0.0, entry - stop)
    if risk_per_share <= 0:
        return {"triggered": False, "reason": "invalid_risk_per_share"}

    unrealized = (float(px or 0.0) - entry) * qty
    if unrealized < float(SWING_OVERSIZED_WINNER_MIN_UNREALIZED_DOLLARS or 0.0):
        return {
            "triggered": False,
            "reason": "winner_profit_below_threshold",
            "unrealized_pl": round(unrealized, 4),
        }

    current_risk = qty * risk_per_share
    configured_risk = max(0.0, float(RISK_DOLLARS or 0.0))
    advisory_threshold = configured_risk * max(0.0, float(SWING_OVERSIZED_POSITION_ADVISORY_MULTIPLE or 0.0))
    target_risk = configured_risk * max(0.0, float(SWING_OVERSIZED_WINNER_REDUCE_TO_RISK_MULTIPLE or 0.0))

    if configured_risk <= 0 or current_risk <= advisory_threshold:
        return {
            "triggered": False,
            "reason": "not_oversized_vs_config",
            "current_risk_dollars": round(current_risk, 4),
            "advisory_threshold_dollars": round(advisory_threshold, 4),
        }

    target_qty_by_risk = target_risk / risk_per_share if risk_per_share > 0 else qty
    min_remaining = max(0.0, float(SWING_OVERSIZED_WINNER_MIN_REMAINING_QTY or 0.0))
    target_qty = min(qty, max(min_remaining, target_qty_by_risk))
    qty_to_close = max(0.0, qty - target_qty)

    if qty_to_close < float(SWING_PARTIAL_PROFIT_MIN_QTY or 0.0) or qty_to_close >= qty:
        return {
            "triggered": False,
            "reason": "trim_qty_not_actionable",
            "qty": round(qty, 4),
            "target_qty": round(target_qty, 4),
            "qty_to_close": round(qty_to_close, 4),
        }

    return {
        "triggered": True,
        "reason": "oversized_winner_preservation_trim",
        "symbol": str(symbol or "").upper(),
        "qty": round(qty, 4),
        "qty_to_close": round(qty_to_close, 4),
        "target_remaining_qty": round(target_qty, 4),
        "entry_price": round(entry, 4),
        "current_price": round(float(px or 0.0), 4),
        "stop_price": round(stop, 4),
        "risk_per_share": round(risk_per_share, 4),
        "unrealized_pl": round(unrealized, 4),
        "current_risk_dollars": round(current_risk, 4),
        "target_risk_dollars": round(target_risk, 4),
        "configured_risk_dollars": round(configured_risk, 4),
    }

def _p389_legacy_oversized_position_normalization_plan(symbol: str, plan: dict, px: float) -> dict:
    if not bool(SWING_LEGACY_OVERSIZED_NORMALIZATION_ENABLED):
        return {"triggered": False, "reason": "disabled"}
    if bool((plan or {}).get("legacy_oversized_normalization_taken")):
        return {"triggered": False, "reason": "already_taken"}

    sizing_contract = str((plan or {}).get("sizing_contract") or "").strip()
    true_risk = (plan or {}).get("true_dollar_risk_sizing")
    if sizing_contract == "true_dollar_risk_from_active_stop" and isinstance(true_risk, dict) and true_risk:
        return {"triggered": False, "reason": "not_legacy_position"}

    side = str((plan or {}).get("side") or "buy").lower()
    if side != "buy":
        return {"triggered": False, "reason": "not_long"}

    qty = abs(_safe_float((plan or {}).get("filled_qty") or (plan or {}).get("qty") or 0.0))
    entry = _safe_float((plan or {}).get("entry_price") or (plan or {}).get("avg_fill_price") or 0.0)
    stop = _safe_float((plan or {}).get("stop_price") or (plan or {}).get("initial_stop_price") or 0.0)

    if qty <= 0 or entry <= 0 or stop <= 0:
        return {"triggered": False, "reason": "missing_qty_entry_or_stop"}

    risk_per_share = max(0.0, entry - stop)
    if risk_per_share <= 0:
        return {"triggered": False, "reason": "invalid_risk_per_share"}

    unrealized = (float(px or 0.0) - entry) * qty
    min_unrealized = float(SWING_LEGACY_OVERSIZED_NORMALIZATION_MIN_UNREALIZED_DOLLARS or 0.0)
    if unrealized < min_unrealized:
        return {
            "triggered": False,
            "reason": "legacy_oversized_profit_below_threshold",
            "unrealized_pl": round(unrealized, 4),
            "min_unrealized_dollars": round(min_unrealized, 4),
        }

    configured_risk = max(0.0, float(RISK_DOLLARS or 0.0))
    advisory_threshold = configured_risk * max(0.0, float(SWING_OVERSIZED_POSITION_ADVISORY_MULTIPLE or 0.0))
    current_risk = qty * risk_per_share

    if configured_risk <= 0 or current_risk <= advisory_threshold:
        return {
            "triggered": False,
            "reason": "not_oversized_vs_config",
            "current_risk_dollars": round(current_risk, 4),
            "advisory_threshold_dollars": round(advisory_threshold, 4),
        }

    target_risk = configured_risk * max(
        0.0,
        float(SWING_LEGACY_OVERSIZED_NORMALIZATION_REDUCE_TO_RISK_MULTIPLE or 0.0),
    )
    min_remaining = max(0.0, float(SWING_LEGACY_OVERSIZED_NORMALIZATION_MIN_REMAINING_QTY or 0.0))
    target_qty_by_risk = target_risk / risk_per_share if risk_per_share > 0 else qty
    target_qty = min(qty, max(min_remaining, target_qty_by_risk))
    qty_to_close = max(0.0, qty - target_qty)

    if qty_to_close < float(SWING_PARTIAL_PROFIT_MIN_QTY or 0.0) or qty_to_close >= qty:
        return {
            "triggered": False,
            "reason": "legacy_trim_qty_not_actionable",
            "qty": round(qty, 4),
            "target_qty": round(target_qty, 4),
            "qty_to_close": round(qty_to_close, 4),
        }

    return {
        "triggered": True,
        "reason": "legacy_oversized_position_normalization_trim",
        "symbol": str(symbol or "").upper(),
        "qty": round(qty, 4),
        "qty_to_close": round(qty_to_close, 4),
        "target_remaining_qty": round(target_qty, 4),
        "entry_price": round(entry, 4),
        "current_price": round(float(px or 0.0), 4),
        "stop_price": round(stop, 4),
        "risk_per_share": round(risk_per_share, 4),
        "unrealized_pl": round(unrealized, 4),
        "current_risk_dollars": round(current_risk, 4),
        "target_risk_dollars": round(target_risk, 4),
        "configured_risk_dollars": round(configured_risk, 4),
        "legacy_contract_backfill": {
            "sizing_contract": "legacy_position_normalized_to_true_dollar_risk",
            "normalization_patch": PATCH_VERSION,
        },
    }

def _calc_swing_dynamic_levels(symbol: str, plan: dict, px: float) -> dict:
    out = {
        "updates": {},
        "flags": [],
        "stall_exit": False,
        "stall_r": 0.0,
        "partial_profit_ready": False,
        "partial_profit_qty": 0.0,
        "oversized_winner_preservation_ready": False,
        "oversized_winner_preservation_qty": 0.0,
        "oversized_winner_preservation": {},
        "legacy_oversized_normalization_ready": False,
        "legacy_oversized_normalization_qty": 0.0,
        "legacy_oversized_normalization": {},
        "time_exit_grace": False,
    }
    if STRATEGY_MODE != "swing":
        return out
    side = str((plan or {}).get("side") or "buy").lower()
    if side != "buy":
        return out

    entry = _safe_float((plan or {}).get("entry_price") or 0.0)
    current_stop = _safe_float((plan or {}).get("stop_price") or 0.0)
    current_profit_lock = _safe_float((plan or {}).get("profit_lock_price") or 0.0)
    risk = _plan_risk_per_share(plan or {})
    if entry <= 0 or risk <= 0:
        return out

    qty_now = _p445_plan_available_qty(plan or {})
    out["effective_qty"] = round(qty_now, 4)
    out["effective_qty_source"] = _p445_qty_source(plan or {})

    unrealized_r = _swing_unrealized_r(plan or {}, float(px))
    out["stall_r"] = round(unrealized_r, 4)

    breakout_giveback = _p378_daily_breakout_profit_giveback_state(symbol, plan, float(px))
    out["daily_breakout_profit_giveback"] = breakout_giveback
    if breakout_giveback.get("updates"):
        out["updates"].update(dict(breakout_giveback.get("updates") or {}))
    if breakout_giveback.get("profit_lock_armed"):
        out["flags"].append("daily_breakout_profit_lock_armed")
    if breakout_giveback.get("triggered"):
        out["daily_breakout_profit_giveback_exit"] = True
        out["flags"].append("daily_breakout_profit_giveback_preservation_exit")

    failed_followthrough = _p380_daily_breakout_failed_followthrough_state(symbol, plan, float(px))
    out["daily_breakout_failed_followthrough"] = failed_followthrough
    if failed_followthrough.get("triggered"):
        out["daily_breakout_failed_followthrough_exit"] = True
        out["flags"].append("daily_breakout_failed_followthrough_exit")

    proposed_stop = current_stop
    proposed_profit_lock = current_profit_lock
    if _safe_float(out.get("updates", {}).get("profit_lock_price") or 0.0, 0.0) > proposed_profit_lock:
        proposed_profit_lock = _safe_float(out.get("updates", {}).get("profit_lock_price"), proposed_profit_lock)
    legacy_oversized = _p389_legacy_oversized_position_normalization_plan(symbol, plan, float(px))
    out["legacy_oversized_normalization"] = dict(legacy_oversized)
    if bool(legacy_oversized.get("triggered")):
        out["legacy_oversized_normalization_ready"] = True
        out["legacy_oversized_normalization_qty"] = float(legacy_oversized.get("qty_to_close") or 0.0)
        out["flags"].append("legacy_oversized_normalization_ready")
        out["updates"]["break_even_armed"] = True
        proposed_profit_lock = max(proposed_profit_lock, entry)

    oversized_winner = _p388_oversized_winner_preservation_plan(symbol, plan, float(px))
    out["oversized_winner_preservation"] = dict(oversized_winner)
    if bool(oversized_winner.get("triggered")):
        out["oversized_winner_preservation_ready"] = True
        out["oversized_winner_preservation_qty"] = float(oversized_winner.get("qty_to_close") or 0.0)
        out["flags"].append("oversized_winner_preservation_ready")
        out["updates"]["break_even_armed"] = True
        proposed_profit_lock = max(proposed_profit_lock, entry)

    partial_taken = bool((plan or {}).get("partial_profit_taken"))

    if SWING_PARTIAL_PROFIT_ENABLED and (not partial_taken) and unrealized_r >= float(SWING_PARTIAL_PROFIT_R):
        fraction = min(max(float(SWING_PARTIAL_PROFIT_FRACTION), 0.05), 0.95)
        qty_to_close = _normalize_close_qty(qty_now * fraction)
        if qty_to_close >= float(SWING_PARTIAL_PROFIT_MIN_QTY) and qty_to_close < qty_now:
            out["partial_profit_ready"] = True
            out["partial_profit_qty"] = qty_to_close
            out["partial_profit_reason"] = "partial_profit"
            out["flags"].append("partial_profit_ready")

    breakout_bias = _p444_breakout_partial_profit_bias_state(symbol, plan, px, out)
    out["breakout_partial_profit_bias"] = breakout_bias
    if breakout_bias.get("applies"):
        out["partial_profit_ready"] = True
        out["partial_profit_qty"] = breakout_bias.get("qty_to_close")
        out["partial_profit_reason"] = "breakout_partial_profit_bias"
        out["flags"].append("breakout_partial_profit_bias_ready")
        out["updates"]["break_even_armed"] = True
        proposed_profit_lock = max(proposed_profit_lock, entry)

    if SWING_ENABLE_BREAK_EVEN_STOP and unrealized_r >= float(SWING_BREAK_EVEN_R):
        out["updates"]["break_even_armed"] = True
        proposed_profit_lock = max(proposed_profit_lock, entry)
        out["flags"].append("break_even_armed")

    if SWING_ENABLE_TRAILING_STOP and unrealized_r >= float(SWING_TRAIL_AFTER_R):
        lookback = max(2, int(SWING_TRAIL_LOOKBACK_DAYS))
        bars = fetch_daily_bars_multi([symbol], lookback_days=max(lookback + 10, 20)).get(symbol, [])
        if len(bars) >= lookback:
            lows = [_safe_float(b.get("low") or 0.0) for b in bars[-lookback:]]
            trail_stop = max(lows) if lows else 0.0
            if trail_stop > 0:
                if trail_stop > entry:
                    proposed_profit_lock = max(proposed_profit_lock, trail_stop)
                    out["flags"].append("profit_lock_armed")
                else:
                    proposed_stop = max(proposed_stop, trail_stop)
                    out["flags"].append("trailing_stop_armed")

    hold_days = plan_days_held(plan or {})
    max_hold_days = int((plan or {}).get("max_hold_days") or SWING_MAX_HOLD_DAYS or 0)
    if max_hold_days > 0 and hold_days >= max_hold_days and unrealized_r >= float(SWING_TIME_EXIT_GRACE_R) and hold_days < (max_hold_days + max(int(SWING_TIME_EXIT_GRACE_DAYS), 0)):
        out["time_exit_grace"] = True
        out["updates"]["time_exit_grace_active"] = True
        out["flags"].append("time_exit_grace")
        proposed_profit_lock = max(proposed_profit_lock, entry)

    proposed = dict(plan or {})
    proposed["stop_price"] = round(proposed_stop, 4)
    if proposed_profit_lock > 0:
        proposed["profit_lock_price"] = round(proposed_profit_lock, 4)
    sanity = _normalize_long_exit_plan(proposed, float(px))
    if sanity.get("flags"):
        out["flags"].extend([f for f in sanity.get("flags", []) if f not in out["flags"]])

    sane_stop = _safe_float(proposed.get("stop_price") or 0.0)
    sane_profit_lock = _safe_float(proposed.get("profit_lock_price") or 0.0)
    if sane_stop > current_stop + 1e-9 or (current_stop > 0 and sane_stop < current_stop - 1e-9 and sane_stop <= entry + 1e-9):
        out["updates"]["stop_price"] = round(sane_stop, 4)
    if sane_profit_lock > current_profit_lock + 1e-9:
        out["updates"]["profit_lock_price"] = round(sane_profit_lock, 4)

    stall_guard_days = max(0, int(SWING_STALL_LOSS_GUARD_DAYS or 0))
    stall_max_loss_r = float(SWING_STALL_MAX_LOSS_R or 0.0)
    stall_containment = _p286_target_path_stall_containment(plan, hold_days, unrealized_r)
    out["target_path_stall_containment"] = dict(stall_containment)
    effective_stall_guard_days = int(stall_containment.get("effective_guard_days") or stall_guard_days)
    effective_stall_max_loss_r = float(stall_containment.get("effective_max_loss_r") or stall_max_loss_r)

    if bool(stall_containment.get("contained")):
        out["flags"].append("target_path_stall_loss_guard_contained")

    if (
        bool(SWING_STALL_LOSS_GUARD_ENABLED)
        and effective_stall_guard_days > 0
        and hold_days >= effective_stall_guard_days
        and effective_stall_max_loss_r < 0.0
        and unrealized_r <= effective_stall_max_loss_r
        and not out.get("time_exit_grace")
    ):
        out["stall_exit"] = True
        out["stall_loss_guard"] = True
        out["flags"].append("stall_loss_guard_ready")

        reduce_first = _p444_breakout_stall_loss_reduce_first_state(symbol, plan, px, out)
        out["breakout_stall_loss_reduce_first"] = reduce_first
        if reduce_first.get("applies"):
            out["stall_exit"] = False
            out["stall_loss_guard"] = False
            out["partial_profit_ready"] = True
            out["partial_profit_qty"] = reduce_first.get("qty_to_close")
            out["partial_profit_reason"] = "breakout_stall_loss_reduce_first"
            out["flags"].append("breakout_stall_loss_reduce_first_ready")
    
    if SWING_STALL_EXIT_DAYS > 0 and hold_days >= int(SWING_STALL_EXIT_DAYS) and unrealized_r < float(SWING_STALL_MIN_R) and not out.get("time_exit_grace"):
        out["stall_exit"] = True
        out["flags"].append("stall_exit_ready")
    return out

def _pending_order_entry_freeze_snapshot(symbol: str | None = None) -> dict:
    scope = str(PENDING_ORDER_ENTRY_FREEZE_SCOPE or "symbol").strip().lower()
    if scope not in {"symbol", "global"}:
        scope = "symbol"
    if not PENDING_ORDER_ENTRY_FREEZE_ENABLE:
        return {"active": False, "enabled": False, "scope": scope, "open_order_count": 0, "open_order_symbols": [], "open_orders": []}
    orders = list_open_orders_safe()
    requested_symbol = str(symbol or "").upper().strip()
    symbols = sorted({str(o.get("symbol") or "").upper() for o in orders if str(o.get("symbol") or "").strip()})
    relevant_orders = list(orders)
    if scope == "symbol" and requested_symbol:
        relevant_orders = [o for o in orders if str(o.get("symbol") or "").upper().strip() == requested_symbol]
    relevant_symbols = sorted({str(o.get("symbol") or "").upper() for o in relevant_orders if str(o.get("symbol") or "").strip()})
    return {
        "active": bool(relevant_orders),
        "enabled": True,
        "scope": scope,
        "requested_symbol": requested_symbol,
        "open_order_count": len(orders),
        "open_order_symbols": symbols,
        "relevant_open_order_count": len(relevant_orders),
        "relevant_open_order_symbols": relevant_symbols,
        "open_orders": orders,
        "relevant_open_orders": relevant_orders,
    }

def _p328_limit_entry_preview(symbol: str, side: str, snapshot: dict | None, meta: dict | None = None) -> dict:
    snap = dict(snapshot or {})
    m = dict(meta or {})
    avg_dollar_volume = (
        snap.get("avg_dollar_volume_20d")
        or snap.get("avg_dollar_volume")
        or m.get("avg_dollar_volume_20d")
        or m.get("avg_dollar_volume")
        or m.get("dollar_volume")
    )
    if avg_dollar_volume is not None:
        snap["avg_dollar_volume_20d"] = avg_dollar_volume
    return swing_exec_limit_entry_preview(
        symbol,
        side,
        snap,
        config=_p335_swing_limit_entry_config(),
    )


def _p353_requires_protective_limit_entry(source: str, signal: str, meta: dict | None = None) -> bool:
    if not bool(SWING_PRODUCTION_REQUIRE_PROTECTIVE_LIMIT_ENTRY):
        return False
    if str(STRATEGY_MODE or "").strip().lower() != "swing":
        return False

    m = dict(meta or {})
    src = str(source or "").strip().lower()
    selected_source = str(m.get("selected_source") or "").strip().lower()
    sig = str(signal or "").strip().lower()

    production_sources = {
        "worker_scan",
        "swing_production_reset",
        "swing_fast_scan",
        "scan",
    }
    return bool(
        src in production_sources
        or selected_source in production_sources
        or bool(m.get("selected_by_scanner"))
        or sig.startswith("daily_")
    )

def execute_entry_signal(symbol: str, side: str, signal: str, source: str, meta: dict | None = None, auth_payload: dict | None = None) -> dict:
    """Shared entry execution path for scanner + webhook."""
    meta = meta or {}
    auth_payload = auth_payload or {}
    selected_source = str(meta.get("selected_source") or "").strip()
    source = str(source or "").strip() or "unknown"
    if selected_source and source == "worker_scan" and selected_source != source:
        source = selected_source
    symbol = (symbol or "").upper().strip()
    side = (side or "").lower().strip()
    signal = (signal or "").strip()

    if not symbol:
        return {"ok": False, "rejected": True, "reason": "symbol_required"}
    if side not in ("buy", "sell"):
        return {"ok": False, "rejected": True, "reason": "invalid_side"}
    if ALLOWED_SYMBOLS and symbol not in ALLOWED_SYMBOLS:
        return {"ok": True, "ignored": True, "reason": "symbol_not_allowed", "symbol": symbol, "signal": signal}

    if KILL_SWITCH:
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="rejected", reason="kill_switch_enabled", meta=meta)
        return {"ok": False, "rejected": True, "reason": "kill_switch_enabled"}
    if daily_halt_active():
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="rejected", reason="daily_halt_active", meta=meta)
        return {"ok": False, "rejected": True, "reason": "daily_halt_active"}
    if daily_stop_hit():
        activate_daily_halt("daily_stop_hit")
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="rejected", reason="daily_stop_hit", meta=meta)
        return {"ok": False, "rejected": True, "reason": "daily_stop_hit"}
    realized_halt = _p229_realized_closed_trade_loss_halt()
    if bool(realized_halt.get("active")):
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="rejected", reason=realized_halt.get("reason") or "realized_closed_trade_loss_halt", meta={**(meta or {}), "realized_closed_trade_loss_halt": realized_halt})
        return {"ok": False, "rejected": True, "reason": realized_halt.get("reason") or "realized_closed_trade_loss_halt", "realized_closed_trade_loss_halt": realized_halt}

    meta = dict(meta or {})
    strategy_name = str(
        meta.get("strategy_name")
        or meta.get("strategy")
        or signal
        or ""
    ).strip().lower()

    if STRATEGY_MODE == "swing":
        drawdown_block = _p261_strategy_entry_block(strategy_name)
        if drawdown_block.get("blocked"):
            record_decision(
                "ENTRY",
                source,
                symbol,
                side=side,
                signal=signal,
                action="rejected",
                reason="swing_post_change_drawdown_circuit",
                meta={
                    **meta,
                    "swing_post_change_drawdown_circuit": drawdown_block,
                },
            )
            return {
                "ok": True,
                "ignored": True,
                "reason": "swing_post_change_drawdown_circuit",
                "symbol": symbol,
                "signal": signal,
                "strategy_name": strategy_name,
                "drawdown_circuit": drawdown_block,
            }
    market_clock = _market_clock_snapshot()
    if ONLY_MARKET_HOURS and not bool(market_clock.get("is_open")):
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason="outside_market_hours", meta={"market_clock": market_clock, **(meta or {})})
        return {"ok": True, "ignored": True, "reason": "outside_market_hours", "symbol": symbol, "signal": signal, "market_clock": market_clock}

    pending_freeze = _pending_order_entry_freeze_snapshot(symbol)
    if bool(pending_freeze.get("active")):
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason="pending_order_entry_freeze", meta={"pending_order_entry_freeze": pending_freeze, **(meta or {})})
        return {"ok": True, "ignored": True, "reason": "pending_order_entry_freeze", "symbol": symbol, "signal": signal, "pending_order_entry_freeze": pending_freeze}

    if side == "sell" and not ALLOW_SHORT:
        qty_signed, _pos_side = get_position(symbol)
        if qty_signed > 0:
            out = close_position(symbol)
            if symbol in TRADE_PLAN:
                TRADE_PLAN[symbol]["active"] = False
            return {"ok": True, "closed": True, "reason": "shorts_disabled_closed_long", "symbol": symbol, "signal": signal, **out}
        return {"ok": True, "ignored": True, "reason": "shorts_disabled", "symbol": symbol, "signal": signal}

    if not NEW_ENTRIES_ENABLED:
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason="new_entries_disabled", meta=meta)
        return {"ok": True, "ignored": True, "reason": "new_entries_disabled", "symbol": symbol, "signal": signal}
    
    if source == "webhook" and ENABLE_IDEMPOTENCY:
        dk = dedup_key(auth_payload)
        last = DEDUP_CACHE.get(dk, 0)
        now = utc_ts()
        if last and (now - last) < DEDUP_WINDOW_SEC:
            record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason="dedup", meta=meta)
            return {"ok": True, "ignored": True, "reason": "dedup", "symbol": symbol, "signal": signal}
        DEDUP_CACHE[dk] = now

    if TRADE_PLAN.get(symbol, {}).get("active"):
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason="plan_active", meta=meta)
        return {"ok": True, "ignored": True, "reason": "plan_active", "symbol": symbol, "signal": signal}

    qty_signed, pos_side = get_position(symbol)
    if qty_signed != 0:
        desired_side = "long" if side == "buy" else "short"
        if desired_side == pos_side:
            record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason=f"position_already_open:{pos_side}", meta=meta)
            return {"ok": True, "ignored": True, "reason": f"position_already_open:{pos_side}", "symbol": symbol, "signal": signal}

        close_out = close_position(symbol, reason="reverse_not_allowed", source=source)
        if symbol in TRADE_PLAN:
            TRADE_PLAN[symbol]["active"] = False

        if not close_out.get("closed"):
            record_decision("ENTRY", source, symbol, side=side, signal=signal, action="rejected", reason="reverse_close_failed", meta=meta)
            return {"ok": False, "rejected": True, "reason": "reverse_close_failed", "symbol": symbol, "signal": signal, **close_out}

        if not ALLOW_REVERSAL:
            record_decision("ENTRY", source, symbol, side=side, signal=signal, action="closed_opposite_position", reason="allow_reversal_false", meta=meta)
            return {"ok": True, "action": "closed_opposite_position", "symbol": symbol, "signal": signal, **close_out}

    if max_open_positions_reached():
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason="max_open_positions_reached", meta=meta)
        return {"ok": True, "ignored": True, "reason": "max_open_positions_reached", "symbol": symbol, "signal": signal, "max_open_positions": MAX_OPEN_POSITIONS}

    if not take_symbol_lock(symbol, SYMBOL_LOCK_SEC):
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason="symbol_locked", meta=meta)
        return {"ok": True, "ignored": True, "reason": "symbol_locked", "symbol": symbol, "signal": signal}

    effective_dry_run = effective_entry_dry_run(source)
    payload = None

    try:
        snapshot = get_latest_quote_snapshot(symbol)
        base_price = snapshot.get("price")
        if base_price is None or float(base_price) <= 0:
            raise ValueError("latest_price_missing")
        if ENTRY_REQUIRE_QUOTE and not snapshot.get("quote_ok"):
            record_decision("ENTRY", source, symbol, side=side, signal=signal, action="rejected", reason="quote_missing", meta={"snapshot": snapshot, "payload": payload, **(meta or {})})
            soften_symbol_lock(symbol, 5)
            return {"ok": False, "rejected": True, "reason": "quote_missing", "symbol": symbol, "signal": signal, "snapshot": snapshot}
        if ENTRY_REQUIRE_FRESH_QUOTE and not snapshot.get("fresh"):
            fallback_snapshot, bar_fallback_debug = _try_build_snapshot_from_recent_1m_bar(symbol, max_age_sec=ENTRY_BAR_FALLBACK_MAX_AGE_SEC)
            if fallback_snapshot:
                stale_snapshot = dict(snapshot or {})
                fallback_snapshot["stale_snapshot"] = stale_snapshot
                qd = fallback_snapshot.setdefault("quote_debug", {})
                qd["fallback_activation_reason"] = "stale_primary_quote"
                qd["bar_fallback_attempted"] = bar_fallback_debug
                snapshot = fallback_snapshot
            else:
                candidate_fallback_snapshot, candidate_fallback_debug = _try_build_snapshot_from_candidate_meta(symbol, meta=meta, max_age_sec=max(120.0, ENTRY_BAR_FALLBACK_MAX_AGE_SEC))
                if candidate_fallback_snapshot:
                    stale_snapshot = dict(snapshot or {})
                    candidate_fallback_snapshot["stale_snapshot"] = stale_snapshot
                    qd = candidate_fallback_snapshot.setdefault("quote_debug", {})
                    qd["fallback_activation_reason"] = "stale_primary_quote"
                    qd["bar_fallback_attempted"] = bar_fallback_debug
                    qd["candidate_fallback_attempted"] = candidate_fallback_debug
                    snapshot = candidate_fallback_snapshot
                else:
                    qd = snapshot.setdefault("quote_debug", {})
                    qd["bar_fallback_attempted"] = bar_fallback_debug
                    qd["candidate_fallback_attempted"] = candidate_fallback_debug
                    record_decision("ENTRY", source, symbol, side=side, signal=signal, action="rejected", reason="price_stale", meta={"snapshot": snapshot, "payload": payload, **(meta or {})})
                    soften_symbol_lock(symbol, 5)
                    return {"ok": False, "rejected": True, "reason": "price_stale", "symbol": symbol, "signal": signal, "snapshot": snapshot}
        p328_limit_entry = None
        spread_pct = snapshot.get("spread_pct")
        if spread_pct is not None and float(spread_pct) > float(ENTRY_MAX_SPREAD_PCT):
            spread_override = _entry_spread_override_decision(snapshot, meta=meta)
            limit_preview = _p328_limit_entry_preview(symbol, side, snapshot, meta=meta)
            snapshot["spread_override"] = spread_override
            snapshot["limit_entry_preview"] = limit_preview

            if limit_preview.get("allowed") and (
                not spread_override.get("allowed")
                or bool(SWING_LIMIT_ENTRY_FOR_SPREAD_OVERRIDE_ENABLED)
            ):
                p328_limit_entry = limit_preview
                limit_reason = (
                    "protective_limit_entry_for_spread_override"
                    if spread_override.get("allowed")
                    else "limit_entry_for_spread_block"
                )
                record_decision(
                    "ENTRY",
                    source,
                    symbol,
                    side=side,
                    signal=signal,
                    action="allowed",
                    reason=limit_reason,
                    meta={
                        "snapshot": snapshot,
                        "spread_override": spread_override,
                        "limit_entry": limit_preview,
                        **(meta or {}),
                    },
                )
            elif not spread_override.get("allowed"):
                record_decision(
                    "ENTRY",
                    source,
                    symbol,
                    side=side,
                    signal=signal,
                    action="rejected",
                    reason="spread_too_wide",
                    meta={
                        "snapshot": snapshot,
                        "spread_override": spread_override,
                        "limit_entry": limit_preview,
                        **(meta or {}),
                    },
                )
                soften_symbol_lock(symbol, 5)
                return {
                    "ok": False,
                    "rejected": True,
                    "reason": "spread_too_wide",
                    "symbol": symbol,
                    "signal": signal,
                    "snapshot": snapshot,
                    "spread_override": spread_override,
                    "limit_entry": limit_preview,
                }
            else:
                record_decision(
                    "ENTRY",
                    source,
                    symbol,
                    side=side,
                    signal=signal,
                    action="allowed",
                    reason="spread_override_allowed_without_limit_entry",
                    meta={
                        "snapshot": snapshot,
                        "spread_override": spread_override,
                        "limit_entry": limit_preview,
                        **(meta or {}),
                    },
                )

        if p328_limit_entry is None and _p353_requires_protective_limit_entry(source, signal, meta=meta):
            forced_limit_preview = _p328_limit_entry_preview(symbol, side, snapshot, meta=meta)
            snapshot["production_limit_entry_required"] = True
            snapshot["production_limit_entry_preview"] = forced_limit_preview

            if forced_limit_preview.get("allowed"):
                p328_limit_entry = forced_limit_preview
                record_decision(
                    "ENTRY",
                    source,
                    symbol,
                    side=side,
                    signal=signal,
                    action="allowed",
                    reason="production_protective_limit_entry_required",
                    meta={
                        "snapshot": snapshot,
                        "limit_entry": forced_limit_preview,
                        **(meta or {}),
                    },
                )
            else:
                record_decision(
                    "ENTRY",
                    source,
                    symbol,
                    side=side,
                    signal=signal,
                    action="rejected",
                    reason="limit_entry_unavailable",
                    meta={
                        "snapshot": snapshot,
                        "limit_entry": forced_limit_preview,
                        "production_limit_required": True,
                        **(meta or {}),
                    },
                )
                soften_symbol_lock(symbol, 5)
                return {
                    "ok": False,
                    "rejected": True,
                    "reason": "limit_entry_unavailable",
                    "symbol": symbol,
                    "signal": signal,
                    "snapshot": snapshot,
                    "limit_entry": forced_limit_preview,
                    "production_limit_required": True,
                }

        qty_signed_post_lock, pos_side_post_lock = get_position(symbol)
        if qty_signed_post_lock != 0:
            desired_side = "long" if side == "buy" else "short"
            reason = f"position_open_after_lock:{pos_side_post_lock}"
            record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason=reason, meta={"snapshot": snapshot, "submit_transport": _order_attr(order, "_submit_transport", "sdk") if "order" in locals() else None, **(meta or {})})
            return {"ok": True, "ignored": True, "reason": reason, "symbol": symbol, "signal": signal, "snapshot": snapshot}
        if TRADE_PLAN.get(symbol, {}).get("active"):
            record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason="plan_active_after_lock", meta={"snapshot": snapshot, **(meta or {})})
            return {"ok": True, "ignored": True, "reason": "plan_active_after_lock", "symbol": symbol, "signal": signal, "snapshot": snapshot}

        entry_level_preview = _p388_entry_level_preview(side, float(base_price), meta=meta)
        meta.setdefault("stop_price", entry_level_preview.get("stop_price"))
        meta.setdefault("take_price", entry_level_preview.get("take_price"))
        meta.setdefault("target_price", entry_level_preview.get("take_price"))
        meta["p388_true_dollar_risk_sizing"] = {
            "enabled": bool(SWING_TRUE_DOLLAR_RISK_SIZING_ENABLED),
            "configured_risk_dollars": float(RISK_DOLLARS or 0.0),
            **entry_level_preview,
        }

        risk_qty = compute_qty(float(base_price), side=side, meta=meta) if side == "buy" else round(abs(qty_signed), 2)
        qty = risk_qty
        affordability = None
        if side == "buy":
            affordability = clip_qty_for_affordability(float(base_price), float(risk_qty))
            qty = float(affordability.get("submitted_qty") or 0.0)
            if affordability.get("reason"):
                reason = str(affordability.get("reason"))
                record_decision("ENTRY", source, symbol, side=side, signal=signal, action="rejected", reason=reason, qty=risk_qty, meta={"snapshot": snapshot, "affordability": affordability, **(meta or {})})
                soften_symbol_lock(symbol, 5)
                return {"ok": False, "rejected": True, "reason": reason, "symbol": symbol, "signal": signal, "snapshot": snapshot, "affordability": affordability}
        if qty <= 0:
            raise ValueError("qty_zero")

        payload = {
            "symbol": symbol,
            "side": side,
            "qty": qty,
            "risk_qty": risk_qty,
            "affordability": affordability,
            "base_price": round(float(base_price), 2),
            "signal": signal,
            "paper": APCA_PAPER,
            "dry_run": effective_dry_run,
            "source": source,
            "effective_submit_source": source,
            "selected_source": (meta or {}).get("selected_source") or source,
            "snapshot": snapshot,
            "limit_entry_preview": p328_limit_entry or {},
        }

        if effective_dry_run:
            existing_open_order = find_open_order_for_symbol(symbol)
            if existing_open_order:
                adopted = _adopt_open_broker_order_as_plan(symbol, existing_open_order, source=str((meta or {}).get("selected_source") or source or "reconcile"), signal=signal, base_price=float(base_price), meta=meta)
                record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason="broker_backed_execution_exists", qty=qty, meta={"snapshot": snapshot, "open_order": existing_open_order, **(meta or {})})
                return {"ok": True, "ignored": True, "reason": "broker_backed_execution_exists", "symbol": symbol, "signal": signal, "open_order": existing_open_order, "plan": adopted}
            existing_plan = TRADE_PLAN.get(symbol) or {}
            if _plan_is_pending_entry(existing_plan):
                record_decision("ENTRY", source, symbol, side=side, signal=signal, action="ignored", reason="pending_entry_plan_preserved", qty=qty, meta={"snapshot": snapshot, **(meta or {})})
                return {"ok": True, "ignored": True, "reason": "pending_entry_plan_preserved", "symbol": symbol, "signal": signal, "plan": existing_plan}
            plan = build_trade_plan(symbol, side, qty, float(base_price), signal, meta=meta)
            plan["source"] = source
            plan["requested_qty"] = float(risk_qty)
            plan["submitted_qty"] = float(qty)
            plan["filled_qty"] = float(qty)
            plan["avg_fill_price"] = float(base_price)
            plan["affordability"] = affordability or {}
            TRADE_PLAN[symbol] = plan
            _ensure_execution_lifecycle_plan(symbol, plan)
            _transition_execution_lifecycle(plan, symbol, "planned", reason="entry_dry_run_plan", details={"source": source, "signal": signal, "qty": qty}, allow_illegal=True)
            persist_positions_snapshot(reason="entry_dry_run_plan", extra={"symbol": symbol, "source": source, "signal": signal})
            record_decision("ENTRY", source, symbol, side=side, signal=signal, action="dry_run_plan_created", reason="", qty=qty, meta={"snapshot": snapshot, **(meta or {})})
            try:
                _record_paper_lifecycle("entry", "planned", symbol=symbol, details={"source": source, "signal": signal, "qty": qty, "dry_run": True, "base_price": round(float(base_price), 4)})
            except Exception:
                pass
            return {"ok": True, "submitted": False, "dry_run": True, "order": payload, "plan": plan}

        submit_order_type = "market"
        submit_price = float(base_price)

        if isinstance(p328_limit_entry, dict) and p328_limit_entry.get("allowed"):
            submit_order_type = "limit"
            submit_price = float(p328_limit_entry.get("limit_price") or base_price)
            if not SWING_LIMIT_ENTRY_FRACTIONAL_ENABLED:
                qty = float(math.floor(float(qty)))
                if qty <= 0:
                    record_decision("ENTRY", source, symbol, side=side, signal=signal, action="rejected", reason="limit_qty_zero_after_whole_share_rounding", qty=qty, meta={"snapshot": snapshot, "limit_entry": p328_limit_entry, **(meta or {})})
                    soften_symbol_lock(symbol, 5)
                    return {"ok": False, "rejected": True, "reason": "limit_qty_zero_after_whole_share_rounding", "symbol": symbol, "signal": signal, "snapshot": snapshot, "limit_entry": p328_limit_entry}

            _p337_record_limit_submit_evidence(
                symbol=symbol,
                side=side,
                signal=signal,
                source=source,
                stage="attempted",
                order_type="limit",
                qty=qty,
                limit_price=submit_price,
                limit_entry=p328_limit_entry,
                snapshot=snapshot,
            )
            order = submit_limit_order(symbol, side, qty, submit_price)
        else:
            order = submit_market_order(symbol, side, qty)

        plan = build_trade_plan(symbol, side, qty, submit_price, signal, meta=meta)
        plan["source"] = source
        plan["order_id"] = str(_order_attr(order, "id", ""))
        plan["submitted_at"] = now_ny().isoformat()
        plan["requested_qty"] = float(risk_qty)
        plan["submitted_qty"] = float(qty)
        plan["filled_qty"] = 0.0
        plan["avg_fill_price"] = float(base_price)
        plan["order_status"] = "submitted"
        plan["order_type"] = submit_order_type
        plan["limit_price"] = submit_price if submit_order_type == "limit" else None
        plan["limit_entry"] = p328_limit_entry or {}
        plan["affordability"] = affordability or {}
        p337_limit_submit_evidence = {}
        if submit_order_type == "limit":
            p337_limit_submit_evidence = _p337_record_limit_submit_evidence(
                symbol=symbol,
                side=side,
                signal=signal,
                source=source,
                stage="submitted",
                order_type=submit_order_type,
                qty=qty,
                limit_price=submit_price,
                order_id=str(_order_attr(order, "id", "")),
                client_order_id=str(_order_attr(order, "client_order_id", "")),
                limit_entry=p328_limit_entry,
                snapshot=snapshot,
                plan=plan,
            )
        TRADE_PLAN[symbol] = plan
        _ensure_execution_lifecycle_plan(symbol, plan)
        _transition_execution_lifecycle(
            plan,
            symbol,
            "submitted",
            reason="entry_submitted",
            details={
                "source": source,
                "signal": signal,
                "qty": qty,
                "order_id": str(_order_attr(order, "id", "")),
                "order_type": submit_order_type,
                "limit_price": submit_price if submit_order_type == "limit" else None,
                "protective_limit_submit_evidence": p337_limit_submit_evidence,
            },
            allow_illegal=True,
        )
        persist_positions_snapshot(reason="entry_submitted", extra={"symbol": symbol, "order_id": str(_order_attr(order, "id", "")), "source": source, "signal": signal})
        log("ORDER_SUBMITTED", symbol=symbol, side=side, qty=qty, order_id=str(_order_attr(order, "id", "")), signal=signal, source=source)
        record_decision("ENTRY", source, symbol, side=side, signal=signal, action="order_submitted", reason="", order_id=str(_order_attr(order, "id", "")), qty=qty, meta={"snapshot": snapshot, **(meta or {})})
        try:
            _record_paper_lifecycle(
                "entry",
                "submitted",
                symbol=symbol,
                details={
                    "source": source,
                    "signal": signal,
                    "qty": qty,
                    "order_id": str(_order_attr(order, "id", "")),
                    "order_type": submit_order_type,
                    "limit_price": submit_price if submit_order_type == "limit" else None,
                    "dry_run": False,
                },
            )
        except Exception:
            pass
        return {"ok": True, "submitted": True, "order_id": str(_order_attr(order, "id", "")), "order_type": submit_order_type, "limit_price": submit_price if submit_order_type == "limit" else None, "protective_limit_submit_evidence": p337_limit_submit_evidence, "order": payload, "plan": plan}
    except Exception as e:
        submit_error = str(e)
        rate_limited = _p352_is_alpaca_rate_limit_error(submit_error)
        evidence_stage = "rate_limited" if rate_limited else "rejected"

        if str(locals().get("submit_order_type") or "").lower() == "limit" or isinstance(locals().get("p328_limit_entry"), dict):
            try:
                _p337_record_limit_submit_evidence(
                    symbol=symbol,
                    side=side,
                    signal=signal,
                    source=source,
                    stage=evidence_stage,
                    order_type=str(locals().get("submit_order_type") or "limit"),
                    qty=locals().get("qty"),
                    limit_price=locals().get("submit_price"),
                    limit_entry=locals().get("p328_limit_entry") if isinstance(locals().get("p328_limit_entry"), dict) else {},
                    snapshot=locals().get("snapshot") if isinstance(locals().get("snapshot"), dict) else {},
                    plan=TRADE_PLAN.get(symbol) if isinstance(TRADE_PLAN.get(symbol), dict) else None,
                    error=submit_error,
                )
            except Exception:
                pass
        log("ORDER_REJECTED", symbol=symbol, side=side, err=submit_error, signal=signal, source=source)
        decision_reason = "alpaca_submit_rate_limited" if rate_limited else "alpaca_submit_failed"
        record_decision(
            "ENTRY",
            source,
            symbol,
            side=side,
            signal=signal,
            action="rejected",
            reason=decision_reason,
            err=submit_error,
            meta={**dict(meta or {}), "rate_limited": rate_limited, "retryable": rate_limited},
        )
        try:
            _record_paper_lifecycle("entry", "rejected", symbol=symbol, details={"source": source, "signal": signal, "reason": decision_reason, "error": submit_error, "rate_limited": rate_limited, "retryable": rate_limited})
        except Exception:
            pass
        try:
            stale_plan = TRADE_PLAN.get(symbol)
            if isinstance(stale_plan, dict):
                _ensure_execution_lifecycle_plan(symbol, stale_plan)
                _transition_execution_lifecycle(stale_plan, symbol, "rejected", reason=decision_reason, details={"source": source, "signal": signal, "error": submit_error, "rate_limited": rate_limited, "retryable": rate_limited}, allow_illegal=True)
        except Exception:
            pass
        soften_symbol_lock(symbol, 5)
        return {
            "ok": False,
            "rejected": True,
            "retryable": bool(rate_limited),
            "rate_limited": bool(rate_limited),
            "reason": f"{decision_reason}:{submit_error}",
            "symbol": symbol,
            "signal": signal,
            "affordability": affordability if "affordability" in locals() else None,
            "submit_diagnostics": {
                "error": submit_error,
                "rate_limited": bool(rate_limited),
                "retryable": bool(rate_limited),
                "snapshot_present": isinstance(locals().get("snapshot"), dict),
                "payload_present": isinstance(locals().get("payload"), dict),
                "base_price": (locals().get("payload") or {}).get("base_price") if isinstance(locals().get("payload"), dict) else None,
                "qty": (locals().get("payload") or {}).get("qty") if isinstance(locals().get("payload"), dict) else None,
                "side": side,
                "source": source,
                "effective_submit_source": source,
                "selected_source": (meta or {}).get("selected_source") or source,
            },
        }


def _p352_is_alpaca_rate_limit_error(err: object) -> bool:
    text = str(err or "").strip().lower()
    if not text:
        return False
    return (
        "429" in text
        or "too many requests" in text
        or "rate limit" in text
        or "rate_limit" in text
    )


def _p352_record_rate_limit_submit_recovery(symbol: str, side: str, signal: str, source: str, stage: str, **details) -> dict:
    row = {
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "ts_ny": now_ny().isoformat(),
        "patch_version": PATCH_VERSION,
        "symbol": str(symbol or "").strip().upper(),
        "side": str(side or "").strip().lower(),
        "signal": str(signal or ""),
        "source": str(source or ""),
        "stage": str(stage or ""),
        **dict(details or {}),
    }
    try:
        P352_RATE_LIMIT_SUBMIT_RECOVERY.append(row)
        del P352_RATE_LIMIT_SUBMIT_RECOVERY[:-50]
    except Exception:
        pass
    return row


def _p352_response_rate_limited(resp: dict | None) -> bool:
    r = dict(resp or {})
    return bool(
        r.get("rate_limited")
        or r.get("retryable")
        or _p352_is_alpaca_rate_limit_error(r.get("reason"))
        or _p352_is_alpaca_rate_limit_error((r.get("submit_diagnostics") or {}).get("error"))
    )

def _p398_submit_row_rate_limited(row: dict | None, submit_meta: dict | None = None, resp: dict | None = None) -> bool:
    r = dict(row or {})
    meta = dict(submit_meta or {})
    response = dict(resp or {})
    diagnostics = dict(r.get("submit_diagnostics") or response.get("submit_diagnostics") or {})
    state = str(r.get("submit_state") or meta.get("state") or "").strip().lower()
    return bool(
        state == "retryable_rate_limit"
        or bool(r.get("rate_limited"))
        or bool(r.get("retryable"))
        or bool(meta.get("rate_limited"))
        or bool(meta.get("retryable"))
        or bool(response.get("rate_limited"))
        or bool(response.get("retryable"))
        or _p352_is_alpaca_rate_limit_error(r.get("submit_reason"))
        or _p352_is_alpaca_rate_limit_error(r.get("reason"))
        or _p352_is_alpaca_rate_limit_error(meta.get("reason"))
        or _p352_is_alpaca_rate_limit_error(response.get("reason"))
        or _p352_is_alpaca_rate_limit_error(diagnostics.get("error"))
    )

def _p387_rate_limit_retry_key(symbol: str, signal: str | None = None) -> str:
    sym = str(symbol or "").strip().upper()
    sig = str(signal or "daily_breakout").strip().lower() or "daily_breakout"
    return f"{sym}|{sig}"


def _p387_prune_rate_limit_selected_submit_retry_queue() -> None:
    ttl = max(1, int(SWING_RATE_LIMIT_SELECTED_SUBMIT_RETRY_TTL_SEC or 900))
    now_ts = datetime.now(timezone.utc).timestamp()
    for key, row in list(P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE.items()):
        try:
            queued_ts = float(row.get("queued_utc_ts") or 0.0)
        except Exception:
            queued_ts = 0.0
        if queued_ts <= 0 or (now_ts - queued_ts) > ttl:
            P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE.pop(key, None)


def _p387_queue_rate_limited_selected_submit(candidate: dict | None, submit_row: dict | None) -> dict:
    if not bool(SWING_RATE_LIMIT_SELECTED_SUBMIT_RETRY_ENABLED):
        return {"queued": False, "reason": "rate_limit_selected_submit_retry_disabled"}

    c = dict(candidate or {})
    row = dict(submit_row or {})
    sym = str(c.get("symbol") or row.get("symbol") or "").strip().upper()
    sig = str(c.get("signal") or row.get("signal") or row.get("strategy") or "daily_breakout").strip() or "daily_breakout"
    side = str(c.get("side") or row.get("side") or "buy").strip().lower() or "buy"
    reason = str(row.get("submit_reason") or row.get("reason") or "").strip()

    if not sym:
        return {"queued": False, "reason": "missing_symbol"}
    if not _p398_submit_row_rate_limited(row):
        return {"queued": False, "reason": "not_rate_limited"}

    key = _p387_rate_limit_retry_key(sym, sig)
    prior = dict(P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE.get(key) or {})
    attempts = int(prior.get("attempts") or 0) + 1

    queued = {
        "key": key,
        "queued_utc": datetime.now(timezone.utc).isoformat(),
        "queued_ny": now_ny().isoformat(),
        "queued_utc_ts": datetime.now(timezone.utc).timestamp(),
        "patch_version": PATCH_VERSION,
        "symbol": sym,
        "side": side,
        "signal": sig,
        "source": str(c.get("submit_source") or c.get("source") or row.get("source") or "swing_production_reset"),
        "entry_type": str(c.get("entry_type") or row.get("entry_type") or "swing_production_contract"),
        "rank_score": _safe_float(c.get("rank_score") or row.get("rank_score") or 0.0),
        "signal_family": str(c.get("signal_family") or row.get("signal_family") or "primary"),
        "attempts": attempts,
        "first_reason": prior.get("first_reason") or reason,
        "last_reason": reason,
        "candidate": c,
        "submit_row": row,
    }
    P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE[key] = queued
    _p352_record_rate_limit_submit_recovery(
        sym,
        side,
        sig,
        queued.get("source"),
        "durable_retry_queued",
        key=key,
        attempts=attempts,
        reason=reason,
    )
    return {"queued": True, "key": key, "attempts": attempts, "reason": "rate_limited_selected_submit_queued"}


def _p387_pending_rate_limited_selected_submit_retry_candidates(max_items: int | None = None) -> list[dict]:
    if not bool(SWING_RATE_LIMIT_SELECTED_SUBMIT_RETRY_ENABLED):
        return []
    _p387_prune_rate_limit_selected_submit_retry_queue()
    lim = max(0, int(max_items if max_items is not None else SWING_RATE_LIMIT_SELECTED_SUBMIT_RETRY_MAX_PER_SCAN or 1))
    rows = sorted(
        [dict(row or {}) for row in P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE.values()],
        key=lambda row: float(row.get("queued_utc_ts") or 0.0),
    )
    out = []
    for row in rows[:lim]:
        candidate = dict(row.get("candidate") or {})
        candidate.update({
            "symbol": row.get("symbol"),
            "side": row.get("side") or candidate.get("side") or "buy",
            "signal": row.get("signal") or candidate.get("signal") or "daily_breakout",
            "rank_score": row.get("rank_score") or candidate.get("rank_score"),
            "signal_family": row.get("signal_family") or candidate.get("signal_family") or "primary",
            "source": row.get("source") or candidate.get("source") or "swing_production_reset",
            "submit_source": row.get("source") or candidate.get("submit_source") or "swing_production_reset",
            "entry_type": row.get("entry_type") or candidate.get("entry_type") or "swing_production_contract",
            "p387_rate_limit_retry": True,
            "p387_rate_limit_retry_key": row.get("key"),
            "p387_rate_limit_retry_attempt": int(row.get("attempts") or 0) + 1,
            "p387_rate_limit_retry_first_reason": row.get("first_reason"),
            "p387_rate_limit_retry_last_reason": row.get("last_reason"),
        })
        out.append(candidate)
    return out

def _p387_clear_rate_limit_selected_submit_retry(symbol: str, signal: str | None = None, reason: str = "cleared") -> None:
    key = _p387_rate_limit_retry_key(symbol, signal)
    row = P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE.pop(key, None)
    if isinstance(row, dict):
        _p352_record_rate_limit_submit_recovery(
            row.get("symbol"),
            row.get("side"),
            row.get("signal"),
            row.get("source"),
            "durable_retry_cleared",
            key=key,
            reason=reason,
        )

def submit_scan_trade(symbol: str, side: str, signal: str, meta: dict | None = None, source: str = "worker_scan") -> dict:
    """Submit an order originating from the scanner through the shared execution path."""
    source_name = str(source or "worker_scan").strip() or "worker_scan"
    first = execute_entry_signal(symbol=symbol, side=side, signal=signal, source=source_name, meta=meta)

    if not bool(ALPACA_SUBMIT_RATE_LIMIT_RETRY_ENABLED):
        return first
    if not _p352_response_rate_limited(first):
        return first

    max_attempts = max(1, int(ALPACA_SUBMIT_RATE_LIMIT_RETRY_MAX_ATTEMPTS or 1))
    if max_attempts <= 1:
        return first

    delay_sec = max(0.0, float(ALPACA_SUBMIT_RATE_LIMIT_RETRY_DELAY_SEC or 0.0))
    _p352_record_rate_limit_submit_recovery(
        symbol,
        side,
        signal,
        source_name,
        "retry_scheduled",
        delay_sec=delay_sec,
        first_reason=first.get("reason"),
    )
    record_decision(
        "ENTRY",
        source_name,
        symbol,
        side=side,
        signal=signal,
        action="submit_retry_scheduled",
        reason="alpaca_rate_limit",
        meta={"delay_sec": delay_sec, "first_response": first},
    )

    if delay_sec > 0:
        _time.sleep(delay_sec)

    try:
        release_symbol_lock(str(symbol or "").strip().upper())
    except Exception:
        pass

    retry_meta = dict(meta or {})
    retry_meta["rate_limit_retry"] = True
    retry_meta["rate_limit_retry_attempt"] = 2
    retry = execute_entry_signal(symbol=symbol, side=side, signal=signal, source=source_name, meta=retry_meta)
    retry["rate_limit_retry"] = {
        "attempted": True,
        "first_reason": first.get("reason"),
        "retry_reason": retry.get("reason"),
        "retry_submitted": bool(retry.get("submitted")),
    }

    _p352_record_rate_limit_submit_recovery(
        symbol,
        side,
        signal,
        source_name,
        "retry_completed",
        submitted=bool(retry.get("submitted")),
        first_reason=first.get("reason"),
        retry_reason=retry.get("reason"),
        order_id=str(retry.get("order_id") or ""),
    )
    return retry


def _classify_scan_submit_response(resp: dict | None) -> dict:
    resp = dict(resp or {})
    reason = str(resp.get("reason") or resp.get("action") or "").strip()
    if bool(resp.get("submitted")):
        return {"state": "submitted", "reason": reason, "attempted": True, "order_id": str(resp.get("order_id") or "").strip()}
    if bool(resp.get("dry_run")):
        return {"state": "preview_only", "reason": reason or "dry_run", "attempted": False, "order_id": ""}
    if bool(resp.get("ignored")):
        return {"state": "ignored", "reason": reason or "ignored", "attempted": False, "order_id": ""}
    if bool(resp.get("rejected")):
        retryable = bool(resp.get("retryable") or resp.get("rate_limited") or _p352_is_alpaca_rate_limit_error(reason))
        return {
            "state": "retryable_rate_limit" if retryable else "blocked",
            "reason": reason or ("alpaca_submit_rate_limited" if retryable else "rejected"),
            "attempted": True,
            "retryable": retryable,
            "rate_limited": retryable,
            "order_id": "",
        }
    if bool(resp.get("ok")):
        return {"state": "not_submitted", "reason": reason or "ok_without_submit", "attempted": False, "order_id": ""}
    return {"state": "error", "reason": reason or "unknown", "attempted": False, "order_id": ""}

def _p366_submit_execution_quality_blocked(submit_state: str | None, submit_reason: str | None) -> bool:
    state = str(submit_state or "").strip().lower()
    reason = str(submit_reason or "").strip().lower()
    return bool(
        state == "blocked"
        and reason in {
            "spread_too_wide",
            "quote_missing",
            "quote_stale",
            "fresh_quote_required",
        }
    )


def _p366_retryable_spread_block(symbol: str, signal: str | None, submit_state: str | None, submit_reason: str | None) -> dict:
    state = str(submit_state or "").strip().lower()
    reason = str(submit_reason or "").strip().lower()
    sym = str(symbol or "").strip().upper()
    sig = str(signal or "daily_breakout").strip() or "daily_breakout"
    key = _p327_spread_retry_key(sym, sig) if sym else ""

    retryable = bool(
        SPREAD_BLOCKED_RETRY_ENABLED
        and sym
        and state == "blocked"
        and reason == "spread_too_wide"
    )

    queued = bool(key and key in SPREAD_BLOCKED_SELECTED_RETRY_QUEUE)

    return {
        "retryable": retryable,
        "queued": queued,
        "key": key or None,
        "reason": "spread_blocked_retry_available" if retryable else "not_retryable_spread_block",
    }

def _p312_scan_submit_side_effect(symbol: str, submit_meta: dict | None = None, resp: dict | None = None) -> dict:
    sym = str(symbol or "").strip().upper()
    meta = dict(submit_meta or {})
    resp = dict(resp or {})
    submit_state = str(meta.get("state") or resp.get("submit_state") or "").strip().lower()
    submit_order_id = str(meta.get("order_id") or resp.get("order_id") or resp.get("submit_order_id") or "").strip()

    plan = dict((TRADE_PLAN or {}).get(sym) or {}) if sym else {}
    active_plan = bool(plan.get("active"))
    pending_entry_plan = bool(_plan_is_pending_entry(plan))

    reasons = []
    if active_plan:
        reasons.append("active_plan")
    if pending_entry_plan:
        reasons.append("pending_entry_plan")
    if submit_order_id:
        reasons.append("submit_order_id")
    if submit_state in {"submitted", "preview_only"}:
        reasons.append(f"submit_state:{submit_state}")

    actual_submit_side_effect = bool(
        active_plan
        or pending_entry_plan
        or bool(submit_order_id)
        or submit_state in {"submitted", "preview_only"}
    )

    return {
        "actual_submit_side_effect": bool(actual_submit_side_effect),
        "side_effect_reasons": _dedupe_candidate_reasons(reasons),
        "submit_gap": not bool(actual_submit_side_effect),
        "active_plan": active_plan,
        "pending_entry_plan": pending_entry_plan,
        "submit_state": submit_state or None,
        "submit_order_id": submit_order_id or None,
        "plan_status": plan.get("execution_state") or plan.get("lifecycle_state") or plan.get("status"),
        "plan_source": plan.get("source"),
    }

def _p327_spread_retry_key(symbol: str, signal: str | None = None) -> str:
    sym = str(symbol or "").strip().upper()
    sig = str(signal or "daily_breakout").strip().lower() or "daily_breakout"
    return f"{sym}|{sig}"


def _p327_queue_spread_blocked_selected_candidate(candidate: dict | None, meta: dict | None, resp: dict | None) -> dict:
    if not bool(SPREAD_BLOCKED_RETRY_ENABLED):
        return {"queued": False, "reason": "spread_blocked_retry_disabled"}

    c = dict(candidate or {})
    m = dict(meta or {})
    r = dict(resp or {})
    symbol = str(c.get("symbol") or m.get("symbol") or r.get("symbol") or "").strip().upper()
    signal = str(c.get("signal") or m.get("signal") or r.get("signal") or "daily_breakout").strip() or "daily_breakout"
    if not symbol:
        return {"queued": False, "reason": "missing_symbol"}

    if str(r.get("reason") or "").strip().lower() != "spread_too_wide":
        return {"queued": False, "reason": "not_spread_blocked"}

    now_iso = datetime.now(timezone.utc).isoformat()
    key = _p327_spread_retry_key(symbol, signal)
    existing = dict(SPREAD_BLOCKED_SELECTED_RETRY_QUEUE.get(key) or {})
    first_seen = existing.get("first_seen_utc") or now_iso
    attempts = int(existing.get("attempts") or 0)

    row = {
        "key": key,
        "symbol": symbol,
        "signal": signal,
        "first_seen_utc": first_seen,
        "last_seen_utc": now_iso,
        "expires_utc": (datetime.now(timezone.utc) + timedelta(seconds=max(60, int(SPREAD_BLOCKED_RETRY_WINDOW_SEC or 900)))).isoformat(),
        "attempts": attempts,
        "last_reason": "spread_too_wide",
        "candidate": c,
        "meta": m,
        "last_response": r,
        "last_snapshot": dict(r.get("snapshot") or {}),
        "last_spread_override": dict(r.get("spread_override") or (r.get("snapshot") or {}).get("spread_override") or {}),
        "source_name": str(m.get("selected_source") or m.get("source_name") or "swing_production_reset"),
        "entry_type": str(m.get("entry_type") or c.get("entry_type") or "swing_production_contract"),
    }
    SPREAD_BLOCKED_SELECTED_RETRY_QUEUE[key] = row
    persist_scan_runtime_state(reason="spread_blocked_selected_candidate_queued")
    return {"queued": True, "key": key, "symbol": symbol, "expires_utc": row.get("expires_utc")}

def _p327_find_candidate_for_spread_retry_backfill(symbol: str, summary: dict | None = None) -> dict:
    sym = str(symbol or "").strip().upper()
    summary = dict(summary or {})
    if not sym:
        return {}

    search_sets = [
        list(LAST_SWING_CANDIDATES or []),
        list(summary.get("top_candidates") or []),
        list(summary.get("top_breakout_candidates") or []),
        list(summary.get("top_mean_reversion_candidates") or []),
        list((summary.get("production_contract_miss_reasons") or {}).get("approved") or []),
        list((summary.get("production_contract_miss_reasons") or {}).get("missed") or []),
        list((summary.get("production_contract_miss_reasons") or {}).get("near_approved") or []),
    ]

    for rows in search_sets:
        for row in rows:
            if not isinstance(row, dict):
                continue
            if str(row.get("symbol") or "").strip().upper() == sym:
                return dict(row)

    return {}


def _p327_backfill_spread_retry_queue_from_selected_submission_rows(summary: dict | None = None) -> dict:
    summary = dict(summary or {})
    rows = list(summary.get("selected_submission_rows") or summary.get("would_submit") or [])
    backfilled = []
    skipped = []

    for row in rows:
        if not isinstance(row, dict):
            continue
        symbol = str(row.get("symbol") or "").strip().upper()
        signal = str(row.get("signal") or "daily_breakout").strip() or "daily_breakout"
        submit_state = str(row.get("submit_state") or "").strip().lower()
        submit_reason = str(row.get("submit_reason") or row.get("reason") or "").strip().lower()

        if not symbol:
            skipped.append({"symbol": symbol, "reason": "missing_symbol"})
            continue
        if submit_state != "blocked" or submit_reason != "spread_too_wide":
            skipped.append({"symbol": symbol, "reason": "not_spread_blocked"})
            continue

        key = _p327_spread_retry_key(symbol, signal)
        if key in SPREAD_BLOCKED_SELECTED_RETRY_QUEUE:
            skipped.append({"symbol": symbol, "reason": "already_queued"})
            continue

        candidate = _p327_find_candidate_for_spread_retry_backfill(symbol, summary=summary)
        candidate.update({
            "symbol": symbol,
            "signal": signal,
            "selected": True,
            "selected_source": "swing_production_reset",
            "entry_type": str(row.get("entry_type") or candidate.get("entry_type") or "swing_production_contract"),
        })

        meta = {
            "symbol": symbol,
            "signal": signal,
            "selected_source": "swing_production_reset",
            "entry_type": str(row.get("entry_type") or candidate.get("entry_type") or "swing_production_contract"),
            "rank_score": row.get("rank_score") or candidate.get("rank_score"),
            "avg_dollar_volume_20d": candidate.get("avg_dollar_volume_20d") or candidate.get("avg_dollar_volume"),
            "strategy": candidate.get("strategy") or row.get("strategy") or row.get("signal"),
            "strategy_name": candidate.get("strategy") or row.get("strategy") or row.get("signal"),
            "breakout_level": candidate.get("breakout_level"),
            "stop_price": candidate.get("stop_price"),
            "target_price": candidate.get("target_price"),
            "risk_per_share": candidate.get("risk_per_share"),
            "max_hold_days": candidate.get("max_hold_days"),
            "regime_mode": candidate.get("regime_mode"),
            "scan_ts_utc": candidate.get("scan_ts_utc"),
            "close": candidate.get("close") or row.get("price") or row.get("trade_price"),
            "price": candidate.get("close") or row.get("price") or row.get("trade_price"),
            "trade_price": candidate.get("close") or row.get("price") or row.get("trade_price"),
            "swing_production_contract": candidate.get("swing_production_contract"),
            "legacy_gate_mode": candidate.get("legacy_gate_mode"),
            "spread_retry_backfilled": True,
        }

        resp = {
            "ok": False,
            "rejected": True,
            "reason": "spread_too_wide",
            "symbol": symbol,
            "signal": signal,
            "snapshot": dict(row.get("snapshot") or {}),
            "spread_override": dict(row.get("spread_override") or (row.get("snapshot") or {}).get("spread_override") or {}),
        }

        queued = _p327_queue_spread_blocked_selected_candidate(candidate, meta=meta, resp=resp)
        backfilled.append({
            "symbol": symbol,
            "key": key,
            "queued": bool(queued.get("queued")),
            "reason": queued.get("reason"),
        })

    return {
        "attempted": len(rows),
        "backfilled": backfilled,
        "skipped": skipped[:25],
        "backfilled_count": len([r for r in backfilled if r.get("queued")]),
    }


def _p369_spread_retry_rows_from_summary(summary: dict | None = None) -> list[dict]:
    summary = dict(summary or {})
    rows = list(summary.get("selected_submission_rows") or summary.get("would_submit") or [])
    return [dict(r) for r in rows if isinstance(r, dict)]


def _p369_refresh_spread_retry_queue_from_latest_selection(summary: dict | None = None) -> dict:
    if not bool(SPREAD_BLOCKED_RETRY_REFRESH_ON_SELECTED_SCAN_ENABLED):
        return {"enabled": False, "refreshed_count": 0, "reason": "refresh_disabled"}

    summary = dict(summary or {})
    rows = _p369_spread_retry_rows_from_summary(summary)
    selected_symbols = {
        str(s or "").strip().upper()
        for s in list(summary.get("selected_symbols") or [])
        if str(s or "").strip()
    }
    selected_symbols.update({
        str((r or {}).get("symbol") or "").strip().upper()
        for r in rows
        if str((r or {}).get("symbol") or "").strip()
    })

    row_by_key = {}
    for row in rows:
        symbol = str(row.get("symbol") or "").strip().upper()
        signal = str(row.get("signal") or row.get("strategy") or "daily_breakout").strip() or "daily_breakout"
        if symbol:
            row_by_key[_p327_spread_retry_key(symbol, signal)] = dict(row)

    now_dt = datetime.now(timezone.utc)
    now_iso = now_dt.isoformat()
    ttl_sec = max(60, int(SPREAD_BLOCKED_RETRY_WINDOW_SEC or 900))
    refreshed = []
    skipped = []

    for key, queued_row in list(SPREAD_BLOCKED_SELECTED_RETRY_QUEUE.items()):
        row = dict(queued_row or {})
        symbol = str(row.get("symbol") or "").strip().upper()
        signal = str(row.get("signal") or "daily_breakout").strip() or "daily_breakout"
        current_key = _p327_spread_retry_key(symbol, signal)
        submit_row = dict(row_by_key.get(current_key) or {})

        if not symbol:
            skipped.append({"key": key, "reason": "missing_symbol"})
            continue
        if symbol not in selected_symbols:
            skipped.append({"key": key, "symbol": symbol, "reason": "not_selected_in_latest_scan"})
            continue

        submit_state = str(submit_row.get("submit_state") or "").strip().lower()
        submit_reason = str(submit_row.get("submit_reason") or submit_row.get("reason") or "").strip().lower()
        still_spread_blocked = bool(submit_state == "blocked" and submit_reason == "spread_too_wide")
        listed_retryable = symbol in {
            str(s or "").strip().upper()
            for s in list(summary.get("retryable_spread_block_symbols") or [])
            if str(s or "").strip()
        }

        if submit_row and not (still_spread_blocked or listed_retryable):
            skipped.append({"key": key, "symbol": symbol, "reason": "latest_selection_not_spread_blocked"})
            continue

        row["last_seen_utc"] = now_iso
        row["expires_utc"] = (now_dt + timedelta(seconds=ttl_sec)).isoformat()
        row["last_refresh_utc"] = now_iso
        row["refresh_count"] = int(row.get("refresh_count") or 0) + 1
        row["last_refresh_reason"] = "latest_scan_still_selected"

        if submit_row:
            row["latest_submit_row"] = submit_row
            row["last_snapshot"] = dict(submit_row.get("snapshot") or row.get("last_snapshot") or {})
            row["last_spread_override"] = dict(
                submit_row.get("spread_override")
                or (submit_row.get("snapshot") or {}).get("spread_override")
                or row.get("last_spread_override")
                or {}
            )

        SPREAD_BLOCKED_SELECTED_RETRY_QUEUE[key] = row
        refreshed.append({
            "key": key,
            "symbol": symbol,
            "expires_utc": row.get("expires_utc"),
            "refresh_count": int(row.get("refresh_count") or 0),
        })

    if refreshed:
        persist_scan_runtime_state(reason="p369_spread_retry_ttl_refresh")

    return {
        "enabled": True,
        "refreshed_count": len(refreshed),
        "refreshed": refreshed[:25],
        "skipped": skipped[:25],
    }


def _p369_auto_retry_after_scan_summary(summary: dict | None = None) -> dict:
    if not bool(SPREAD_BLOCKED_RETRY_AUTO_APPLY_ON_SCAN_ENABLED):
        return {"enabled": False, "applied": False, "reason": "auto_apply_disabled"}
    if not bool(SPREAD_BLOCKED_RETRY_ENABLED):
        return {"enabled": False, "applied": False, "reason": "spread_retry_disabled"}

    summary = dict(summary or {})
    has_retryable_selection = bool(summary.get("retryable_spread_block_symbols"))
    if not SPREAD_BLOCKED_SELECTED_RETRY_QUEUE and not has_retryable_selection:
        return {"enabled": True, "applied": False, "reason": "no_retry_queue_or_retryable_selection"}

    try:
        result = _p327_spread_blocked_submission_retry_snapshot(apply=True, limit=5)
        return {
            "enabled": True,
            "applied": True,
            "ok": bool(result.get("ok")),
            "eligible_count": int(result.get("eligible_count") or 0),
            "submitted_count": int(result.get("submitted_count") or 0),
            "removed_count": int(result.get("removed_count") or 0),
            "recommended_action": result.get("recommended_action"),
        }
    except Exception as exc:
        logger.exception("P369_SPREAD_RETRY_AUTO_APPLY_FAILED")
        return {"enabled": True, "applied": False, "reason": "auto_apply_error", "error": str(exc)}


def _p327_retry_row_status(row: dict | None) -> dict:
    r = dict(row or {})
    symbol = str(r.get("symbol") or "").strip().upper()
    signal = str(r.get("signal") or "daily_breakout").strip() or "daily_breakout"
    now_dt = datetime.now(timezone.utc)
    expires_dt = _safe_parse_iso_utc(r.get("expires_utc")) if r.get("expires_utc") else None
    expired = bool(expires_dt and now_dt > expires_dt)
    first_seen_dt = _safe_parse_iso_utc(r.get("first_seen_utc")) if r.get("first_seen_utc") else None
    last_seen_dt = _safe_parse_iso_utc(r.get("last_seen_utc")) if r.get("last_seen_utc") else None
    queue_age_sec = round(max(0.0, (now_dt - first_seen_dt).total_seconds()), 2) if first_seen_dt else None
    last_seen_age_sec = round(max(0.0, (now_dt - last_seen_dt).total_seconds()), 2) if last_seen_dt else None
    ttl_remaining_sec = round((expires_dt - now_dt).total_seconds(), 2) if expires_dt else None
    attempts = int(r.get("attempts") or 0)
    max_attempts_hit = attempts >= int(SPREAD_BLOCKED_RETRY_MAX_ATTEMPTS or 0)

    candidate = dict(r.get("candidate") or {})
    contract_row = _p323_apply_swing_production_contract(candidate, global_block_reasons=[])
    contract = dict(contract_row.get("swing_production_contract") or {})
    contract_approved = bool(contract.get("approved"))

    snapshot = {}
    spread_override = {}
    quote_error = None
    try:
        snapshot = get_latest_quote_snapshot(symbol)
        spread_override = _entry_spread_override_decision(snapshot, meta=dict(r.get("meta") or {}))
        snapshot["spread_override"] = spread_override
    except Exception as e:
        quote_error = str(e)

    spread_pct = snapshot.get("spread_pct") if isinstance(snapshot, dict) else None
    quote_ok = bool(snapshot.get("quote_ok")) if isinstance(snapshot, dict) else False
    fresh = bool(snapshot.get("fresh")) if isinstance(snapshot, dict) else False
    spread_allowed = bool(spread_override.get("allowed"))

    retry_eligible = bool(
        SPREAD_BLOCKED_RETRY_ENABLED
        and symbol
        and not expired
        and not max_attempts_hit
        and contract_approved
        and quote_error is None
        and quote_ok
        and ((not ENTRY_REQUIRE_FRESH_QUOTE) or fresh)
        and (
            spread_allowed
            or (spread_pct is not None and float(spread_pct) <= float(ENTRY_MAX_SPREAD_PCT))
        )
    )

    blockers = []
    if not bool(SPREAD_BLOCKED_RETRY_ENABLED):
        blockers.append("spread_blocked_retry_disabled")
    if expired:
        blockers.append("retry_window_expired")
    if max_attempts_hit:
        blockers.append("retry_max_attempts_hit")
    if not contract_approved:
        blockers.append("production_contract_not_approved_now")
    if quote_error:
        blockers.append("quote_error")
    if not quote_ok:
        blockers.append("quote_not_ok")
    if ENTRY_REQUIRE_FRESH_QUOTE and not fresh:
        blockers.append("quote_not_fresh")
    if not retry_eligible and quote_error is None and quote_ok and (not ENTRY_REQUIRE_FRESH_QUOTE or fresh):
        if not (spread_allowed or (spread_pct is not None and float(spread_pct) <= float(ENTRY_MAX_SPREAD_PCT))):
            blockers.append("spread_still_too_wide")

    return {
        "key": r.get("key") or _p327_spread_retry_key(symbol, signal),
        "symbol": symbol,
        "signal": signal,
        "retry_eligible": bool(retry_eligible),
        "blockers": _dedupe_candidate_reasons(blockers),
        "expired": bool(expired),
        "freshness_status": (
            "retry_eligible_now"
            if retry_eligible
            else "expired"
            if expired
            else "max_attempts_hit"
            if max_attempts_hit
            else "waiting_for_spread_to_normalize"
            if "spread_still_too_wide" in blockers
            else "waiting_for_quote_freshness"
            if "quote_not_fresh" in blockers
            else "blocked"
            if blockers
            else "waiting"
        ),
        "waiting_intentional": bool((not retry_eligible) and (not expired) and (not max_attempts_hit) and bool(blockers)),
        "queue_age_sec": queue_age_sec,
        "last_seen_age_sec": last_seen_age_sec,
        "ttl_remaining_sec": ttl_remaining_sec,
        "attempts": attempts,
        "max_attempts": int(SPREAD_BLOCKED_RETRY_MAX_ATTEMPTS or 0),
        "first_seen_utc": r.get("first_seen_utc"),
        "last_seen_utc": r.get("last_seen_utc"),
        "expires_utc": r.get("expires_utc"),
        "last_refresh_utc": r.get("last_refresh_utc"),
        "refresh_count": int(r.get("refresh_count") or 0),
        "last_refresh_reason": r.get("last_refresh_reason"),
        "contract_approved_now": bool(contract_approved),
        "contract_blockers": list(contract.get("blockers") or []),
        "quote_error": quote_error,
        "execution_quality": {
            "quote_ok": quote_ok,
            "fresh": fresh,
            "spread_pct": spread_pct,
            "entry_max_spread_pct": float(ENTRY_MAX_SPREAD_PCT),
            "spread_override_allowed": bool(spread_allowed),
            "spread_override": spread_override,
            "feed": ((snapshot.get("quote_debug") or {}).get("feed") if isinstance(snapshot, dict) else None),
            "quote_ts_utc": snapshot.get("quote_ts_utc") if isinstance(snapshot, dict) else None,
            "trade_ts_utc": snapshot.get("trade_ts_utc") if isinstance(snapshot, dict) else None,
            "price_age_sec": snapshot.get("price_age_sec") if isinstance(snapshot, dict) else None,
        },
        "candidate": candidate,
        "meta": dict(r.get("meta") or {}),
    }


def _p327_spread_blocked_submission_retry_snapshot(apply: bool = False, limit: int = 10) -> dict:
    lim = max(1, min(int(limit or 10), 25))
    latest_scan, summary = _p298_latest_scan_summary_light()
    backfill = _p327_backfill_spread_retry_queue_from_selected_submission_rows(summary)
    ttl_refresh = _p369_refresh_spread_retry_queue_from_latest_selection(summary)
    rows = []
    submitted = []
    removed = []

    for key, row in list(SPREAD_BLOCKED_SELECTED_RETRY_QUEUE.items()):
        status = _p327_retry_row_status(row)
        rows.append(status)

        if status.get("expired") or "retry_max_attempts_hit" in list(status.get("blockers") or []):
            removed.append({"key": key, "symbol": status.get("symbol"), "reason": "expired_or_max_attempts"})
            SPREAD_BLOCKED_SELECTED_RETRY_QUEUE.pop(key, None)
            continue

        if apply and status.get("retry_eligible"):
            queued = dict(SPREAD_BLOCKED_SELECTED_RETRY_QUEUE.get(key) or {})
            queued["attempts"] = int(queued.get("attempts") or 0) + 1
            queued["last_retry_utc"] = datetime.now(timezone.utc).isoformat()
            SPREAD_BLOCKED_SELECTED_RETRY_QUEUE[key] = queued

            resp = submit_scan_trade(
                status.get("symbol"),
                "buy",
                status.get("signal") or "daily_breakout",
                meta=dict(status.get("meta") or {}),
                source=str((status.get("meta") or {}).get("selected_source") or "swing_production_reset"),
            )
            submit_meta = _classify_scan_submit_response(resp)
            side_effect = _p312_scan_submit_side_effect(status.get("symbol"), submit_meta=submit_meta, resp=resp)
            submitted_row = {
                "key": key,
                "symbol": status.get("symbol"),
                "response": resp,
                "submit_state": submit_meta.get("state"),
                "submit_reason": submit_meta.get("reason"),
                "submit_order_id": submit_meta.get("order_id"),
                "actual_submit_side_effect": bool(side_effect.get("actual_submit_side_effect")),
                "side_effect_reasons": list(side_effect.get("side_effect_reasons") or []),
            }
            submitted.append(submitted_row)
            if bool(side_effect.get("actual_submit_side_effect")):
                SPREAD_BLOCKED_SELECTED_RETRY_QUEUE.pop(key, None)

    rows.sort(key=lambda r: (1 if r.get("retry_eligible") else 0, str(r.get("first_seen_utc") or "")), reverse=True)
    freshness_counts = Counter(str(r.get("freshness_status") or "unknown") for r in rows)
    intentional_wait_symbols = [
        str(r.get("symbol") or "").strip().upper()
        for r in rows
        if bool(r.get("waiting_intentional"))
    ]
    no_longer_spread_blocked_symbols = _dedupe_keep_order([
        str((r or {}).get("symbol") or "").strip().upper()
        for r in list((backfill or {}).get("skipped") or [])
        if str((r or {}).get("reason") or "") == "not_spread_blocked"
        and str((r or {}).get("symbol") or "").strip()
    ])
    resolved_retry_symbols = _dedupe_keep_order([
        str((r or {}).get("symbol") or "").strip().upper()
        for r in submitted
        if bool((r or {}).get("actual_submit_side_effect"))
        and str((r or {}).get("symbol") or "").strip()
    ] + no_longer_spread_blocked_symbols)
    persist_scan_runtime_state(reason="spread_blocked_submission_retry_apply" if apply else "spread_blocked_submission_retry_snapshot")

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "spread_blocked_submission_retry",
        "apply": bool(apply),
        "enabled": bool(SPREAD_BLOCKED_RETRY_ENABLED),
        "queue_count": len(SPREAD_BLOCKED_SELECTED_RETRY_QUEUE),
        "eligible_count": len([r for r in rows if r.get("retry_eligible")]),
        "submitted_count": len(submitted),
        "removed_count": len(removed),
        "freshness_counts": dict(freshness_counts),
        "intentional_wait_symbols": intentional_wait_symbols,
        "stale_queue_symbols": [
            str(r.get("symbol") or "").strip().upper()
            for r in rows
            if str(r.get("freshness_status") or "") in {"expired", "max_attempts_hit"}
        ],
        "resolved_retry_symbols": resolved_retry_symbols,
        "no_longer_spread_blocked_symbols": no_longer_spread_blocked_symbols,
        "backfill": backfill,
        "ttl_refresh": ttl_refresh,
        "latest_scan": {
            "ts_utc": latest_scan.get("ts_utc"),
            "reason": latest_scan.get("reason"),
            "selected_symbols": list(summary.get("selected_symbols") or []),
        },
        "config": {
            "window_sec": int(SPREAD_BLOCKED_RETRY_WINDOW_SEC or 0),
            "max_attempts": int(SPREAD_BLOCKED_RETRY_MAX_ATTEMPTS or 0),
            "refresh_on_selected_scan_enabled": bool(SPREAD_BLOCKED_RETRY_REFRESH_ON_SELECTED_SCAN_ENABLED),
            "auto_apply_on_scan_enabled": bool(SPREAD_BLOCKED_RETRY_AUTO_APPLY_ON_SCAN_ENABLED),
            "entry_max_spread_pct": float(ENTRY_MAX_SPREAD_PCT),
            "iex_override_enabled": bool(ENTRY_IEX_LIQUIDITY_OVERRIDE_ENABLED),
            "iex_override_max_spread_pct": float(ENTRY_IEX_LIQUIDITY_OVERRIDE_MAX_SPREAD_PCT),
        },
        "rows": rows[:lim],
        "submitted": submitted,
        "removed": removed,
        "recommended_action": (
            "retry_submitted"
            if submitted
            else "spread_retry_resolved_or_no_longer_blocked"
            if resolved_retry_symbols
            else "run_apply_true_when_retry_eligible"
            if any(r.get("retry_eligible") for r in rows)
            else "wait_for_spread_to_normalize"
            if rows
            else "no_spread_blocked_candidates_or_selected_rows"
        ),
    }

def _p297_symbol_entry_side_effect(symbol: str) -> dict:
    sym = str(symbol or "").strip().upper()
    if not sym:
        return {
            "symbol": sym,
            "side_effect_detected": False,
            "reasons": ["missing_symbol"],
        }

    reasons = []
    plan = dict((TRADE_PLAN or {}).get(sym) or {})
    if bool(plan.get("active")):
        reasons.append("active_plan")
    if _plan_is_pending_entry(plan):
        reasons.append("pending_entry_plan")

    open_order = {}
    try:
        open_order = dict(find_open_order_for_symbol(sym) or {})
    except Exception:
        open_order = {}
    if open_order:
        reasons.append("open_order")

    qty_signed = 0.0
    pos_side = ""
    try:
        qty_signed, pos_side = get_position(sym)
    except Exception:
        qty_signed, pos_side = 0.0, ""
    if float(qty_signed or 0.0) != 0.0:
        reasons.append("broker_position")

    return {
        "symbol": sym,
        "side_effect_detected": bool(reasons),
        "reasons": _dedupe_candidate_reasons(reasons),
        "active_plan": bool(plan.get("active")),
        "pending_entry_plan": bool(_plan_is_pending_entry(plan)),
        "open_order": bool(open_order),
        "open_order_id": str(open_order.get("id") or open_order.get("order_id") or ""),
        "broker_position_qty": float(qty_signed or 0.0),
        "broker_position_side": pos_side,
        "plan_status": plan.get("execution_state") or plan.get("lifecycle_state") or plan.get("status"),
        "plan_source": plan.get("source"),
        "plan_entry_type": plan.get("entry_type") or (plan.get("thesis") or {}).get("entry_type"),
    }


def _p297_selected_symbols_from_sections(sections: dict | None = None) -> list[str]:
    sections = dict(sections or {})
    candidates = dict(sections.get("candidates_full") or {})
    selected = [
        str(s or "").strip().upper()
        for s in list(candidates.get("selected_symbols") or [])
        if str(s or "").strip()
    ]

    if not selected:
        for row in list(candidates.get("items") or []):
            if not isinstance(row, dict):
                continue
            if bool(row.get("selected")):
                sym = str(row.get("symbol") or "").strip().upper()
                if sym:
                    selected.append(sym)

    if not selected:
        lifecycle = dict(sections.get("execution_lifecycle") or {})
        for row in reversed(list(lifecycle.get("items") or [])):
            if not isinstance(row, dict):
                continue
            if str(row.get("stage") or "").strip().lower() == "candidate" and str(row.get("status") or "").strip().lower() == "selected":
                sym = str(row.get("symbol") or "").strip().upper()
                if sym:
                    selected.append(sym)
                    break

    if not selected:
        last_event = dict(LAST_PAPER_LIFECYCLE or {})
        if str(last_event.get("stage") or "").strip().lower() == "candidate" and str(last_event.get("status") or "").strip().lower() == "selected":
            sym = str(last_event.get("symbol") or "").strip().upper()
            if sym:
                selected.append(sym)

    return _dedupe_keep_order(selected)


def _p297_selected_submission_truth(selected_symbols: list[str] | None = None, sections: dict | None = None) -> dict:
    symbols = _dedupe_keep_order([
        str(s or "").strip().upper()
        for s in list(selected_symbols or [])
        if str(s or "").strip()
    ])
    if not symbols:
        symbols = _p297_selected_symbols_from_sections(sections)

    rows = [_p297_symbol_entry_side_effect(sym) for sym in symbols]
    missing = [
        row.get("symbol")
        for row in rows
        if row.get("symbol") and not bool(row.get("side_effect_detected"))
    ]

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "selected_candidate_submission_truth",
        "selected_symbols": symbols,
        "selected_count": len(symbols),
        "side_effect_symbols": [
            row.get("symbol")
            for row in rows
            if bool(row.get("side_effect_detected"))
        ],
        "missing_side_effect_symbols": missing,
        "selected_side_effect_detected": bool(symbols and not missing),
        "selected_without_side_effect": bool(missing),
        "rows": rows,
        "recommended_action": (
            "investigate_submit_path_for_selected_symbols"
            if missing
            else "selected_symbols_have_plan_order_or_position"
            if symbols
            else "no_selected_symbols_found"
        ),
    }

def _p310_scan_is_stale_preopen(latest_scan: dict | None = None) -> bool:
    scan = dict(latest_scan or LAST_SCAN or {})
    if not bool(in_market_hours()):
        return False
    if str(scan.get("reason") or "").strip() != "outside_market_hours":
        return False
    scan_dt = _safe_parse_iso_utc(scan.get("ts_utc")) if scan.get("ts_utc") else None
    if scan_dt is None:
        return False
    scan_ny = scan_dt.astimezone(NY_TZ)
    now_local = now_ny()
    if scan_ny.date() != now_local.date():
        return False
    open_cutoff = now_local.replace(hour=9, minute=30, second=0, microsecond=0)
    return scan_ny < open_cutoff <= now_local


def _p298_latest_scan_summary_light() -> tuple[dict, dict]:
    latest_scan, summary = _p324_effective_latest_scan_for_light()

    if not summary and CANDIDATE_HISTORY:
        latest_candidate = dict((CANDIDATE_HISTORY or [])[-1] or {})
        summary = dict(latest_candidate.get("summary") or latest_candidate or {})

    if _p310_scan_is_stale_preopen(latest_scan):
        summary = dict(summary or {})
        summary["post_open_scan_missing"] = True
        summary["stale_preopen_scan"] = True
        latest_scan["post_open_scan_missing"] = True
        latest_scan["stale_preopen_scan"] = True

    summary["scanner_exception_truth"] = _p324_latest_scan_exception_truth()
    summary["scanner_failure_root_cause"] = _p455_scanner_failure_root_cause(
        latest_scan=latest_scan,
        telemetry=LAST_SCANNER_TELEMETRY,
        telemetry_summary=_scanner_telemetry_summary(today_prefix=str(now_ny().date())),
    )
    summary["last_successful_production_scan_available"] = bool(LAST_SUCCESSFUL_PRODUCTION_SCAN)
    summary["last_successful_production_selected_symbols"] = _p324_scan_selected_symbols(LAST_SUCCESSFUL_PRODUCTION_SCAN)

    return latest_scan, summary

def _p325_latest_scan_successfully_closed(latest_scan: dict | None, telemetry: dict | None, telemetry_summary: dict | None) -> bool:
    scan = dict(latest_scan or {})
    tel = dict(telemetry or {})
    summary = dict(telemetry_summary or {})
    scan_reason = str(scan.get("reason") or "").strip().lower()
    last_status = str(tel.get("status") or tel.get("last_status") or "").strip().lower()
    last_event = str(tel.get("event") or tel.get("last_event") or "").strip().lower()
    return bool(
        scan_reason == "scan_completed"
        and not bool(summary.get("in_flight_run"))
        and last_status in {"success", "ok", "skipped", "sleep"}
        and last_event in {
            "scan_ok",
            "scan_closed",
            "scan_completed",
            "heartbeat",
            "scanner_heartbeat",
            "worker_heartbeat",
            "sleep",
            "",
        }
    )


def _p325_normalize_warning_code(code) -> str:
    return str(code or "").strip().lower()


def _p325_recover_scanner_warning_summary(
    telemetry_summary: dict | None,
    latest_scan: dict | None,
    telemetry: dict | None = None,
) -> dict:
    summary = dict(telemetry_summary or {})
    active = [
        _p325_normalize_warning_code(code)
        for code in list(summary.get("active_warning_codes") or [])
        if _p325_normalize_warning_code(code)
    ]
    recovered = [
        _p325_normalize_warning_code(code)
        for code in list(summary.get("recovered_warning_codes") or [])
        if _p325_normalize_warning_code(code)
    ]
    historical = [
        _p325_normalize_warning_code(code)
        for code in list(summary.get("historical_warning_codes") or [])
        if _p325_normalize_warning_code(code)
    ]

    recovered_by_success = _p325_latest_scan_successfully_closed(latest_scan, telemetry, summary)
    if recovered_by_success and "dispatch_failure" in active:
        active = [code for code in active if code != "dispatch_failure"]
        if "dispatch_failure_recovered_by_scan_success" not in recovered:
            recovered.append("dispatch_failure_recovered_by_scan_success")
        if "dispatch_failure" not in historical:
            historical.append("dispatch_failure")

    summary["active_warning_codes"] = _dedupe_keep_order(active)
    summary["recovered_warning_codes"] = _dedupe_keep_order(recovered)
    summary["historical_warning_codes"] = _dedupe_keep_order(historical)
    summary["warning_codes"] = list(summary["active_warning_codes"])
    summary["has_warnings"] = bool(summary["active_warning_codes"])
    summary["has_active_warnings"] = bool(summary["active_warning_codes"])
    summary["has_recovered_warnings"] = bool(summary["recovered_warning_codes"])
    summary["dispatch_failure_recovered_by_scan_success"] = bool(
        recovered_by_success and "dispatch_failure" in historical
    )
    return summary

