def _p404_runtime_universe_coverage(latest_scan: dict | None = None, summary: dict | None = None) -> dict:
    latest_scan = dict(latest_scan or {})
    summary = dict(summary or {})

    runtime_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(universe_symbols() or [])
        if str(sym or "").strip()
    ])

    runtime_slim = dict(summary.get("runtime_slim") or latest_scan.get("runtime_slim") or {})
    runtime_slim_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(runtime_slim.get("symbols") or [])
        if str(sym or "").strip()
    ])

    scanned_symbols = []
    for source in (
        summary.get("symbols"),
        summary.get("scanned_symbols"),
        latest_scan.get("symbols"),
        (latest_scan.get("summary") or {}).get("symbols") if isinstance(latest_scan.get("summary"), dict) else [],
    ):
        scanned_symbols = _dedupe_keep_order([
            str(sym or "").strip().upper()
            for sym in list(source or [])
            if str(sym or "").strip()
        ])
        if scanned_symbols:
            break

    if not scanned_symbols and runtime_slim_symbols:
        scanned_symbols = list(runtime_slim_symbols)

    if not scanned_symbols and CANDIDATE_HISTORY:
        hist = dict((CANDIDATE_HISTORY or [])[-1] or {})
        scanned_symbols = _dedupe_keep_order([
            str(sym or "").strip().upper()
            for sym in list(hist.get("symbols") or [])
            if str(sym or "").strip()
        ])

    if not scanned_symbols and LAST_SWING_CANDIDATES:
        scanned_symbols = _dedupe_keep_order([
            str((row or {}).get("symbol") or "").strip().upper()
            for row in list(LAST_SWING_CANDIDATES or [])
            if isinstance(row, dict) and str((row or {}).get("symbol") or "").strip()
        ])

    runtime_set = set(runtime_symbols)
    scanned_set = set(scanned_symbols)

    current_configured_cap = max(1, int(SWING_RUNTIME_SLIM_MAX_SYMBOLS or 25))
    last_scan_configured_cap = int(
        runtime_slim.get("configured_max_symbols")
        or runtime_slim.get("max_symbols")
        or current_configured_cap
    )

    last_scan_slim_applied = bool(
        runtime_slim.get("applied")
        or (
            bool(SWING_RUNTIME_SLIM_ENABLED)
            and runtime_symbols
            and len(scanned_symbols) < len(runtime_symbols)
            and len(scanned_symbols) <= last_scan_configured_cap
        )
    )

    current_env_wants_full_coverage = bool(
        not bool(SWING_RUNTIME_SLIM_ENABLED)
        or current_configured_cap >= len(runtime_symbols)
    )

    missing_runtime_symbols = [sym for sym in runtime_symbols if sym not in scanned_set]

    if runtime_symbols and scanned_symbols == runtime_symbols:
        coverage_status = "full_runtime_scanned"
    elif current_env_wants_full_coverage and missing_runtime_symbols:
        coverage_status = "last_scan_partial_but_current_env_wants_full_coverage"
    elif last_scan_slim_applied:
        coverage_status = "intentional_runtime_slim_subset_at_scan_time"
    else:
        coverage_status = "partial_runtime_scan_unexplained"

    return {
        "runtime_symbol_count": len(runtime_symbols),
        "scanned_symbol_count": len(scanned_symbols),
        "coverage_pct": round((len(scanned_set & runtime_set) / max(1, len(runtime_set))) * 100.0, 2),
        "matches_runtime": bool(runtime_symbols and scanned_symbols == runtime_symbols),
        "runtime_slim_enabled_current_env": bool(SWING_RUNTIME_SLIM_ENABLED),
        "current_configured_runtime_slim_max_symbols": current_configured_cap,
        "current_env_wants_full_coverage": current_env_wants_full_coverage,
        "last_scan_runtime_slim": {
            "present": bool(runtime_slim),
            "enabled": bool(runtime_slim.get("enabled")),
            "applied": bool(last_scan_slim_applied),
            "configured_max_symbols": last_scan_configured_cap,
            "original_count": runtime_slim.get("original_count"),
            "scanned_count": runtime_slim.get("scanned_count") or len(runtime_slim_symbols) or len(scanned_symbols),
            "rotation_enabled": bool(runtime_slim.get("rotation_enabled")),
            "rotation_slots": int(runtime_slim.get("rotation_slots") or 0),
            "rotation_symbols": list(runtime_slim.get("rotation_symbols") or []),
        },
        "runtime_slim_enabled": bool(SWING_RUNTIME_SLIM_ENABLED),
        "runtime_slim_applied": bool(last_scan_slim_applied),
        "configured_runtime_slim_max_symbols": last_scan_configured_cap,
        "coverage_status": coverage_status,
        "missing_runtime_symbols": missing_runtime_symbols,
        "excluded_by_runtime_slim_symbols": missing_runtime_symbols if last_scan_slim_applied else [],
        "extra_scanned_symbols": [sym for sym in scanned_symbols if sym not in runtime_set],
        "scanned_symbols": scanned_symbols,
        "runtime_symbols": runtime_symbols,
        "recommended_action": (
            "coverage_clean"
            if coverage_status == "full_runtime_scanned"
            else "rerun_scan_to_confirm_new_runtime_env"
            if coverage_status == "last_scan_partial_but_current_env_wants_full_coverage"
            else "runtime_rotation_active_monitor_coverage"
            if coverage_status == "intentional_runtime_slim_subset_at_scan_time"
            else "investigate_partial_runtime_scan"
        ),
    }

def _p325_build_production_contract_miss_snapshot(
    rows: list | None,
    selected: list | None = None,
    limit: int = 50,
) -> dict:
    lim = max(1, min(int(limit or 50), 200))
    open_symbols = set(_p404_active_position_symbols_light())
    checked = []

    for row in list(rows or []):
        if not isinstance(row, dict):
            continue
        miss_row = _p325_contract_miss_row(row)
        sym = str(miss_row.get("symbol") or "").strip().upper()
        if not sym:
            continue
        miss_row["open_position"] = sym in open_symbols
        if miss_row["open_position"]:
            miss_row["candidate_context"] = "open_position_not_new_entry"
        else:
            miss_row["candidate_context"] = "new_entry_candidate"
        checked.append(miss_row)

    approved = [r for r in checked if bool(r.get("approved")) and not bool(r.get("open_position"))]
    missed = [r for r in checked if not bool(r.get("approved")) and not bool(r.get("open_position"))]
    open_position_rows = [r for r in checked if bool(r.get("open_position"))]

    reason_counts = Counter()
    for row in missed:
        blockers = list(row.get("blockers") or [])
        if not blockers:
            reason_counts["no_contract_blocker_reported"] += 1
        for reason in blockers:
            reason_counts[str(reason)] += 1

    near_approved = [
        r for r in missed
        if int(r.get("blocker_count") or 0) == 1
        and "position_already_open" not in list(r.get("blockers") or [])
        and "plan_or_pending_entry_exists" not in list(r.get("blockers") or [])
    ]

    sort_key = lambda r: (
        float(_safe_float(r.get("rank_score"))),
        float(_safe_float(r.get("close_to_high_pct"))),
        0.0 - abs(float(_safe_float(r.get("breakout_distance_pct")))),
    )
    approved.sort(key=sort_key, reverse=True)
    near_approved.sort(key=sort_key, reverse=True)
    missed.sort(key=sort_key, reverse=True)
    open_position_rows.sort(key=sort_key, reverse=True)

    selected_symbols = _p404_selected_symbol_list(selected)

    return {
        "rows_checked": len(checked),
        "new_entry_rows_checked": len([r for r in checked if not bool(r.get("open_position"))]),
        "open_position_rows_checked": len(open_position_rows),
        "approved_count": len(approved),
        "missed_count": len(missed),
        "near_approved_count": len(near_approved),
        "open_position_scrubbed_count": len(open_position_rows),
        "open_position_scrubbed_symbols": [r.get("symbol") for r in open_position_rows[:lim]],
        "top_reason_counts": dict(reason_counts.most_common(12)),
        "selected_symbols": selected_symbols,
        "thresholds": {
            "min_rank_score": float(SWING_PRODUCTION_RESET_MIN_RANK_SCORE),
            "min_avg_dollar_volume": float(SWING_PRODUCTION_RESET_MIN_AVG_DOLLAR_VOLUME),
            "max_risk_per_share_pct": float(SWING_PRODUCTION_RESET_MAX_RISK_PER_SHARE_PCT),
            "max_below_breakout_pct": float(SWING_PRODUCTION_RESET_MAX_BELOW_BREAKOUT_PCT),
            "max_above_breakout_pct": float(SWING_PRODUCTION_RESET_MAX_ABOVE_BREAKOUT_PCT),
            "min_close_to_high_pct": float(SWING_PRODUCTION_RESET_MIN_CLOSE_TO_HIGH_PCT),
            "min_return_20d_pct": float(SWING_PRODUCTION_RESET_MIN_RETURN_20D_PCT),
            "allow_mean_reversion": bool(SWING_PRODUCTION_RESET_ALLOW_MEAN_REVERSION),
            "risk_calibration": {
                "enabled": bool(SWING_PRODUCTION_RISK_CALIBRATION_ENABLED),
                "max_risk_pct": float(SWING_PRODUCTION_RISK_CALIBRATION_MAX_RISK_PCT),
                "min_rank_score": float(SWING_PRODUCTION_RISK_CALIBRATION_MIN_RANK_SCORE),
                "min_close_to_high_pct": float(SWING_PRODUCTION_RISK_CALIBRATION_MIN_CLOSE_TO_HIGH_PCT),
                "max_above_breakout_pct": float(SWING_PRODUCTION_RISK_CALIBRATION_MAX_ABOVE_BREAKOUT_PCT),
                "max_entries_per_scan": int(SWING_PRODUCTION_RISK_CALIBRATION_MAX_ENTRIES_PER_SCAN),
            },
            "near_rank_revival": {
                "enabled": bool(SWING_PRODUCTION_NEAR_RANK_REVIVAL_ENABLED),
                "min_rank_score": float(SWING_PRODUCTION_NEAR_RANK_REVIVAL_MIN_RANK_SCORE),
                "min_close_to_high_pct": float(SWING_PRODUCTION_NEAR_RANK_REVIVAL_MIN_CLOSE_TO_HIGH_PCT),
                "max_risk_pct": float(SWING_PRODUCTION_NEAR_RANK_REVIVAL_MAX_RISK_PCT),
                "min_target_path_score": float(SWING_PRODUCTION_NEAR_RANK_REVIVAL_MIN_TARGET_PATH_SCORE),
                "max_entries_per_scan": int(SWING_PRODUCTION_NEAR_RANK_REVIVAL_MAX_ENTRIES_PER_SCAN),
            },
        },
        "approved": approved[:lim],
        "near_approved": near_approved[:lim],
        "missed": missed[:lim],
        "open_position_rows": open_position_rows[:lim],
    }

def _p325_production_contract_miss_reason_rows(limit: int = 25) -> dict:
    lim = max(1, min(int(limit or 25), 100))
    latest_scan, summary = _p298_latest_scan_summary_light()

    snapshot = dict(summary.get("production_contract_miss_reasons") or {})
    source = "scan_summary_full_candidate_snapshot"

    if int(snapshot.get("rows_checked") or 0) <= 0:
        rows, source = _p404_current_candidate_rows_for_miss(summary=summary)
        rows = _p412_rebuild_current_candidate_contract_rows(rows)
        source = f"{source}_p412_contract_rebuilt"
        rows = _p412_rebuild_current_candidate_contract_rows(rows)
        source = f"{source}_p412_contract_rebuilt"
        snapshot = _p325_build_production_contract_miss_snapshot(
            rows,
            selected=summary.get("selected_symbols") or [],
            limit=lim,
        )

    if int(snapshot.get("rows_checked") or 0) <= 0:
        rows = []
        source = "last_swing_candidates_fallback"
        if LAST_SWING_CANDIDATES:
            rows = [dict(r or {}) for r in LAST_SWING_CANDIDATES if isinstance(r, dict)]
        elif CANDIDATE_HISTORY:
            hist = dict((CANDIDATE_HISTORY or [])[-1] or {})
            source = "candidate_history_fallback"
            rows = [
                dict(r or {})
                for r in list(hist.get("candidates") or hist.get("items") or [])
                if isinstance(r, dict)
            ]
        snapshot = _p325_build_production_contract_miss_snapshot(
            rows,
            selected=summary.get("selected_symbols") or [],
            limit=lim,
        )

    approved = list(snapshot.get("approved") or [])[:lim]
    near_approved = list(snapshot.get("near_approved") or [])[:lim]
    missed = list(snapshot.get("missed") or [])[:lim]
    open_position_rows = list(snapshot.get("open_position_rows") or [])[:lim]
    coverage = _p404_runtime_universe_coverage(latest_scan=latest_scan, summary=summary)
    selected_context = _p405_selected_symbol_context(
        snapshot.get("selected_symbols") or summary.get("selected_symbols") or []
    )

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "production_contract_miss_reasons",
        "source": source,
        "contract_rebuild_applied": "_p412_contract_rebuilt" in str(source),
        "contract_rebuild_source": "p412_current_scan_contract_rebuild",
        "latest_scan": {
            "ts_utc": latest_scan.get("ts_utc"),
            "reason": latest_scan.get("reason"),
            "scanned": latest_scan.get("scanned"),
            "signals": latest_scan.get("signals"),
            "would_trade": latest_scan.get("would_trade"),
            "blocked": latest_scan.get("blocked"),
            "duration_ms": latest_scan.get("duration_ms"),
        },
        "runtime_universe_coverage": coverage,
        "summary": {
            "rows_checked": int(snapshot.get("rows_checked") or 0),
            "new_entry_rows_checked": int(snapshot.get("new_entry_rows_checked") or 0),
            "open_position_rows_checked": int(snapshot.get("open_position_rows_checked") or 0),
            "approved_count": int(snapshot.get("approved_count") or 0),
            "near_approved_count": int(snapshot.get("near_approved_count") or 0),
            "missed_count": int(snapshot.get("missed_count") or 0),
            "open_position_scrubbed_count": int(snapshot.get("open_position_scrubbed_count") or 0),
            "open_position_scrubbed_symbols": list(snapshot.get("open_position_scrubbed_symbols") or []),
            "top_reason_counts": dict(snapshot.get("top_reason_counts") or {}),
            "thresholds": dict(snapshot.get("thresholds") or {}),
            "selected_symbols": list(selected_context.get("selected_symbols") or []),
            "selected_total": int(selected_context.get("selected_total") or 0),
            "raw_selected_symbols": list(selected_context.get("raw_selected_symbols") or []),
            "raw_selected_total": int(selected_context.get("raw_selected_total") or 0),
            "open_position_selected_symbols": list(selected_context.get("open_position_selected_symbols") or []),
            "open_position_selected_total": int(selected_context.get("open_position_selected_total") or 0),
            "selection_echo_removed": bool(selected_context.get("selection_echo_removed")),
            "last_successful_production_selected_symbols": list(summary.get("last_successful_production_selected_symbols") or []),
        },
        "approved": approved,
        "near_approved": near_approved,
        "missed": missed,
        "open_position_rows": open_position_rows,
        "recommended_action": (
            "production_contract_has_approved_candidates"
            if approved
            else "review_near_approved_candidates"
            if near_approved
            else "runtime_universe_partial_scan_review_missing_symbols"
            if not bool(coverage.get("matches_runtime"))
            else "review_top_miss_reasons_before_relaxing_contract"
        ),
    }

def _p298_recent_lifecycle_items(limit: int = 100) -> list[dict]:
    lim = max(1, min(int(limit or 100), 250))
    rows = [dict(r or {}) for r in list(PAPER_LIFECYCLE_HISTORY or [])[-lim:] if isinstance(r, dict)]
    if LAST_PAPER_LIFECYCLE and (not rows or rows[-1] != LAST_PAPER_LIFECYCLE):
        rows.append(dict(LAST_PAPER_LIFECYCLE or {}))
    return rows[-lim:]


def _p298_selected_symbols_light(summary: dict | None = None, lifecycle_items: list | None = None) -> list[str]:
    summary = dict(summary or {})

    explicit_selected_total = summary.get("selected_total")
    explicit_would_trade = summary.get("would_trade")
    explicit_selected_symbols_present = "selected_symbols" in summary

    symbols = [
        str(s or "").strip().upper()
        for s in list(summary.get("selected_symbols") or [])
        if str(s or "").strip()
    ]

    scanner_exception_truth = dict(summary.get("scanner_exception_truth") or summary.get("latest_scan_exception") or {})
    if bool(scanner_exception_truth.get("active")) and not symbols:
        symbols = [
            str(s or "").strip().upper()
            for s in list(summary.get("last_successful_production_selected_symbols") or scanner_exception_truth.get("preserved_selected_symbols") or [])
            if str(s or "").strip()
        ]

    # If the latest successful scan explicitly says nothing was selected, do not resurrect stale lifecycle selections.
    if (
        not bool(scanner_exception_truth.get("active"))
        and explicit_selected_symbols_present
        and not symbols
        and int(explicit_selected_total or 0) <= 0
    ):
        return []

    if (
        not bool(scanner_exception_truth.get("active"))
        and not symbols
        and explicit_would_trade is not None
        and int(explicit_would_trade or 0) <= 0
    ):
        return []

    if not symbols:
        for row in list(summary.get("top_candidates") or []):
            if not isinstance(row, dict):
                continue
            cleaned = _p300_apply_executable_selection_contract(row)
            if bool(cleaned.get("selected")) and bool((cleaned.get("executable_sizing_truth") or {}).get("executable")):
                sym = str(cleaned.get("symbol") or "").strip().upper()
                if sym:
                    symbols.append(sym)

    if (
        not symbols
        and not explicit_selected_symbols_present
        and not (bool(SWING_PRODUCTION_CORE_CLEANUP_ENABLED) and bool(SWING_SELECTED_SYMBOL_SOURCE_STRICT_SCAN))
    ):
        for row in reversed(list(lifecycle_items or [])):
            if not isinstance(row, dict):
                continue
            if str(row.get("stage") or "").lower() == "candidate" and str(row.get("status") or "").lower() == "selected":
                sym = str(row.get("symbol") or "").strip().upper()
                if sym:
                    symbols.append(sym)
                    break

    return _dedupe_keep_order(symbols)

def _p330_after_hours_empty_selection_scan(latest_scan: dict | None, summary: dict | None) -> bool:
    scan = dict(latest_scan or {})
    summ = dict(summary or {})
    reason = str(scan.get("reason") or summ.get("reason") or "").strip().lower()
    selected_total = int(summ.get("selected_total") or len(summ.get("selected_symbols") or []) or 0)
    return bool(reason == "outside_market_hours" and selected_total <= 0)


def _p330_preserved_selected_submission_summary(latest_scan: dict | None, summary: dict | None) -> tuple[dict, dict, dict]:
    current_scan = dict(latest_scan or {})
    current_summary = dict(summary or {})
    if not _p330_after_hours_empty_selection_scan(current_scan, current_summary):
        return current_scan, current_summary, {
            "applied": False,
            "reason": "latest_scan_has_current_selection_context",
        }

    preserved = dict(LAST_SUCCESSFUL_PRODUCTION_SCAN or {})
    preserved_summary = dict(preserved.get("summary") or {})
    preserved_symbols = _p324_scan_selected_symbols(preserved)
    if not preserved or not preserved_symbols:
        return current_scan, current_summary, {
            "applied": False,
            "reason": "no_preserved_selected_production_scan_available",
        }

    preserved_scan = dict(preserved)
    preserved_scan["p330_after_hours_truth_source"] = "last_successful_production_scan"
    preserved_scan["p330_current_latest_scan"] = {
        "ts_utc": current_scan.get("ts_utc"),
        "reason": current_scan.get("reason"),
        "selected_total": int(current_summary.get("selected_total") or 0),
    }

    preserved_summary["p330_after_hours_truth_source"] = "last_successful_production_scan"
    preserved_summary["p330_after_hours_stability_applied"] = True
    preserved_summary["p330_current_latest_scan_reason"] = current_scan.get("reason")
    preserved_summary["p330_current_latest_scan_ts_utc"] = current_scan.get("ts_utc")

    return preserved_scan, preserved_summary, {
        "applied": True,
        "reason": "after_hours_empty_scan_replaced_with_last_successful_production_scan",
        "preserved_ts_utc": preserved.get("ts_utc"),
        "preserved_selected_symbols": preserved_symbols,
    }


def _p330_plan_execution_dt_ny(plan: dict | None):
    p = dict(plan or {})
    for key in ("submitted_at", "opened_at", "execution_updated_ny", "execution_updated_utc"):
        value = p.get(key)
        if not value:
            continue
        dt = _coerce_dt_ny(value)
        if dt:
            return dt
    return None


def _p330_filled_plan_execution_backfill_symbols() -> list[str]:
    symbols: list[str] = []
    today = now_ny().date()
    for sym, plan in dict(TRADE_PLAN or {}).items():
        symbol = str(sym or "").strip().upper()
        p = dict(plan or {})
        if not symbol:
            continue
        if not bool(p.get("active")):
            continue
        if not str(p.get("order_id") or "").strip():
            continue

        status = str(
            p.get("order_status")
            or p.get("execution_state")
            or p.get("lifecycle_state")
            or p.get("status")
            or ""
        ).strip().lower()
        if status not in {"filled", "submitted", "accepted", "partially_filled"}:
            continue

        dt_ny = _p330_plan_execution_dt_ny(p)
        if not dt_ny or dt_ny.date() != today:
            continue

        symbols.append(symbol)

    return _dedupe_keep_order(symbols)

def _p520_lifecycle_rate_limit_event(lifecycle_matches: list | None) -> dict:
    for row in reversed(list(lifecycle_matches or [])):
        if not isinstance(row, dict):
            continue
        details = row.get("details") if isinstance(row.get("details"), dict) else {}
        if (
            bool(row.get("rate_limited"))
            or bool(details.get("rate_limited"))
            or bool(row.get("retryable"))
            or bool(details.get("retryable"))
            or _p352_is_alpaca_rate_limit_error(row.get("reason"))
            or _p352_is_alpaca_rate_limit_error(row.get("status"))
            or _p352_is_alpaca_rate_limit_error(row.get("error"))
            or _p352_is_alpaca_rate_limit_error(details.get("reason"))
            or _p352_is_alpaca_rate_limit_error(details.get("error"))
        ):
            return dict(row)
    return {}

def _p298_selected_submission_truth_light() -> dict:
    latest_scan, summary = _p298_latest_scan_summary_light()
    latest_scan, summary, p330_after_hours_truth = _p330_preserved_selected_submission_summary(latest_scan, summary)

    lifecycle_items = _p298_recent_lifecycle_items(limit=100)
    selected_symbols = _p298_selected_symbols_light(summary, lifecycle_items)

    p330_filled_plan_backfill_symbols = _p330_filled_plan_execution_backfill_symbols()
    selected_symbols = _dedupe_keep_order(list(selected_symbols or []) + p330_filled_plan_backfill_symbols)

    submit_rows = {
        str((row or {}).get("symbol") or "").strip().upper(): dict(row or {})
        for row in list(summary.get("selected_submission_rows") or summary.get("would_submit") or [])
        if str((row or {}).get("symbol") or "").strip()
    }
    current_candidate_truth = _p406_fast_current_candidate_payload(limit=100)
    current_candidate_by_symbol = {
        str((row or {}).get("symbol") or "").strip().upper(): dict(row or {})
        for row in list(current_candidate_truth.get("candidate_rows") or [])
        if isinstance(row, dict) and str((row or {}).get("symbol") or "").strip()
    }

    open_symbols = set(_p404_active_position_symbols_light())
    raw_selected_symbols_before_echo_suppression = list(selected_symbols)
    submitted_then_active_symbols = [
        sym for sym in selected_symbols
        if sym in open_symbols
        and sym in submit_rows
        and bool((submit_rows.get(sym) or {}).get("actual_submit_side_effect"))
    ]
    submitted_then_active_set = set(submitted_then_active_symbols)
    open_position_echo_symbols = [
        sym for sym in selected_symbols
        if sym in open_symbols
        and sym not in submitted_then_active_set
    ]
    open_position_echo_set = set(open_position_echo_symbols)
    selected_symbols = [
        sym for sym in selected_symbols
        if sym not in open_position_echo_set
    ]
    p524_selection_revalidation = _p524_revalidate_current_selected_symbols(
        selected_symbols,
        current_candidate_truth,
        preserve_symbols=_dedupe_keep_order(list(submit_rows.keys()) + list(open_symbols)),
    )
    p524_stale_selected_symbols = set(p524_selection_revalidation.get("stale_symbols") or [])
    if p524_stale_selected_symbols:
        selected_symbols = [
            sym for sym in selected_symbols
            if sym not in p524_stale_selected_symbols
        ]

    rows = []
    for sym in selected_symbols:
        lifecycle_matches = [
            dict(row or {})
            for row in lifecycle_items
            if str((row or {}).get("symbol") or "").strip().upper() == sym
        ]
        lifecycle_submit_evidence = [
            row for row in lifecycle_matches
            if str(row.get("stage") or "").lower() in {"entry", "submit", "order"}
            or "submitted" in str(row.get("status") or "").lower()
            or "accepted" in str(row.get("status") or "").lower()
            or "filled" in str(row.get("status") or "").lower()
            or "order" in str(row.get("status") or "").lower()
        ]
        candidate_selected_only_events = [
            row for row in lifecycle_matches
            if str(row.get("stage") or "").lower() == "candidate"
            and str(row.get("status") or "").lower() == "selected"
        ]
        submit_row = dict(submit_rows.get(sym) or {})
        candidate_row = dict(current_candidate_by_symbol.get(sym) or {})
        lifecycle_rate_limit_event = _p520_lifecycle_rate_limit_event(lifecycle_matches)
        if not submit_row and lifecycle_rate_limit_event:
            lifecycle_details = lifecycle_rate_limit_event.get("details") if isinstance(lifecycle_rate_limit_event.get("details"), dict) else {}
            lifecycle_reason = (
                lifecycle_rate_limit_event.get("reason")
                or lifecycle_details.get("reason")
                or lifecycle_rate_limit_event.get("error")
                or lifecycle_details.get("error")
                or "alpaca_submit_rate_limited"
            )
            submit_row = dict(candidate_row or {})
            submit_row.update({
                "symbol": sym,
                "signal": submit_row.get("signal") or submit_row.get("strategy") or "daily_breakout",
                "submit_state": "retryable_rate_limit",
                "submit_reason": lifecycle_reason,
                "reason": lifecycle_reason,
                "submit_attempted": True,
                "actual_submit_side_effect": False,
                "rate_limited": True,
                "retryable": True,
                "p520_lifecycle_rate_limit_rehydrated": True,
                "p520_lifecycle_rate_limit_event": dict(lifecycle_rate_limit_event),
            })
        plan_snapshot = dict((TRADE_PLAN or {}).get(sym) or {})
        submit_meta = {
            "state": submit_row.get("submit_state"),
            "reason": submit_row.get("submit_reason"),
            "attempted": bool(submit_row.get("submit_attempted")),
            "order_id": submit_row.get("order_id") or submit_row.get("submit_order_id"),
        }
        submit_reason_norm = str(
            submit_meta.get("reason")
            or submit_row.get("reason")
            or ""
        ).strip().lower()
        submit_state_norm = str(submit_meta.get("state") or submit_row.get("state") or "").strip().lower()
        after_hours_selected_not_submitted = bool(
            submit_reason_norm in {"outside_market_hours", "outside_scanner_session", "market_closed"}
            or (
                bool(submit_row.get("ignored"))
                and submit_reason_norm in {"outside_market_hours", "outside_scanner_session", "market_closed"}
            )
            or (
                submit_state_norm in {"ignored", "skipped"}
                and submit_reason_norm in {"outside_market_hours", "outside_scanner_session", "market_closed"}
            )
        )
        side_effect = _p312_scan_submit_side_effect(sym, submit_meta=submit_meta, resp=submit_row)
        execution_quality_blocked = _p366_submit_execution_quality_blocked(
            submit_meta.get("state"),
            submit_meta.get("reason"),
        )
        retryable_spread_block = _p366_retryable_spread_block(
            sym,
            submit_row.get("signal") or submit_row.get("strategy") or "daily_breakout",
            submit_meta.get("state"),
            submit_meta.get("reason"),
        )
        rate_limited_retryable = bool(
            _p398_submit_row_rate_limited(submit_row, submit_meta=submit_meta)
        )
        rate_limit_retry_key = _p387_rate_limit_retry_key(
            sym,
            submit_row.get("signal") or submit_row.get("strategy") or "daily_breakout",
        )
        rate_limit_retry_queued = bool(rate_limit_retry_key in P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE)
        rate_limit_retry_queue_backfill = {"queued": False, "reason": "not_needed"}

        if (
            rate_limited_retryable
            and not rate_limit_retry_queued
            and submit_row
            and not bool(side_effect.get("actual_submit_side_effect"))
        ):
            rate_limit_retry_queue_backfill = _p387_queue_rate_limited_selected_submit(
                submit_row,
                submit_row,
            )
            rate_limit_retry_queued = bool(rate_limit_retry_key in P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE)

        submit_gap = bool(
            not side_effect.get("actual_submit_side_effect")
            and not execution_quality_blocked
            and not bool(retryable_spread_block.get("retryable"))
            and not rate_limited_retryable
            and not after_hours_selected_not_submitted
        )
        submit_gap_type = (
            "none"
            if bool(side_effect.get("actual_submit_side_effect"))
            else "after_hours_selected_not_submitted"
            if after_hours_selected_not_submitted
            else "rate_limited_retryable"
            if rate_limited_retryable
            else "spread_retryable"
            if bool(retryable_spread_block.get("retryable"))
            else "execution_quality_blocked"
            if execution_quality_blocked
            else "unattempted"
            if not bool(submit_meta.get("attempted"))
            else "terminal_failed"
            if submit_gap
            else "none"
        )
        retry_evidence_status = (
            "resolved_by_active_plan_or_submit_side_effect"
            if bool(side_effect.get("actual_submit_side_effect"))
            else "after_hours_selected_not_submitted"
            if after_hours_selected_not_submitted
            else "waiting_for_rate_limit_retry"
            if rate_limited_retryable
            else "waiting_for_spread_retry"
            if bool(retryable_spread_block.get("retryable"))
            else "blocked_by_execution_quality"
            if execution_quality_blocked
            else "submit_gap_unattempted"
            if submit_gap_type == "unattempted"
            else "submit_gap_terminal_failed"
            if submit_gap_type == "terminal_failed"
            else "no_retry_evidence_needed"
        )

        rows.append({
            "symbol": sym,
            "submitted_then_active": bool(sym in submitted_then_active_set),
            "selection_truth_status": (
                "submitted_then_active"
                if sym in submitted_then_active_set
                else "selected_pending_submit_truth"
            ),
            "p330_evidence_source": (
                "filled_active_plan_backfill"
                if sym in p330_filled_plan_backfill_symbols and not submit_row
                else "scan_selected_submission_row"
                if submit_row
                else "selected_symbol_side_effect_check"
            ),
            "p330_after_hours_truth_applied": bool(p330_after_hours_truth.get("applied")),
            "p330_filled_plan_backfill": bool(sym in p330_filled_plan_backfill_symbols),
            "side_effect_detected_light": bool(side_effect.get("actual_submit_side_effect")),
            "actual_submit_side_effect": bool(side_effect.get("actual_submit_side_effect")),
            "candidate_selected_only": bool(candidate_selected_only_events and not side_effect.get("actual_submit_side_effect")),
            "after_hours_selected_not_submitted": bool(after_hours_selected_not_submitted),
            "submit_gap": bool(submit_gap),
            "submit_gap_type": submit_gap_type,
            "rate_limited_retryable": bool(rate_limited_retryable),
            "p520_lifecycle_rate_limit_rehydrated": bool(submit_row.get("p520_lifecycle_rate_limit_rehydrated")),
            "p520_lifecycle_rate_limit_event": dict(lifecycle_rate_limit_event or {}),
            "rate_limit_retry_key": rate_limit_retry_key,
            "rate_limit_retry_queued": bool(rate_limit_retry_queued),
            "rate_limit_retry_queue_backfill": rate_limit_retry_queue_backfill,
            "rate_limit_retry_queue_row": dict(P387_RATE_LIMIT_SELECTED_SUBMIT_RETRY_QUEUE.get(rate_limit_retry_key) or {}),
            "execution_quality_blocked": bool(execution_quality_blocked),
            "retryable_spread_block": retryable_spread_block,
            "retry_evidence_status": retry_evidence_status,
            "reasons": list(side_effect.get("side_effect_reasons") or []),
            "active_plan": bool(side_effect.get("active_plan")),
            "pending_entry_plan": bool(side_effect.get("pending_entry_plan")),
            "plan_status": side_effect.get("plan_status"),
            "plan_source": side_effect.get("plan_source"),
            "submit_state": side_effect.get("submit_state"),
            "submit_reason": submit_row.get("submit_reason"),
            "submit_attempted": bool(submit_row.get("submit_attempted")),
            "submit_order_id": side_effect.get("submit_order_id"),
            "plan_order_id": plan_snapshot.get("order_id"),
            "plan_order_type": plan_snapshot.get("order_type"),
            "plan_limit_price": plan_snapshot.get("limit_price"),
            "plan_order_status": plan_snapshot.get("order_status"),
            "plan_filled_qty": plan_snapshot.get("filled_qty"),
            "plan_avg_fill_price": plan_snapshot.get("avg_fill_price") or plan_snapshot.get("filled_avg_price"),
            "plan_limit_entry": dict(plan_snapshot.get("limit_entry") or {}),
            "recent_lifecycle_count": len(lifecycle_matches),
            "recent_submit_event_count": len(lifecycle_submit_evidence),
            "lifecycle_submit_evidence_only": bool(lifecycle_submit_evidence and not side_effect.get("actual_submit_side_effect")),
            "candidate_selected_only_count": len(candidate_selected_only_events),
            "last_lifecycle_event": lifecycle_matches[-1] if lifecycle_matches else None,
            "scan_submit_row": submit_row or None,
        })

    out = swing_diag_selected_submission_truth_light_snapshot(
        patch_version=PATCH_VERSION,
        latest_scan=latest_scan,
        selected_symbols=selected_symbols,
        rows=rows,
    )
    eligible_new_entry_symbols = _p413_eligible_new_entry_symbols_from_fast_payload(current_candidate_truth)

    out["p330_after_hours_truth"] = p330_after_hours_truth
    out["p330_filled_plan_backfill_symbols"] = p330_filled_plan_backfill_symbols
    out["p330_filled_plan_backfill_count"] = len(p330_filled_plan_backfill_symbols)
    out["open_position_echo_suppression"] = {
        "applied": bool(open_position_echo_symbols),
        "raw_selected_symbols_before_echo_suppression": raw_selected_symbols_before_echo_suppression,
        "stale_open_position_echo_symbols": open_position_echo_symbols,
        "submitted_then_active_symbols_preserved": submitted_then_active_symbols,
        "selected_symbols_after_echo_suppression": selected_symbols,
    }
    out["submitted_then_active_truth"] = {
        "count": len(submitted_then_active_symbols),
        "symbols": submitted_then_active_symbols,
        "status": (
            "submitted_then_active_present"
            if submitted_then_active_symbols
            else "none"
        ),
    }
    out["p524_selection_revalidation"] = p524_selection_revalidation
    out["stale_revalidated_blocked_symbols"] = list(p524_stale_selected_symbols)
    out["stale_revalidated_blocked_count"] = len(p524_stale_selected_symbols)
    out["eligible_new_entry_truth"] = {
        "count": len(eligible_new_entry_symbols),
        "symbols": eligible_new_entry_symbols,
        "not_selected_symbols": [
            sym for sym in eligible_new_entry_symbols
            if sym not in set(selected_symbols)
        ],
        "status": (
            "eligible_new_entry_not_selected"
            if eligible_new_entry_symbols and not selected_symbols
            else "selected_symbols_present"
            if selected_symbols
            else "no_eligible_new_entry"
        ),
    }
    after_hours_selected_symbols = list(out.get("after_hours_selected_symbols") or [])
    out["next_open_carry_forward_truth"] = {
        "enabled": True,
        "symbols": after_hours_selected_symbols,
        "count": len(after_hours_selected_symbols),
        "does_not_submit_after_hours": True,
        "requires_fresh_next_open_scan": bool(after_hours_selected_symbols),
        "reason": (
            "after_hours_selected_candidate_requires_next_open_recheck"
            if after_hours_selected_symbols
            else "no_after_hours_selected_candidate"
        ),
    }
    if submitted_then_active_symbols:
        out["recommended_action"] = "selected_symbols_have_actual_submit_side_effect"
    elif after_hours_selected_symbols:
        out["recommended_action"] = "after_hours_selected_not_submitted_monitor_next_open"
    elif p524_stale_selected_symbols and not selected_symbols:
        out["recommended_action"] = "stale_selected_candidate_revalidated_blocked"
    elif eligible_new_entry_symbols and not selected_symbols:
        out["recommended_action"] = "scheduled_scanner_should_promote_current_eligible_contract_rows"
    return out

def _p482_tombstone_historical_background_failure(background_truth: dict | None) -> dict:
    return swing_scan_state_tombstone_background_failure(background_truth)

def _p298_scanner_light() -> dict:
    tel = dict(LAST_SCANNER_TELEMETRY or {})
    latest_scan, summary = _p298_latest_scan_summary_light()
    today_prefix = str(now_ny().date())
    telemetry_summary = _scanner_telemetry_summary(today_prefix=today_prefix)

    latest_scan = _p464_sanitize_persisted_over_budget_scan(dict(latest_scan or {}), source="scanner_light_latest_scan")
    latest_scan = _p475_normalize_scan_truth_contract(latest_scan, source="scanner_light")
    p475_latest_truth = dict(latest_scan.get("p475_scan_truth_contract") or {})
    background_truth = dict(_p456_background_scan_truth() or {})
    sanitized_background_wrapper = _p464_sanitize_persisted_over_budget_scan(
        {"reason": background_truth.get("reason") or "scan_completed", "scan_background_completion_truth": background_truth},
        source="scanner_light_background_truth",
    )
    background_truth = dict(sanitized_background_wrapper.get("scan_background_completion_truth") or background_truth)
    background_truth = _p482_tombstone_historical_background_failure(background_truth)
    p469_release_gate_cache_truth = {
        "cached": bool(P469_RELEASE_GATE_SNAPSHOT_CACHE),
        "cached_utc": (P469_RELEASE_GATE_SNAPSHOT_CACHE or {}).get("cached_utc"),
        "ttl_sec": int(P469_RELEASE_GATE_SNAPSHOT_TTL_SEC),
        "live_orders_permitted": ((P469_RELEASE_GATE_SNAPSHOT_CACHE or {}).get("status") or {}).get("live_orders_permitted"),
        "go_live_eligible": ((P469_RELEASE_GATE_SNAPSHOT_CACHE or {}).get("status") or {}).get("go_live_eligible"),
        "unmet_conditions": list(((P469_RELEASE_GATE_SNAPSHOT_CACHE or {}).get("status") or {}).get("unmet_conditions") or []),
    }

    latest_scan["scanner_exception_truth"] = summary.get("scanner_exception_truth")
    latest_scan["using_last_successful_production_scan"] = bool(summary.get("using_last_successful_production_scan"))
    latest_scan["scan_background_completion_truth"] = background_truth
    latest_scan["p469_release_gate_cache_truth"] = dict(p469_release_gate_cache_truth)
    latest_scan["candidate_bearing_scan"] = bool(p475_latest_truth.get("candidate_bearing"))
    latest_scan["trade_judgable"] = bool(p475_latest_truth.get("trade_judgable"))
    latest_scan["regime_only_non_actionable"] = bool(p475_latest_truth.get("regime_only_non_actionable"))
    latest_scan["p481_canonical_scan_truth"] = dict(latest_scan.get("_p481_canonical_scan_truth") or {})
    latest_scan["after_hours_does_not_replace_candidate_truth"] = bool(
        (latest_scan.get("_p481_canonical_scan_truth") or {}).get("after_hours_does_not_replace_candidate_truth")
    )
    latest_scan["swing_scan_state_module_version"] = SWING_SCAN_STATE_MODULE_VERSION
    latest_scan["swing_scan_state_module_status"] = swing_scan_state_module_status(patch_version=PATCH_VERSION)
    latest_scan = swing_candidate_eval_attach_status(latest_scan, patch_version=PATCH_VERSION)
    summary["scan_background_completion_truth"] = background_truth
    summary["p469_release_gate_cache_truth"] = dict(p469_release_gate_cache_truth)
    summary["candidate_bearing_scan"] = bool(p475_latest_truth.get("candidate_bearing"))
    summary["trade_judgable"] = bool(p475_latest_truth.get("trade_judgable"))
    summary["regime_only_non_actionable"] = bool(p475_latest_truth.get("regime_only_non_actionable"))
    summary["p475_scan_truth_contract"] = dict(p475_latest_truth)
    summary["p481_canonical_scan_truth"] = dict(latest_scan.get("_p481_canonical_scan_truth") or {})
    summary["swing_scan_state_module_version"] = SWING_SCAN_STATE_MODULE_VERSION
    summary = swing_candidate_eval_attach_status(summary, patch_version=PATCH_VERSION)

    p525_current_candidate_truth = _p406_fast_current_candidate_payload(limit=100)
    p525_selected_symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(summary.get("selected_symbols") or latest_scan.get("selected_symbols") or [])
        if str(sym or "").strip()
    ])
    p525_submit_rows = [
        dict(row or {})
        for row in list(summary.get("selected_submission_rows") or summary.get("would_submit") or latest_scan.get("would_submit") or [])
        if isinstance(row, dict)
    ]
    p525_terminal_evidence_symbols = _dedupe_keep_order([
        str((row or {}).get("symbol") or "").strip().upper()
        for row in p525_submit_rows
        if str((row or {}).get("symbol") or "").strip()
    ] + [
        str(sym or "").strip().upper()
        for sym, plan in dict(TRADE_PLAN or {}).items()
        if str(sym or "").strip()
        and isinstance(plan, dict)
        and (bool(plan.get("active")) or _plan_is_pending_entry(plan))
    ])
    p525_selection_revalidation = _p524_revalidate_current_selected_symbols(
        p525_selected_symbols,
        p525_current_candidate_truth,
        preserve_symbols=p525_terminal_evidence_symbols,
    )
    p525_active_selected_symbols = list(p525_selection_revalidation.get("active_symbols") or [])
    p525_stale_selected_symbols = list(p525_selection_revalidation.get("stale_symbols") or [])
    if p525_stale_selected_symbols:
        for target in (summary, latest_scan):
            target["p525_scanner_selection_revalidation"] = dict(p525_selection_revalidation)
            target["stale_revalidated_blocked_symbols"] = list(p525_stale_selected_symbols)
            target["selected_symbols_before_p525_revalidation"] = list(p525_selected_symbols)
            target["selected_symbols"] = list(p525_active_selected_symbols)
            target["production_contract_selected_symbols"] = list(p525_active_selected_symbols)
            target["selected_total"] = len(p525_active_selected_symbols)
            target["would_trade"] = len(p525_active_selected_symbols)
            target["selected_submit_gap_symbols"] = [
                sym for sym in list(target.get("selected_submit_gap_symbols") or [])
                if str(sym or "").strip().upper() not in set(p525_stale_selected_symbols)
            ]
            target["selected_submit_gap_count"] = len(target.get("selected_submit_gap_symbols") or [])
            target["selected_submit_gap_active"] = bool(target.get("selected_submit_gap_symbols"))
        summary["p525_scanner_latest_scan_selection_scrubbed"] = True
    else:
        summary["p525_scanner_latest_scan_selection_scrubbed"] = False
        summary["p525_scanner_selection_revalidation"] = dict(p525_selection_revalidation)

    telemetry_summary = _p325_recover_scanner_warning_summary(
        telemetry_summary,
        latest_scan,
        telemetry=tel,
    )

    return swing_diag_scanner_light_snapshot(
        patch_version=PATCH_VERSION,
        telemetry=tel,
        telemetry_summary=telemetry_summary,
        latest_scan=latest_scan,
        scan_summary=summary,
        in_flight_grace_sec=int(SCANNER_LIGHT_IN_FLIGHT_GRACE_SEC),
        scan_runtime_budget_sec=int(SCAN_RUNTIME_BUDGET_SEC),
    )


