def _live_loss_halt_checklist(halt_truth: dict | None, today_pnl: dict | None, flatten_decision: dict | None, open_orders: list | None = None) -> dict:
    halt = dict(halt_truth or {})
    pnl = dict(today_pnl or halt.get("today_pnl_truth") or {})
    decision = dict(flatten_decision or {})
    realized_halt = dict(halt.get("realized_closed_trade_loss_halt") or _p229_realized_closed_trade_loss_halt(pnl_truth=pnl))
    active = bool(halt.get("daily_halt_active") or daily_halt_active() or realized_halt.get("active"))
    new_entries_blocked = bool(active or (not NEW_ENTRIES_ENABLED) or (not is_live_trading_permitted("worker_scan")))
    exits_still_permitted = bool(is_live_exit_permitted("worker_exit", reason="daily_stop_hit" if active else ""))
    bulk_flatten_allowed = bool(decision.get("allow_bulk_flatten", globals().get("ALLOW_DAILY_STOP_BULK_FLATTEN", False)))
    recommended = []
    if active:
        recommended.extend(["monitor_existing_positions", "verify_open_orders", "do_not_enable_new_entries", "review_after_close"])
    elif open_orders:
        recommended.append("verify_open_orders")
    else:
        recommended.append("monitor")
    return {
        "daily_halt_active": active,
        "daily_halt_reason": halt.get("daily_halt_reason") or (DAILY_HALT_STATE or {}).get("reason") or "none",
        "account_daily_pnl": halt.get("account_daily_pnl") if halt.get("account_daily_pnl") is not None else pnl.get("account_daily_pnl"),
        "today_realized_pnl": pnl.get("today_realized_pnl"),
        "today_unrealized_pnl": pnl.get("today_unrealized_pnl"),
        "configured_daily_stop_dollars": halt.get("configured_daily_stop_dollars") or _configured_daily_stop_dollars_safe(),
        "realized_closed_trade_loss_halt": realized_halt,
        "new_entries_blocked": new_entries_blocked,
        "exits_still_permitted": exits_still_permitted,
        "bulk_flatten_allowed": bulk_flatten_allowed,
        "can_bulk_flatten_now": bool(decision.get("can_flatten", False)),
        "flatten_decision_reasons": list(decision.get("reasons") or []),
        "recommended_actions": recommended,
        "recommended_action": recommended[0],
        "open_order_count": len(list(open_orders or [])),
    }

def _p245_defensive_open_position_guard(symbol: str, plan: dict | None, pos: dict | None) -> dict:
    sym = str(symbol or "").upper()
    p = dict(plan or {})
    broker = dict(pos or {})
    signal = str(p.get("signal") or p.get("strategy_name") or "").strip().lower()
    mode = str(p.get("regime_mode") or ((p.get("thesis") or {}) if isinstance(p.get("thesis"), dict) else {}).get("regime_mode") or "").strip().lower()
    entry = _safe_float(broker.get("avg_entry_price") or p.get("entry_price") or p.get("avg_fill_price"), 0.0)
    stop = _safe_float(p.get("stop_price") or p.get("initial_stop_price"), 0.0)
    last = _safe_float(broker.get("current_price") or broker.get("last_price") or 0.0, 0.0)
    risk_pct = ((entry - stop) / max(entry, 1e-9)) if entry > 0 and stop > 0 else 0.0
    unrealized = _safe_float(broker.get("unrealized_pl"), 0.0)
    reasons = []

    if signal == BREAKOUT_STRATEGY_NAME and mode == "defensive":
        if risk_pct > float(SWING_DEFENSIVE_MAX_RISK_PER_SHARE_PCT):
            reasons.append("open_defensive_risk_per_share_above_patch245_guard")
        if last > 0 and stop > 0:
            distance_to_stop_pct = (last - stop) / max(last, 1e-9)
            if distance_to_stop_pct <= 0.01:
                reasons.append("open_defensive_near_stop")
        if unrealized < 0:
            reasons.append("open_defensive_unrealized_negative")

    return {
        "symbol": sym,
        "enabled": bool(SWING_DEFENSIVE_ENTRY_TIGHTENING_ENABLED),
        "advisory_only": True,
        "triggered": bool(reasons),
        "reasons": reasons,
        "entry_price": round(entry, 4) if entry > 0 else None,
        "last_price": round(last, 4) if last > 0 else None,
        "stop_price": round(stop, 4) if stop > 0 else None,
        "risk_per_share_pct": round(risk_pct * 100.0, 4),
        "unrealized_pl": round(unrealized, 4),
        "recommended_action": "monitor_tight_exit_behavior" if reasons else "none",
    }

def _p246_entry_quality_memory_guard(symbol: str, plan: dict | None, pos: dict | None) -> dict:
    sym = str(symbol or "").upper()
    p = dict(plan or {})
    thesis = dict(p.get("thesis") or {}) if isinstance(p.get("thesis"), dict) else {}
    snap = dict(thesis.get("entry_quality_snapshot") or {}) if isinstance(thesis.get("entry_quality_snapshot"), dict) else {}
    broker = dict(pos or {})

    mode = str(snap.get("regime_mode") or thesis.get("regime_mode") or p.get("regime_mode") or "").strip().lower()
    strategy = str(snap.get("strategy") or p.get("strategy_name") or p.get("signal") or "").strip().lower()
    return_20d = _safe_float(snap.get("return_20d_pct"), 0.0)
    risk_pct = _safe_float(snap.get("risk_per_share_pct"), 0.0)
    breakout_distance = _safe_float(snap.get("breakout_distance_pct"), 0.0)
    rank_score = snap.get("rank_score") if snap.get("rank_score") is not None else thesis.get("candidate_rank_score")
    reasons = []

    has_snapshot = bool(snap)
    if strategy == BREAKOUT_STRATEGY_NAME and mode == "defensive":
        if has_snapshot:
            if float(SWING_DEFENSIVE_MAX_20D_RETURN_PCT) > 0 and return_20d > float(SWING_DEFENSIVE_MAX_20D_RETURN_PCT) * 100.0:
                reasons.append("entry_memory_defensive_20d_return_too_extended")
            if float(SWING_DEFENSIVE_MAX_RISK_PER_SHARE_PCT) > 0 and risk_pct > float(SWING_DEFENSIVE_MAX_RISK_PER_SHARE_PCT) * 100.0:
                reasons.append("entry_memory_defensive_risk_per_share_too_wide")
        else:
            reasons.append("entry_quality_snapshot_missing")

    unrealized = _safe_float(broker.get("unrealized_pl"), 0.0)
    if unrealized < 0 and reasons:
        reasons.append("open_position_negative_with_entry_quality_warning")

    return {
        "symbol": sym,
        "enabled": True,
        "advisory_only": True,
        "has_entry_quality_snapshot": has_snapshot,
        "triggered": bool(reasons),
        "reasons": reasons,
        "entry_snapshot": {
            "strategy": strategy or None,
            "regime_mode": mode or None,
            "rank_score": rank_score,
            "return_20d_pct": return_20d if has_snapshot else None,
            "risk_per_share_pct": risk_pct if has_snapshot else None,
            "breakout_distance_pct": breakout_distance if has_snapshot else None,
            "defensive_tightening_enabled": snap.get("defensive_tightening_enabled"),
        },
        "current_unrealized_pl": round(unrealized, 4),
        "recommended_action": "monitor_or_tighten_exit_only" if reasons else "none",
    }


def _p246_entry_quality_memory_snapshot() -> dict:
    rows = []
    for sym, plan in list((TRADE_PLAN or {}).items()):
        if not isinstance(plan, dict) or not plan.get("active"):
            continue
        symbol = str(sym or plan.get("symbol") or "").upper()
        pos = {}
        try:
            for row in list_open_positions_details_allowed() or []:
                if str((row or {}).get("symbol") or "").upper() == symbol:
                    pos = dict(row or {})
                    break
        except Exception:
            pos = {}
        rows.append(_p246_entry_quality_memory_guard(symbol, plan, pos))
    triggered = [r for r in rows if r.get("triggered")]
    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "read_only_entry_quality_memory_guard",
        "active_position_count": len(rows),
        "triggered_count": len(triggered),
        "triggered_symbols": [r.get("symbol") for r in triggered],
        "rows": rows,
        "recommended_action": "review_triggered_positions_exit_plan" if triggered else "none",
    }

def _p250_entry_quality_exit_advisory(symbol: str, plan: dict | None, pos: dict | None) -> dict:
    sym = str(symbol or "").upper()
    p = dict(plan or {})
    broker = dict(pos or {})

    entry = _safe_float(
        broker.get("avg_entry_price")
        or p.get("entry_price")
        or p.get("avg_fill_price")
        or 0.0
    )
    last = _safe_float(
        broker.get("current_price")
        or broker.get("last_price")
        or p.get("last_price")
        or p.get("entry_price")
        or 0.0
    )
    stop = _safe_float(p.get("stop_price") or p.get("initial_stop_price") or 0.0)
    target = _safe_float(p.get("take_price") or p.get("target_price") or 0.0)
    qty = _safe_float(broker.get("qty") or p.get("qty") or p.get("quantity") or 0.0)
    side = str(p.get("side") or broker.get("side") or "buy").strip().lower()

    risk = _plan_risk_per_share(p)
    if risk <= 0 and entry > 0 and stop > 0:
        risk = abs(entry - stop)

    current_r = None
    if entry > 0 and last > 0 and risk > 0:
        if side in {"sell", "short"}:
            current_r = (entry - last) / risk
        else:
            current_r = (last - entry) / risk

    distance_to_stop_pct = None
    if last > 0 and stop > 0:
        distance_to_stop_pct = ((last - stop) / last) * 100.0

    distance_to_target_pct = None
    if last > 0 and target > 0:
        distance_to_target_pct = ((target - last) / last) * 100.0

    days_held = plan_days_held(p)
    memory_guard = _p246_entry_quality_memory_guard(sym, p, broker)

    stall_containment = _p286_target_path_stall_containment(p, days_held, current_r)
    stall_loss_guard_due = (
        bool(SWING_STALL_LOSS_GUARD_ENABLED)
        and current_r is not None
        and int(days_held or 0) >= int(stall_containment.get("effective_guard_days") or SWING_STALL_LOSS_GUARD_DAYS or 0)
        and float(current_r) <= float(stall_containment.get("effective_max_loss_r") or SWING_STALL_MAX_LOSS_R or -0.60)
    )
    stall_exit_due = (
        current_r is not None
        and int(SWING_STALL_EXIT_DAYS or 0) > 0
        and int(days_held or 0) >= int(SWING_STALL_EXIT_DAYS or 0)
        and float(current_r) < float(SWING_STALL_MIN_R or 0.0)
    )
    opening_damage_due = (
        current_r is not None
        and bool(SWING_OPENING_DAMAGE_GUARD_ENABLED)
        and float(current_r) <= float(SWING_OPENING_DAMAGE_MAX_LOSS_R or -1.10)
    )
    near_stop = distance_to_stop_pct is not None and distance_to_stop_pct <= 1.0

    reasons = []
    if memory_guard.get("triggered"):
        reasons.append("entry_quality_memory_flagged")
    if current_r is not None and current_r < 0:
        reasons.append("position_negative_r")
    if near_stop:
        reasons.append("within_1pct_of_stop")
    if stall_loss_guard_due:
        reasons.append("stall_loss_guard_due")
    if stall_exit_due:
        reasons.append("stall_exit_due")
    if opening_damage_due:
        reasons.append("opening_damage_guard_due")

    if stall_loss_guard_due or opening_damage_due:
        recommended_action = "exit_guard_likely_or_active"
    elif memory_guard.get("triggered") and (near_stop or (current_r is not None and current_r <= -0.50)):
        recommended_action = "tighten_exit_review"
    elif stall_exit_due:
        recommended_action = "stall_exit_review"
    elif memory_guard.get("triggered"):
        recommended_action = "monitor_flagged_entry"
    else:
        recommended_action = "allow_normal_hold"

    return {
        "symbol": sym,
        "mode": "read_only_entry_quality_exit_advisory",
        "advisory_only": True,
        "qty": round(qty, 6),
        "side": side,
        "entry_price": round(entry, 4) if entry > 0 else None,
        "last_price": round(last, 4) if last > 0 else None,
        "stop_price": round(stop, 4) if stop > 0 else None,
        "target_price": round(target, 4) if target > 0 else None,
        "risk_per_share": round(risk, 4) if risk > 0 else None,
        "current_r": round(float(current_r), 4) if current_r is not None else None,
        "days_held": int(days_held or 0),
        "distance_to_stop_pct": round(distance_to_stop_pct, 4) if distance_to_stop_pct is not None else None,
        "distance_to_target_pct": round(distance_to_target_pct, 4) if distance_to_target_pct is not None else None,
        "entry_quality_memory_guard": memory_guard,
        "stall_projection": {
            "stall_loss_guard_enabled": bool(SWING_STALL_LOSS_GUARD_ENABLED),
            "stall_loss_guard_days": int(SWING_STALL_LOSS_GUARD_DAYS or 0),
            "stall_max_loss_r": float(SWING_STALL_MAX_LOSS_R or 0.0),
            "target_path_stall_containment": dict(stall_containment),
            "stall_exit_days": int(SWING_STALL_EXIT_DAYS or 0),
            "stall_min_r": float(SWING_STALL_MIN_R or 0.0),
            "stall_loss_guard_due": bool(stall_loss_guard_due),
            "stall_exit_due": bool(stall_exit_due),
        },
        "opening_damage_projection": {
            "enabled": bool(SWING_OPENING_DAMAGE_GUARD_ENABLED),
            "max_loss_r": float(SWING_OPENING_DAMAGE_MAX_LOSS_R or 0.0),
            "guard_due": bool(opening_damage_due),
        },
        "triggered": bool(reasons),
        "reasons": reasons,
        "recommended_action": recommended_action,
    }


def _p250_entry_quality_exit_advisory_snapshot() -> dict:
    rows = []
    broker_by_symbol = {}

    try:
        for row in list_open_positions_details_allowed() or []:
            sym = str((row or {}).get("symbol") or "").upper()
            if sym:
                broker_by_symbol[sym] = dict(row or {})
    except Exception:
        broker_by_symbol = {}

    symbols = sorted({
        str(sym or "").upper()
        for sym, plan in (TRADE_PLAN or {}).items()
        if isinstance(plan, dict) and bool(plan.get("active"))
    } | set(broker_by_symbol.keys()))

    for sym in symbols:
        plan = dict((TRADE_PLAN or {}).get(sym) or {})
        pos = broker_by_symbol.get(sym) or {}
        if not plan and not pos:
            continue
        rows.append(_p250_entry_quality_exit_advisory(sym, plan, pos))

    tighten = [r for r in rows if r.get("recommended_action") in {"tighten_exit_review", "exit_guard_likely_or_active", "stall_exit_review"}]
    flagged = [r for r in rows if bool((r.get("entry_quality_memory_guard") or {}).get("triggered"))]

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "read_only_entry_quality_flagged_exit_advisory_stall_projection",
        "active_position_count": len(rows),
        "entry_quality_flagged_count": len(flagged),
        "tighten_review_count": len(tighten),
        "flagged_symbols": [r.get("symbol") for r in flagged],
        "tighten_review_symbols": [r.get("symbol") for r in tighten],
        "rows": rows,
        "recommended_action": "review_tighten_candidates" if tighten else ("monitor_flagged_entries" if flagged else "none"),
    }

def _p251_today_symbol_loss_cooldown_rows(state: dict | None = None) -> list[dict]:
    preferred = _p245_broker_preferred_closed_rows(state or STRATEGY_PERFORMANCE_STATE)
    rows = []
    today = now_ny().date()

    for row in list(preferred.get("kept_rows") or []):
        r = dict(row or {})
        sym = str(r.get("symbol") or "").strip().upper()
        if not sym:
            continue

        ts = _p175_parse_dt(r.get("ts_utc") or r.get("closed_at") or r.get("exit_ts_utc"))
        if not ts:
            continue
        if ts.astimezone(NY_TZ).date() != today:
            continue

        pnl = _safe_float(r.get("gross_pnl"), 0.0)
        if pnl >= -abs(float(SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_MIN_LOSS_DOLLARS or 0.01)):
            continue

        reason = str(r.get("reason") or r.get("exit_reason") or "").strip().lower()
        if reason == "opening_damage_exit" and not bool(SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_INCLUDE_OPENING_DAMAGE):
            continue
        if reason in {"stall_loss_guard", "stall_exit"} and not bool(SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_INCLUDE_STALL_LOSS):
            continue

        rows.append({
            "symbol": sym,
            "ts_utc": ts.astimezone(timezone.utc).isoformat(),
            "gross_pnl": round(pnl, 4),
            "reason": reason or None,
            "source": r.get("source"),
            "entry_price": r.get("entry_price"),
            "exit_price": r.get("exit_price"),
            "qty": r.get("qty"),
        })

    rows.sort(key=lambda x: str(x.get("ts_utc") or ""), reverse=True)
    return rows


def _p251_same_day_symbol_loss_cooldown(symbol: str, state: dict | None = None) -> dict:
    sym = str(symbol or "").strip().upper()
    rows = [r for r in _p251_today_symbol_loss_cooldown_rows(state=state) if str(r.get("symbol") or "").upper() == sym]
    active = bool(SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_ENABLED and rows)
    blocked = bool(active and not SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_ADVISORY_ONLY)
    return {
        "symbol": sym,
        "enabled": bool(SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_ENABLED),
        "advisory_only": bool(SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_ADVISORY_ONLY),
        "active": bool(active),
        "blocked": bool(blocked),
        "reason": "same_day_symbol_realized_loss" if active else "none",
        "loss_count_today": len(rows),
        "gross_pnl_today": round(sum(_safe_float(r.get("gross_pnl"), 0.0) for r in rows), 4),
        "rows": rows,
    }


def _p251_same_day_symbol_loss_cooldown_snapshot() -> dict:
    rows = _p251_today_symbol_loss_cooldown_rows()
    symbols = sorted({str(r.get("symbol") or "").upper() for r in rows if str(r.get("symbol") or "").strip()})
    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "same_day_symbol_loss_cooldown",
        "enabled": bool(SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_ENABLED),
        "advisory_only": bool(SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_ADVISORY_ONLY),
        "blocked_symbols": [] if SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_ADVISORY_ONLY else symbols,
        "loss_symbols": symbols,
        "loss_count": len(rows),
        "gross_pnl": round(sum(_safe_float(r.get("gross_pnl"), 0.0) for r in rows), 4),
        "rows": rows,
        "recommended_action": "cooldown_active_for_loss_symbols" if symbols else "none",
    }

def _p384_candidate_dollar_risk_truth(candidate: dict | None) -> dict:
    c = dict(candidate or {})
    sym = str(c.get("symbol") or "").strip().upper()
    enabled = bool(SWING_DOLLAR_RISK_SELECTION_TRUTH_ENABLED)
    configured_risk = max(0.0, float(RISK_DOLLARS or 0.0))
    max_multiple = max(0.0, float(SWING_DOLLAR_RISK_SELECTION_MAX_MULTIPLE or 0.0))
    max_dollar_risk = configured_risk * max_multiple if configured_risk > 0 and max_multiple > 0 else 0.0

    qty = abs(float(_safe_float(c.get("estimated_qty") or c.get("requested_qty") or 0.0)))
    entry = float(_safe_float(c.get("close") or c.get("price") or c.get("trade_price") or 0.0))
    stop = float(_safe_float(c.get("stop_price") or c.get("initial_stop_price") or 0.0))
    side = str(c.get("side") or "buy").strip().lower()

    if side in {"sell", "short"}:
        risk_per_share = max(0.0, stop - entry) if stop > 0 and entry > 0 else 0.0
    else:
        risk_per_share = max(0.0, entry - stop) if stop > 0 and entry > 0 else 0.0

    dollar_risk = qty * risk_per_share
    risk_multiple = dollar_risk / configured_risk if configured_risk > 0 else None

    blockers = []
    if not enabled:
        reason = "disabled"
    elif qty <= 0:
        blockers.append("missing_or_zero_qty")
        reason = "missing_or_zero_qty"
    elif entry <= 0:
        blockers.append("missing_entry_price")
        reason = "missing_entry_price"
    elif stop <= 0:
        blockers.append("missing_stop_price")
        reason = "missing_stop_price"
    elif max_dollar_risk > 0 and dollar_risk > max_dollar_risk:
        blockers.append("dollar_risk_above_selection_max")
        reason = "dollar_risk_above_selection_max"
    else:
        reason = "dollar_risk_ok"

    return {
        "enabled": enabled,
        "symbol": sym,
        "allowed": enabled and not blockers,
        "reason": reason,
        "blockers": blockers,
        "configured_risk_per_trade_dollars": round(configured_risk, 4),
        "max_risk_multiple": round(max_multiple, 4),
        "max_dollar_risk": round(max_dollar_risk, 4),
        "qty": round(qty, 4),
        "entry_price": round(entry, 4),
        "stop_price": round(stop, 4) if stop > 0 else None,
        "risk_per_share": round(risk_per_share, 4),
        "dollar_risk": round(dollar_risk, 4),
        "risk_multiple": round(risk_multiple, 4) if risk_multiple is not None else None,
        "percent_risk": c.get("risk_per_share_pct"),
    }

def _p385_apply_dollar_risk_add_slot_contract(candidate: dict | None) -> dict:
    c = dict(candidate or {})
    if not bool(SWING_DOLLAR_RISK_ADD_SLOT_SELECTION_ENABLED):
        return c

    contract = dict(c.get("swing_production_contract") or {})
    checks = dict(contract.get("checks") or {})
    blockers = [
        str(r or "").strip()
        for r in list(contract.get("blockers") or c.get("rejection_reasons") or [])
        if str(r or "").strip()
    ]

    risk_blockers = {"production_contract_risk_too_wide", "risk_per_share", "gate:risk_per_share"}
    non_risk_blockers = [r for r in blockers if r not in risk_blockers]
    dollar_risk = _p384_candidate_dollar_risk_truth(c)

    can_promote = bool(
        dollar_risk.get("allowed")
        and blockers
        and not non_risk_blockers
        and bool(checks.get("executable"))
        and bool(checks.get("rank_score_ok"))
        and bool(checks.get("liquidity_ok"))
        and bool(checks.get("not_too_far_below_breakout"))
        and bool(checks.get("not_too_extended_above_breakout"))
        and bool(checks.get("close_to_high_ok"))
        and bool(checks.get("return_20d_ok"))
    )

    c["dollar_risk_add_slot"] = {
        "enabled": True,
        "allowed": can_promote,
        "dollar_risk_selection_truth": dollar_risk,
        "original_blockers": blockers,
        "non_risk_blockers": non_risk_blockers,
    }

    if not can_promote:
        return c

    checks["dollar_risk_add_slot_ok"] = True
    checks["risk_ok"] = True
    checks["contract_path_ok"] = True
    contract["approved"] = True
    contract["blockers"] = []
    contract["checks"] = checks
    contract.setdefault("advisory_legacy_reasons", [])
    contract["advisory_legacy_reasons"] = _dedupe_keep_order(
        list(contract.get("advisory_legacy_reasons") or []) + blockers + ["dollar_risk_add_slot_promoted"]
    )

    c["swing_production_contract"] = contract
    c["eligible"] = True
    c["production_contract_approved"] = True
    c["rejection_reasons"] = []
    c["entry_type"] = "swing_production_dollar_risk_add_slot"
    c["selected_source"] = "swing_production_dollar_risk_add_slot"
    c["dollar_risk_add_slot"]["promoted"] = True
    return c


def _p385_sync_dollar_risk_add_slot_finalizer(finalizer: dict | None, *, max_new_entries: int) -> dict:
    out = dict(finalizer or {})
    rows = [
        _p385_apply_dollar_risk_add_slot_contract(dict(row or {}))
        for row in list(out.get("rows") or [])
        if isinstance(row, dict)
    ]

    max_total = max(0, int(max_new_entries or 0))
    max_add = max(0, int(SWING_DOLLAR_RISK_ADD_SLOT_MAX_PER_SCAN or 0))
    selected = [dict(row or {}) for row in list(out.get("selected") or []) if isinstance(row, dict)]
    selected_symbols = {
        str(row.get("symbol") or "").strip().upper()
        for row in selected
        if str(row.get("symbol") or "").strip()
    }

    add_slot_rows = [
        row for row in rows
        if bool((row.get("dollar_risk_add_slot") or {}).get("promoted"))
        and str(row.get("symbol") or "").strip().upper() not in selected_symbols
    ]
    add_slot_rows.sort(
        key=lambda row: (
            float(_safe_float(row.get("rank_score"))),
            float(_safe_float(row.get("target_path_score") or (row.get("target_path_profit") or {}).get("score"))),
        ),
        reverse=True,
    )

    added = []
    for row in add_slot_rows:
        if len(selected) >= max_total or len(added) >= max_add:
            break
        c = dict(row or {})
        c["selected"] = True
        c["entry_type"] = "swing_production_dollar_risk_add_slot"
        c["selected_source"] = "swing_production_dollar_risk_add_slot"
        c["selection_finalizer"] = "p385_dollar_risk_add_slot_selection_sync"
        selected.append(c)
        added.append(c)
        selected_symbols.add(str(c.get("symbol") or "").strip().upper())

    rebuilt_rows = []
    for row in rows:
        c = dict(row or {})
        sym = str(c.get("symbol") or "").strip().upper()
        c["selected"] = bool(sym and sym in selected_symbols)
        rebuilt_rows.append(c)

    approved = [
        dict(row or {})
        for row in rebuilt_rows
        if bool((row.get("swing_production_contract") or {}).get("approved"))
    ]

    out["rows"] = rebuilt_rows
    out["approved"] = approved
    out["selected"] = selected
    out["selected_symbols"] = [
        str(row.get("symbol") or "").strip().upper()
        for row in selected
        if str(row.get("symbol") or "").strip()
    ]
    out["approved_symbols"] = [
        str(row.get("symbol") or "").strip().upper()
        for row in approved
        if str(row.get("symbol") or "").strip()
    ]
    out["p385_dollar_risk_add_slot_sync"] = {
        "enabled": bool(SWING_DOLLAR_RISK_ADD_SLOT_SELECTION_ENABLED),
        "max_per_scan": max_add,
        "added_count": len(added),
        "added_symbols": [row.get("symbol") for row in added],
    }
    return out


def _p385_risk_adjusted_capacity_truth(active_truth: dict | None = None) -> dict:
    active = dict(active_truth or {})
    active_count = int(active.get("active_position_count") or 0)
    effective_max = int(_effective_max_open_positions())
    raw_open_slots = max(0, effective_max - active_count)

    advisory = _p384_oversized_position_remediation_advisory()
    oversized_symbols = list(advisory.get("oversized_symbols") or [])
    max_add_while_oversized = max(0, int(SWING_OVERSIZED_POSITION_MAX_ADD_SLOTS_WHILE_OVERSIZED or 0))

    if bool(SWING_OVERSIZED_POSITION_CAPACITY_ADJUSTMENT_ENABLED) and oversized_symbols:
        risk_adjusted_open_slots = min(raw_open_slots, max_add_while_oversized)
        read = "oversized_position_capacity_capped"
    else:
        risk_adjusted_open_slots = raw_open_slots
        read = "normal_capacity"

    return {
        "enabled": bool(SWING_OVERSIZED_POSITION_CAPACITY_ADJUSTMENT_ENABLED),
        "effective_max_open_positions": effective_max,
        "active_position_count": active_count,
        "raw_open_slots": raw_open_slots,
        "risk_adjusted_open_slots": risk_adjusted_open_slots,
        "max_add_slots_while_oversized": max_add_while_oversized,
        "oversized_symbols": oversized_symbols,
        "oversized_count": len(oversized_symbols),
        "read": read,
    }

def _p384_oversized_position_remediation_advisory() -> dict:
    risk_truth = _p383_broker_native_position_risk_truth()
    configured_risk = max(0.0, float(risk_truth.get("configured_risk_per_trade_dollars") or RISK_DOLLARS or 0.0))
    advisory_multiple = max(0.0, float(SWING_OVERSIZED_POSITION_ADVISORY_MULTIPLE or 0.0))
    reduce_multiple = max(0.0, float(SWING_OVERSIZED_POSITION_REDUCE_TO_RISK_MULTIPLE or 0.0))
    advisory_threshold = configured_risk * advisory_multiple if configured_risk > 0 and advisory_multiple > 0 else 0.0
    reduce_target = configured_risk * reduce_multiple if configured_risk > 0 and reduce_multiple > 0 else 0.0

    rows = []
    for row in list(risk_truth.get("rows") or []):
        r = dict(row or {})
        risk_to_stop = float(_safe_float(r.get("risk_to_stop_dollars"), 0.0))
        qty = abs(float(_safe_float(r.get("qty"), 0.0)))
        risk_per_share = risk_to_stop / qty if qty > 0 else 0.0
        target_qty = qty
        reduce_qty = 0.0

        if risk_per_share > 0 and reduce_target > 0:
            target_qty = max(0.0, reduce_target / risk_per_share)
            reduce_qty = max(0.0, qty - target_qty)

        oversized = bool(advisory_threshold > 0 and risk_to_stop > advisory_threshold)
        r.update({
            "oversized_advisory": oversized,
            "advisory_threshold_dollars": round(advisory_threshold, 4),
            "reduce_target_risk_dollars": round(reduce_target, 4),
            "risk_per_share_dollars": round(risk_per_share, 4),
            "suggested_target_qty": round(target_qty, 4),
            "suggested_reduce_qty": round(reduce_qty, 4),
            "remediation": (
                "consider_reduce_or_tighten_stop"
                if oversized
                else "none"
            ),
        })
        rows.append(r)

    oversized_symbols = [r.get("symbol") for r in rows if r.get("oversized_advisory")]

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "oversized_position_remediation_advisory",
        "configured_risk_per_trade_dollars": round(configured_risk, 4),
        "advisory_multiple": round(advisory_multiple, 4),
        "reduce_to_risk_multiple": round(reduce_multiple, 4),
        "oversized_count": len(oversized_symbols),
        "oversized_symbols": oversized_symbols,
        "rows": rows,
        "recommended_action": "review_reduce_or_tighten_stop_candidates" if oversized_symbols else "none",
    }

def _p383_broker_native_position_risk_truth() -> dict:
    rows = []
    total_risk_to_stop = 0.0
    total_reward_to_target = 0.0
    configured_risk = max(0.0, float(RISK_DOLLARS or 0.0))

    try:
        positions = list_open_positions_details_allowed()
    except Exception:
        positions = []

    for pos in list(positions or []):
        sym = str((pos or {}).get("symbol") or "").strip().upper()
        if not sym:
            continue

        plan = TRADE_PLAN.get(sym) if isinstance(TRADE_PLAN.get(sym), dict) else {}
        qty = abs(float(_safe_float((pos or {}).get("qty"), 0.0)))
        entry = float(_safe_float((pos or {}).get("avg_entry_price") or (pos or {}).get("entry_price") or plan.get("entry_price"), 0.0))
        last = float(_safe_float((pos or {}).get("current_price") or (pos or {}).get("last_price") or entry, 0.0))
        stop = float(_safe_float(plan.get("stop_price") or plan.get("initial_stop_price"), 0.0))
        target = float(_safe_float(plan.get("take_price") or plan.get("target_price"), 0.0))
        side = "short" if float(_safe_float((pos or {}).get("qty"), 0.0)) < 0 else "long"

        if side == "long":
            risk_to_stop = max(0.0, entry - stop) * qty if stop > 0 else None
            reward_to_target = max(0.0, target - entry) * qty if target > 0 else None
            gap_down_2pct = (last * 0.98 - entry) * qty
            gap_down_5pct = (last * 0.95 - entry) * qty
            gap_up_2pct = (last * 1.02 - entry) * qty
        else:
            risk_to_stop = max(0.0, stop - entry) * qty if stop > 0 else None
            reward_to_target = max(0.0, entry - target) * qty if target > 0 else None
            gap_down_2pct = (entry - last * 0.98) * qty
            gap_down_5pct = (entry - last * 0.95) * qty
            gap_up_2pct = (entry - last * 1.02) * qty

        if risk_to_stop is not None:
            total_risk_to_stop += risk_to_stop
        if reward_to_target is not None:
            total_reward_to_target += reward_to_target

        risk_multiple = None
        if configured_risk > 0 and risk_to_stop is not None:
            risk_multiple = risk_to_stop / configured_risk

        rows.append({
            "symbol": sym,
            "side": side,
            "qty": qty,
            "entry_price": round(entry, 4),
            "last_price": round(last, 4),
            "stop_price": round(stop, 4) if stop > 0 else None,
            "target_price": round(target, 4) if target > 0 else None,
            "unrealized_pl": round(float(_safe_float((pos or {}).get("unrealized_pl"), 0.0)), 4),
            "risk_to_stop_dollars": round(risk_to_stop, 4) if risk_to_stop is not None else None,
            "reward_to_target_dollars": round(reward_to_target, 4) if reward_to_target is not None else None,
            "risk_multiple_of_configured_trade_risk": round(risk_multiple, 2) if risk_multiple is not None else None,
            "gap_down_2pct_pnl": round(gap_down_2pct, 4),
            "gap_down_5pct_pnl": round(gap_down_5pct, 4),
            "gap_up_2pct_pnl": round(gap_up_2pct, 4),
            "risk_status": (
                "missing_stop"
                if stop <= 0
                else "oversized_vs_config"
                if risk_multiple is not None and risk_multiple > float(SWING_OVERSIZED_POSITION_ADVISORY_MULTIPLE or 2.0)
                else "ok"
            ),
        })

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "broker_native_position_risk_truth",
        "configured_risk_per_trade_dollars": configured_risk,
        "position_count": len(rows),
        "total_risk_to_stop_dollars": round(total_risk_to_stop, 4),
        "total_reward_to_target_dollars": round(total_reward_to_target, 4),
        "oversized_symbols": [r["symbol"] for r in rows if r.get("risk_status") == "oversized_vs_config"],
        "missing_stop_symbols": [r["symbol"] for r in rows if r.get("risk_status") == "missing_stop"],
        "rows": rows,
        "recommended_action": "review_oversized_position_risk" if any(r.get("risk_status") != "ok" for r in rows) else "none",
    }


def _p383_loss_day_recovery_slot_policy_snapshot(throttle: dict | None = None) -> dict:
    throttle = dict(throttle or {})
    active = bool(throttle.get("block_new_entries"))
    enabled = bool(SWING_LOSS_DAY_RECOVERY_SLOT_ENABLED)

    return {
        "enabled": enabled,
        "active": bool(active and enabled),
        "throttle_active": bool(active),
        "max_entries": max(0, int(SWING_LOSS_DAY_RECOVERY_SLOT_MAX_ENTRIES or 0)),
        "min_rank_score": float(SWING_LOSS_DAY_RECOVERY_SLOT_MIN_RANK_SCORE or 0.0),
        "min_target_path_score": float(SWING_LOSS_DAY_RECOVERY_SLOT_MIN_TARGET_PATH_SCORE or 0.0),
        "max_risk_per_share_pct": float(SWING_LOSS_DAY_RECOVERY_SLOT_MAX_RISK_PER_SHARE_PCT or 0.0),
        "read": "candidate_level_recovery_slot" if active and enabled else "normal_loss_day_throttle",
    }


def _p383_loss_day_recovery_slot_candidate(candidate: dict | None, throttle: dict | None = None) -> dict:
    c = dict(candidate or {})
    policy = _p383_loss_day_recovery_slot_policy_snapshot(throttle)
    sym = str(c.get("symbol") or "").strip().upper()

    out = {
        "enabled": bool(policy.get("enabled")),
        "active": bool(policy.get("active")),
        "allowed": False,
        "symbol": sym,
        "reason": "not_active",
        "policy": policy,
    }

    if not bool(policy.get("active")):
        return out

    target_path = c.get("target_path_profit")
    if not isinstance(target_path, dict):
        target_path = _p283_target_path_profit_score(c)

    rank_score = float(_safe_float(c.get("rank_score"), 0.0))
    target_path_score = float(_safe_float((target_path or {}).get("score") if isinstance(target_path, dict) else c.get("target_path_score"), 0.0))
    risk_per_share_pct = abs(float(_safe_float(c.get("risk_per_share_pct"), 0.0)))

    blockers = []
    if rank_score < float(policy.get("min_rank_score") or 0.0):
        blockers.append("rank_score_below_recovery_min")
    if target_path_score < float(policy.get("min_target_path_score") or 0.0):
        blockers.append("target_path_score_below_recovery_min")
    if risk_per_share_pct > float(policy.get("max_risk_per_share_pct") or 0.0):
        blockers.append("risk_per_share_above_recovery_max")

    out.update({
        "rank_score": round(rank_score, 4),
        "target_path_score": round(target_path_score, 4),
        "risk_per_share_pct": round(risk_per_share_pct, 6),
        "blockers": blockers,
        "allowed": not blockers,
        "reason": "allowed_recovery_candidate" if not blockers else "blocked_by_recovery_quality",
    })
    return out

def _p252_swing_loss_day_entry_throttle_snapshot() -> dict:
    try:
        pnl = dict(today_pnl_truth_snapshot() or {})
    except Exception as exc:
        return {
            "ok": False,
            "patch_version": PATCH_VERSION,
            "mode": "swing_loss_day_entry_throttle",
            "enabled": bool(SWING_LOSS_DAY_ENTRY_THROTTLE_ENABLED),
            "active": False,
            "block_new_entries": False,
            "error": str(exc),
            "recommended_action": "monitor",
        }

    realized = _safe_float(pnl.get("today_realized_pnl"), 0.0)
    unrealized = _safe_float(pnl.get("today_unrealized_pnl"), 0.0)
    include_unrealized = bool(SWING_LOSS_DAY_ENTRY_THROTTLE_INCLUDE_UNREALIZED)
    loss_basis = realized + unrealized if include_unrealized else realized
    threshold = abs(float(SWING_LOSS_DAY_ENTRY_THROTTLE_REALIZED_LOSS_DOLLARS or 0.0))
    max_after = max(0, int(SWING_LOSS_DAY_ENTRY_THROTTLE_MAX_NEW_ENTRIES_AFTER_TRIGGER or 0))

    active = bool(
        SWING_LOSS_DAY_ENTRY_THROTTLE_ENABLED
        and threshold > 0
        and loss_basis <= -threshold
    )
    block_new_entries = bool(
        active
        and not SWING_LOSS_DAY_ENTRY_THROTTLE_ADVISORY_ONLY
        and max_after <= 0
    )

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "swing_loss_day_entry_throttle",
        "enabled": bool(SWING_LOSS_DAY_ENTRY_THROTTLE_ENABLED),
        "advisory_only": bool(SWING_LOSS_DAY_ENTRY_THROTTLE_ADVISORY_ONLY),
        "active": bool(active),
        "block_new_entries": bool(block_new_entries),
        "max_new_entries_after_trigger": int(max_after),
        "include_unrealized": bool(include_unrealized),
        "loss_basis": "realized_plus_unrealized" if include_unrealized else "realized_only",
        "loss_basis_value": round(loss_basis, 4),
        "today_realized_pnl": round(realized, 4),
        "today_unrealized_pnl": round(unrealized, 4),
        "threshold_dollars": float(threshold),
        "accounting_source": pnl.get("accounting_source"),
        "broker_exit_fills_today": pnl.get("broker_exit_fills_today"),
        "closed_trades_today": pnl.get("closed_trades_today"),
        "recommended_action": "block_new_swing_entries_for_loss_day" if block_new_entries else ("limit_new_swing_entries_for_loss_day" if active else "none"),
    }

