def _p253_broker_backed_exposure_truth_snapshot() -> dict:
    broker_positions = []
    try:
        broker_positions = list_open_positions_details_allowed() or []
    except Exception:
        broker_positions = []

    broker_by_symbol = {
        str((p or {}).get("symbol") or "").upper(): dict(p or {})
        for p in broker_positions
        if str((p or {}).get("symbol") or "").strip()
    }

    rows = []
    totals = {
        "broker_market_value": 0.0,
        "current_strategy_market_value": 0.0,
        "current_recovered_market_value": 0.0,
        "corrected_strategy_market_value": 0.0,
        "corrected_recovered_market_value": 0.0,
    }

    for sym, pos in sorted(broker_by_symbol.items()):
        plan = dict((TRADE_PLAN or {}).get(sym) or {})
        market_value = _p254_position_notional(pos)
        signal = str(plan.get("signal") or plan.get("strategy_name") or "").strip().lower()
        recovered = bool(plan.get("recovered"))
        broker_backed = bool(pos)
        is_swing_strategy = signal in {BREAKOUT_STRATEGY_NAME, MEAN_REVERSION_STRATEGY_NAME, "daily_breakout", "daily_mean_reversion"}

        current_bucket = "recovered" if recovered else ("strategy" if is_swing_strategy else "unmanaged")
        corrected_bucket = "strategy" if broker_backed and is_swing_strategy and bool(SWING_BROKER_BACKED_RECOVERED_COUNTS_AS_STRATEGY) else current_bucket

        totals["broker_market_value"] += market_value
        if current_bucket == "strategy":
            totals["current_strategy_market_value"] += market_value
        elif current_bucket == "recovered":
            totals["current_recovered_market_value"] += market_value

        if corrected_bucket == "strategy":
            totals["corrected_strategy_market_value"] += market_value
        elif corrected_bucket == "recovered":
            totals["corrected_recovered_market_value"] += market_value

        rows.append({
            "symbol": sym,
            "market_value": round(market_value, 4),
            "qty": pos.get("qty"),
            "signal": signal or None,
            "recovered": recovered,
            "broker_backed": broker_backed,
            "is_swing_strategy": bool(is_swing_strategy),
            "current_bucket": current_bucket,
            "corrected_bucket": corrected_bucket,
            "classification_changed": current_bucket != corrected_bucket,
            "opened_at": plan.get("opened_at"),
            "source": plan.get("source"),
            "attribution_source": plan.get("attribution_source"),
        })

    changed = [r for r in rows if r.get("classification_changed")]
    rounded_totals = {k: round(v, 4) for k, v in totals.items()}

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "broker_backed_exposure_truth",
        "counts_recovered_as_strategy": bool(SWING_BROKER_BACKED_RECOVERED_COUNTS_AS_STRATEGY),
        "broker_position_count": len(rows),
        "classification_changed_count": len(changed),
        "classification_changed_symbols": [r.get("symbol") for r in changed],
        "totals": rounded_totals,
        "rows": rows,
        "recommended_action": "capacity_truth_corrected_observe" if changed else "none",
        "note": "Recovered broker-backed swing positions are now counted as strategy exposure by corrected capacity truth.",
    }


def _p253_swing_simplification_audit_snapshot() -> dict:
    control_surface = _p253_swing_control_surface_snapshot()
    exposure_truth = _p253_broker_backed_exposure_truth_snapshot()

    try:
        performance = _p245_broker_preferred_performance_snapshot()
    except Exception as exc:
        performance = {"ok": False, "error": str(exc)}

    try:
        throttle = _p252_swing_loss_day_entry_throttle_snapshot()
    except Exception as exc:
        throttle = {"ok": False, "error": str(exc)}

    try:
        cooldown = _p251_same_day_symbol_loss_cooldown_snapshot()
    except Exception as exc:
        cooldown = {"ok": False, "error": str(exc)}

    try:
        capacity = _p255_corrected_swing_capacity_truth_snapshot()
    except Exception as exc:
        capacity = {"ok": False, "error": str(exc)}

    try:
        backtest = _p255_swing_profit_opportunity_backtest()
    except Exception as exc:
        backtest = {"ok": False, "error": str(exc)}

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "swing_system_simplification_audit",
        "read_only": True,
        "control_surface": control_surface,
        "broker_backed_exposure_truth": exposure_truth,
        "corrected_capacity_truth": capacity,
        "performance": performance.get("broker_preferred") if isinstance(performance, dict) else {},
        "same_day_symbol_loss_cooldown": cooldown,
        "loss_day_entry_throttle": throttle,
        "profit_opportunity_backtest_summary": {
            "baseline": backtest.get("baseline"),
            "best_scenario": backtest.get("best_scenario"),
            "recommended_action": backtest.get("recommended_action"),
        },
        "recommended_env_updates": control_surface.get("recommended_env_updates"),
        "recommended_next_patch": "review_swing_profit_opportunity_backtest",
    }

def _p252_fresh_active_plans_for_snapshot_guard() -> dict[str, dict]:
    plans: dict[str, dict] = {}

    for sym, plan in dict(TRADE_PLAN or {}).items():
        if isinstance(plan, dict) and bool(plan.get("active")):
            key = str(sym or plan.get("symbol") or "").strip().upper()
            if key:
                plans[key] = dict(plan)

    try:
        snap = dict(read_positions_snapshot() or {})
        snapshot_plans = dict(snap.get("active_plans") or {})
    except Exception:
        snapshot_plans = {}

    for sym, plan in snapshot_plans.items():
        if not isinstance(plan, dict) or not bool(plan.get("active")):
            continue
        key = str(sym or plan.get("symbol") or "").strip().upper()
        if not key:
            continue

        current = dict(plans.get(key) or {})
        current_thesis = dict(current.get("thesis") or {}) if isinstance(current.get("thesis"), dict) else {}
        current_snap = dict(current_thesis.get("entry_quality_snapshot") or {}) if isinstance(current_thesis.get("entry_quality_snapshot"), dict) else {}

        snapshot_thesis = dict(plan.get("thesis") or {}) if isinstance(plan.get("thesis"), dict) else {}
        snapshot_snap = dict(snapshot_thesis.get("entry_quality_snapshot") or {}) if isinstance(snapshot_thesis.get("entry_quality_snapshot"), dict) else {}

        if not current or (
            _p249_snapshot_has_useful_values(snapshot_snap)
            and not _p249_snapshot_has_useful_values(current_snap)
        ):
            plans[key] = dict(plan)

    try:
        for pos in list_open_positions_details_allowed() or []:
            key = str((pos or {}).get("symbol") or "").strip().upper()
            if key and key not in plans and isinstance(TRADE_PLAN.get(key), dict):
                plans[key] = dict(TRADE_PLAN.get(key) or {})
    except Exception:
        pass

    return plans

def _p251_entry_snapshot_guard_snapshot() -> dict:
    rows = []
    plans = _p252_fresh_active_plans_for_snapshot_guard()

    for sym, plan in sorted(plans.items()):
        if not isinstance(plan, dict) or not plan.get("active"):
            continue

        thesis = dict(plan.get("thesis") or {}) if isinstance(plan.get("thesis"), dict) else {}
        snap = dict(thesis.get("entry_quality_snapshot") or {}) if isinstance(thesis.get("entry_quality_snapshot"), dict) else {}
        completeness = _p251_entry_snapshot_completeness(snap)
        probe = _p247_entry_quality_backfill_probe_for_position(str(sym or "").upper(), plan)

        rows.append({
            "symbol": str(sym or "").upper(),
            "complete": bool(completeness.get("useful")),
            "partial": bool(completeness.get("partial")),
            "required_missing": list(completeness.get("required_missing") or []),
            "snapshot": snap,
            "can_backfill": bool(probe.get("can_backfill")),
            "recovered_snapshot_preview": probe.get("recovered_snapshot_preview"),
            "source": "fresh_active_plan_snapshot_merge",
            "recommended_action": "apply_entry_memory_backfill" if probe.get("can_backfill") else ("patch_or_monitor_partial_snapshot" if completeness.get("partial") else "none"),
        })

    partial = [r for r in rows if r.get("partial")]
    backfillable = [r for r in rows if r.get("can_backfill")]

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "fresh_placeholder_entry_snapshot_guard",
        "active_position_count": len(rows),
        "partial_snapshot_count": len(partial),
        "backfillable_count": len(backfillable),
        "partial_symbols": [r.get("symbol") for r in partial],
        "backfillable_symbols": [r.get("symbol") for r in backfillable],
        "rows": rows,
        "recommended_action": "apply_entry_memory_backfill" if backfillable else ("review_partial_snapshots" if partial else "none"),
    }

def _p251_simulate_exit_variant(rows: list[dict], name: str, remove_reasons: set[str] | None = None, blocked_symbols: set[str] | None = None) -> dict:
    remove_reasons = set(remove_reasons or set())
    blocked_symbols = set(blocked_symbols or set())
    kept = []
    removed = []

    for row in rows:
        r = dict(row or {})
        sym = str(r.get("symbol") or "").upper()
        reason = str(r.get("reason") or r.get("exit_reason") or "").strip().lower()
        if sym in blocked_symbols or reason in remove_reasons:
            removed.append(r)
        else:
            kept.append(r)

    kept_rollup = _p245_performance_rollup(kept)
    base_rollup = _p245_performance_rollup(rows)
    return {
        "scenario": name,
        "removed_count": len(removed),
        "removed_gross_pnl": round(sum(_safe_float(r.get("gross_pnl"), 0.0) for r in removed), 4),
        "base": base_rollup,
        "simulated": kept_rollup,
        "gross_pnl_delta": round(_safe_float(kept_rollup.get("gross_pnl"), 0.0) - _safe_float(base_rollup.get("gross_pnl"), 0.0), 4),
        "avg_r_delta": round(_safe_float(kept_rollup.get("avg_r"), 0.0) - _safe_float(base_rollup.get("avg_r"), 0.0), 4),
        "removed_symbols": sorted({str(r.get("symbol") or "").upper() for r in removed if str(r.get("symbol") or "").strip()}),
    }


def _p251_swing_replay_backtest_lab() -> dict:
    preferred = _p245_broker_preferred_closed_rows()
    rows = [dict(r or {}) for r in list(preferred.get("kept_rows") or []) if isinstance(r, dict)]
    today_loss_rows = _p251_today_symbol_loss_cooldown_rows()
    today_loss_symbols = {str(r.get("symbol") or "").upper() for r in today_loss_rows}

    scenarios = [
        _p251_simulate_exit_variant(rows, "current_broker_preferred", set(), set()),
        _p251_simulate_exit_variant(rows, "remove_opening_damage_exits", {"opening_damage_exit"}, set()),
        _p251_simulate_exit_variant(rows, "remove_stall_loss_guard_exits", {"stall_loss_guard"}, set()),
        _p251_simulate_exit_variant(rows, "remove_stall_exits", {"stall_exit"}, set()),
        _p251_simulate_exit_variant(rows, "same_day_loss_symbol_cooldown_today", set(), today_loss_symbols),
    ]

    scenarios.sort(key=lambda r: _safe_float(r.get("gross_pnl_delta"), 0.0), reverse=True)

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "read_only_swing_replay_backtest_lab",
        "note": "This is a closed-trade attribution simulator, not a full OHLCV bar replay yet.",
        "closed_trade_count": len(rows),
        "base": _p245_performance_rollup(rows),
        "today_loss_symbols": sorted(today_loss_symbols),
        "scenarios": scenarios,
        "recommended_action": "use_next_patch_for_full_bar_replay" if rows else "collect_more_trades",
    }

def _p255_corrected_swing_capacity_truth_snapshot() -> dict:
    exposure = _current_portfolio_exposure_breakdown()
    same_day_stats = _same_day_entry_stats()
    equity = max(0.0, _current_equity_estimate())
    portfolio_cap = equity * SWING_MAX_PORTFOLIO_EXPOSURE_PCT if equity > 0 else 0.0
    strategy_exposure = float(exposure.get("strategy_managed") or 0.0)
    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "corrected_swing_capacity_truth",
        "same_day_entry_count": int(same_day_stats.get("counted") or 0),
        "same_day_entry_details": same_day_stats,
        "max_new_entries_per_day": int(SWING_MAX_NEW_ENTRIES_PER_DAY),
        "remaining_new_entries_today": max(0, int(SWING_MAX_NEW_ENTRIES_PER_DAY) - int(same_day_stats.get("counted") or 0)),
        "portfolio_exposure": round(float(exposure.get("total") or 0.0), 2),
        "strategy_portfolio_exposure": round(strategy_exposure, 2),
        "recovered_portfolio_exposure": round(float(exposure.get("recovered") or 0.0), 2),
        "unmanaged_portfolio_exposure": round(float(exposure.get("unmanaged") or 0.0), 2),
        "portfolio_exposure_cap": round(portfolio_cap, 2),
        "portfolio_exposure_remaining": round(max(0.0, portfolio_cap - strategy_exposure), 2) if portfolio_cap > 0 else None,
        "classification_source": exposure.get("classification_source"),
        "counts_recovered_as_strategy": exposure.get("counts_recovered_as_strategy"),
        "corrected_recovered_as_strategy_symbols": list(exposure.get("corrected_recovered_as_strategy_symbols") or []),
        "strategy_symbols": list(exposure.get("strategy_symbols") or []),
        "recovered_symbols": list(exposure.get("recovered_symbols") or []),
        "recommended_action": "observe_corrected_capacity_truth",
    }


def _p255_ny_trade_day(row: dict | None) -> str:
    r = dict(row or {})
    ts = (
        r.get("entry_ts_utc")
        or r.get("opened_at")
        or r.get("ts_utc")
        or r.get("exit_ts_utc")
        or r.get("closed_at")
    )
    dt = _p175_parse_dt(ts)
    if dt:
        return dt.astimezone(NY_TZ).date().isoformat()
    return str(r.get("session_date") or "")[:10]


def _p255_trade_sort_key(row: dict | None) -> str:
    r = dict(row or {})
    return str(
        r.get("entry_ts_utc")
        or r.get("opened_at")
        or r.get("ts_utc")
        or r.get("exit_ts_utc")
        or r.get("closed_at")
        or ""
    )


def _p255_backtest_summary(rows: list[dict]) -> dict:
    rollup = _p245_performance_rollup(rows)
    return {
        "closed_trades": rollup.get("closed_trades"),
        "wins": rollup.get("wins"),
        "losses": rollup.get("losses"),
        "win_rate": rollup.get("win_rate"),
        "gross_pnl": rollup.get("gross_pnl"),
        "avg_r": rollup.get("avg_r"),
        "sample_maturity": rollup.get("sample_maturity"),
    }


def _p255_scenario_payload(name: str, baseline_rows: list[dict], kept_rows: list[dict], removed_rows: list[dict], rationale: str, env_hint: str = "") -> dict:
    base = _p255_backtest_summary(baseline_rows)
    simulated = _p255_backtest_summary(kept_rows)
    removed = _p255_backtest_summary(removed_rows)
    return {
        "scenario": name,
        "rationale": rationale,
        "env_hint": env_hint,
        "removed_count": len(removed_rows),
        "removed_symbols": sorted({str(r.get("symbol") or "").upper() for r in removed_rows if str(r.get("symbol") or "").strip()}),
        "removed": removed,
        "simulated": simulated,
        "gross_pnl_delta": round(_safe_float(simulated.get("gross_pnl"), 0.0) - _safe_float(base.get("gross_pnl"), 0.0), 4),
        "avg_r_delta": round(_safe_float(simulated.get("avg_r"), 0.0) - _safe_float(base.get("avg_r"), 0.0), 4),
        "win_rate_delta": round(_safe_float(simulated.get("win_rate"), 0.0) - _safe_float(base.get("win_rate"), 0.0), 4),
    }


def _p255_filter_daily_entry_cap(rows: list[dict], cap: int) -> tuple[list[dict], list[dict]]:
    cap = max(1, int(cap or 1))
    kept = []
    removed = []
    counts: dict[str, int] = {}
    for row in sorted([dict(r or {}) for r in rows], key=_p255_trade_sort_key):
        day = _p255_ny_trade_day(row)
        if not day:
            kept.append(row)
            continue
        counts[day] = int(counts.get(day, 0))
        if counts[day] < cap:
            kept.append(row)
            counts[day] += 1
        else:
            copy = dict(row)
            copy["p255_removed_reason"] = f"daily_entry_cap_{cap}"
            removed.append(copy)
    return kept, removed


def _p255_filter_entry_types(rows: list[dict], blocked: set[str]) -> tuple[list[dict], list[dict]]:
    kept = []
    removed = []
    blocked_norm = {str(x or "").strip().lower() for x in blocked}
    for row in rows:
        r = dict(row or {})
        entry_type = _p207_closed_trade_entry_type(r)
        if entry_type in blocked_norm:
            r["p255_removed_reason"] = f"entry_type_{entry_type}"
            removed.append(r)
        else:
            kept.append(r)
    return kept, removed


def _p255_filter_strategy(rows: list[dict], allowed: set[str]) -> tuple[list[dict], list[dict]]:
    kept = []
    removed = []
    allowed_norm = {str(x or "").strip().lower() for x in allowed}
    for row in rows:
        r = dict(row or {})
        strategy = _p207_closed_trade_strategy(r)
        if strategy in allowed_norm:
            kept.append(r)
        else:
            r["p255_removed_reason"] = f"strategy_{strategy}"
            removed.append(r)
    return kept, removed


def _p255_filter_same_day_symbol_reentry_after_loss(rows: list[dict]) -> tuple[list[dict], list[dict]]:
    kept = []
    removed = []
    symbol_day_loss_seen: set[tuple[str, str]] = set()
    for row in sorted([dict(r or {}) for r in rows], key=_p255_trade_sort_key):
        sym = str(row.get("symbol") or "").upper()
        day = _p255_ny_trade_day(row)
        key = (sym, day)
        pnl = _safe_float(row.get("gross_pnl"), 0.0)
        if sym and day and key in symbol_day_loss_seen:
            row["p255_removed_reason"] = "same_day_symbol_reentry_after_loss"
            removed.append(row)
            continue
        kept.append(row)
        if sym and day and pnl < 0:
            symbol_day_loss_seen.add(key)
    return kept, removed


def _p255_swing_profit_opportunity_backtest() -> dict:
    preferred = _p245_broker_preferred_closed_rows()
    rows = [dict(r or {}) for r in list(preferred.get("kept_rows") or []) if isinstance(r, dict)]
    baseline = _p255_backtest_summary(rows)

    scenarios = [
        _p255_scenario_payload(
            "current_broker_preferred",
            rows,
            rows,
            [],
            "Current broker-preferred performance after duplicate worker exits are removed.",
            "",
        )
    ]

    kept, removed = _p255_filter_daily_entry_cap(rows, 3)
    scenarios.append(_p255_scenario_payload(
        "max_3_entries_per_day_proxy",
        rows,
        kept,
        removed,
        "Closed-trade proxy for reducing daily entry burst risk to 3 entries.",
        "SWING_MAX_NEW_ENTRIES_PER_DAY=3",
    ))

    kept, removed = _p255_filter_daily_entry_cap(rows, 4)
    scenarios.append(_p255_scenario_payload(
        "max_4_entries_per_day_proxy",
        rows,
        kept,
        removed,
        "Closed-trade proxy for reducing daily entry burst risk to 4 entries while preserving more opportunity.",
        "SWING_MAX_NEW_ENTRIES_PER_DAY=4",
    ))

    kept, removed = _p255_filter_entry_types(rows, {"adaptive", "early_override"})
    scenarios.append(_p255_scenario_payload(
        "simplified_no_adaptive_or_early_override_history",
        rows,
        kept,
        removed,
        "Historical proxy for the current simplification posture with expansion entry types removed.",
        "SWING_ADAPTIVE_CAPACITY_ENABLED=false; SWING_EARLY_ENTRY_OVERRIDE_ENABLED=false",
    ))

    kept, removed = _p255_filter_strategy(rows, {"daily_breakout"})
    scenarios.append(_p255_scenario_payload(
        "daily_breakout_only",
        rows,
        kept,
        removed,
        "Checks whether the original daily breakout engine is still the primary profit source.",
        "",
    ))

    kept, removed = _p255_filter_same_day_symbol_reentry_after_loss(rows)
    scenarios.append(_p255_scenario_payload(
        "same_day_symbol_loss_cooldown_proxy",
        rows,
        kept,
        removed,
        "Closed-trade proxy for avoiding repeat same-day entries after a symbol has already lost.",
        "SWING_SAME_DAY_SYMBOL_LOSS_COOLDOWN_ENABLED=true",
    ))

    tuning = _swing_profit_acceleration_simulator(perf_state={"closed_trades": rows})
    tuning_scenarios = list(tuning.get("scenarios") or [])[:8]

    ranked = sorted(
        scenarios,
        key=lambda r: (
            _safe_float(r.get("gross_pnl_delta"), 0.0),
            _safe_float(r.get("avg_r_delta"), 0.0),
            _safe_float(r.get("win_rate_delta"), 0.0),
        ),
        reverse=True,
    )
    best = next((r for r in ranked if str(r.get("scenario")) != "current_broker_preferred"), ranked[0] if ranked else {})

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "read_only_swing_profit_opportunity_backtest",
        "note": "Closed-trade replay proxy. This does not recreate full OHLCV entry timing, but it is useful for comparing simplification and capacity settings against actual closed-trade outcomes.",
        "baseline": baseline,
        "broker_preferred_source": {
            "raw_count": preferred.get("raw_count"),
            "kept_count": preferred.get("kept_count"),
            "shadowed_worker_count": preferred.get("shadowed_worker_count"),
            "shadowed_worker_gross_pnl": preferred.get("shadowed_worker_gross_pnl"),
        },
        "scenarios": ranked,
        "best_scenario": best,
        "tuning_simulator_best": tuning.get("best_tuning_candidate"),
        "tuning_simulator_scenarios": tuning_scenarios,
        "recommended_action": "review_best_scenario_before_env_change" if rows else "collect_more_closed_trades",
    }

def _p247_candidate_like_rows_from_payload(payload: object, limit: int = 500) -> list[dict]:
    rows: list[dict] = []

    def walk(obj: object):
        if len(rows) >= max(1, int(limit or 500)):
            return
        if isinstance(obj, list):
            for item in obj:
                walk(item)
            return
        if not isinstance(obj, dict):
            return

        symbol = str(obj.get("symbol") or "").strip().upper()
        if symbol and (
            "rank_score" in obj
            or "selection_quality_score" in obj
            or "return_20d_pct" in obj
            or "breakout_distance_pct" in obj
            or "risk_per_share_pct" in obj
            or "rejection_reasons" in obj
        ):
            rows.append(dict(obj))

        for key in (
            "items",
            "candidates",
            "top_candidates",
            "eligible_but_not_selected",
            "selection_blocked_items",
            "shadow_items",
            "shadow_selected",
            "history",
            "summary",
            "last_scan",
        ):
            if key in obj:
                walk(obj.get(key))

    walk(payload)
    return rows[:max(1, int(limit or 500))]


def _p247_recent_candidate_rows_for_symbol(symbol: str, limit: int = 200) -> list[dict]:
    sym = str(symbol or "").strip().upper()
    if not sym:
        return []

    payloads = []
    try:
        payloads.extend(list(CANDIDATE_HISTORY or [])[-25:])
    except Exception:
        pass
    try:
        if LAST_SCAN:
            payloads.append(dict(LAST_SCAN))
    except Exception:
        pass
    try:
        if LAST_SWING_CANDIDATES:
            payloads.append({"items": list(LAST_SWING_CANDIDATES or [])})
    except Exception:
        pass

    matches = []
    for payload in reversed(payloads):
        for row in _p247_candidate_like_rows_from_payload(payload, limit=limit):
            if str(row.get("symbol") or "").strip().upper() == sym:
                matches.append(row)

    return matches[:max(1, int(limit or 200))]

def _p276_candidate_row_ts(row: dict | None, fallback_ts: str | None = None):
    r = dict(row or {})
    raw = (
        r.get("scan_ts_utc")
        or r.get("active_scan_ts_utc")
        or r.get("ts_utc")
        or fallback_ts
    )
    return _p175_parse_dt(raw)


def _p276_plan_opened_dt(plan: dict | None):
    p = dict(plan or {})
    return _p175_parse_dt(
        p.get("opened_at")
        or p.get("submitted_at")
        or p.get("created_at")
        or p.get("entry_ts_utc")
    )


def _p276_timestamped_candidate_rows_for_symbol(symbol: str, limit: int = 300) -> list[dict]:
    sym = str(symbol or "").strip().upper()
    if not sym:
        return []

    payloads: list[tuple[dict, str | None, str]] = []
    try:
        for payload in list(CANDIDATE_HISTORY or [])[-max(1, int(SWING_DEFENSIVE_TIER_EVIDENCE_HISTORY_SCANS or 5)):]:
            if isinstance(payload, dict):
                payloads.append((dict(payload), payload.get("ts_utc") or payload.get("scan_ts_utc"), "candidate_history"))
    except Exception:
        pass

    try:
        if LAST_SCAN:
            payloads.append((dict(LAST_SCAN), (LAST_SCAN or {}).get("ts_utc") or (LAST_SCAN or {}).get("scan_ts_utc"), "last_scan"))
    except Exception:
        pass

    try:
        if LAST_SWING_CANDIDATES:
            payloads.append(({"items": list(LAST_SWING_CANDIDATES or [])}, None, "last_swing_candidates"))
    except Exception:
        pass

    matches = []
    for payload, fallback_ts, source in reversed(payloads):
        for row in _p247_candidate_like_rows_from_payload(payload, limit=limit):
            if str(row.get("symbol") or "").strip().upper() != sym:
                continue
            copy = dict(row)
            row_dt = _p276_candidate_row_ts(copy, fallback_ts=fallback_ts)
            copy["candidate_context_source"] = source
            copy["candidate_context_ts_utc"] = row_dt.isoformat() if row_dt else None
            copy["candidate_context_has_ts"] = bool(row_dt)
            matches.append(copy)

    return matches[:max(1, int(limit or 300))]


def _p276_candidate_rows_near_entry(symbol: str, plan: dict | None, limit: int = 200) -> dict:
    opened_dt = _p276_plan_opened_dt(plan)
    rows = _p276_timestamped_candidate_rows_for_symbol(symbol, limit=limit)
    before_sec = max(0.0, float(SWING_ENTRY_ATTRIBUTION_MATCH_BEFORE_HOURS or 0.0) * 3600.0)
    after_sec = max(0.0, float(SWING_ENTRY_ATTRIBUTION_MATCH_AFTER_MINUTES or 0.0) * 60.0)

    eligible = []
    excluded_after = 0
    excluded_before = 0
    missing_ts = 0

    for row in rows:
        row_dt = _p276_candidate_row_ts(row)
        if not opened_dt or not row_dt:
            missing_ts += 1
            continue

        delta = (row_dt - opened_dt).total_seconds()
        copy = dict(row)
        copy["entry_match_delta_sec"] = round(delta, 3)

        if delta > after_sec:
            excluded_after += 1
            continue
        if delta < -before_sec:
            excluded_before += 1
            continue
        eligible.append(copy)

    eligible.sort(
        key=lambda r: (
            abs(float(r.get("entry_match_delta_sec") or 999999.0)),
            -_safe_float(r.get("rank_score"), 0.0),
            -_safe_float(r.get("selection_quality_score"), 0.0),
        )
    )

    return {
        "opened_at": opened_dt.isoformat() if opened_dt else None,
        "all_match_count": len(rows),
        "timestamp_eligible_count": len(eligible),
        "missing_ts_count": missing_ts,
        "excluded_after_entry_count": excluded_after,
        "excluded_too_old_count": excluded_before,
        "window": {
            "before_hours": float(SWING_ENTRY_ATTRIBUTION_MATCH_BEFORE_HOURS or 0.0),
            "after_minutes": float(SWING_ENTRY_ATTRIBUTION_MATCH_AFTER_MINUTES or 0.0),
        },
        "rows": eligible[:max(1, int(limit or 200))],
    }


def _p276_snapshot_from_candidate(symbol: str, candidate: dict | None) -> dict:
    best = dict(candidate or {})
    if not best:
        return {}

    return {
        "symbol": str(symbol or "").strip().upper(),
        "strategy": best.get("strategy") or best.get("strategy_name") or best.get("signal"),
        "rank_score": best.get("rank_score"),
        "min_rank_score": best.get("min_rank_score"),
        "selection_quality_score": best.get("selection_quality_score"),
        "regime_mode": best.get("regime_mode"),
        "return_20d_pct": best.get("return_20d_pct"),
        "risk_per_share_pct": best.get("risk_per_share_pct"),
        "breakout_distance_pct": best.get("breakout_distance_pct"),
        "close_to_high_pct": best.get("close_to_high_pct"),
        "strong_atr_relax_applied": best.get("strong_atr_relax_applied"),
        "defensive_tightening_enabled": best.get("defensive_tightening_enabled"),
        "defensive_breakout_tier_approved": best.get("defensive_breakout_tier_approved"),
        "defensive_daily_breakout_rollback": best.get("defensive_daily_breakout_rollback"),
        "rejection_reasons_at_entry": list(best.get("rejection_reasons") or []),
        "candidate_context_ts_utc": best.get("candidate_context_ts_utc"),
        "entry_match_delta_sec": best.get("entry_match_delta_sec"),
    }


def _p276_entry_quality_match_for_plan(symbol: str, plan: dict | None) -> dict:
    matched = _p276_candidate_rows_near_entry(symbol, plan, limit=250)
    rows = list(matched.get("rows") or [])
    best = rows[0] if rows else {}

    return {
        "match": matched,
        "best_candidate": dict(best or {}),
        "recovered_snapshot": _p276_snapshot_from_candidate(symbol, best),
    }

def _p251_entry_snapshot_completeness(snapshot: dict | None) -> dict:
    snap = dict(snapshot or {})
    symbol = str(snap.get("symbol") or "").strip().upper()
    strategy = str(snap.get("strategy") or snap.get("strategy_name") or snap.get("signal") or "").strip().lower()
    regime_mode = str(snap.get("regime_mode") or "").strip().lower()

    has_rank = snap.get("rank_score") not in (None, "", [], {})
    has_selection_quality = snap.get("selection_quality_score") not in (None, "", [], {})
    has_return = snap.get("return_20d_pct") not in (None, "", [], {})
    has_risk = snap.get("risk_per_share_pct") not in (None, "", [], {})
    has_breakout_distance = snap.get("breakout_distance_pct") not in (None, "", [], {})
    has_defensive_flag = snap.get("defensive_tightening_enabled") not in (None, "", [], {})

    required_missing = []
    if not symbol:
        required_missing.append("symbol")
    if not strategy:
        required_missing.append("strategy")
    if not regime_mode:
        required_missing.append("regime_mode")
    if not has_rank:
        required_missing.append("rank_score")
    if not has_return:
        required_missing.append("return_20d_pct")
    if not has_risk:
        required_missing.append("risk_per_share_pct")
    if not has_breakout_distance:
        required_missing.append("breakout_distance_pct")

    useful = bool(symbol and strategy and regime_mode and has_rank and has_return and has_risk and has_breakout_distance)
    partial = bool(snap) and not useful

    return {
        "useful": bool(useful),
        "partial": bool(partial),
        "required_missing": required_missing,
        "has_selection_quality": bool(has_selection_quality),
        "has_defensive_flag": bool(has_defensive_flag),
    }


def _p249_snapshot_has_useful_values(snapshot: dict | None) -> bool:
    return bool(_p251_entry_snapshot_completeness(snapshot).get("useful"))


def _p249_snapshot_is_empty_or_placeholder(snapshot: dict | None) -> bool:
    snap = dict(snapshot or {})
    if not snap:
        return True
    return not bool(_p251_entry_snapshot_completeness(snap).get("useful"))

def _p247_entry_quality_backfill_probe_for_position(symbol: str, plan: dict | None) -> dict:
    sym = str(symbol or "").strip().upper()
    p = dict(plan or {})
    thesis = dict(p.get("thesis") or {}) if isinstance(p.get("thesis"), dict) else {}
    existing_snapshot = dict(thesis.get("entry_quality_snapshot") or {}) if isinstance(thesis.get("entry_quality_snapshot"), dict) else {}
    existing_snapshot_has_values = _p249_snapshot_has_useful_values(existing_snapshot)

    rows = _p247_recent_candidate_rows_for_symbol(sym, limit=200)
    best = {}
    if rows:
        best = sorted(
            rows,
            key=lambda r: (
                _safe_float(r.get("rank_score"), 0.0),
                _safe_float(r.get("selection_quality_score"), 0.0),
            ),
            reverse=True,
        )[0]

    recovered_snapshot = {}
    if best:
        recovered_snapshot = {
            "symbol": sym,
            "strategy": best.get("strategy") or best.get("strategy_name") or best.get("signal"),
            "rank_score": best.get("rank_score"),
            "min_rank_score": best.get("min_rank_score"),
            "selection_quality_score": best.get("selection_quality_score"),
            "regime_mode": best.get("regime_mode"),
            "return_20d_pct": best.get("return_20d_pct"),
            "risk_per_share_pct": best.get("risk_per_share_pct"),
            "breakout_distance_pct": best.get("breakout_distance_pct"),
            "close_to_high_pct": best.get("close_to_high_pct"),
            "strong_atr_relax_applied": best.get("strong_atr_relax_applied"),
            "defensive_tightening_enabled": best.get("defensive_tightening_enabled"),
            "defensive_max_20d_return_pct": best.get("defensive_max_20d_return_pct"),
            "defensive_max_risk_per_share_pct": best.get("defensive_max_risk_per_share_pct"),
            "rejection_reasons_at_entry": list(best.get("rejection_reasons") or []),
        }

    reasons = []
    if existing_snapshot_has_values:
        reasons.append("entry_quality_snapshot_already_present")
    elif recovered_snapshot:
        reasons.append("candidate_history_match_available")
    else:
        reasons.append("candidate_history_match_missing")

    return {
        "symbol": sym,
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "read_only_entry_memory_backfill_probe",
        "advisory_only": True,
        "has_existing_entry_quality_snapshot": bool(existing_snapshot_has_values),
        "candidate_history_match_count": len(rows),
        "can_backfill": bool((not existing_snapshot_has_values) and recovered_snapshot),
        "reasons": reasons,
        "existing_snapshot": existing_snapshot,
        "recovered_snapshot_preview": recovered_snapshot,
        "recommended_action": "consider_manual_or_future_safe_backfill" if bool((not existing_snapshot) and recovered_snapshot) else "none",
    }


def _p247_entry_memory_backfill_probe_snapshot() -> dict:
    rows = []
    for sym, plan in list((TRADE_PLAN or {}).items()):
        if not isinstance(plan, dict) or not plan.get("active"):
            continue
        symbol = str(sym or plan.get("symbol") or "").upper()
        rows.append(_p247_entry_quality_backfill_probe_for_position(symbol, plan))

    backfillable = [r for r in rows if r.get("can_backfill")]
    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "read_only_entry_memory_backfill_probe",
        "active_position_count": len(rows),
        "backfillable_count": len(backfillable),
        "backfillable_symbols": [r.get("symbol") for r in backfillable],
        "rows": rows,
        "recommended_action": "review_backfillable_entry_snapshots" if backfillable else "none",
    }

def _p248_apply_entry_quality_snapshot(symbol: str, recovered_snapshot: dict | None) -> dict:
    sym = str(symbol or "").strip().upper()
    snapshot = dict(recovered_snapshot or {})
    if not sym:
        return {"ok": False, "symbol": sym, "applied": False, "reason": "missing_symbol"}
    if not snapshot:
        return {"ok": False, "symbol": sym, "applied": False, "reason": "missing_recovered_snapshot"}

    plan = dict((TRADE_PLAN or {}).get(sym) or {})
    if not plan or not plan.get("active"):
        return {"ok": False, "symbol": sym, "applied": False, "reason": "active_plan_missing"}

    thesis = dict(plan.get("thesis") or {}) if isinstance(plan.get("thesis"), dict) else {}
    existing = dict(thesis.get("entry_quality_snapshot") or {}) if isinstance(thesis.get("entry_quality_snapshot"), dict) else {}

    if _p249_snapshot_has_useful_values(existing):
        return {
            "ok": True,
            "symbol": sym,
            "applied": False,
            "reason": "entry_quality_snapshot_already_present",
            "existing_snapshot": existing,
        }

    replace_reason = "empty_snapshot_replaced" if existing else "missing_snapshot_backfilled"

    thesis["entry_quality_snapshot"] = snapshot
    thesis["entry_quality_snapshot_backfilled"] = True
    thesis["entry_quality_snapshot_backfilled_at_utc"] = datetime.now(timezone.utc).isoformat()
    thesis["entry_quality_snapshot_backfill_patch"] = PATCH_VERSION
    thesis["entry_quality_snapshot_replace_reason"] = replace_reason

    plan["thesis"] = thesis
    plan["rank_score"] = plan.get("rank_score") if plan.get("rank_score") not in (None, "", [], {}) else snapshot.get("rank_score")
    plan["selection_quality_score"] = plan.get("selection_quality_score") if plan.get("selection_quality_score") not in (None, "", [], {}) else snapshot.get("selection_quality_score")
    plan["regime_mode"] = plan.get("regime_mode") if plan.get("regime_mode") not in (None, "", [], {}) else snapshot.get("regime_mode")
    plan["entry_type"] = plan.get("entry_type") if plan.get("entry_type") not in (None, "", [], {}) else "standard"

    TRADE_PLAN[sym] = plan
    persist_result = {"ok": False, "method": "none"}
    try:
        persist_positions_snapshot(
            reason="entry_quality_snapshot_backfill",
            extra={
                "symbol": sym,
                "patch_version": PATCH_VERSION,
                "replace_reason": replace_reason,
                "entry_quality_snapshot": snapshot,
            },
        )
        persist_result = {"ok": True, "method": "persist_positions_snapshot"}
    except Exception as exc:
        persist_result = {"ok": False, "method": "persist_positions_snapshot", "error": str(exc)}

    return {
        "ok": bool(persist_result.get("ok")),
        "symbol": sym,
        "applied": True,
        "reason": "entry_quality_snapshot_backfilled" if persist_result.get("ok") else "applied_but_persist_failed",
        "replace_reason": replace_reason,
        "persist_result": persist_result,
        "entry_quality_snapshot": snapshot,
    }


def _p248_entry_memory_backfill_apply_snapshot(apply: bool = False) -> dict:
    probe = _p247_entry_memory_backfill_probe_snapshot()
    rows = []
    applied = 0
    skipped = 0
    errors = 0

    for row in list(probe.get("rows") or []):
        item = dict(row or {})
        sym = str(item.get("symbol") or "").upper()
        result = {
            "symbol": sym,
            "can_backfill": bool(item.get("can_backfill")),
            "apply_requested": bool(apply),
            "applied": False,
            "reason": "apply_false_read_only",
            "probe": item,
        }

        if apply and item.get("can_backfill"):
            apply_result = _p248_apply_entry_quality_snapshot(sym, item.get("recovered_snapshot_preview") or {})
            result.update({
                "applied": bool(apply_result.get("applied")),
                "reason": apply_result.get("reason"),
                "apply_result": apply_result,
            })
            if apply_result.get("applied") and apply_result.get("ok"):
                applied += 1
            elif apply_result.get("applied") and not apply_result.get("ok"):
                errors += 1
            elif apply_result.get("ok"):
                skipped += 1
            else:
                errors += 1
        elif item.get("can_backfill"):
            skipped += 1
        else:
            skipped += 1

        rows.append(result)

    return {
        "ok": errors == 0,
        "patch_version": PATCH_VERSION,
        "mode": "entry_memory_backfill_apply" if apply else "read_only_entry_memory_backfill_apply_preview",
        "apply": bool(apply),
        "active_position_count": probe.get("active_position_count"),
        "backfillable_count": probe.get("backfillable_count"),
        "applied_count": applied,
        "skipped_count": skipped,
        "error_count": errors,
        "rows": rows,
        "post_apply_guard": _p246_entry_quality_memory_snapshot() if apply else None,
        "post_apply_backfill_probe": _p247_entry_memory_backfill_probe_snapshot() if apply else None,
        "recommended_action": "rerun_entry_quality_memory_guard" if apply and applied else ("review_backfillable_entry_snapshots" if probe.get("backfillable_count") else "none"),
    }

def _live_operator_snapshot(force: bool = False) -> dict:
    now_ts = _time.time()
    cached = LIVE_DASHBOARD_CACHE.get("payload")
    if not force and cached and (now_ts - float(LIVE_DASHBOARD_CACHE.get("ts") or 0.0)) < max(1, int(LIVE_DASHBOARD_CACHE_SEC or 1)):
        out = dict(cached)
        out["cached"] = True
        out["cache_age_sec"] = round(now_ts - float(LIVE_DASHBOARD_CACHE.get("ts") or 0.0), 2)
        return out

    generated_utc = datetime.now(timezone.utc).isoformat()
    generated_ny = now_ny().isoformat()
    broker_positions = list(list_open_positions_details_allowed() or [])
    open_orders = list(list_open_orders_safe() or [])
    broker_symbols = sorted({str((p or {}).get("symbol") or "").upper() for p in broker_positions if str((p or {}).get("symbol") or "").strip()})
    active_plans = {
        str(sym or plan.get("symbol") or "").upper(): dict(plan)
        for sym, plan in TRADE_PLAN.items()
        if isinstance(plan, dict) and str(sym or plan.get("symbol") or "").strip() and (plan.get("active") or _plan_is_pending_entry(plan))
    }
    open_order_symbols = sorted({str((o or {}).get("symbol") or "").upper() for o in open_orders if str((o or {}).get("symbol") or "").strip()})
    reconcile = {
        "broker_positions_count": len(broker_positions),
        "broker_symbols": broker_symbols,
        "active_plan_count": len(active_plans),
        "active_plan_symbols": sorted(active_plans.keys()),
        "open_order_count": len(open_orders),
        "open_order_symbols": open_order_symbols,
        "missing_from_plans": sorted([s for s in broker_symbols if s not in active_plans]),
        "stale_active_plans": sorted([s for s in active_plans if s not in broker_symbols and s not in open_order_symbols]),
        "pending_entry_plan_symbols": sorted([s for s, plan in active_plans.items() if _plan_is_pending_entry(plan)]),
        "orphan_open_order_symbols": sorted([s for s in open_order_symbols if s not in active_plans and s not in broker_symbols]),
        "plans_missing_open_order": sorted([s for s, plan in active_plans.items() if _plan_is_pending_entry(plan) and s not in open_order_symbols and s not in broker_symbols]),
        "partial_fill_plan_symbols": sorted([s for s, plan in active_plans.items() if str(plan.get("order_status") or "").lower() == "partially_filled"]),
        "open_orders": open_orders[:50],
    }
    reconcile.update(_build_reconcile_assessment(reconcile))
    truth = _position_truth_snapshot(snapshot=read_positions_snapshot(), reconcile=reconcile, live=True)
    orders_by_symbol: dict[str, list[dict]] = {}
    for order in open_orders:
        sym = str((order or {}).get("symbol") or "").upper()
        if sym:
            orders_by_symbol.setdefault(sym, []).append(dict(order or {}))
    positions_by_symbol = {str((p or {}).get("symbol") or "").upper(): dict(p or {}) for p in broker_positions if str((p or {}).get("symbol") or "").strip()}
    all_symbols = sorted(set(positions_by_symbol) | set(active_plans) | set(orders_by_symbol))
    rows = []
    for sym in all_symbols:
        pos = dict(positions_by_symbol.get(sym) or {})
        plan = dict(active_plans.get(sym) or {})
        symbol_orders = list(orders_by_symbol.get(sym) or [])
        qty = pos.get("qty") if pos else (plan.get("qty") or plan.get("filled_qty") or 0)
        plan_qty = plan.get("qty") or plan.get("filled_qty") or plan.get("submitted_qty")
        warnings = []
        if pos and not plan:
            warnings.append("missing_internal_plan")
        if plan and not pos and not symbol_orders:
            warnings.append("stale_plan_no_broker_position")
        if symbol_orders:
            warnings.append("open_order_present")
        if _safe_float(qty, 0.0) < 0:
            warnings.append("short_position")
        if pos and plan and plan_qty is not None and abs(abs(_safe_float(qty, 0.0)) - abs(_safe_float(plan_qty, 0.0))) > 0.001:
            warnings.append("qty_mismatch")
        close_side = "buy" if _safe_float(qty, 0.0) < 0 else "sell"
        if any(str((o or {}).get("side") or "").lower() == close_side for o in symbol_orders):
            warnings.append("pending_close_order")
        trust = "bad" if any(w in warnings for w in ["missing_internal_plan", "stale_plan_no_broker_position", "short_position", "qty_mismatch"]) else ("warn" if warnings else "ok")
        rows.append({
            "symbol": sym,
            "trust": trust,
            "warnings": warnings,
            "broker": {
                "present": bool(pos),
                "qty": qty,
                "side": _live_position_side(qty),
                "avg_entry_price": pos.get("avg_entry_price"),
                "last_price": pos.get("current_price") or pos.get("last_price"),
                "market_value": pos.get("market_value"),
                "unrealized_pl": pos.get("unrealized_pl"),
                "unrealized_plpc": pos.get("unrealized_plpc"),
            },
            "plan": {
                "present": bool(plan),
                "signal": plan.get("signal"),
                "strategy_name": plan.get("strategy_name"),
                "status": plan.get("order_status") or plan.get("execution_state") or plan.get("lifecycle_state"),
                "stop_price": plan.get("stop_price"),
                "take_price": plan.get("take_price"),
                "days_held": plan.get("days_held"),
                "opened_at": plan.get("opened_at"),
                "source": plan.get("source"),
                "recovered": bool(plan.get("recovered")),
                "attribution_source": plan.get("attribution_source"),
            },
            "defensive_open_guard": _p245_defensive_open_position_guard(sym, plan, pos) if LIVE_DASHBOARD_INCLUDE_POSITION_ADVISORIES else {"skipped": True, "reason": "live_dashboard_fast_path"},
            "entry_quality_memory_guard": _p246_entry_quality_memory_guard(sym, plan, pos) if LIVE_DASHBOARD_INCLUDE_POSITION_ADVISORIES else {"skipped": True, "reason": "live_dashboard_fast_path"},
            "entry_quality_exit_advisory": _p250_entry_quality_exit_advisory(sym, plan, pos) if LIVE_DASHBOARD_INCLUDE_POSITION_ADVISORIES else {"skipped": True, "reason": "live_dashboard_fast_path"},
            "entry_memory_backfill_probe": _p247_entry_quality_backfill_probe_for_position(sym, plan) if LIVE_DASHBOARD_INCLUDE_POSITION_ADVISORIES else {"skipped": True, "reason": "live_dashboard_fast_path"},
            "open_orders": symbol_orders,
        })
    halt_truth = daily_halt_truth_snapshot()
    stale_halt_pnl = dict(halt_truth.get("today_pnl_truth") or {})
    fresh_today_pnl = dict(today_pnl_truth_snapshot())
    today_pnl = fresh_today_pnl if fresh_today_pnl.get("ok", True) else dict(stale_halt_pnl or fresh_today_pnl)
    today_pnl["live_positions_pnl_source"] = "fresh_today_pnl_truth_snapshot"
    today_pnl["stale_halt_pnl_snapshot"] = stale_halt_pnl
    live_unrealized_truth = _p246_live_unrealized_pnl_truth()
    if live_unrealized_truth.get("ok"):
        today_pnl["today_unrealized_pnl"] = live_unrealized_truth.get("today_unrealized_pnl")
        today_pnl["today_net_pnl"] = round(_safe_float(today_pnl.get("today_realized_pnl"), 0.0) + _safe_float(today_pnl.get("today_unrealized_pnl"), 0.0), 4)
        today_pnl["unrealized_source"] = live_unrealized_truth.get("source")
        today_pnl["unrealized_truth"] = live_unrealized_truth
    flatten_decision = _daily_stop_flatten_decision() if bool(halt_truth.get("daily_halt_active")) else {}
    loss_halt = _live_loss_halt_checklist(halt_truth, today_pnl, flatten_decision, open_orders)
    summary = {
        "broker_positions_count": len(broker_positions),
        "active_plan_count": len(active_plans),
        "open_order_count": len(open_orders),
        "warning_count": sum(1 for r in rows if r.get("warnings")),
        "bad_count": sum(1 for r in rows if r.get("trust") == "bad"),
        "short_count": sum(1 for r in rows if _safe_float((r.get("broker") or {}).get("qty"), 0.0) < 0),
        "position_truth_status": truth.get("status"),
        "position_truth_mismatch_count": truth.get("mismatch_count"),
    }
    payload = {"ok": True, "patch_version": PATCH_VERSION, "generated_utc": generated_utc, "generated_ny": generated_ny, "cached": False, "cache_ttl_sec": int(LIVE_DASHBOARD_CACHE_SEC), "market_open": bool(in_market_hours()), "summary": summary, "positions": rows, "open_orders": open_orders, "position_truth": truth, "reconcile": reconcile, "today_pnl": today_pnl, "loss_halt": loss_halt, "performance": _live_operator_performance_summary()}
    LIVE_DASHBOARD_CACHE.update({"ts": now_ts, "payload": payload})
    return payload
    
    
def _dashboard_pnl_summary(rows: list[dict]) -> dict:
    total_pl = 0.0
    total_count = 0
    winners = 0
    losers = 0
    for row in rows or []:
        v = row.get("unrealized_pl")
        if v is None:
            continue
        try:
            fv = float(v)
        except Exception:
            continue
        total_pl += fv
        total_count += 1
        if fv > 0:
            winners += 1
        elif fv < 0:
            losers += 1
    return {
        "positions_with_price": total_count,
        "total_unrealized_pl": total_pl if total_count else None,
        "winners": winners,
        "losers": losers,
    }


def _dashboard_risk_integrity_view(reconcile: dict | None) -> dict:
    reconcile = dict(reconcile or {})
