def _p268_active_scanner_error_truth(scanner: dict | None) -> dict:
    scanner = dict(scanner or {})
    summary = dict(scanner.get("summary") or {})
    last = dict(scanner.get("last") or {})

    last_event = str(summary.get("last_event") or last.get("event") or "").strip().lower()
    last_status = str(summary.get("last_event_status") or last.get("status") or "").strip().lower()
    last_closed_status = str(summary.get("last_closed_status") or last.get("last_closed_status") or "").strip().lower()
    last_http_status = last.get("last_http_status")
    last_error = str(
        last.get("last_error")
        or (last.get("details") or {}).get("error")
        or ""
    ).strip()

    consecutive_failures = int(summary.get("consecutive_failures") or last.get("consecutive_failures") or 0)
    failure_today = int(summary.get("failure_today") or last.get("failure_today") or 0)
    success_today = int(summary.get("success_today") or last.get("success_today") or 0)

    last_success_dt = _p175_parse_dt(summary.get("last_success_utc") or last.get("last_success_utc"))
    last_failure_dt = _p175_parse_dt(summary.get("last_failure_utc") or last.get("last_failure_utc"))
    failure_after_success = bool(
        last_failure_dt
        and (
            not last_success_dt
            or last_failure_dt > last_success_dt
        )
    )
    recovered_after_failure = bool(
        last_success_dt
        and last_failure_dt
        and last_success_dt >= last_failure_dt
    )

    active_warning_codes = list(summary.get("active_warning_codes") or last.get("active_warning_codes") or [])
    side_effect_truth = dict(summary.get("side_effect_truth") or last.get("side_effect_truth") or {})
    success_after_side_effect = bool(side_effect_truth.get("side_effect_detected"))
    current_event_error = bool(
        last_event in {"scan_error", "scan_fail", "scan_dispatch_http_error"}
        or last_status in {"exception", "failure", "http_error", "error"}
        or str(last_http_status or "") in {"500", "502", "503", "504"}
    )

    active_error = bool(
        consecutive_failures > 0
        and (
            current_event_error
            or failure_after_success
        )
    )

    if (recovered_after_failure and consecutive_failures == 0) or success_after_side_effect:
        active_error = False

    historical_error = bool(
        failure_today > 0
        or last_error
        or active_warning_codes
    )

    return {
        "active_error": active_error,
        "historical_error": historical_error,
        "recovered_after_failure": recovered_after_failure,
        "failure_after_success": failure_after_success,
        "last_event": last_event,
        "last_status": last_status,
        "last_closed_status": last_closed_status,
        "last_http_status": last_http_status,
        "last_error": last_error or None,
        "consecutive_failures": consecutive_failures,
        "failure_today": failure_today,
        "success_today": success_today,
        "success_after_side_effect": success_after_side_effect,
        "side_effect_truth": side_effect_truth,
        "active_warning_codes": active_warning_codes,
        "interpretation": (
            "scanner_timeout_but_side_effects_confirmed"
            if success_after_side_effect
            else "active_scanner_error"
            if active_error
            else "recovered_scanner_errors_present"
            if historical_error
            else "scanner_currently_healthy"
        ),
    }

def _p268_no_trade_brief(sections: dict | None = None) -> dict:
    sections = dict(sections or {})
    scanner = dict(sections.get("scanner") or {})
    scanner_truth = _p268_active_scanner_error_truth(scanner)
    selected_symbols_for_truth = _p298_selected_symbols_light(
        dict((sections.get("candidates_full") or {})),
        list(((sections.get("execution_lifecycle") or {}).get("items") or [])),
    )
    if selected_symbols_for_truth:
        selected_submission_truth = _p297_selected_submission_truth(
            selected_symbols=selected_symbols_for_truth,
            sections=sections,
        )
    else:
        selected_submission_truth = {
            "ok": True,
            "patch_version": PATCH_VERSION,
            "mode": "selected_candidate_submission_truth",
            "selected_symbols": [],
            "selected_count": 0,
            "side_effect_symbols": [],
            "missing_side_effect_symbols": [],
            "selected_side_effect_detected": False,
            "selected_without_side_effect": False,
            "rows": [],
            "recommended_action": "no_selected_symbols_found",
        }
    candidates = dict(sections.get("candidates_full") or {})
    live = dict(sections.get("live_positions") or {})
    live_summary = dict(live.get("summary") or {})
    loss_halt = dict(live.get("loss_halt") or {})
    release = dict(sections.get("release") or {})
    lifecycle = dict(sections.get("execution_lifecycle") or {})
    lifecycle_issues = dict(lifecycle.get("issue_counts") or {})

    selected_count = int(candidates.get("selected_total") or 0)
    eligible_count = int(candidates.get("eligible_count") or 0)
    open_orders = int(live_summary.get("open_order_count") or 0)
    position_count = int(live_summary.get("broker_positions_count") or 0)
    active_plan_count = int(live_summary.get("active_plan_count") or 0)
    market_open = bool(live.get("market_open") or (release.get("market_clock") or {}).get("is_open"))
    live_orders_permitted = bool(release.get("live_orders_permitted"))
    dry_run = bool(release.get("dry_run"))
    kill_switch = bool(release.get("kill_switch"))
    daily_halt_active = bool(loss_halt.get("daily_halt_active") or release.get("daily_halt_active"))
    new_entries_blocked = bool(loss_halt.get("new_entries_blocked"))
    position_truth_status = str(live_summary.get("position_truth_status") or "")

    top_rejections = []
    for row in list(candidates.get("items") or [])[:15]:
        if not isinstance(row, dict):
            continue
        reasons = list(row.get("rejection_reasons") or [])
        if reasons:
            top_rejections.append({
                "symbol": row.get("symbol"),
                "reasons": reasons,
            })

    root_cause = "unknown"
    recommended_action = "review_bundle_sections"

    if selected_submission_truth.get("selected_without_side_effect"):
        root_cause = "selected_candidate_without_submission_side_effect"
        recommended_action = "review_selected_submission_truth_and_scanner_finalizer"
    elif (
        scanner_truth.get("success_after_side_effect")
        and selected_submission_truth.get("selected_side_effect_detected")
    ):
        root_cause = "scanner_timeout_after_selected_side_effect_confirmed"
        recommended_action = "review_reconcile_then_tune_scanner_timeout_or_runtime"
    elif scanner_truth.get("success_after_side_effect"):
        root_cause = "scanner_timeout_after_unrelated_side_effect"
        recommended_action = "ignore_unrelated_side_effect_for_selected_symbol_review_submission_path"
    elif scanner_truth.get("active_error"):
        root_cause = "scanner_error"
        recommended_action = "fix_active_scanner_error_before_strategy_tuning"
    elif not market_open:
        root_cause = "market_closed"
        recommended_action = "wait_for_regular_market_hours"
    elif kill_switch:
        root_cause = "kill_switch_enabled"
        recommended_action = "operator_review_kill_switch"
    elif dry_run or not live_orders_permitted:
        root_cause = "live_orders_not_permitted"
        recommended_action = "review_release_gate_and_envs"
    elif daily_halt_active or new_entries_blocked:
        root_cause = "daily_loss_or_entry_halt"
        recommended_action = "do_not_force_entries_review_loss_halt"
    elif position_truth_status and position_truth_status != "aligned":
        root_cause = "position_truth_not_aligned"
        recommended_action = "run_reconcile_before_entries"
    elif open_orders > 0:
        root_cause = "open_orders_present"
        recommended_action = "wait_or_review_open_orders"
    elif eligible_count == 0 and selected_count == 0:
        root_cause = "candidate_filters_no_eligible_symbols"
        recommended_action = "review_top_rejection_reasons"
    elif eligible_count > 0 and selected_count == 0:
        root_cause = "eligible_but_not_selected"
        recommended_action = "review_capacity_selection_and_correlation_gates"
    elif selected_count > 0:
        root_cause = "selected_candidates_present_check_submission_path"
        recommended_action = "review_scanner_dispatch_and_execution_lifecycle"
    elif position_count == active_plan_count and position_count > 0:
        root_cause = "system_holding_existing_positions"
        recommended_action = "monitor_existing_positions_and_next_scan"

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "no_trade_root_cause_brief",
        "generated_utc": datetime.now(timezone.utc).isoformat(),
        "root_cause": root_cause,
        "recommended_action": recommended_action,
        "market_open": market_open,
        "live_orders_permitted": live_orders_permitted,
        "dry_run": dry_run,
        "kill_switch": kill_switch,
        "daily_halt_active": daily_halt_active,
        "new_entries_blocked": new_entries_blocked,
        "scanner": scanner_truth,
        "selected_submission_truth": selected_submission_truth,
        "candidates": {
            "eligible_count": eligible_count,
            "selected_total": selected_count,
            "selected_symbols": list(candidates.get("selected_symbols") or []),
            "blocked_by_post_change_drawdown": bool(candidates.get("blocked_by_post_change_drawdown")),
            "top_rejections": top_rejections,
        },
        "live": {
            "broker_positions_count": position_count,
            "active_plan_count": active_plan_count,
            "open_order_count": open_orders,
            "position_truth_status": position_truth_status,
            "account_daily_pnl": (live.get("today_pnl") or {}).get("account_daily_pnl"),
            "today_realized_pnl": (live.get("today_pnl") or {}).get("today_realized_pnl"),
            "today_unrealized_pnl": (live.get("today_pnl") or {}).get("today_unrealized_pnl"),
        },
        "execution_lifecycle": {
            "plan_count": lifecycle.get("plan_count"),
            "errors": lifecycle_issues.get("error"),
            "warnings": lifecycle_issues.get("warn"),
        },
        "advisory_notes": [
            "historical_scanner_errors_present"
            if scanner_truth.get("historical_error") and not scanner_truth.get("active_error")
            else "",
        ],
    }


def _p268_bundle_sections(scope: str, limit: int = 25, refresh_live: bool = True) -> dict:
    scope = str(scope or "all").strip().lower()
    limit = max(1, min(int(limit or 25), 100))

    sections: dict[str, dict] = {
        "build": _p268_safe_section("build", _build_fingerprint_snapshot),
        "release": _p268_safe_section("release", _p268_release_snapshot),
        "scanner": _p268_safe_section("scanner", lambda: _p274h_compact_scanner(history_limit=DIAGNOSTIC_SCANNER_HISTORY_LIMIT)),
        "live_positions": _p268_safe_section("live_positions", lambda: _live_operator_snapshot(force=refresh_live)),
        "execution_lifecycle": _p268_safe_section("execution_lifecycle", lambda: diagnostics_execution_lifecycle(limit=limit)),
        "worker_exit_status": _p268_safe_section("worker_exit_status", lambda: _worker_exit_status_snapshot(limit=limit)),
        "candidates_full": _p268_safe_section("candidates_full", lambda: _diagnostics_candidates_payload(limit=limit, full=True)),
    }

    if scope in {"all", "swing", "no_trade"}:
        sections.update({
            "swing_post_change_drawdown": _p268_safe_section("swing_post_change_drawdown", lambda: _p261_post_change_drawdown_snapshot(perf_state=_recompute_strategy_performance_state())),
            "daily_breakout_circuit_release_criteria": _p268_safe_section("daily_breakout_circuit_release_criteria", _p264_daily_breakout_circuit_release_criteria),
            "strategy_performance": _p268_safe_section("strategy_performance", lambda: diagnostics_strategy_performance(None)),
            "broker_preferred_performance": _p268_safe_section("broker_preferred_performance", _p245_broker_preferred_performance_snapshot),
            "entry_quality_exit_advisory": _p268_safe_section("entry_quality_exit_advisory", _p250_entry_quality_exit_advisory_snapshot),
            "current_open_stall_risk_preview": _p268_safe_section("current_open_stall_risk_preview", _p257_current_open_stall_risk_preview),
        })

    if scope in {"all", "intraday"}:
        sections.update({
            "intraday_bundle_summary": _p268_safe_section("intraday_bundle_summary", _p274h_lazy_intraday_bundle_summary),
            "intraday_live_brief": _p268_safe_section("intraday_live_brief", lambda: diagnostics_intraday_live_brief(None)),
            "intraday_quality_scoped_live_promotion": _p268_safe_section("intraday_quality_scoped_live_promotion", lambda: diagnostics_intraday_quality_scoped_live_promotion(None, detail="compact")),
            "eod_flatten_status": _p268_safe_section("eod_flatten_status", lambda: _p270_compact_eod_summary(_eod_flatten_status_snapshot(live=True))),
        })

    if scope in {"all", "performance"}:
        sections.update({
            "strategy_performance": _p268_safe_section("strategy_performance", lambda: diagnostics_strategy_performance(None)),
            "swing_performance_attribution": _p268_safe_section("swing_performance_attribution", _swing_performance_attribution),
            "broker_preferred_performance": _p268_safe_section("broker_preferred_performance", _p245_broker_preferred_performance_snapshot),
            "broker_preferred_daily_pnl_dedup": _p268_safe_section("broker_preferred_daily_pnl_dedup", lambda: {
                "ok": True,
                "patch_version": PATCH_VERSION,
                "today_pnl_truth": today_pnl_truth_snapshot(),
                "deduped_strategy_state_today": _p254_broker_preferred_today_strategy_realized_pnl(),
            }),
        })

    if scope in {"all", "risk"}:
        sections.update({
            "loss_control_incident": _p268_safe_section("loss_control_incident", lambda: _loss_control_incident_summary(
                daily_halt_truth=daily_halt_truth_snapshot(),
                today_pnl_truth=today_pnl_truth_snapshot(),
                flatten_decision={},
                snapshot=read_positions_snapshot(),
            )),
            "swing_damage_guard": _p268_safe_section("swing_damage_guard", _swing_damage_guard_snapshot),
            "stall_loss_guard_live_validation": _p268_safe_section("stall_loss_guard_live_validation", _p257_stall_loss_guard_live_validation),
            "eod_flatten_status": _p268_safe_section("eod_flatten_status", lambda: _eod_flatten_status_snapshot(live=True)),
        })

    sections["no_trade_brief"] = _p268_no_trade_brief(sections)
    return sections


def _p268_operator_bundle(scope: str = "all", limit: int = 25, refresh_live: bool = True) -> dict:
    _ensure_runtime_state_loaded()
    sections = _p268_bundle_sections(scope=scope, limit=limit, refresh_live=refresh_live)
    failed_sections = [
        name for name, payload in sections.items()
        if isinstance(payload, dict) and payload.get("_bundle_collection_ok") is False
    ]
    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "scenario_diagnostic_bundle",
        "scope": str(scope or "all").strip().lower(),
        "generated_utc": datetime.now(timezone.utc).isoformat(),
        "generated_ny": now_ny().isoformat(),
        "read_only": True,
        "failed_section_count": len(failed_sections),
        "failed_sections": failed_sections,
        "brief": sections.get("no_trade_brief"),
        "sections": sections,
    }

def _p270_gate_result(name: str, ok: bool, value=None, required: bool = True, note: str = "") -> dict:
    return {
        "name": name,
        "ok": bool(ok),
        "required": bool(required),
        "value": value,
        "note": note,
    }


def _p270_intraday_gate_metrics(paper: dict | None, proof: dict | None) -> dict:
    paper = dict(paper or {})
    proof = dict(proof or {})
    required = str(CONCURRENT_INTRADAY_REQUIRED_QUALITY_SCENARIO or "").strip().lower()

    gate = {}
    for key in [
        "promoted_paper_gate",
        "tournament_recommended_gate",
        "replay_aligned_rank_gate",
        "paper_pilot_conservative_gate",
        "legacy_core_symbols_gate",
    ]:
        candidate = dict(paper.get(key) or {})
        if str(candidate.get("scenario") or "").strip().lower() == required:
            gate = candidate
            break

    quality_truth = dict(proof.get("quality_scoped_live_promotion_truth") or {})
    if not gate and str(quality_truth.get("scenario") or "").strip().lower() == required:
        gate = dict(quality_truth.get("active_filter_result") or {})

    settled_count = int(
        gate.get("accepted_count")
        or gate.get("settled_count")
        or quality_truth.get("settled_count")
        or 0
    )
    avg_r = _safe_float(
        gate.get("avg_r")
        if gate.get("avg_r") is not None
        else quality_truth.get("settled_avg_r"),
        0.0,
    )
    positive_rate = _safe_float(
        gate.get("positive_rate")
        if gate.get("positive_rate") is not None
        else quality_truth.get("settled_positive_rate"),
        0.0,
    )
    raw_stop_hit_rate = gate.get("stop_hit_rate")
    if raw_stop_hit_rate is None:
        stop_hit_count = int(gate.get("stop_hit_count") or 0)
        stop_hit_rate = round(stop_hit_count / max(1, settled_count), 4) if settled_count else 0.0
    else:
        stop_hit_rate = _safe_float(raw_stop_hit_rate, 0.0)

    return {
        "required_scenario": required,
        "gate": gate,
        "scenario": str(gate.get("scenario") or "").strip().lower(),
        "ready": bool(gate.get("ready")),
        "settled_count": settled_count,
        "avg_r": round(float(avg_r), 4),
        "positive_rate": round(float(positive_rate), 4),
        "stop_hit_rate": round(float(stop_hit_rate), 4),
        "thresholds": {
            "min_settled": int(CONCURRENT_INTRADAY_MIN_SETTLED),
            "min_avg_r": float(CONCURRENT_INTRADAY_MIN_AVG_R),
            "min_positive_rate": float(CONCURRENT_INTRADAY_MIN_POSITIVE_RATE),
            "max_stop_hit_rate": float(CONCURRENT_INTRADAY_MAX_STOP_HIT_RATE),
        },
    }

