def _candidate_row_compact(item: dict) -> dict:
    row = dict(item or {})
    return {
        'symbol': str(row.get('symbol') or '').upper(),
        'strategy': row.get('strategy'),
        'eligible': bool(row.get('eligible')),
        'rank_score': row.get('rank_score'),
        'selection_quality_score': row.get('selection_quality_score'),
        'rejection_reasons': list(row.get('rejection_reasons') or []),
        'selection_blockers': list(row.get('selection_blockers') or []),
        'close': row.get('close'),
        'close_to_high_pct': row.get('close_to_high_pct'),
        'breakout_distance_pct': row.get('breakout_distance_pct'),
        'correlation_group_id': row.get('correlation_group_id'),
        'correlation_group_open_count': row.get('correlation_group_open_count'),
    }

def _p406_candidate_row_fast(item: dict, open_symbols: set[str] | None = None) -> dict:
    row = dict(item or {})
    sym = str(row.get("symbol") or "").strip().upper()
    open_symbols = open_symbols or set()
    contract = dict(row.get("swing_production_contract") or {})
    return {
        "symbol": sym,
        "strategy": row.get("strategy") or row.get("signal"),
        "eligible": bool(row.get("eligible")) and sym not in open_symbols,
        "raw_eligible": bool(row.get("eligible")),
        "selected": bool(row.get("selected")) and sym not in open_symbols,
        "raw_selected": bool(row.get("selected")),
        "open_position": sym in open_symbols,
        "candidate_context": "open_position_not_new_entry" if sym in open_symbols else "new_entry_candidate",
        "rank_score": row.get("rank_score"),
        "selection_quality_score": row.get("selection_quality_score"),
        "close": row.get("close"),
        "close_to_high_pct": row.get("close_to_high_pct"),
        "breakout_distance_pct": row.get("breakout_distance_pct"),
        "risk_per_share_pct": row.get("risk_per_share_pct"),
        "return_20d_pct": row.get("return_20d_pct"),
        "entry_type": row.get("entry_type"),
        "selected_source": row.get("selected_source"),
        "production_contract_approved": bool(row.get("production_contract_approved") or contract.get("approved")),
        "swing_production_contract": contract,
        "rejection_reasons": list(row.get("rejection_reasons") or []),
        "selection_blockers": list(row.get("selection_blockers") or []),
        "correlation_group_id": row.get("correlation_group_id"),
        "correlation_group_open_count": row.get("correlation_group_open_count"),
    }

def _p412_rebuild_current_candidate_contract_rows(rows: list | None) -> list[dict]:
    source_rows = [
        dict(row or {})
        for row in list(rows or [])
        if isinstance(row, dict)
    ]
    if not source_rows:
        return []

    try:
        rebuilt = _p323_enforce_production_contract_selection(
            source_rows,
            global_block_reasons=[],
        )
    except Exception as exc:
        rebuilt = []
        for row in source_rows:
            c = dict(row or {})
            c["p412_contract_rebuild_error"] = str(exc)
            rebuilt.append(c)

    return [
        dict(row or {})
        for row in list(rebuilt or [])
        if isinstance(row, dict)
    ]

def _p413_eligible_new_entry_rows_from_fast_payload(payload: dict | None) -> list[dict]:
    data = dict(payload or {})
    rows = [
        dict(row or {})
        for row in list(
            data.get("eligible_new_entry_rows_all")
            or data.get("candidate_rows")
            or data.get("top_new_entry_candidates")
            or []
        )
        if isinstance(row, dict)
        and bool(row.get("eligible"))
        and not bool(row.get("open_position"))
    ]
    rows.sort(
        key=lambda row: (
            float(_safe_float(row.get("rank_score"), 0.0)),
            float(_safe_float(row.get("selection_quality_score"), 0.0)),
        ),
        reverse=True,
    )
    return rows

def _p413_eligible_new_entry_symbols_from_fast_payload(payload: dict | None) -> list[str]:
    return _dedupe_keep_order([
        str(row.get("symbol") or "").strip().upper()
        for row in _p413_eligible_new_entry_rows_from_fast_payload(payload)
        if str(row.get("symbol") or "").strip()
    ])

def _p524_current_candidate_rows_by_symbol(payload: dict | None) -> dict[str, dict]:
    data = dict(payload or {})
    rows = []
    for key in (
        "candidate_rows",
        "eligible_new_entry_rows_all",
        "top_new_entry_candidates",
        "top_candidates",
    ):
        for row in list(data.get(key) or []):
            if not isinstance(row, dict):
                continue
            symbol = str(row.get("symbol") or "").strip().upper()
            if not symbol:
                continue
            item = dict(row)
            item.setdefault("_p524_source", key)
            rows.append(item)

    by_symbol: dict[str, dict] = {}
    for row in rows:
        symbol = str(row.get("symbol") or "").strip().upper()
        if symbol and symbol not in by_symbol:
            by_symbol[symbol] = row
    return by_symbol

def _p524_revalidate_current_selected_symbols(
    selected_symbols: list[str] | tuple[str, ...] | None,
    current_candidate_truth: dict | None,
    *,
    preserve_symbols: list[str] | tuple[str, ...] | None = None,
) -> dict:
    symbols = _dedupe_keep_order([
        str(sym or "").strip().upper()
        for sym in list(selected_symbols or [])
        if str(sym or "").strip()
    ])
    preserve_set = {
        str(sym or "").strip().upper()
        for sym in list(preserve_symbols or [])
        if str(sym or "").strip()
    }
    current_rows = _p524_current_candidate_rows_by_symbol(current_candidate_truth)

    active_symbols: list[str] = []
    stale_symbols: list[str] = []
    unknown_symbols: list[str] = []
    stale_rows: list[dict] = []

    for sym in symbols:
        row = dict(current_rows.get(sym) or {})
        if sym in preserve_set:
            active_symbols.append(sym)
            continue
        if not row:
            unknown_symbols.append(sym)
            active_symbols.append(sym)
            continue

        current_eligible = bool(row.get("eligible") or row.get("raw_eligible"))
        current_selected = bool(row.get("selected") or row.get("raw_selected"))
        if current_eligible and current_selected:
            active_symbols.append(sym)
            continue

        stale_symbols.append(sym)
        stale_rows.append({
            "symbol": sym,
            "eligible": bool(row.get("eligible")),
            "raw_eligible": bool(row.get("raw_eligible")),
            "selected": bool(row.get("selected")),
            "raw_selected": bool(row.get("raw_selected")),
            "rank_score": row.get("rank_score"),
            "rejection_reasons": list(row.get("rejection_reasons") or row.get("reasons") or []),
            "source": row.get("_p524_source"),
            "classification": "selection_stale_revalidated_blocked",
        })

    return {
        "applied": bool(symbols),
        "source": "current_candidate_truth",
        "input_symbols": symbols,
        "active_symbols": active_symbols,
        "stale_symbols": stale_symbols,
        "unknown_symbols_preserved": unknown_symbols,
        "stale_rows": stale_rows,
        "stale_count": len(stale_symbols),
        "preserved_symbols": _dedupe_keep_order(list(preserve_set)),
    }

def _p409_current_near_miss_rows(limit: int = 25) -> list[dict]:
    payload = _p406_fast_current_candidate_payload(limit=limit)
    rows = [
        dict(row or {})
        for row in list(payload.get("top_new_entry_candidates") or [])
        if isinstance(row, dict)
    ]
    if not rows:
        rows = [
            dict(row or {})
            for row in list(payload.get("top_candidates") or [])
            if isinstance(row, dict)
            and not bool(row.get("open_position"))
        ]
    return rows[: max(1, min(int(limit or 25), 100))]


def _p409_first_2k_symbol_profile() -> dict:
    rows = [
        dict(row or {})
        for row in list((STRATEGY_PERFORMANCE_STATE or {}).get("closed_trades") or [])
        if isinstance(row, dict)
    ]

    # Use earliest profitable trades as the closest available proxy for the first-$2K window.
    ordered = []
    running = 0.0
    for row in rows:
        pnl = _safe_float(row.get("gross_pnl") or row.get("pnl") or row.get("realized_pnl"), 0.0)
        ordered.append(row)
        if pnl > 0:
            running += pnl
        if running >= 2000:
            break

    if not ordered:
        ordered = rows[:50]

    winners = [
        row for row in ordered
        if _safe_float(row.get("gross_pnl") or row.get("pnl") or row.get("realized_pnl"), 0.0) > 0
    ]
    winner_symbols = _dedupe_keep_order([
        str(row.get("symbol") or "").strip().upper()
        for row in winners
        if str(row.get("symbol") or "").strip()
    ])

    return {
        "source": "strategy_performance_state_first_profitable_window_proxy",
        "window_trade_count": len(ordered),
        "winner_count": len(winners),
        "winner_symbols": winner_symbols,
        "top_winner_symbols": winner_symbols[:15],
        "profit_accumulated": round(sum(
            max(0.0, _safe_float(row.get("gross_pnl") or row.get("pnl") or row.get("realized_pnl"), 0.0))
            for row in ordered
        ), 4),
    }


def _p409_candidate_profile_match(row: dict, first_2k_profile: dict) -> dict:
    symbol = str((row or {}).get("symbol") or "").strip().upper()
    winner_symbols = set(first_2k_profile.get("winner_symbols") or [])
    rank_score = _safe_float((row or {}).get("rank_score"), 0.0)
    close_to_high = _safe_float((row or {}).get("close_to_high_pct"), 0.0)
    breakout_distance = _safe_float((row or {}).get("breakout_distance_pct"), 0.0)
    risk_pct = _safe_float((row or {}).get("risk_per_share_pct"), 0.0)
    return_20d = _safe_float((row or {}).get("return_20d_pct"), 0.0)

    match_score = 0
    reasons = []

    if symbol in winner_symbols:
        match_score += 35
        reasons.append("symbol_in_first_2k_winners")
    if rank_score >= 97:
        match_score += 20
        reasons.append("rank_near_current_gate")
    if close_to_high >= 99.0 or close_to_high >= 0.99:
        match_score += 15
        reasons.append("near_high")
    if breakout_distance >= -1.0 or breakout_distance >= -0.01:
        match_score += 15
        reasons.append("near_breakout")
    if 0 < risk_pct <= 2.5 or 0 < risk_pct <= 0.025:
        match_score += 10
        reasons.append("controlled_risk")
    if return_20d > 0:
        match_score += 5
        reasons.append("positive_20d_return")

    return {
        "symbol": symbol,
        "match_score": match_score,
        "match_reasons": reasons,
        "first_2k_winner_symbol": symbol in winner_symbols,
    }


def _p409_rank_relaxation_replay(limit: int = 25) -> dict:
    lim = max(1, min(int(limit or 25), 100))
    rows = _p409_current_near_miss_rows(limit=lim)
    profile = _p409_first_2k_symbol_profile()
    scenarios = [103, 100, 99, 98, 97, 95, 92]

    scenario_rows = []
    for threshold in scenarios:
        passed = []
        for row in rows:
            rank_score = _safe_float(row.get("rank_score"), 0.0)
            reasons = [str(r) for r in list(row.get("rejection_reasons") or [])]
            non_rank_blockers = [
                r for r in reasons
                if r not in {"production_contract_rank_below_min", "rank_score_below_min"}
            ]
            if rank_score >= float(threshold) and not non_rank_blockers:
                enriched = dict(row)
                enriched["profile_match"] = _p409_candidate_profile_match(row, profile)
                passed.append(enriched)

        passed.sort(
            key=lambda r: (
                _safe_float((r.get("profile_match") or {}).get("match_score"), 0.0),
                _safe_float(r.get("rank_score"), 0.0),
                _safe_float(r.get("selection_quality_score"), 0.0),
            ),
            reverse=True,
        )

        scenario_rows.append({
            "rank_threshold": threshold,
            "pass_count": len(passed),
            "symbols": [r.get("symbol") for r in passed],
            "rows": passed[:10],
        })

    best = next((row for row in scenario_rows if int(row.get("pass_count") or 0) > 0), None)

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "first_2k_rank_relaxation_replay",
        "read_only": True,
        "production_threshold": float(SWING_PRODUCTION_RESET_MIN_RANK_SCORE),
        "candidate_count": len(rows),
        "first_2k_profile": profile,
        "scenarios": scenario_rows,
        "best_non_empty_scenario": best,
        "recommended_action": (
            "review_best_non_empty_scenario_before_any_live_threshold_change"
            if best
            else "no_rank_only_relaxation_candidate_currently"
        ),
    }

def _p410_geometry_value_pct(row: dict, key: str) -> float:
    value = _safe_float((row or {}).get(key), 0.0)

    # Current candidate rows already store breakout distance, risk, and returns as
    # percent-style values. Do not infer-scale those fields or valid near-misses
    # such as IWM -0.149% become bogus -14.9%.
    if key == "close_to_high_pct" and 0 < value <= 1.5:
        return value * 100.0

    return value

def _p410_current_geometry_replay(limit: int = 25) -> dict:
    lim = max(1, min(int(limit or 25), 100))
    rows = _p409_current_near_miss_rows(limit=lim)
    profile = _p409_first_2k_symbol_profile()

    scenarios = [
        {"name": "production", "max_below_breakout_pct": 0.07, "min_rank_score": float(SWING_PRODUCTION_RESET_MIN_RANK_SCORE)},
        {"name": "below_1_pct_rank_103", "max_below_breakout_pct": 1.0, "min_rank_score": 103.0},
        {"name": "below_1_pct_rank_97", "max_below_breakout_pct": 1.0, "min_rank_score": 97.0},
        {"name": "below_2_pct_rank_97", "max_below_breakout_pct": 2.0, "min_rank_score": 97.0},
        {"name": "below_3_pct_rank_97", "max_below_breakout_pct": 3.0, "min_rank_score": 97.0},
        {"name": "below_3_pct_rank_92", "max_below_breakout_pct": 3.0, "min_rank_score": 92.0},
    ]

    scenario_rows = []
    for scenario in scenarios:
        max_below = float(scenario.get("max_below_breakout_pct") or 0.0)
        min_rank = float(scenario.get("min_rank_score") or 0.0)
        passed = []

        for row in rows:
            symbol = str(row.get("symbol") or "").strip().upper()
            rank_score = _safe_float(row.get("rank_score"), 0.0)
            breakout_distance = _p410_geometry_value_pct(row, "breakout_distance_pct")
            close_to_high = _p410_geometry_value_pct(row, "close_to_high_pct")
            risk_pct = _p410_geometry_value_pct(row, "risk_per_share_pct")
            reasons = [str(r) for r in list(row.get("rejection_reasons") or [])]

            below_breakout_ok = breakout_distance >= -max_below
            rank_ok = rank_score >= min_rank
            close_to_high_ok = close_to_high >= 98.5
            risk_ok = risk_pct <= 12.0

            remaining_blockers = []
            if not rank_ok:
                remaining_blockers.append("rank_score")
            if not below_breakout_ok:
                remaining_blockers.append("breakout_distance")
            if not close_to_high_ok:
                remaining_blockers.append("close_to_high")
            if not risk_ok:
                remaining_blockers.append("risk_per_share")

            if rank_ok and below_breakout_ok and close_to_high_ok and risk_ok:
                enriched = dict(row)
                enriched["geometry_replay"] = {
                    "scenario": scenario.get("name"),
                    "rank_score": rank_score,
                    "breakout_distance_pct": breakout_distance,
                    "close_to_high_pct": close_to_high,
                    "risk_per_share_pct": risk_pct,
                    "original_rejection_reasons": reasons,
                }
                enriched["profile_match"] = _p409_candidate_profile_match(row, profile)
                passed.append(enriched)

        passed.sort(
            key=lambda r: (
                _safe_float((r.get("profile_match") or {}).get("match_score"), 0.0),
                _safe_float(r.get("rank_score"), 0.0),
                _safe_float(r.get("selection_quality_score"), 0.0),
            ),
            reverse=True,
        )

        scenario_rows.append({
            "scenario": scenario.get("name"),
            "max_below_breakout_pct": max_below,
            "min_rank_score": min_rank,
            "pass_count": len(passed),
            "symbols": [r.get("symbol") for r in passed],
            "rows": passed[:10],
        })

    best = next((row for row in scenario_rows if int(row.get("pass_count") or 0) > 0), None)

    first_2k_geometry_rows = []
    for row in rows:
        match = _p409_candidate_profile_match(row, profile)
        first_2k_geometry_rows.append({
            "symbol": row.get("symbol"),
            "rank_score": row.get("rank_score"),
            "selection_quality_score": row.get("selection_quality_score"),
            "breakout_distance_pct": _p410_geometry_value_pct(row, "breakout_distance_pct"),
            "close_to_high_pct": _p410_geometry_value_pct(row, "close_to_high_pct"),
            "risk_per_share_pct": _p410_geometry_value_pct(row, "risk_per_share_pct"),
            "return_20d_pct": _p410_geometry_value_pct(row, "return_20d_pct"),
            "rejection_reasons": list(row.get("rejection_reasons") or []),
            "profile_match": match,
        })

    first_2k_geometry_rows.sort(
        key=lambda r: (
            _safe_float((r.get("profile_match") or {}).get("match_score"), 0.0),
            _safe_float(r.get("rank_score"), 0.0),
            _safe_float(r.get("selection_quality_score"), 0.0),
        ),
        reverse=True,
    )

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "breakout_distance_relaxation_replay",
        "read_only": True,
        "candidate_count": len(rows),
        "production": {
            "min_rank_score": float(SWING_PRODUCTION_RESET_MIN_RANK_SCORE),
            "max_below_breakout_pct": (
                float(SWING_PRODUCTION_RESET_MAX_BELOW_BREAKOUT_PCT) * 100.0
                if abs(float(SWING_PRODUCTION_RESET_MAX_BELOW_BREAKOUT_PCT)) <= 1.0
                else float(SWING_PRODUCTION_RESET_MAX_BELOW_BREAKOUT_PCT)
            ),
            "min_close_to_high_pct": (
                float(SWING_PRODUCTION_RESET_MIN_CLOSE_TO_HIGH_PCT) * 100.0
                if abs(float(SWING_PRODUCTION_RESET_MIN_CLOSE_TO_HIGH_PCT)) <= 1.5
                else float(SWING_PRODUCTION_RESET_MIN_CLOSE_TO_HIGH_PCT)
            ),
            "max_risk_per_share_pct": (
                float(SWING_PRODUCTION_RESET_MAX_RISK_PER_SHARE_PCT) * 100.0
                if abs(float(SWING_PRODUCTION_RESET_MAX_RISK_PER_SHARE_PCT)) <= 1.5
                else float(SWING_PRODUCTION_RESET_MAX_RISK_PER_SHARE_PCT)
            ),
        },
        "first_2k_profile": profile,
        "scenarios": scenario_rows,
        "best_non_empty_scenario": best,
        "first_2k_winner_geometry_audit": first_2k_geometry_rows[:15],
        "recommended_action": (
            "review_best_geometry_scenario_before_any_live_threshold_change"
            if best
            else "no_geometry_relaxation_candidate_currently"
        ),
    }

def _p527_late_day_first_2k_near_miss_calibration(limit: int = 25) -> dict:
    lim = max(1, min(int(limit or 25), 100))
    payload = _p406_fast_current_candidate_payload(limit=lim)
    rows = [
        dict(row or {})
        for row in list(payload.get("top_new_entry_candidates") or payload.get("candidate_rows") or [])
        if isinstance(row, dict)
        and not bool(row.get("open_position"))
    ]
    profile = _p409_first_2k_symbol_profile()

    current_selected = set(payload.get("selected_symbols") or [])
    stale_selected = set(payload.get("stale_revalidated_blocked_symbols") or [])
    late_day_rows = []
    sleeve_candidates = []

    for row in rows:
        reasons = [str(reason) for reason in list(row.get("rejection_reasons") or [])]
        late_day_reasons = [
            reason for reason in reasons
            if reason.startswith("late_day_") or reason == "late_day_entry_quality_tightening"
        ]
        if not late_day_reasons:
            continue

        symbol = str(row.get("symbol") or "").strip().upper()
        profile_match = _p409_candidate_profile_match(row, profile)
        rank_score = float(_safe_float(row.get("rank_score"), 0.0))
        target_path_score = float(_safe_float(
            row.get("target_path_score")
            or ((row.get("target_path_profit") or {}).get("score") if isinstance(row.get("target_path_profit"), dict) else 0.0),
            0.0,
        ))
        breakout_distance = _p410_geometry_value_pct(row, "breakout_distance_pct")
        close_to_high = _p410_geometry_value_pct(row, "close_to_high_pct")
        risk_pct = _p410_geometry_value_pct(row, "risk_per_share_pct")
        risk_calibrated = str(row.get("entry_type") or "").strip() in {
            "swing_production_risk_calibrated_starter",
            "swing_production_near_rank_revival",
            "first_2k_geometry_sleeve",
            "target_path_risk_adjusted_near_miss",
        }

        rank_gap = max(0.0, float(SWING_LATE_DAY_ENTRY_MIN_RANK_SCORE) - rank_score)
        geometry_ok = bool(
            breakout_distance >= -1.0
            and close_to_high >= 98.5
            and 0.0 < risk_pct <= 12.0
        )
        match_score = float(_safe_float(profile_match.get("match_score"), 0.0))
        first_2k_like = bool(
            match_score >= float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MIN_MATCH_SCORE)
            or symbol in set(profile.get("winner_symbols") or [])
        )
        reduced_risk_sleeve_candidate = bool(
            SWING_LATE_DAY_FIRST_2K_SLEEVE_ENABLED
            and first_2k_like
            and geometry_ok
            and rank_gap <= float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MAX_RANK_GAP)
            and (
                not bool(SWING_LATE_DAY_ENTRY_ALLOW_RISK_CALIBRATED_ONLY)
                or risk_calibrated
            )
        )

        item = {
            "symbol": symbol,
            "rank_score": rank_score,
            "late_day_min_rank_score": float(SWING_LATE_DAY_ENTRY_MIN_RANK_SCORE),
            "rank_gap": round(rank_gap, 4),
            "target_path_score": target_path_score,
            "breakout_distance_pct": breakout_distance,
            "close_to_high_pct": close_to_high,
            "risk_per_share_pct": risk_pct,
            "entry_type": row.get("entry_type"),
            "risk_calibrated": bool(risk_calibrated),
            "profile_match": profile_match,
            "first_2k_like": bool(first_2k_like),
            "geometry_ok": bool(geometry_ok),
            "reduced_risk_sleeve_candidate": bool(reduced_risk_sleeve_candidate),
            "live_selected": symbol in current_selected,
            "stale_selected": symbol in stale_selected,
            "late_day_reasons": late_day_reasons,
            "rejection_reasons": reasons,
            "advisory_sleeve": {
                "mode": "live_reduced_risk_late_day_sleeve",
                "enabled": bool(SWING_LATE_DAY_FIRST_2K_SLEEVE_ENABLED),
                "risk_multiplier": float(SWING_LATE_DAY_FIRST_2K_SLEEVE_RISK_MULTIPLIER),
                "max_rank_gap": float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MAX_RANK_GAP),
                "min_match_score": float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MIN_MATCH_SCORE),
                "reason": (
                    "eligible_for_reduced_risk_late_day_first_2k_sleeve"
                    if reduced_risk_sleeve_candidate
                    else "not_live_sleeve_eligible"
                ),
            },
        }
        late_day_rows.append(item)
        if reduced_risk_sleeve_candidate:
            sleeve_candidates.append(item)

    late_day_rows.sort(
        key=lambda item: (
            bool(item.get("reduced_risk_sleeve_candidate")),
            float((item.get("profile_match") or {}).get("match_score") or 0.0),
            float(item.get("rank_score") or 0.0),
        ),
        reverse=True,
    )

    recommended_action = (
        "review_reduced_risk_sleeve_candidates_with_replay_before_live_promotion"
        if sleeve_candidates
        else "late_day_filter_currently_blocks_all_near_misses"
        if late_day_rows
        else "no_late_day_near_misses_currently"
    )

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "late_day_first_2k_near_miss_calibration",
        "read_only": True,
        "does_not_submit_orders": True,
        "does_not_change_state": True,
        "mantra": "cleanup_simplify_align_with_first_2k_sweet_spot",
        "current_candidate_status": payload.get("status"),
        "current_candidate_recommended_action": payload.get("recommended_action"),
        "candidate_count": int(payload.get("candidate_count") or 0),
        "eligible_count": int(payload.get("eligible_count") or 0),
        "selected_symbols": list(payload.get("selected_symbols") or []),
        "stale_revalidated_blocked_symbols": list(payload.get("stale_revalidated_blocked_symbols") or []),
        "late_day_config": {
            "enabled": bool(SWING_LATE_DAY_ENTRY_QUALITY_TIGHTEN_ENABLED),
            "start_ny": str(SWING_LATE_DAY_ENTRY_QUALITY_START_NY),
            "min_rank_score": float(SWING_LATE_DAY_ENTRY_MIN_RANK_SCORE),
            "min_target_path_score": float(SWING_LATE_DAY_ENTRY_MIN_TARGET_PATH_SCORE),
            "allow_risk_calibrated_only": bool(SWING_LATE_DAY_ENTRY_ALLOW_RISK_CALIBRATED_ONLY),
        },
        "live_sleeve_config": {
            "enabled": bool(SWING_LATE_DAY_FIRST_2K_SLEEVE_ENABLED),
            "max_rank_gap": float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MAX_RANK_GAP),
            "min_match_score": float(SWING_LATE_DAY_FIRST_2K_SLEEVE_MIN_MATCH_SCORE),
            "risk_multiplier": float(SWING_LATE_DAY_FIRST_2K_SLEEVE_RISK_MULTIPLIER),
            "max_entries_per_scan": 1,
        },
        "first_2k_profile": profile,
        "late_day_near_miss_count": len(late_day_rows),
        "reduced_risk_sleeve_candidate_count": len(sleeve_candidates),
        "reduced_risk_sleeve_symbols": [row.get("symbol") for row in sleeve_candidates],
        "rows": late_day_rows[:lim],
        "recommended_action": recommended_action,
    }

def _p406_fast_current_candidate_payload(limit: int = 25) -> dict:
    lim = max(1, min(int(limit or 25), 100))
    latest_scan, summary = _p298_latest_scan_summary_light()

    summary_full_rows = [
        dict(row or {})
        for row in list(
            summary.get("candidate_rows_for_truth")
            or summary.get("candidates")
            or summary.get("results")
            or summary.get("items")
            or []
        )
        if isinstance(row, dict)
    ]
    rows_all = [
        dict(row or {})
        for row in list(LAST_SWING_CANDIDATES or [])
        if isinstance(row, dict)
    ]
    source = "last_swing_candidates_memory"

    if summary_full_rows and (not rows_all or len(summary_full_rows) >= len(rows_all)):
        rows_all = summary_full_rows
        source = "latest_scan_summary_candidate_rows_for_truth"

    if not rows_all and CANDIDATE_HISTORY:
        hist = dict((CANDIDATE_HISTORY or [])[-1] or {})
        rows_all = [
            dict(row or {})
            for row in list(hist.get("candidates") or hist.get("items") or [])
            if isinstance(row, dict)
        ]
        source = "candidate_history_latest"

    if not rows_all:
        rows_all = [
            dict(row or {})
            for row in list(summary.get("top_candidates") or summary.get("top_new_entry_candidates") or [])
            if isinstance(row, dict)
        ]
        if rows_all:
            source = "latest_scan_summary_display_rows"

    rows_all = _p412_rebuild_current_candidate_contract_rows(rows_all)
    open_symbols = set(_p404_active_position_symbols_light())
    fast_rows_all = [_p406_candidate_row_fast(row, open_symbols=open_symbols) for row in rows_all]
    fast_rows = fast_rows_all[:lim]

    new_entry_rows_all = [row for row in fast_rows_all if not bool(row.get("open_position"))]
    open_position_rows_all = [row for row in fast_rows_all if bool(row.get("open_position"))]
    new_entry_rows = new_entry_rows_all[:lim]
    open_position_rows = open_position_rows_all[:lim]
    eligible_rows_all = [row for row in new_entry_rows_all if bool(row.get("eligible"))]
    eligible_rows = eligible_rows_all[:lim]
    selected_context = _p405_selected_symbol_context(summary.get("selected_symbols") or [])

    reason_summary = _p277h_candidate_reason_counts(new_entry_rows_all)
    protective_reasons = {
        reason: count
        for reason, count in dict(reason_summary.get("reason_counts") or {}).items()
        if _p277_reason_family(reason) == "protective"
    }

    coverage = _p404_runtime_universe_coverage(latest_scan=latest_scan, summary=summary)
    try:
        coverage_audit = _p407_candidate_coverage_opportunity_audit(limit=lim)
    except Exception as exc:
        coverage_audit = {
            "ok": False,
            "error": str(exc),
            "runtime_slim": {},
            "rotation_symbols": [],
            "excluded_symbols": list(coverage.get("excluded_by_runtime_slim_symbols") or coverage.get("missing_runtime_symbols") or [])[:lim],
            "symbols_due_next_rotation": [],
            "recommended_action": "coverage_audit_unavailable_use_runtime_universe_coverage",
        }

    latest_reason = str(latest_scan.get("reason") or "").strip().lower()
    using_preserved_market_scan = str(latest_scan.get("_scan_source") or "").strip() == "last_actionable_market_scan"
    p526_completed_scan_failure_tombstone = bool(
        latest_reason == "scan_completed"
        and int(_safe_float(latest_scan.get("scanned"), 0.0)) > 0
        and bool((summary.get("scanner_failure_root_cause") or {}).get("historical_failure_tombstoned"))
    )
    p526_selection_revalidation = _p524_revalidate_current_selected_symbols(
        list(selected_context.get("selected_symbols") or []),
        {"candidate_rows": fast_rows_all},
        preserve_symbols=[
            str(sym or "").strip().upper()
            for sym, plan in dict(TRADE_PLAN or {}).items()
            if str(sym or "").strip()
            and isinstance(plan, dict)
            and (bool(plan.get("active")) or _plan_is_pending_entry(plan))
        ],
    )
    p526_stale_selected_symbols = list(p526_selection_revalidation.get("stale_symbols") or [])
    if p526_stale_selected_symbols:
        active_selected_symbols = list(p526_selection_revalidation.get("active_symbols") or [])
        selected_context = dict(selected_context)
        selected_context["selected_symbols_before_p526_revalidation"] = list(selected_context.get("selected_symbols") or [])
        selected_context["selected_symbols"] = active_selected_symbols
        selected_context["selected_total"] = len(active_selected_symbols)
        selected_context["stale_revalidated_blocked_symbols"] = p526_stale_selected_symbols
        selected_context["selection_echo_removed"] = True

    stale_scan_blocks_action = bool(
        (
            summary.get("post_open_scan_missing")
            or latest_reason in {"outside_market_hours", "scan_exception"}
            or (
                bool((summary.get("scanner_failure_root_cause") or {}).get("active"))
                and not p526_completed_scan_failure_tombstone
            )
        )
        and not using_preserved_market_scan
    )

    if stale_scan_blocks_action:
        status = "stale_scan_not_actionable"
        recommended_action = "recover_fresh_scan_before_evaluating_candidates"
        eligible_rows = []
    elif selected_context.get("selected_symbols"):
        status = "selecting"
        recommended_action = "monitor_submissions"
    elif eligible_rows_all:
        status = "eligible_new_entry_not_selected"
        recommended_action = "sync_selected_symbols_from_current_eligible_contract_rows"
    elif selected_context.get("open_position_selected_symbols"):
        status = "open_position_selection_echo_removed"
        recommended_action = "ignore_open_position_echo_and_wait_for_new_entry_selection"
    elif protective_reasons:
        status = "suppressed_by_protection"
        recommended_action = "review_protective_reasons_before_relaxing"
    elif new_entry_rows_all:
        status = "no_current_eligible_candidates"
        recommended_action = "wait_for_better_setup_or_review_near_misses"
    else:
        status = "no_candidate_flow"
        recommended_action = "inspect_scanner_runtime"

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "fast_current_candidate_truth",
        "payload_mode": "compact",
        "source": source,
        "p519_full_candidate_cache_adopted": bool(fast_rows_all),
        "p519_full_candidate_cache_source": source,
        "p519_display_limit": lim,
        "contract_rebuild_applied": True,
        "contract_rebuild_source": "p412_current_scan_contract_rebuild",
        "heavy_available": True,
        "heavy_url_hint": "/diagnostics/candidates_full?heavy=true&limit=10",
        "status": status,
        "recommended_action": recommended_action,
        "latest_scan": {
            "ts_utc": latest_scan.get("ts_utc"),
            "reason": latest_scan.get("reason"),
            "scanned": latest_scan.get("scanned"),
            "signals": latest_scan.get("signals"),
            "would_trade": latest_scan.get("would_trade"),
            "blocked": latest_scan.get("blocked"),
            "duration_ms": latest_scan.get("duration_ms"),
            "scanner_failure_root_cause": summary.get("scanner_failure_root_cause"),
            "stale_scan_blocks_action": bool(stale_scan_blocks_action),
            "p526_completed_scan_failure_tombstone": bool(p526_completed_scan_failure_tombstone),
        },
        "runtime_universe_coverage": coverage,
        "candidate_coverage_opportunity_audit": {
            "runtime_slim": dict(coverage_audit.get("runtime_slim") or {}),
            "rotation_symbols": list(coverage_audit.get("rotation_symbols") or []),
            "excluded_symbols": list(coverage_audit.get("excluded_symbols") or [])[:lim],
            "symbols_due_next_rotation": list(coverage_audit.get("symbols_due_next_rotation") or [])[:lim],
            "recommended_action": coverage_audit.get("recommended_action"),
        },
        "candidate_count": len(fast_rows_all),
        "display_candidate_count": len(fast_rows),
        "new_entry_candidate_count": len(new_entry_rows_all),
        "open_position_candidate_count": len(open_position_rows_all),
        "open_position_candidate_symbols": [row.get("symbol") for row in open_position_rows],
        "eligible_count": len(eligible_rows_all),
        "eligible_symbols": [row.get("symbol") for row in eligible_rows_all],
        "eligible_not_selected_count": len(eligible_rows_all) if not selected_context.get("selected_symbols") else 0,
        "eligible_not_selected_symbols": (
            [row.get("symbol") for row in eligible_rows_all]
            if not selected_context.get("selected_symbols")
            else []
        ),
        "selected_total": int(selected_context.get("selected_total") or 0),
        "selected_symbols": list(selected_context.get("selected_symbols") or []),
        "selected_symbols_before_p526_revalidation": list(selected_context.get("selected_symbols_before_p526_revalidation") or []),
        "stale_revalidated_blocked_symbols": list(selected_context.get("stale_revalidated_blocked_symbols") or []),
        "p526_selection_revalidation": dict(p526_selection_revalidation),
        "raw_selected_total": int(selected_context.get("raw_selected_total") or 0),
        "raw_selected_symbols": list(selected_context.get("raw_selected_symbols") or []),
        "open_position_selected_total": int(selected_context.get("open_position_selected_total") or 0),
        "open_position_selected_symbols": list(selected_context.get("open_position_selected_symbols") or []),
        "selection_echo_removed": bool(selected_context.get("selection_echo_removed")),
        "reason_counts": reason_summary.get("reason_counts"),
        "reason_family_counts": reason_summary.get("reason_family_counts"),
        "protective_reason_counts": protective_reasons,
        "candidate_rows": fast_rows_all,
        "eligible_new_entry_rows_all": eligible_rows_all,
        "top_candidates": fast_rows[:15],
        "top_new_entry_candidates": new_entry_rows[:15],
    }

def _diagnostics_candidates_payload(limit: int = 25, full: bool = False) -> dict:
    _ensure_runtime_state_loaded()
    _refresh_regime_snapshot_if_needed()
    lim = max(1, min(int(limit or 25), 200))
    current_runtime = [str(s).strip().upper() for s in (universe_symbols() or []) if str(s).strip()]
    runtime_validation = _universe_validation_snapshot()
    preview = _current_runtime_preview_snapshot(limit=lim)
    active_scan = _p285_saved_truth_scan(limit=lim)
    active_summary = (active_scan.get('summary') if isinstance(active_scan, dict) else {}) or {}
    items = _p285_saved_candidate_rows(active_scan, limit=lim)
    source = active_scan.get('_scan_source') if isinstance(active_scan, dict) else None
    matching_history = _matching_candidate_history(current_runtime, limit=5)
    active_symbols = [str(s).strip().upper() for s in (active_summary.get('symbols') or active_scan.get('symbols') or []) if str(s).strip()]
    eligible_items = [dict(item) for item in items if bool((item or {}).get('eligible'))]
    target_path_pass_items = [
        dict(item) for item in items
        if bool(((item.get("target_path_profit") or {}).get("passed")))
    ]
    target_path_strong_items = [
        dict(item) for item in target_path_pass_items
        if _safe_float((item.get("target_path_profit") or {}).get("score"), 0.0) >= float(SWING_TARGET_PATH_STRONG_SCORE)
    ]
    target_path_recovery_items = [
        dict(item) for item in items
        if bool((item.get("target_path_recovery") or {}).get("applies"))
    ]
    selection_blocked_items = [
        {
            'symbol': str((item or {}).get('symbol') or '').upper(),
            'rank_score': item.get('rank_score'),
            'selection_blockers': list((item or {}).get('selection_blockers') or []),
        }
        for item in items
        if bool((item or {}).get('selection_blockers'))
    ]
    blockers = _diagnostics_swing_blockers()
    post_change_drawdown = dict(
        preview.get('post_change_drawdown_circuit')
        or blockers.get('post_change_drawdown_circuit')
        or {}
    )
    defensive_breakout_rollback = dict(
        blockers.get("defensive_daily_breakout_rollback") or {}
    )
    selected_context = _p405_selected_symbol_context(active_summary.get('selected_symbols') or [])
    payload = {
        'ok': True,
        'strategy_mode': STRATEGY_MODE,
        'strategy_name': SWING_STRATEGY_NAME,
        'payload_mode': 'full' if full else 'summary',
        'full_endpoint': '/diagnostics/candidates_full',
        'truth_source': source,
        'post_change_drawdown_circuit': post_change_drawdown,
        'blocked_by_post_change_drawdown': bool(
            post_change_drawdown.get('block_new_entries')
        ),
        'defensive_daily_breakout_rollback': defensive_breakout_rollback,
        'blocked_by_defensive_daily_breakout_rollback': bool(
            defensive_breakout_rollback.get("blocked")
        ),
        'regime': {
            'ts_utc': (preview.get('regime') or LAST_REGIME_SNAPSHOT or {}).get('ts_utc'),
            'favorable': (preview.get('regime') or LAST_REGIME_SNAPSHOT or {}).get('favorable'),
            'score': (preview.get('regime') or LAST_REGIME_SNAPSHOT or {}).get('score'),
            'reasons': list(((preview.get('regime') or LAST_REGIME_SNAPSHOT or {}).get('reasons') or [])),
            'data_complete': (preview.get('regime') or LAST_REGIME_SNAPSHOT or {}).get('data_complete'),
        },
        'blockers': {
            'market_open_now': bool((blockers or {}).get('market_open_now')),
            'blocked_by_market_hours': bool((blockers or {}).get('blocked_by_market_hours')),
            'blocked_by_weak_regime': bool((blockers or {}).get('blocked_by_weak_regime')),
            'blocked_by_defensive_daily_breakout_rollback': bool(
                (blockers or {}).get('blocked_by_defensive_daily_breakout_rollback')
            ),
            'blocked_by_post_change_drawdown': bool(
                (blockers or {}).get('blocked_by_post_change_drawdown')
            ),
            'blocked_by_entry_cap': bool((blockers or {}).get('blocked_by_entry_cap')),
            'blocked_by_portfolio_cap': bool((blockers or {}).get('blocked_by_portfolio_cap')),
            'remaining_new_entries_today': int((blockers or {}).get('remaining_new_entries_today') or 0),
            'portfolio_exposure': (blockers or {}).get('portfolio_exposure'),
            'portfolio_exposure_cap': (blockers or {}).get('portfolio_exposure_cap'),
            'strategy_symbols': list((blockers or {}).get('strategy_symbols') or []),
            'last_scan_ts': (blockers or {}).get('last_scan_ts'),
            'last_scan_reason': (blockers or {}).get('last_scan_reason'),
        },
        'count': len(items),
        'items': [_candidate_row_compact(item) for item in items],
        'source': source,
        'active_scan_ts_utc': active_scan.get('ts_utc') if isinstance(active_scan, dict) else None,
        'active_scan_symbols': active_symbols,
        'current_runtime_symbols': current_runtime,
        'active_scan_matches_current_runtime': bool(current_runtime and active_symbols == current_runtime),
        'runtime_universe_coverage': _p404_runtime_universe_coverage(
            latest_scan=active_scan if isinstance(active_scan, dict) else {},
            summary=active_summary,
        ),
        'eligible_count': len([
            item for item in eligible_items
            if str((item or {}).get('symbol') or '').strip().upper() not in set(_p404_active_position_symbols_light())
        ]),
        'eligible_symbols': [
            str((item or {}).get('symbol') or '').upper()
            for item in eligible_items
            if str((item or {}).get('symbol') or '').strip()
            and str((item or {}).get('symbol') or '').strip().upper() not in set(_p404_active_position_symbols_light())
        ],
        'raw_selected_total': int(selected_context.get('raw_selected_total') or 0),
        'raw_selected_symbols': list(selected_context.get('raw_selected_symbols') or []),
        'open_position_selected_total': int(selected_context.get('open_position_selected_total') or 0),
        'open_position_selected_symbols': list(selected_context.get('open_position_selected_symbols') or []),
        'selection_echo_removed': bool(selected_context.get('selection_echo_removed')),
        'selected_total': int(selected_context.get('selected_total') or 0),
        'selected_symbols': list(selected_context.get('selected_symbols') or []),
        'selection_blocked_items': selection_blocked_items[:lim],
        'invalid_runtime_symbols': list(runtime_validation.get('invalid_runtime_symbols') or []),
        'adaptive_capacity': dict((active_summary.get('adaptive_capacity') or {})),
        'target_path_profit_engine': dict((active_summary.get('target_path_profit_engine') or {})),
        'target_path_dynamic_entry_cap': dict((active_summary.get('target_path_dynamic_entry_cap') or {})),
        'strong_target_path_weak_tape_override': dict((active_summary.get('strong_target_path_weak_tape_override') or {})),
        'target_path_opportunity_expansion_lab': dict(
            active_summary.get('target_path_opportunity_expansion_lab')
            or _p285_target_path_opportunity_expansion_lab(
                items,
                summary=active_summary,
                limit=lim,
            )
        ),
        'thrive_capacity_truth': dict((active_summary.get('thrive_capacity_truth') or {})),
        'target_path_pass_count': len(target_path_pass_items),
        'target_path_strong_count': len(target_path_strong_items),
        'target_path_recovery_count': len(target_path_recovery_items),
        'target_path_recovery_symbols': sorted({
            str(item.get("symbol") or "").upper()
            for item in target_path_recovery_items
            if item.get("symbol")
        }),
    }
    if full:
        shadow_items = [dict(item) for item in items if bool((item or {}).get('shadow_regime_candidate'))]
        shadow_alignment_items = [dict(item) for item in items if bool((item or {}).get('shadow_alignment_only_candidate'))]
        payload.update({
            'regime': dict(preview.get('regime') or LAST_REGIME_SNAPSHOT or {}),
            'blockers': blockers,
            'items': items,
            'eligible_but_not_selected': [dict(r) for r in (active_summary.get('eligible_but_not_selected') or []) if isinstance(r, dict)],
            'shadow_count': len(shadow_items),
            'shadow_items': shadow_items[:SHADOW_REGIME_MAX_CANDIDATES],
            'shadow_selected_count': len((matching_history[-1].get('shadow_selected') if matching_history else []) or []),
            'shadow_selected': list((matching_history[-1].get('shadow_selected') if matching_history else []) or []),
            'shadow_alignment_count': len(shadow_alignment_items),
            'shadow_alignment_items': shadow_alignment_items[:SHADOW_REGIME_MAX_CANDIDATES],
            'shadow_alignment_selected_count': len((matching_history[-1].get('shadow_alignment_selected') if matching_history else []) or []),
            'shadow_alignment_selected': list((matching_history[-1].get('shadow_alignment_selected') if matching_history else []) or []),
            'history': matching_history,
            'history_matches_current_runtime': bool(matching_history),
        })
    return payload

