def _p337_record_limit_submit_evidence(
    *,
    symbol: str,
    side: str,
    signal: str,
    source: str,
    stage: str,
    order_type: str,
    qty: float | None = None,
    limit_price: float | None = None,
    order_id: str = "",
    client_order_id: str = "",
    limit_entry: dict | None = None,
    snapshot: dict | None = None,
    plan: dict | None = None,
    error: str = "",
) -> dict:
    evidence = {
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        "ts_ny": now_ny().isoformat(),
        "patch_version": PATCH_VERSION,
        "symbol": str(symbol or "").upper(),
        "side": str(side or "").lower(),
        "signal": str(signal or ""),
        "source": str(source or ""),
        "stage": str(stage or ""),
        "order_type": str(order_type or "").lower(),
        "qty": _safe_float(qty, 0.0),
        "limit_price": _safe_float(limit_price, 0.0) if limit_price is not None else None,
        "order_id": str(order_id or ""),
        "client_order_id": str(client_order_id or ""),
        "limit_entry": dict(limit_entry or {}),
        "limit_entry_reason": str((limit_entry or {}).get("reason") or ""),
        "marketable": bool((limit_entry or {}).get("marketable")),
        "limit_distance_to_ask_pct": (
            round(((_safe_float(limit_price, 0.0) - _safe_float((snapshot or {}).get("ask"), 0.0)) / _safe_float((snapshot or {}).get("ask"), 1.0)), 6)
            if limit_price is not None and _safe_float((snapshot or {}).get("ask"), 0.0) > 0
            else None
        ),
        "snapshot": {
            "price": (snapshot or {}).get("price"),
            "bid": (snapshot or {}).get("bid"),
            "ask": (snapshot or {}).get("ask"),
            "mid": (snapshot or {}).get("mid"),
            "spread_pct": (snapshot or {}).get("spread_pct"),
            "fresh": (snapshot or {}).get("fresh"),
            "quote_ok": (snapshot or {}).get("quote_ok"),
        },
        "error": str(error or ""),
    }

    try:
        P337_PROTECTIVE_LIMIT_SUBMIT_EVIDENCE.append(evidence)
        del P337_PROTECTIVE_LIMIT_SUBMIT_EVIDENCE[:-50]
    except Exception:
        pass

    if isinstance(plan, dict):
        history = list(plan.get("protective_limit_submit_evidence_history") or [])
        history.append(evidence)
        plan["protective_limit_submit_evidence_history"] = history[-10:]
        plan["protective_limit_submit_evidence"] = evidence
        plan["protective_limit_submit_evidence_patch"] = PATCH_VERSION
        if evidence.get("stage") == "submitted":
            plan["protective_limit_submit_live_proven"] = True

    return evidence

def _p359_limit_plan_live_proof(plan: dict | None) -> dict:
    p = dict(plan or {})
    limit_entry = p.get("limit_entry") if isinstance(p.get("limit_entry"), dict) else {}
    order_type = str(
        p.get("order_type")
        or p.get("entry_order_type")
        or p.get("plan_order_type")
        or ""
    ).strip().lower()
    limit_price = _safe_float(
        p.get("limit_price")
        or p.get("entry_limit_price")
        or limit_entry.get("limit_price"),
        0.0,
    )
    order_id = str(p.get("order_id") or p.get("entry_order_id") or "").strip()
    client_order_id = str(p.get("client_order_id") or p.get("entry_client_order_id") or "").strip()
    order_status = str(p.get("order_status") or p.get("execution_state") or p.get("lifecycle_state") or "").strip().lower()
    filled_qty = _safe_float(p.get("filled_qty") or p.get("entry_filled_qty") or 0.0, 0.0)
    submitted_qty = _safe_float(p.get("submitted_qty") or p.get("qty") or p.get("requested_qty") or 0.0, 0.0)

    limit_like = bool(order_type == "limit" or limit_price > 0 or limit_entry)
    broker_identified = bool(order_id or client_order_id)
    status_proven = order_status in {
        "submitted",
        "accepted",
        "new",
        "partially_filled",
        "filled",
        "open",
        "acknowledged",
    }
    fill_proven = bool(filled_qty > 0)

    live_proven = bool(limit_like and broker_identified and (status_proven or fill_proven))

    return {
        "live_proven": live_proven,
        "limit_like": limit_like,
        "broker_identified": broker_identified,
        "status_proven": status_proven,
        "fill_proven": fill_proven,
        "order_type": order_type,
        "limit_price": limit_price if limit_price > 0 else None,
        "order_id": order_id,
        "client_order_id": client_order_id,
        "order_status": order_status,
        "filled_qty": filled_qty,
        "submitted_qty": submitted_qty,
        "limit_entry_reason": limit_entry.get("reason"),
        "marketable": bool(limit_entry.get("marketable")),
    }

def _p336_recent_limit_entry_evidence(limit: int = 10) -> dict:
    latest_scan, summary = _p298_latest_scan_summary_light()
    rows = []

    for evidence in list(P337_PROTECTIVE_LIMIT_SUBMIT_EVIDENCE or []):
        if not isinstance(evidence, dict):
            continue
        stage = str(evidence.get("stage") or "").lower()
        err = str(evidence.get("error") or "")
        rows.append({
            "source": "p337_runtime_evidence",
            "symbol": str(evidence.get("symbol") or "").upper(),
            "order_type": str(evidence.get("order_type") or "").lower(),
            "limit_price": evidence.get("limit_price"),
            "stage": evidence.get("stage"),
            "order_id": evidence.get("order_id"),
            "client_order_id": evidence.get("client_order_id"),
            "ts_utc": evidence.get("ts_utc"),
            "error": err,
            "rate_limited": bool(stage == "rate_limited" or _p352_is_alpaca_rate_limit_error(err)),
            "retryable": bool(stage == "rate_limited" or _p352_is_alpaca_rate_limit_error(err)),
            "live_proven": stage == "submitted",
            "limit_entry_reason": evidence.get("limit_entry_reason") or dict(evidence.get("limit_entry") or {}).get("reason"),
            "marketable": bool(evidence.get("marketable") or dict(evidence.get("limit_entry") or {}).get("marketable")),
            "limit_distance_to_ask_pct": evidence.get("limit_distance_to_ask_pct"),
        })

    for sym, plan in sorted(dict(TRADE_PLAN or {}).items()):
        p = dict(plan or {})
        limit_entry = p.get("limit_entry") if isinstance(p.get("limit_entry"), dict) else {}
        order_type = str(
            p.get("order_type")
            or p.get("entry_order_type")
            or p.get("plan_order_type")
            or ""
        ).strip().lower()
        limit_price = _safe_float(
            p.get("limit_price")
            or p.get("entry_limit_price")
            or limit_entry.get("limit_price"),
            0.0,
        )
        if order_type == "limit" or limit_price > 0 or bool(limit_entry):
            live_proof = _p359_limit_plan_live_proof(p)
            if live_proof.get("live_proven") and isinstance(TRADE_PLAN.get(sym), dict):
                TRADE_PLAN[sym]["protective_limit_submit_live_proven"] = True
                TRADE_PLAN[sym]["protective_limit_submit_live_proven_source"] = "p359_filled_or_submitted_limit_plan_backfill"
            rows.append({
                "source": "trade_plan",
                "symbol": str(sym or "").upper(),
                "order_type": order_type or live_proof.get("order_type") or "unknown",
                "limit_price": limit_price if limit_price > 0 else live_proof.get("limit_price"),
                "active": bool(p.get("active")),
                "pending_entry": bool(_plan_is_pending_entry(p)),
                "submitted": bool(p.get("submitted") or p.get("entry_submitted") or live_proof.get("status_proven")),
                "filled": bool(p.get("filled") or p.get("entry_filled") or live_proof.get("fill_proven")),
                "order_id": p.get("order_id") or live_proof.get("order_id"),
                "order_status": p.get("order_status") or live_proof.get("order_status"),
                "submitted_at": p.get("submitted_at"),
                "client_order_id": p.get("client_order_id") or p.get("entry_client_order_id") or live_proof.get("client_order_id"),
                "filled_qty": live_proof.get("filled_qty"),
                "submitted_qty": live_proof.get("submitted_qty"),
                "limit_entry_reason": limit_entry.get("reason") or live_proof.get("limit_entry_reason"),
                "marketable": bool(limit_entry.get("marketable") or live_proof.get("marketable")),
                "protective_limit_submit_live_proven": bool(p.get("protective_limit_submit_live_proven") or live_proof.get("live_proven")),
                "protective_limit_submit_live_proven_source": (
                    p.get("protective_limit_submit_live_proven_source")
                    or ("p359_filled_or_submitted_limit_plan_backfill" if live_proof.get("live_proven") else "")
                ),
                "protective_limit_submit_evidence": dict(p.get("protective_limit_submit_evidence") or {}),
                "live_proof": live_proof,
            })

    for row in list(summary.get("selected_submission_rows") or summary.get("would_submit") or []):
        if not isinstance(row, dict):
            continue
        plan = row.get("plan") if isinstance(row.get("plan"), dict) else {}
        order_type = str(
            row.get("order_type")
            or row.get("plan_order_type")
            or plan.get("order_type")
            or ""
        ).strip().lower()
        limit_price = _safe_float(
            row.get("limit_price")
            or row.get("entry_limit_price")
            or plan.get("limit_price"),
            0.0,
        )
        if order_type == "limit" or limit_price > 0:
            rows.append({
                "source": "selected_submission_rows",
                "symbol": str(row.get("symbol") or plan.get("symbol") or "").upper(),
                "order_type": order_type or "unknown",
                "limit_price": limit_price if limit_price > 0 else None,
                "actual_submit_side_effect": bool(row.get("actual_submit_side_effect")),
                "side_effect_detected_light": bool(row.get("side_effect_detected_light")),
                "block_reason": row.get("block_reason") or row.get("reason"),
                "limit_entry_reason": row.get("limit_entry_reason") or plan.get("limit_entry_reason"),
                "marketable": bool(row.get("marketable") or plan.get("marketable")),
            })

    symbols = _dedupe_keep_order([
        str(row.get("symbol") or "").upper()
        for row in rows
        if str(row.get("symbol") or "").strip()
    ])

    return {
        "evidence_count": len(rows),
        "symbols": symbols,
        "rows": rows[: max(1, int(limit or 10))],
        "latest_scan": {
            "ts_utc": latest_scan.get("ts_utc"),
            "reason": latest_scan.get("reason"),
            "selected_total": int(summary.get("selected_total") or 0),
            "selected_symbols": list(summary.get("selected_symbols") or []),
        },
    }

