@app.get("/diagnostics/swing_cleanup_status")
def diagnostics_swing_cleanup_status():
    def _retired_path_row(enabled: bool, env: str, reason: str) -> dict:
        disabled = not bool(enabled)
        return {
            "disabled": disabled,
            "enabled": bool(enabled),
            "env": env,
            "status": "retired_disabled" if disabled else "retired_but_still_enabled",
            "reason": reason,
        }

    retired_paths = {
        "heavy_operator_bundle": _retired_path_row(
            HEAVY_DIAGNOSTICS_ENABLED,
            "HEAVY_DIAGNOSTICS_ENABLED",
            "heavy bundles caused latency and memory pressure; light diagnostics replaced operator flow",
        ),
        "selected_entry_intent_queue": {
            "disabled": True,
            "enabled": False,
            "env": "SELECTED_ENTRY_INTENT_QUEUE_ENABLED",
            "env_removed": True,
            "status": "retired_removed",
            "reason": "selected intent queue config and storage removed; direct submit path is authoritative",
        },
        "selected_entry_finalizer": {
            "disabled": True,
            "enabled": False,
            "env": "SELECTED_ENTRY_FINALIZER_ENABLED",
            "env_removed": True,
            "status": "retired_removed",
            "reason": "selected entry finalizer config and loop removed; direct submit path is authoritative",
        },
        "selected_submission_finalizer": {
            "disabled": True,
            "enabled": False,
            "env": "SWING_SELECTED_SUBMISSION_FINALIZER_ENABLED",
            "env_removed": True,
            "status": "retired_removed",
            "reason": "selected submission finalizer config and retry loop removed; direct submit path is authoritative",
        },
        "fast_swing_scan_trigger": _retired_path_row(
            SWING_FAST_SCAN_TRIGGER_ENABLED,
            "SWING_FAST_SCAN_TRIGGER_ENABLED",
            "main-web fast trigger is retired; scanner service owns scan cadence",
        ),
        "intraday_shadow_inside_swing_scan": _retired_path_row(
            SWING_SCAN_RUN_INTRADAY_SHADOW,
            "SWING_SCAN_RUN_INTRADAY_SHADOW",
            "intraday is paused and should not run inside swing scanner runtime",
        ),
        "intraday_live": _retired_path_row(
            INTRADAY_LIVE_ENABLED,
            "INTRADAY_LIVE_ENABLED",
            "intraday live trading remains paused until separated from swing runtime",
        ),
    }
    live_swing_runtime = bool(
        str(STRATEGY_MODE or "").strip().lower() == "swing"
        and LIVE_TRADING_ENABLED
        and SCANNER_ALLOW_LIVE
        and not DRY_RUN
        and not SCANNER_DRY_RUN
    )
    return swing_diag_cleanup_status_snapshot(
        patch_version=PATCH_VERSION,
        strategy_mode=STRATEGY_MODE,
        live_swing_runtime=live_swing_runtime,
        retired_paths=retired_paths,
    )

@app.get("/diagnostics/protective_limit_submit_evidence")
def diagnostics_protective_limit_submit_evidence(limit: int = 20):
    evidence = _p336_recent_limit_entry_evidence(limit=max(1, min(int(limit or 20), 50)))
    submitted_rows = [
        row for row in list(evidence.get("rows") or [])
        if str(row.get("stage") or "").lower() == "submitted"
        or bool(row.get("protective_limit_submit_live_proven"))
        or bool(row.get("live_proven"))
        or bool((row.get("live_proof") or {}).get("live_proven"))
    ]
    attempted_rows = [
        row for row in list(evidence.get("rows") or [])
        if str(row.get("stage") or "").lower() == "attempted"
    ]
    rejected_rows = [
        row for row in list(evidence.get("rows") or [])
        if str(row.get("stage") or "").lower() == "rejected"
    ]
    rate_limited_rows = [
        row for row in list(evidence.get("rows") or [])
        if str(row.get("stage") or "").lower() == "rate_limited"
        or bool(row.get("rate_limited"))
        or _p352_is_alpaca_rate_limit_error(row.get("error"))
        or _p352_is_alpaca_rate_limit_error(row.get("block_reason"))
    ]
    retryable_symbols = _dedupe_keep_order([
        str(row.get("symbol") or "").upper()
        for row in rate_limited_rows
        if str(row.get("symbol") or "").strip()
    ])

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "protective_limit_submit_evidence",
        "broker_free": True,
        "evidence_count": int(evidence.get("evidence_count") or 0),
        "submitted_count": len(submitted_rows),
        "attempted_count": len(attempted_rows),
        "rejected_count": len(rejected_rows),
        "rate_limited_count": len(rate_limited_rows),
        "retryable_symbols": retryable_symbols,
        "limit_path_live_proven": bool(submitted_rows),
        "symbols": list(evidence.get("symbols") or []),
        "rows": list(evidence.get("rows") or []),
        "latest_scan": dict(evidence.get("latest_scan") or {}),
        "recommended_action": (
            "rate_limited_submit_retry_needed"
            if rate_limited_rows and not submitted_rows
            else "submit_split_greenlight_available"
            if submitted_rows
            else "wait_for_next_protective_limit_submit"
        ),
    }

@app.get("/diagnostics/swing_submit_split_readiness")
def diagnostics_swing_submit_split_readiness():
    execution_status = diagnostics_swing_execution_module_status()
    limit_evidence = _p336_recent_limit_entry_evidence(limit=10)

    helper_mismatch_count = int(execution_status.get("mismatch_count") or 0)
    execution_checks = dict(execution_status.get("checks") or {})
    submit_decision_helper_ready = bool(
        execution_checks.get("submit_decision_broker_free")
        and execution_checks.get("submit_decision_limit")
        and execution_checks.get("submit_decision_marketable")
    )
    limit_path_proven = any(
        str(row.get("stage") or "").lower() == "submitted"
        or bool(row.get("protective_limit_submit_live_proven"))
        or bool(row.get("live_proven"))
        or bool((row.get("live_proof") or {}).get("live_proven"))
        for row in list(limit_evidence.get("rows") or [])
        if isinstance(row, dict)
    )

    blockers = []
    if helper_mismatch_count:
        blockers.append("execution_helper_module_parity_not_clean")
    if not submit_decision_helper_ready:
        blockers.append("submit_decision_helper_not_ready")
    if not limit_path_proven:
        blockers.append("protective_limit_live_path_not_proven")

    submit_split_ready = not blockers
    limit_path_proof_symbols = _dedupe_keep_order([
        str(row.get("symbol") or "").upper()
        for row in list(limit_evidence.get("rows") or [])
        if isinstance(row, dict)
        and (
            str(row.get("stage") or "").lower() == "submitted"
            or bool(row.get("protective_limit_submit_live_proven"))
            or bool(row.get("live_proven"))
            or bool((row.get("live_proof") or {}).get("live_proven"))
        )
        and str(row.get("symbol") or "").strip()
    ])

    return {
        "ok": True,
        "patch_version": PATCH_VERSION,
        "mode": "swing_submit_split_readiness",
        "broker_free": True,
        "submit_split_ready": submit_split_ready,
        "execution_submit_moved": False,
        "broker_submit_still_in_app_py": True,
        "pure_helpers_moved": True,
        "helper_mismatch_count": helper_mismatch_count,
        "submit_decision_helper_ready": submit_decision_helper_ready,
        "limit_path_proven": limit_path_proven,
        "limit_path_proof_symbols": limit_path_proof_symbols,
        "limit_entry_evidence": limit_evidence,
        "blockers": blockers,
        "recommended_action": (
            "ready_to_split_submit_functions_next"
            if submit_split_ready
            else "wait_for_limit_path_live_proof_before_submit_split"
        ),
    }

